def mask_secret(value: str, keep: int = 4) -> str:
    value = str(value or "")
    if not value:
        return "missing"
    if len(value) <= keep * 2:
        return "***"
    return value[:keep] + "***" + value[-keep:]

def _log_secret_values() -> list[str]:
    keys = [
        "TELEGRAM_TOKEN",
        "BOT_TOKEN",
        "PAYOS_API_KEY",
        "PAYOS_CHECKSUM_KEY",
        "OPENAI_API_KEY",
        "OPENROUTER_API_KEY",
        "SHOPAIKEY_API_KEY",
        "GEMINI_API_KEY",
        "DEEPGRAM_API_KEY",
        "DEEPL_API_KEY",
        "FISH_AUDIO_KEY",
        "ELEVENLABS_API_KEY",
        "AUPHONIC_API_KEY",
        "JAMENDO_CLIENT_ID",
        "JAMENDO_CLIENT_SECRET",
        "FREESOUND_API_KEY",
        "FREESOUND_CLIENT_ID",
        "FREESOUND_CLIENT_SECRET",
        "PIXABAY_API_KEY",
        "MUSICFUL_API_KEY",
        "MINIMAX_API_KEY",
        "MINIMAX_GROUP_ID",
        "REPLICATE_API_TOKEN",
        "CLIPDROP_API_KEY",
        "MUBERT_API_KEY",
        "BEATOVEN_API_KEY",
        "SOUNDRAW_API_KEY",
        "SERPAPI_API_KEY",
        "STABILITY_API_KEY",
        "KLING_ACCESS_KEY",
        "KLING_SECRET_KEY",
        "KLING_API_KEY",
        "RUNWAY_API_KEY",
        "HEYGEN_API_KEY",
        "REMOVEBG_API_KEY",
        "CUTOUT_API_KEY",
        "RAPIDAPI_KEY",
        "COBALT_API_KEY",
        "TELEGRAM_WEBHOOK_SECRET",
        "LEAD_WEBHOOK_SECRET",
        "OPERATOR_API_TOKEN",
        "LOCAL_WORKER_TOKEN",
        "AFFILIATE_POSTBACK_TOKEN",
    ]
    values = []
    for key in keys:
        value = globals().get(key) or os.environ.get(key, "")
        if value and len(str(value)) >= 8:
            values.append(str(value))
    return values

def sanitize_log_text(text: str) -> str:
    safe = str(text or "")
    for value in _log_secret_values():
        safe = safe.replace(value, mask_secret(value))
    return safe

def safe_html(text: object) -> str:
    return html.escape("" if text is None else str(text), quote=True)

class SecretMaskingFilter(logging.Filter):
    def filter(self, record):
        try:
            record.msg = sanitize_log_text(record.getMessage())
            record.args = ()
        except Exception:
            pass
        return True

class SecretMaskingFormatter(logging.Formatter):
    def format(self, record):
        return sanitize_log_text(super().format(record))

_secret_masking_filter = SecretMaskingFilter()
for _handler in logging.getLogger().handlers:
    _handler.addFilter(_secret_masking_filter)
    _handler.setFormatter(SecretMaskingFormatter("%(asctime)s | %(levelname)s | %(message)s"))
for _log_name in ("TOAN_AAS", "httpx", "telegram", "telegram.ext"):
    logging.getLogger(_log_name).addFilter(_secret_masking_filter)

# ─── BIẾN MÔI TRƯỜNG ─────────────────────────────────────────────────────────
def _env(key: str, default: str = "") -> str:
    return os.environ.get(key, default).strip()

def _first_env_line(value: str) -> str:
    return str(value or "").strip().splitlines()[0].strip() if str(value or "").strip() else ""

def env_any(*names: str, default: str = "") -> str:
    for name in names:
        value = os.environ.get(str(name or ""), "")
        if value and str(value).strip():
            return str(value).strip()
    return default

def env_flag(name: str, default: str = "0") -> bool:
    return str(os.environ.get(name, default) or default).strip().lower() in {"1", "true", "yes", "on"}

def env_int(name: str, default: int = 0) -> int:
    try:
        return int(str(os.environ.get(name, str(default)) or str(default)).strip())
    except Exception:
        return int(default)

def env_float(name: str, default: float = 0.0) -> float:
    try:
        return float(str(os.environ.get(name, str(default)) or str(default)).strip())
    except Exception:
        return float(default)

