def normalize_public_base_url(value: str = "") -> str:
    value = (value or "").strip().rstrip("/")
    if not value:
        return ""
    if value.startswith("http://") or value.startswith("https://"):
        return value
    return "https://" + value

def detect_public_base_url() -> tuple[str, str]:
    candidates = [
        "PUBLIC_BASE_URL",
        "WEBHOOK_BASE_URL",
        "BOT_PUBLIC_URL",
        "RAILWAY_PUBLIC_DOMAIN",
        "RAILWAY_STATIC_URL",
        "RAILWAY_PUBLIC_URL",
        "RAILWAY_SERVICE_DOMAIN",
        "RAILWAY_PROJECT_DOMAIN",
        "RENDER_EXTERNAL_URL",
    ]
    for key in candidates:
        value = normalize_public_base_url(_env(key))
        if value:
            return value, key
    railway_markers = [
        "RAILWAY_ENVIRONMENT",
        "RAILWAY_ENVIRONMENT_ID",
        "RAILWAY_PROJECT_ID",
        "RAILWAY_SERVICE_ID",
        "RAILWAY_DEPLOYMENT_ID",
    ]
    if any(_env(key) for key in railway_markers):
        fallback = normalize_public_base_url(
            _env("TOAN_AAS_FALLBACK_PUBLIC_URL", "https://bot-production-2dd7.up.railway.app")
        )
        if fallback:
            return fallback, "TOAN_AAS_FALLBACK_PUBLIC_URL"
    return "", ""

def parse_id_set(raw: str) -> set[str]:
    return {x.strip() for x in str(raw or "").replace(";", ",").split(",") if x.strip()}

