def add_data_persistence_warning(code: str, message: str):
    code_clean = str(code or "DATA_PERSISTENCE_WARNING").strip()[:80]
    message_clean = str(message or "").strip()[:500]
    if not code_clean:
        code_clean = "DATA_PERSISTENCE_WARNING"
    if any(item.get("code") == code_clean for item in DATA_PERSISTENCE_WARNINGS):
        return
    DATA_PERSISTENCE_WARNINGS.append({
        "code": code_clean,
        "message": message_clean,
        "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
    })

def now_text_safe() -> str:
    return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

def masked_db_path(path: str = "") -> str:
    value = str(path or DB_FILE or "").strip()
    if not value:
        return "missing"
    base = os.path.basename(value) or value
    if value == base:
        return base
    drive, _tail = os.path.splitdrive(value)
    prefix = drive or ("/" if value.startswith("/") else "")
    return f"{prefix}...{os.sep}{base}" if prefix else f"...{os.sep}{base}"

def display_db_path(path: str = "") -> str:
    value = str(path or DB_FILE or "").strip()
    return value or "missing"

def masked_database_url(url: str = "") -> str:
    value = str(url or DATABASE_URL or "").strip()
    if not value:
        return "missing"
    try:
        parsed = urlparse(value)
        if not parsed.scheme:
            return "configured"
        host = parsed.hostname or "host"
        port = f":{parsed.port}" if parsed.port else ""
        return f"{parsed.scheme}://***@{host}{port}{parsed.path or ''}"
    except Exception:
        return "configured"

def sqlite_db_abs_path() -> str:
    db_path = str(DB_FILE or "").strip()
    return os.path.abspath(db_path) if db_path else ""

def sqlite_local_fallback_path() -> str:
    return os.path.abspath("toandaas_system.db")

def sqlite_candidate_mounts() -> list[str]:
    mounts: list[str] = []
    for candidate in (_env("RAILWAY_VOLUME_MOUNT_PATH", ""), "/data", "/mnt/data", "/app/data"):
        candidate_clean = str(candidate or "").strip()
        if candidate_clean and candidate_clean not in mounts:
            mounts.append(candidate_clean)
    return mounts

def path_under_dir(path: str, directory: str) -> bool:
    path_clean = str(path or "").strip()
    dir_clean = str(directory or "").strip()
    if not path_clean or not dir_clean:
        return False
    normalized_path = os.path.abspath(path_clean).replace("\\", "/").rstrip("/")
    normalized_dir = os.path.abspath(dir_clean).replace("\\", "/").rstrip("/")
    return normalized_path == normalized_dir or normalized_path.startswith(normalized_dir + "/")

def is_persistent_sqlite_path(path: str = "") -> bool:
    db_path = str(path or DB_FILE or "").strip()
    if not db_path:
        return False
    return any(path_under_dir(db_path, mount) for mount in sqlite_candidate_mounts())

def is_relative_sqlite_path(path: str = "") -> bool:
    db_path = str(path or DB_FILE or "").strip()
    return bool(db_path and not os.path.isabs(db_path))

def sqlite_parent_dir(path: str = "") -> str:
    db_path = str(path or DB_FILE or "").strip()
    if not db_path:
        return ""
    parent = os.path.dirname(os.path.abspath(db_path))
    return parent or os.getcwd()

def directory_writable(path: str) -> bool:
    directory = str(path or "").strip()
    if not directory:
        return False
    try:
        os.makedirs(directory, exist_ok=True)
        probe = os.path.join(directory, f".toanaas_write_test_{os.getpid()}_{int(time.time() * 1000)}")
        with open(probe, "w", encoding="utf-8") as f:
            f.write("ok")
        os.remove(probe)
        return True
    except Exception:
        try:
            if "probe" in locals() and os.path.exists(probe):
                os.remove(probe)
        except Exception:
            pass
        return False

def sqlite_db_writable() -> bool:
    db_path = str(DB_FILE or "").strip()
    if not db_path:
        return False
    if os.path.exists(db_path):
        return os.access(db_path, os.W_OK)
    return directory_writable(sqlite_parent_dir(db_path))

def sqlite_backup_dir_writable() -> bool:
    return directory_writable(str(DB_BACKUP_DIR or "backups"))

def sqlite_db_exists() -> bool:
    db_path = str(DB_FILE or "").strip()
    return bool(db_path and os.path.exists(db_path))

def sqlite_db_size_bytes() -> int:
    try:
        return os.path.getsize(str(DB_FILE)) if sqlite_db_exists() else 0
    except Exception:
        return 0

def prepare_sqlite_persistent_path_once() -> dict:
    global DB_STARTUP_PREP_RESULT
    if DATA_PERSISTENCE_MODE != "sqlite":
        DB_STARTUP_PREP_RESULT = {"status": "skipped", "path": "", "created_at": "", "reason": "non_sqlite_mode"}
        return DB_STARTUP_PREP_RESULT
    current_abs = sqlite_db_abs_path()
    previous_abs = os.path.abspath(str(DB_STARTUP_PREP_RESULT.get("path") or "")) if DB_STARTUP_PREP_RESULT.get("path") else ""
    if DB_STARTUP_PREP_RESULT.get("status") not in {"not_run", ""} and previous_abs == current_abs:
        return DB_STARTUP_PREP_RESULT
    db_path = str(DB_FILE or "").strip()
    if not db_path:
        DB_STARTUP_PREP_RESULT = {"status": "error", "path": "", "created_at": now_text_safe(), "reason": "db_path_missing"}
        add_data_persistence_warning("DB_PATH_MISSING", "SQLite DB path is missing.")
        return DB_STARTUP_PREP_RESULT
    persistent_candidate = is_persistent_sqlite_path(db_path)
    if not persistent_candidate:
        if is_relative_sqlite_path(db_path):
            add_data_persistence_warning("DATA_LOSS_RISK_DETECTED", "SQLite DB path is relative/local; configure DB_PATH=/data/toandaas_system.db for Railway production.")
        DB_STARTUP_PREP_RESULT = {"status": "local_dev_path", "path": db_path, "created_at": now_text_safe(), "reason": "not_persistent_candidate"}
        return DB_STARTUP_PREP_RESULT

    target_abs = os.path.abspath(db_path)
    parent = os.path.dirname(target_abs) or os.getcwd()
    if os.path.exists(target_abs):
        DB_STARTUP_PREP_RESULT = {"status": "persistent_db_exists", "path": target_abs, "created_at": now_text_safe(), "reason": "use_existing_persistent_db"}
        return DB_STARTUP_PREP_RESULT

    if not directory_writable(parent):
        add_data_persistence_warning("PERSISTENT_DB_NOT_WRITABLE", f"Persistent SQLite directory is not writable: {display_db_path(parent)}")
        DB_STARTUP_PREP_RESULT = {"status": "error", "path": target_abs, "created_at": now_text_safe(), "reason": "persistent_dir_not_writable"}
        return DB_STARTUP_PREP_RESULT

    legacy_abs = sqlite_local_fallback_path()
    if os.path.exists(legacy_abs) and os.path.getsize(legacy_abs) > 0 and os.path.abspath(legacy_abs) != target_abs:
        try:
            shutil.copy2(legacy_abs, target_abs)
            logger.info("migrated local sqlite db to persistent path")
            DB_STARTUP_PREP_RESULT = {"status": "copied_local_to_persistent", "path": target_abs, "created_at": now_text_safe(), "reason": "migrated local sqlite db to persistent path"}
            return DB_STARTUP_PREP_RESULT
        except Exception as e:
            add_data_persistence_warning("PERSISTENT_DB_COPY_FAILED", f"Could not copy local SQLite DB to persistent path: {type(e).__name__}")
            DB_STARTUP_PREP_RESULT = {"status": "error", "path": target_abs, "created_at": now_text_safe(), "reason": str(e)[:160]}
            return DB_STARTUP_PREP_RESULT

    add_data_persistence_warning("SQLITE_NEW_EMPTY_DB_PENDING", "Persistent SQLite DB does not exist and no local fallback DB was found; a new empty DB will be created.")
    DB_STARTUP_PREP_RESULT = {"status": "new_empty_db_pending", "path": target_abs, "created_at": now_text_safe(), "reason": "no_existing_db_found"}
    return DB_STARTUP_PREP_RESULT

def sqlite_volume_status() -> dict:
    db_path = sqlite_db_abs_path()
    detected = False
    matched = ""
    for candidate_clean in sqlite_candidate_mounts():
        if path_under_dir(db_path, candidate_clean):
            detected = True
            matched = candidate_clean
            break
    parent = sqlite_parent_dir(db_path)
    parent_writable = directory_writable(parent) if detected else False
    return {
        "detected": detected,
        "mount": display_db_path(matched) if matched else "unknown",
        "db_under_volume": detected,
        "persistent_path_candidate": detected,
        "parent_dir": display_db_path(parent),
        "parent_writable": parent_writable,
    }

def data_persistence_risk_level() -> str:
    if DATA_PERSISTENCE_MODE != "sqlite":
        return "YES" if not bool(DATABASE_URL) else "NO"
    volume = sqlite_volume_status()
    persistent_candidate = bool(volume.get("persistent_path_candidate"))
    db_writable = sqlite_db_writable()
    if REQUIRE_PERSISTENT_DB and (not persistent_candidate or not db_writable):
        return "ERROR"
    if is_relative_sqlite_path():
        return "YES"
    if is_railway_runtime() and not persistent_candidate:
        return "YES"
    if is_railway_runtime() and (not sqlite_db_exists() or sqlite_db_size_bytes() <= 0):
        return "YES"
    if persistent_candidate and db_writable:
        return "NO"
    if persistent_candidate:
        return "LOW"
    return "YES" if any(item.get("code") == "DATA_LOSS_RISK_DETECTED" for item in DATA_PERSISTENCE_WARNINGS) else "NO"

def data_persistence_runtime_is_risky() -> bool:
    return data_persistence_risk_level() in {"YES", "ERROR"}

def assert_safe_migration_sql(sql: str):
    sql_upper = re.sub(r"\s+", " ", str(sql or "")).upper().strip()
    if DB_ALLOW_DESTRUCTIVE_MIGRATION:
        return True
    for marker in DESTRUCTIVE_SQL_MARKERS:
        if marker in sql_upper:
            raise RuntimeError(f"Blocked destructive migration while DB_ALLOW_DESTRUCTIVE_MIGRATION=false: {marker}")
    return True

def evaluate_data_persistence_startup_state():
    prepare_sqlite_persistent_path_once()
    db_exists = sqlite_db_exists()
    db_size = sqlite_db_size_bytes()
    volume = sqlite_volume_status()
    db_writable = sqlite_db_writable()
    backup_writable = sqlite_backup_dir_writable()
    if DATA_PERSISTENCE_MODE != "sqlite" and not DATABASE_URL:
        add_data_persistence_warning(
            "DATA_LOSS_RISK_DETECTED",
            "DATA_PERSISTENCE_MODE is not sqlite but DATABASE_URL is missing.",
        )
    if DATA_PERSISTENCE_MODE == "sqlite" and is_relative_sqlite_path():
        add_data_persistence_warning(
            "DATA_LOSS_RISK_DETECTED",
            "SQLite DB path is relative/local. Use DB_PATH=/data/toandaas_system.db with a Railway Volume for production.",
        )
    if is_railway_runtime() and DATA_PERSISTENCE_MODE == "sqlite":
        if not volume.get("detected"):
            add_data_persistence_warning(
                "DATA_LOSS_RISK_DETECTED",
                "Railway runtime is using SQLite without a detected persistent volume path.",
            )
        if not db_exists or db_size <= 0:
            add_data_persistence_warning(
                "DATA_LOSS_RISK_DETECTED",
                "Railway SQLite DB is missing or empty before init_db; old data may have disappeared.",
            )
    if REQUIRE_PERSISTENT_DB:
        if DATA_PERSISTENCE_MODE == "sqlite" and not volume.get("detected"):
            add_data_persistence_warning(
                "PERSISTENT_DB_REQUIRED",
                "REQUIRE_PERSISTENT_DB=true but DB_PATH is not under a detected persistent volume.",
            )
            raise RuntimeError("Persistent DB required but SQLite DB path is not under a detected persistent volume.")
        if DATA_PERSISTENCE_MODE == "sqlite" and not db_writable:
            add_data_persistence_warning(
                "PERSISTENT_DB_NOT_WRITABLE",
                "REQUIRE_PERSISTENT_DB=true but SQLite DB path or parent directory is not writable.",
            )
            raise RuntimeError("Persistent DB required but SQLite DB path is not writable.")
        if DATA_PERSISTENCE_MODE == "sqlite" and DB_STARTUP_BACKUP_ENABLED and not backup_writable:
            add_data_persistence_warning(
                "DB_BACKUP_DIR_NOT_WRITABLE",
                "DB_STARTUP_BACKUP_ENABLED=true but DB_BACKUP_DIR is not writable.",
            )
        if DATA_PERSISTENCE_MODE != "sqlite" and not DATABASE_URL:
            add_data_persistence_warning(
                "PERSISTENT_DB_REQUIRED",
                "REQUIRE_PERSISTENT_DB=true but DATABASE_URL is missing.",
            )
            raise RuntimeError("Persistent DB required but DATABASE_URL is missing.")

def latest_startup_backup_info() -> dict:
    result = dict(DB_STARTUP_BACKUP_RESULT or {})
    if result.get("path"):
        return result
    backup_dir = str(DB_BACKUP_DIR or "backups")
    try:
        if not os.path.isdir(backup_dir):
            return {"status": result.get("status") or "not_found", "path": "", "created_at": "", "reason": result.get("reason") or ""}
        files = []
        for name in os.listdir(backup_dir):
            if name.startswith("toandaas_system_") and name.endswith("_startup.db"):
                path = os.path.join(backup_dir, name)
                files.append((os.path.getmtime(path), path))
        if not files:
            return {"status": result.get("status") or "not_found", "path": "", "created_at": "", "reason": result.get("reason") or ""}
        _mtime, path = sorted(files, reverse=True)[0]
        return {
            "status": "found",
            "path": path,
            "created_at": datetime.fromtimestamp(os.path.getmtime(path)).strftime("%Y-%m-%d %H:%M:%S"),
            "reason": "latest_file",
        }
    except Exception as e:
        return {"status": "error", "path": "", "created_at": "", "reason": str(e)[:160]}

def cleanup_old_startup_backups():
    backup_dir = str(DB_BACKUP_DIR or "backups")
    try:
        if not os.path.isdir(backup_dir):
            return
        files = []
        for name in os.listdir(backup_dir):
            if name.startswith("toandaas_system_") and name.endswith("_startup.db"):
                path = os.path.join(backup_dir, name)
                files.append((os.path.getmtime(path), path))
        files = sorted(files, reverse=True)
        for _mtime, path in files[DB_STARTUP_BACKUP_RETENTION:]:
            try:
                os.remove(path)
            except Exception as e:
                logger.warning(f"Startup DB backup cleanup skipped {masked_db_path(path)}: {type(e).__name__}")
    except Exception as e:
        logger.warning(f"Startup DB backup cleanup failed: {type(e).__name__}")

def db_backup_dir_is_public(path: str = "") -> bool:
    value = str(path or DB_BACKUP_DIR or "").strip()
    if not value:
        return False
    parts = [part.lower() for part in Path(os.path.abspath(value)).parts]
    public_markers = {"public", "static", "assets", "www", "wwwroot", "htdocs"}
    return any(part in public_markers for part in parts)

def db_backup_filename(now_dt: datetime | None = None) -> str:
    stamp = (now_dt or datetime.now()).strftime("%Y%m%d_%H%M%S")
    return f"toanaas_system_{stamp}.sqlite3"

def db_backup_file_candidates() -> list[tuple[float, str]]:
    backup_dir = str(DB_BACKUP_DIR or "backups")
    files: list[tuple[float, str]] = []
    try:
        if not os.path.isdir(backup_dir):
            return []
        for name in os.listdir(backup_dir):
            if name.startswith("toanaas_system_") and name.endswith(".sqlite3"):
                path = os.path.join(backup_dir, name)
                if os.path.isfile(path):
                    files.append((os.path.getmtime(path), path))
    except Exception:
        return []
    return sorted(files, reverse=True)

def latest_db_backup_info() -> dict:
    files = db_backup_file_candidates()
    if files:
        mtime, path = files[0]
        return {
            "status": "found",
            "path": path,
            "filename": os.path.basename(path),
            "created_at": datetime.fromtimestamp(mtime).strftime("%Y-%m-%d %H:%M:%S"),
            "size_bytes": os.path.getsize(path) if os.path.exists(path) else 0,
        }
    startup = latest_startup_backup_info()
    if startup.get("path"):
        return {
            "status": startup.get("status") or "startup",
            "path": startup.get("path") or "",
            "filename": os.path.basename(startup.get("path") or ""),
            "created_at": startup.get("created_at") or "",
            "size_bytes": startup.get("size_bytes") or 0,
        }
    return {"status": "not_found", "path": "", "filename": "", "created_at": "", "size_bytes": 0}

def cleanup_old_db_backups(keep_last: int | None = None) -> list[str]:
    keep = max(1, int(keep_last or DB_BACKUP_KEEP_LAST or 10))
    removed: list[str] = []
    for _mtime, path in db_backup_file_candidates()[keep:]:
        try:
            os.remove(path)
            removed.append(os.path.basename(path))
        except Exception as e:
            logger.warning("DB backup retention skipped %s: %s", masked_db_path(path), type(e).__name__)
    return removed

def create_db_backup_now(actor_id="", note: str = "") -> dict:
    db_path = str(DB_FILE or "").strip()
    backup_dir = str(DB_BACKUP_DIR or "backups").strip()
    if DATA_PERSISTENCE_MODE != "sqlite":
        return {"ok": False, "reason": "non_sqlite_mode", "backup_dir": display_db_path(backup_dir)}
    if not db_path or not os.path.exists(db_path):
        return {"ok": False, "reason": "db_file_not_found", "db_file": db_file_health_label(), "backup_dir": display_db_path(backup_dir)}
    if db_backup_dir_is_public(backup_dir):
        return {"ok": False, "reason": "backup_dir_public", "backup_dir": display_db_path(backup_dir)}
    os.makedirs(backup_dir, exist_ok=True)
    filename = db_backup_filename()
    backup_path = os.path.join(backup_dir, filename)
    if os.path.exists(backup_path):
        filename = f"toanaas_system_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{os.getpid()}.sqlite3"
        backup_path = os.path.join(backup_dir, filename)
    try:
        source = sqlite3.connect(db_path, timeout=30)
        dest = sqlite3.connect(backup_path, timeout=30)
        try:
            source.execute("PRAGMA wal_checkpoint(FULL)")
            source.backup(dest)
            dest.commit()
        finally:
            dest.close()
            source.close()
        size = os.path.getsize(backup_path)
        removed = cleanup_old_db_backups(DB_BACKUP_KEEP_LAST)
        created_at = now_text_safe()
        try:
            if callable(globals().get("set_system_setting")):
                set_system_setting("db_backup_last_path", backup_path, "last manual DB backup path", actor_id or "system")
                set_system_setting("db_backup_last_at", created_at, "last manual DB backup timestamp", actor_id or "system")
        except Exception:
            pass
        return {
            "ok": True,
            "path": backup_path,
            "filename": filename,
            "size_bytes": size,
            "created_at": created_at,
            "removed": removed,
            "backup_dir": display_db_path(backup_dir),
            "retention_keep_last": int(DB_BACKUP_KEEP_LAST),
        }
    except Exception as e:
        try:
            if backup_path and os.path.exists(backup_path):
                os.remove(backup_path)
        except Exception:
            pass
        return {"ok": False, "reason": type(e).__name__, "error": sanitize_log_text(str(e))[:200], "backup_dir": display_db_path(backup_dir)}

def mask_risk_filename(name: str) -> str:
    base = os.path.basename(str(name or ""))
    if len(base) <= 8:
        return "***"
    stem, ext = os.path.splitext(base)
    return f"{stem[:2]}***{stem[-2:]}{ext}" if stem else f"***{ext}"

def secret_file_risk_check(root_dir: str | None = None) -> dict:
    base_dir = os.path.abspath(root_dir or os.path.dirname(__file__))
    scan_dirs = [base_dir]
    for child in ("public", "static", "assets", "www", "wwwroot"):
        candidate = os.path.join(base_dir, child)
        if os.path.isdir(candidate):
            scan_dirs.append(candidate)
    risks: list[dict] = []
    for directory in scan_dirs:
        try:
            names = os.listdir(directory)
        except Exception:
            continue
        public_dir = db_backup_dir_is_public(directory)
        for name in names:
            path = os.path.join(directory, name)
            if os.path.isdir(path):
                continue
            lower = name.lower()
            ext = os.path.splitext(lower)[1]
            reason = ""
            if lower == ".env" or lower.endswith(".env"):
                reason = "env_file"
            elif any(marker in lower for marker in ("secret", "token", "api_key", "apikey", "checksum", "private_key")):
                reason = "secret_like_filename"
            elif public_dir and ext in {".sqlite", ".sqlite3", ".db"}:
                reason = "public_db_backup"
            elif ext in {".sqlite", ".sqlite3", ".db"} and ("backup" in lower or lower.startswith("toanaas_system_")):
                reason = "db_backup_in_repo"
            if reason:
                risks.append({
                    "masked_name": mask_risk_filename(name),
                    "reason": reason,
                    "public": bool(public_dir),
                    "dir": "repo" if directory == base_dir else os.path.basename(directory),
                })
    return {"ok": not risks, "count": len(risks), "risks": risks[:20]}

def backup_sqlite_before_migration(reason: str = "startup") -> dict:
    global DB_STARTUP_BACKUP_RESULT
    if DATA_PERSISTENCE_MODE != "sqlite":
        DB_STARTUP_BACKUP_RESULT = {"status": "skipped", "path": "", "created_at": "", "reason": "non_sqlite_mode"}
        return DB_STARTUP_BACKUP_RESULT
    if not DB_STARTUP_BACKUP_ENABLED:
        DB_STARTUP_BACKUP_RESULT = {"status": "skipped", "path": "", "created_at": "", "reason": "disabled"}
        return DB_STARTUP_BACKUP_RESULT
    db_path = str(DB_FILE or "").strip()
    if not db_path or not os.path.exists(db_path):
        DB_STARTUP_BACKUP_RESULT = {"status": "skipped", "path": "", "created_at": "", "reason": "db_missing"}
        return DB_STARTUP_BACKUP_RESULT
    if os.path.getsize(db_path) <= 0:
        DB_STARTUP_BACKUP_RESULT = {"status": "skipped", "path": "", "created_at": "", "reason": "db_empty"}
        return DB_STARTUP_BACKUP_RESULT
    try:
        backup_dir = str(DB_BACKUP_DIR or "backups")
        os.makedirs(backup_dir, exist_ok=True)
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_path = os.path.join(backup_dir, f"toandaas_system_{timestamp}_{reason}.db")
        shutil.copy2(db_path, backup_path)
        DB_STARTUP_BACKUP_RESULT = {
            "status": "created",
            "path": backup_path,
            "created_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "reason": reason,
            "size_bytes": os.path.getsize(backup_path),
        }
        cleanup_old_startup_backups()
        return DB_STARTUP_BACKUP_RESULT
    except Exception as e:
        add_data_persistence_warning(
            "STARTUP_BACKUP_FAILED",
            f"Could not create SQLite backup before migration: {type(e).__name__}",
        )
        DB_STARTUP_BACKUP_RESULT = {"status": "failed", "path": "", "created_at": "", "reason": str(e)[:160]}
        return DB_STARTUP_BACKUP_RESULT

def ensure_startup_sqlite_backup_once():
    db_abs = sqlite_db_abs_path()
    if not db_abs or db_abs in DB_STARTUP_BACKUP_PATHS:
        return DB_STARTUP_BACKUP_RESULT
    DB_STARTUP_BACKUP_PATHS.add(db_abs)
    return backup_sqlite_before_migration("startup")

def db_connect():
    global DB_STARTUP_PREP_RESULT
    db_path = str(DB_FILE or "").strip()
    if db_path and os.path.dirname(os.path.abspath(db_path)):
        os.makedirs(os.path.dirname(os.path.abspath(db_path)), exist_ok=True)
    existed_before = bool(db_path and os.path.exists(db_path))
    conn = sqlite3.connect(DB_FILE, timeout=30)
    if not existed_before and DB_STARTUP_PREP_RESULT.get("status") == "new_empty_db_pending":
        DB_STARTUP_PREP_RESULT = {
            **DB_STARTUP_PREP_RESULT,
            "status": "new_empty_db_created",
            "created_at": now_text_safe(),
        }
    conn.execute("PRAGMA busy_timeout=30000")
    return conn

def telegram_token_runtime_summary() -> dict:
    token = TELEGRAM_TOKEN or ""
    return {
        "configured": bool(token),
        "len": len(token),
        "masked": mask_secret(token) if token else "",
    }

def runtime_db_status() -> dict:
    base = os.path.basename(str(DB_FILE or ""))
    db_label = base if str(DB_FILE) == base else f"configured:{base}"
    try:
        conn = db_connect()
        try:
            conn.execute("SELECT 1")
            return {"ok": True, "status": "OK", "file": db_label}
        finally:
            conn.close()
    except Exception as e:
        return {"ok": False, "status": "FAIL", "file": db_label, "error": str(e)[:300]}

def sqlite_table_exists(conn, table: str) -> bool:
    try:
        row = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name=?", (str(table),)).fetchone()
        return bool(row)
    except Exception:
        return False

def sqlite_count_table(conn, table: str) -> int:
    try:
        if not sqlite_table_exists(conn, table):
            return 0
        row = conn.execute(f"SELECT COUNT(*) FROM {table}").fetchone()
        return int(row[0] or 0) if row else 0
    except Exception:
        return 0

def data_persistence_status_payload(include_counts: bool = True) -> dict:
    evaluate_safe = False
    try:
        evaluate_data_persistence_startup_state()
        evaluate_safe = True
    except RuntimeError:
        raise
    except Exception as e:
        add_data_persistence_warning("DATA_PERSISTENCE_CHECK_FAILED", f"Startup persistence check failed: {type(e).__name__}")
    exists = sqlite_db_exists()
    size_bytes = sqlite_db_size_bytes()
    volume = sqlite_volume_status()
    backup = latest_startup_backup_info()
    prep = dict(DB_STARTUP_PREP_RESULT or {})
    risk_level = data_persistence_risk_level()
    payload = {
        "mode": DATA_PERSISTENCE_MODE,
        "database_url": masked_database_url(DATABASE_URL),
        "db_path": display_db_path(DB_FILE),
        "db_path_env_configured": bool(DB_PATH_ENV_CONFIGURED),
        "db_file_env_configured": bool(DB_FILE_ENV_CONFIGURED),
        "db_exists": exists,
        "db_size_bytes": size_bytes,
        "db_writable": sqlite_db_writable(),
        "railway_runtime": is_railway_runtime(),
        "volume_detected": bool(volume.get("detected")),
        "persistent_path_candidate": bool(volume.get("persistent_path_candidate")),
        "volume_mount": volume.get("mount") or "unknown",
        "volume_parent_dir": volume.get("parent_dir") or "",
        "volume_parent_writable": bool(volume.get("parent_writable")),
        "backup_enabled": bool(DB_STARTUP_BACKUP_ENABLED),
        "backup_last_status": backup.get("status") or "not_run",
        "backup_last_path": display_db_path(backup.get("path") or ""),
        "backup_last_at": backup.get("created_at") or "",
        "backup_dir": display_db_path(DB_BACKUP_DIR),
        "backup_dir_writable": sqlite_backup_dir_writable(),
        "migration_dry_run": bool(DB_MIGRATION_DRY_RUN),
        "destructive_migration_allowed": bool(DB_ALLOW_DESTRUCTIVE_MIGRATION),
        "require_persistent_db": bool(REQUIRE_PERSISTENT_DB),
        "startup_prep_status": prep.get("status") or "not_run",
        "startup_prep_reason": prep.get("reason") or "",
        "startup_prep_path": display_db_path(prep.get("path") or ""),
        "warnings": list(DATA_PERSISTENCE_WARNINGS),
        "data_loss_risk": risk_level in {"YES", "ERROR"},
        "data_loss_risk_level": risk_level,
        "startup_check_ok": evaluate_safe,
    }
    if include_counts and exists and size_bytes > 0:
        try:
            conn = db_connect()
            try:
                payload["table_count"] = sqlite_count_table(conn, "sqlite_master")
                row = conn.execute("SELECT COUNT(*) FROM sqlite_master WHERE type='table'").fetchone()
                payload["main_table_count"] = int(row[0] or 0) if row else 0
                payload["users_count"] = sqlite_count_table(conn, "users")
                payload["payment_topup_count"] = (
                    sqlite_count_table(conn, "payos_orders")
                    + sqlite_count_table(conn, "pending_deposits")
                    + sqlite_count_table(conn, "transactions")
                )
                payload["credit_events_count"] = sqlite_count_table(conn, "credit_events")
                payload["trial_claims_count"] = (
                    sqlite_count_table(conn, "trial_grants")
                    + sqlite_count_table(conn, "trial_bonus_claims")
                )
                payload["shopaikey_jobs_count"] = sqlite_count_table(conn, "shopaikey_jobs")
                payload["shopaikey_billing_events_count"] = sqlite_count_table(conn, "shopaikey_billing_events")
                payload["provider_status_count"] = (
                    sqlite_count_table(conn, "api_debug_events")
                    + sqlite_count_table(conn, "tool_events")
                    + sqlite_count_table(conn, "provider_freeze_state")
                )
                payload["settings_count"] = (
                    sqlite_count_table(conn, "system_settings")
                    + sqlite_count_table(conn, "system_flags")
                    + sqlite_count_table(conn, "feature_flags")
                )
                payload["backup_records_count"] = sqlite_count_table(conn, "audit_logs")
            finally:
                conn.close()
        except Exception as e:
            payload["count_error"] = str(e)[:160]
    else:
        payload.update({
            "main_table_count": 0,
            "users_count": 0,
            "payment_topup_count": 0,
            "credit_events_count": 0,
            "trial_claims_count": 0,
            "shopaikey_jobs_count": 0,
            "shopaikey_billing_events_count": 0,
            "provider_status_count": 0,
            "settings_count": 0,
            "backup_records_count": 0,
        })
    return payload

def telegram_handler_count(application) -> int:
    try:
        return sum(len(handlers) for handlers in getattr(application, "handlers", {}).values())
    except Exception:
        return 0

def _safe_sql_identifier(identifier: str) -> str:
    name = str(identifier or "").strip()
    if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
        raise ValueError(f"Unsafe SQL identifier: {name!r}")
    return name

def _table_columns(cursor, table_name):
    safe_table = _safe_sql_identifier(table_name)
    cursor.execute(f"PRAGMA table_info({safe_table})")
    return {row[1] for row in cursor.fetchall()}

def _add_column_if_missing(cursor, table_name, column_name, column_sql, existing_columns=None):
    safe_table = _safe_sql_identifier(table_name)
    safe_column = _safe_sql_identifier(column_name)
    columns = existing_columns if existing_columns is not None else _table_columns(cursor, safe_table)
    if safe_column not in columns:
        cursor.execute(f"ALTER TABLE {safe_table} ADD COLUMN {column_sql}")
        if existing_columns is not None:
            existing_columns.add(safe_column)

def migrate_feedback_schema(cursor) -> None:
    columns = _table_columns(cursor, "feedback")
    for column_name, column_sql in [
        ("user_id", "user_id TEXT"),
        ("username", "username TEXT"),
        ("category", "category TEXT DEFAULT ''"),
        ("content", "content TEXT"),
        ("context", "context TEXT DEFAULT ''"),
        ("status", "status TEXT DEFAULT 'new'"),
        ("reviewed_at", "reviewed_at TEXT DEFAULT ''"),
        ("resolved_at", "resolved_at TEXT DEFAULT ''"),
        ("timestamp", "timestamp DATETIME"),
    ]:
        _add_column_if_missing(cursor, "feedback", column_name, column_sql, columns)

