def update_video_project_job_result(job_id: int, status: str, *, final_video_path: str = "", final_video_file_id: str = "", error: str = "", result: dict | None = None, conn=None) -> dict:
    owned = conn is None
    db = conn or db_connect()
    try:
        clean_status = str(status or "").lower()
        if clean_status == "completed":
            return video_project_queue.complete_video_job(
                db,
                job_id=int(job_id),
                final_video_path=final_video_path,
                final_video_file_id=final_video_file_id,
                result=result,
            )
        if clean_status == "failed":
            return video_project_queue.fail_video_job(db, job_id=int(job_id), error=error or "video_worker_failed")
        raise ValueError("unsupported_video_job_status")
    finally:
        if owned:
            db.close()

SENSITIVE_AUDIT_KEYS = ("key", "token", "secret", "password", "authorization", "api")

def _safe_audit_value(value):
    if isinstance(value, dict):
        safe = {}
        for key, item in value.items():
            if any(marker in str(key).lower() for marker in SENSITIVE_AUDIT_KEYS):
                safe[key] = "***"
            else:
                safe[key] = _safe_audit_value(item)
        return safe
    if isinstance(value, list):
        return [_safe_audit_value(item) for item in value]
    return value

def _audit_json(value):
    if value is None:
        return ""
    try:
        return json.dumps(_safe_audit_value(value), ensure_ascii=False, default=str)
    except Exception:
        return str(value)

def record_audit(conn, actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    try:
        c = conn.cursor()
        c.execute(
            """INSERT INTO audit_logs
            (actor_id, actor_type, action, object_type, object_id, before_json, after_json, note, created_at)
            VALUES (?,?,?,?,?,?,?,?,?)""",
            (
                str(actor_id or ""),
                str(actor_type or ""),
                str(action or ""),
                str(object_type or ""),
                str(object_id or ""),
                _audit_json(before),
                _audit_json(after),
                str(note or "")[:1200],
                now_text(),
            )
        )
    except Exception as e:
        logger.warning(f"Audit log write failed: {e}")

def record_audit_event(actor_id, actor_type, action, object_type="", object_id="", before=None, after=None, note=""):
    conn = None
    try:
        conn = db_connect()
        record_audit(conn, actor_id, actor_type, action, object_type, object_id, before, after, note)
        conn.commit()
    except Exception as e:
        logger.warning(f"Audit event write failed: {e}")
    finally:
        if conn:
            conn.close()

def get_system_setting(key, default=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute("SELECT value FROM system_settings WHERE key=?", (str(key),))
        row = c.fetchone()
        return row[0] if row else default
    except sqlite3.OperationalError as e:
        if "no such table: system_settings" not in str(e).lower():
            logger.warning(f"System setting read failed: {e}")
        return default
    except Exception as e:
        logger.warning(f"System setting read failed: {e}")
        return default
    finally:
        if conn:
            conn.close()

def get_system_settings(keys: list[str]) -> dict:
    return {key: get_system_setting(key, "") for key in keys}

def set_system_setting(key, value, note="", updated_by=""):
    conn = None
    try:
        conn = db_connect()
        c = conn.cursor()
        c.execute(
            """INSERT OR REPLACE INTO system_settings
            (key, value, note, updated_at, updated_by)
            VALUES (?,?,?,?,?)""",
            (str(key), str(value or ""), str(note or "")[:1200], now_text(), str(updated_by or "")),
        )
        conn.commit()
    except Exception as e:
        logger.warning(f"System setting write failed: {e}")
        raise
    finally:
        if conn:
            conn.close()

