def _engine_async_parse_time(value) -> datetime | None:
    raw = str(value or "").strip()
    if not raw:
        return None
    for pattern in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%dT%H:%M:%S.%f"):
        try:
            return datetime.strptime(raw[:26], pattern)
        except ValueError:
            continue
    try:
        return datetime.fromisoformat(raw.replace("Z", "+00:00")).replace(tzinfo=None)
    except ValueError:
        return None

def engine_async_job_age_seconds(job: dict, now: datetime | None = None) -> int:
    created = _engine_async_parse_time((job or {}).get("created_at"))
    if not created:
        return 0
    current = now or datetime.now()
    return max(0, int((current - created).total_seconds()))

def engine_async_next_poll_after_text(now: datetime | None = None, interval_seconds: int | None = None) -> str:
    current = now or datetime.now()
    interval = max(30, int(interval_seconds or ENGINE_ASYNC_PROVIDER_POLL_INTERVAL_SECONDS))
    return (current + timedelta(seconds=interval)).strftime("%Y-%m-%d %H:%M:%S")

def engine_async_age_text(job: dict, now: datetime | None = None) -> str:
    seconds = engine_async_job_age_seconds(job, now)
    if seconds <= 0:
        return "-"
    minutes, sec = divmod(seconds, 60)
    hours, minute = divmod(minutes, 60)
    if hours:
        return f"{hours}h{minute:02d}m"
    if minutes:
        return f"{minutes}m{sec:02d}s"
    return f"{sec}s"

def engine_async_provider_processing_timed_out(job: dict, now: datetime | None = None) -> bool:
    current = dict(job or {})
    if str(current.get("feature") or "").lower() not in {"music_suno", "music_song"}:
        return False
    if str(current.get("status") or "").lower() not in {"submitted", "queued", "processing", "timeout_provider_processing"}:
        return False
    if int(current.get("output_bytes") or 0) > 0:
        return False
    return engine_async_job_age_seconds(current, now) >= ENGINE_ASYNC_PROVIDER_PROCESSING_TIMEOUT_SECONDS

def engine_async_provider_processing_soft_timed_out(job: dict, now: datetime | None = None) -> bool:
    current = dict(job or {})
    if str(current.get("feature") or "").lower() not in {"music_suno", "music_song"}:
        return False
    if str(current.get("status") or "").lower() not in {"submitted", "queued", "processing", "timeout_provider_processing"}:
        return False
    if int(current.get("output_bytes") or 0) > 0:
        return False
    return engine_async_job_age_seconds(current, now) >= ENGINE_ASYNC_PROVIDER_SOFT_TIMEOUT_SECONDS

def engine_async_status_text(job: dict, *, admin: bool = False) -> str:
    current = dict(job or {})
    if not current:
        return "⚠️ Không tìm thấy job nội bộ. TOAN AAS chưa gọi provider mới."
    provider_task_id = str(current.get("provider_task_id") or "")
    status = str(current.get("status") or "unknown")
    progress = str(current.get("progress_text") or "")
    if engine_async_provider_processing_timed_out(current):
        status = "timeout_provider_processing"
        progress = "Provider xử lý quá lâu, chưa có file nhạc. TOAN AAS chưa trừ Xu."
    if not progress:
        if status == "submitted":
            progress = "Đã gửi yêu cầu tạo nhạc/video tới provider."
        elif status == "processing":
            progress = "Provider đang xử lý. Thường mất vài phút."
        elif status == "downloading":
            progress = "Đã có kết quả, TOAN AAS đang tải file."
        elif status == "completed":
            progress = "Output đã được xác thực bytes > 0."
        elif status == "timeout":
            progress = "Provider xử lý quá lâu, chưa có file tải về."
        elif status == "failed":
            progress = "Provider/job thất bại; không fake success."
        else:
            progress = "Đang chờ trạng thái provider."
    lines = [
        f"🧾 <b>Engine job {html.escape(str(current.get('internal_job_id') or '-'))}</b>",
        "",
        f"• Feature: <code>{html.escape(str(current.get('feature') or '-'))}</code>",
        f"• Provider: <code>{html.escape(str(current.get('provider') or '-'))}</code>",
        f"• Status: <code>{html.escape(status)}</code>",
        f"• Progress: <code>{html.escape(sanitize_provider_status_text(progress, provider_task_id, 260))}</code>",
        f"• Age: <code>{html.escape(engine_async_age_text(current))}</code>",
        f"• Poll count: <code>{int(current.get('poll_count') or 0)}</code>",
        f"• Last poll: <code>{html.escape(str(current.get('last_poll_at') or '-'))}</code>",
        f"• Next poll after: <code>{html.escape(str(current.get('next_poll_after') or '-'))}</code>",
        f"• Output bytes: <code>{int(current.get('output_bytes') or 0)}</code>",
        f"• Error: <code>{html.escape(str(current.get('error_category') or '-')[:160])}</code>",
        f"• Updated: <code>{html.escape(str(current.get('updated_at') or '-'))}</code>",
    ]
    if admin:
        lines.extend([
            f"• Provider task: <code>{html.escape(mask_provider_task_id(provider_task_id))}</code>",
            f"• Last provider status: <code>{html.escape(sanitize_provider_status_text(current.get('last_provider_status') or '-', provider_task_id, 260))}</code>",
        ])
        parsed_fields = current.get("parsed_fields") if isinstance(current.get("parsed_fields"), dict) else {}
        if parsed_fields:
            lines.append(f"• Parsed fields: <code>{html.escape(suno_parsed_fields_text(parsed_fields))}</code>")
        if str(current.get("feature") or "").lower() in {"music_suno", "music_song"}:
            lines.append(f"• Fallback: <code>{html.escape(sanitize_provider_status_text(suno_fallback_status_text(str(current.get('provider') or 'key4u_suno')), provider_task_id, 260))}</code>")
    return "\n".join(lines)

def engine_async_status_keyboard(internal_job_id: str, kind: str = "music") -> InlineKeyboardMarkup:
    safe_id = re.sub(r"[^A-Za-z0-9_.:-]", "", str(internal_job_id or ""))[:40]
    safe_kind = re.sub(r"[^A-Za-z0-9_.:-]", "", str(kind or "music"))[:20]
    callback_data = f"enginejob|{safe_kind}|{safe_id}"
    rows = []
    if safe_id and len(callback_data.encode("utf-8")) <= 64:
        refresh_label = "🔄 Làm mới" if safe_kind == "multiscene" else "🔄 Kiểm tra trạng thái"
        rows.append([InlineKeyboardButton(refresh_label, callback_data=callback_data)])
    if safe_kind == "multiscene" and safe_id:
        retry_callback = f"enginejob|multiscene_retry|{safe_id}"
        if len(retry_callback.encode("utf-8")) <= 64:
            rows.append([InlineKeyboardButton("🔁 Retry cảnh lỗi", callback_data=retry_callback)])
        rows.append([InlineKeyboardButton("🟡 Freeze", callback_data="menu|admin_confirm_provider_freeze_video"), InlineKeyboardButton("📊 Provider Status", callback_data="menu|admin_provider_status")])
        rows.append([InlineKeyboardButton("⚙️ Admin", callback_data="menu|admin"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")])
    else:
        rows.append([InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)

def record_api_debug(provider: str, action: str, status: str, http_status: int = 0, detail: str = ""):
    conn = None
    try:
        conn = db_connect()
        conn.execute("""CREATE TABLE IF NOT EXISTS api_debug_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            provider TEXT,
            action TEXT,
            status TEXT,
            http_status INTEGER DEFAULT 0,
            detail TEXT,
            created_at TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT,
            severity TEXT,
            user_id TEXT,
            username TEXT,
            detail TEXT,
            created_at TEXT
        )""")
        conn.execute(
            "INSERT INTO api_debug_events (provider, action, status, http_status, detail, created_at) VALUES (?,?,?,?,?,?)",
            (
                str(provider or "")[:60],
                str(action or "")[:80],
                str(status or "")[:80],
                int(http_status or 0),
                sanitize_log_text(str(detail or ""))[:1000],
                now_text(),
            ),
        )
        status_upper = str(status or "").upper()
        if status_upper not in {"PASS", "OK", "SUCCESS"}:
            since = (vn_now() - timedelta(minutes=10)).strftime("%Y-%m-%d %H:%M:%S")
            row = conn.execute(
                """SELECT COUNT(*) FROM api_debug_events
                WHERE provider=? AND UPPER(status) NOT IN ('PASS','OK','SUCCESS') AND created_at>=?""",
                (str(provider or "")[:60], since),
            ).fetchone()
            fail_count = int(row[0] or 0) if row else 0
            if fail_count in {10, 20, 50}:
                conn.execute(
                    """INSERT INTO security_events (event_type, severity, user_id, username, detail, created_at)
                    VALUES (?,?,?,?,?,?)""",
                    (
                        "provider_error_spike",
                        "medium",
                        "",
                        "",
                        f"provider={sanitize_log_text(str(provider or ''))[:60]}; fail_count_10m={fail_count}; last_action={sanitize_log_text(str(action or ''))[:80]}",
                        now_text(),
                    ),
                )
        conn.commit()
    except Exception as e:
        logger.warning(f"API debug event write failed: {e}")
    finally:
        if conn:
            conn.close()

