def effective_chat_charge(user_id, mode: str, base_cost: int, is_admin=False, is_legacy_vip=False) -> dict:
    mode_norm = normalize_chat_tier(mode or CHAT_TIER_NORMAL)
    charge = apply_member_service_discount(user_id, int(base_cost or 0), f"ai_chat_{mode_norm}")
    tier = charge.get("tier") or "newbie"
    badge = charge.get("badge") or get_member_badge(tier)
    cost = int(charge.get("final_cost") or 0)
    reason = ""
    if is_admin:
        cost = 0
        reason = "Admin"
    elif int(charge.get("discount_xu") or 0) > 0:
        reason = f"{badge} discount {int(charge.get('discount_rate') or 0)}%"
    return {
        "base_cost": int(base_cost or 0),
        "cost": int(cost or 0),
        "mode": mode_norm,
        "tier": tier,
        "badge": badge,
        "reason": reason,
        "discount_rate": int(charge.get("discount_rate") or 0),
        "discount_xu": int(charge.get("discount_xu") or 0),
    }

def eligible_for_member_discount(tool_name: str, base_cost: int) -> bool:
    blocked = {"payment", "payos", "manual_qr", "topup", "deposit", "promo", "gift", "trial", "admin", "refund", "provider_fail"}
    name = str(tool_name or "").strip().lower()
    if int(base_cost or 0) <= 0:
        return False
    return not any(marker in name for marker in blocked)

def get_member_service_discount_rate(user_id, total_spent=None, is_vip=None) -> int:
    profile = get_member_profile(user_id)
    tier = profile.get("tier") or "newbie"
    return int(MEMBER_TOOL_DISCOUNT_POLICY.get(tier, 0) or 0)

def apply_member_service_discount(user_id, base_cost: int, tool_name: str = "service") -> dict:
    base = int(base_cost or 0)
    profile = get_member_profile(user_id)
    tier = profile.get("tier") or "newbie"
    percent = get_member_service_discount_rate(user_id)
    if not eligible_for_member_discount(tool_name, base):
        percent = 0
    discount_xu = int(math.floor(base * percent / 100)) if percent else 0
    final_cost = max(0, base - discount_xu)
    return {
        "base_cost": base,
        "discount_rate": percent,
        "discount_percent": percent,
        "discount_xu": discount_xu,
        "final_cost": final_cost,
        "discounted_cost": final_cost,
        "tier": tier,
        "tier_label": member_tier_label(tier),
        "badge": get_member_badge(tier),
    }

def calculate_member_discounted_cost(user_id, tool_name: str, base_cost: int) -> dict:
    return apply_member_service_discount(user_id, base_cost, tool_name)

def member_discount_display_line(charge: dict) -> str:
    if int((charge or {}).get("discount_xu") or 0) <= 0:
        return ""
    final_cost = int(charge.get("final_cost") or 0)
    final_line = f"Đã trừ: {final_cost} Xu" if final_cost > 0 else "Sau ưu đãi: 0 Xu"
    return (
        f"Giá gốc: {int(charge.get('base_cost') or 0)} Xu\n"
        f"Ưu đãi thành viên {html.escape(str(charge.get('badge') or ''))}: "
        f"-{int(charge.get('discount_xu') or 0)} Xu ({int(charge.get('discount_rate') or 0)}%)\n"
        f"{final_line}"
    )

def user_exists(user_id, conn=None) -> bool:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        row = conn.execute("SELECT 1 FROM users WHERE user_id=?", (str(user_id),)).fetchone()
        return bool(row)
    finally:
        if close_conn:
            conn.close()

def user_has_successful_deposit_conn(conn, user_id) -> bool:
    row = conn.execute("SELECT COALESCE(has_deposited,0) FROM users WHERE user_id=?", (str(user_id),)).fetchone()
    if row and int(row[0] or 0) > 0:
        return True
    paid_count = conn.execute(
        "SELECT COUNT(*) FROM payos_orders WHERE user_id=? AND status=? AND COALESCE(order_type,'topup')='topup'",
        (str(user_id), PAYOS_STATUS_PAID),
    ).fetchone()[0]
    if int(paid_count or 0) > 0:
        return True
    manual_count = conn.execute(
        "SELECT COUNT(*) FROM usage_events WHERE user_id=? AND event_type='payment_manual_approved'",
        (str(user_id),),
    ).fetchone()[0]
    return int(manual_count or 0) > 0

def member_total_paid_vnd(user_id, conn=None) -> int:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        stored = 0
        row = conn.execute("SELECT COALESCE(total_paid_vnd,0) FROM users WHERE user_id=?", (str(user_id),)).fetchone()
        if row:
            stored = int(row[0] or 0)
        payos_paid = int(conn.execute(
            "SELECT COALESCE(SUM(amount),0) FROM payos_orders WHERE user_id=? AND status=? AND COALESCE(order_type,'topup')='topup'",
            (str(user_id), PAYOS_STATUS_PAID),
        ).fetchone()[0] or 0)
        manual_paid = int(conn.execute(
            "SELECT COALESCE(SUM(amount_vnd),0) FROM usage_events WHERE user_id=? AND event_type='payment_manual_approved'",
            (str(user_id),),
        ).fetchone()[0] or 0)
        return max(stored, payos_paid + manual_paid)
    finally:
        if close_conn:
            conn.close()

def get_member_profile(user_id, conn=None) -> dict:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        uid = str(user_id)
        row = conn.execute(
            "SELECT COALESCE(is_vip,0), COALESCE(vip_tier_override,''), COALESCE(username,'') FROM users WHERE user_id=?",
            (uid,),
        ).fetchone()
        is_vip_flag = int(row[0] or 0) if row else 0
        user_override = normalize_member_tier(row[1] if row else "")
        table_row = conn.execute("SELECT tier FROM member_tier_overrides WHERE user_id=?", (uid,)).fetchone()
        table_override = normalize_member_tier(table_row[0] if table_row else "")
        override = table_override or user_override
        has_override = bool(override)
        total_paid = member_total_paid_vnd(uid, conn=conn)
        tier = override or ("vip" if is_vip_flag == 1 else member_tier_by_total_paid(total_paid))
        if tier == "newbie" and is_vip_flag == 1 and not has_override:
            tier = "vip"
        policy = MEMBER_REFERRAL_POLICY.get(tier, MEMBER_REFERRAL_POLICY["newbie"])
        next_tier, needed = member_next_tier(total_paid, tier)
        return {
            "user_id": uid,
            "tier": tier,
            "tier_label": member_tier_label(tier),
            "tier_badge": get_member_badge(tier),
            "total_paid_vnd": total_paid,
            "override": override,
            "is_vip": is_vip_flag,
            "next_tier": next_tier,
            "next_tier_label": member_tier_label(next_tier) if next_tier else "",
            "amount_to_next": max(0, int(needed or 0)),
            "ref_percent": int(policy.get("percent") or 0),
            "ref_cap": int(policy.get("cap") or 0),
            "discount_percent": int(MEMBER_TOOL_DISCOUNT_POLICY.get(tier, 0) or 0),
        }
    finally:
        if close_conn:
            conn.close()

def referral_link_for_user(user_id, bot_username: str = "") -> str:
    bot_name = str(bot_username or BOT_USERNAME or "toanaasbot").lstrip("@")
    return f"https://t.me/{bot_name}?start=ref_{str(user_id)}"

def referral_stats_for_user(user_id, conn=None) -> dict:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        uid = str(user_id)
        total = int(conn.execute("SELECT COUNT(*) FROM referrals WHERE referrer_user_id=?", (uid,)).fetchone()[0] or 0)
        pending = int(conn.execute("SELECT COUNT(*) FROM referrals WHERE referrer_user_id=? AND COALESCE(status,'registered') IN ('pending','registered','trial_claimed','paid_topup','reward_pending')", (uid,)).fetchone()[0] or 0)
        rewarded = int(conn.execute("SELECT COUNT(*) FROM referrals WHERE referrer_user_id=? AND COALESCE(status,'') IN ('rewarded','reward_paid')", (uid,)).fetchone()[0] or 0)
        qualified_no_reward = int(conn.execute("SELECT COUNT(*) FROM referrals WHERE referrer_user_id=? AND COALESCE(status,'')='qualified_no_reward'", (uid,)).fetchone()[0] or 0)
        reward_xu = int(conn.execute("SELECT COALESCE(SUM(reward_xu),0) FROM referrals WHERE referrer_user_id=?", (uid,)).fetchone()[0] or 0)
        recent = conn.execute(
            """SELECT referred_user_id, COALESCE(status,'pending'), COALESCE(reward_xu,0), COALESCE(created_at,'')
            FROM referrals WHERE referrer_user_id=? ORDER BY COALESCE(created_at,'') DESC LIMIT 5""",
            (uid,),
        ).fetchall()
        return {
            "total": total,
            "pending": pending,
            "rewarded": rewarded,
            "qualified_no_reward": qualified_no_reward,
            "reward_xu": reward_xu,
            "recent": recent,
        }
    finally:
        if close_conn:
            conn.close()

def register_referral(referred_user_id, referrer_user_id, user_existed_before: bool = False) -> dict:
    result = {"registered": False, "reason": "", "referrer_user_id": str(referrer_user_id or "")}
    if not str(referrer_user_id or "").isdigit():
        result["reason"] = "invalid_referrer"
        return result
    if str(referred_user_id) == str(referrer_user_id):
        result["reason"] = "self_ref"
        return result
    if user_existed_before:
        result["reason"] = "existing_user"
        return result
    get_user(referrer_user_id)
    get_user(referred_user_id)
    conn = db_connect()
    c = conn.cursor()
    try:
        if user_has_successful_deposit_conn(conn, referred_user_id):
            result["reason"] = "already_deposited"
            return result
        existing = c.execute(
            "SELECT referrer_user_id FROM referrals WHERE referred_user_id=?",
            (str(referred_user_id),),
        ).fetchone()
        if existing:
            result["reason"] = "existing_referral"
            result["referrer_user_id"] = str(existing[0] or "")
            return result
        c.execute(
            """INSERT OR IGNORE INTO referrals
            (referred_user_id, referrer_user_id, ref_code, status, first_start_at, bonus_paid, created_at, note)
            VALUES (?,?,?,?,?,?,?,?)""",
            (
                str(referred_user_id),
                str(referrer_user_id),
                f"ref_{referrer_user_id}",
                "registered",
                now_text(),
                0,
                now_text(),
                "Registered from /start referral link",
            )
        )
        inserted = c.rowcount > 0
        if inserted:
            c.execute(
                "UPDATE users SET referred_by=? WHERE user_id=? AND COALESCE(referred_by,'')=''",
                (str(referrer_user_id), str(referred_user_id)),
            )
            result["registered"] = True
            result["reason"] = "registered"
        else:
            result["reason"] = "insert_ignored"
        conn.commit()
        return result
    finally:
        conn.close()

def award_referral_bonus_if_needed(conn, referred_user_id, order_code="", amount_vnd=0, base_xu=0, is_first_deposit=False) -> dict:
    empty = {
        "status": "none",
        "reward_xu": 0,
        "referrer_user_id": "",
        "tier": "newbie",
        "tier_label": "Newbie",
        "tier_badge": get_member_badge("newbie"),
    }
    c = conn.cursor()
    c.execute(
        """SELECT referrer_user_id, COALESCE(status,'pending'), COALESCE(bonus_paid,0)
        FROM referrals WHERE referred_user_id=?""",
        (str(referred_user_id),)
    )
    row = c.fetchone()
    if not row:
        return empty
    referrer_id, status, bonus_paid = row
    result = dict(empty)
    result["referrer_user_id"] = str(referrer_id or "")
    if not referrer_id or str(referrer_id) == str(referred_user_id):
        c.execute(
            "UPDATE referrals SET status='invalid', note=? WHERE referred_user_id=? AND COALESCE(status,'registered') IN ('pending','registered','trial_claimed','paid_topup','reward_pending')",
            ("Rejected self-ref/invalid referrer", str(referred_user_id)),
        )
        result["status"] = "invalid"
        return result
    if int(bonus_paid or 0) == 1 or str(status) in {"rewarded", "reward_paid"}:
        result["status"] = "duplicate"
        return result
    if not is_first_deposit:
        c.execute(
            """UPDATE referrals SET status='invalid', note=?
            WHERE referred_user_id=? AND COALESCE(status,'registered') IN ('pending','registered','trial_claimed','paid_topup','reward_pending')""",
            ("No reward because this was not the first successful deposit", str(referred_user_id)),
        )
        result["status"] = "invalid"
        return result

    c.execute(
        "INSERT OR IGNORE INTO users (user_id, username, credits, is_vip, join_date, total_spent) VALUES (?,?,?,?,?,?)",
        (str(referrer_id), "Referral user", 0, 0, now_text(), 0),
    )
    profile = get_member_profile(referrer_id, conn=conn)
    tier = profile.get("tier") or "none"
    reward_xu = member_referral_reward(int(base_xu or 0), tier)
    final_status = "reward_paid" if reward_xu > 0 else "qualified_no_reward"
    if reward_xu > 0:
        c.execute("UPDATE users SET credits = credits + ? WHERE user_id=?", (int(reward_xu), str(referrer_id)))
        record_credit_event(
            conn,
            referrer_id,
            reward_xu,
            "referral_reward",
            order_code or referred_user_id,
            "Thưởng giới thiệu khách nạp lần đầu",
        )
    record_usage_event_conn(
        conn,
        referrer_id,
        event_type="referral_reward",
        tool_name="referral",
        command="/start ref",
        status=final_status,
        xu_delta=int(reward_xu or 0),
        amount_vnd=int(amount_vnd or 0),
        provider="internal",
        detail=f"referred={referred_user_id}; order={order_code}; tier={tier}; base_xu={int(base_xu or 0)}",
    )
    c.execute(
        """UPDATE referrals
        SET status=?, bonus_paid=?, first_deposit_order_id=?, first_deposit_amount_vnd=?,
            first_deposit_base_xu=?, reward_xu=?, rewarded_at=?, note=?
        WHERE referred_user_id=?""",
        (
            final_status,
            1 if reward_xu > 0 else 0,
            str(order_code or ""),
            int(amount_vnd or 0),
            int(base_xu or 0),
            int(reward_xu or 0),
            now_text(),
            f"Referral reward policy tier={tier}",
            str(referred_user_id),
        ),
    )
    record_audit(
        conn,
        "system",
        "system",
        "referral.reward_evaluated",
        "referral",
        str(referred_user_id),
        before={"status": status, "bonus_paid": bonus_paid},
        after={"status": final_status, "referrer_user_id": str(referrer_id), "reward_xu": int(reward_xu or 0), "tier": tier},
        note="Referral evaluated after first successful deposit",
    )
    result.update({
        "status": final_status,
        "reward_xu": int(reward_xu or 0),
        "tier": tier,
        "tier_label": profile.get("tier_label") or member_tier_label(tier),
        "tier_badge": profile.get("tier_badge") or get_member_badge(tier),
        "referrer_user_id": str(referrer_id),
    })
    return result

def normalize_promo_code(code: str) -> str:
    return re.sub(r"[^A-Z0-9_-]", "", str(code or "").strip().upper())[:32]

def tier_up_promo_policy(tier: str) -> dict:
    return MEMBER_TIER_PROMO_POLICY.get(normalize_member_tier(tier) or "", {})

def tier_up_promo_code(user_id, tier: str) -> str:
    tier_norm = normalize_member_tier(tier)
    suffix = re.sub(r"\D", "", str(user_id or ""))[-6:] or str(user_id or "")[-6:]
    return normalize_promo_code(f"UP_{tier_norm.upper()}_{suffix}")

def create_member_tier_reward(conn, user_id, tier: str, created_by="system", force=False) -> dict:
    tier_norm = normalize_member_tier(tier)
    policy = tier_up_promo_policy(tier_norm)
    if not policy:
        return {"created": False, "status": "no_policy", "tier": tier_norm, "promo_code": ""}
    uid = str(user_id)
    promo_code = tier_up_promo_code(uid, tier_norm)
    now = now_text()
    c = conn.cursor()
    existing = c.execute(
        "SELECT promo_code, bonus_percent, cap_xu, status, used_at FROM member_tier_rewards WHERE user_id=? AND tier=?",
        (uid, tier_norm),
    ).fetchone()
    if existing and not force:
        return {
            "created": False,
            "status": existing[3] or "active",
            "tier": tier_norm,
            "promo_code": existing[0] or promo_code,
            "bonus_percent": int(existing[1] or policy["percent"]),
            "cap_xu": int(existing[2] or policy["cap"]),
            "used_at": existing[4] or "",
        }
    if existing and force:
        c.execute("DELETE FROM member_tier_rewards WHERE user_id=? AND tier=?", (uid, tier_norm))
        c.execute("UPDATE promotion_codes SET status='disabled', updated_at=? WHERE code=?", (now, promo_code))
    c.execute(
        """INSERT OR IGNORE INTO member_tier_rewards
        (user_id, tier, promo_code, bonus_percent, cap_xu, status, created_at, note)
        VALUES (?,?,?,?,?,?,?,?)""",
        (uid, tier_norm, promo_code, int(policy["percent"]), int(policy["cap"]), "active", now, f"Tier up reward created by {created_by}"),
    )
    c.execute(
        """INSERT INTO promotion_codes
        (code, bonus_xu, discount_percent, max_uses, used_count, min_amount, status, note, created_at, updated_at,
         name, promo_type, value, min_amount_vnd, max_bonus_xu, usage_limit, usage_count, per_user_limit,
         created_by, requires_assignment, owner_user_id)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
        ON CONFLICT(code) DO UPDATE SET
            status=CASE WHEN promotion_codes.status='disabled' THEN 'active' ELSE promotion_codes.status END,
            note=excluded.note,
            updated_at=excluded.updated_at,
            name=excluded.name,
            promo_type=excluded.promo_type,
            value=excluded.value,
            discount_percent=excluded.discount_percent,
            min_amount=excluded.min_amount,
            min_amount_vnd=excluded.min_amount_vnd,
            max_bonus_xu=excluded.max_bonus_xu,
            usage_limit=excluded.usage_limit,
            max_uses=excluded.max_uses,
            per_user_limit=excluded.per_user_limit,
            requires_assignment=1,
            owner_user_id=excluded.owner_user_id""",
        (
            promo_code, 0, int(policy["percent"]), 1, 0, 50000, "active",
            f"Tier-up personal promo {tier_norm} for user {uid}", now, now,
            f"{get_member_badge(tier_norm)} tier-up promo", "tier_up", int(policy["percent"]), 50000,
            int(policy["cap"]), 1, 0, 1, str(created_by or ADMIN_ID), 1, uid,
        ),
    )
    record_usage_event_conn(
        conn,
        uid,
        event_type="tier_promo_created",
        tool_name="member",
        command="/grant_tier_promo" if created_by != "system" else "tier_up",
        status="created",
        provider="internal",
        detail=f"tier={tier_norm}; code={promo_code}; percent={policy['percent']}; cap={policy['cap']}",
    )
    return {
        "created": True,
        "status": "active",
        "tier": tier_norm,
        "promo_code": promo_code,
        "bonus_percent": int(policy["percent"]),
        "cap_xu": int(policy["cap"]),
        "used_at": "",
    }

def member_tiers_crossed(old_tier: str, new_tier: str) -> list[str]:
    old_rank = member_tier_rank(old_tier)
    new_rank = member_tier_rank(new_tier)
    if new_rank <= old_rank:
        return []
    return [tier for tier in MEMBER_TIER_ORDER[old_rank + 1:new_rank + 1] if tier in MEMBER_TIER_PROMO_POLICY]

def handle_member_tier_up(conn, user_id, old_tier: str, new_tier: str, total_paid_vnd: int, source="payment", grant_topup_rewards: bool = True) -> dict:
    crossed = member_tiers_crossed(old_tier, new_tier)
    if not crossed:
        return {"upgraded": False, "old_tier": normalize_member_tier(old_tier) or "newbie", "new_tier": normalize_member_tier(new_tier) or "newbie", "promos": []}
    promos = []
    if grant_topup_rewards:
        for tier in crossed:
            promo = create_member_tier_reward(conn, user_id, tier, created_by="system")
            promo["badge"] = get_member_badge(tier)
            promos.append(promo)
    record_usage_event_conn(
        conn,
        user_id,
        event_type="tier_up",
        tool_name="member",
        command=source,
        status="upgraded",
        amount_vnd=int(total_paid_vnd or 0),
        provider="internal",
        detail=f"old={normalize_member_tier(old_tier)}; new={normalize_member_tier(new_tier)}; promos={','.join(p.get('promo_code') or '' for p in promos)}",
    )
    record_audit(
        conn,
        "system",
        "system",
        "member.tier_up",
        "user",
        str(user_id),
        before={"tier": normalize_member_tier(old_tier) or "newbie"},
        after={"tier": normalize_member_tier(new_tier) or "newbie", "total_paid_vnd": int(total_paid_vnd or 0), "promos": promos},
        note=f"Tier up after {source}",
    )
    return {
        "upgraded": True,
        "old_tier": normalize_member_tier(old_tier) or "newbie",
        "new_tier": normalize_member_tier(new_tier) or "newbie",
        "total_paid_vnd": int(total_paid_vnd or 0),
        "promos": promos,
    }

