def parse_birthday_mmdd(value: str) -> str:
    raw = str(value or "").strip().replace("/", "-").replace(".", "-")
    m = re.match(r"^(\d{1,2})-(\d{1,2})$", raw)
    if not m:
        return ""
    day = int(m.group(1))
    month = int(m.group(2))
    try:
        datetime(2024, month, day)
    except ValueError:
        return ""
    return f"{day:02d}-{month:02d}"

def birthday_gift_xu_for_tier(tier: str) -> int:
    return int(MEMBER_BIRTHDAY_GIFT_XU.get(normalize_member_tier(tier) or "newbie", 0) or 0)

def get_birthday_gift_xu(tier: str) -> int:
    return birthday_gift_xu_for_tier(tier)

def parse_datetime_text(value: str):
    try:
        return datetime.strptime(str(value or "")[:19], "%Y-%m-%d %H:%M:%S").replace(tzinfo=VN_TZ)
    except Exception:
        return None

def days_since_datetime_text(value: str) -> int:
    dt = parse_datetime_text(value)
    if not dt:
        return 0
    return max(0, (vn_now() - dt).days)

def days_until_birthday(mmdd: str, from_dt=None) -> int:
    from_dt = from_dt or vn_now()
    parsed = parse_birthday_mmdd(mmdd)
    if not parsed:
        return 9999
    day, month = [int(x) for x in parsed.split("-")]
    target = datetime(from_dt.year, month, day, tzinfo=VN_TZ)
    if target.date() < from_dt.date():
        target = datetime(from_dt.year + 1, month, day, tzinfo=VN_TZ)
    return max(0, (target.date() - from_dt.date()).days)

def get_user_birthday(user_id, conn=None) -> dict:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        row = conn.execute(
            "SELECT birthday_mmdd, birthday_set_at, last_changed_at, COALESCE(change_locked,0), COALESCE(note,'') FROM user_birthdays WHERE user_id=?",
            (str(user_id),),
        ).fetchone()
        if not row:
            return {}
        return {
            "birthday_mmdd": row[0] or "",
            "birthday_set_at": row[1] or "",
            "last_changed_at": row[2] or "",
            "change_locked": int(row[3] or 0),
            "note": row[4] or "",
        }
    finally:
        if close_conn:
            conn.close()

def birthday_received_this_year(conn, user_id, year=None) -> bool:
    year = int(year or vn_now().year)
    row = conn.execute(
        "SELECT 1 FROM birthday_gifts WHERE user_id=? AND birthday_year=? LIMIT 1",
        (str(user_id), year),
    ).fetchone()
    return bool(row)

def birthday_gift_status(user_id, conn=None) -> dict:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        birthday = get_user_birthday(user_id, conn=conn)
        profile = get_member_profile(user_id, conn=conn)
        tier = profile.get("tier") or "newbie"
        gift_xu = birthday_gift_xu_for_tier(tier)
        today = vn_now()
        already = birthday_received_this_year(conn, user_id, today.year)
        if not birthday:
            state = "not_set"
        elif parse_birthday_mmdd(birthday.get("birthday_mmdd")) != today.strftime("%d-%m"):
            state = "not_today"
        elif already:
            state = "already_received"
        elif gift_xu <= 0:
            state = "tier_not_eligible"
        elif days_since_datetime_text(birthday.get("birthday_set_at")) < 30:
            state = "needs_manual_review"
        else:
            state = "eligible"
        return {
            "user_id": str(user_id),
            "birthday": birthday,
            "tier": tier,
            "badge": get_member_badge(tier),
            "gift_xu": gift_xu,
            "already_received_this_year": already,
            "days_since_set": days_since_datetime_text((birthday or {}).get("birthday_set_at", "")),
            "days_until_birthday": days_until_birthday((birthday or {}).get("birthday_mmdd", "")),
            "state": state,
        }
    finally:
        if close_conn:
            conn.close()

def serialize_birthday_review_request(row) -> dict:
    if not row:
        return {}
    return {
        "id": int(row[0] or 0),
        "user_id": row[1] or "",
        "username": row[2] or "",
        "full_name": row[3] or "",
        "birthday_mmdd": row[4] or "",
        "tier": row[5] or "",
        "status": row[6] or "",
        "reason": row[7] or "",
        "admin_id": row[8] or "",
        "admin_note": row[9] or "",
        "created_at": row[10] or "",
        "decided_at": row[11] or "",
    }

def get_birthday_review_request(conn, request_id) -> dict:
    row = conn.execute(
        """SELECT id, user_id, username, full_name, birthday_mmdd, tier, status, reason,
        admin_id, admin_note, created_at, decided_at
        FROM birthday_review_requests WHERE id=?""",
        (int(request_id),),
    ).fetchone()
    return serialize_birthday_review_request(row)

def get_pending_birthday_review_request(conn, user_id) -> dict:
    row = conn.execute(
        """SELECT id, user_id, username, full_name, birthday_mmdd, tier, status, reason,
        admin_id, admin_note, created_at, decided_at
        FROM birthday_review_requests
        WHERE user_id=? AND status='pending'
        ORDER BY id DESC LIMIT 1""",
        (str(user_id),),
    ).fetchone()
    return serialize_birthday_review_request(row)

def create_birthday_review_request(conn, user, birthday_mmdd: str, reason="birthday_within_30_days") -> dict:
    uid = str(getattr(user, "id", "") or "")
    existing = get_pending_birthday_review_request(conn, uid)
    if existing:
        return {"created": False, "request": existing}
    username = getattr(user, "username", "") or ""
    full_name = getattr(user, "full_name", "") or " ".join(
        x for x in [getattr(user, "first_name", "") or "", getattr(user, "last_name", "") or ""] if x
    ).strip()
    profile = get_member_profile(uid, conn=conn)
    tier = normalize_member_tier(profile.get("tier") or "newbie") or "newbie"
    created_at = now_text()
    cur = conn.execute(
        """INSERT INTO birthday_review_requests
        (user_id, username, full_name, birthday_mmdd, tier, status, reason, created_at)
        VALUES (?,?,?,?,?,?,?,?)""",
        (uid, username, full_name, birthday_mmdd, tier, "pending", reason, created_at),
    )
    request_id = int(cur.lastrowid or 0)
    record_usage_event_conn(
        conn,
        uid,
        username=username,
        event_type="birthday_review_requested",
        tool_name="member",
        command="/set_birthday",
        status="pending",
        provider="internal",
        detail=f"request_id={request_id}; reason={reason}; birthday={birthday_mmdd}; tier={tier}",
    )
    return {"created": True, "request": get_birthday_review_request(conn, request_id)}

def list_pending_birthday_review_requests(conn, limit=20) -> tuple[list[dict], int]:
    safe_limit = max(1, min(int(limit or 20), 20))
    rows = conn.execute(
        """SELECT id, user_id, username, full_name, birthday_mmdd, tier, status, reason,
        admin_id, admin_note, created_at, decided_at
        FROM birthday_review_requests
        WHERE status='pending'
        ORDER BY id DESC
        LIMIT ?""",
        (safe_limit,),
    ).fetchall()
    total = int(conn.execute(
        "SELECT COUNT(*) FROM birthday_review_requests WHERE status='pending'"
    ).fetchone()[0] or 0)
    return [serialize_birthday_review_request(row) for row in rows], total

def birthday_review_pending_count(conn=None) -> int:
    close_conn = False
    if conn is None:
        conn = db_connect()
        close_conn = True
    try:
        row = conn.execute("SELECT COUNT(*) FROM birthday_review_requests WHERE status='pending'").fetchone()
        return int(row[0] or 0) if row else 0
    except Exception:
        return 0
    finally:
        if close_conn:
            conn.close()

