def normalize_preset_key(text):
    return re.sub(r"[^a-z0-9]+", "", (text or "").strip().lower())

def list_campaign_presets():
    return DEFAULT_CAMPAIGN_PRESETS

def get_campaign_preset(preset_key=""):
    key = normalize_preset_key(preset_key or "tech")
    for item in DEFAULT_CAMPAIGN_PRESETS:
        keys = [item["key"], item["name"], *(item.get("aliases") or [])]
        if key in {normalize_preset_key(value) for value in keys}:
            return item
    return DEFAULT_CAMPAIGN_PRESETS[0]

def ensure_campaign_for_preset(owner_id, preset):
    campaign_name = preset.get("campaign_name") or preset.get("name") or "TOAN AAS Campaign"
    existing = find_campaign_by_name(owner_id, campaign_name)
    if existing:
        return existing, False
    campaign_id = create_campaign(
        owner_id,
        campaign_name,
        preset.get("niche", ""),
        ",".join(preset.get("platforms") or ["tiktok"]),
        "",
        "",
    )
    return get_campaign(campaign_id, owner_id), True

def operator_bootstrap_data(owner_id, include_channels=True, include_campaigns=True, include_affiliates=True, include_references=True, reference_limit=200):
    result = {
        "created": {"channels": [], "campaigns": [], "affiliates": [], "references": []},
        "skipped": {"channels": [], "campaigns": [], "affiliates": [], "references": []},
        "errors": [],
        "rule": "Bootstrap chỉ thêm cấu hình còn thiếu; không xóa, không ghi đè channel/campaign/link cũ.",
    }
    if include_channels:
        for item in DEFAULT_OPERATOR_CHANNELS:
            existing = find_social_channel(owner_id, item["platform"], item["name"], item.get("account", ""))
            if existing:
                result["skipped"]["channels"].append({"id": existing[0], "platform": existing[1], "name": existing[2], "reason": "exists"})
                continue
            channel_id = create_social_channel(
                owner_id,
                item["platform"],
                item["name"],
                item.get("account", ""),
                item.get("focus", ""),
                item.get("audience", ""),
                item.get("slots", "2/day"),
                item.get("notes", ""),
                "manual",
                "",
                "",
            )
            result["created"]["channels"].append({"id": channel_id, "platform": item["platform"], "name": item["name"]})
    if include_campaigns:
        for item in DEFAULT_OPERATOR_CAMPAIGNS:
            existing = find_campaign_by_name(owner_id, item["name"])
            if existing:
                result["skipped"]["campaigns"].append({"id": existing[0], "name": existing[1], "reason": "exists"})
                continue
            campaign_id = create_campaign(
                owner_id,
                item["name"],
                item["niche"],
                item["platforms"],
                "",
                "",
            )
            result["created"]["campaigns"].append({"id": campaign_id, "name": item["name"], "platforms": item["platforms"]})
    if include_affiliates:
        created, skipped = seed_default_affiliate_links(owner_id)
        result["created"]["affiliates"] = [
            {"id": aid, "network": network, "product": product, "url": url}
            for aid, network, product, url in created
        ]
        result["skipped"]["affiliates"] = [
            {"id": row[0], "network": row[1], "product": row[2], "reason": "exists"}
            for row in skipped
        ]
    if include_references:
        scan = scan_reference_video_folder(
            owner_id,
            REFERENCE_VIDEO_DIR,
            platform="tiktok",
            tags="reference,bootstrap,affiliate-video",
            note="operator_bootstrap_reference_scan",
            limit=reference_limit,
        )
        result["reference_scan"] = scan
        result["created"]["references"] = scan.get("created", [])
        result["skipped"]["references"] = [{"path": path, "reason": "exists"} for path in scan.get("skipped", [])]
        result["errors"].extend(scan.get("errors", []))
    status = operator_status_data(owner_id)
    audit = operator_audit_data(owner_id)
    result["counts_after"] = status["counts"]
    result["audit_level_after"] = audit["level"]
    result["next_command"] = audit["next_command"]
    return result

def list_affiliate_links(owner_id, limit=30):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, network, product_name, niche, url, commission_note, status,
                  price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
        FROM affiliate_links WHERE owner_id=? ORDER BY id DESC LIMIT ?""",
        (str(owner_id), limit)
    )
    rows = c.fetchall()
    conn.close()
    return rows

def get_affiliate_link(affiliate_id, owner_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, network, product_name, niche, url, commission_note, status,
                  price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
        FROM affiliate_links WHERE id=? AND owner_id=?""",
        (affiliate_id, str(owner_id))
    )
    row = c.fetchone()
    conn.close()
    return row

def find_affiliate_link_by_url(owner_id, url):
    clean_url = (url or "").strip()
    if not clean_url:
        return None
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, network, product_name, niche, url, commission_note, status,
                  price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
        FROM affiliate_links WHERE owner_id=? AND url=? ORDER BY id DESC LIMIT 1""",
        (str(owner_id), clean_url)
    )
    row = c.fetchone()
    conn.close()
    return row

def public_tracking_base_url():
    return (PUBLIC_BASE_URL or "").rstrip("/")

def check_operator_bridge_config(public_base_url=None, operator_api_token=None, enabled=None) -> dict:
    bridge_enabled = OPERATOR_API_ENABLED if enabled is None else bool(enabled)
    base_url = (PUBLIC_BASE_URL if public_base_url is None else str(public_base_url or "")).strip().rstrip("/")
    token = OPERATOR_API_TOKEN if operator_api_token is None else str(operator_api_token or "")
    if not bridge_enabled:
        return {
            "status": "disabled",
            "severity": "disabled",
            "enabled": False,
            "ok": True,
            "missing": [],
            "reason": "operator_api_disabled",
            "safe_message": "Operator API bridge đang tắt bằng OPERATOR_API_ENABLED=false; đây là tính năng nội bộ tùy chọn.",
            "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        }
    missing = []
    if not base_url:
        missing.append("PUBLIC_BASE_URL")
    if not token:
        missing.append("OPERATOR_API_TOKEN")
    parsed = urlparse(base_url) if base_url else None
    host = (parsed.hostname or "").lower() if parsed else ""
    if base_url and (host in {"localhost", "127.0.0.1", "::1"} or base_url.startswith(("http://localhost", "https://localhost"))):
        return {
            "status": "fail",
            "severity": "fail",
            "enabled": True,
            "ok": False,
            "missing": [],
            "reason": "public_base_url_localhost",
            "safe_message": "PUBLIC_BASE_URL không được là localhost/127.0.0.1 khi bật Operator API.",
            "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        }
    if missing:
        return {
            "status": "fail",
            "severity": "fail",
            "enabled": True,
            "ok": False,
            "missing": missing,
            "reason": "missing_required_env",
            "safe_message": "Thiếu cấu hình bắt buộc cho Operator API bridge: " + ", ".join(missing),
            "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        }
    if len(token) < 24:
        return {
            "status": "fail",
            "severity": "fail",
            "enabled": True,
            "ok": False,
            "missing": [],
            "reason": "operator_token_too_short",
            "safe_message": "OPERATOR_API_TOKEN quá ngắn; hãy dùng secret mạnh, ví dụ secrets.token_urlsafe(32).",
            "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        }
    if parsed and parsed.scheme not in {"http", "https"}:
        return {
            "status": "fail",
            "severity": "fail",
            "enabled": True,
            "ok": False,
            "missing": [],
            "reason": "public_base_url_invalid_scheme",
            "safe_message": "PUBLIC_BASE_URL phải là URL http/https public của backend Railway.",
            "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
        }
    return {
        "status": "pass",
        "severity": "pass",
        "enabled": True,
        "ok": True,
        "missing": [],
        "reason": "configured",
        "safe_message": "PUBLIC_BASE_URL và OPERATOR_API_TOKEN đã sẵn sàng cho bridge nội bộ.",
        "public_base_url_source": PUBLIC_BASE_URL_SOURCE or "",
    }

def affiliate_tracking_url(affiliate_id, job_id=0, source=""):
    base_url = public_tracking_base_url()
    if not base_url or not affiliate_id:
        return ""
    query = {}
    if job_id:
        query["job"] = int(job_id)
    if source:
        query["src"] = normalize_tracking_source(source)
    suffix = f"?{urlencode(query)}" if query else ""
    return f"{base_url}/r/{int(affiliate_id)}{suffix}"

def update_affiliate_profile(owner_id, affiliate_id, **fields):
    allowed = {
        "network", "product_name", "niche", "url", "commission_note", "price_vnd",
        "commission_rate", "target_audience", "allowed_claims", "blocked_claims",
        "product_score", "status"
    }
    updates = []
    params = []
    for key, value in fields.items():
        if key not in allowed or value is None:
            continue
        updates.append(f"{key}=?")
        params.append(value)
    if not updates:
        return False
    params.extend([affiliate_id, str(owner_id)])
    conn = db_connect()
    c = conn.cursor()
    c.execute(f"UPDATE affiliate_links SET {', '.join(updates)} WHERE id=? AND owner_id=?", params)
    changed = c.rowcount
    conn.commit()
    conn.close()
    return changed > 0

def infer_affiliate_network_from_url(url):
    host = urlparse(url or "").netloc.lower()
    if "shopee" in host or "goeco.mobi" in host:
        return "GoEco"
    if "lazada" in host:
        return "Lazada"
    if "trackfin" in host:
        return "TrackFin"
    if "trackec" in host:
        return "TrackEC"
    if "trackecom" in host:
        return "TrackEcom"
    if "trackmobi" in host:
        return "TrackMobi"
    if "attracking" in host:
        return "Attracking"
    if "shorten" in host:
        return "ShortenAsia"
    if "goecom" in host:
        return "GoEcom"
    return host.replace("www.", "").split(".")[0].title() if host else "Affiliate"

def infer_affiliate_niche(product_name, fallback=""):
    text = (product_name or "").lower()
    rules = [
        (("bank", "vpbank", "vib", "mbbank", "bidv", "hdbank", "the", "vay", "loan", "finance", "bao hiem", "card"), "tai chinh ngan hang the vay bao hiem"),
        (("shopee", "lazada", "aeon", "nguyen kim", "nguyễn kim", "media", "mediamart", "samsung", "cellphones", "shopdunk", "hoang ha", "hoàng hà", "dien thoai", "điện thoại", "computer"), "cong nghe san thuong mai dien tu dien may"),
        (("travel", "klook", "ve may bay", "airlines", "vinwonders", "gotadi", "atadi", "bestprice", "du lich"), "du lich booking ve may bay khach san tour"),
        (("adidas", "supersports", "juno", "vascara", "vera", "jockey", "bitis", "shondo", "fashion", "thoi trang"), "thoi trang giay dep lifestyle"),
        (("con cung", "chickita", "mam", "nam ngu", "elmich", "gia dung", "me va be"), "hang tieu dung gia dinh me va be"),
        (("zalo ads", "tiktok for business", "ads", "marketing"), "quang cao marketing ban hang"),
    ]
    for keys, niche in rules:
        if any(key in text for key in keys):
            return niche
    return fallback or "affiliate tong hop"

def parse_affiliate_import_items(raw_text, default_niche="", default_network=""):
    items = []
    seen = set()
    for match in re.finditer(r"https?://[^\s,;]+", raw_text or "", flags=re.I):
        url = match.group(0).rstrip(").,;!?\"'")
        if url in seen:
            continue
        seen.add(url)
        tail = (raw_text or "")[match.end(): match.end() + 180]
        label_match = re.match(r"\s*\(([^)]+)\)", tail)
        product = label_match.group(1).strip() if label_match else ""
        if not product:
            line_start = (raw_text or "").rfind("\n", 0, match.start()) + 1
            line_end = (raw_text or "").find("\n", match.end())
            if line_end < 0:
                line_end = len(raw_text or "")
            line = (raw_text or "")[line_start:line_end]
            product = re.sub(r"https?://[^\s,;]+", " ", line, flags=re.I)
            product = re.sub(r"[\(\)\[\]{}:,;]+", " ", product)
            product = re.sub(r"\s+", " ", product).strip()
        if not product:
            slug = urlparse(url).path.strip("/").split("/")[-1] or urlparse(url).netloc
            product = f"{infer_affiliate_network_from_url(url)} {slug}".strip()
        network = default_network or infer_affiliate_network_from_url(url)
        niche = infer_affiliate_niche(product, default_niche)
        items.append({
            "network": network,
            "product_name": product[:160],
            "niche": niche,
            "url": url,
            "commission_note": f"bulk_import | brand={product[:80]} | family={niche} | os=all",
            "target_audience": niche,
            "allowed_claims": DEFAULT_AFFILIATE_ALLOWED_CLAIMS,
            "blocked_claims": DEFAULT_AFFILIATE_BLOCKED_CLAIMS,
            "product_score": 72,
        })
    return items

def import_affiliate_links_from_text(owner_id, raw_text, default_niche="", default_network=""):
    created = []
    skipped = []
    errors = []
    for item in parse_affiliate_import_items(raw_text, default_niche=default_niche, default_network=default_network):
        existing = get_affiliate_by_url(owner_id, item["url"])
        if existing:
            skipped.append(existing)
            continue
        try:
            affiliate_id = create_affiliate_link(
                owner_id,
                item["network"],
                item["product_name"],
                item["niche"],
                item["url"],
                item["commission_note"],
                0,
                0,
                item["target_audience"],
                item["allowed_claims"],
                item["blocked_claims"],
                item["product_score"],
            )
            created.append((affiliate_id, item["network"], item["product_name"], item["url"], item["niche"]))
        except Exception as exc:
            errors.append({"url": item["url"], "error": str(exc)})
    return created, skipped, errors

def ensure_growth_content_defaults_after_affiliate_import(owner_id) -> dict:
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute("SELECT COUNT(*) FROM affiliate_links WHERE owner_id=? AND status='active'", (str(owner_id),))
        active_affiliates = int(c.fetchone()[0] or 0)
        c.execute("SELECT COUNT(*) FROM social_channels WHERE owner_id=? AND status='active'", (str(owner_id),))
        active_channels = int(c.fetchone()[0] or 0)
        c.execute("SELECT COUNT(*) FROM campaigns WHERE owner_id=? AND status='active'", (str(owner_id),))
        active_campaigns = int(c.fetchone()[0] or 0)
    finally:
        conn.close()
    result = {
        "active_affiliates": active_affiliates,
        "created_channel": None,
        "created_campaign": None,
        "skipped": [],
    }
    if active_affiliates <= 0:
        result["skipped"].append("no_real_affiliate_data")
        return result
    if active_channels <= 0:
        channel_id = create_social_channel(
            owner_id,
            "telegram",
            "TOAN AAS Affiliate Content",
            "planned",
            "affiliate content seed",
            "khách quan tâm sản phẩm affiliate và nội dung AI",
            "manual",
            "Default planned/manual channel created after real affiliate import. No publisher API is enabled.",
            "manual",
            "",
            "",
        )
        result["created_channel"] = {"id": channel_id, "name": "TOAN AAS Affiliate Content", "status": "active"}
    if active_campaigns <= 0:
        campaign_id = create_campaign(
            owner_id,
            "Affiliate Content Seed Campaign",
            "affiliate content test",
            "telegram",
            "",
            "",
        )
        result["created_campaign"] = {"id": campaign_id, "name": "Affiliate Content Seed Campaign", "status": "active"}
    return result

def affiliate_match_score(affiliate, niche="", trend_text="", platform=""):
    (
        aid, network, product_name, aff_niche, url, commission_note, status,
        price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
    ) = affiliate
    text = f"{niche} {trend_text} {platform}".lower()
    tokens = (
        tokenize_text(product_name) + tokenize_text(aff_niche) + tokenize_text(network) +
        tokenize_text(target_audience) + tokenize_text(allowed_claims)
    )
    hits = sum(1 for token in tokens[:30] if token in text)
    score = int(product_score or 0) + hits * 8
    if commission_rate:
        score += min(20, int(float(commission_rate) * 2))
    if commission_note:
        score += 5
    if url:
        score += 5
    blocked_hits = sum(1 for token in tokenize_text(blocked_claims)[:20] if token in text)
    score -= blocked_hits * 12
    return clamp_score(score), hits, blocked_hits

def list_affiliate_matches(owner_id, niche="", trend_text="", platform="", limit=10):
    rows = list_affiliate_links(owner_id, limit=100)
    active_rows = [row for row in rows if (row[6] or "active") == "active"]
    ranked = []
    for row in active_rows:
        score, hits, blocked_hits = affiliate_match_score(row, niche, trend_text, platform)
        ranked.append((score, hits, blocked_hits, row))
    ranked.sort(key=lambda item: item[0], reverse=True)
    return ranked[:limit]

def affiliate_search_blob(affiliate):
    (
        aid, network, product_name, aff_niche, url, commission_note, status,
        price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
    ) = affiliate
    return " ".join([
        str(network or ""),
        str(product_name or ""),
        str(aff_niche or ""),
        str(commission_note or ""),
        str(target_audience or ""),
    ]).lower()

def extract_affiliate_brand_hint(text):
    text = text or ""
    match = re.search(r"brand\s*=\s*([^|,;\n]+)", text, flags=re.I)
    if match:
        return match.group(1).strip()
    return ""

def affiliate_family_tokens(affiliate):
    blob = affiliate_search_blob(affiliate)
    groups = {
        "finance": ["tai", "chinh", "ngan", "hang", "the", "vay", "credit", "bank", "loan", "bao", "hiem"],
        "travel": ["du", "lich", "tour", "ve", "may", "bay", "khach", "san", "booking", "sim", "tham", "quan"],
        "tech": ["cong", "nghe", "dien", "thoai", "laptop", "pc", "may", "tinh", "samsung", "iphone", "apple"],
        "ecommerce": ["san", "thuong", "mai", "voucher", "deal", "mua", "online", "eshop"],
        "fashion": ["thoi", "trang", "giay", "tui", "dep", "juno", "adidas", "vascara", "jockey", "vera"],
        "home": ["gia", "dung", "dien", "may", "nha", "bep", "noi", "tro", "elmich"],
        "mom_baby": ["me", "be", "con", "cung", "tre", "nho"],
    }
    found = set()
    for family, tokens in groups.items():
        if any(token in blob for token in tokens):
            found.add(family)
    return found

def score_related_affiliate(base_affiliate, candidate, brand_query="", niche_query=""):
    if not candidate or (candidate[6] or "active") != "active":
        return 0, []
    if base_affiliate and candidate[0] == base_affiliate[0]:
        return 0, []

    base_blob = affiliate_search_blob(base_affiliate) if base_affiliate else ""
    cand_blob = affiliate_search_blob(candidate)
    query_blob = f"{brand_query or ''} {niche_query or ''}".lower()
    score = 0
    reasons = []

    brand_hint = extract_affiliate_brand_hint(base_blob) or brand_query
    if brand_hint and brand_hint.lower() in cand_blob:
        score += 60
        reasons.append(f"cùng brand {brand_hint}")

    base_tokens = set(tokenize_text(base_blob + " " + query_blob)[:80])
    cand_tokens = set(tokenize_text(cand_blob)[:80])
    overlap = sorted((base_tokens & cand_tokens) - {"affiliate", "link", "brand", "family", "all"})
    if overlap:
        score += min(40, len(overlap) * 5)
        reasons.append("trùng từ khóa: " + ", ".join(overlap[:5]))

    families = affiliate_family_tokens(base_affiliate) if base_affiliate else set()
    query_family = affiliate_family_tokens((0, "", niche_query, niche_query, "", query_blob, "active", 0, 0, "", "", "", 0)) if niche_query else set()
    family_overlap = (families | query_family) & affiliate_family_tokens(candidate)
    if family_overlap:
        score += 22
        reasons.append("cùng nhóm: " + ", ".join(sorted(family_overlap)))

    if "android" in (base_blob + query_blob) and "ios" in cand_blob:
        score += 35
        reasons.append("bổ sung link iOS")
    if ("ios" in base_blob or "iphone" in base_blob or "iphone" in query_blob) and "android" in cand_blob:
        score += 35
        reasons.append("bổ sung link Android")

    return score, reasons

def list_related_affiliate_links(owner_id, affiliate_id=0, brand="", niche="", limit=12):
    base = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    rows = list_affiliate_links(owner_id, limit=300)
    ranked = []
    for row in rows:
        score, reasons = score_related_affiliate(base, row, brand, niche)
        if score > 0:
            ranked.append((score, reasons, row))
    ranked.sort(key=lambda item: item[0], reverse=True)
    return ranked[:limit]

def build_affiliate_link_bundle(owner_id, affiliate_id=0, job_id=0, brand="", niche="", platform="tiktok", limit=12):
    platform = (platform or "social").lower()
    base = get_affiliate_link(affiliate_id, owner_id) if affiliate_id else None
    auto_selected = False
    if not base and (brand or niche):
        matches = list_affiliate_matches(owner_id, niche=niche or brand, trend_text=f"{brand} {niche}", platform=platform, limit=1)
        if matches:
            _score, _hits, _blocked, base = matches[0]
            affiliate_id = base[0]
            auto_selected = True
    if affiliate_id and not base:
        return False, "affiliate_not_found", {}

    related = list_related_affiliate_links(
        owner_id,
        affiliate_id=affiliate_id,
        brand=brand,
        niche=niche or (base[3] if base else ""),
        limit=limit,
    )
    placements = ["caption", "pinned_comment", "bio", "status", "reply_comment"]

    def link_payload(row, role, score=0, reasons=None):
        aid, network, product, aff_niche, url, note, status, price_vnd, commission_rate, audience, allowed, blocked, product_score = row
        tracking = {
            placement: affiliate_tracking_url(aid, job_id, f"{platform}_{placement}_{role}") or url
            for placement in placements
        }
        return {
            "id": aid,
            "role": role,
            "network": network,
            "product": product,
            "niche": aff_niche,
            "url": url,
            "tracking": tracking,
            "recommended_url": tracking["pinned_comment"] or url,
            "score": int(score or product_score or 0),
            "reasons": reasons or [],
            "target_audience": audience,
            "allowed_claims": allowed,
            "blocked_claims": blocked,
        }

    primary = link_payload(base, "primary") if base else None
    related_links = [
        link_payload(row, "related", score, reasons[:3])
        for score, reasons, row in related
    ]
    all_links = ([primary] if primary else []) + related_links
    pinned_lines = []
    if primary:
        pinned_lines.append(f"Link chính - {primary['product']}: {primary['tracking']['pinned_comment']}")
    for item in related_links[:6]:
        pinned_lines.append(f"{item['product']}: {item['tracking']['pinned_comment']}")
    caption_links = []
    if primary:
        caption_links.append(primary["tracking"]["caption"])
    return True, "ok", {
        "job_id": int(job_id or 0),
        "platform": platform,
        "auto_selected_primary": auto_selected,
        "query": {"affiliate_id": affiliate_id, "brand": brand, "niche": niche},
        "primary": primary,
        "related_links": related_links,
        "all_links": all_links,
        "placement_plan": {
            "caption": caption_links,
            "pinned_comment": "\n".join(pinned_lines),
            "bio": primary["tracking"]["bio"] if primary else "",
            "status": "\n".join([item["tracking"]["status"] for item in all_links[:8]]),
            "reply_comment": "\n".join([item["tracking"]["reply_comment"] for item in related_links[:5]]),
        },
        "performance_rule": (
            "Mỗi placement có src riêng trong tracking URL. Sau khi đăng, dùng tracking_report/affiliate_report "
            "để so sánh caption, pinned_comment, bio, status và reply_comment."
        ),
    }

def format_related_affiliate_links(related, max_items=8):
    lines = []
    for score, reasons, row in related[:max_items]:
        aid, network, product_name, aff_niche, url, *_ = row
        reason_text = "; ".join(reasons[:2]) if reasons else f"score={score}"
        lines.append(f"#{aid} | {network or '-'} | {product_name or '-'} | {url or '-'} | {reason_text}")
    return "\n".join(lines)

def build_affiliate_comment_pack(owner_id, job_id, max_comments=10, delay_seconds=30):
    job = get_production_job(job_id, owner_id)
    if not job:
        return None
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    max_comments = max(1, min(int(max_comments or 10), 10))
    delay_seconds = max(10, min(int(delay_seconds or 30), 600))
    _ok, _reason, bundle = build_affiliate_link_bundle(
        owner_id,
        affiliate_id=affiliate_id or 0,
        job_id=jid,
        brand=product_name or "",
        niche=topic or product_name or "",
        platform=platform or "social",
        limit=max_comments,
    )
    all_links = (bundle or {}).get("all_links") or []
    primary = (bundle or {}).get("primary") or {}
    disclosure = "Có thể nhận hoa hồng affiliate nếu bạn mua/đăng ký qua link."
    comments = []
    templates = [
        "Mình để link chính ở đây cho ai cần: {url}\n{disclosure}",
        "Sản phẩm/dịch vụ liên quan trong video: {product}\n{url}",
        "Ai muốn so sánh thêm lựa chọn tương tự thì xem link này: {url}",
        "Link tham khảo cho {product}: {url}",
        "Nếu link chính chưa hợp nhu cầu, đây là lựa chọn liên quan: {url}",
        "Mình tách riêng link để mọi người dễ bấm và dễ đo hiệu quả: {url}",
        "Gợi ý thêm cùng nhóm sản phẩm: {product}\n{url}",
        "Danh sách link liên quan mình để dần ở comment để tránh caption quá dài: {url}",
        "Ai cần xem sau thì lưu comment này: {product} - {url}",
        "Link theo dõi hiệu quả nguồn comment: {url}",
    ]
    for idx, link in enumerate(all_links[:max_comments], start=1):
        tracking = link.get("tracking") or {}
        url = tracking.get("pinned_comment") or tracking.get("reply_comment") or link.get("recommended_url") or link.get("url") or ""
        text = templates[(idx - 1) % len(templates)].format(
            product=link.get("product") or product_name or "sản phẩm",
            url=url,
            disclosure=disclosure if idx == 1 else "",
        ).strip()
        source = normalize_tracking_source(f"{platform or 'social'}_job_{jid}_comment_{idx}", "comment")
        comments.append({
            "order": idx,
            "role": link.get("role") or ("primary" if idx == 1 else "related"),
            "affiliate_id": int(link.get("id") or 0),
            "product": link.get("product") or "",
            "network": link.get("network") or "",
            "text": text,
            "url": url,
            "tracking_source": source,
            "delay_seconds_after_previous": 0 if idx == 1 else delay_seconds,
            "status": "draft",
            "record_click_command": f"/performance_add job={jid} type=click value=<CLICKS> source={source} note=comment_{idx}",
        })
    caption_comment = ""
    if primary:
        primary_url = ((primary.get("tracking") or {}).get("caption") or primary.get("recommended_url") or primary.get("url") or "")
        caption_comment = f"Link chính: {primary_url}\n{disclosure}".strip()
    return {
        "ok": True,
        "generated_at": now_text(),
        "job_id": jid,
        "platform": platform or "social",
        "topic": topic or "",
        "channel": {"id": channel_id, "name": channel_name, "account_label": account_label},
        "publish_url": publish_url or "",
        "primary_comment": caption_comment or (comments[0]["text"] if comments else ""),
        "comments": comments,
        "max_comments": max_comments,
        "delay_seconds_between_comments": delay_seconds,
        "affiliate_bundle": bundle or {},
        "commands": {
            "publish_pack": f"/publish_pack job={jid}",
            "distribution_pack": f"/distribution_pack job={jid}",
            "post_publish": f"/post_publish job={jid}",
            "tracking_report": "/tracking_report days=30 limit=20",
        },
        "rule": (
            "Không spam comment quá nhanh; đăng comment chính trước, các comment liên quan cách nhau delay_seconds. "
            "Mỗi comment có tracking_source riêng để đo comment/link nào hiệu quả."
        ),
    }

def fallback_affiliate_video_ideas(affiliate, platform="tiktok", limit=5):
    (
        aid, network, product_name, niche, url, commission_note, status,
        price_vnd, commission_rate, target_audience, allowed_claims, blocked_claims, product_score
    ) = affiliate
    product = product_name or "sản phẩm affiliate"
    audience = target_audience or "người mua online"
    platform = platform or "tiktok"
    templates = [
        (
            f"3 lỗi thường gặp khi chọn {product}",
            f"mở bằng vấn đề thật của {audience}, demo cách tránh lỗi, CTA xem link nếu phù hợp",
            "problem -> quick checklist -> soft CTA",
        ),
        (
            f"So sánh nhanh {product} cho người mới",
            "đặt 2-3 tiêu chí chọn mua, không phóng đại kết quả, chốt bằng tiêu chí tự kiểm tra",
            "comparison -> buying criteria -> disclosure",
        ),
        (
            f"Checklist trước khi dùng {product}",
            "dùng dạng checklist lưu lại được, ưu tiên minh bạch điều kiện/chi phí/chính sách",
            "checklist -> common traps -> CTA",
        ),
        (
            f"Một tình huống đời thường cần {product}",
            "kể tình huống ngắn, đưa sản phẩm như một lựa chọn, không ép mua",
            "story -> use case -> link placement",
        ),
        (
            f"Review thật lòng: {product} hợp với ai?",
            "nêu ai nên dùng, ai không nên dùng, minh bạch đây là affiliate",
            "fit/not-fit -> pros/limits -> affiliate disclosure",
        ),
    ]
    ideas = []
    for idx, (hook, angle, structure) in enumerate(templates[:limit], 1):
        ideas.append(
            f"{idx}. Hook: {hook}\n"
            f"   Góc làm: {angle}\n"
            f"   Format: {structure}\n"
            f"   Nền tảng: {platform}\n"
            f"   CTA: Xem link {product} trong bio/mô tả nếu phù hợp nhu cầu."
        )
    return "\n\n".join(ideas)

def create_calendar_slot(owner_id, channel_id, campaign_id, affiliate_id, post_date, platform, topic, notes="") -> int:
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO content_calendar
        (owner_id, channel_id, campaign_id, affiliate_id, post_date, platform, topic, status, notes, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (str(owner_id), channel_id, campaign_id, affiliate_id, post_date, platform, topic, "planned", notes, now_text())
    )
    slot_id = c.lastrowid
    conn.commit()
    conn.close()
    return slot_id

def list_calendar_slots(owner_id, limit=30):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT cc.id, cc.post_date, cc.platform, sc.channel_name, cc.topic, cc.status, cc.campaign_id, cc.affiliate_id
        FROM content_calendar cc
        LEFT JOIN social_channels sc ON sc.id = cc.channel_id
        WHERE cc.owner_id=?
        ORDER BY cc.post_date ASC, cc.id DESC
        LIMIT ?""",
        (str(owner_id), limit)
    )
    rows = c.fetchall()
    conn.close()
    return rows

def get_calendar_slot(slot_id, owner_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT cc.id, cc.owner_id, cc.channel_id, cc.campaign_id, cc.affiliate_id, cc.post_date,
                  cc.platform, cc.topic, cc.status, cc.notes,
                  sc.channel_name, sc.account_label, sc.topic_focus, sc.audience,
                  al.network, al.product_name, al.url, al.commission_note
        FROM content_calendar cc
        LEFT JOIN social_channels sc ON sc.id = cc.channel_id
        LEFT JOIN affiliate_links al ON al.id = cc.affiliate_id
        WHERE cc.id=? AND cc.owner_id=?""",
        (slot_id, str(owner_id))
    )
    row = c.fetchone()
    conn.close()
    return row

def create_production_job(owner_id, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, brief_text="", note="") -> int:
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO production_jobs
        (owner_id, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic,
         stage, status, operator_note, brief_text, asset_url, publish_url, created_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            str(owner_id), calendar_id, campaign_id, channel_id, affiliate_id, platform, topic,
            "brief", "queued", note, brief_text, "", "", now_text(), now_text()
        )
    )
    job_id = c.lastrowid
    if calendar_id:
        c.execute("UPDATE content_calendar SET status=? WHERE id=? AND owner_id=?", ("in_production", calendar_id, str(owner_id)))
    conn.commit()
    conn.close()
    return job_id

def create_operator_mission(owner_id, title, objective, platform="tiktok", priority=5, note="") -> int:
    title = (title or "").strip()[:240] or "Operator mission"
    objective = (objective or "").strip()
    platform = (platform or "tiktok").strip().lower()[:40]
    priority = max(1, min(int(priority or 5), 10))
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO operator_missions
        (owner_id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
        (str(owner_id), title, objective, platform, priority, "queued", "", "", note, now_text(), now_text())
    )
    mission_id = c.lastrowid
    conn.commit()
    conn.close()
    return mission_id

def list_operator_missions(owner_id, status="", limit=10):
    limit = max(1, min(int(limit or 10), 50))
    conn = db_connect()
    c = conn.cursor()
    if status:
        c.execute(
            """SELECT id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at
            FROM operator_missions WHERE owner_id=? AND status=?
            ORDER BY priority DESC, id ASC LIMIT ?""",
            (str(owner_id), status, limit)
        )
    else:
        c.execute(
            """SELECT id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at
            FROM operator_missions WHERE owner_id=?
            ORDER BY
              CASE status WHEN 'working' THEN 0 WHEN 'queued' THEN 1 WHEN 'blocked' THEN 2 ELSE 3 END,
              priority DESC, id DESC
            LIMIT ?""",
            (str(owner_id), limit)
        )
    rows = c.fetchall()
    conn.close()
    return rows

def get_operator_mission(owner_id, mission_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at
        FROM operator_missions WHERE owner_id=? AND id=?""",
        (str(owner_id), int(mission_id))
    )
    row = c.fetchone()
    conn.close()
    return row

def claim_operator_mission(owner_id, worker="claude"):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at
        FROM operator_missions
        WHERE owner_id=? AND status='queued'
        ORDER BY priority DESC, id ASC
        LIMIT 1""",
        (str(owner_id),)
    )
    row = c.fetchone()
    if not row:
        conn.close()
        return None
    mission_id = row[0]
    c.execute(
        "UPDATE operator_missions SET status='working', assigned_to=?, updated_at=? WHERE id=? AND owner_id=? AND status='queued'",
        ((worker or "claude")[:120], now_text(), mission_id, str(owner_id))
    )
    conn.commit()
    conn.close()
    return get_operator_mission(owner_id, mission_id)

def complete_operator_mission(owner_id, mission_id, status="done", result=None, note=""):
    status = (status or "done").lower()
    if status not in {"done", "blocked", "queued", "working", "cancelled"}:
        status = "done"
    result_json = json.dumps(result or {}, ensure_ascii=False)
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """UPDATE operator_missions
        SET status=?, result_json=?, note=?, updated_at=?
        WHERE id=? AND owner_id=?""",
        (status, result_json, note or "", now_text(), int(mission_id), str(owner_id))
    )
    changed = c.rowcount
    conn.commit()
    conn.close()
    return changed > 0

def serialize_operator_mission(row):
    if not row:
        return None
    mission_id, title, objective, platform, priority, status, assigned_to, result_json, note, created_at, updated_at = row
    result = {}
    if result_json:
        try:
            result = json.loads(result_json)
        except Exception:
            result = {"raw": result_json}
    return {
        "id": mission_id,
        "title": title,
        "objective": objective,
        "platform": platform,
        "priority": priority,
        "status": status,
        "assigned_to": assigned_to,
        "result": result,
        "note": note,
        "created_at": created_at,
        "updated_at": updated_at,
    }

