async def operator_head_brain_run_data(
    owner_id,
    days=1,
    platform="tiktok",
    limit=8,
    topic="",
    execute=False,
    safe_mode=True,
    max_steps=1,
    include_growth=True,
    execute_growth=False,
    include_context=True,
    include_prompt=True,
):
    days = max(1, min(safe_int(days, 1), 30))
    limit = max(3, min(safe_int(limit, 8), 20))
    max_steps = max(1, min(safe_int(max_steps, 1), 5))
    platform = (platform or "tiktok").lower()
    topic = (topic or "").strip()
    before = operator_head_brain_cockpit_data(owner_id, days=max(7, days), platform=platform, limit=limit)
    cycle = await operator_daily_cycle_data(
        owner_id,
        days=days,
        platform=platform,
        limit=limit,
        topic=topic,
        max_steps=max_steps,
        execute=execute,
        safe_mode=safe_mode,
        include_context=include_context,
        include_prompt=include_prompt,
    )
    cycle_job_ids = extract_operator_job_ids(cycle, limit=limit)
    worker_autorun = await operator_worker_autorun_data(
        owner_id,
        job_ids=cycle_job_ids,
        limit=min(limit, 8),
        max_tasks=min(max(12, max_steps * max(limit, 1) * 10), 40),
        execute=bool(execute and safe_mode),
    ) if cycle_job_ids else {"ok": True, "execute": bool(execute), "completed": [], "pending_external": [], "next_video_work_orders": {"orders": []}}
    after = operator_head_brain_cockpit_data(owner_id, days=max(7, days), platform=platform, limit=limit)
    video_work_orders = operator_video_work_orders_data(
        owner_id,
        job_ids=cycle_job_ids,
        limit=min(limit, 8),
        tool="claude",
    ) if cycle_job_ids else {"ok": True, "count": 0, "job_ids": [], "orders": []}
    worker_next = operator_worker_next_summary(
        owner_id,
        job_ids=cycle_job_ids,
        limit=min(limit, 8),
        tool="",
    ) if cycle_job_ids else []
    growth_loop = await operator_growth_loop_data(
        owner_id,
        days=max(7, days),
        platform=platform,
        limit=min(limit, 8),
        execute=bool(execute and execute_growth),
        build=True,
        duration=45,
        per_affiliate_limit=2,
    ) if include_growth else {"ok": True, "skipped": True, "reason": "include_growth_false"}
    first_order = ((video_work_orders.get("orders") or [None])[0]) or {}
    order_job_ids = ",".join(str(jid) for jid in (video_work_orders.get("job_ids") or cycle_job_ids)[:8])
    video_orders_cmd = f"/video_work_orders jobs={order_job_ids} tool=claude" if order_job_ids else "/video_work_orders tool=claude"
    video_orders_api = f"/api/operator/video-work-orders?job_ids={order_job_ids}&tool=claude" if order_job_ids else "/api/operator/video-work-orders?tool=claude"
    created_jobs = []
    for step in (cycle.get("steps") or []):
        payloads = [step.get("result") or {}]
        nested = (step.get("result") or {}).get("result")
        if isinstance(nested, dict):
            payloads.append(nested)
        for payload in payloads:
            for job in (payload.get("created_jobs") or []):
                if isinstance(job, dict) and job.get("job_id") not in {item.get("job_id") for item in created_jobs}:
                    created_jobs.append(job)
    return {
        "ok": True,
        "generated_at": now_text(),
        "mode": "EXECUTE" if execute else "PREVIEW",
        "safe_mode": bool(safe_mode),
        "platform": platform,
        "topic": topic,
        "max_steps": max_steps,
        "before": {
            "level": before.get("level"),
            "decision": before.get("decision"),
            "score": before.get("score"),
            "admin_next": before.get("admin_next"),
        },
        "cycle": cycle,
        "after": {
            "level": after.get("level"),
            "decision": after.get("decision"),
            "score": after.get("score"),
            "admin_next": after.get("admin_next"),
        },
        "executed_count": int(cycle.get("executed_count") or 0),
        "autorun_completed_count": int(worker_autorun.get("completed_count") or 0),
        "claimed_tasks": cycle.get("claimed_tasks") or [],
        "created_jobs": created_jobs,
        "worker_handoff": {
            "job_ids": cycle_job_ids,
            "worker_next": worker_next,
            "video_work_orders": video_work_orders,
            "autorun": worker_autorun,
            "first_order": {
                "job_id": first_order.get("job_id"),
                "task_id": first_order.get("task_id"),
                "video_brief": (first_order.get("telegram") or {}).get("video_brief"),
                "worker_pack": (first_order.get("telegram") or {}).get("worker_pack"),
                "compose_video": (first_order.get("telegram") or {}).get("compose_video"),
                "review_video": (first_order.get("telegram") or {}).get("review_video"),
            } if first_order else {},
            "claude_instruction": (
                "Đọc video_work_orders.orders theo thứ tự. Với mỗi order: tạo video/output thật theo worker_prompt, "
                "upload/complete vào upload_url hoặc complete_url, sau đó dừng ở review_video/approve_publish để admin duyệt."
            ),
        },
        "growth_loop": growth_loop,
        "stop_reason": cycle.get("stop_reason"),
        "next": {
            "head_brain": f"/head_brain days=30 platform={platform} limit={limit}",
            "preview": f"/head_run execute=0 platform={platform} max={max_steps}",
            "execute": f"/head_run execute=1 platform={platform} max={max_steps}",
            "execute_with_growth": f"/head_run execute=1 growth=1 platform={platform} max={max_steps}",
            "worker": "/worker_intake claim=0 include_prompt=1",
            "worker_autorun": f"/worker_autorun jobs={order_job_ids} execute=1" if order_job_ids else "/worker_autorun execute=1",
            "video_work_orders": video_orders_cmd,
            "publish": f"/publish_cockpit platform={platform} limit={limit}",
            "growth_loop": f"/growth_loop days={max(7, days)} platform={platform} limit={min(limit, 8)} execute={1 if execute_growth else 0}",
            "api_worker_autorun": "/api/operator/worker-autorun",
            "api_video_work_orders": video_orders_api,
        },
        "rule": "Head run dùng safe daily cycle và growth loop. Nó có thể launch/claim task/scale khi safe; gặp setup/review/publish/manual gate thì dừng và trả lệnh cho admin.",
    }

def operator_dispatch_preview_data(owner_id, days=30, platform="tiktok", limit=8):
    days = max(1, min(int(days or 30), 180))
    limit = max(3, min(int(limit or 8), 20))
    platform = (platform or "tiktok").lower()
    next_run = operator_next_run_data(owner_id, days=days, platform=platform, limit=limit)
    focus_job_id = int(((next_run.get("state") or {}).get("focus_job_id") or 0))
    pipeline = operator_pipeline_pack_data(owner_id, job_id=focus_job_id, days=days, platform=platform, limit=limit) if focus_job_id else operator_pipeline_pack_data(owner_id, job_id=0, days=days, platform=platform, limit=limit)
    worker_next = (pipeline.get("worker_next") or {}) if pipeline else {}
    task = worker_next.get("next_task") or {}
    mode = next_run.get("mode") or pipeline.get("pipeline_state") or "UNKNOWN"
    action = {
        "kind": "observe",
        "safe_to_execute": False,
        "reason": "Không có bước tự động an toàn rõ ràng.",
        "api": next_run.get("api") or {},
        "telegram": next_run.get("telegram_command") or "/operator_next_run",
    }
    if task.get("id"):
        action = {
            "kind": "claim_task",
            "safe_to_execute": True,
            "reason": "Có task queued/waiting; claim chỉ chuyển task sang working và trả prompt_pack, chưa publish.",
            "task_id": int(task.get("id") or 0),
            "job_id": int(task.get("job_id") or focus_job_id or 0),
            "api": {"method": "GET", "url": f"/api/operator/tasks/claim?job_id={int(task.get('job_id') or focus_job_id or 0)}&include_context=1&include_prompt=1"},
            "telegram": f"/task_prompt id={int(task.get('id') or 0)}",
        }
    elif mode in {"SETUP", "SETUP_REQUIRED"}:
        action = {
            "kind": "setup_required",
            "safe_to_execute": False,
            "reason": "Còn blocker cấu hình; cần admin/Railway/API key/kênh/link trước khi tự động chạy.",
            "api": {"method": "GET", "url": "/api/operator/goal-audit"},
            "telegram": "/goal_audit",
        }
    elif mode in {"NEEDS_ADMIN_APPROVAL", "READY_TO_QUEUE"}:
        action = {
            "kind": "needs_admin_review",
            "safe_to_execute": False,
            "reason": "Video/job cần review và approve của admin trước khi queue publish.",
            "api": {"method": "GET", "url": f"/api/operator/jobs/{focus_job_id}/review-video"},
            "telegram": f"/review_video job={focus_job_id} send=1",
        }
    elif mode in {"PUBLISH", "PUBLISHER_NEEDED", "READY_TO_PUBLISH"}:
        action = {
            "kind": "publish_handoff",
            "safe_to_execute": False,
            "reason": "Publish cần adapter/publisher gate; manual/API chính thức tùy platform.",
            "api": {"method": "POST", "url": "/api/operator/publisher/run"},
            "telegram": "/publisher_run platform=tiktok mode=api hoặc /publisher_handoff queue=<QUEUE_ID>",
        }
    elif mode in {"LAUNCH"}:
        action = {
            "kind": "launch_suggested",
            "safe_to_execute": False,
            "reason": "Chưa có job/task active; admin hoặc commander nên launch với topic cụ thể.",
            "api": {"method": "POST", "url": "/api/operator/launch"},
            "telegram": f"/operator_launch topic=công nghệ AI platform={platform} channel=all limit=3 build=1",
        }
    return {
        "ok": True,
        "generated_at": now_text(),
        "mode": mode,
        "days": days,
        "platform": platform,
        "focus_job_id": focus_job_id,
        "dispatch_action": action,
        "next_run": next_run,
        "pipeline": {
            "state": pipeline.get("pipeline_state") if pipeline else "NONE",
            "focus_job_id": pipeline.get("focus_job_id") if pipeline else 0,
            "next_action": pipeline.get("next_action") if pipeline else {},
            "worker_next": worker_next,
        },
        "rule": "Dispatcher chỉ tự claim task khi có queued/waiting task. Review, approve và publish vẫn cần gate riêng để không đăng nhầm.",
    }

def operator_dispatch_execute_data(owner_id, days=30, platform="tiktok", limit=8, claim_task=True, include_context=True, include_prompt=True):
    preview = operator_dispatch_preview_data(owner_id, days=days, platform=platform, limit=limit)
    action = preview.get("dispatch_action") or {}
    result = {"executed": False, "kind": action.get("kind"), "message": action.get("reason") or "not_executed"}
    if action.get("kind") == "claim_task" and action.get("safe_to_execute") and claim_task:
        result = claim_operator_task_payload(
            job_id=int(action.get("job_id") or 0),
            tool="",
            include_context=include_context,
            include_prompt=include_prompt,
        )
        result["executed"] = bool(result.get("task"))
        result["kind"] = "claim_task"
    return {
        "ok": True,
        "executed": bool(result.get("executed")),
        "preview": preview,
        "result": result,
        "after_done": "/api/operator/dispatch hoặc /operator_dispatch để lấy bước kế tiếp.",
    }

def operator_run_cycle_data(owner_id, days=30, platform="tiktok", limit=8, max_steps=3, execute=False, claim_task=True, include_context=True, include_prompt=True):
    days = max(1, min(int(days or 30), 180))
    limit = max(3, min(int(limit or 8), 20))
    max_steps = max(1, min(int(max_steps or 3), 10))
    platform = (platform or "tiktok").lower()
    steps = []
    stop_reason = "max_steps_reached"
    for index in range(1, max_steps + 1):
        preview = operator_dispatch_preview_data(owner_id, days=days, platform=platform, limit=limit)
        action = preview.get("dispatch_action") or {}
        step = {
            "step": index,
            "mode": preview.get("mode"),
            "action": action,
            "executed": False,
            "result": None,
        }
        if not action.get("safe_to_execute"):
            stop_reason = f"gate:{action.get('kind') or 'not_safe'}"
            steps.append(step)
            break
        if action.get("kind") != "claim_task":
            stop_reason = f"unsupported_safe_action:{action.get('kind') or 'unknown'}"
            steps.append(step)
            break
        if not execute or not claim_task:
            stop_reason = "preview_only"
            steps.append(step)
            break
        result = operator_dispatch_execute_data(
            owner_id,
            days=days,
            platform=platform,
            limit=limit,
            claim_task=claim_task,
            include_context=include_context,
            include_prompt=include_prompt,
        )
        step["executed"] = bool(result.get("executed"))
        step["result"] = result.get("result")
        steps.append(step)
        if not result.get("executed"):
            stop_reason = "dispatch_not_executed"
            break
    claimed_tasks = []
    for step in steps:
        result = step.get("result") or {}
        task = result.get("task") or {}
        if task:
            claimed_tasks.append({
                "task_id": task.get("id"),
                "job_id": task.get("job_id"),
                "task_type": task.get("task_type"),
                "tool": task.get("tool"),
                "has_prompt_pack": bool(result.get("prompt_pack")),
                "submit_url": result.get("submit_url"),
                "upload_url": result.get("upload_url"),
                "acceptance_url": result.get("acceptance_url"),
            })
    return {
        "ok": True,
        "generated_at": now_text(),
        "execute": bool(execute),
        "platform": platform,
        "days": days,
        "max_steps": max_steps,
        "steps": steps,
        "claimed_tasks": claimed_tasks,
        "stop_reason": stop_reason,
        "next": {
            "dispatch": "/api/operator/dispatch",
            "run_cycle": "/api/operator/run-cycle",
            "telegram": "/operator_cycle execute=1 max=3",
        },
        "rule": "Run cycle chỉ lặp các dispatch action safe_to_execute=claim_task. Nó không render giả, không approve và không publish; gặp gate là dừng.",
    }

def get_production_job(job_id, owner_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT pj.id, pj.calendar_id, pj.campaign_id, pj.channel_id, pj.affiliate_id, pj.platform, pj.topic,
                  pj.stage, pj.status, pj.operator_note, pj.brief_text, pj.asset_url, pj.publish_url,
                  sc.channel_name, sc.account_label, al.network, al.product_name, al.url
        FROM production_jobs pj
        LEFT JOIN social_channels sc ON sc.id = pj.channel_id
        LEFT JOIN affiliate_links al ON al.id = pj.affiliate_id
        WHERE pj.id=? AND pj.owner_id=?""",
        (job_id, str(owner_id))
    )
    row = c.fetchone()
    conn.close()
    return row

def update_production_job(job_id, owner_id, stage=None, status=None, note=None, asset_url=None, publish_url=None):
    updates = []
    params = []
    if stage:
        updates.append("stage=?")
        params.append(stage)
    if status:
        updates.append("status=?")
        params.append(status)
    if note is not None:
        updates.append("operator_note=?")
        params.append(note)
    if asset_url is not None:
        updates.append("asset_url=?")
        params.append(asset_url)
    if publish_url is not None:
        updates.append("publish_url=?")
        params.append(publish_url)
    updates.append("updated_at=?")
    params.append(now_text())
    params.extend([job_id, str(owner_id)])
    conn = db_connect()
    c = conn.cursor()
    c.execute(f"UPDATE production_jobs SET {', '.join(updates)} WHERE id=? AND owner_id=?", params)
    changed = c.rowcount
    conn.commit()
    conn.close()
    return changed > 0

def add_production_asset(owner_id, job_id, asset_type, url="", file_id="", note="", local_path="", content_type="", filename=""):
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, None
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO production_assets
        (owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at)
        VALUES (?,?,?,?,?,?,?,?,?,?)""",
        (str(owner_id), job_id, asset_type, url, file_id, note, local_path, content_type, filename, now_text())
    )
    asset_id = c.lastrowid
    conn.commit()
    conn.close()
    if url:
        update_production_job(job_id, owner_id, asset_url=url)
    return True, asset_id

def get_production_asset(owner_id, asset_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at
        FROM production_assets
        WHERE owner_id=? AND id=?""",
        (str(owner_id), int(asset_id))
    )
    row = c.fetchone()
    conn.close()
    return row

def latest_production_asset(owner_id, job_id, asset_type=""):
    rows = list_production_assets(owner_id, job_id, limit=80)
    asset_type = (asset_type or "").lower()
    for row in rows:
        aid, row_type, url, file_id, note, created_at = row
        row_type_l = (row_type or "").lower()
        if asset_type and row_type_l != asset_type:
            continue
        if row_type_l in {"final_video", "raw_video", "voice", "audio", "thumbnail", "subtitle", "source"} or not asset_type:
            return get_production_asset(owner_id, aid)
    return None

def list_production_asset_records(owner_id, job_id, asset_type="", limit=200):
    conn = db_connect()
    c = conn.cursor()
    asset_type = (asset_type or "").lower().strip()
    if asset_type:
        c.execute(
            """SELECT id, owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at
            FROM production_assets
            WHERE owner_id=? AND job_id=? AND LOWER(COALESCE(asset_type,''))=?
            ORDER BY id ASC LIMIT ?""",
            (str(owner_id), int(job_id), asset_type, int(limit))
        )
    else:
        c.execute(
            """SELECT id, owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at
            FROM production_assets
            WHERE owner_id=? AND job_id=?
            ORDER BY id ASC LIMIT ?""",
            (str(owner_id), int(job_id), int(limit))
        )
    rows = c.fetchall()
    conn.close()
    return rows

def safe_asset_local_path(asset_row):
    if not asset_row:
        return ""
    _aid, _owner_id, _job_id, _asset_type, _url, _file_id, _note, local_path, _content_type, _filename, _created_at = asset_row
    if not local_path:
        return ""
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    abs_path = os.path.abspath(local_path)
    if os.path.commonpath([upload_root, abs_path]) != upload_root or not os.path.exists(abs_path):
        return ""
    return abs_path

def asset_scene_sort_key(asset_row):
    aid, _owner_id, _job_id, _asset_type, _url, _file_id, note, local_path, _content_type, filename, _created_at = asset_row
    text = f"{note or ''} {filename or ''} {local_path or ''}"
    match = re.search(r"(?:scene|sc|cảnh|canh)[_ :=-]*(\d+)", text, re.IGNORECASE)
    return (int(match.group(1)) if match else int(aid or 0), int(aid or 0))

def scene_number_from_text(text, default=0):
    text = str(text or "")
    patterns = [
        r'"scene"\s*:\s*(\d+)',
        r"'scene'\s*:\s*(\d+)",
        r"(?:scene|sc|cảnh|canh)[_ :=-]*(\d+)",
    ]
    for pattern in patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            return int(match.group(1))
    return int(default or 0)

def scene_number_from_asset(asset_row, default=0):
    if not asset_row:
        return int(default or 0)
    aid, _owner_id, _job_id, _asset_type, _url, _file_id, note, local_path, _content_type, filename, _created_at = asset_row
    return scene_number_from_text(f"{note or ''} {filename or ''} {local_path or ''}", default=default or aid)

def serialize_asset_record_for_worker(asset_row):
    if not asset_row:
        return None
    aid, _owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at = asset_row
    download_url = operator_asset_url(aid)
    return {
        "id": int(aid),
        "job_id": int(job_id or 0),
        "asset_type": asset_type or "",
        "url": url or "",
        "download_url": download_url,
        "file_id": file_id or "",
        "filename": filename or "",
        "content_type": content_type or "",
        "note": note or "",
        "created_at": created_at or "",
        "local_file_available": bool(local_path and safe_asset_local_path(asset_row)),
        "download_auth": "Authorization: Bearer <OPERATOR_API_TOKEN>",
    }

def latest_manifest_payload(owner_id, job_id):
    manifest_row = latest_production_manifest(owner_id, job_id)
    if not manifest_row:
        return None, {}
    try:
        manifest = json.loads(manifest_row[4] or "{}")
    except Exception:
        manifest = {}
    return manifest_row, manifest

def operator_scene_pack_data(owner_id, job_id, scene=0, task_id=0):
    try:
        job_id = int(job_id or 0)
    except (TypeError, ValueError):
        job_id = 0
    try:
        scene = int(scene or 0)
    except (TypeError, ValueError):
        scene = 0
    try:
        task_id = int(task_id or 0)
    except (TypeError, ValueError):
        task_id = 0
    task = get_production_task(owner_id, task_id) if task_id else None
    if task:
        job_id = int(task[1] or job_id or 0)
        scene = int(task[5] or scene or 0)
    job = get_production_job(job_id, owner_id) if job_id else None
    if not job:
        return None
    base_url = (PUBLIC_BASE_URL or "https://<RAILWAY_DOMAIN>").rstrip("/")
    manifest_row, manifest = latest_manifest_payload(owner_id, job_id)
    manifest_scenes = manifest.get("scenes") or []
    manifest_by_scene = {int(item.get("scene") or idx + 1): item for idx, item in enumerate(manifest_scenes)}
    task_rows = [get_production_task(owner_id, row[0]) for row in list_production_tasks(owner_id, job_id=job_id, limit=240)]
    visual_tasks = [row for row in task_rows if row and (row[3] or "").lower() == "visual_scene"]
    visual_by_scene = {int(row[5] or 0): row for row in visual_tasks}
    scene_images = [
        row for row in list_production_asset_records(owner_id, job_id, asset_type="scene_image", limit=300)
        if scene_number_from_asset(row, 0)
    ]
    raw_videos = [
        row for row in list_production_asset_records(owner_id, job_id, limit=400)
        if (row[3] or "").lower() in {"raw_video", "scene_video", "video"} and scene_number_from_asset(row, 0)
    ]
    images_by_scene = {}
    raw_by_scene = {}
    for row in sorted(scene_images, key=asset_scene_sort_key):
        images_by_scene.setdefault(scene_number_from_asset(row, 0), []).append(row)
    for row in sorted(raw_videos, key=asset_scene_sort_key):
        raw_by_scene.setdefault(scene_number_from_asset(row, 0), []).append(row)
    scene_numbers = set(manifest_by_scene) | set(visual_by_scene) | set(images_by_scene) | set(raw_by_scene)
    if scene:
        scene_numbers = {scene}
    scene_items = []
    for scene_no in sorted(n for n in scene_numbers if n):
        scene_manifest = manifest_by_scene.get(scene_no) or {}
        visual_task = visual_by_scene.get(scene_no)
        latest_scene_image = (images_by_scene.get(scene_no) or [None])[-1]
        latest_raw_video = (raw_by_scene.get(scene_no) or [None])[-1]
        task_contract = operator_task_contract(visual_task[0], visual_task[3], job_id) if visual_task else {}
        scene_items.append({
            "scene": scene_no,
            "manifest": scene_manifest,
            "visual_task": serialize_operator_task(visual_task) if visual_task else None,
            "scene_image": serialize_asset_record_for_worker(latest_scene_image),
            "scene_images": [serialize_asset_record_for_worker(row) for row in images_by_scene.get(scene_no, [])],
            "raw_video": serialize_asset_record_for_worker(latest_raw_video),
            "raw_videos": [serialize_asset_record_for_worker(row) for row in raw_by_scene.get(scene_no, [])],
            "worker_prompt": {
                "image_prompt": scene_manifest.get("image_prompt") or "",
                "video_prompt": scene_manifest.get("video_prompt") or scene_manifest.get("visual_prompt") or "",
                "voice_line": scene_manifest.get("voice_line") or "",
                "caption": scene_manifest.get("caption") or scene_manifest.get("on_screen_text") or "",
                "duration": scene_manifest.get("duration_seconds") or "",
                "asset_needed": scene_manifest.get("asset_needed") or "",
            },
            "submit": {
                "complete_url": f"{base_url}{task_contract.get('complete_url', '/api/operator/tasks/<TASK_ID>/complete')}" if visual_task else "",
                "upload_url": f"{base_url}{task_contract.get('upload_url', '/api/operator/tasks/<TASK_ID>/upload')}" if visual_task else "",
                "asset_type": "raw_video",
                "note": f"scene={scene_no} from scene_pack",
            },
        })
    return {
        "ok": True,
        "generated_at": now_text(),
        "base_url": base_url,
        "job": serialize_production_job(job),
        "job_id": job_id,
        "manifest_id": int(manifest_row[0]) if manifest_row else 0,
        "scene_filter": scene,
        "scene_count": len(scene_items),
        "scenes": scene_items,
        "next": {
            "claim_visual_task": f"/worker_intake job={job_id} claim=1",
            "task_prompt": f"/task_prompt job={job_id}",
            "compose_when_raw_ready": f"/compose_video job={job_id} voice=1",
            "review_after_compose": f"/review_video job={job_id} send=1",
        },
        "rule": "Scene pack nối storyboard image -> video prompt -> raw_video upload. Worker phải tạo video riêng cho từng cảnh, không copy video tham khảo.",
    }

async def compose_job_video_with_ffmpeg(owner_id, job_id, include_voice=True, force=False):
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, "job_not_found", {}
    if not force:
        final_asset = latest_production_asset(owner_id, job_id, "final_video")
        if final_asset:
            aid, *_rest = final_asset
            return True, "already_has_final_video", {
                "asset_id": aid,
                "asset_url": operator_asset_url(aid),
                "review_url": f"/api/operator/jobs/{job_id}/review-video",
            }
    ffmpeg = shutil.which("ffmpeg")
    if not ffmpeg:
        return False, "ffmpeg_missing", {
            "message": "Server chưa có ffmpeg. Dockerfile cần cài apt-get install -y ffmpeg rồi redeploy.",
            "manual_next": f"/worker_pack job={job_id} tool=capcut",
        }
    video_types = {"raw_video", "scene_video", "video"}
    video_rows = [
        row for row in list_production_asset_records(owner_id, job_id, limit=300)
        if (row[3] or "").lower() in video_types and safe_asset_local_path(row)
    ]
    video_rows.sort(key=asset_scene_sort_key)
    video_paths = [safe_asset_local_path(row) for row in video_rows]
    if not video_paths:
        return False, "no_local_scene_videos", {
            "message": "Chưa có scene/raw video local để ghép. Worker cần upload file qua /api/operator/tasks/<TASK_ID>/upload.",
            "worker_intake": f"/api/operator/worker-intake?job_id={job_id}&claim=0&include_prompt=1",
        }
    voice_path = ""
    if include_voice:
        voice_candidates = [
            row for row in list_production_asset_records(owner_id, job_id, limit=120)
            if (row[3] or "").lower() in {"voice", "audio"} and safe_asset_local_path(row)
        ]
        if voice_candidates:
            voice_path = safe_asset_local_path(voice_candidates[-1])
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    job_dir = os.path.abspath(os.path.join(upload_root, f"job_{int(job_id)}"))
    if os.path.commonpath([upload_root, job_dir]) != upload_root:
        return False, "invalid_compose_path", {}
    os.makedirs(job_dir, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    concat_path = os.path.join(job_dir, f"compose_{stamp}.txt")
    output_path = os.path.abspath(os.path.join(job_dir, f"final_{stamp}.mp4"))
    if os.path.commonpath([upload_root, output_path]) != upload_root:
        return False, "invalid_output_path", {}
    with open(concat_path, "w", encoding="utf-8") as f:
        for path in video_paths:
            escaped = path.replace("\\", "/").replace("'", "'\\''")
            f.write(f"file '{escaped}'\n")
    vf = "scale=1080:1920:force_original_aspect_ratio=decrease,pad=1080:1920:(ow-iw)/2:(oh-ih)/2,setsar=1"
    cmd = [ffmpeg, "-y", "-f", "concat", "-safe", "0", "-i", concat_path]
    if voice_path:
        cmd += ["-i", voice_path, "-map", "0:v:0", "-map", "1:a:0", "-shortest"]
    cmd += ["-vf", vf, "-r", "30", "-c:v", "libx264", "-pix_fmt", "yuv420p"]
    if voice_path:
        cmd += ["-c:a", "aac", "-b:a", "128k"]
    else:
        cmd += ["-an"]
    cmd += [output_path]
    try:
        proc = await asyncio.create_subprocess_exec(
            *cmd,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=900)
    except asyncio.TimeoutError:
        return False, "ffmpeg_timeout", {"scene_count": len(video_paths)}
    except Exception as e:
        return False, "ffmpeg_exception", {"error": str(e)}
    if proc.returncode != 0 or not os.path.exists(output_path) or os.path.getsize(output_path) <= 0:
        return False, "ffmpeg_failed", {
            "returncode": proc.returncode,
            "stderr": truncate_text((stderr or b"").decode("utf-8", errors="ignore"), 1600),
        }
    ok, asset_id = add_production_asset(
        owner_id,
        job_id,
        "final_video",
        "",
        "",
        f"ffmpeg_compose scenes={len(video_paths)} voice={'yes' if voice_path else 'no'}",
        output_path,
        "video/mp4",
        os.path.basename(output_path),
    )
    if not ok:
        return False, "asset_save_failed", {}
    asset_url = operator_asset_url(asset_id)
    update_production_asset_url(owner_id, asset_id, asset_url)
    edit_tasks = [
        row for row in list_production_tasks(owner_id, job_id, limit=120)
        if (row[3] or "").lower() == "edit" and (row[7] or "").lower() not in {"ready", "done"}
    ]
    if edit_tasks:
        update_production_task(
            owner_id,
            int(edit_tasks[0][0]),
            status="ready",
            output_url=asset_url,
            note=f"ffmpeg_compose asset:{asset_id}",
            asset_type="final_video",
            record_asset=False,
        )
    update_production_job(job_id, owner_id, stage="review", status="ready", asset_url=asset_url, note=f"ffmpeg_compose final_video asset:{asset_id}")
    return True, "ok", {
        "asset_id": asset_id,
        "asset_url": asset_url,
        "local_path": output_path,
        "scene_count": len(video_paths),
        "voice_included": bool(voice_path),
        "review_url": f"/api/operator/jobs/{job_id}/review-video",
        "telegram_review": f"/review_video job={job_id} send=1",
    }

async def send_production_asset_to_chat(context: ContextTypes.DEFAULT_TYPE, chat_id: int, owner_id, asset_id: int):
    asset = get_production_asset(owner_id, asset_id)
    if not asset:
        return False, "asset_not_found"
    aid, _owner_id, job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at = asset
    caption = (
        f"📦 Asset #{aid} | job #{job_id}\n"
        f"Type: {asset_type or '-'}\n"
        f"File: {filename or '-'}\n"
        f"Note: {note or '-'}"
    )
    media_kind = (asset_type or "").lower()
    ctype = (content_type or "").lower()
    ext = os.path.splitext(filename or local_path or url or "")[1].lower()

    def is_video():
        return media_kind in {"final_video", "raw_video", "scene_video", "video", "source"} or ctype.startswith("video/") or ext in {".mp4", ".mov", ".mkv", ".webm"}

    def is_audio():
        return media_kind in {"voice", "audio"} or ctype.startswith("audio/") or ext in {".mp3", ".wav", ".m4a", ".ogg"}

    def is_photo():
        return media_kind in {"thumbnail", "image", "photo"} or ctype.startswith("image/") or ext in {".png", ".jpg", ".jpeg", ".webp"}

    async def send_opened_file(path):
        with open(path, "rb") as f:
            try:
                if is_video():
                    await context.bot.send_video(chat_id=chat_id, video=f, caption=caption)
                elif is_audio():
                    await context.bot.send_audio(chat_id=chat_id, audio=f, caption=caption)
                elif is_photo():
                    await context.bot.send_photo(chat_id=chat_id, photo=f, caption=caption)
                else:
                    await context.bot.send_document(chat_id=chat_id, document=f, filename=filename or os.path.basename(path), caption=caption)
            except Exception:
                f.seek(0)
                await context.bot.send_document(chat_id=chat_id, document=f, filename=filename or os.path.basename(path), caption=caption)

    if local_path:
        upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
        abs_path = os.path.abspath(local_path)
        if not abs_path.startswith(upload_root) or not os.path.exists(abs_path):
            return False, "local_file_missing"
        await send_opened_file(abs_path)
        return True, "sent_local"
    if file_id:
        if is_video():
            await context.bot.send_video(chat_id=chat_id, video=file_id, caption=caption)
        elif is_audio():
            await context.bot.send_audio(chat_id=chat_id, audio=file_id, caption=caption)
        elif is_photo():
            await context.bot.send_photo(chat_id=chat_id, photo=file_id, caption=caption)
        else:
            await context.bot.send_document(chat_id=chat_id, document=file_id, caption=caption)
        return True, "sent_file_id"
    if url:
        if is_video():
            await context.bot.send_video(chat_id=chat_id, video=url, caption=caption)
        elif is_audio():
            await context.bot.send_audio(chat_id=chat_id, audio=url, caption=caption)
        elif is_photo():
            await context.bot.send_photo(chat_id=chat_id, photo=url, caption=caption)
        else:
            await context.bot.send_message(chat_id=chat_id, text=f"{caption}\n\n{url}")
        return True, "sent_url"
    return False, "asset_has_no_media"

def update_production_asset_url(owner_id, asset_id, url):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        "UPDATE production_assets SET url=? WHERE owner_id=? AND id=?",
        (url, str(owner_id), int(asset_id))
    )
    changed = c.rowcount
    conn.commit()
    conn.close()
    return changed > 0

def safe_upload_filename(filename: str) -> str:
    base = os.path.basename(filename or "asset.bin")
    base = re.sub(r"[^A-Za-z0-9._-]+", "_", base).strip("._")
    return base[:120] or "asset.bin"

def operator_asset_url(asset_id: int) -> str:
    path = f"/api/operator/assets/{int(asset_id)}/file"
    base = (PUBLIC_BASE_URL or "").rstrip("/")
    return f"{base}{path}" if base else path

async def save_operator_upload_file(upload: UploadFile, job_id: int) -> tuple[bool, str, dict]:
    filename = safe_upload_filename(upload.filename)
    content_type = upload.content_type or "application/octet-stream"
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    job_dir = os.path.abspath(os.path.join(upload_root, f"job_{int(job_id)}"))
    if os.path.commonpath([upload_root, job_dir]) != upload_root:
        return False, "invalid_upload_path", {}
    os.makedirs(job_dir, exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    local_path = os.path.abspath(os.path.join(job_dir, f"{stamp}_{filename}"))
    max_bytes = max(1, MAX_OPERATOR_UPLOAD_MB) * 1024 * 1024
    total = 0
    try:
        with open(local_path, "wb") as f:
            while True:
                chunk = await upload.read(1024 * 1024)
                if not chunk:
                    break
                total += len(chunk)
                if total > max_bytes:
                    f.close()
                    try:
                        os.remove(local_path)
                    except Exception:
                        pass
                    return False, f"file_too_large_{MAX_OPERATOR_UPLOAD_MB}mb", {}
                f.write(chunk)
        if total <= 0:
            try:
                os.remove(local_path)
            except Exception:
                pass
            return False, "empty_file", {}
        return True, "ok", {
            "local_path": local_path,
            "filename": filename,
            "content_type": content_type,
            "size": total,
        }
    finally:
        await upload.close()

def crop_storyboard_grid_to_assets(owner_id, job_id, image_path, episode=1, rows=2, cols=5, start_scene=1, trim_percent=0.0, note=""):
    if Image is None:
        return False, "pillow_missing", {"message": "Server chưa có Pillow. requirements.txt cần có Pillow rồi redeploy."}
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, "job_not_found", {}
    upload_root = os.path.abspath(OPERATOR_UPLOAD_DIR or "operator_uploads")
    abs_path = os.path.abspath(image_path)
    if os.path.commonpath([upload_root, abs_path]) != upload_root or not os.path.exists(abs_path):
        return False, "invalid_storyboard_path", {}
    rows = max(1, min(int(rows or 2), 6))
    cols = max(1, min(int(cols or 5), 8))
    episode = max(1, int(episode or 1))
    start_scene = max(1, int(start_scene or 1))
    trim_percent = max(0.0, min(float(trim_percent or 0.0), 0.18))
    job_dir = os.path.abspath(os.path.join(upload_root, f"job_{int(job_id)}", "storyboard_scenes"))
    if os.path.commonpath([upload_root, job_dir]) != upload_root:
        return False, "invalid_crop_path", {}
    os.makedirs(job_dir, exist_ok=True)
    scene_assets = []
    try:
        with Image.open(abs_path) as img:
            img = img.convert("RGB")
            width, height = img.size
            cell_w = width / cols
            cell_h = height / rows
            stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            for r in range(rows):
                for c in range(cols):
                    scene_no = start_scene + (r * cols) + c
                    x0 = int(round(c * cell_w))
                    y0 = int(round(r * cell_h))
                    x1 = int(round((c + 1) * cell_w))
                    y1 = int(round((r + 1) * cell_h))
                    trim_x = int((x1 - x0) * trim_percent)
                    trim_y = int((y1 - y0) * trim_percent)
                    crop_box = (x0 + trim_x, y0 + trim_y, x1 - trim_x, y1 - trim_y)
                    scene_img = img.crop(crop_box)
                    filename = f"ep{episode:02d}_scene{scene_no:02d}_{stamp}.jpg"
                    scene_path = os.path.abspath(os.path.join(job_dir, filename))
                    if os.path.commonpath([upload_root, scene_path]) != upload_root:
                        return False, "invalid_scene_path", {}
                    scene_img.save(scene_path, "JPEG", quality=94, optimize=True)
                    metadata = {
                        "source": "storyboard_grid_crop",
                        "episode": episode,
                        "scene": scene_no,
                        "row": r + 1,
                        "column": c + 1,
                        "x": crop_box[0],
                        "y": crop_box[1],
                        "width": crop_box[2] - crop_box[0],
                        "height": crop_box[3] - crop_box[1],
                    }
                    ok, asset_id = add_production_asset(
                        owner_id,
                        job_id,
                        "scene_image",
                        "",
                        "",
                        f"storyboard_grid_crop {json.dumps(metadata, ensure_ascii=False)} {note or ''}".strip(),
                        scene_path,
                        "image/jpeg",
                        filename,
                    )
                    if not ok:
                        return False, "asset_save_failed", {"scene": scene_no}
                    asset_url = operator_asset_url(asset_id)
                    update_production_asset_url(owner_id, asset_id, asset_url)
                    metadata.update({"asset_id": asset_id, "asset_url": asset_url, "filename": filename})
                    scene_assets.append(metadata)
    except Exception as e:
        return False, "storyboard_crop_failed", {"error": str(e)}
    update_production_job(
        job_id,
        owner_id,
        stage="storyboard",
        status="working",
        note=f"storyboard_grid_cropped scenes={len(scene_assets)} episode={episode}",
    )
    return True, "ok", {
        "job_id": int(job_id),
        "episode": episode,
        "rows": rows,
        "cols": cols,
        "scene_count": len(scene_assets),
        "scenes": scene_assets,
        "next": {
            "worker_intake": f"/worker_intake job={job_id} claim=0",
            "task_prompt": f"/task_prompt job={job_id}",
            "compose_after_videos": f"/compose_video job={job_id} voice=1",
        },
        "rule": "scene_image assets là keyframe/storyboard riêng; worker dùng prompt pack để tạo raw_video tương ứng rồi compose final video.",
    }

def list_production_assets(owner_id, job_id, limit=20):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, asset_type, url, file_id, note, created_at
        FROM production_assets
        WHERE owner_id=? AND job_id=?
        ORDER BY id DESC LIMIT ?""",
        (str(owner_id), job_id, limit)
    )
    rows = c.fetchall()
    conn.close()
    return rows

def job_report_data(owner_id, job_id):
    job = get_production_job(job_id, owner_id)
    if not job:
        return None
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, asset_type, url, file_id, note, created_at
        FROM production_assets
        WHERE owner_id=? AND job_id=?
        ORDER BY id DESC LIMIT 8""",
        (str(owner_id), job_id)
    )
    assets = c.fetchall()
    c.execute(
        """SELECT id, mode, status, scheduled_at, publish_url, note, updated_at
        FROM publish_queue
        WHERE owner_id=? AND job_id=?
        ORDER BY id DESC LIMIT 5""",
        (str(owner_id), job_id)
    )
    queue_items = c.fetchall()
    c.execute(
        """SELECT event_type, COALESCE(SUM(value),0), COALESCE(SUM(amount),0), COUNT(*)
        FROM performance_events
        WHERE owner_id=? AND job_id=?
        GROUP BY event_type ORDER BY event_type""",
        (str(owner_id), job_id)
    )
    performance = c.fetchall()
    conn.close()
    return job, assets, queue_items, performance

def list_publish_queue_for_job(owner_id, job_id, limit=5):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, mode, status, scheduled_at, publish_url, note, updated_at
        FROM publish_queue
        WHERE owner_id=? AND job_id=?
        ORDER BY id DESC LIMIT ?""",
        (str(owner_id), job_id, limit)
    )
    rows = c.fetchall()
    conn.close()
    return rows

def production_readiness_data(owner_id, job_id):
    job = get_production_job(job_id, owner_id)
    if not job:
        return None
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    assets = list_production_assets(owner_id, job_id, limit=80)
    variants = list_creative_variants(owner_id, job_id, limit=80)
    manifests = list_production_manifests(owner_id, job_id, limit=5)
    tasks = list_production_tasks(owner_id, job_id=job_id, limit=120)
    queue_items = list_publish_queue_for_job(owner_id, job_id, limit=5)

    selected_variant = next((row for row in variants if (row[8] or "").lower() == "selected"), None)
    final_asset = next(
        (
            row for row in assets
            if (row[1] or "").lower() == "final_video" and (row[2] or row[3] or asset_url)
        ),
        None
    )
    raw_assets = [row for row in assets if (row[1] or "").lower() in {"raw_video", "scene_video", "source"}]
    voice_asset = next((row for row in assets if (row[1] or "").lower() in {"voice", "audio"} and (row[2] or row[3])), None)
    queue_open = next((row for row in queue_items if (row[2] or "").lower() in {"queued", "scheduled", "publishing", "published"}), None)
    blocked_tasks = [row for row in tasks if (row[7] or "").lower() == "blocked"]
    active_tasks = [row for row in tasks if (row[7] or "").lower() not in {"cancelled"}]

    def tasks_by_type(task_type):
        return [row for row in active_tasks if (row[3] or "").lower() == task_type]

    def tasks_done(task_rows):
        return bool(task_rows) and all((row[7] or "").lower() in {"ready", "done"} for row in task_rows)

    proof_tasks = tasks_by_type("proof_asset")
    visual_tasks = tasks_by_type("visual_scene")
    voice_tasks = tasks_by_type("voice")
    edit_tasks = tasks_by_type("edit")
    review_tasks = tasks_by_type("review")

    review_ok = (
        tasks_done(review_tasks)
        or (stage or "").lower() in {"review", "publish", "approved", "done"}
        and (status or "").lower() in {"ready", "approved", "queued", "published"}
    )
    final_ok = bool(final_asset or publish_url)
    checks = [
        ("brief", bool(brief), "Có brief sản xuất.", f"/video_job {job_id} hoặc /operator_next id={job_id} stage=script"),
        ("channel", bool(channel_id), "Có kênh/account để đăng.", "/channel_add platform=tiktok name=... account=..."),
        ("affiliate", bool(affiliate_url), "Có link affiliate gắn sản phẩm.", "/affiliate_add network=... product=... url=..."),
        ("creative_selected", bool(selected_variant), "Đã chọn creative variant thắng.", f"/creative_test job={job_id} n=5 rồi /creative_select id=<VARIANT_ID>"),
        ("manifest", bool(manifests), "Có production manifest.", f"/manifest job={job_id} duration=45"),
        ("tasks", bool(active_tasks), "Đã tách task sản xuất.", f"/task_plan job={job_id}"),
        ("proof_assets", not proof_tasks or tasks_done(proof_tasks) or final_ok, "Proof asset/screenshot/workflow đã sẵn sàng hoặc đã có final video.", f"/next_task job={job_id}"),
        ("visuals", tasks_done(visual_tasks) or bool(raw_assets) or final_ok, "Visual scene đã có output hoặc final video.", f"/next_task job={job_id}"),
        ("voice", tasks_done(voice_tasks) or bool(voice_asset) or final_ok, "Voice/audio đã có output hoặc final video.", f"/next_task job={job_id}"),
        ("edit_final", final_ok or tasks_done(edit_tasks), "Có final video hoặc edit task đã ready.", f"/next_task job={job_id}"),
        ("review", review_ok, "Đã qua review gate.", f"/review_gate job={job_id}"),
        ("queue_or_published", bool(queue_open or publish_url or (status or "").lower() == "published"), "Đã vào hàng đợi hoặc đã đăng.", f"/publish_pack job={job_id} rồi /approve_publish job={job_id} queue=1 mode=manual"),
    ]
    if blocked_tasks:
        checks.append(("blocked_tasks", False, f"Có {len(blocked_tasks)} task bị blocked.", f"/tasks job={job_id}"))

    missing = [row for row in checks if not row[1]]
    core_missing = [row for row in missing if row[0] != "queue_or_published"]
    approved_ok = (stage or "").lower() == "approved" and (status or "").lower() == "approved"
    publish_gate = {
        "can_approve": not core_missing,
        "can_queue": not core_missing and approved_ok,
        "approval_required": not approved_ok,
        "has_final_video": final_ok,
        "has_queue": bool(queue_open),
        "blocking": [
            {"key": key, "detail": detail, "next": next_cmd}
            for key, _ok, detail, next_cmd in core_missing
        ],
        "rule": "Queue publish chỉ mở sau khi đủ core checklist và job đã được approve qua review gate.",
    }
    if not core_missing and not queue_open and not publish_url and (status or "").lower() != "published":
        level = "READY_TO_QUEUE"
        next_action = f"/publish_pack job={job_id} rồi /approve_publish job={job_id} queue=1 mode=manual"
    elif not missing:
        level = "READY_TO_PUBLISH"
        next_action = f"/publish_queue hoặc /mark_published job={job_id} url=https://..."
    else:
        level = "BLOCKED"
        next_action = missing[0][3]

    return {
        "job": job,
        "assets": assets,
        "variants": variants,
        "manifests": manifests,
        "tasks": tasks,
        "queue_items": queue_items,
        "checks": checks,
        "missing": missing,
        "level": level,
        "next_action": next_action,
        "selected_variant": selected_variant,
        "final_asset": final_asset,
        "blocked_tasks": blocked_tasks,
        "publish_gate": publish_gate,
    }

def apply_worker_output_job_state(owner_id, job_id, task_id=0, task_type="", task_status="", asset_type="", note=""):
    status_l = (task_status or "").lower()
    asset_type_l = (asset_type or "").lower()
    task_type_l = (task_type or "").lower()
    if status_l == "blocked":
        update_production_job(job_id, owner_id, status="blocked", note=f"task_blocked:{task_id} {note or ''}".strip())
    elif status_l in {"ready", "done"}:
        if asset_type_l == "final_video" or task_type_l == "edit":
            update_production_job(job_id, owner_id, stage="review", status="ready", note=f"final_video_ready task:{task_id} {note or ''}".strip())
        elif task_type_l == "publish":
            update_production_job(job_id, owner_id, stage="publish", status="ready", note=f"publish_task_ready:{task_id} {note or ''}".strip())
        else:
            update_production_job(job_id, owner_id, status="working", note=f"task_ready:{task_id} {task_type_l or '-'} {note or ''}".strip())
    readiness = production_readiness_data(owner_id, job_id)
    return readiness

def _asset_has_media(asset_row):
    if not asset_row:
        return False
    if len(asset_row) >= 11:
        _aid, _owner_id, _job_id, _asset_type, url, file_id, _note, local_path, _content_type, _filename, _created_at = asset_row
        return bool(url or file_id or local_path)
    if len(asset_row) >= 6:
        _aid, _asset_type, url, file_id, _note, _created_at = asset_row
        return bool(url or file_id)
    return False

def _output_media_kind(text=""):
    value = (text or "").lower().split("?", 1)[0]
    ext = os.path.splitext(value)[1]
    if ext in {".mp4", ".mov", ".mkv", ".webm"}:
        return "video"
    if ext in {".mp3", ".wav", ".m4a", ".ogg"}:
        return "audio"
    if ext in {".png", ".jpg", ".jpeg", ".webp"}:
        return "image"
    if ext in {".srt", ".vtt", ".txt"}:
        return "text"
    return "unknown"

def operator_task_output_acceptance(owner_id, task_row, assets=None):
    if not task_row:
        return None
    tid, job_id, manifest_id, task_type, tool, scene_no, title, prompt, status, output_url, note, updated_at = task_row
    task_type_l = (task_type or "").lower()
    status_l = (status or "queued").lower()
    expected_asset = default_asset_type_for_task(task_type_l)
    assets = assets if assets is not None else list_production_assets(owner_id, job_id, limit=80)
    related_assets = []
    for row in assets:
        aid, asset_type, url, file_id, asset_note, created_at = row
        note_l = (asset_note or "").lower()
        type_l = (asset_type or "").lower()
        if f"task:{tid}" in note_l or f"api_task:{tid}" in note_l or f"api_upload_task:{tid}" in note_l:
            related_assets.append(row)
        elif output_url and url == output_url:
            related_assets.append(row)
        elif type_l == expected_asset and _asset_has_media(row):
            related_assets.append(row)
    has_media = bool(output_url) or any(_asset_has_media(row) for row in related_assets)
    media_kind = _output_media_kind(output_url)
    if media_kind == "unknown" and related_assets:
        media_kind = _output_media_kind((related_assets[0][2] or related_assets[0][3] or ""))

    checks = []
    checks.append({
        "key": "status_terminal",
        "ok": status_l in {"ready", "done", "blocked"},
        "detail": "Task đã có trạng thái kết thúc hoặc blocked rõ ràng." if status_l in {"ready", "done", "blocked"} else "Task chưa có output cuối.",
        "next": f"/task_handoff id={tid}",
    })
    if status_l == "blocked":
        checks.append({
            "key": "blocked_note",
            "ok": bool(note),
            "detail": "Blocked task có note lỗi/fallback." if note else "Blocked task cần note nêu lỗi, quota hoặc fallback đã thử.",
            "next": f"/task_set id={tid} status=blocked note=<LY_DO>",
        })
    elif task_type_l in {"proof_asset", "visual_scene", "voice", "edit", "publish"}:
        checks.append({
            "key": "media_present",
            "ok": has_media,
            "detail": "Có output_url hoặc asset upload thật." if has_media else "Thiếu output_url/file upload thật.",
            "next": f"/task_set id={tid} status=ready url=https://... hoặc upload /api/operator/tasks/{tid}/upload",
        })
    if task_type_l == "edit":
        checks.append({
            "key": "final_video_type",
            "ok": expected_asset == "final_video" and (media_kind in {"video", "unknown"}) and has_media,
            "detail": "Edit task trả final_video có media để review." if has_media else "Edit task phải trả final_video mp4/URL/file upload.",
            "next": f"/task_set id={tid} status=ready type=final_video url=https://... hoặc /asset_add job={job_id} type=final_video url=https://...",
        })
    if task_type_l == "voice":
        checks.append({
            "key": "voice_media",
            "ok": has_media and media_kind in {"audio", "unknown"},
            "detail": "Voice task có audio output." if has_media else "Voice task cần mp3/wav hoặc file upload.",
            "next": f"/task_set id={tid} status=ready type=voice url=https://...",
        })
    blocking = [item for item in checks if not item["ok"]]
    accepted = not blocking and status_l in {"ready", "done"}
    return {
        "task_id": tid,
        "job_id": job_id,
        "task_type": task_type,
        "tool": tool,
        "expected_asset_type": expected_asset,
        "status": status_l,
        "output_url": output_url,
        "media_kind": media_kind,
        "related_assets": [
            {"id": aid, "asset_type": asset_type, "url": url, "file_id": file_id, "note": asset_note, "created_at": created_at}
            for aid, asset_type, url, file_id, asset_note, created_at in related_assets[:8]
        ],
        "accepted": accepted,
        "checks": checks,
        "blocking": blocking,
        "next": (blocking[0]["next"] if blocking else f"/job_ready job={job_id}"),
    }

def operator_output_acceptance_data(owner_id, job_id=0, task_id=0):
    task = get_production_task(owner_id, int(task_id)) if int(task_id or 0) else None
    if task:
        job_id = int(task[1] or 0)
    job = get_production_job(int(job_id or 0), owner_id) if int(job_id or 0) else None
    if not job:
        return {"ok": False, "reason": "job_not_found", "job_id": int(job_id or 0), "task_id": int(task_id or 0)}
    job_id = int(job[0])
    assets = list_production_assets(owner_id, job_id, limit=100)
    tasks = [task] if task else [get_production_task(owner_id, row[0]) for row in list_production_tasks(owner_id, job_id=job_id, limit=120)]
    task_reports = [operator_task_output_acceptance(owner_id, row, assets=assets) for row in tasks if row]
    readiness = production_readiness_data(owner_id, job_id)
    final_asset = (readiness or {}).get("final_asset")
    blocking = []
    if not task_reports:
        blocking.append({"key": "tasks", "detail": "Job chưa có task để worker thực hiện.", "next": f"/task_plan job={job_id}"})
    for report in task_reports:
        for item in report.get("blocking") or []:
            blocking.append({"task_id": report.get("task_id"), **item})
    requires_final_video = not task or (task and (task[3] or "").lower() == "edit")
    if requires_final_video and not final_asset and not any((report.get("expected_asset_type") == "final_video" and report.get("accepted")) for report in task_reports):
        blocking.append({"key": "final_video", "detail": "Chưa có final_video để review/publish.", "next": f"/worker_pack job={job_id}"})
    accepted = not blocking
    return {
        "ok": True,
        "generated_at": now_text(),
        "job": serialize_production_job(job),
        "task_id": int(task_id or 0),
        "accepted": accepted,
        "level": "ACCEPTED_FOR_REVIEW" if accepted else "NEEDS_WORKER_OUTPUT",
        "task_reports": task_reports,
        "final_asset": {
            "id": final_asset[0],
            "asset_type": final_asset[1],
            "url": final_asset[2],
            "file_id": final_asset[3],
            "note": final_asset[4],
            "created_at": final_asset[5],
        } if final_asset else None,
        "blocking": blocking,
        "next": (blocking[0]["next"] if blocking else f"/review_video job={job_id} send=1"),
        "api": {
            "complete_task": "/api/operator/tasks/<TASK_ID>/complete",
            "upload_task": "/api/operator/tasks/<TASK_ID>/upload",
            "review_video": f"/api/operator/jobs/{job_id}/review-video",
            "job_ready": f"/api/operator/jobs/{job_id}/ready",
        },
        "rule": "Worker output chỉ được accepted khi status/output/asset khớp task. Không publish khi chưa có final_video review được.",
    }

def approve_publish_job(owner_id, job_id, note="", queue=True, mode="manual", scheduled_at=""):
    readiness = production_readiness_data(owner_id, job_id)
    if not readiness:
        return False, "job_not_found", {}
    blocking = [row for row in readiness["missing"] if row[0] != "queue_or_published"]
    if blocking:
        return False, "not_ready", {
            "missing": [
                {"key": key, "detail": detail, "next": next_cmd}
                for key, _ok, detail, next_cmd in blocking
            ],
            "next_action": blocking[0][3],
        }
    update_production_job(
        job_id,
        owner_id,
        stage="approved",
        status="approved",
        note=note or "approved_publish_gate",
    )
    queue_id = 0
    queued = False
    if queue:
        ok, result = create_publish_queue_item(owner_id, job_id, mode=mode or "manual", scheduled_at=scheduled_at or "", note=note or "approved_publish_gate")
        queued = bool(ok)
        queue_id = result if ok else 0
        if not ok:
            return False, str(result), {"approved": True, "queued": False}
    return True, "approved", {"approved": True, "queued": queued, "queue_id": queue_id}

def approve_ready_jobs(owner_id, limit=3, mode="manual", scheduled_at="", note="admin_batch_approve_ready"):
    limit = max(1, min(int(limit or 3), 10))
    mode = (mode or "manual").lower()
    if mode not in {"manual", "api"}:
        return False, "invalid_mode", {"approved": [], "skipped": []}
    approved = []
    skipped = []
    for jid, stage, status, platform, topic, channel_name, product_name, updated_at in list_production_jobs(owner_id, limit=max(limit * 4, 20)):
        if len(approved) >= limit:
            break
        if (status or "").lower() in {"published", "done", "cancelled"}:
            continue
        summary = build_video_review_summary(owner_id, jid)
        decision = (summary or {}).get("review_decision") or {}
        if decision.get("decision") != "READY_FOR_ADMIN_APPROVAL":
            skipped.append({
                "job_id": jid,
                "topic": topic,
                "platform": platform,
                "reason": decision.get("decision") or "not_ready",
                "next": decision.get("next_telegram") or ((summary or {}).get("commands") or {}).get("fix_next") or "",
            })
            continue
        ok, reason, info = approve_publish_job(
            owner_id,
            jid,
            note=note,
            queue=True,
            mode=mode,
            scheduled_at=scheduled_at,
        )
        if ok:
            approved.append({
                "job_id": jid,
                "queue_id": info.get("queue_id") or 0,
                "topic": topic,
                "platform": platform,
                "channel_name": channel_name,
                "product_name": product_name,
                "mode": mode,
            })
        else:
            skipped.append({
                "job_id": jid,
                "topic": topic,
                "platform": platform,
                "reason": reason,
                "next": (info or {}).get("next_action", ""),
                "missing": (info or {}).get("missing", []),
            })
    return True, "ok", {
        "approved": approved,
        "skipped": skipped,
        "limit": limit,
        "mode": mode,
        "scheduled_at": scheduled_at,
        "rule": "Chỉ batch approve các job có review_decision READY_FOR_ADMIN_APPROVAL; vẫn cần admin gọi lệnh này.",
    }

def create_creative_variant(owner_id, job_id, variant_label, hook="", script_angle="", caption="", cta="", hashtags="", creative_score=0, note=""):
    job = get_production_job(job_id, owner_id)
    if not job:
        return False, None
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """INSERT INTO creative_variants
        (owner_id, job_id, variant_label, hook, script_angle, caption, cta, hashtags, creative_score, status, note, created_at, selected_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            str(owner_id), job_id, variant_label, hook, script_angle, caption, cta, hashtags,
            int(creative_score or 0), "draft", note, now_text(), None
        )
    )
    variant_id = c.lastrowid
    conn.commit()
    conn.close()
    return True, variant_id

def list_creative_variants(owner_id, job_id, limit=20):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT id, variant_label, hook, script_angle, caption, cta, hashtags, creative_score, status, note, created_at, selected_at
        FROM creative_variants
        WHERE owner_id=? AND job_id=?
        ORDER BY creative_score DESC, id ASC
        LIMIT ?""",
        (str(owner_id), job_id, limit)
    )
    rows = c.fetchall()
