def build_publish_pack_prompt(job):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    related = list_related_affiliate_links(ADMIN_ID, affiliate_id=affiliate_id, niche=topic or product_name or "", limit=8) if affiliate_id else []
    related_note = format_related_affiliate_links(related, max_items=6)
    pattern = select_video_pattern(job, 45)
    platform_key = (platform or "").lower()
    if platform_key in {"onlyfans", "of"}:
        platform_rule = (
            "OnlyFans: chỉ dùng người thật có consent rõ ràng hoặc nhân vật AI tự tạo; tất cả nhân vật phải đủ 18 tuổi; "
            "không mạo danh người thật/creator khác; không dùng ảnh người khác để gợi dục hoặc lừa đảo."
        )
    elif platform_key in {"tiktok", "tik tok"}:
        platform_rule = (
            "TikTok: hook nhanh, caption gọn, affiliate disclosure rõ, tránh claim tài chính quá mức, tránh spam link trong mô tả; "
            "nếu cần nhiều link thì đưa link chính ở bio/mô tả và link liên quan ở comment ghim/status."
        )
    elif platform_key in {"facebook", "fb", "reels"}:
        platform_rule = (
            "Facebook/Reels: caption có ngữ cảnh, disclosure affiliate, link chính trong post/comment ghim, không bait tương tác giả tạo."
        )
    else:
        platform_rule = "Nền tảng bất kỳ: minh bạch affiliate, không spam, không mạo danh, không cam kết kết quả tài chính."
    return (
        "Bạn là AI Operator trưởng chuẩn bị gói đăng bài kiếm tiền cho TOAN AAS. "
        "Tạo nội dung đăng hợp pháp, không spam, không mạo danh, không cam kết thu nhập phi thực tế, "
        "không hướng dẫn né kiểm duyệt. Nếu nền tảng là OnlyFans hoặc có người mẫu/AI influencer thì chỉ dùng nhân vật tự tạo "
        "hoặc người thật có consent rõ ràng và đủ 18 tuổi.\n\n"
        f"Job ID: #{jid}\n"
        f"Nền tảng: {platform or '-'}\n"
        f"Kênh: {channel_name or channel_id or '-'} / account={account_label or 'main'}\n"
        f"Topic: {topic or '-'}\n"
        f"Affiliate: {network or '-'} - {product_name or '-'}\n"
        f"Affiliate URL: {affiliate_url or 'chưa có'}\n"
        f"Link liên quan để chèn caption/comment/status:\n{related_note or '-'}\n"
        f"Asset URL: {asset_url or 'chưa có'}\n"
        f"Publish URL hiện tại: {publish_url or 'chưa có'}\n"
        f"Ghi chú: {note or '-'}\n\n"
        f"Video pattern:\n{format_video_pattern_for_prompt(pattern)}\n\n"
        f"Luật nền tảng:\n{platform_rule}\n\n"
        f"Brief/job context:\n{brief or 'Chưa có brief'}\n\n"
        "Trả về tiếng Việt theo format:\n"
        "1. Caption chính theo nền tảng.\n"
        "2. Caption ngắn A/B.\n"
        "3. Hashtag.\n"
        "4. CTA và vị trí gắn link affiliate chính.\n"
        "5. Link liên quan nên đưa vào comment ghim/status/mô tả, chỉ chọn link thật sự liên quan.\n"
        "6. Checklist trước khi đăng.\n"
        "7. Kế hoạch đo hiệu quả sau đăng: publish_url, view, click, order/lead, revenue, cost bằng /mark_published và /performance_add."
    )

def build_static_publish_pack(job, owner_id=ADMIN_ID):
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    _bundle_ok, _bundle_reason, affiliate_bundle = build_affiliate_link_bundle(
        owner_id,
        affiliate_id=affiliate_id or 0,
        job_id=jid,
        brand=product_name or "",
        niche=topic or product_name or "",
        platform=platform or "social",
        limit=8,
    )
    pattern = select_video_pattern(job, 45)
    selected_references = select_reference_examples_for_job(owner_id, job, limit=3)
    related_links = affiliate_bundle.get("related_links", []) if affiliate_bundle else []
    primary_tracking_url = affiliate_tracking_url(affiliate_id, jid, f"{platform or 'social'}_primary") if affiliate_id else ""
    if affiliate_bundle and affiliate_bundle.get("primary"):
        primary_tracking_url = (affiliate_bundle["primary"].get("tracking") or {}).get("caption") or primary_tracking_url
    primary_display_url = primary_tracking_url or affiliate_url
    disclosure = "Có thể nhận hoa hồng affiliate nếu người xem mua/đăng ký qua link."
    caption = (
        f"{topic or product_name or 'Gợi ý sản phẩm/dịch vụ'}\n\n"
        f"Góc video: {pattern.get('name')} - {pattern.get('hook_formula')}\n"
        f"Link chính: {primary_display_url or 'chưa có'}\n"
        f"{disclosure}"
    )
    pinned_comment = ((affiliate_bundle or {}).get("placement_plan") or {}).get("pinned_comment") or ""
    if not pinned_comment and primary_display_url:
        pinned_comment = f"Link chính: {primary_display_url}"
    comment_pack = build_affiliate_comment_pack(owner_id, jid, max_comments=10, delay_seconds=30)
    checklist = [
        "Đã kiểm tra quyền hình ảnh/voice/nhạc.",
        "Đã ghi disclosure affiliate rõ ràng.",
        "Không hứa thu nhập/lãi suất/kết quả phê duyệt.",
        "Không mạo danh thương hiệu/người thật.",
        "Nếu nội dung người mẫu/OnlyFans: nhân vật tự tạo hoặc có consent, đủ 18 tuổi.",
        "Sau đăng ghi /mark_published và /performance_add.",
    ]
    return {
        "job_id": jid,
        "platform": platform,
        "channel_name": channel_name,
        "account_label": account_label,
        "topic": topic,
        "primary_affiliate": {
            "id": affiliate_id,
            "network": network,
            "product": product_name,
            "url": affiliate_url,
            "tracking_url": primary_tracking_url,
        },
        "related_links": related_links,
        "affiliate_bundle": affiliate_bundle,
        "video_pattern": pattern,
        "reference_examples": selected_references,
        "proof_assets_required": pattern.get("proof_assets_required") or [],
        "placement_plan": (affiliate_bundle or {}).get("placement_plan", {}),
        "comment_pack": comment_pack,
        "caption": caption,
        "pinned_comment": pinned_comment,
        "hashtags": "#review #affiliate #muasamthongminh #AI",
        "cta": "Xem link chính và các lựa chọn liên quan trong mô tả/comment ghim.",
        "disclosure": disclosure,
        "checklist": checklist,
        "performance_plan": {
            "after_publish": f"/mark_published job={jid} url=https://... views=0 clicks=0 note=...",
            "views": f"/performance_add job={jid} type=view value=<VIEWS>",
            "clicks": f"/performance_add job={jid} type=click value=<CLICKS>",
            "orders": f"/performance_add job={jid} type=order value=<ORDERS> amount=<REVENUE>",
            "revenue": f"/performance_add job={jid} type=revenue value=1 amount=<REVENUE>",
            "cost": f"/performance_add job={jid} type=cost value=1 amount=<COST>",
        },
    }

def build_distribution_pack(owner_id, job_id):
    job = get_production_job(job_id, owner_id)
    if not job:
        return None
    (
        jid, calendar_id, campaign_id, channel_id, affiliate_id, platform, topic, stage, status,
        note, brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    channel = get_social_channel(channel_id, owner_id) if channel_id else None
    readiness = "unknown"
    readiness_reason = "Không tìm thấy cấu hình kênh."
    publish_mode = "manual"
    if channel:
        readiness_rows = {row[0]: row for row in list_social_publish_readiness(owner_id)}
        readiness_row = readiness_rows.get(channel_id)
        if readiness_row:
            readiness, readiness_reason = channel_publish_readiness(readiness_row)
            publish_mode = readiness_row[5] or "manual"
    publish_pack = build_static_publish_pack(job, owner_id)
    comment_pack = publish_pack.get("comment_pack") or build_affiliate_comment_pack(owner_id, job_id)
    review = build_video_review_summary(owner_id, job_id)
    post_publish = build_post_publish_handoff(owner_id, job_id, days=30)
    bundle = publish_pack.get("affiliate_bundle") or {}
    placement = publish_pack.get("placement_plan") or bundle.get("placement_plan") or {}
    primary = bundle.get("primary") or {}
    tracking = primary.get("tracking") or {}
    source_prefix = f"{(platform or 'social').lower()}_job_{job_id}"
    channel_payload = None
    if channel:
        cid, ch_platform, ch_name, ch_account, focus, audience, slots, ch_status = channel
        channel_payload = {
            "id": cid,
            "platform": ch_platform,
            "channel_name": ch_name,
            "account_label": ch_account,
            "topic_focus": focus,
            "audience": audience,
            "posting_slots": slots,
            "status": ch_status,
            "publish_mode": publish_mode,
            "readiness": readiness,
            "readiness_reason": readiness_reason,
            "can_manual_publish": readiness in {"manual_ready", "api_ready", "manual_required"},
            "can_api_publish": readiness == "api_ready",
        }
    return {
        "ok": True,
        "generated_at": now_text(),
        "job": {
            "id": jid,
            "calendar_id": calendar_id,
            "campaign_id": campaign_id,
            "channel_id": channel_id,
            "affiliate_id": affiliate_id,
            "platform": platform,
            "topic": topic,
            "stage": stage,
            "status": status,
            "has_final_asset": bool(asset_url),
            "asset_url": asset_url,
            "publish_url": publish_url,
        },
        "channel": channel_payload,
        "affiliate": {
            "id": affiliate_id,
            "network": network,
            "product_name": product_name,
            "url": affiliate_url,
            "primary_tracking": tracking.get("caption") or publish_pack.get("primary_affiliate", {}).get("tracking_url", ""),
        },
        "publish_pack": publish_pack,
        "comment_pack": comment_pack,
        "placement_map": {
            "caption": tracking.get("caption") or publish_pack.get("primary_affiliate", {}).get("tracking_url", ""),
            "pinned_comment": placement.get("pinned_comment") or tracking.get("comment") or "",
            "status_or_story": tracking.get("status") or "",
            "bio_or_profile": tracking.get("bio") or "",
            "ads": tracking.get("ads") or "",
            "related_links": publish_pack.get("related_links", [])[:8],
            "disclosure": publish_pack.get("disclosure", ""),
        },
        "review_gate": {
            "decision": ((review or {}).get("review_decision") or {}).get("decision", "REVIEW_REQUIRED"),
            "can_auto_publish": bool(((review or {}).get("review_decision") or {}).get("can_auto_publish")),
            "missing_checks": (review or {}).get("missing_checks") or (review or {}).get("missing") or [],
            "next_command": (review or {}).get("next_command") or f"/review_video job={job_id} send=1",
        },
        "tracking_plan": {
            "source_prefix": source_prefix,
            "sources": {
                "caption": f"{source_prefix}_caption",
                "comment": f"{source_prefix}_comment",
                "status": f"{source_prefix}_status",
                "bio": f"{source_prefix}_bio",
                "ads": f"{source_prefix}_ads",
            },
            "events": ["view", "click", "lead", "order", "revenue", "cost"],
            "post_publish": (post_publish or {}).get("tracking_event_pack", {}),
        },
        "commands": {
            "telegram": {
                "worker_pack": f"/worker_pack job={job_id}",
                "review_video": f"/review_video job={job_id} send=1",
                "approve_publish": f"/approve_publish job={job_id} queue=1 mode=manual",
                "publish_pack": f"/publish_pack job={job_id}",
                "comment_pack": f"/comment_pack job={job_id} max=10 delay=30",
                "post_publish": f"/post_publish job={job_id}",
                "mark_published": f"/mark_published job={job_id} url=<PUBLISH_URL> views=0 clicks=0 note=manual",
                "performance_view": f"/performance_add job={job_id} type=view value=1 source={source_prefix}_caption",
                "performance_revenue": f"/performance_add job={job_id} type=revenue value=1 amount=<VND> source={source_prefix}_caption",
            },
            "api": {
                "worker_pack": f"/api/operator/jobs/{job_id}/worker-pack",
                "review_video": f"/api/operator/jobs/{job_id}/review-video",
                "approve_publish": f"/api/operator/jobs/{job_id}/approve",
                "publish_pack": f"/api/operator/jobs/{job_id}/publish-pack",
                "distribution_pack": f"/api/operator/jobs/{job_id}/distribution-pack",
                "comment_pack": f"/api/operator/jobs/{job_id}/comment-pack",
                "post_publish": f"/api/operator/jobs/{job_id}/post-publish",
                "performance": "/api/operator/performance",
            },
        },
        "rule": "Distribution pack là hợp đồng đăng và đo hiệu quả cho một job. Không publish tự động nếu review_gate chưa APPROVE hoặc channel không api_ready; manual/API đều phải giữ disclosure affiliate.",
    }

def build_video_review_summary(owner_id, job_id):
    job = get_production_job(job_id, owner_id)
    if not job:
        return None
    readiness = production_readiness_data(owner_id, job_id)
    pack = build_static_publish_pack(job, owner_id)
    assets = list_production_assets(owner_id, job_id, limit=80)
    final_asset = latest_production_asset(owner_id, job_id, "final_video")
    if not final_asset:
        final_asset = latest_production_asset(owner_id, job_id, "raw_video")
    (
        jid, _calendar_id, _campaign_id, _channel_id, _affiliate_id, platform, topic, stage, status,
        _note, _brief, asset_url, publish_url, channel_name, account_label, network, product_name, affiliate_url
    ) = job
    missing = [
        {"key": key, "detail": detail, "next": next_cmd}
        for key, ok, detail, next_cmd in (readiness.get("checks", []) if readiness else [])
        if not ok
    ]
    summary = {
        "job": {
            "id": jid,
            "platform": platform,
            "topic": topic,
            "stage": stage,
            "status": status,
            "asset_url": asset_url,
            "publish_url": publish_url,
            "channel_name": channel_name,
            "account_label": account_label,
            "network": network,
            "product_name": product_name,
            "affiliate_url": affiliate_url,
        },
        "readiness": readiness,
        "missing": missing,
        "publish_pack": pack,
        "assets": assets,
        "final_asset": final_asset,
        "commands": {
            "send_video": f"/asset_send job={job_id} type=final_video",
            "publish_pack": f"/publish_pack job={job_id}",
            "approve_manual": f"/approve_publish job={job_id} queue=1 mode=manual note=review_video_ok",
            "approve_api": f"/approve_publish job={job_id} queue=1 mode=api note=review_video_ok",
            "mark_published": f"/mark_published job={job_id} url=https://... views=0 clicks=0 note=...",
            "fix_next": missing[0].get("next") if missing else "",
        },
    }
    summary["review_decision"] = build_video_review_decision(summary)
    return summary

def build_video_review_decision(summary):
    job = summary.get("job") or {}
    readiness = summary.get("readiness") or {}
    publish_gate = readiness.get("publish_gate") or {}
    missing = summary.get("missing") or []
    final_asset = summary.get("final_asset")
    pack = summary.get("publish_pack") or {}
    commands = summary.get("commands") or {}
    core_missing = [item for item in missing if item.get("key") != "queue_or_published"]
    has_final = bool(final_asset)
    has_affiliate = bool(((pack.get("primary_affiliate") or {}).get("tracking_url")) or job.get("affiliate_url"))
    has_disclosure = bool(pack.get("disclosure") or "affiliate" in (pack.get("caption") or "").lower())
    risk_checks = [
        {"key": "final_video", "ok": has_final, "detail": "Có final_video/raw_video để admin xem trước khi duyệt." if has_final else "Chưa có video để kiểm duyệt."},
        {"key": "affiliate_link", "ok": has_affiliate, "detail": "Có link affiliate/tracking cho caption/comment." if has_affiliate else "Thiếu link affiliate."},
        {"key": "affiliate_disclosure", "ok": has_disclosure, "detail": "Có disclosure affiliate trong caption/pack." if has_disclosure else "Thiếu disclosure affiliate rõ ràng."},
        {"key": "admin_human_review", "ok": False, "detail": "Bắt buộc admin xem video thật, caption, claim, link và quyền nội dung trước khi approve."},
        {"key": "rights_and_consent", "ok": False, "detail": "Admin xác nhận hình/giọng/nhạc/AI model có quyền dùng; OnlyFans/người mẫu phải 18+ và có consent nếu là người thật."},
        {"key": "claim_safety", "ok": False, "detail": "Admin xác nhận không hứa chắc thu nhập, duyệt vay/thẻ, sức khỏe hoặc kết quả tài chính."},
    ]
    if not has_final:
        decision = "BLOCKED_NO_VIDEO"
        safety_gate = "blocked"
        next_telegram = commands.get("fix_next") or f"/next_task job={job.get('id') or '<JOB_ID>'}"
    elif core_missing:
        decision = "NEEDS_FIX"
        safety_gate = "needs_admin"
        next_telegram = commands.get("fix_next") or f"/job_ready job={job.get('id') or '<JOB_ID>'}"
    elif publish_gate.get("can_approve"):
        decision = "READY_FOR_ADMIN_APPROVAL"
        safety_gate = "needs_admin"
        next_telegram = commands.get("approve_manual") or f"/approve_publish job={job.get('id') or '<JOB_ID>'} queue=1 mode=manual"
    else:
        decision = "REVIEW_REQUIRED"
        safety_gate = "needs_admin"
        next_telegram = commands.get("send_video") or f"/review_video job={job.get('id') or '<JOB_ID>'} send=1"
    return {
        "decision": decision,
        "safety_gate": safety_gate,
        "can_admin_approve": decision == "READY_FOR_ADMIN_APPROVAL",
        "can_auto_publish": False,
        "reason": "Auto publish luôn tắt ở review gate; chỉ queue sau khi admin approve.",
        "core_missing": core_missing,
        "risk_checks": risk_checks,
        "next_telegram": next_telegram,
        "next_api": f"/api/operator/jobs/{job.get('id')}/approve" if decision == "READY_FOR_ADMIN_APPROVAL" else "",
        "approval_payload": {"queue": True, "mode": "manual", "note": "review_video_ok", "notify_admin": True} if decision == "READY_FOR_ADMIN_APPROVAL" else {},
        "rule": "Claude/n8n chỉ được đề xuất approve, không tự bypass bước admin human review.",
    }

def format_video_review_summary(summary):
    job = summary.get("job") or {}
    pack = summary.get("publish_pack") or {}
    readiness = summary.get("readiness") or {}
    final_asset = summary.get("final_asset")
    commands = summary.get("commands") or {}
    decision = summary.get("review_decision") or {}
    level = readiness.get("level") or "UNKNOWN"
    missing = summary.get("missing") or []
    primary = pack.get("primary_affiliate") or {}
    related = pack.get("related_links") or []
    final_asset_text = "-"
    if final_asset:
        aid, _owner_id, _job_id, asset_type, url, file_id, note, local_path, content_type, filename, created_at = final_asset
        final_asset_text = f"#{aid} / {asset_type or '-'} / {filename or url or file_id or local_path or '-'}"
    lines = [
        f"🎥 <b>VIDEO REVIEW — JOB #{job.get('id')}</b>",
        f"• Readiness: <b>{html.escape(level)}</b>",
        f"• Stage/status: <b>{html.escape(job.get('stage') or '-')}</b>/<b>{html.escape(job.get('status') or '-')}</b>",
        f"• Platform: <code>{html.escape(job.get('platform') or '-')}</code>",
        f"• Channel: {html.escape(job.get('channel_name') or '-')} / <code>{html.escape(job.get('account_label') or 'main')}</code>",
        f"• Topic: {html.escape(job.get('topic') or '-')}",
        f"• Final asset: <code>{html.escape(final_asset_text)}</code>",
        f"• Decision: <code>{html.escape(decision.get('decision') or 'REVIEW_REQUIRED')}</code> | gate=<code>{html.escape(decision.get('safety_gate') or 'needs_admin')}</code>",
        "",
        "<b>Affiliate chính:</b>",
        f"• {html.escape(primary.get('network') or job.get('network') or '-')} / {html.escape(primary.get('product') or job.get('product_name') or '-')}",
        f"• Link tracking/caption: <code>{html.escape(primary.get('tracking_url') or primary.get('url') or job.get('affiliate_url') or '-')}</code>",
        "",
        "<b>Caption:</b>",
        f"<pre>{html_pre(pack.get('caption') or '-', 1200)}</pre>",
        "<b>Comment ghim/link kèm:</b>",
        f"<pre>{html_pre(pack.get('pinned_comment') or '-', 1000)}</pre>",
    ]
    if related:
        lines.append("<b>Link liên quan nên kèm:</b>")
        for item in related[:5]:
            placement = item.get("placement") or {}
            lines.append(
                f"• {html.escape(item.get('product_name') or '-')} | "
                f"<code>{html.escape(placement.get('caption') or item.get('url') or '-')}</code>"
            )
    lines.append("\n<b>Checklist trước đăng:</b>")
    for item in (pack.get("checklist") or [])[:8]:
        lines.append(f"• {html.escape(item)}")
    if decision.get("risk_checks"):
        lines.append("\n<b>Review decision/risk:</b>")
        for item in decision.get("risk_checks", [])[:6]:
            icon = "✅" if item.get("ok") else "⚠️"
            lines.append(f"• {icon} <code>{html.escape(item.get('key') or '-')}</code>: {html.escape(item.get('detail') or '-')}")
    if missing:
        lines.append("\n<b>Đang thiếu:</b>")
        for item in missing[:6]:
            lines.append(
                f"• <code>{html.escape(item.get('key') or '-')}</code>: {html.escape(item.get('detail') or '-')}\n"
                f"  Next: <code>{html.escape(item.get('next') or '-')}</code>"
            )
    lines.append("\n<b>Lệnh tiếp theo:</b>")
    lines.append(f"• Xem video: <code>{html.escape(commands.get('send_video') or '')}</code>")
    lines.append(f"• Pack đầy đủ: <code>{html.escape(commands.get('publish_pack') or '')}</code>")
    if level == "READY_TO_QUEUE":
        lines.append(f"• Duyệt đăng tay: <code>{html.escape(commands.get('approve_manual') or '')}</code>")
        lines.append(f"• Duyệt API chính thức: <code>{html.escape(commands.get('approve_api') or '')}</code>")
    elif commands.get("fix_next"):
        lines.append(f"• Sửa điểm thiếu: <code>{html.escape(commands.get('fix_next') or '')}</code>")
    lines.append(f"• Sau đăng: <code>{html.escape(commands.get('mark_published') or '')}</code>")
    return "\n".join(lines)

def operator_review_job_ids_from_result(owner_id, result, limit=3):
    result = result or {}
    autorun = result.get("autorun") or ((result.get("worker_handoff") or {}).get("autorun") or {})
    candidates = []

    def add_job_id(value):
        job_id = safe_int(value, 0)
        if job_id > 0 and job_id not in candidates:
            candidates.append(job_id)

    for item in (autorun.get("completed") or result.get("completed") or []):
        task_type = (item.get("task_type") or "").lower()
        if task_type in {"edit", "review", "final_video"} or item.get("telegram_review"):
            add_job_id(item.get("job_id"))
    for job_id in autorun.get("job_ids") or result.get("job_ids") or []:
        add_job_id(job_id)
    for item in result.get("created_jobs") or []:
        add_job_id(item.get("job_id") or item.get("id"))

    ready = []
    for job_id in candidates:
        summary = build_video_review_summary(owner_id, job_id)
        if summary and summary.get("final_asset"):
            ready.append(job_id)
        if len(ready) >= limit:
            break
    return ready

async def send_operator_review_packets(context: ContextTypes.DEFAULT_TYPE, chat_id: int, owner_id, result, limit=3):
    sent = []
    errors = []
    for job_id in operator_review_job_ids_from_result(owner_id, result, limit=limit):
        summary = build_video_review_summary(owner_id, job_id)
        if not summary:
            continue
        final_asset = summary.get("final_asset")
        try:
            if final_asset:
                await send_production_asset_to_chat(context, chat_id, owner_id, final_asset[0])
            await context.bot.send_message(
                chat_id=chat_id,
                text=format_video_review_summary(summary),
                parse_mode="HTML",
            )
            sent.append(job_id)
        except Exception as exc:
            errors.append({"job_id": job_id, "error": str(exc)})
            logger.error(f"operator review packet send error: job={job_id} error={exc}")
    return {"sent": sent, "errors": errors}

def job_performance_summary(owner_id, job_id):
    conn = db_connect()
    c = conn.cursor()
    c.execute(
        """SELECT event_type, SUM(COALESCE(value,0)), SUM(COALESCE(amount,0)), COUNT(*)
        FROM performance_events
        WHERE owner_id=? AND job_id=?
        GROUP BY event_type""",
        (str(owner_id), int(job_id)),
    )
    totals = {
        event_type: {"value": int(value or 0), "amount": int(amount or 0), "events": int(count or 0)}
        for event_type, value, amount, count in c.fetchall()
    }
    c.execute(
        """SELECT COALESCE(note,''), event_type, SUM(COALESCE(value,0)), SUM(COALESCE(amount,0)), COUNT(*)
        FROM performance_events
        WHERE owner_id=? AND job_id=?
        GROUP BY COALESCE(note,''), event_type
        ORDER BY MAX(id) DESC
        LIMIT 30""",
        (str(owner_id), int(job_id)),
    )
    by_source = []
    for note, event_type, value, amount, count in c.fetchall():
        by_source.append({
            "source": performance_source_from_note(note),
            "note": note,
            "event_type": event_type,
            "value": int(value or 0),
            "amount": int(amount or 0),
            "events": int(count or 0),
        })
    conn.close()
    views = totals.get("view", {}).get("value", 0)
    clicks = totals.get("click", {}).get("value", 0)
    conversions = sum(totals.get(key, {}).get("value", 0) for key in ("order", "lead", "revenue"))
    revenue = sum(totals.get(key, {}).get("amount", 0) for key in ("order", "lead", "revenue"))
    cost = totals.get("cost", {}).get("amount", 0)
    score, ctr, cvr, roi = growth_score(views, clicks, conversions, revenue, cost)
    return {
        "totals": totals,
        "by_source": by_source,
        "score": score,
        "views": views,
        "clicks": clicks,
        "conversions": conversions,
        "revenue": revenue,
        "cost": cost,
        "ctr": ctr,
        "cvr": cvr,
        "roi": roi,
    }

