def build_trend_prompt_suggestions(trend: dict) -> list[str]:
    title = str(trend.get("title") or trend.get("trend_title") or trend.get("topic") or "trend").strip()[:180]
    summary = str(trend.get("summary") or trend.get("trend_summary") or "").strip()[:260]
    platform = str(trend.get("platform") or "tiktok").strip()[:40]
    niche = str(trend.get("niche") or "AI/product").strip()[:80]
    simple_image = f"Create a clean realistic image about {title}, target audience {niche}, clear subject, no watermark, high quality, aspect ratio 9:16."
    product_image = f"Product/affiliate ad image for {title}, show problem-solution visually, clean commercial lighting, CTA space, no fake claims, 4:5."
    viral_image = f"Viral social image for {platform}: bold visual hook about {title}, UGC style, emotional contrast, readable composition, no extra text."
    thumbnail = f"Cinematic thumbnail for {title}, premium tech lighting, strong focal point, high contrast, professional brand style, 16:9."
    short_video = f"Short video prompt: {build_video_flow_suggestions(title)}"
    return [
        "",
        f"<b>Trend guide:</b> {html.escape(title)}",
        f"• Vì sao đáng chú ý: {html.escape(summary or 'Có tín hiệu mới/đang được quan tâm trong nguồn trend.')}",
        f"• Audience: <code>{html.escape(niche)}</code> | Platform: <code>{html.escape(platform)}</code>",
        "• Risk/copyright: kiểm tra nguồn, tránh dùng logo/nhân vật/thương hiệu nếu chưa có quyền; không cam kết kết quả quá mức.",
        "• Hook/caption gợi ý: <code>Đừng mua/làm điều này trước khi xem 3 điểm sau...</code> | <code>Đây là cách biến vấn đề này thành lợi thế.</code>",
        "• CTA gợi ý: <code>Lưu lại để thử sau</code> | <code>Nhắn TOAN AAS để tạo pack nội dung tương tự</code>",
        "Bạn có thể copy 1 trong các prompt này để tạo ảnh:",
        f"<pre>{html.escape(simple_image)}</pre>",
        f"<pre>{html.escape(product_image)}</pre>",
        f"<pre>{html.escape(viral_image)}</pre>",
        f"<pre>{html.escape(thumbnail)}</pre>",
        "Gợi ý pose/góc máy/style:",
        f"<pre>{html.escape(build_image_pose_suggestions(title))}</pre>",
        "Gợi ý video tiếp theo:",
        f"<pre>{html.escape(short_video)}</pre>",
        "Nếu ảnh này ổn, bạn có thể dùng nó để tạo video. Gợi ý: copy prompt video ở trên.",
    ]

def set_manual_bill_state(uid, order_code="", amount=0, xu=0, pkg_key="", method="bank_acb", **details):
    currency = str(details.get("currency") or "VND").strip().upper()
    amount_vnd = int(details.get("amount_vnd") or amount or 0)
    subtotal_amount_vnd = int(details.get("subtotal_amount_vnd") or details.get("taxable_amount_vnd") or amount_vnd or 0)
    vat_amount_vnd = int(details.get("vat_amount_vnd") or 0)
    total_amount_vnd = int(details.get("total_amount_vnd") or amount_vnd or 0)
    vat_rate = float(details.get("vat_rate") or 0)
    vat_mode = str(details.get("vat_mode") or VAT_DEFAULT_MODE)
    vat_label = str(details.get("vat_label") or VAT_DEFAULT_LABEL)
    if subtotal_amount_vnd > 0 and vat_amount_vnd <= 0 and total_amount_vnd <= subtotal_amount_vnd:
        try:
            tax_snapshot = calculate_vat_snapshot(subtotal_amount_vnd, finance_tax_config(), taxable=True)
            vat_rate = float(tax_snapshot.get("vat_rate") or vat_rate or 0)
            vat_amount_vnd = int(tax_snapshot.get("vat_amount_vnd") or 0)
            total_amount_vnd = int(tax_snapshot.get("total_amount_vnd") or subtotal_amount_vnd)
            vat_mode = str(tax_snapshot.get("vat_mode") or vat_mode)
            vat_label = str(tax_snapshot.get("vat_label") or vat_label)
            amount_vnd = total_amount_vnd
        except Exception:
            total_amount_vnd = amount_vnd
    base_xu = int(details.get("base_xu") or 0)
    expected_xu = int(details.get("expected_xu") or xu or 0)
    if currency == "VND" and base_xu <= 0 and subtotal_amount_vnd > 0:
        base_xu = package_base_xu(subtotal_amount_vnd)
    bonus_xu = int(details.get("bonus_xu") or max(0, expected_xu - base_xu))
    state = {
        "order_code": str(order_code or ""),
        "amount": amount_vnd,
        "xu": expected_xu,
        "pkg_key": str(pkg_key or ""),
        "method": str(method or "bank_acb"),
        "currency": currency,
        "original_amount": details.get("original_amount", amount_vnd),
        "fixed_rate_vnd": int(details.get("fixed_rate_vnd") or (1 if currency == "VND" else foreign_topup_rate_vnd(currency))),
        "amount_vnd": amount_vnd,
        "subtotal_amount_vnd": subtotal_amount_vnd,
        "vat_rate": vat_rate,
        "vat_amount_vnd": vat_amount_vnd,
        "total_amount_vnd": total_amount_vnd,
        "vat_mode": vat_mode,
        "vat_label": vat_label,
        "base_xu": base_xu,
        "bonus_xu": bonus_xu,
        "expected_xu": expected_xu,
        "foreign_manual": bool(details.get("foreign_manual", currency in {"USD", "CNY"} or str(method) == "usdt_trc20")),
        "first_bonus_applied": bool(details.get("first_bonus_applied", False)),
        "launch_bonus_applied": bool(details.get("launch_bonus_applied", False)),
        "rank_topup_reward_applied": bool(details.get("rank_topup_reward_applied", False)),
        "extra_xu_percent_bonus_applied": bool(details.get("extra_xu_percent_bonus_applied", False)),
        "rank_discount_percent_preserved": bool(details.get("rank_discount_percent_preserved", True)),
        "member_points_eligible": bool(details.get("member_points_eligible", True)),
        "transfer_content": str(details.get("transfer_content") or f"AAS {uid} MANUAL"),
        "step": str(details.get("step") or "select_method"),
        "source": "manual_bill_flow",
        "expires_at": time.time() + MANUAL_BILL_STATE_TTL_SECONDS,
    }
    USER_BILL_STATE[uid] = state

def update_manual_bill_state(uid, **changes):
    state = get_active_manual_bill_state(uid) or {}
    state.update(changes)
    set_manual_bill_state(
        uid,
        order_code=state.get("order_code") or "MANUAL",
        amount=state.get("amount_vnd") or state.get("amount") or 0,
        xu=state.get("expected_xu") or state.get("xu") or 0,
        pkg_key=state.get("pkg_key") or "",
        method=state.get("method") or "bank_acb",
        **{key: value for key, value in state.items() if key not in {"order_code", "amount", "xu", "pkg_key", "method", "source", "expires_at"}},
    )
    return get_active_manual_bill_state(uid)

def get_active_manual_bill_state(uid):
    state = USER_BILL_STATE.get(uid)
    if not state:
        return None
    if state is True:
        state = {"expires_at": time.time() + MANUAL_BILL_STATE_TTL_SECONDS}
        USER_BILL_STATE[uid] = state
    if not isinstance(state, dict):
        USER_BILL_STATE.pop(uid, None)
        return None
    if state.get("source") != "manual_bill_flow":
        USER_BILL_STATE.pop(uid, None)
        return None
    if float(state.get("expires_at") or 0) < time.time():
        USER_BILL_STATE.pop(uid, None)
        return None
    return state

