TRANSLATION_REQUEST_TTL_SECONDS = 10 * 60
LAST_TRANSLATION_REQUEST: dict = {}
TRANSLATION_MENU_PENDING: dict = {}
TRANSLATION_SESSION_TTL_SECONDS = 60 * 60
TRANSLATION_SESSION_PENDING: dict = {}

def set_translation_menu_pending(user_id, source_type: str, **fields) -> None:
    payload = {
        "source_type": str(source_type or "text"),
        "created_at_ts": time.time(),
    }
    payload.update({
        key: value for key, value in fields.items()
        if key in {
            "target_language", "return_action", "source_text", "confirm_token",
            "source_language", "output_type", "translation_context", "parent_menu",
        }
    })
    TRANSLATION_MENU_PENDING[str(user_id)] = payload

def get_translation_menu_pending(user_id) -> dict:
    pending = TRANSLATION_MENU_PENDING.get(str(user_id)) or {}
    if not pending:
        return {}
    if float(pending.get("created_at_ts") or 0) + TRANSLATION_REQUEST_TTL_SECONDS < time.time():
        TRANSLATION_MENU_PENDING.pop(str(user_id), None)
        return {}
    return dict(pending)

def clear_translation_menu_pending(user_id) -> bool:
    return TRANSLATION_MENU_PENDING.pop(str(user_id), None) is not None

def set_translation_session(user_id, mode: str, lang_a: str = "vi", lang_b: str = "en", input_mode: str = "text_voice", output_mode: str = "text", budget_xu: int = 0, **fields) -> dict:
    a = normalize_translate_target(lang_a) or "vi"
    b = normalize_translate_target(lang_b) or "en"
    current = dict(TRANSLATION_SESSION_PENDING.get(str(user_id)) or {})
    session_id = str(fields.get("translation_session_id") or current.get("translation_session_id") or "").strip()
    if not session_id:
        session_id = hashlib.sha256(f"task2:{user_id}:{time.time_ns()}".encode("utf-8")).hexdigest()[:20]
    product = "conversation" if str(mode or "") == "live_conversation" else "language_two_way"
    payload = {
        "mode": str(mode or "two_way"),
        "translation_session_id": session_id,
        "product": product,
        "current_step": "active",
        "previous_step": "language_pair",
        "lang_a": a,
        "lang_b": b,
        "input_mode": str(input_mode or "text_voice"),
        "output_mode": str(output_mode or "text"),
        "budget_xu": max(0, int(budget_xu or 0)),
        "source_ref": str(fields.get("source_ref") or current.get("source_ref") or "")[:300],
        "selected_language": b,
        "selected_voice": str(fields.get("selected_voice") or current.get("selected_voice") or "")[:160],
        "speed": str(fields.get("speed") or current.get("speed") or "1.0")[:20],
        "return_to": "translation_language_hub",
        "detected_lang_a": str(fields.get("detected_lang_a") or current.get("detected_lang_a") or "")[:20],
        "last_detected_language": str(fields.get("last_detected_language") or current.get("last_detected_language") or "")[:20],
        "created_at_ts": time.time(),
        "last_used_at_ts": time.time(),
    }
    TRANSLATION_SESSION_PENDING[str(user_id)] = payload
    return dict(payload)

def get_translation_session(user_id) -> dict:
    payload = TRANSLATION_SESSION_PENDING.get(str(user_id)) or {}
    if not payload:
        return {}
    if float(payload.get("created_at_ts") or 0) + TRANSLATION_SESSION_TTL_SECONDS < time.time():
        TRANSLATION_SESSION_PENDING.pop(str(user_id), None)
        return {}
    return dict(payload)

def clear_translation_session(user_id) -> bool:
    return TRANSLATION_SESSION_PENDING.pop(str(user_id), None) is not None

def translation_session_is_active(user_id) -> bool:
    return bool(get_translation_session(user_id))

