async def cmd_admin_deduct(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    try:
        target_id = str(context.args[0]).strip()
        amount = int(context.args[1])
        if amount <= 0:
            raise ValueError("amount")
    except Exception:
        return await update.message.reply_text("⚠️ Cú pháp: <code>/deduct USER_ID Xu</code>", parse_mode="HTML")
    conn = db_connect()
    try:
        row = conn.execute("SELECT credits FROM users WHERE user_id=?", (target_id,)).fetchone()
    finally:
        conn.close()
    if not row:
        return await update.message.reply_text(f"⚠️ Không tìm thấy user <code>{html.escape(target_id)}</code>.", parse_mode="HTML")
    credits = int(row[0] or 0)
    if int(credits or 0) < amount:
        return await update.message.reply_text(
            f"⚠️ User <code>{html.escape(target_id)}</code> chỉ còn <b>{int(credits or 0)} Xu</b>, không đủ để trừ <b>{amount} Xu</b>.",
            parse_mode="HTML",
        )
    conn = db_connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        conn.execute("UPDATE users SET credits = credits - ? WHERE user_id=?", (amount, target_id))
        record_credit_event(conn, target_id, -amount, "admin_deduct", "", f"Admin {update.effective_user.id} deducted Xu")
        record_audit(
            conn,
            update.effective_user.id,
            "admin",
            "credit.deducted",
            "user",
            target_id,
            before={"credits": int(credits or 0)},
            after={"delta": -amount, "credits": int(credits or 0) - amount},
            note="/deduct admin manual adjustment",
        )
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    await update.message.reply_text(
        f"✅ Đã trừ <b>{amount} Xu</b> từ user <code>{html.escape(target_id)}</code>.\n"
        f"• Số dư mới: <b>{int(credits or 0) - amount} Xu</b>",
        parse_mode="HTML",
    )

def get_system_flag(key, default=""):
    try:
        conn = db_connect()
        row = conn.execute("SELECT value FROM system_flags WHERE key=?", (str(key),)).fetchone()
        conn.close()
        if not row:
            return default
        return row[0] if row[0] is not None else default
    except Exception:
        return default

def set_system_flag(key, value, updated_by="", note=""):
    conn = db_connect()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS system_flags (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT,
            updated_by TEXT,
            note TEXT
        )""")
        conn.execute(
            """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
            VALUES (?,?,?,?,?)
            ON CONFLICT(key) DO UPDATE SET
                value=excluded.value,
                updated_at=excluded.updated_at,
                updated_by=excluded.updated_by,
                note=excluded.note""",
            (str(key), str(value), now_text(), str(updated_by or ""), str(note or "")[:1000]),
        )
        conn.commit()
    finally:
        conn.close()

def set_system_flags(values: dict, updated_by="", note=""):
    conn = db_connect()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS system_flags (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT,
            updated_by TEXT,
            note TEXT
        )""")
        for key, value in (values or {}).items():
            conn.execute(
                """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
                VALUES (?,?,?,?,?)
                ON CONFLICT(key) DO UPDATE SET
                    value=excluded.value,
                    updated_at=excluded.updated_at,
                    updated_by=excluded.updated_by,
                    note=excluded.note""",
                (str(key), str(value), now_text(), str(updated_by or ""), str(note or "")[:1000]),
            )
        conn.commit()
    finally:
        conn.close()

def system_flag_row(key: str) -> dict:
    try:
        conn = db_connect()
        row = conn.execute(
            "SELECT value, updated_at, updated_by, note FROM system_flags WHERE key=?",
            (str(key),),
        ).fetchone()
        conn.close()
    except Exception:
        row = None
    if not row:
        return {"key": str(key), "value": "", "updated_at": "", "updated_by": "", "note": ""}
    return {"key": str(key), "value": row[0] or "", "updated_at": row[1] or "", "updated_by": row[2] or "", "note": row[3] or ""}

def flag_on(key: str) -> bool:
    return str(get_system_flag(key, "0") or "0").strip().lower() in {"1", "true", "yes", "on"}

def current_system_mode() -> dict:
    keys = ["emergency_lock", "maintenance_mode", "payment_freeze", "tool_freeze", "provider_freeze", "safe_mode_reason", "last_emergency_at"]
    rows = {key: system_flag_row(key) for key in keys}
    emergency = str(rows["emergency_lock"]["value"]).strip() in {"1", "true", "on", "yes"}
    maintenance = str(rows["maintenance_mode"]["value"]).strip() in {"1", "true", "on", "yes"}
    payment = str(rows["payment_freeze"]["value"]).strip() in {"1", "true", "on", "yes"}
    tools = str(rows["tool_freeze"]["value"]).strip() in {"1", "true", "on", "yes"}
    providers = str(rows["provider_freeze"]["value"]).strip() in {"1", "true", "on", "yes"}
    if emergency:
        label = "EMERGENCY LOCK"
    elif maintenance:
        label = "MAINTENANCE"
    else:
        label = "NORMAL"
    return {
        "label": label,
        "emergency_lock": emergency,
        "maintenance_mode": maintenance,
        "payment_freeze": payment,
        "tool_freeze": tools,
        "provider_freeze": providers,
        "safe_mode_reason": rows["safe_mode_reason"]["value"] or "",
        "last_emergency_at": rows["last_emergency_at"]["value"] or "",
        "rows": rows,
    }

