def record_anomaly(kind, severity, detail, user_id="", username="", auto_lock=True) -> dict:
    severity_clean = str(severity or "low").lower()
    detail_clean = sanitize_log_text(str(detail or ""))[:1500]
    conn = db_connect()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS security_events (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            event_type TEXT,
            severity TEXT,
            user_id TEXT,
            username TEXT,
            detail TEXT,
            created_at TEXT
        )""")
        conn.execute("""CREATE TABLE IF NOT EXISTS system_flags (
            key TEXT PRIMARY KEY,
            value TEXT,
            updated_at TEXT,
            updated_by TEXT,
            note TEXT
        )""")
        conn.execute(
            """INSERT INTO security_events (event_type, severity, user_id, username, detail, created_at)
            VALUES (?,?,?,?,?,?)""",
            (str(kind or "unknown"), severity_clean, str(user_id or ""), str(username or ""), detail_clean, now_text()),
        )
        if auto_lock and severity_clean == "critical":
            conn.execute(
                """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
                VALUES (?,?,?,?,?)
                ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at, updated_by=excluded.updated_by, note=excluded.note""",
                ("emergency_lock", "1", now_text(), "auto_anomaly", detail_clean),
            )
            for key in ("payment_freeze", "tool_freeze", "provider_freeze"):
                conn.execute(
                    """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
                    VALUES (?,?,?,?,?)
                    ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at, updated_by=excluded.updated_by, note=excluded.note""",
                    (key, "1", now_text(), "auto_anomaly", detail_clean),
                )
            conn.execute(
                """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
                VALUES (?,?,?,?,?)
                ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at, updated_by=excluded.updated_by, note=excluded.note""",
                ("safe_mode_reason", detail_clean, now_text(), "auto_anomaly", detail_clean),
            )
            conn.execute(
                """INSERT INTO system_flags (key, value, updated_at, updated_by, note)
                VALUES (?,?,?,?,?)
                ON CONFLICT(key) DO UPDATE SET value=excluded.value, updated_at=excluded.updated_at, updated_by=excluded.updated_by, note=excluded.note""",
                ("last_emergency_at", now_text(), now_text(), "auto_anomaly", detail_clean),
            )
        conn.commit()
    finally:
        conn.close()
    return {"event_type": str(kind or "unknown"), "severity": severity_clean, "detail": detail_clean, "auto_locked": bool(auto_lock and severity_clean == "critical")}

def request_security_context(request: Request | None = None) -> dict:
    if not request:
        return {"ip": "", "user_agent": "", "endpoint": ""}
    client = getattr(request, "client", None)
    return {
        "ip": sanitize_log_text(str(getattr(client, "host", "") or ""))[:80],
        "user_agent": sanitize_log_text(str(request.headers.get("user-agent") or ""))[:240],
        "endpoint": sanitize_log_text(str(getattr(getattr(request, "url", None), "path", "") or ""))[:160],
    }

def record_security_event(
    kind: str,
    severity: str = "low",
    detail: str | dict = "",
    request: Request | None = None,
    user_id: str = "",
    username: str = "",
    action: str = "",
    endpoint: str = "",
    order_code: str = "",
    payment_id: str = "",
    auto_lock: bool = False,
) -> dict:
    ctx = request_security_context(request)
    payload = {
        "detail": detail if isinstance(detail, dict) else str(detail or ""),
        "ip": ctx.get("ip") or "",
        "user_agent": ctx.get("user_agent") or "",
        "endpoint": endpoint or ctx.get("endpoint") or "",
        "action": str(action or ""),
        "order_code": str(order_code or ""),
        "payment_id": str(payment_id or ""),
    }
    clean_detail = sanitize_log_text(json.dumps(payload, ensure_ascii=False, default=str))[:1500]
    return record_anomaly(
        kind,
        severity,
        clean_detail,
        user_id=str(user_id or ""),
        username=str(username or ""),
        auto_lock=auto_lock,
    )

def recent_security_events(limit: int = 8) -> list[dict]:
    conn = db_connect()
    try:
        rows = conn.execute(
            """SELECT event_type,severity,user_id,username,detail,created_at
               FROM security_events ORDER BY id DESC LIMIT ?""",
            (max(1, min(50, int(limit or 8))),),
        ).fetchall()
    finally:
        conn.close()
    events = []
    for row in rows:
        events.append({
            "event_type": str(row[0] or ""),
            "severity": str(row[1] or ""),
            "user_id": str(row[2] or ""),
            "username": str(row[3] or ""),
            "detail": sanitize_log_text(str(row[4] or ""))[:360],
            "created_at": str(row[5] or ""),
        })
    return events

