def video_final_duration_model(payload: dict | None = None, state: dict | None = None, tier: str = "") -> dict:
    payload = dict(payload or {})
    state = dict(state or {})
    project = dict(state.get("video_project") or payload.get("video_project") or {})
    tier_norm = normalize_video_tier(tier or state.get("video_tier") or payload.get("video_tier") or "")
    scene_duration = max(
        1,
        _safe_int(
            state.get("scene_duration_seconds")
            or payload.get("scene_duration_seconds")
            or state.get("estimated_scene_seconds")
            or payload.get("estimated_scene_seconds")
            or project.get("scene_duration_seconds")
            or project.get("estimated_scene_seconds")
            or VIDEO_FINAL_DEFAULT_SCENE_SECONDS,
            VIDEO_FINAL_DEFAULT_SCENE_SECONDS,
        ),
    )
    requested_seconds = _safe_int(
        state.get("requested_seconds")
        or payload.get("requested_seconds")
        or state.get("duration_seconds")
        or payload.get("duration_seconds")
        or state.get("current_video_duration_seconds")
        or payload.get("source_duration")
        or 0,
        0,
    )
    explicit_scene_count = _safe_int(
        state.get("scene_count")
        or payload.get("scene_count")
        or project.get("scene_count")
        or len(project.get("scenes") or []),
        0,
    )
    selected_scene_count = _safe_int(
        state.get("selected_scene_count")
        or payload.get("selected_scene_count")
        or project.get("selected_scene_count")
        or 0,
        0,
    )
    if selected_scene_count > 0:
        scene_count = selected_scene_count
        final_seconds = scene_count * scene_duration
    elif explicit_scene_count > 0:
        scene_count = max(VIDEO_FINAL_DEFAULT_SCENES, explicit_scene_count)
        final_seconds = scene_count * scene_duration
    elif requested_seconds > 0:
        scene_count = max(VIDEO_FINAL_DEFAULT_SCENES, int(math.ceil(requested_seconds / max(1, scene_duration))))
        final_seconds = max(VIDEO_FINAL_DEFAULT_SECONDS, scene_count * scene_duration)
    else:
        scene_count = VIDEO_FINAL_DEFAULT_SCENES
        final_seconds = VIDEO_FINAL_DEFAULT_SECONDS
    short_request = bool(requested_seconds and requested_seconds <= 17)
    paid_preview_route_ready = video_paid_preview_worker_available()
    preview_locked_reason = ""
    preview_enabled = True
    if tier_norm == "low":
        preview_enabled = False
        preview_locked_reason = "tier_200"
    elif short_request or final_seconds <= 17 or scene_count < VIDEO_FINAL_DEFAULT_SCENES:
        preview_enabled = False
        preview_locked_reason = "under_18s"
    elif not paid_preview_route_ready:
        preview_enabled = False
        preview_locked_reason = "preview_route_not_ready"
    return {
        "scene_count": int(scene_count),
        "scene_duration_seconds": int(scene_duration),
        "final_duration_seconds": int(final_seconds),
        "requested_seconds": int(requested_seconds or final_seconds),
        "preview_duration_seconds": int(VIDEO_PREVIEW_DEFAULT_SECONDS),
        "preview_enabled": bool(preview_enabled),
        "preview_locked_reason": preview_locked_reason,
        "selected_tier": tier_norm,
    }

def video_order_normalize_items(items) -> list[dict]:
    normalized = []
    for item in items or []:
        if isinstance(item, dict):
            key = str(item.get("key") or item.get("label") or "").strip()
            label = str(item.get("label") or key).strip()
            price = int(item.get("price_xu") or 0)
            if key or label:
                normalized.append({"key": key, "label": label, "price_xu": max(0, price)})
        else:
            text = str(item or "").strip()
            if text:
                normalized.append({"key": text, "label": text, "price_xu": 0})
    return normalized

def video_order_dedupe_items(items) -> list[dict]:
    deduped = []
    seen = set()
    for item in video_order_normalize_items(items):
        key = str(item.get("key") or item.get("label") or "").strip()
        if not key or key in seen:
            continue
        seen.add(key)
        deduped.append(item)
    return deduped

def video_order_create(
    user_id=None,
    tier: str = "low",
    source_payload: dict | None = None,
    state: dict | None = None,
    current_screen: str = "video_addon_menu",
) -> dict:
    source_payload = dict(source_payload or {})
    state = dict(state or {})
    tier_norm = normalize_video_tier(tier or state.get("video_tier") or source_payload.get("video_tier") or "low")
    payload = video_tier_payload(tier_norm)
    duration_model = video_final_duration_model(source_payload, state, tier_norm)
    duration = int(duration_model.get("final_duration_seconds") or VIDEO_FINAL_DEFAULT_SECONDS)
    project = dict(state.get("video_project") or source_payload.get("video_project") or {})
    scene_count = next(
        (
            safe_int(source.get("selected_scene_count") or source.get("scene_count"), 0)
            for source in (state, source_payload, project)
            if safe_int(source.get("selected_scene_count") or source.get("scene_count"), 0) > 0
        ),
        1,
    )
    order = {
        "user_id": str(user_id or state.get("user_id") or source_payload.get("user_id") or ""),
        "tier": tier_norm,
        "tier_name": str(payload.get("label") or video_tier_short_label(tier_norm, "vi")),
        "base_price_xu": int(payload.get("cost") or video_tier_cost_xu(tier_norm) or 0),
        "base_seconds": int(VIDEO_FINAL_DEFAULT_SECONDS),
        "requested_seconds": max(1, int(duration or VIDEO_ORDER_DEFAULT_BASE_SECONDS)),
        "scene_count": max(1, int(scene_count or VIDEO_ORDER_DEFAULT_BASE_SCENES)),
        "scene_duration_seconds": int(duration_model.get("scene_duration_seconds") or VIDEO_FINAL_DEFAULT_SCENE_SECONDS),
        "preview_duration_seconds": int(duration_model.get("preview_duration_seconds") or VIDEO_PREVIEW_DEFAULT_SECONDS),
        "preview_enabled": bool(duration_model.get("preview_enabled")),
        "preview_locked_reason": str(duration_model.get("preview_locked_reason") or ""),
        "scene_extra_price_xu": 0,
        "duration_extra_price_xu": 0,
        "quality_level": str(video_quality_from_tier(tier_norm) or tier_norm),
        "addons": {
            "music": None,
            "voice": None,
            "subtitle": None,
            "dub": None,
            "subtitle_translate": None,
            "subtitle_plus_dub": None,
        },
        "free_items": [],
        "paid_items": [],
        "discounts": [],
        "total_xu": 0,
        "origin_screen": str(state.get("origin_screen") or "video_tier_detail"),
        "current_screen": current_screen,
        "screen_stack": list(state.get("screen_stack") or ["video_tier_detail", current_screen]),
        "confirmed": False,
        "billable": tier_norm not in VIDEO_ORDER_COMING_SOON_TIERS,
    }
    return video_order_recalculate(order, state)

def video_order_from_state(state: dict | None = None, user_id=None) -> dict:
    state = dict(state or {})
    existing = dict(state.get("video_order") or {})
    tier = normalize_video_tier(existing.get("tier") or state.get("video_tier") or (state.get("pending_payload") or {}).get("video_tier") or "low")
    if existing:
        order = {
            **video_order_create(user_id, tier, state.get("pending_payload") or {}, state, existing.get("current_screen") or "video_addon_menu"),
            **existing,
        }
        order["tier"] = tier
    else:
        order = video_order_create(user_id, tier, state.get("pending_payload") or {}, state, "video_addon_menu")
    return video_order_recalculate(order, state)

def video_order_paid_addons_allowed(order_or_tier) -> bool:
    tier = normalize_video_tier(order_or_tier.get("tier") if isinstance(order_or_tier, dict) else order_or_tier)
    return video_tier_allows_paid_addons(tier) and tier not in VIDEO_ORDER_COMING_SOON_TIERS

def video_order_music_item(state: dict, order: dict) -> tuple[dict | None, dict | None]:
    matrix = video_addon_pricing_matrix()
    pending = dict(state.get("pending_payload") or {})
    finalization = dict(state.get("video_finalization") or pending.get("video_finalization") or {})
    option = str(
        state.get("current_video_music_choice")
        or state.get("current_video_music_option")
        or pending.get("music_choice_key")
        or pending.get("music_option")
        or finalization.get("music_choice")
        or finalization.get("music_mode")
        or ""
    ).strip().lower()
    if not option:
        return None, None
    if option in {"none", "off", "no"}:
        return {"key": "music_none", "label": "Không thêm nhạc", "price_xu": 0}, None
    if option in {"suggested", "library", "stock", "stock_music", "music_library"}:
        item = matrix["stock_music_library"]
        return {"key": "stock_music_library", "label": item["label"], "price_xu": 0}, None
    if option in {"sfx", "stock_sfx", "sfx_library"}:
        return {"key": "stock_sfx_library", "label": "SFX từ kho có sẵn", "price_xu": 0}, None
    if option in {"uploaded", "upload", "user_media", "media", "my_media"}:
        return {"key": "user_audio_media", "label": "Audio trong Media của tôi", "price_xu": 0}, None
    if option in {"ai", "ai_music", "music_ai", "suno"}:
        item = matrix["suno_music"]
        return None, {"key": "suno_music", "label": item["label"], "price_xu": int(item.get("price_xu") or 0)}
    if option in {"sfx_ai"}:
        item = matrix["sfx_ai"]
        return None, {"key": "sfx_ai", "label": item["label"], "price_xu": int(item.get("price_xu") or 0)}
    return {"key": "music_planning", "label": "Gợi ý mood/nhạc trong kế hoạch", "price_xu": 0}, None

def video_order_voice_item(state: dict, order: dict) -> tuple[dict | None, dict | None]:
    matrix = video_addon_pricing_matrix()
    pending = dict(state.get("pending_payload") or {})
    finalization = dict(state.get("video_finalization") or pending.get("video_finalization") or {})
    option = str(
        state.get("current_video_voice_choice")
        or pending.get("voice_choice")
        or finalization.get("voice_choice")
        or finalization.get("voice_mode")
        or ""
    ).strip().lower()
    if not option:
        return None, None
    if option in {"none", "off", "no"}:
        return {"key": "voice_none", "label": "Không thêm giọng", "price_xu": 0}, None
    if option in {"default_female", "default_female_free", "female", "female_free"}:
        return {"key": "voice_default_female", "label": "Giọng nữ mặc định", "price_xu": 0}, None
    if option in {"default_male", "default_male_free", "male", "male_free"}:
        return {"key": "voice_default_male", "label": "Giọng nam mặc định", "price_xu": 0}, None
    if option in {"default_neutral", "default_neutral_free", "neutral", "neutral_free"}:
        return {"key": "voice_default_neutral", "label": "Giọng mặc định sẵn sàng", "price_xu": 0}, None
    if option in {"saved_voice", "saved_voice_free", "voice_profile", "profile"}:
        return {"key": "voice_saved_profile", "label": "Voice đã lưu", "price_xu": 0}, None
    if option in {"paid_clone", "voice_clone", "voice_clone_create"}:
        item = matrix["voice_clone_create"]
        user_token = str(order.get("user_id") or state.get("user_id") or pending.get("user_id") or "").strip()
        profile_id = _safe_int(
            state.get("current_video_voice_profile_id")
            or pending.get("voice_profile_id")
            or finalization.get("voice_profile_id"),
            0,
        )
        price = voice_profile_storage_price_xu(user_token, PRODUCT_CONTEXT_VIDEO_ADDON, profile_id) if user_token else int(VOICE_PROFILE_PRICE_XU or 0)
        return None, {"key": "voice_clone_create", "label": item["label"], "price_xu": max(0, int(price or 0))}
    if option in {"advanced_dubbing", "advanced_voice"}:
        item = matrix["voice_advanced"]
        return None, {"key": "voice_advanced", "label": item["label"], "price_xu": int(item.get("price_xu") or 0)}
    return None, None

def video_scene_discount_percent(scene_count) -> int:
    count = max(1, min(20, safe_int(scene_count, 1)))
    if count == 1:
        return 100
    if count <= 9:
        return 90
    if count <= 19:
        return 85
    return 80

def video_scene_discount_multiplier(scene_count) -> float:
    return video_scene_discount_percent(scene_count) / 100.0

def calculate_scene_video_price(package_base_xu, scene_count) -> int:
    base = max(0, safe_int(package_base_xu, 0))
    count = max(1, min(20, safe_int(scene_count, 1)))
    percent = video_scene_discount_percent(count)
    return int(round(base * count * (percent / 100.0)))

def video_order_recalculate(order: dict, state: dict | None = None) -> dict:
    order = dict(order or {})
    state = dict(state or {})
    matrix = video_addon_pricing_matrix()
    tier = normalize_video_tier(order.get("tier") or state.get("video_tier") or "low")
    payload = video_tier_payload(tier)
    base_price = int(order.get("base_price_xu") or payload.get("cost") or video_tier_cost_xu(tier) or 0)
    existing_addons = dict(order.get("addons") or {})
    free_items = [
        item for item in video_order_normalize_items(order.get("free_items"))
        if str(item.get("key") or "") not in VIDEO_ORDER_MANAGED_FREE_KEYS
    ]
    paid_items = []
    order["addons"] = dict(existing_addons)
    order["addons"].update({"music": None, "voice": None, "subtitle": None, "dub": None, "subtitle_translate": None, "subtitle_plus_dub": None})

    music_free, music_paid = video_order_music_item(state, order)
    if music_free:
        free_items.append(music_free)
        order["addons"]["music"] = music_free["key"]
    if music_paid:
        order["addons"]["music"] = music_paid["key"]
        if video_order_paid_addons_allowed(tier):
            paid_items.append(music_paid)

    voice_free, voice_paid = video_order_voice_item(state, order)
    if voice_free:
        free_items.append(voice_free)
        order["addons"]["voice"] = voice_free["key"]
    if voice_paid:
        order["addons"]["voice"] = voice_paid["key"]
        if video_order_paid_addons_allowed(tier):
            paid_items.append(voice_paid)

    subtitle = str(state.get("current_video_subtitle_option") or existing_addons.get("subtitle") or "none").strip().lower()
    dubbing = str(state.get("current_video_dubbing_option") or existing_addons.get("dub") or "none").strip().lower()
    translated = bool(state.get("translation_enabled") or "translated" in subtitle or "translated" in dubbing)
    duration_seconds = max(1, int(order.get("requested_seconds") or VIDEO_ORDER_DEFAULT_BASE_SECONDS))
    voice_addon_key = str((order.get("addons") or {}).get("voice") or "").strip().lower()
    if (
        dubbing not in {"", "none"}
        and subtitle in {"", "none"}
        and not translated
        and voice_addon_key in {"voice_default_female", "voice_default_male", "voice_default_neutral"}
    ):
        dubbing = "none"
        order["addons"]["dub"] = None
    if tier == "low":
        subtitle = "none"
        dubbing = "none"
        translated = False
    if subtitle not in {"", "none"} and dubbing not in {"", "none"}:
        key = "subtitle_plus_dubbing"
        breakdown = subtitle_dub_price_breakdown(key, duration_seconds)
        price = int(breakdown["total_xu"])
        label = breakdown["label"]
        order["addons"]["subtitle_plus_dub"] = key
        if video_order_paid_addons_allowed(tier):
            paid_items.append({"key": key, "label": label, "price_xu": price})
    elif subtitle not in {"", "none"}:
        key = "subtitle_translate" if translated else "subtitle_auto"
        order["addons"]["subtitle"] = key
        if translated:
            order["addons"]["subtitle_translate"] = key
        if video_order_paid_addons_allowed(tier):
            breakdown = subtitle_dub_price_breakdown("translate_subtitle" if translated else "subtitle", duration_seconds)
            paid_items.append({"key": key, "label": breakdown["label"], "price_xu": int(breakdown["total_xu"])})
    elif dubbing not in {"", "none"}:
        key = "dubbing_default"
        order["addons"]["dub"] = key
        if video_order_paid_addons_allowed(tier):
            breakdown = subtitle_dub_price_breakdown("dubbing", duration_seconds)
            paid_items.append({"key": key, "label": breakdown["label"], "price_xu": int(breakdown["total_xu"])})

    if not free_items:
        free_items.extend([
            {"key": "prompt_script_templates", "label": "Prompt/kịch bản mẫu", "price_xu": 0},
            {"key": "save_to_media_vault", "label": "Lưu kế hoạch/kết quả trong hạn mức", "price_xu": 0},
        ])
    if tier == "low":
        paid_items = []
        order["addons"].update({"voice": None, "subtitle": None, "dub": None, "subtitle_translate": None, "subtitle_plus_dub": None})

    scene_count = max(1, min(20, safe_int(
        order.get("scene_count")
        or state.get("selected_scene_count")
        or state.get("scene_count")
        or (state.get("pending_payload") or {}).get("selected_scene_count")
        or (state.get("pending_payload") or {}).get("scene_count")
        or (state.get("source_payload") or {}).get("selected_scene_count")
        or (state.get("video_project") or {}).get("selected_scene_count")
        or VIDEO_ORDER_DEFAULT_BASE_SCENES,
        VIDEO_ORDER_DEFAULT_BASE_SCENES,
    )))
    scene_discount_percent = video_scene_discount_percent(scene_count)
    scene_discount_multiplier = video_scene_discount_multiplier(scene_count)
    scene_video_xu = calculate_scene_video_price(base_price, scene_count)
    addon_fee_xu = sum(int(item.get("price_xu") or 0) for item in paid_items)
    discount_items = [item for item in video_order_normalize_items(order.get("discounts")) if int(item.get("price_xu") or 0) > 0 and item.get("valid")]
    subtotal = max(0, scene_video_xu + addon_fee_xu)
    discount_total = min(subtotal, sum(int(item.get("price_xu") or 0) for item in discount_items))
    total = max(0, subtotal - discount_total)
    if subtotal > 0 and total <= 0 and not discount_items:
        total = subtotal
    order.update({
        "tier": tier,
        "tier_name": str(payload.get("label") or video_tier_short_label(tier, "vi")),
        "base_price_xu": base_price,
        "scene_count": scene_count,
        "scene_discount": scene_discount_multiplier,
        "scene_discount_percent": scene_discount_percent,
        "scene_video_xu": scene_video_xu,
        "addon_fee_xu": addon_fee_xu,
        "free_items": video_order_dedupe_items(free_items),
        "paid_items": video_order_dedupe_items(paid_items),
        "discounts": discount_items,
        "total_xu": total,
        "estimated_vnd": total * int(XU_TO_VND or 100),
        "billable": tier not in VIDEO_ORDER_COMING_SOON_TIERS,
    })
    return order

def video_order_push_screen(order: dict, screen: str) -> dict:
    order = dict(order or {})
    screen = str(screen or "video_addon_menu")
    stack = [str(item) for item in (order.get("screen_stack") or []) if str(item or "").strip()]
    if not stack:
        stack = ["video_tier_detail"]
    if stack[-1] != screen:
        stack.append(screen)
    order["current_screen"] = screen
    order["screen_stack"] = stack[-8:]
    return order

def video_order_back_screen(order: dict, fallback: str = "video_addon_menu") -> dict:
    order = dict(order or {})
    current = str(order.get("current_screen") or "")
    stack = [str(item) for item in (order.get("screen_stack") or []) if str(item or "").strip()]
    if stack and current and stack[-1] == current:
        stack.pop()
    target = stack[-1] if stack else fallback
    order["current_screen"] = target
    order["screen_stack"] = stack or [target]
    return order

def video_order_to_price_preview(order: dict, state: dict | None = None) -> dict:
    order = video_order_recalculate(order, state)
    subtitle_xu = sum(int(item.get("price_xu") or 0) for item in order.get("paid_items") or [] if "phụ đề" in str(item.get("label") or "").lower() or "subtitle" in str(item.get("key") or ""))
    dubbing_xu = sum(int(item.get("price_xu") or 0) for item in order.get("paid_items") or [] if "lồng tiếng" in str(item.get("label") or "").lower() or "dub" in str(item.get("key") or ""))
    music_xu = sum(int(item.get("price_xu") or 0) for item in order.get("paid_items") or [] if "music" in str(item.get("key") or "") or "suno" in str(item.get("key") or "") or "sfx" in str(item.get("key") or ""))
    addon_xu = sum(int(item.get("price_xu") or 0) for item in order.get("paid_items") or [])
    duration = int(order.get("requested_seconds") or VIDEO_FINAL_DEFAULT_SECONDS)
    segment_seconds = int(order.get("scene_duration_seconds") or (state or {}).get("current_video_segment_seconds") or VIDEO_FINAL_DEFAULT_SCENE_SECONDS)
    return {
        "duration_seconds": duration,
        "processing_type": (state or {}).get("current_video_processing_type") or "ai_text_to_video",
        "quality_tier": order.get("quality_level") or video_quality_from_tier(order.get("tier")),
        "segments": max(1, int(math.ceil(duration / max(1, segment_seconds)))),
        "segment_seconds": segment_seconds,
        "scene_count": int(order.get("scene_count") or max(1, int(math.ceil(duration / max(1, segment_seconds))))),
        "scene_duration_seconds": segment_seconds,
        "preview_duration_seconds": int(order.get("preview_duration_seconds") or VIDEO_PREVIEW_DEFAULT_SECONDS),
        "preview_enabled": bool(order.get("preview_enabled")),
        "preview_locked_reason": str(order.get("preview_locked_reason") or ""),
        "music_option": (state or {}).get("current_video_music_option") or "none",
        "base_video_xu": int(order.get("scene_video_xu") or order.get("base_price_xu") or 0),
        "package_base_xu": int(order.get("base_price_xu") or 0),
        "scene_discount": float(order.get("scene_discount") or video_scene_discount_multiplier(order.get("scene_count") or 1)),
        "scene_discount_percent": int(order.get("scene_discount_percent") or video_scene_discount_percent(order.get("scene_count") or 1)),
        "scene_video_xu": int(order.get("scene_video_xu") or 0),
        "music_xu": music_xu,
        "subtitle_xu": subtitle_xu,
        "dubbing_xu": dubbing_xu,
        "addon_xu": addon_xu,
        "raw_total_xu": int(order.get("total_xu") or 0),
        "discount_xu": 0,
        "total_xu": int(order.get("total_xu") or 0),
        "estimated_vnd": int(order.get("estimated_vnd") or 0),
        "video_order": order,
        "notes": ["Video price is calculated from the shared video_order."],
    }

def video_quote_selected_addon_keys(state: dict | None = None, order: dict | None = None) -> list[str]:
    state = dict(state or {})
    order = dict(order or {})
    pending = dict(state.get("pending_payload") or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(pending.get("video_finalization") or {}))
    finalization.update(dict(state.get("video_finalization") or {}))
    keys = []
    music_choice = str(
        state.get("current_video_music_choice")
        or state.get("current_video_music_option")
        or pending.get("music_choice_key")
        or pending.get("music_option")
        or finalization.get("music_choice")
        or finalization.get("music_mode")
        or "none"
    ).strip().lower()
    voice_choice = str(
        state.get("current_video_voice_choice")
        or pending.get("voice_choice")
        or finalization.get("voice_choice")
        or finalization.get("voice_mode")
        or "none"
    ).strip().lower()
    subtitle_choice = str(
        state.get("current_video_subtitle_option")
        or pending.get("subtitle_option")
        or finalization.get("subtitle_mode")
        or "none"
    ).strip().lower()
    dub_choice = str(
        state.get("current_video_dubbing_option")
        or pending.get("dubbing_option")
        or finalization.get("subtitle_dub_choice")
        or "none"
    ).strip().lower()
    if music_choice not in VIDEO_ADDON_NONE_VALUES:
        keys.append("music")
    voice_is_free_default = voice_choice in VIDEO_FREE_VOICE_VALUES
    if voice_choice not in VIDEO_ADDON_NONE_VALUES and not voice_is_free_default:
        keys.append("voice")
    if subtitle_choice not in VIDEO_ADDON_NONE_VALUES:
        keys.append("subtitle")
    free_default_dub = voice_is_free_default and dub_choice in {"dub_original", "dubbing", "dub", "voice", "voice_default"}
    if dub_choice not in VIDEO_ADDON_NONE_VALUES and not free_default_dub:
        keys.append("dubbing")
    for field, key in (
        ("music_enabled", "music"),
        ("voice_enabled", "voice"),
        ("subtitle_enabled", "subtitle"),
        ("dub_enabled", "dubbing"),
        ("subtitle_dub_enabled", "subtitle_dub"),
        ("translation_enabled", "translation"),
    ):
        if finalization.get(field):
            keys.append(key)
    for item in list(order.get("paid_items") or []):
        item_key = str(item.get("key") or "").strip().lower()
        if item_key and item_key not in {"prompt_script_templates", "save_to_media_vault", "music_none", "voice_none"}:
            keys.append(item_key)
    return list(dict.fromkeys(keys))

def calculate_video_quote(session: dict | None = None) -> dict:
    state = dict(session or {})
    order = video_order_from_state(state, state.get("user_id") or state.get("owner_user_id"))
    scene_sources = (
        state,
        dict(state.get("pending_payload") or {}),
        dict(state.get("source_payload") or {}),
        dict(state.get("video_project") or {}),
    )
    explicit_scene_count = next(
        (
            safe_int(source.get("selected_scene_count") or source.get("scene_count"), 0)
            for source in scene_sources
            if safe_int(source.get("selected_scene_count") or source.get("scene_count"), 0) > 0
        ),
        0,
    )
    # Old confirmations created before the package-first flow have no scene
    # selection. Preserve those as one clip instead of pricing/guarding them as
    # the former three-scene display default.
    if explicit_scene_count <= 0:
        order["scene_count"] = 1
        order["requested_seconds"] = TASK3D_SCENE_SECONDS
        order = video_order_recalculate(order, state)
    pricing = video_order_to_price_preview(order, state)
    order = dict(pricing.get("video_order") or order)
    tier = normalize_video_tier(order.get("tier") or state.get("video_tier") or (state.get("pending_payload") or {}).get("video_tier") or "low")
    package_base_xu = int(order.get("base_price_xu") or video_tier_cost_xu(tier) or 0)
    scene_count = max(1, min(20, safe_int(order.get("scene_count") or pricing.get("scene_count") or 1, 1)))
    estimated_seconds = max(1, safe_int(
        order.get("requested_seconds")
        or pricing.get("duration_seconds")
        or scene_count * safe_int(order.get("scene_duration_seconds") or TASK3D_SCENE_SECONDS, TASK3D_SCENE_SECONDS),
        scene_count * TASK3D_SCENE_SECONDS,
    ))
    scene_discount = float(order.get("scene_discount") or video_scene_discount_multiplier(scene_count))
    scene_discount_percent = int(order.get("scene_discount_percent") or video_scene_discount_percent(scene_count))
    scene_video_xu = int(order.get("scene_video_xu") or calculate_scene_video_price(package_base_xu, scene_count))
    addon_fee_xu = int(order.get("addon_fee_xu") or sum(int(item.get("price_xu") or 0) for item in order.get("paid_items") or []))
    legacy_preview = dict(state.get("current_video_price_preview") or (state.get("pending_payload") or {}).get("video_price_preview") or {})
    addon_fee_xu = max(addon_fee_xu, safe_int(legacy_preview.get("addon_xu"), 0))
    total_xu = max(int(order.get("total_xu") or 0), scene_video_xu + addon_fee_xu)
    package_id = {
        "low": "package_200",
        "basic": "package_300",
        "common": "package_400",
        "advanced": "package_500",
        "standard": "package_600",
        "high": "package_800",
        "future_1000": "package_1000",
        "future_1200": "package_1200",
        "future_1500": "package_1500",
    }.get(tier, f"package_{package_base_xu}")
    package_label = str(order.get("tier_name") or video_tier_short_label(tier, "vi"))
    paid_items = video_order_dedupe_items(order.get("paid_items") or [])
    free_items = video_order_dedupe_items(order.get("free_items") or [])
    line_items = [
        {
            "key": "scene_video",
            "label": "Video theo cảnh",
            "price_xu": scene_video_xu,
            "scene_count": scene_count,
            "package_base_xu": package_base_xu,
            "discount_percent": scene_discount_percent,
        },
        *paid_items,
    ]
    package_200 = tier == "low" or package_base_xu == int(VIDEO_LOW_COST_XU or 200)
    selected_addons = video_quote_selected_addon_keys(state, order)
    addon_classification = classify_video_addons_for_package({**state, "video_order": order})
    paid_addon_items = list(addon_classification.get("paid_addons") or [])
    is_package_200_valid = bool(
        not package_200
        or (scene_count == 1 and addon_fee_xu == 0 and total_xu == int(VIDEO_LOW_COST_XU or 200) and not paid_addon_items)
    )
    warnings = []
    if package_200 and not is_package_200_valid:
        warnings.append("package_200_invalid")
    if scene_count > 1 and not video_multiscene_public_ready(scene_count):
        warnings.append("multiscene_not_public_ready")
    return {
        "package_id": package_id,
        "package_label": package_label,
        "package_base_xu": package_base_xu,
        "tier": tier,
        "scene_count": scene_count,
        "estimated_seconds": estimated_seconds,
        "scene_discount": scene_discount,
        "scene_discount_percent": scene_discount_percent,
        "scene_video_xu": scene_video_xu,
        "addon_fee_xu": addon_fee_xu,
        "total_xu": total_xu,
        "estimated_vnd": int(order.get("estimated_vnd") or total_xu * int(XU_TO_VND or 100)),
        "free_items": free_items,
        "paid_items": paid_items,
        "selected_addons": selected_addons,
        "paid_addon_items": paid_addon_items,
        "line_items": line_items,
        "is_package_200_valid": is_package_200_valid,
        "warnings": warnings,
        "video_order": order,
        "pricing": pricing,
    }

