def _diagnostic_message_args(update: Update, context: ContextTypes.DEFAULT_TYPE) -> list[str]:
    raw_args = getattr(context, "args", None)
    if raw_args is not None:
        return [str(item or "").strip() for item in raw_args if str(item or "").strip()]
    message = getattr(update, "message", None)
    text = str(getattr(message, "text", "") or "")
    return [part.strip() for part in text.split()[1:] if part.strip()]


async def _reply_product_claim_diagnostic(update: Update, text: str):
    message = getattr(update, "message", None)
    if message is None:
        return None
    try:
        return await message.reply_text(text, parse_mode="HTML")
    except Exception as exc:
        logger.warning("product video worker claim diagnostic reply failed: %s", type(exc).__name__)
        plain = html.unescape(str(text or ""))
        for tag in ("<b>", "</b>", "<code>", "</code>"):
            plain = plain.replace(tag, "")
        return await message.reply_text(plain)


async def cmd_tool_test_video_product_worker_claim(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    if not is_admin_user(uid):
        return await update.message.reply_text(VIDEO_B14_PUBLIC_UNSTABLE_TOOL_MESSAGE)
    args = _diagnostic_message_args(update, context)
    if "--no-charge" not in args:
        return await update.message.reply_text("Dùng: /tool_test_video_product_worker_claim --no-charge")
    flags = worker_auth.worker_api_runtime_flags(LOCAL_WORKER_TOKEN)
    if not flags.get("worker_api_enabled"):
        return await update.message.reply_text(
            "⚠️ <b>Product video worker diagnostic</b>\n\n"
            "Không tạo job vì worker API chưa sẵn sàng.\n"
            "• Error: <code>worker_api_disabled</code>\n"
            "• Trừ Xu: Không",
            parse_mode="HTML",
        )
    try:
        from services.video_real_render_connector import real_video_provider_readiness

        readiness = real_video_provider_readiness()
    except Exception as exc:
        readiness = {"ok": False, "providers": [], "reason": type(exc).__name__}
    created = {}
    claimability = {}
    product = {"last": {}}
    try:
        conn = db_connect()
        try:
            created = remote_worker_api.create_product_video_worker_claim_test_job(conn, admin_user_id=safe_int(uid, 0), scene_count=1, duration_seconds=6)
            if created.get("ok"):
                job_id = safe_int((created.get("job") or {}).get("id") or (created.get("job") or {}).get("job_id"), 0)
                claimability = remote_worker_api.explain_product_video_claimability(conn, job_id, owner_only=True, public_enabled=False)
                product = remote_worker_api.remote_worker_product_video_queue_snapshot(conn)
                set_system_setting("remote_worker:last_product_video_job_id", str(job_id or ""), "last product video worker diagnostic job", uid)
        finally:
            conn.close()
    except sqlite3.Error as exc:
        logger.exception("product video worker diagnostic db_error")
        return await _reply_product_claim_diagnostic(
            update,
            "⚠️ <b>Product video worker diagnostic</b>\n\n"
            "Chưa tạo được job kiểm tra. Bot chưa trừ Xu.\n"
            "• Error: <code>db_error</code>\n"
            "• Next: kiểm tra DB/log Railway.",
        )
    except (KeyError, TypeError, ValueError) as exc:
        logger.exception("product video worker diagnostic invalid_payload")
        return await _reply_product_claim_diagnostic(
            update,
            "⚠️ <b>Product video worker diagnostic</b>\n\n"
            "Payload kiểm tra chưa hợp lệ. Bot chưa trừ Xu.\n"
            "• Error: <code>invalid_payload</code>",
        )
    except Exception as exc:
        logger.exception("product video worker diagnostic unexpected_error")
        error_id = hashlib.sha1(f"{type(exc).__name__}:{str(exc)[:80]}".encode("utf-8", errors="ignore")).hexdigest()[:8]
        return await _reply_product_claim_diagnostic(
            update,
            "⚠️ <b>Product video worker diagnostic</b>\n\n"
            "Chưa tạo được job kiểm tra. Bot chưa trừ Xu.\n"
            f"• Error: <code>unexpected_error:{html.escape(error_id)}</code>",
        )
    if not created.get("ok"):
        reason = str(created.get("reason") or "create_failed")
        category = "missing_config" if "config" in reason else ("invalid_payload" if "required" in reason else reason)
        return await _reply_product_claim_diagnostic(
            update,
            f"⚠️ <b>Product video worker diagnostic</b>\n\nChưa tạo được job kiểm tra: <code>{html.escape(category)}</code>. Chưa trừ Xu.",
        )
    job = dict(created.get("job") or {})
    project = dict(created.get("project") or {})
    job_id = safe_int(job.get("id") or job.get("job_id"), 0)
    last = dict(product.get("last") or {})
    claimed = bool(str(last.get("worker_id") or "").strip() and safe_int(last.get("job_id"), 0) == job_id)
    provider_ready = bool(readiness.get("ok"))
    claimable = bool(claimability.get("claimable"))
    claim_reason = str(claimability.get("reason") or ("claimable" if claimable else "claim_route_missing"))
    providers = readiness.get("providers") if isinstance(readiness.get("providers"), list) else []
    provider_lines = []
    for item in providers:
        provider_lines.append(f"• {html.escape(str(item.get('provider') or '-'))}: <code>{'ready' if item.get('configured') else 'missing'}</code>")
    lines = [
        "🧪 <b>Product video worker claim diagnostic</b>",
        "",
        "Đã tạo job kiểm tra claim product_video. Lệnh này không tạo MP4, không dùng test pattern, không gọi provider, không trừ Xu.",
        f"• Mã xử lý: <code>{html.escape(str(job_id or '-'))}</code>",
        f"• Project: <code>{html.escape(str(project.get('project_id') or '-'))}</code>",
        "• source: <code>product_video</code>",
        "• render_mode: <code>real</code>",
        "• test_pattern: <code>false</code>",
        "• admin_video_delivery: <code>false</code>",
        "• Diagnostic mode: <code>claim_only</code>",
        "• Provider call: <code>NO</code>",
        f"• Claim product route: <code>{'CLAIMED' if claimed else 'WAITING'}</code>",
        f"• Claimable by --owner-product-video: <code>{'YES' if claimable else 'NO'}</code>",
        f"• Claim reason: <code>{html.escape(claim_reason)}</code>",
        f"• Last worker: <code>{html.escape(str(last.get('worker_id') or '-'))}</code>",
        f"• Job left queued for VPS: <code>{'NO' if claimed else 'YES'}</code>",
        f"• Worker API token: <code>{'YES' if flags.get('worker_api_enabled') else 'NO'}</code>",
        f"• Real provider ready: <code>{'YES' if provider_ready else 'NO'}</code>",
        f"• Updated: <code>{html.escape(vn_now_text())}</code>",
        "",
        "Provider readiness:",
        *(provider_lines or ["• none: <code>not configured</code>"]),
        "",
        "Worker đã claim job kiểm tra. Theo dõi tiếp bằng /video_worker_status."
        if claimed else "Đã tạo job kiểm tra video thật nhưng chưa có worker claim. Job đã để nguyên trong hàng đợi để VPS claim.",
        "Nếu VPS vẫn idle, kiểm tra service `toanaas-worker-owner-product-video`." if not claimed else "",
        "",
        "VPS owner/admin product service:",
        "<code>systemctl status toanaas-worker-owner-product-video --no-pager -l</code>",
        "<code>journalctl -u toanaas-worker-owner-product-video -n 100 --no-pager -l</code>",
        "<code>python remote_worker.py --owner-product-video --once</code>",
        "",
        "VPS product service khi mở public:",
        "<code>python remote_worker.py --product-video --once</code>",
    ]
    return await _reply_product_claim_diagnostic(update, "\n".join(lines))


def _video_provider_readiness_lines(readiness: dict | None = None) -> list[str]:
    providers = (readiness or {}).get("providers")
    if not isinstance(providers, list):
        providers = []
    lines = []
    for item in providers:
        provider = html.escape(str((item or {}).get("provider") or "-"))
        lines.append(f"• {provider}: <code>{'ready' if (item or {}).get('configured') else 'missing'}</code>")
    return lines or ["• none: <code>not configured</code>"]


def _video_worker_last_job_note(last: dict) -> str:
    status = str((last or {}).get("status") or "").strip().lower()
    worker_id = str((last or {}).get("worker_id") or "").strip()
    if status in {"failed", "error"}:
        return "old_failed_job"
    if status == "queued" and not worker_id:
        return "waiting_for_owner_product_worker"
    if status == "processing" and worker_id:
        return "claimed"
    return "-"


def _video_worker_next_action(status: dict, product: dict, readiness: dict, last: dict) -> str:
    last_status = str((last or {}).get("status") or "").strip().lower()
    if not (status or {}).get("worker_api_enabled"):
        return "Kiểm tra LOCAL_WORKER_TOKEN trên Railway trước."
    if last_status in {"failed", "error"}:
        return "Tạo diagnostic mới; không dùng job cũ để QA."
    if safe_int((product or {}).get("queued"), 0) > 0 and not str((last or {}).get("worker_id") or "").strip():
        return "Chạy owner-product --once để xem idle reason trên VPS."
    if not (readiness or {}).get("ok"):
        return "Kiểm tra provider readiness trước khi test product video thật."
    return "Chờ worker claim hoặc tạo diagnostic mới nếu cần."


