def public_video_combo_pricing_payload() -> list[dict]:
    return [item for item in video_combo_pricing_payload() if item.get("public", True) is not False]

def video_combo_pricing_payload() -> list[dict]:
    rows: list[dict] = []
    for code, entry in p0_21c_combo_catalog_payload(include_legacy=True).items():
        item = dict(entry)
        item["code"] = code
        item.setdefault("summary", entry.get("note") or "")
        item.setdefault("includes", package_items_summary(entry.get("items") or {}))
        item.setdefault("button_label", entry.get("button_label") or entry.get("label") or code)
        item.setdefault("rank_points", False)
        rows.append(item)
    return rows

def workflow_trend_analysis_cost_xu() -> int:
    return max(0, int(WORKFLOW_TREND_ANALYSIS_COST_XU or 0))

def workflow_script_storyboard_cost_xu() -> int:
    return max(0, int(WORKFLOW_SCRIPT_STORYBOARD_COST_XU or 0))

def workflow_prompt_pack_cost_xu() -> int:
    return max(0, int(WORKFLOW_PROMPT_PACK_COST_XU or 0))

def workflow_content_cost_xu() -> int:
    return workflow_trend_analysis_cost_xu() + workflow_script_storyboard_cost_xu() + workflow_prompt_pack_cost_xu()

def trend_workflow_content_cost_breakdown() -> dict:
    trend_cost = workflow_trend_analysis_cost_xu()
    script_cost = workflow_script_storyboard_cost_xu()
    prompt_pack_cost = workflow_prompt_pack_cost_xu()
    return {
        "trend_analysis": trend_cost,
        "script_storyboard": script_cost,
        "prompt_pack": prompt_pack_cost,
        "total": trend_cost + script_cost + prompt_pack_cost,
        "image_separate": image_base_cost_xu(),
        "video_separate": video_base_cost_xu(),
    }

def trend_workflow_billing_status_text() -> str:
    if not TREND_WORKFLOW_PUBLIC_ENABLED:
        return "public_off/admin_preview_no_xu"
    if not TREND_WORKFLOW_BILLING_ENABLED:
        return "public_on/billing_off"
    if TREND_WORKFLOW_REQUIRE_CONFIRM:
        return "public_on/confirm_before_deduct"
    return "public_on/billing_on_no_confirm"

