def normalize_package_item_type(value: str = "") -> str:
    raw = str(value or "").strip().lower().replace("-", "_").replace(" ", "_")
    aliases = {
        "video_low": "video_experience",
        "video_trial": "video_experience",
        "video_pho_thong": "video_common",
        "video_phothong": "video_common",
        "video_tieu_chuan": "video_standard",
        "video_tieuchuan": "video_standard",
        "image_standard_plus": "image_standard_warranty",
        "image_high_plus": "image_high_warranty",
    }
    item_type = aliases.get(raw, raw)
    return item_type if item_type in PACKAGE_ITEM_TYPES else ""

def package_item_display_name(item_type: str, lang: str = "vi") -> str:
    normalized = normalize_package_item_type(item_type)
    return PACKAGE_ITEM_LABELS.get(normalized, normalized or "-")

def package_item_type_for_image_tier(tier: str = "") -> str:
    tier_norm = normalize_image_tier(tier)
    return f"image_{tier_norm}"

def package_item_type_for_video_tier(tier: str = "") -> str:
    tier_norm = normalize_video_tier(tier)
    return {
        "low": "video_experience",
        "basic": "video_basic",
        "common": "video_common",
        "standard": "video_standard",
        "high": "video_high",
    }.get(tier_norm, "")

def package_catalog_entry(code: str, package_type: str = "") -> dict:
    catalog = package_catalog_payload()
    safe_code = str(code or "").strip().lower()
    safe_type = str(package_type or "").strip().lower()
    if safe_type in {"combo", "combos"}:
        return dict((catalog.get("combos") or {}).get(safe_code) or {})
    if safe_type in {"monthly", "month", "plan"}:
        return dict((catalog.get("monthly") or {}).get(safe_code) or {})
    for group in ("combos", "monthly"):
        entry = dict((catalog.get(group) or {}).get(safe_code) or {})
        if entry:
            entry["package_type"] = "combo" if group == "combos" else "monthly"
            return entry
    return {}

def package_purchase_price_vnd(package_type: str, code: str) -> int:
    package_type = "monthly" if str(package_type or "").strip().lower() in {"monthly", "month", "plan"} else "combo"
    code = str(code or "").strip().lower()
    entry = package_catalog_entry(code, package_type)
    if int((entry or {}).get("price_vnd") or 0) > 0:
        return max(0, int(entry.get("price_vnd") or 0))
    if package_type == "combo":
        for item in video_combo_pricing_payload():
            if str(item.get("code") or "").strip().lower() == code:
                return max(0, int(item.get("price_vnd") or 0))
        return 0
    monthly_prices = {
        "starter_monthly": MONTHLY_STARTER_PRICE_VND,
        "creator_monthly": MONTHLY_CREATOR_PRICE_VND,
        "shop_monthly": MONTHLY_SHOP_PRICE_VND,
        "pro_monthly": MONTHLY_PRO_PRICE_VND,
        "small_business_monthly": MONTHLY_SMALL_BUSINESS_PRICE_VND,
    }
    return max(0, int(monthly_prices.get(code) or 0))

def package_purchase_display_price(package_type: str, code: str) -> str:
    price = package_purchase_price_vnd(package_type, code)
    if price <= 0:
        return "liên hệ admin"
    if price % 1000 == 0:
        return f"{price // 1000}k"
    return f"{price:,}đ".replace(",", ".")

def package_purchase_kind_label(package_type: str) -> str:
    return "Gói tháng" if str(package_type or "").strip().lower() in {"monthly", "month", "plan", "task", "package"} else "Combo thành phẩm"

def package_purchase_description(package_type: str, code: str) -> str:
    package_type = "monthly" if str(package_type or "").strip().lower() in {"monthly", "month", "plan"} else "combo"
    safe_code = re.sub(r"[^a-zA-Z0-9]", "", str(code or "").upper())[:10]
    prefix = "AASMONTH" if package_type == "monthly" else "AASCOMBO"
    desc = f"{prefix}{safe_code}"[:25]
    return desc or "TOANAASPKG"

