def parse_shopaikey_usage(payload: dict) -> dict:
    data = payload if isinstance(payload, dict) else {}
    def num(name):
        try:
            value = data.get(name)
            return float(value) if value is not None and value != "" else 0.0
        except Exception:
            return 0.0
    total = num("total")
    used = num("used")
    balance = num("balance")
    remaining = num("remaining")
    remaining_percent = round((remaining / total * 100), 2) if total > 0 else 0.0
    return {
        "total": total,
        "used": used,
        "balance": balance,
        "remaining": remaining,
        "remaining_percent": remaining_percent,
        "group_name": str(data.get("group_name") or ""),
        "token_name": str(data.get("token_name") or ""),
        "schema_known": any(key in data for key in ("total", "used", "balance", "remaining")),
    }

def format_quota_number(value) -> str:
    try:
        number = float(value)
    except Exception:
        return "0"
    if number.is_integer():
        return str(int(number))
    return f"{number:.2f}".rstrip("0").rstrip(".")

def parse_key_value_detail(detail: str) -> dict:
    parsed = {}
    for part in str(detail or "").split(";"):
        if "=" not in part:
            continue
        key, value = part.split("=", 1)
        parsed[key.strip()] = value.strip()
    return parsed

def shopaikey_usage_from_debug_detail(event: dict) -> dict:
    detail = parse_key_value_detail(event.get("detail") or "")
    usage = {
        "total": detail.get("total", ""),
        "used": detail.get("used", ""),
        "balance": detail.get("balance", ""),
        "remaining": detail.get("remaining", ""),
        "remaining_percent": detail.get("remaining_percent", ""),
        "group_name": detail.get("group", ""),
        "token_name": "",
        "last_at": event.get("created_at") or "",
    }
    return {key: str(value or "") for key, value in usage.items()}

def save_shopaikey_usage_snapshot(usage: dict, updated_by=""):
    safe_usage = {
        "total": format_quota_number(usage.get("total")),
        "used": format_quota_number(usage.get("used")),
        "balance": format_quota_number(usage.get("balance")),
        "remaining": format_quota_number(usage.get("remaining")),
        "remaining_percent": format_quota_number(usage.get("remaining_percent")),
        "group_name": str(usage.get("group_name") or "")[:120],
        "token_name": mask_key_fingerprint(usage.get("token_name") or ""),
    }
    set_system_setting("shopaikey_usage_total", safe_usage["total"], "ShopAIKey usage total", updated_by)
    set_system_setting("shopaikey_usage_used", safe_usage["used"], "ShopAIKey usage used", updated_by)
    set_system_setting("shopaikey_usage_balance", safe_usage["balance"], "ShopAIKey usage balance", updated_by)
    set_system_setting("shopaikey_usage_remaining", safe_usage["remaining"], "ShopAIKey usage remaining", updated_by)
    set_system_setting("shopaikey_usage_remaining_percent", safe_usage["remaining_percent"], "ShopAIKey usage remaining percent", updated_by)
    set_system_setting("shopaikey_usage_group_name", safe_usage["group_name"], "ShopAIKey usage group", updated_by)
    set_system_setting("shopaikey_usage_token_name", safe_usage["token_name"], "ShopAIKey usage token masked", updated_by)
    set_system_setting("shopaikey_usage_snapshot_json", json.dumps(safe_usage, ensure_ascii=False), "ShopAIKey usage sanitized snapshot", updated_by)
    set_system_setting("shopaikey_usage_last_at", now_text(), "ShopAIKey usage checked", updated_by)
    evaluate_shopaikey_usage_freeze(safe_usage, updated_by)

def shopaikey_last_usage_snapshot() -> dict:
    snapshot = {
        "total": get_system_setting("shopaikey_usage_total", ""),
        "used": get_system_setting("shopaikey_usage_used", ""),
        "balance": get_system_setting("shopaikey_usage_balance", ""),
        "remaining": get_system_setting("shopaikey_usage_remaining", ""),
        "remaining_percent": get_system_setting("shopaikey_usage_remaining_percent", ""),
        "group_name": get_system_setting("shopaikey_usage_group_name", ""),
        "token_name": get_system_setting("shopaikey_usage_token_name", ""),
        "last_at": get_system_setting("shopaikey_usage_last_at", ""),
    }
    if not any(snapshot.get(key) for key in ("total", "remaining", "group_name")):
        try:
            data = json.loads(get_system_setting("shopaikey_usage_snapshot_json", "{}") or "{}")
            if isinstance(data, dict):
                for key in ("total", "used", "balance", "remaining", "remaining_percent", "group_name", "token_name"):
                    snapshot[key] = str(data.get(key) or "")
        except Exception:
            pass
    if not any(snapshot.get(key) for key in ("total", "remaining", "group_name", "remaining_percent")):
        debug_usage = shopaikey_usage_from_debug_detail(latest_api_debug_event("shopaikey", ["usage", "shopaikey_usage"]))
        for key, value in debug_usage.items():
            if value:
                snapshot[key] = value
    return snapshot

def shopaikey_usage_summary_text(usage: dict) -> str:
    if not any(usage.get(key) for key in ("total", "remaining", "group_name", "last_at")):
        return "not_checked"
    remaining = str(usage.get("remaining") or "-")
    total = str(usage.get("total") or "-")
    percent = str(usage.get("remaining_percent") or "-")
    group = str(usage.get("group_name") or "-")
    last_at = str(usage.get("last_at") or "-")
    return f"remaining {remaining} / total {total} ({percent}%) | group {group} | last {last_at}"

def save_shopaikey_chat_snapshot(result: dict, detail: str, updated_by=""):
    save_shopaikey_component_snapshot("chat", result, detail, updated_by)

def save_shopaikey_component_snapshot(component: str, result: dict, detail: str, updated_by=""):
    component = re.sub(r"[^a-z0-9_:-]", "_", str(component or "").strip().lower())
    if component not in {"chat", "tts", "image", "video"}:
        return
    status = str(result.get("status") or "UNKNOWN").upper()
    model = str(result.get("model") or "")
    if component == "chat":
        model = model or SHOPAIKEY_CHAT_MODEL or SHOPAIKEY_DEFAULT_MODEL or ""
    elif component == "tts":
        model = model or f"{SHOPAIKEY_TTS_MODEL or 'speech-2.6-turbo'}/{SHOPAIKEY_TTS_VOICE or 'male-qn-qingse'}"
    elif component == "image":
        model = model or SHOPAIKEY_IMAGE_MODEL or "nano-banana"
    elif component == "video":
        model = model or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast"
    safe_detail = str(detail or "")[:1000]
    prefix = f"shopaikey_{component}_last"
    set_system_setting(f"{prefix}_status", status, safe_detail, updated_by)
    set_system_setting(f"{prefix}_model", model, safe_detail, updated_by)
    set_system_setting(f"{prefix}_http", str(result.get("http_status") or 0), safe_detail, updated_by)
    set_system_setting(f"{prefix}_latency_ms", str(result.get("latency_ms") or 0), safe_detail, updated_by)
    set_system_setting(f"{prefix}_detail", safe_detail, safe_detail, updated_by)
    set_system_setting(f"{prefix}_at", now_text(), safe_detail, updated_by)

def shopaikey_component_status_snapshot(component: str, tool_names: list[str], debug_actions: list[str]) -> dict:
    component = re.sub(r"[^a-z0-9_:-]", "_", str(component or "").strip().lower())
    result = preferred_tool_test_result(*tool_names)
    status = str(result.get("status") or "NOT_TESTED").upper()
    prefix = f"shopaikey_{component}_last"
    model = get_system_setting(f"{prefix}_model", "")
    detail = result.get("detail") or get_system_setting(f"{prefix}_detail", "")
    tested_at = result.get("tested_at") or get_system_setting(f"{prefix}_at", "")
    if status in {"", "NOT_TESTED"}:
        status = get_system_setting(f"{prefix}_status", "NOT_TESTED") or "NOT_TESTED"
    if str(status or "").upper() in {"", "NOT_TESTED"}:
        event = latest_api_debug_event("shopaikey", debug_actions)
        if event:
            status = str(event.get("status") or "NOT_TESTED").upper()
            detail = detail or event.get("detail") or ""
            tested_at = tested_at or event.get("created_at") or ""
            detail_map = parse_key_value_detail(detail)
            model = model or detail_map.get("model", "")
    return {
        "status": status,
        "model": model,
        "detail": detail,
        "tested_at": tested_at,
    }

def shopaikey_status_event_is_newer(event_at: str, current_at: str) -> bool:
    event_dt = parse_now_text(event_at)
    current_dt = parse_now_text(current_at)
    if event_dt and current_dt:
        return event_dt > current_dt
    return bool(event_at and not current_at)

def normalize_shopaikey_video_snapshot(snapshot: dict) -> dict:
    snap = dict(snapshot or {})
    status = str(snap.get("status") or "NOT_TESTED").upper()
    tested_at = str(snap.get("tested_at") or "")
    output_confirmed = bool_from_runtime_value(get_system_setting("shopaikey_video_last_output_sent", ""), False)
    last_output = str(get_system_setting("shopaikey_video_last_output", "") or "").strip().lower()
    if output_confirmed or last_output == "confirmed" or video_gate_detail_has_output(snap.get("detail") or ""):
        if status in {"PASS_SUBMITTED", "SUBMITTED", "IN_PROGRESS", "PROCESSING", "RUNNING", "QUEUED", "PENDING", "NOT_TESTED", ""}:
            snap["status"] = "SUCCESS"
            detail = str(snap.get("detail") or "")
            confirmed_detail = "last_video_output=confirmed; output_sent=yes"
            snap["detail"] = detail if video_gate_detail_has_output(detail) else ((detail + "; " if detail else "") + confirmed_detail)
            snap["tested_at"] = get_system_setting("shopaikey_video_last_completed_at", "") or tested_at
            status = "SUCCESS"
            tested_at = str(snap.get("tested_at") or "")
    event = latest_api_debug_event("shopaikey", ["shopaikey_video_job", "tool_test_shopaikey_video", "quick_video_test", "tool_test_workflow_image_to_video"])
    event_status = str((event or {}).get("status") or "").upper()
    if event and event_status and event_status not in {"", "NOT_TESTED"}:
        event_success = event_status in {"PASS", "SUCCESS", "COMPLETED", "DONE", "SUCCEEDED", "LIVE_PASS"}
        preserve_confirmed_success = status == "SUCCESS" and (output_confirmed or last_output == "confirmed") and not event_success
        if not preserve_confirmed_success and (
            status in {"PASS_SUBMITTED", "IN_PROGRESS", "PROCESSING", "RUNNING", "QUEUED", "PENDING"}
            or shopaikey_status_event_is_newer(event.get("created_at") or "", tested_at)
        ):
            snap["status"] = event_status
            snap["detail"] = event.get("detail") or snap.get("detail") or ""
            snap["tested_at"] = event.get("created_at") or tested_at
            detail_map = parse_key_value_detail(snap.get("detail") or "")
            snap["model"] = snap.get("model") or detail_map.get("model", "")
            status = event_status
            tested_at = str(snap.get("tested_at") or "")
    if status in {"PASS_SUBMITTED", "SUBMITTED", "IN_PROGRESS", "PROCESSING", "RUNNING", "QUEUED", "PENDING"}:
        last_dt = parse_now_text(tested_at)
        max_age_seconds = max(300, int(SHOPAIKEY_VIDEO_JOB_MAX_AGE_MINUTES or 60) * 60)
        if last_dt and (datetime.now() - last_dt).total_seconds() > max_age_seconds:
            snap["status"] = "TIMEOUT_STALE"
            detail = str(snap.get("detail") or "")
            snap["detail"] = (detail + "; " if detail else "") + "video smoke exceeded configured maximum job age"
    return snap

