def extract_shopaikey_suno_task_id(payload) -> str:
    if isinstance(payload, str):
        return payload.strip()
    if not isinstance(payload, dict):
        return ""
    data = payload.get("data")
    if isinstance(data, str):
        return data.strip()
    candidates: list[str] = []

    def visit(value):
        if isinstance(value, dict):
            for key in ("task_id", "taskId", "taskID", "id"):
                raw = value.get(key)
                if isinstance(raw, (str, int)) and str(raw).strip():
                    candidates.append(str(raw).strip())
            for child in ("data", "result", "task", "job"):
                if child in value:
                    visit(value.get(child))
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return candidates[0] if candidates else ""

def _shopaikey_suno_status_raw(payload) -> str:
    values: list[str] = []

    def visit(value):
        if isinstance(value, dict):
            for key in ("status", "state", "task_status", "taskStatus"):
                raw = value.get(key)
                if isinstance(raw, str) and raw.strip():
                    values.append(raw.strip())
            for child in ("data", "result", "task", "job"):
                if child in value:
                    visit(value.get(child))
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    if values:
        return values[0]
    if isinstance(payload, dict):
        code = str(payload.get("code") or "").strip()
        if code:
            return code
    return ""

def extract_shopaikey_suno_audio_urls(payload) -> list[str]:
    urls: list[str] = []
    audio_keys = {
        "audio_url", "audioUrl", "audio", "download_url", "downloadUrl",
        "stream_url", "streamUrl", "source_audio_url", "sourceAudioUrl",
        "output_url", "outputUrl", "file_url", "fileUrl", "url",
    }

    def add_candidate(key: str, raw):
        if not isinstance(raw, str):
            return
        value = raw.strip()
        if not value.startswith(("http://", "https://")):
            return
        lowered_key = str(key or "").lower()
        lowered_url = value.lower()
        looks_audio = (
            "audio" in lowered_key
            or lowered_url.split("?", 1)[0].endswith((".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac"))
            or "/audio" in lowered_url
        )
        if looks_audio and value not in urls:
            urls.append(value)

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                if key in audio_keys:
                    add_candidate(key, child)
                visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return urls

SUNO_RESULT_FIELD_KEYS = (
    "status", "state", "result", "output",
    "audio_url", "url", "file_url", "download_url", "stream_url",
)
SUNO_AUDIO_EXTENSIONS = (".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac")

def suno_response_parsed_fields(payload) -> dict:
    fields = {key: False for key in SUNO_RESULT_FIELD_KEYS}

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                lowered = str(key or "").strip().lower()
                for field in fields:
                    if lowered == field:
                        fields[field] = True
                visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    return fields

def suno_result_parsed_fields(result: dict | None) -> dict:
    current = dict(result or {})
    fields = current.get("parsed_fields")
    if isinstance(fields, dict):
        return {key: bool(fields.get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    debug = current.get("raw_debug_admin_only")
    if isinstance(debug, dict):
        nested = debug.get("parsed_fields")
        if isinstance(nested, dict):
            return {key: bool(nested.get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    return {key: False for key in SUNO_RESULT_FIELD_KEYS}

def suno_parsed_fields_text(fields: dict | None) -> str:
    current = {key: bool((fields or {}).get(key)) for key in SUNO_RESULT_FIELD_KEYS}
    return ", ".join(f"{key}={'yes' if current.get(key) else 'no'}" for key in SUNO_RESULT_FIELD_KEYS)

def music_audio_url_has_acceptable_extension(url: str) -> bool:
    try:
        path = urlparse(str(url or "")).path.lower()
    except Exception:
        path = str(url or "").split("?", 1)[0].lower()
    return path.endswith(SUNO_AUDIO_EXTENSIONS) or "/audio" in path

async def _download_music_audio_url_bytes(url: str, timeout_seconds: float = 60.0) -> tuple[bytes, str, int]:
    audio_bytes, detail, http_status = await _download_audio_url_bytes(url, timeout_seconds=timeout_seconds)
    if not audio_bytes:
        return b"", detail, http_status
    detail_text = str(detail or "")
    if music_audio_url_has_acceptable_extension(url) or "content_type=audio/" in detail_text.lower():
        return audio_bytes, detail, http_status
    return b"", f"audio_mime_or_extension_missing; {sanitize_provider_status_text(detail_text, '', 180)}", http_status

def tool_test_result_audio_bytes_positive(result: dict | None) -> bool:
    current = dict(result or {})
    try:
        if int(current.get("output_bytes") or 0) > 0:
            return True
    except Exception:
        pass
    detail = str(current.get("detail") or current.get("message") or "")
    matches = re.findall(r"\bbytes=(\d+)\b", detail)
    return any(int(item or 0) > 0 for item in matches)

def extract_shopaikey_suno_media_presence(payload) -> dict:
    presence = {"audio": False, "video": False, "image": False}

    def visit(value):
        if isinstance(value, dict):
            for key, child in value.items():
                lowered_key = str(key or "").lower()
                raw = str(child or "").strip() if isinstance(child, str) else ""
                if raw.startswith(("http://", "https://")):
                    lowered_url = raw.lower().split("?", 1)[0]
                    if "audio" in lowered_key or lowered_url.endswith((".mp3", ".wav", ".m4a", ".aac", ".ogg", ".flac")):
                        presence["audio"] = True
                    if "video" in lowered_key or lowered_url.endswith((".mp4", ".mov", ".webm", ".mkv")):
                        presence["video"] = True
                    if "image" in lowered_key or lowered_url.endswith((".jpg", ".jpeg", ".png", ".webp")):
                        presence["image"] = True
                visit(child)
        elif isinstance(value, list):
            for item in value:
                visit(item)

    visit(payload)
    if extract_shopaikey_suno_audio_urls(payload):
        presence["audio"] = True
    return presence

def normalize_shopaikey_suno_fetch_status(payload, http_status: int = 0) -> str:
    raw = _shopaikey_suno_status_raw(payload).strip()
    lowered = raw.lower()
    has_audio = bool(extract_shopaikey_suno_audio_urls(payload))
    if has_audio and lowered in {"", "success", "ok", "complete", "completed", "succeeded", "done", "finish", "finished"}:
        return "SUCCESS"
    if lowered in {"success", "ok", "complete", "completed", "succeeded", "done", "finish", "finished"}:
        return "COMPLETED_NO_AUDIO"
    if lowered in {"submitted", "queued", "queue", "pending", "processing", "running", "in_progress", "generating"}:
        return "PROCESSING"
    if lowered in {"fail", "failed", "error", "cancelled", "canceled", "timeout"}:
        return "FAILED"
    if http_status and int(http_status or 0) >= 400:
        return classify_provider_error(http_status, "FAIL_PROVIDER_ERROR", raw)
    return raw.upper() if raw else ("SUCCESS" if has_audio else "PROCESSING")

async def resolve_shopaikey_tts_audio_bytes(payload) -> tuple[bytes, str, int]:
    for candidate in _minimax_audio_candidates(payload):
        if candidate.startswith(("http://", "https://")):
            audio_bytes, detail, http_status = await _download_audio_url_bytes(candidate, timeout_seconds=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60))
            if audio_bytes:
                return audio_bytes, f"audio_url=yes; {detail}", int(http_status or 0)
            continue
        audio_bytes, encoding = _decode_minimax_audio_string(candidate)
        if audio_bytes:
            return audio_bytes, f"bytes={len(audio_bytes)}; encoding={encoding}", 0
    return b"", "no_audio", 0

async def _download_audio_url_bytes(url: str, timeout_seconds: float = 60.0) -> tuple[bytes, str, int]:
    target = str(url or "").strip()
    if not target.startswith(("http://", "https://")):
        return b"", "invalid_url", 0
    async with httpx.AsyncClient(timeout=timeout_seconds, follow_redirects=True) as client:
        res = await client.get(target)
    content_type = str(res.headers.get("content-type") or "")
    if res.status_code < 400 and res.content and (content_type.startswith("audio/") or len(res.content) > 1024):
        return bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; content_type={content_type or '-'}", int(res.status_code)
    return b"", shopaikey_sanitize_error(res.text[:260] if getattr(res, "text", "") else f"HTTP {res.status_code}"), int(res.status_code)

async def minimax_audio_reference_to_bytes(value) -> tuple[bytes, str]:
    candidates = _minimax_audio_candidates(value if isinstance(value, (dict, list)) else {"audio": value})
    for candidate in candidates:
        if str(candidate).startswith(("http://", "https://")):
            audio_bytes, detail, _http_status = await _download_audio_url_bytes(str(candidate))
            if audio_bytes:
                return audio_bytes, f"url:{detail}"
            continue
        audio_bytes, encoding = _decode_minimax_audio_string(str(candidate))
        if audio_bytes:
            return audio_bytes, encoding
    return b"", "empty_demo_audio"

async def key4u_minimax_tts_bytes(text: str, voice_id: str = "", voice_style: str = "", voice_speed: str = VOICE_TTS_DEFAULT_SPEED, allow_admin: bool = False) -> tuple[str, bytes, str, int]:
    if not key4u_minimax_tts_configured(require_public=not allow_admin):
        return "MISSING", b"", "KEY4U_ENABLED/KEY4U_API_KEY/KEY4U_TTS_ENDPOINT/KEY4U_TTS_MODEL missing", 0
    provider = key4u_provider_instance()
    selected_voice_id = str(voice_id or default_tts_voice_id("male"))
    selected_speed = voice_tts_provider_speed(voice_speed or VOICE_TTS_DEFAULT_SPEED)
    fallback = await provider.voice_tts_fallback(
        str(text or "")[:3500],
        voice_id=selected_voice_id,
        speed=selected_speed,
        timeout_seconds=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60),
    )
    fallback_status = str(fallback.get("status") or ("PASS" if fallback.get("ok") else "FAIL"))
    fallback_http = int(fallback.get("http_status") or 0)
    fallback_bytes = bytes(fallback.get("output_bytes") or b"")
    if fallback.get("ok") and fallback_bytes:
        return "PASS", fallback_bytes, f"http={fallback_http}; bytes={len(fallback_bytes)}; route=key4u_voice_fallback", fallback_http
    fallback_url = str(fallback.get("output_url") or "").strip()
    if fallback.get("ok") and fallback_url:
        downloaded, detail, download_http = await _download_audio_url_bytes(fallback_url)
        if downloaded:
            return "PASS", downloaded, f"http={fallback_http}; {detail}; route=key4u_voice_fallback", int(download_http or fallback_http)
    result = await provider.tts(
        str(text or "")[:3500],
        model=KEY4U_TTS_MODEL,
        voice_id=str(voice_id or default_tts_voice_id("male")),
        speed=selected_speed,
        timeout_seconds=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60),
    )
    status = str(result.get("status") or ("PASS" if result.get("ok") else "FAIL"))
    http_status = int(result.get("http_status") or 0)
    audio_bytes = bytes(result.get("output_bytes") or b"")
    if result.get("ok") and audio_bytes:
        return "PASS", audio_bytes, f"http={http_status}; bytes={len(audio_bytes)}; route=key4u_minimax", http_status
    output_url = str(result.get("output_url") or "").strip()
    if result.get("ok") and output_url:
        downloaded, detail, download_http = await _download_audio_url_bytes(output_url)
        if downloaded:
            return "PASS", downloaded, f"http={http_status}; {detail}; route=key4u_minimax", int(download_http or http_status)
    detail = sanitize_provider_error(result.get("error_message_safe") or status)[:240]
    fallback_detail = sanitize_provider_error(fallback.get("error_message_safe") or fallback_status)[:160]
    return status or "FAIL", b"", (detail + (" | voice_fallback=" + fallback_detail if fallback_detail else ""))[:240], http_status

async def shopaikey_minimax_tts_bytes(text: str, voice_id: str = "", voice_style: str = "", voice_speed: str = VOICE_TTS_DEFAULT_SPEED) -> tuple[str, bytes, str, int]:
    if not shopaikey_minimax_tts_configured():
        if direct_minimax_tts_configured():
            return await call_direct_minimax_tts_bytes_with_speed(text, voice_id=voice_id, voice_style=voice_style, voice_speed=voice_speed)
        return "MISSING", b"", "SHOPAIKEY_API_KEY/MINIMAX_TTS_ENDPOINT/MINIMAX_TTS_MODEL missing", 0
    endpoint = shopaikey_tts_final_url(MINIMAX_TTS_ENDPOINT)
    selected_voice = str(voice_id or MINIMAX_DEFAULT_VOICE_ID or "male-qn-qingse").strip()
    text_value = str(text or "").strip()[:3500]
    if not text_value:
        return "FAIL_BAD_REQUEST", b"", "empty_text", 0
    payload = shopaikey_official_tts_payload(text_value, voice_id=selected_voice, speed=voice_speed)
    try:
        async with httpx.AsyncClient(timeout=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60), follow_redirects=True) as client:
            res = await client.post(
                endpoint,
                headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Content-Type": "application/json"},
                json=payload,
            )
        content_type = str(res.headers.get("content-type") or "")
        if res.status_code < 400 and res.content and content_type.startswith("audio/"):
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        try:
            data = res.json()
        except Exception:
            data = {}
        if res.status_code < 400 and isinstance(data, dict):
            audio_bytes, detail, http_status = await resolve_shopaikey_tts_audio_bytes(data)
            if audio_bytes:
                return "PASS", audio_bytes, f"http={res.status_code}; {detail}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(http_status or res.status_code)
        elif res.status_code < 400 and res.content and len(res.content) > 512:
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; content_type={content_type or '-'}; model={SHOPAIKEY_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        detail = shopaikey_sanitize_error(res.text[:320] if getattr(res, "text", "") else f"HTTP {res.status_code}; no_audio")
        return shopaikey_classify_error(res.status_code, detail), b"", detail, int(res.status_code)
    except httpx.TimeoutException as exc:
        return "FAIL_TIMEOUT", b"", shopaikey_sanitize_error(str(exc)), 0
    except Exception as exc:
        return "FAIL_PROVIDER_ERROR", b"", shopaikey_sanitize_error(str(exc)), 0

async def direct_minimax_tts_bytes(text: str, voice_id: str = "", voice_style: str = "", voice_speed: str = VOICE_TTS_DEFAULT_SPEED) -> tuple[str, bytes, str, int]:
    if not direct_minimax_tts_configured():
        return "MISSING", b"", "MINIMAX_API_KEY/MINIMAX_GROUP_ID/MINIMAX_TTS_MODEL missing", 0
    selected_voice = str(voice_id or MINIMAX_DEFAULT_VOICE_ID or "male-qn-qingse").strip()
    text_value = str(text or "").strip()[:3500]
    if not text_value:
        return "FAIL_BAD_REQUEST", b"", "empty_text", 0
    endpoint = direct_minimax_tts_url()
    payload = minimax_tts_payload(text_value, voice_id=selected_voice, voice_style=voice_style, voice_speed=voice_speed)
    try:
        async with httpx.AsyncClient(timeout=float(SHOPAIKEY_TTS_TIMEOUT_SECONDS or 60), follow_redirects=True) as client:
            res = await client.post(
                endpoint,
                headers={"Authorization": f"Bearer {MINIMAX_API_KEY}", "Content-Type": "application/json"},
                json=payload,
            )
        content_type = str(res.headers.get("content-type") or "")
        if res.status_code < 400 and res.content and content_type.startswith("audio/"):
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}; provider=direct_minimax; model={MINIMAX_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        try:
            data = res.json()
        except Exception:
            data = {}
        if res.status_code < 400 and isinstance(data, dict):
            for candidate in _minimax_audio_candidates(data):
                if candidate.startswith(("http://", "https://")):
                    audio_bytes, detail, http_status = await _download_audio_url_bytes(candidate)
                    if audio_bytes:
                        return "PASS", audio_bytes, f"http={res.status_code}; audio_url=yes; {detail}; provider=direct_minimax; model={MINIMAX_TTS_MODEL}; voice={selected_voice}", int(http_status or res.status_code)
                audio_bytes, encoding = _decode_minimax_audio_string(candidate)
                if audio_bytes:
                    return "PASS", audio_bytes, f"http={res.status_code}; bytes={len(audio_bytes)}; encoding={encoding}; provider=direct_minimax; model={MINIMAX_TTS_MODEL}; voice={selected_voice}", int(res.status_code)
        detail = shopaikey_sanitize_error(res.text[:320] if getattr(res, "text", "") else f"HTTP {res.status_code}; no_audio")
        return shopaikey_classify_error(res.status_code, detail), b"", detail, int(res.status_code)
    except httpx.TimeoutException as exc:
        return "FAIL_TIMEOUT", b"", shopaikey_sanitize_error(str(exc)), 0
    except Exception as exc:
        return "FAIL_PROVIDER_ERROR", b"", shopaikey_sanitize_error(str(exc)), 0

