def shopaikey_job_by_id(job_id: int) -> dict | None:
    if not int(job_id or 0):
        return None
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        row = conn.execute("SELECT * FROM shopaikey_jobs WHERE id=? LIMIT 1", (int(job_id),)).fetchone()
        return dict(row) if row else None
    finally:
        conn.close()

def refund_shopaikey_job_if_needed(user_id, job_id: int = 0, task_id: str = "", reason: str = "provider_fail") -> bool:
    if not SHOPAIKEY_REFUND_ON_PROVIDER_FAIL:
        return False
    job = shopaikey_job_by_task_id(task_id) if task_id else None
    if not job and job_id:
        conn = db_connect()
        conn.row_factory = sqlite3.Row
        try:
            row = conn.execute("SELECT * FROM shopaikey_jobs WHERE id=?", (int(job_id),)).fetchone()
            job = dict(row) if row else None
        finally:
            conn.close()
    if not job:
        return False
    if str(job.get("refund_status") or "").lower() == "refunded":
        return False
    amount = int(job.get("xu_deducted") or 0)
    if amount <= 0:
        return False
    balance_before, _, _ = get_user(user_id)
    refunded = refund_charged_credit(
        user_id,
        amount,
        "shopaikey_refund",
        str(job.get("id") or job_id or task_id or ""),
        f"Hoàn Xu ShopAIKey do {shopaikey_sanitize_error(reason)}",
        True,
    )
    if refunded:
        balance_after, _, _ = get_user(user_id)
        update_shopaikey_job(
            job_id=int(job.get("id") or job_id or 0),
            task_id=str(job.get("task_id") or task_id or ""),
            refund_status="refunded",
            refund_amount=amount,
            refund_reason=reason,
            billing_status="refunded",
        )
        record_shopaikey_billing_event(
            user_id,
            int(job.get("id") or job_id or 0),
            "refund",
            amount,
            int(balance_before or 0),
            int(balance_after or 0),
            reason,
        )
    return refunded

def shopaikey_video_job_timeout_minutes(job: dict) -> int:
    if int((job or {}).get("admin_only") or 0):
        return max(60, int(SHOPAIKEY_VIDEO_STALE_TIMEOUT_DEFAULT_MINUTES or 30))
    planned = int((job or {}).get("xu_cost_planned") or 0)
    try:
        low_cost = int((video_tier_payload("low") or {}).get("cost") or VIDEO_LOW_COST_XU or 0)
    except Exception:
        low_cost = int(VIDEO_LOW_COST_XU or 0)
    if planned and low_cost and planned <= low_cost:
        return max(5, int(SHOPAIKEY_VIDEO_STALE_TIMEOUT_LOW_MINUTES or 15))
    return max(10, int(SHOPAIKEY_VIDEO_STALE_TIMEOUT_DEFAULT_MINUTES or 30))

def mark_stale_public_video_jobs(user_id: str = "", limit: int = 50) -> list[dict]:
    statuses = tuple(sorted(SHOPAIKEY_ACTIVE_JOB_STATUSES))
    placeholders = ",".join("?" for _ in statuses)
    uid = str(user_id or "").strip()
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            f"""
            SELECT * FROM shopaikey_jobs
            WHERE job_type='video'
              AND admin_only=0
              AND (?='' OR user_id=?)
              AND UPPER(status) IN ({placeholders})
            ORDER BY id ASC
            LIMIT ?
            """,
            (uid, uid, *statuses, max(1, min(200, int(limit or 50)))),
        ).fetchall()
    finally:
        conn.close()
    stale_jobs: list[dict] = []
    now_dt = datetime.now()
    for row in rows:
        job = dict(row)
        created_dt = parse_now_text(job.get("created_at") or job.get("updated_at") or "")
        if not created_dt:
            continue
        timeout_minutes = shopaikey_video_job_timeout_minutes(job)
        if now_dt - created_dt < timedelta(minutes=timeout_minutes):
            continue
        job_id = int(job.get("id") or 0)
        deducted_amount = int(job.get("xu_deducted") or 0)
        balance_before, _, _ = get_user(job.get("user_id") or "")
        record_shopaikey_billing_event(
            job.get("user_id") or "",
            job_id,
            "video_stale_timeout",
            0,
            int(balance_before or 0),
            int(balance_before or 0),
            f"timeout_minutes={timeout_minutes}",
        )
        refunded = refund_shopaikey_job_if_needed(job.get("user_id") or "", job_id, job.get("task_id") or "", "stale_video_timeout") if deducted_amount > 0 else False
        package_used = bool(int(job.get("package_item_id") or 0) and int(job.get("package_units_used") or 0))
        package_refunded = refund_package_item_for_job(job.get("user_id") or "", job_id, "stale_video_timeout") if package_used else False
        balance_after, _, _ = get_user(job.get("user_id") or "")
        if deducted_amount > 0 and refunded:
            record_shopaikey_billing_event(
                job.get("user_id") or "",
                job_id,
                "video_refunded",
                deducted_amount,
                int(balance_before or 0),
                int(balance_after or 0),
                "stale_video_timeout",
            )
        elif deducted_amount > 0:
            record_shopaikey_billing_event(
                job.get("user_id") or "",
                job_id,
                "video_refund_failed",
                deducted_amount,
                int(balance_before or 0),
                int(balance_after or 0),
                "stale_video_timeout; refund_error=auto_refund_failed",
            )
        update_shopaikey_job(
            job_id=job_id,
            status="FAILED_TIMEOUT",
            error_class="STALE_TIMEOUT",
            fail_reason="stale_video_timeout",
            refund_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged"),
            refund_amount=deducted_amount if refunded else 0,
            refund_reason="stale_video_timeout",
            billing_status="package_refunded" if package_refunded else ("refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "timeout_not_charged")),
            package_refund_status="refunded" if package_refunded else ("refund_failed" if package_used else ""),
            finished_at=now_text(),
        )
        record_system_event(
            "shopaikey_video_stale_timeout",
            provider="shopaikey_video",
            tool="video",
            severity="warning",
            code="STALE_TIMEOUT",
            message=f"job_id={job_id}; user_id={job.get('user_id') or ''}; timeout_minutes={timeout_minutes}",
        )
        stale_jobs.append({**job, "refunded": refunded, "timeout_minutes": timeout_minutes})
    return stale_jobs

def mark_stale_admin_video_jobs(user_id: str = "", limit: int = 50) -> list[dict]:
    statuses = tuple(sorted(SHOPAIKEY_ACTIVE_JOB_STATUSES))
    placeholders = ",".join("?" for _ in statuses)
    uid = str(user_id or "").strip()
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            f"""
            SELECT * FROM shopaikey_jobs
            WHERE job_type='video'
              AND admin_only=1
              AND (?='' OR user_id=?)
              AND UPPER(status) IN ({placeholders})
            ORDER BY id ASC
            LIMIT ?
            """,
            (uid, uid, *statuses, max(1, min(200, int(limit or 50)))),
        ).fetchall()
    finally:
        conn.close()
    stale_jobs: list[dict] = []
    now_dt = datetime.now()
    for row in rows:
        job = dict(row)
        created_dt = parse_now_text(job.get("created_at") or job.get("updated_at") or "")
        if not created_dt:
            continue
        timeout_minutes = shopaikey_video_job_timeout_minutes(job)
        if now_dt - created_dt < timedelta(minutes=timeout_minutes):
            continue
        job_id = int(job.get("id") or 0)
        deducted_amount = int(job.get("xu_deducted") or 0)
        refunded = refund_shopaikey_job_if_needed(job.get("user_id") or "", job_id, job.get("task_id") or "", "admin_smoke_stale_timeout") if deducted_amount > 0 else False
        update_shopaikey_job(
            job_id=job_id,
            status="FAILED_TIMEOUT",
            error_class="ADMIN_STALE_TIMEOUT",
            fail_reason="admin_smoke_stale_timeout",
            refund_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged"),
            refund_amount=deducted_amount if refunded else 0,
            refund_reason="admin_smoke_stale_timeout",
            billing_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "admin_timeout_not_charged"),
            finished_at=now_text(),
        )
        record_system_event(
            "shopaikey_video_admin_stale_timeout",
            provider="shopaikey_video",
            tool="video",
            severity="warning",
            code="ADMIN_STALE_TIMEOUT",
            message=f"job_id={job_id}; user_id={job.get('user_id') or ''}; timeout_minutes={timeout_minutes}",
        )
        stale_jobs.append({**job, "refunded": refunded, "timeout_minutes": timeout_minutes})
    return stale_jobs

def shopaikey_active_video_admin_block_text(job: dict | None, user_id) -> str:
    job = job or {}
    job_id = int(job.get("id") or 0)
    task_id = str(job.get("task_id") or "").strip()
    status = str(job.get("status") or "-")
    created_at = str(job.get("created_at") or "-")
    lines = [
        "⏳ <b>Bạn đang có một tác vụ video đang chạy.</b>",
        "",
        f"• Job ID: <code>{job_id or '-'}</code>",
        f"• Status: <code>{html.escape(status)}</code>",
        f"• Task ID: <code>{html.escape(task_id or '-')}</code>",
        f"• Created: <code>{html.escape(created_at)}</code>",
        "",
    ]
    if task_id:
        lines.append(f"Kiểm tra provider: <code>/shopaikey_video_job {html.escape(task_id)}</code>")
    if job_id:
        lines.append(f"Kiểm tra DB: <code>/job_status {job_id}</code>")
    lines.append(f"Nếu đã xác nhận job kẹt: <code>/clear_job_lock {html.escape(str(user_id or ''))}</code>")
    lines.append("")
    lines.append("Bot chưa gửi thêm job mới để tránh submit trùng và tốn credit provider thật.")
    return "\n".join(lines)

def shopaikey_video_queue_counts() -> dict:
    mark_stale_public_video_jobs()
    mark_stale_admin_video_jobs()
    conn = db_connect()
    try:
        rows = conn.execute(
            """SELECT UPPER(COALESCE(status, 'UNKNOWN')), COUNT(*)
            FROM shopaikey_jobs
            WHERE job_type='video'
            GROUP BY UPPER(COALESCE(status, 'UNKNOWN'))"""
        ).fetchall()
        counts = {str(status or "UNKNOWN"): int(count or 0) for status, count in rows}
    except Exception:
        counts = {}
    finally:
        conn.close()
    active = sum(counts.get(status, 0) for status in SHOPAIKEY_ACTIVE_JOB_STATUSES)
    return {
        "queued": counts.get("QUEUED", 0),
        "running": active,
        "success": counts.get("SUCCESS", 0),
        "failed": counts.get("FAILED", 0) + counts.get("FAILED_TIMEOUT", 0) + counts.get("TIMEOUT", 0),
        "total": sum(counts.values()),
        "raw": counts,
    }

def public_video_active_job_text(lang: str = "vi") -> str:
    if normalize_user_language(lang) == "zh":
        return "⏳ 你已有一个视频正在处理中。完成后会自动发送视频。请不要重复创建新任务。"
    if normalize_user_language(lang) != "vi":
        return "⏳ You already have a video being processed. The video will be sent automatically when it is ready. Please do not create another job."
    return "⏳ Bạn đang có video đang xử lý. Video sẽ được gửi tự động khi hoàn tất. Vui lòng không tạo thêm job mới."

def public_video_active_job_keyboard(active_job: dict | None, lang: str = "vi") -> InlineKeyboardMarkup:
    task_id = str((active_job or {}).get("task_id") or "").strip()
    keyboard = shopaikey_video_job_check_keyboard(task_id, lang, public_user=True) if task_id else None
    if keyboard:
        return keyboard
    return InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]])

async def shopaikey_video_create_for_model(model: str, prompt: str = "") -> dict:
    if not SHOPAIKEY_API_KEY:
        return {"status": "MISSING", "http_status": 0, "latency_ms": 0, "model": SHOPAIKEY_VIDEO_MODEL, "task_id": "", "provider_status": "", "message": "SHOPAIKEY_API_KEY missing", "error_class": "missing_api_key"}
    started = time.perf_counter()
    payload = shopaikey_video_request_payload(model, prompt)
    try:
        async with httpx.AsyncClient(timeout=float(SHOPAIKEY_VIDEO_SMOKE_SUBMIT_TIMEOUT_SECONDS or 30)) as client:
            res = await client.post(
                SHOPAIKEY_VIDEO_URL,
                headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Content-Type": "application/json"},
                json=payload,
            )
        latency_ms = int((time.perf_counter() - started) * 1000)
        try:
            data = res.json()
        except Exception:
            data = {}
        response_data = shopaikey_video_payload_data(data)
        task_id = shopaikey_extract_task_id(data)
        provider_status = str(response_data.get("status") or data.get("status") or data.get("code") or "").strip()
        provider_message = shopaikey_sanitize_error(str(data.get("message") or response_data.get("message") or "")[:260])
        if res.status_code < 400 and task_id:
            return {
                "status": "PASS_SUBMITTED",
                "http_status": int(res.status_code),
                "latency_ms": latency_ms,
                "model": payload["model"],
                "task_id": task_id,
                "provider_status": provider_status,
                "message": provider_message,
                "error_class": "",
                "detail": f"model={payload['model']}; http={res.status_code}; latency_ms={latency_ms}; task_id={task_id}; provider_status={provider_status or '-'}",
            }
        provider_code, provider_error = shopaikey_provider_error_from_payload(data)
        detail = provider_error or provider_message or shopaikey_sanitize_error(res.text[:260] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        status = shopaikey_classify_video_error(res.status_code, detail)
        return {
            "status": status,
            "http_status": int(res.status_code),
            "latency_ms": latency_ms,
            "model": payload["model"],
            "task_id": task_id,
            "provider_status": provider_status,
            "provider_error_code": provider_code,
            "message": detail,
            "error_class": status,
            "detail": detail,
        }
    except Exception as e:
        latency_ms = int((time.perf_counter() - started) * 1000)
        error_class = "FAIL_TIMEOUT" if "timeout" in type(e).__name__.lower() else "FAIL_PROVIDER_ERROR"
        return {"status": error_class, "http_status": 0, "latency_ms": latency_ms, "model": payload["model"], "task_id": "", "provider_status": "", "message": shopaikey_sanitize_error(str(e)), "error_class": error_class, "detail": shopaikey_sanitize_error(str(e))}

async def shopaikey_workflow_image_to_video_create(image_url: str, prompt: str = "", model: str = "") -> dict:
    if not SHOPAIKEY_API_KEY:
        return {"status": "MISSING", "http_status": 0, "latency_ms": 0, "model": model or SHOPAIKEY_VIDEO_MODEL, "task_id": "", "provider_status": "", "message": "SHOPAIKEY_API_KEY missing", "error_class": "missing_api_key"}
    if not str(image_url or "").strip().startswith(("http://", "https://")):
        return {"status": "FAIL_BAD_REQUEST", "http_status": 0, "latency_ms": 0, "model": model or SHOPAIKEY_VIDEO_MODEL, "task_id": "", "provider_status": "", "message": "workflow image url missing", "error_class": "missing_image_url"}
    started = time.perf_counter()
    payload = shopaikey_workflow_image_to_video_payload(model or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast", image_url, prompt)
    try:
        async with httpx.AsyncClient(timeout=60.0) as client:
            res = await client.post(
                SHOPAIKEY_VIDEO_URL,
                headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Content-Type": "application/json"},
                json=payload,
            )
        latency_ms = int((time.perf_counter() - started) * 1000)
        try:
            data = res.json()
        except Exception:
            data = {}
        response_data = shopaikey_video_payload_data(data)
        task_id = shopaikey_extract_task_id(data)
        provider_status = str(response_data.get("status") or data.get("status") or data.get("code") or "").strip()
        provider_message = shopaikey_sanitize_error(str(data.get("message") or response_data.get("message") or "")[:260])
        if res.status_code < 400 and task_id:
            return {
                "status": "PASS_SUBMITTED",
                "http_status": int(res.status_code),
                "latency_ms": latency_ms,
                "model": payload["model"],
                "task_id": task_id,
                "provider_status": provider_status,
                "message": provider_message,
                "error_class": "",
                "detail": f"model={payload['model']}; http={res.status_code}; latency_ms={latency_ms}; task_id={task_id}; provider_status={provider_status or '-'}; image=yes",
            }
        provider_code, provider_error = shopaikey_provider_error_from_payload(data)
        detail = provider_error or provider_message or shopaikey_sanitize_error(res.text[:260] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        status = shopaikey_classify_video_error(res.status_code, detail)
        return {
            "status": status,
            "http_status": int(res.status_code),
            "latency_ms": latency_ms,
            "model": payload["model"],
            "task_id": task_id,
            "provider_status": provider_status,
            "provider_error_code": provider_code,
            "message": detail,
            "error_class": status,
            "detail": detail,
        }
    except Exception as e:
        latency_ms = int((time.perf_counter() - started) * 1000)
        error_class = "FAIL_TIMEOUT" if "timeout" in type(e).__name__.lower() else "FAIL_PROVIDER_ERROR"
        return {"status": error_class, "http_status": 0, "latency_ms": latency_ms, "model": payload["model"], "task_id": "", "provider_status": "", "message": shopaikey_sanitize_error(str(e)), "error_class": error_class, "detail": shopaikey_sanitize_error(str(e))}

async def shopaikey_video_create_smoke_test(model_override: str = "", prompt: str = "") -> dict:
    models = shopaikey_video_model_sequence(model_override)
    attempts = []
    for model in models:
        result = await shopaikey_video_create_for_model(model, prompt)
        attempts.append({
            "model": result.get("model") or model,
            "status": result.get("status") or "FAIL",
            "http_status": result.get("http_status") or 0,
            "provider_status": result.get("provider_status") or "",
        })
        if result.get("status") == "PASS_SUBMITTED" and result.get("task_id"):
            return {**result, "attempts": attempts, "selected_model": result.get("model") or model}
    last = result if attempts else {"status": "MISSING", "http_status": 0, "model": SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast", "task_id": "", "message": "no video models configured", "error_class": "no_models"}
    final_status = str(last.get("status") or "FAIL")
    if attempts and all(str(item.get("status") or "").upper() == "FAIL_NO_AVAILABLE_CHANNEL" for item in attempts):
        final_status = "FAIL_NO_AVAILABLE_CHANNEL"
    return {**last, "status": final_status, "error_class": final_status, "attempts": attempts, "selected_model": ""}

def shopaikey_video_result_allows_key4u_fallback(result: dict | None = None) -> bool:
    result = dict(result or {})
    if result.get("task_id"):
        return False
    status = str(result.get("error_class") or result.get("status") or "").upper()
    return status in {
        "MISSING", "MISSING_API_KEY", "FAIL_NO_AVAILABLE_CHANNEL",
        "FAIL_QUOTA_OR_BALANCE", "FAIL_RATE_LIMIT", "FAIL_AUTH",
    }

def key4u_public_video_route_ready() -> bool:
    system_on, _ = is_system_maintenance()
    if system_on or not (video_public_beta_enabled_runtime() and shopaikey_public_video_enabled_runtime() and video_ai_public_enabled_runtime()):
        return False
    try:
        return bool(key4u_provider_instance().is_configured())
    except Exception:
        return False

def key4u_public_video_fallback_ready() -> bool:
    return bool(KEY4U_VIDEO_FALLBACK_ENABLED and key4u_public_video_route_ready())

async def _submit_key4u_public_video(prompt: str, user_id="", models: list[str] | None = None) -> dict:
    try:
        provider = key4u_provider_instance()
        if not provider.is_configured():
            return {"status": "MISSING", "error_class": "KEY4U_NOT_CONFIGURED", "task_id": "", "provider_route": "key4u"}
        candidates = list(models or key4u_model_candidates(KEY4U_VIDEO_MODEL, KEY4U_VIDEO_FALLBACK_MODELS, max_fallbacks=1))
        result = await key4u_run_with_model_fallback(
            candidates,
            lambda selected: provider.video_generation(prompt=prompt, model=selected, timeout_seconds=60.0),
        )
    except Exception as exc:
        return {"status": f"FAIL_{type(exc).__name__}", "error_class": type(exc).__name__, "task_id": "", "provider_route": "key4u"}
    record_provider_usage_event(
        provider="key4u", capability="video_generate", model=str(result.get("model") or ""),
        user_id=str(user_id or ""), is_admin_smoke=False, provider_task_id=str(result.get("task_id") or ""),
        status=str(result.get("status") or "FAIL"), media_units=1 if result.get("task_id") else 0,
        note="public_video_key4u_route",
    )
    return {
        **result,
        "provider_route": "key4u",
        "selected_model": result.get("model") or (candidates[0] if candidates else KEY4U_VIDEO_MODEL),
        "attempts": [{
            "provider": "key4u", "model": result.get("model") or (candidates[0] if candidates else KEY4U_VIDEO_MODEL),
            "status": result.get("status") or "FAIL", "http_status": result.get("http_status") or 0,
        }],
    }

async def submit_public_video_with_key4u_fallback(model: str, prompt: str, user_id="", video_tier: str = "") -> dict:
    """Route 1000/1200/1500 to Key4U Kling; keep ShopAIKey primary below them."""
    tier = normalize_video_tier(video_tier)
    if tier in {"future_1000", "future_1200", "future_1500"}:
        return await _submit_key4u_public_video(prompt, user_id, ["kling-video"])
    primary = {**(await shopaikey_video_create_smoke_test(model, prompt)), "provider_route": "shopaikey"}
    if primary.get("status") == "PASS_SUBMITTED" and primary.get("task_id"):
        return primary
    if not key4u_public_video_fallback_ready() or not shopaikey_video_result_allows_key4u_fallback(primary):
        return primary
    fallback = await _submit_key4u_public_video(prompt, user_id)
    if fallback.get("status") == "PASS_SUBMITTED" and fallback.get("task_id"):
        fallback["attempts"] = [*(primary.get("attempts") or []), *(fallback.get("attempts") or [])]
        return fallback
    return {**primary, "key4u_fallback_status": fallback.get("status") or "FAIL"}

async def shopaikey_video_job_status(task_id: str) -> dict:
    task_id = str(task_id or "").strip()
    if not SHOPAIKEY_API_KEY:
        return {"status": "MISSING", "http_status": 0, "latency_ms": 0, "task_id": task_id, "provider_status": "", "progress": "", "result_url": "", "fail_reason": "SHOPAIKEY_API_KEY missing", "error_class": "missing_api_key"}
    if not re.match(r"^[A-Za-z0-9_.:-]{3,160}$", task_id):
        return {"status": "INVALID_TASK_ID", "http_status": 0, "latency_ms": 0, "task_id": "", "provider_status": "", "progress": "", "result_url": "", "fail_reason": "task_id invalid", "error_class": "invalid_task_id"}
    started = time.perf_counter()
    endpoint = (SHOPAIKEY_VIDEO_URL or "").rstrip("/") + "/" + task_id
    try:
        async with httpx.AsyncClient(timeout=45.0) as client:
            res = await client.get(endpoint, headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}", "Accept": "application/json"})
        latency_ms = int((time.perf_counter() - started) * 1000)
        try:
            data = res.json()
        except Exception:
            data = {}
        response_data = shopaikey_video_payload_data(data)
        provider_status = str(response_data.get("status") or data.get("status") or data.get("code") or "").strip()
        progress = str(response_data.get("progress") or data.get("progress") or "").strip()
        result_url = shopaikey_video_result_url(data)
        fail_reason = shopaikey_sanitize_error(str(response_data.get("fail_reason") or response_data.get("error") or data.get("message") or "")[:260])
        if res.status_code < 400:
            normalized_status = normalize_shopaikey_video_status(provider_status)
            if result_url and normalized_status in {"UNKNOWN", "SUCCESS"}:
                status = "SUCCESS"
            elif normalized_status == "SUCCESS":
                status = "SUCCESS"
            elif normalized_status == "FAILED":
                status = "FAILED"
            elif normalized_status in {"QUEUED", "IN_PROGRESS"}:
                status = normalized_status
            else:
                status = provider_status or "PENDING"
            return {
                "status": status,
                "http_status": int(res.status_code),
                "latency_ms": latency_ms,
                "task_id": task_id,
                "provider_status": provider_status,
                "progress": progress,
                "result_url": result_url,
                "fail_reason": fail_reason,
                "error_class": "",
                "detail": f"http={res.status_code}; task_id={task_id}; provider_status={provider_status or '-'}; progress={progress or '-'}; result_url={'yes' if result_url else 'no'}",
            }
        provider_code, provider_error = shopaikey_provider_error_from_payload(data)
        detail = provider_error or fail_reason or shopaikey_sanitize_error(res.text[:260] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        return {
            "status": shopaikey_classify_video_error(res.status_code, detail),
            "http_status": int(res.status_code),
            "latency_ms": latency_ms,
            "task_id": task_id,
            "provider_status": provider_status,
            "progress": progress,
            "result_url": "",
            "fail_reason": detail,
            "provider_error_code": provider_code,
            "error_class": shopaikey_classify_video_error(res.status_code, detail),
            "detail": detail,
        }
    except Exception as e:
        latency_ms = int((time.perf_counter() - started) * 1000)
        error_class = "FAIL_TIMEOUT" if "timeout" in type(e).__name__.lower() else "FAIL_PROVIDER_ERROR"
        return {"status": error_class, "http_status": 0, "latency_ms": latency_ms, "task_id": task_id, "provider_status": "", "progress": "", "result_url": "", "fail_reason": shopaikey_sanitize_error(str(e)), "error_class": error_class, "detail": shopaikey_sanitize_error(str(e))}

async def poll_shopaikey_video_smoke_job(task_id: str) -> dict:
    """Briefly poll a smoke job without turning normal provider latency into a failure."""
    deadline = time.monotonic() + min(
        int(SHOPAIKEY_VIDEO_SMOKE_MAX_WAIT_SECONDS or 180),
        int(SHOPAIKEY_VIDEO_SMOKE_POLL_SECONDS or 10),
    )
    last = {"status": "SUBMITTED", "task_id": task_id, "provider_status": "", "result_url": ""}
    while True:
        last = await shopaikey_video_job_status(task_id)
        normalized = normalize_shopaikey_video_status(last.get("status") or last.get("provider_status") or "")
        if normalized == "SUCCESS":
            return {**last, "lifecycle_status": "succeeded"}
        if normalized == "FAILED" or str(last.get("error_class") or "").upper().startswith("FAIL_"):
            return {**last, "lifecycle_status": "failed"}
        remaining = deadline - time.monotonic()
        if remaining <= 0:
            return {**last, "lifecycle_status": "processing"}
        await asyncio.sleep(min(float(SHOPAIKEY_VIDEO_SMOKE_POLL_SECONDS or 10), remaining))

async def send_shopaikey_video_result(bot_client, chat_id, task_id: str, result_url: str) -> tuple[bool, str]:
    if not bot_client or not chat_id or not result_url:
        return False, ""
    try:
        msg = await bot_client.send_video(
            chat_id=chat_id,
            video=result_url,
            caption="🎞 Video TOAN AAS đã tạo xong",
        )
        file_id = ""
        if getattr(msg, "video", None):
            file_id = getattr(msg.video, "file_id", "") or ""
        return True, file_id
    except Exception:
        try:
            await bot_client.send_message(
                chat_id=chat_id,
                text=(
                    "🎞 <b>Video đã tạo xong</b>\n\n"
                    f"• <a href=\"{html.escape(result_url, quote=True)}\">Mở video kết quả</a>\n"
                    "Telegram không gửi trực tiếp được file, bot gửi link kết quả."
                ),
                parse_mode="HTML",
                disable_web_page_preview=False,
            )
            return True, ""
        except Exception:
            return False, ""

def _video_output_claim_is_stale(claimed_at: str, max_age_seconds: int = 600) -> bool:
    value = str(claimed_at or "").strip()
    if not value:
        return True
    try:
        claimed = datetime.strptime(value, "%Y-%m-%d %H:%M:%S")
        return (datetime.now() - claimed).total_seconds() > max(60, int(max_age_seconds or 600))
    except Exception:
        return True

def _safe_set_video_system_setting(key: str, value, note: str = "") -> None:
    try:
        set_system_setting(key, value, note)
    except Exception:
        logger.warning("video result telemetry setting failed | key=%s", sanitize_log_text(str(key))[:80])

def claim_shopaikey_video_output(
    task_id: str = "",
    job_id: int = 0,
    result_url: str = "",
    source: str = "",
    explicit_resend: bool = False,
) -> dict:
    """Atomically reserve the one public result send for a provider video task."""
    safe_task_id = str(task_id or "").strip()[:180]
    safe_source = str(source or "video_result")[:80]
    safe_url = str(result_url or "").strip()[:1000]
    if not safe_task_id and not int(job_id or 0):
        return {"claimed": False, "reason": "missing_job", "already_sent": False}
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    duplicate = False
    row_dict: dict = {}
    try:
        conn.execute("BEGIN IMMEDIATE")
        if int(job_id or 0):
            row = conn.execute("SELECT * FROM shopaikey_jobs WHERE id=? LIMIT 1", (int(job_id),)).fetchone()
        else:
            row = conn.execute("SELECT * FROM shopaikey_jobs WHERE task_id=? ORDER BY id DESC LIMIT 1", (safe_task_id,)).fetchone()
        if not row:
            conn.rollback()
            return {"claimed": False, "reason": "job_not_found", "already_sent": False}
        row_dict = dict(row)
        resolved_job_id = int(row_dict.get("id") or 0)
        already_sent = bool(int(row_dict.get("result_sent") or 0) or str(row_dict.get("output_sent_at") or "").strip())
        same_output_sent = False
        if safe_url and not explicit_resend:
            same_output = conn.execute(
                """SELECT id FROM shopaikey_jobs
                   WHERE user_id=? AND job_type='video' AND COALESCE(result_sent,0)=1
                     AND (output_sent_result_url=? OR (result_url=? AND output_sent_at<>''))
                   LIMIT 1""",
                (str(row_dict.get("user_id") or ""), safe_url, safe_url),
            ).fetchone()
            same_output_sent = bool(same_output)
        active_claim = str(row_dict.get("output_send_claimed_at") or "").strip()
        if not explicit_resend and (already_sent or same_output_sent or (active_claim and not _video_output_claim_is_stale(active_claim))):
            duplicate = True
            conn.execute(
                "UPDATE shopaikey_jobs SET duplicate_prevented_count=COALESCE(duplicate_prevented_count,0)+1, updated_at=? WHERE id=?",
                (now_text(), resolved_job_id),
            )
            conn.commit()
            return {
                "claimed": False,
                "reason": "already_sent" if (already_sent or same_output_sent) else "send_in_progress",
                "already_sent": bool(already_sent or same_output_sent),
                "job_id": resolved_job_id,
                "task_id": str(row_dict.get("task_id") or safe_task_id),
                "duplicate_prevented": True,
            }
        claimed_at = now_text()
        conn.execute(
            """UPDATE shopaikey_jobs
               SET output_send_claimed_at=?, output_sent_source=?, output_sent_result_url=?,
                   last_telegram_send_error='', updated_at=?
               WHERE id=?""",
            (claimed_at, safe_source, safe_url or str(row_dict.get("result_url") or "")[:1000], claimed_at, resolved_job_id),
        )
        conn.commit()
        return {
            "claimed": True,
            "reason": "explicit_resend" if explicit_resend else "first_send",
            "already_sent": already_sent,
            "job_id": resolved_job_id,
            "task_id": str(row_dict.get("task_id") or safe_task_id),
            "explicit_resend": bool(explicit_resend),
        }
    finally:
        conn.close()
        if duplicate:
            _safe_set_video_system_setting("video_job_last_duplicate_task_id", str(row_dict.get("task_id") or safe_task_id), "duplicate public video result prevented")

def complete_shopaikey_video_output_claim(
    job_id: int,
    task_id: str,
    result_url: str,
    source: str,
    telegram_video_file_id: str = "",
    explicit_resend: bool = False,
) -> None:
    sent_at = now_text()
    fields = {
        "output_send_claimed_at": "",
        "result_sent": 1,
        "output_sent_at": sent_at,
        "completed_notified_at": sent_at,
        "output_sent_result_url": str(result_url or "")[:1000],
        "output_sent_source": str(source or "video_result")[:80],
        "telegram_video_file_id": str(telegram_video_file_id or "")[:180],
        "output_file_id": str(telegram_video_file_id or "")[:180],
        "last_telegram_send_error": "",
    }
    update_shopaikey_job(job_id=job_id, task_id=task_id, **fields)
    _safe_set_video_system_setting("video_job_last_output_sent_source", str(source or "video_result")[:80], "public video result sent")
    _safe_set_video_system_setting("video_job_last_output_task_id", str(task_id or "")[:180], "public video result sent")
    if not explicit_resend:
        _safe_set_video_system_setting("video_job_last_completed_at", sent_at, "public video result sent")

def release_shopaikey_video_output_claim(job_id: int, task_id: str, error: str = "telegram_send_failed") -> None:
    safe_error = shopaikey_sanitize_error(str(error or "telegram_send_failed"))[:260]
    update_shopaikey_job(
        job_id=job_id,
        task_id=task_id,
        output_send_claimed_at="",
        last_telegram_send_error=safe_error,
    )
    _safe_set_video_system_setting("video_job_last_telegram_send_error", safe_error, "public video result send failed")

async def send_shopaikey_video_result_once(
    bot_client,
    chat_id,
    task_id: str,
    result_url: str,
    *,
    job_id: int = 0,
    source: str = "video_result",
    explicit_resend: bool = False,
) -> dict:
    claim = claim_shopaikey_video_output(
        task_id=task_id,
        job_id=job_id,
        result_url=result_url,
        source=source,
        explicit_resend=explicit_resend,
    )
    if not claim.get("claimed"):
        return {**claim, "sent": False}
    resolved_job_id = int(claim.get("job_id") or job_id or 0)
    output_sent, file_id = await send_shopaikey_video_result(bot_client, chat_id, task_id, result_url)
    if output_sent:
        complete_shopaikey_video_output_claim(
            resolved_job_id,
            task_id,
            result_url,
            source,
            file_id,
            explicit_resend=explicit_resend,
        )
        return {**claim, "sent": True, "output_file_id": file_id, "link_fallback": not bool(file_id)}
    release_shopaikey_video_output_claim(resolved_job_id, task_id)
    return {**claim, "sent": False, "reason": "telegram_send_failed"}

def mark_shopaikey_video_output_confirmed(task_id: str = "", model: str = "", updated_by="", source: str = "video_output") -> None:
    safe_task_id = str(task_id or "").strip()[:180]
    safe_model = str(model or SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast")[:120]
    detail = (
        f"task_id={safe_task_id or '-'}; provider_status=SUCCESS; "
        "output_sent=yes; output_sent=true; last_video_output=confirmed; "
        f"source={str(source or 'video_output')[:80]}"
    )
    payload = {"status": "SUCCESS", "model": safe_model, "http_status": 200, "latency_ms": 0}
    save_tool_test_result("shopaikey_video", "SUCCESS", detail, updated_by)
    save_tool_test_result("shopaikey_video_job", "SUCCESS", detail, updated_by)
    save_shopaikey_component_snapshot("video", payload, detail, updated_by)
    set_system_setting("shopaikey_video_last_task_id", safe_task_id, detail, updated_by)
    set_system_setting("shopaikey_video_last_output", "confirmed", detail, updated_by)
    set_system_setting("shopaikey_video_last_output_sent", "true", detail, updated_by)
    set_system_setting("shopaikey_video_last_completed_at", now_text(), detail, updated_by)
    record_api_debug("shopaikey", str(source or "video_output")[:80], "SUCCESS", 200, detail)

async def auto_poll_shopaikey_video_job(bot_client, job_id: int, chat_id, user_id, task_id: str, provider_route: str = "shopaikey") -> None:
    lang = user_ui_lang(user_id)
    provider_route = "key4u" if str(provider_route or "").lower() == "key4u" else "shopaikey"
    max_attempts = max(1, int(SHOPAIKEY_VIDEO_POLL_MAX_ATTEMPTS or 24))
    interval = max(5, int(SHOPAIKEY_VIDEO_POLL_INTERVAL_SECONDS or 25))
    initial_job = shopaikey_job_by_id(job_id) or {}
    if bool(int(initial_job.get("admin_only") or 0)):
        max_attempts = max(
            max_attempts,
            math.ceil((int(SHOPAIKEY_VIDEO_JOB_MAX_AGE_MINUTES or 60) * 60) / interval),
        )
    for attempt in range(1, max_attempts + 1):
        await asyncio.sleep(interval)
        result = await (key4u_provider_instance().poll_video_task(task_id) if provider_route == "key4u" else shopaikey_video_job_status(task_id))
        status = str(result.get("status") or "UNKNOWN").upper()
        result_url = str(result.get("result_url") or result.get("output_url") or "")
        update_shopaikey_job(
            job_id=job_id,
            task_id=task_id,
            status=shopaikey_db_video_status(status),
            result_url=result_url,
            poll_count=attempt,
            error_class=result.get("error_class") or "",
            provider_error_code=result.get("provider_error_code") or "",
            provider_message=result.get("detail") or "",
            fail_reason=result.get("fail_reason") or "",
        )
        credits_polling, _, _ = get_user(user_id)
        record_shopaikey_billing_event(user_id, job_id, "video_polling", 0, int(credits_polling or 0), int(credits_polling or 0), f"task_id={task_id}; attempt={attempt}; status={status}")
        if status == "SUCCESS":
            send_result = await send_shopaikey_video_result_once(
                bot_client,
                chat_id,
                task_id,
                result_url,
                job_id=job_id,
                source=f"auto_poll_{provider_route}",
            )
            output_sent = bool(send_result.get("sent"))
            already_sent = bool(send_result.get("already_sent") or send_result.get("duplicate_prevented"))
            file_id = str(send_result.get("output_file_id") or "")
            update_shopaikey_job(
                job_id=job_id,
                task_id=task_id,
                status="SUCCESS",
                result_sent=1 if (output_sent or already_sent) else 0,
                finished_at=now_text(),
            )
            if output_sent and provider_route == "shopaikey":
                mark_shopaikey_video_output_confirmed(task_id, (initial_job or {}).get("model") or SHOPAIKEY_VIDEO_MODEL, user_id, "auto_poll_shopaikey_video_job")
            elif output_sent:
                save_tool_test_result("key4u_video_job", "SUCCESS", f"public fallback task_id={task_id}; output_sent=yes", user_id)
            credits_now, _, _ = get_user(user_id)
            record_shopaikey_billing_event(user_id, job_id, "video_success", 0, int(credits_now or 0), int(credits_now or 0), f"task_id={task_id}; result_url={'yes' if result_url else 'no'}")
            if output_sent:
                try:
                    await bot_client.send_message(
                        chat_id=chat_id,
                        text=ui_text(lang, "video.next_action"),
                        reply_markup=public_video_success_keyboard(lang=lang, task_id=task_id),
                    )
                except Exception:
                    pass
            return
        if status in {"FAILED", "FAILURE"} or str(result.get("error_class") or "").upper().startswith("FAIL_"):
            provider_error_text = result.get("fail_reason") or result.get("detail") or "video_provider_failed"
            record_provider_error(
                provider_route,
                "video",
                classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, provider_error_text),
                provider_error_text,
            )
            job_snapshot = shopaikey_job_by_id(job_id) or {}
            deducted_amount = int(job_snapshot.get("xu_deducted") or 0)
            package_used = bool(int(job_snapshot.get("package_item_id") or 0) and int(job_snapshot.get("package_units_used") or 0))
            balance_before_refund, _, _ = get_user(user_id)
            record_shopaikey_billing_event(user_id, job_id, "video_provider_fail", 0, int(balance_before_refund or 0), int(balance_before_refund or 0), f"task_id={task_id}; error={provider_error_text}")
            package_refunded = refund_package_item_for_job(user_id, job_id, provider_error_text) if package_used else False
            refunded = refund_shopaikey_job_if_needed(user_id, job_id, task_id, provider_error_text) if deducted_amount > 0 else False
            balance_after_failure, _, _ = get_user(user_id)
            if deducted_amount > 0 and refunded:
                record_shopaikey_billing_event(user_id, job_id, "video_refunded", deducted_amount, int(balance_before_refund or 0), int(balance_after_failure or 0), f"task_id={task_id}; error={provider_error_text}")
            elif deducted_amount > 0:
                record_shopaikey_billing_event(user_id, job_id, "video_refund_failed", deducted_amount, int(balance_before_refund or 0), int(balance_after_failure or 0), f"task_id={task_id}; error={provider_error_text}; refund_error=auto_refund_failed")
                await alert_public_video_refund_failure(context=SimpleNamespace(bot=bot_client), user_id=user_id, job_id=job_id, tier="", amount_xu=deducted_amount, balance_before=int(balance_before_refund or 0), balance_after=int(balance_after_failure or 0), provider_error=provider_error_text, refund_error="auto_refund_failed")
            try:
                await bot_client.send_message(
                    chat_id=chat_id,
                    text=package_provider_fail_message(lang) if package_used and package_refunded else public_video_provider_fail_message(deducted_amount, refunded, lang),
                )
            except Exception:
                pass
            update_shopaikey_job(
                job_id=job_id,
                task_id=task_id,
                status="FAILED",
                refund_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged"),
                refund_amount=deducted_amount if refunded else 0,
                refund_reason=provider_error_text,
                billing_status="package_refunded" if package_refunded else ("refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "failed_not_charged")),
                package_refund_status="refunded" if package_refunded else ("refund_failed" if package_used else ""),
                finished_at=now_text(),
            )
            return
    record_provider_error(provider_route, "video", "TIMEOUT_STALE", "video_poll_timeout")
    job_snapshot = shopaikey_job_by_id(job_id) or {}
    deducted_amount = int(job_snapshot.get("xu_deducted") or 0)
    package_used = bool(int(job_snapshot.get("package_item_id") or 0) and int(job_snapshot.get("package_units_used") or 0))
    balance_before_refund, _, _ = get_user(user_id)
    record_shopaikey_billing_event(user_id, job_id, "video_timeout", 0, int(balance_before_refund or 0), int(balance_before_refund or 0), f"task_id={task_id}")
    package_refunded = refund_package_item_for_job(user_id, job_id, "video_poll_timeout") if package_used else False
    refunded = refund_shopaikey_job_if_needed(user_id, job_id, task_id, "video_poll_timeout") if deducted_amount > 0 else False
    balance_after_timeout, _, _ = get_user(user_id)
    if deducted_amount > 0 and refunded:
        record_shopaikey_billing_event(user_id, job_id, "video_refunded", deducted_amount, int(balance_before_refund or 0), int(balance_after_timeout or 0), f"task_id={task_id}; timeout")
    elif deducted_amount > 0:
        record_shopaikey_billing_event(user_id, job_id, "video_refund_failed", deducted_amount, int(balance_before_refund or 0), int(balance_after_timeout or 0), f"task_id={task_id}; timeout; refund_error=auto_refund_failed")
        await alert_public_video_refund_failure(context=SimpleNamespace(bot=bot_client), user_id=user_id, job_id=job_id, tier="", amount_xu=deducted_amount, balance_before=int(balance_before_refund or 0), balance_after=int(balance_after_timeout or 0), provider_error="video_poll_timeout", refund_error="auto_refund_failed")
    update_shopaikey_job(
        job_id=job_id,
        task_id=task_id,
        status="TIMEOUT",
        poll_count=max_attempts,
        refund_status="refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "not_charged"),
        refund_amount=deducted_amount if refunded else 0,
        refund_reason="video_poll_timeout",
        billing_status="package_refunded" if package_refunded else ("refunded" if refunded else ("refund_failed" if deducted_amount > 0 else "timeout_not_charged")),
        package_refund_status="refunded" if package_refunded else ("refund_failed" if package_used else ""),
        finished_at=now_text(),
    )
    try:
        await bot_client.send_message(
            chat_id=chat_id,
            text=package_provider_fail_message(lang) if package_used and package_refunded else public_video_provider_fail_message(deducted_amount, refunded, lang),
        )
    except Exception:
        return

def start_public_video_auto_poll(context, job_id: int, chat_id, user_id, task_id: str, result: dict) -> bool:
    route = "key4u" if str((result or {}).get("provider_route") or "").lower() == "key4u" else "shopaikey"
    enabled = route == "key4u" or bool(SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED)
    if enabled:
        asyncio.create_task(auto_poll_shopaikey_video_job(context.bot, job_id, chat_id, user_id, task_id, route))
    return enabled

