def video_b14_creative_choice_keyboard(field: str, lang: str = "vi") -> InlineKeyboardMarkup:
    choices = list(VIDEO_B14_3_CREATIVE_CHOICES.get(str(field or ""), ()))
    rows = []
    for index in range(0, len(choices), 2):
        rows.append([
            InlineKeyboardButton(label, callback_data=f"vproduct|b14_creative_set|{field}|{value}")
            for label, value in choices[index:index + 2]
        ])
    rows.append([InlineKeyboardButton("⏭ Theo profile", callback_data=f"vproduct|b14_creative_set|{field}|default")])
    rows.append([InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vproduct|b14_creative_screen"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)


def video_b14_creative_choice_value(field: str, value: str) -> str:
    if value == "default":
        return "theo profile"
    if field == "color_tone":
        field = "color_palette"
    elif field == "mood":
        field = "emotion_tone"
    return str(VIDEO_B14_3_CREATIVE_VALUE_TEXT.get(field, {}).get(value) or value.replace("_", " "))


def video_b14_profile_id_for_session(session: dict | None = None) -> str:
    session = dict(session or {})
    draft = dict(session.get("draft") or {})
    selected = str(draft.get("b14_profile_id") or "").strip()
    if selected:
        try:
            video_profiles.get_video_profile(selected)
            return selected
        except Exception:
            pass
    product_id = str(session.get("product_id") or "")
    idea = str(session.get("topic") or draft.get("topic") or "")
    return video_b14_profile_for_product(product_id, idea).profile_id


def video_b14_scene_count_for_session(session: dict | None = None, default: int = 3) -> int:
    draft = dict((session or {}).get("draft") or {})
    return max(1, min(20, safe_int(draft.get("b14_scene_count") or draft.get("scene_count") or default, default)))


def video_b14_build_storyboard_for_session(user_id, session: dict, *, scene_count: int | None = None):
    draft = dict((session or {}).get("draft") or {})
    product_id = str(session.get("product_id") or "")
    idea = str(session.get("topic") or draft.get("topic") or TASK3D_SAMPLE_TOPICS.get(product_id) or "video ngắn rõ chủ thể").strip()
    pack = video_b14_asset_pack_from_session(session)
    profile = video_profiles.get_video_profile(video_b14_profile_id_for_session(session))
    creative_controls = video_b14_creative_controls_to_storyboard(session)
    plan = video_storyboard.create_storyboard_plan(
        profile_id=profile.profile_id,
        idea_text=idea,
        asset_pack=pack,
        scene_count=scene_count or video_b14_scene_count_for_session(session, 3),
        creative_controls=creative_controls,
    )
    video_continuity.build_continuity_prompts(plan.story_bible, plan.scene_cards)
    prompt_bundle = video_b14_prompt_bundle_from_plan(plan)
    draft.update({
        "b14_storyboard_plan": plan.to_dict(),
        "prompt_bundle": prompt_bundle,
        "prompt_bundle_id": prompt_bundle.get("bundle_id"),
        "b14_profile_id": profile.profile_id,
        "creative_control_json": creative_controls,
        "b14_creative_controls": creative_controls,
        "b14_scene_count": len(plan.scene_cards),
        "topic": idea,
        "provider_called": False,
        "xu_charged": 0,
    })
    session["draft"] = draft
    save_video_session(user_id, session)
    return plan


def video_b14_resize_storyboard_for_session(user_id, session: dict, scene_count: int) -> tuple[dict, str]:
    count = max(1, min(20, safe_int(scene_count, 3)))
    draft = dict((session or {}).get("draft") or {})
    old_plan = dict(draft.get("b14_storyboard_plan") or {})
    old_cards = [dict(item or {}) for item in list(old_plan.get("scene_cards") or [])]
    if old_cards and len(old_cards) == count:
        draft["b14_scene_count"] = count
        draft["b14_scene_resize_note"] = ""
        session["draft"] = draft
        save_video_session(user_id, session)
        return session, ""
    note = ""
    if old_cards and len(old_cards) > count:
        new_plan = dict(old_plan)
        merged_cards = []
        for idx, card in enumerate(old_cards[:count], 1):
            card = dict(card)
            card["scene_index"] = idx
            merged_cards.append(card)
        new_plan["scene_cards"] = merged_cards
        note = f"TOAN AAS sẽ rút gọn storyboard còn {count} cảnh."
    else:
        generated = video_b14_build_storyboard_for_session(user_id, session, scene_count=count)
        session = get_video_session(user_id)
        generated_plan = generated.to_dict()
        generated_cards = [dict(item or {}) for item in list(generated_plan.get("scene_cards") or [])]
        merged_cards = []
        for idx in range(count):
            if idx < len(old_cards):
                card = dict(old_cards[idx])
                card["scene_index"] = idx + 1
                merged_cards.append(card)
            elif idx < len(generated_cards):
                card = dict(generated_cards[idx])
                card["scene_index"] = idx + 1
                merged_cards.append(card)
        new_plan = dict(generated_plan)
        new_plan["scene_cards"] = merged_cards
        if old_cards and count > len(old_cards):
            note = f"TOAN AAS đã giữ {len(old_cards)} cảnh cũ và mở rộng storyboard lên {count} cảnh."
    draft = dict((get_video_session(user_id).get("draft") if old_cards and len(old_cards) <= count else session.get("draft")) or {})
    draft.update({
        "b14_storyboard_plan": new_plan,
        "prompt_bundle": video_b14_prompt_bundle_from_plan_payload(new_plan),
        "b14_scene_count": count,
        "b14_scene_resize_note": note,
        "provider_called": False,
        "xu_charged": 0,
    })
    session["draft"] = draft
    save_video_session(user_id, session)
    return session, note


def video_b14_default_addon_plan(profile_id: str = "storytelling") -> dict:
    profile = video_profiles.get_video_profile(profile_id)
    defaults = dict(profile.postprocess_defaults or {})
    voice_volume = int(round(float(defaults.get("voice_volume", 1.0) or 0.0) * 100))
    music_volume = int(round(float(defaults.get("music_volume", 0.0) or 0.0) * 100))
    voice_enabled = voice_volume > 0 and "usually no voice" not in str(profile.voice_style).lower()
    music_enabled = music_volume > 0
    default_voice_source = "default_male" if voice_enabled else "none"
    default_voice_id = default_tts_voice_id("male") if voice_enabled else ""
    return {
        "voice_enabled": bool(voice_enabled),
        "voice_source": default_voice_source,
        "voice_id": "",
        "voice_provider_voice_id": default_voice_id,
        "voice_profile_id": 0,
        "voice_label": "Nam mặc định" if voice_enabled else "",
        "video_voice_speed": VIDEO_AUDIO_DEFAULT_VOICE_SPEED,
        "voice_speed": VIDEO_AUDIO_DEFAULT_VOICE_SPEED,
        "voice_volume_percent": max(70, min(120, voice_volume or 100)),
        "voice_speed_percent": 100,
        "music_enabled": bool(music_enabled),
        "music_source": "default" if music_enabled else "none",
        "music_id": "",
        "video_music_speed": VIDEO_AUDIO_DEFAULT_MUSIC_SPEED,
        "music_speed": VIDEO_AUDIO_DEFAULT_MUSIC_SPEED,
        "music_volume_percent": min(VIDEO_B14_2_MUSIC_VOLUME_OPTIONS, key=lambda item: abs(item - (music_volume or 10))),
        "sfx_enabled": bool(profile.sfx_policy),
        "subtitle_enabled": bool(defaults.get("burn_subtitles", True)),
        "subtitle_source": "from_narration" if defaults.get("burn_subtitles", True) else "none",
        "subtitle_target_language": "",
        "dub_enabled": False,
        "dub_source": "none",
        "dub_target_language": "",
        "dub_voice_source": "same_as_voice",
        "logo_enabled": False,
        "logo_source": "none",
        "logo_text": "",
        "logo_file_id": "",
        "logo_position": str(defaults.get("logo_position") or "bottom_right"),
        "logo_opacity_percent": int(round(float(defaults.get("logo_opacity", 0.82) or 0.82) * 100)),
    }


def video_b14_addon_plan_from_session(session: dict | None = None) -> dict:
    draft = dict((session or {}).get("draft") or {})
    plan = dict(draft.get("b14_addon_plan") or {})
    defaults = video_b14_default_addon_plan(str(draft.get("b14_profile_id") or video_b14_profile_id_for_session(session)))
    defaults.update({key: value for key, value in plan.items() if key in defaults})
    logo_source = str(defaults.get("logo_source") or "none")
    if logo_source not in {"none", "text"}:
        logo_text_value = logo_watermark_clean_text(defaults.get("logo_text") or "")
        defaults["logo_file_id"] = ""
        if logo_text_value:
            defaults["logo_source"] = "text"
            defaults["logo_text"] = logo_text_value
        else:
            defaults["logo_enabled"] = False
            defaults["logo_source"] = "none"
    for extra_key in ("narration_text", "music_note", "sfx_note", "subtitle_note", "dub_note", "logo_note"):
        if extra_key in plan:
            defaults[extra_key] = str(plan.get(extra_key) or "")
    return defaults


def video_b14_set_addon_plan(user_id, session: dict, **fields) -> dict:
    draft = dict((session or {}).get("draft") or {})
    plan = video_b14_addon_plan_from_session(session)
    plan.update({key: value for key, value in fields.items() if key in plan})
    for extra_key in ("narration_text", "music_note", "sfx_note", "subtitle_note", "dub_note", "logo_note"):
        if extra_key in fields:
            plan[extra_key] = str(fields.get(extra_key) or "")[:4000]
    draft["b14_addon_plan"] = plan
    session["draft"] = draft
    return save_video_session(user_id, session)


