def video_b14_narration_from_storyboard(session: dict | None = None) -> str:
    draft = dict((session or {}).get("draft") or {})
    addon_plan = dict(draft.get("b14_addon_plan") or {})
    saved = str(addon_plan.get("narration_text") or "").strip()
    if saved:
        return saved[:3500]
    plan = dict(draft.get("b14_storyboard_plan") or {})
    lines = []
    for card in list(plan.get("scene_cards") or [])[:20]:
        line = str(card.get("narration_line") or card.get("subtitle_line") or card.get("visual_goal") or "").strip()
        if line:
            lines.append(f"Cảnh {safe_int(card.get('scene_index'), len(lines) + 1)}: {line}")
    if lines:
        return "\n".join(lines)[:3500]
    topic = str((session or {}).get("topic") or draft.get("topic") or "video của anh/chị").strip()
    return f"Cảnh 1: {topic}\nCảnh 2: nhấn lợi ích chính.\nCảnh 3: kết thúc bằng lời kêu gọi hành động."


def video_b14_narration_source(session: dict | None = None) -> dict:
    draft = dict((session or {}).get("draft") or {})
    addon_plan = dict(draft.get("b14_addon_plan") or {})
    manual = str(addon_plan.get("narration_text") or "").strip()
    if manual:
        return {"ok": True, "source": "manual", "text": manual[:3500]}
    plan = dict(draft.get("b14_storyboard_plan") or {})
    lines = []
    for card in list(plan.get("scene_cards") or [])[:20]:
        line = str(card.get("narration_line") or card.get("subtitle_line") or "").strip()
        if line:
            lines.append(f"Cảnh {safe_int(card.get('scene_index'), len(lines) + 1)}: {line}")
    if lines:
        return {"ok": True, "source": "storyboard", "text": "\n".join(lines)[:3500]}
    generated = video_b14_narration_from_storyboard(session)
    if generated.strip():
        return {"ok": True, "source": "generated", "text": generated[:3500]}
    return {
        "ok": False,
        "source": "missing",
        "text": "",
        "public_message": "TOAN AAS cần lời đọc trước khi bật voice. Anh/chị bấm Sửa lời đọc rồi gửi kịch bản muốn đọc.",
    }


def video_b14_saved_voice_profiles(user_id, limit: int = 5) -> list[dict]:
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=False)
    except Exception:
        rows = []
    return [dict(row) for row in rows if voice_profile_can_generate_tts(row)]


def voice_core_vault_lookup(user_id, *, source: str = "saved", limit: int = 5, include_inactive: bool = False) -> list[dict]:
    source = str(source or "saved").strip().lower()
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=include_inactive)
    except Exception:
        rows = []
    if source in {"uploaded", "uploaded_voice"}:
        rows = [row for row in rows if str(row.get("source_file_id") or row.get("source_file_ref") or "").strip()]
    entries = []
    for row in rows:
        entry = minimax_voice_adapter.voice_vault_entry(row, source="uploaded" if source in {"uploaded", "uploaded_voice"} else "saved")
        if not entry.ok:
            continue
        entries.append({
            "id": entry.profile_id,
            "display_name": entry.display_name,
            "provider_voice_id": entry.provider_voice_id,
            "source": entry.source,
            "status": str(row.get("status") or ""),
        })
    return entries


def video_b14_uploaded_voice_profiles(user_id, limit: int = 5) -> list[dict]:
    try:
        rows = user_voice_profile_rows(user_id, max(1, int(limit or 5)), 0, include_inactive=False)
    except Exception:
        rows = []
    return [
        dict(row)
        for row in rows
        if voice_profile_can_generate_tts(row)
        and str(row.get("source_file_id") or row.get("source_file_ref") or "").strip()
    ]


