def video_reference_segment_plan_text(state: dict | None = None, lang: str = "vi") -> str:
    state = state or {}
    duration = max(1, _safe_int(state.get("source_duration"), 0))
    segment_limit = max(1, int(VIDEO_PROVIDER_RENDER_MAX_SECONDS or 60))
    segment_count = max(1, math.ceil(duration / segment_limit)) if duration else 1
    if normalize_user_language(lang) != "vi":
        return (
            "✂️ <b>Reference-video segment plan</b>\n\n"
            f"Reference duration: <b>{duration}s</b>\n"
            f"Render limit per segment: <b>{segment_limit}s</b>\n"
            f"Suggested segments: <b>{segment_count}</b>\n\n"
            "Each segment keeps one hook/idea, one camera goal and a clean transition into the next segment. "
            "TOAN AAS only stores Telegram media metadata in this planning session; it does not load the full video into Railway memory.\n\n"
            "Planning only. No final processing has started and no Xu has been charged."
        )
    return (
        "✂️ <b>Kế hoạch chia video mẫu</b>\n\n"
        f"Thời lượng video mẫu: <b>{duration} giây</b>\n"
        f"Giới hạn render mỗi đoạn: <b>{segment_limit} giây</b>\n"
        f"Số đoạn đề xuất: <b>{segment_count}</b>\n\n"
        "Mỗi đoạn giữ một hook/ý chính, một mục tiêu camera và một điểm chuyển rõ sang đoạn tiếp theo. "
        "Trong bước planning, TOAN AAS chỉ giữ metadata/file ID Telegram, không nạp toàn bộ video vào RAM Railway.\n\n"
        "TOAN AAS chưa xử lý video thật và chưa trừ Xu."
    )

def video_reference_media_info(message) -> dict:
    video = getattr(message, "video", None)
    audio = getattr(message, "audio", None)
    voice = getattr(message, "voice", None)
    document = getattr(message, "document", None)
    media = video or audio or voice or document
    if not media:
        return {}
    mime_type = str(getattr(media, "mime_type", "") or ("video/mp4" if video else "audio/ogg" if voice else "audio/mpeg" if audio else "")).lower()
    file_name = str(getattr(media, "file_name", "") or ("reference_video.mp4" if video else "reference_audio.ogg" if voice else "reference_audio.mp3"))
    file_name_l = file_name.lower()
    is_video = bool(video or mime_type.startswith("video/") or file_name_l.endswith((".mp4", ".mov", ".mkv", ".webm")))
    is_audio = bool(audio or voice or mime_type.startswith("audio/") or file_name_l.endswith((".mp3", ".wav", ".m4a", ".ogg", ".oga", ".aac")))
    if not (is_video or is_audio):
        return {}
    return {
        "file_id": str(getattr(media, "file_id", "") or ""),
        "file_unique_id": str(getattr(media, "file_unique_id", "") or ""),
        "file_name": file_name,
        "mime_type": mime_type or ("video/mp4" if is_video else "audio/mpeg"),
        "duration": int(getattr(media, "duration", 0) or 0),
        "file_size": int(getattr(media, "file_size", 0) or 0),
        "width": int(getattr(media, "width", 0) or 0),
        "height": int(getattr(media, "height", 0) or 0),
        "media_kind": "video" if is_video else "audio",
    }

def video_dubbing_subtitle_document_info(message) -> dict:
    document = getattr(message, "document", None) if message else None
    if not document:
        return {}
    file_name = str(getattr(document, "file_name", "") or "captions.srt")
    file_name_l = file_name.lower()
    mime_type = str(getattr(document, "mime_type", "") or "").lower()
    guessed = str(mimetypes.guess_type(file_name)[0] or "").lower()
    subtitle_mimes = {"text/plain", "text/vtt", "application/x-subrip", "application/srt"}
    if not (
        file_name_l.endswith((".srt", ".vtt", ".txt"))
        or mime_type in subtitle_mimes
        or guessed in subtitle_mimes
    ):
        return {}
    return {
        "file_id": str(getattr(document, "file_id", "") or ""),
        "file_unique_id": str(getattr(document, "file_unique_id", "") or ""),
        "file_name": file_name,
        "mime_type": mime_type or guessed or "text/plain",
        "duration": 0,
        "file_size": int(getattr(document, "file_size", 0) or 0),
        "media_kind": "subtitle_file",
    }

def video_dubbing_is_subtitle_text_source(state: dict | None = None, content_type: str = "") -> bool:
    state = dict(state or {})
    file_name = str(state.get("source_file_name") or state.get("file_name") or "").strip().lower()
    mime_type = str(content_type or state.get("source_mime_type") or state.get("mime_type") or "").strip().lower()
    source_kind = str(state.get("source_kind") or "").strip().lower()
    return bool(
        source_kind in {"subtitle_file", "transcript_file", "text_file"}
        or file_name.endswith((".srt", ".vtt", ".txt"))
        or mime_type in {"text/plain", "text/vtt", "application/x-subrip", "application/srt"}
    )

async def handle_video_reference_pending_upload(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_developing_video_pending(uid)
    if not pending or pending.get("flow") != "videoref" or pending.get("step") != "await_video":
        return False
    info = video_reference_media_info(update.message)
    if not info:
        return False
    lang = get_user_language(uid) or "vi"
    if not VIDEO_ANALYZE_ENABLED:
        await update.message.reply_text(
            "🎞 Công cụ phân tích video mẫu đang bảo trì. TOAN AAS chưa gọi provider và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "🎞 Reference-video analysis is under maintenance. No provider call and no Xu charge.",
            reply_markup=video_reference_start_keyboard(lang),
        )
        return True
    if info.get("duration") and int(info["duration"]) > int(VIDEO_SAMPLE_MAX_SECONDS or 600):
        await update.message.reply_text(
            f"⚠️ Video mẫu vượt giới hạn {int(VIDEO_SAMPLE_MAX_SECONDS or 600)} giây. Vui lòng gửi video ngắn hơn. Bot chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else f"⚠️ The reference video exceeds {int(VIDEO_SAMPLE_MAX_SECONDS or 600)} seconds. Send a shorter video. No Xu charged.",
            reply_markup=video_reference_start_keyboard(lang),
        )
        return True
    max_bytes = int(VIDEO_SAMPLE_MAX_MB or 100) * 1024 * 1024
    if info.get("file_size") and int(info["file_size"]) > max_bytes:
        await update.message.reply_text(
            f"⚠️ Video mẫu vượt giới hạn {int(VIDEO_SAMPLE_MAX_MB or 100)} MB. Vui lòng gửi file nhỏ hơn. Bot chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else f"⚠️ The reference video exceeds {int(VIDEO_SAMPLE_MAX_MB or 100)} MB. Send a smaller file. No Xu charged.",
            reply_markup=video_reference_start_keyboard(lang),
        )
        return True
    remember_last_media(update)
    cache_recent_media_state(update)
    ref_id = add_reference_video(
        uid,
        title=info.get("file_name") or "reference video",
        path_or_url=f"telegram_file:{info.get('file_id')}",
        platform="",
        pattern_hint="pending_analysis",
        tags="reference,telegram-upload",
        note="Metadata only; uploaded file is not retained as a permanent free asset.",
    )
    if ref_id:
        width = _safe_int(info.get("width"), 0)
        height = _safe_int(info.get("height"), 0)
        aspect_ratio = "9:16" if height > width else ("16:9" if width > height else "1:1")
        update_reference_video_metadata(
            ref_id,
            uid,
            user_id=str(uid),
            source_type="upload",
            telegram_file_id=info.get("file_id") or "",
            duration_seconds=_safe_int(info.get("duration"), 0),
            aspect_ratio=aspect_ratio,
            safety_notes=REFERENCE_SAFETY_NOTE,
            status="draft",
        )
    set_developing_video_pending(
        uid,
        "videoref",
        "direction",
        source_file_id=info.get("file_id"),
        source_file_name=info.get("file_name"),
        source_mime_type=info.get("mime_type"),
        source_duration=info.get("duration"),
        source_file_size=info.get("file_size"),
        source_width=info.get("width"),
        source_height=info.get("height"),
        reference_id=ref_id,
    )
    state = get_developing_video_pending(uid) or {}
    await update.message.reply_text(
        video_reference_direction_text(state, lang),
        parse_mode="HTML",
        reply_markup=video_reference_direction_keyboard(lang),
    )
    return True

