    if normalize_user_language(lang) != "vi":
        labels = {
            "professional": "professional",
            "viral": "viral/TikTok",
            "cinematic": "cinematic",
        }
        return labels.get(code, str(style or "custom style"))
    labels = {
        "professional": "chuyên nghiệp",
        "viral": "viral/TikTok",
        "cinematic": "cinematic",
    }
    return labels.get(code, str(style or "phong cách riêng"))

