async def handle_video_reference_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    value = parts[2] if len(parts) > 2 else ""

    if action == "hub":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, video_reference_hub_text(lang), parse_mode="HTML", reply_markup=video_reference_hub_keyboard(lang))
    if action == "profile":
        clear_developing_video_pending(uid)
        profile = get_latest_channel_profile(uid)
        return await safe_edit_or_send(query, channel_profile_text(profile, lang), parse_mode="HTML", reply_markup=channel_profile_keyboard(lang))
    if action == "profile_create":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "profile_platform", language=lang)
        text = "📺 Kênh của bạn đăng ở đâu?" if normalize_user_language(lang) == "vi" else "📺 Which platform is your channel on?"
        return await safe_edit_or_send(query, text, reply_markup=channel_profile_platform_keyboard(lang))
    if action == "profile_platform":
        set_developing_video_pending(uid, "videoref", "profile_niche", platform=value or "other", language=lang)
        text = "1/6. Hãy nhập ngành/chủ đề chính của kênh." if normalize_user_language(lang) == "vi" else "1/6. Enter the channel niche."
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Hồ sơ kênh", "videoref|profile")))
    if action == "profile_affiliate":
        state = get_developing_video_pending(uid) or {}
        restore_developing_video_pending(uid, "videoref", state, "profile_goal")
        set_developing_video_pending(uid, "videoref", "profile_goal", affiliate_allowed=(value == "yes"))
        text = "6/6. Mục tiêu chính của kênh là gì?" if normalize_user_language(lang) == "vi" else "6/6. What is the main channel goal?"
        return await safe_edit_or_send(query, text, reply_markup=channel_profile_goal_keyboard(lang))
    if action == "profile_goal":
        state = get_developing_video_pending(uid) or {}
        state["primary_goal"] = value or "content"
        profile_id = create_channel_profile(uid, state)
        clear_developing_video_pending(uid)
        profile = get_latest_channel_profile(uid)
        prefix = "✅ Đã lưu hồ sơ kênh.\n\n" if profile_id and normalize_user_language(lang) == "vi" else ("✅ Channel profile saved.\n\n" if profile_id else "⚠️ Không lưu được hồ sơ kênh.\n\n")
        return await safe_edit_or_send(query, prefix + channel_profile_text(profile, lang), parse_mode="HTML", reply_markup=channel_profile_keyboard(lang))
    if action == "catalog":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(
            query,
            reference_catalog_text(uid, lang),
            parse_mode="HTML",
            reply_markup=video_v6_keyboard(
                [("📤 Thêm video mẫu" if normalize_user_language(lang) == "vi" else "📤 Add reference", "videoref|start")],
                lang,
                back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub"),
            ),
        )
    if action == "link":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "link_input")
        text = (
            "🔗 Hãy gửi link video tham khảo.\n\nGiai đoạn này TOAN AAS không tải video từ nền tảng. Bot sẽ lưu link/metadata an toàn và yêu cầu upload file hoặc mô tả thủ công để phân tích. Không trừ Xu."
            if normalize_user_language(lang) == "vi" else
            "🔗 Send the reference link. TOAN AAS does not download platform videos in this phase; upload the file or provide a manual description. No Xu charged."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub")))
    if action == "manual":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "manual_description")
        text = "✍️ Hãy mô tả hook, số cảnh, nhịp dựng, visual, caption và CTA của video mẫu." if normalize_user_language(lang) == "vi" else "✍️ Describe the hook, scenes, pacing, visual style, caption and CTA."
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Video mẫu / Kênh mẫu", "videoref|hub")))
    if action == "format":
        plan = get_latest_developing_video_plan(uid, "videoref")
        if plan:
            return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
        return await safe_edit_or_send(
            query,
            "🎬 Hãy upload video mẫu, nhập link/mô tả hoặc chọn format trong kho trước. Bước lập kế hoạch không trừ Xu."
            if normalize_user_language(lang) == "vi" else "🎬 Add a reference or choose a saved format first. Planning does not charge Xu.",
            reply_markup=video_reference_hub_keyboard(lang),
        )
    if action == "publish_package":
        plan = get_latest_developing_video_plan(uid, "videoref") or {"selected_topic": "nội dung theo format kênh"}
        package = create_publish_package(uid, plan, get_latest_channel_profile(uid))
        return await safe_edit_or_send(query, publish_package_text(package, lang), parse_mode="HTML", reply_markup=publish_package_keyboard(lang))
    if action == "save_catalog":
        plan = get_latest_developing_video_plan(uid, "videoref") or {}
        ref_id = _safe_int(plan.get("reference_id"), 0)
        if ref_id:
            update_reference_video_metadata(
                ref_id,
                uid,
                niche=_short_pending_text(plan.get("selected_topic"), 180),
                format_type=_short_pending_text(plan.get("analysis_kind"), 60),
                hook_pattern="hook_0_3s_then_proof_then_cta",
                scene_count=3,
                caption_style="short_channel_aware",
                cta_style="soft_action_cta",
                visual_style="original_adaptation",
                safety_notes=REFERENCE_SAFETY_NOTE,
                status="active",
            )
        text = "📌 Đã lưu metadata/format vào kho mẫu. Không lưu bản video lớn lâu dài và không trừ Xu." if normalize_user_language(lang) == "vi" else "📌 Format metadata saved. No long-term large video storage and no Xu charge."
        return await safe_edit_or_send(query, text, reply_markup=video_reference_result_keyboard(lang))
    if action == "performance":
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "performance_input")
        text = (
            "📊 Nhập hiệu quả bài đăng theo mẫu:\nurl=https://... views=1000 likes=50 comments=5 clicks=10 orders=2 revenue=500000 note=..."
            if normalize_user_language(lang) == "vi" else
            "📊 Enter performance: url=https://... views=1000 likes=50 comments=5 clicks=10 orders=2 revenue=500000 note=..."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_v6_keyboard([], lang, back=("⬅️ Gói đăng bài", "videoref|publish_package")))
    if action == "auto_publish":
        text = (
            "🚫 TOAN AAS hiện chỉ xuất gói đăng bài để bạn tự đăng. Tự động đăng sẽ mở sau khi kết nối kênh hợp lệ và bạn xác nhận rõ. Bot chưa lưu token và chưa đăng nội dung."
            if normalize_user_language(lang) == "vi" else
            "🚫 Manual publish package only. Auto-publish stays disabled until a valid channel is connected and explicitly confirmed."
        )
        return await safe_edit_or_send(query, text, reply_markup=publish_package_keyboard(lang))

    if not VIDEO_ANALYZE_ENABLED:
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

    if action in {"start", "await_video", "back_upload"}:
        clear_developing_video_pending(uid)
        set_developing_video_pending(uid, "videoref", "await_video")
        return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

    pending = get_developing_video_pending(uid)
    plan = get_latest_developing_video_plan(uid, "videoref")
    state = pending or plan or {}
    if state.get("processing") == "1" and VIDEO_WAITING_LOCK_ENABLED:
        return await safe_edit_or_send(
            query,
            "⏳ Yêu cầu trước vẫn đang được xử lý. TOAN AAS chưa tạo thêm job mới."
            if normalize_user_language(lang) == "vi"
            else "⏳ The previous request is still processing. TOAN AAS did not create another job.",
        )
    if action == "back_direction":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "direction")
        return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
    if action == "direction_custom":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "direction_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập hướng phân tích video mẫu." if normalize_user_language(lang) == "vi" else "✍️ Enter the reference-video analysis direction.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại hướng phân tích" if normalize_user_language(lang) == "vi" else "⬅️ Back", "videoref|back_direction")),
        )
    if action == "direction":
        if not state.get("source_file_id"):
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        set_developing_video_pending(uid, "videoref", "topic_suggestions", analysis_kind=value or "ad", suggest_offset=0)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_reference_topic_text(current, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_refresh":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        restore_developing_video_pending(uid, "videoref", state, "topic_suggestions")
        set_developing_video_pending(uid, "videoref", "topic_suggestions", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_reference_topic_text(current, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_custom":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "topic_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập sản phẩm/chủ đề mới." if normalize_user_language(lang) == "vi" else "✍️ Enter the new product/topic.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại 3 gợi ý" if normalize_user_language(lang) == "vi" else "⬅️ Back to suggestions", "videoref|back_topics")),
        )
    if action == "back_topics":
        if not state.get("analysis_kind"):
            return await safe_edit_or_send(query, video_reference_direction_text(state, lang), parse_mode="HTML", reply_markup=video_reference_direction_keyboard(lang))
        restore_developing_video_pending(uid, "videoref", state, "topic_suggestions")
        return await safe_edit_or_send(query, video_reference_topic_text(state, lang), parse_mode="HTML", reply_markup=video_reference_topic_keyboard(lang))
    if action == "topic_choice":
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        topics = video_reference_topic_suggestions(state, lang)
        selected = topics[idx - 1] if idx <= len(topics) else (topics[0] if topics else "")
        working = dict(state)
        working["selected_topic"] = selected
        working["selected_suggestion_index"] = str(idx)
        working["processing"] = "1"
        restore_developing_video_pending(uid, "videoref", working, "processing")
        await safe_edit_or_send(query, video_reference_waiting_text(lang))
        working["processing"] = "0"
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoref", working)
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
    if action == "version_refresh":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        refreshed = dict(plan)
        refreshed["prompt_variant_offset"] = str(_safe_int(refreshed.get("prompt_variant_offset"), 0) + 1)
        refreshed["motion_offset"] = str(_safe_int(refreshed.get("motion_offset"), 0) + 3)
        refreshed["music_offset"] = str(_safe_int(refreshed.get("music_offset"), 0) + 3)
        refreshed = save_developing_video_plan(uid, "videoref", refreshed)
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(refreshed, lang), reply_markup=video_reference_result_keyboard(lang))
    if action == "finalization":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        render_plan = structured_video_plan(plan, "videoref")
        package = {
            "source": "reference_video_plan",
            "concept_text": plan.get("selected_topic") or "",
            "video_prompt": render_plan.get("prompt") or "",
            "music_choice": {"label": "reference-plan audio"},
        }
        source_state = dict(plan)
        source_state["video_prompt"] = package["video_prompt"]
        return await open_video_finalization(query, uid, "videoref", source_state, lang, "videoref|plan", package)
    if action == "image_prompts":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send(
            query,
            video_reference_image_prompts_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "sample_segments":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send(
            query,
            video_reference_segment_plan_text(plan, lang),
            parse_mode="HTML",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "video_prompts":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        duration = max(1, _safe_int(plan.get("source_duration"), 0))
        scene_count = max(3, min(12, math.ceil(duration / max(1, VIDEO_PROVIDER_RENDER_MAX_SECONDS))))
        return await safe_edit_or_send_long_html(
            query,
            detailed_video_scene_prompts_text(plan, "videoref", lang, scene_count=scene_count),
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "frame_plan":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        text = (
            "🎞 <b>Planning ghép ảnh thành video</b>\n\n"
            "1. Tạo/lưu ảnh từng cảnh.\n"
            "2. Gửi ảnh đúng thứ tự.\n"
            "3. Chọn tỉ lệ, thời lượng, hiệu ứng và nhạc.\n"
            "4. Xem giá và xác nhận trước khi render.\n\n"
            "Planning miễn phí. Khi render thật, TOAN AAS giữ nguyên billing Ghép ảnh thành video hiện tại."
            if normalize_user_language(lang) == "vi"
            else
            "🎞 <b>Image slideshow planning</b>\n\nCreate/save scene images, upload them in order, choose ratio/duration/effect/music, then review price before rendering.\n\nPlanning is free. Real rendering keeps the existing frame-video billing."
        )
        return await safe_edit_or_send(
            query,
            text,
            parse_mode="HTML",
            reply_markup=video_v6_keyboard(
                [("📷 Bắt đầu gửi ảnh" if normalize_user_language(lang) == "vi" else "📷 Start uploading images", "framevideo|start")],
                lang,
                back=("⬅️ Quay lại kế hoạch" if normalize_user_language(lang) == "vi" else "⬅️ Back to plan", "videoref|plan"),
            ),
        )
    if action == "generate":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        active = shopaikey_active_job_for_user(uid, "video")
        if active:
            return await safe_edit_or_send(query, public_video_active_job_text(lang), reply_markup=public_video_active_job_keyboard(active, lang))
        render_plan = structured_video_plan(plan, "videoref")
        package = {
            "source": "reference_video_plan",
            "concept_text": plan.get("selected_topic") or "",
            "video_prompt": render_plan.get("prompt") or "",
            "music_choice": {"label": "reference-plan audio"},
        }
        source_state = dict(plan)
        source_state["video_prompt"] = package["video_prompt"]
        return await open_video_finalization(query, uid, "videoref", source_state, lang, "videoref|plan", package)
    if action == "save":
        return await safe_edit_or_send(
            query,
            "💾 Đã lưu kế hoạch video mẫu trong phiên hiện tại. Bot chưa gọi provider và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "💾 Reference-video plan saved in this session. No provider call and no Xu charged.",
            reply_markup=video_reference_result_keyboard(lang),
        )
    if action == "plan":
        if not plan:
            return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))
        return await safe_edit_or_send_long_html(query, video_reference_plan_text(plan, lang), reply_markup=video_reference_result_keyboard(lang))
    return await safe_edit_or_send(query, video_reference_start_text(lang), parse_mode="HTML", reply_markup=video_reference_start_keyboard(lang))

async def handle_self_scene_ai_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    if action == "start":
        clear_developing_video_pending(uid)
        recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
        set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
        go_video_screen(uid, "selfscene:upload", "selfscene")
        return await safe_edit_query_message(
            query,
            self_scene_upload_text(lang, bool(recent.get("file_id"))),
            reply_markup=self_scene_upload_keyboard(lang, bool(recent.get("file_id"))),
        )
    if action == "await_video":
        recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
        set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
        go_video_screen(uid, "selfscene:upload", "selfscene")
        return await safe_edit_query_message(
            query,
            self_scene_upload_text(lang, bool(recent.get("file_id"))),
            reply_markup=self_scene_upload_keyboard(lang, bool(recent.get("file_id"))),
        )
    if action == "plan_without_video":
        set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
        return await safe_edit_query_message(
            query,
            self_scene_upload_text(lang, False),
            reply_markup=self_scene_upload_keyboard(lang, False),
        )
    if action == "use_recent_video":
        recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
        pending_source = get_developing_video_pending(uid) or {}
        source = recent if recent.get("file_id") else pending_source
        if not source.get("file_id") and not source.get("source_file_id"):
            set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
            return await safe_edit_query_message(
                query,
                self_scene_upload_text(lang, False),
                reply_markup=self_scene_upload_keyboard(lang, False),
            )
        set_developing_video_pending(
            uid,
            "selfscene",
            "object",
            input_type="video",
            source_file_id=source.get("file_id") or source.get("source_file_id"),
            source_file_name=source.get("file_name") or source.get("source_file_name") or "self_scene_video.mp4",
            source_mime_type=source.get("mime_type") or source.get("source_mime_type") or "video/mp4",
            source_duration=source.get("duration") or source.get("source_duration") or 0,
            source_file_size=source.get("file_size") or source.get("source_file_size") or 0,
        )
        sync_self_scene_source_video(uid, source, lang)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_object_text(state, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "back_upload":
        pending = get_developing_video_pending(uid) or {}
        recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
        has_source = bool(pending.get("source_file_id") or recent.get("file_id"))
        pop_video_screen(uid, "selfscene:upload")
        return await safe_edit_query_message(
            query,
            self_scene_upload_text(lang, has_source),
            reply_markup=self_scene_upload_keyboard(lang, has_source),
        )
    if action == "direction_refresh":
        current = get_developing_video_pending(uid) or {}
        offset = _safe_int(current.get("style_offset"), 0) + 3
        set_developing_video_pending(uid, "selfscene", "direction", style_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_start_text(lang, state), reply_markup=self_scene_input_keyboard(lang, state))
    if action == "direction_choice":
        state = get_developing_video_pending(uid) or {}
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        options = self_scene_direction_suggestions(_safe_int(state.get("style_offset"), 0), lang)
        selected = options[idx - 1] if idx <= len(options) else (options[0] if options else {})
        direction_text = selected.get("label") or self_scene_direction_label(selected.get("code"), lang)
        next_step = "context" if state.get("source_file_id") and state.get("selected_topic") else "object"
        set_developing_video_pending(uid, "selfscene", next_step, direction=direction_text, direction_code=selected.get("code") or "")
        state = get_developing_video_pending(uid) or {}
        if next_step == "context":
            return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_object_text(state, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "direction":
        direction = parts[2] if len(parts) > 2 else "context"
        state = get_developing_video_pending(uid) or {}
        next_step = "context" if state.get("source_file_id") and state.get("selected_topic") else "object"
        set_developing_video_pending(uid, "selfscene", next_step, direction=direction)
        state = get_developing_video_pending(uid) or {}
        if next_step == "context":
            return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_object_text(state, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "direction_custom":
        set_developing_video_pending(uid, "selfscene", "direction_custom")
        return await safe_edit_query_message(
            query,
            self_scene_direction_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại hướng" if normalize_user_language(lang) == "vi" else "⬅️ Back to directions", "selfscene|back_direction"),
            ),
        )
    if action in {"object", "input"}:
        input_type = parts[2] if len(parts) > 2 else "custom"
        if input_type == "video":
            recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
            if not recent.get("file_id"):
                set_developing_video_pending(uid, "selfscene", "await_video", input_type="video")
                return await safe_edit_query_message(
                    query,
                    "📎 Hãy gửi video tự quay cần đổi cảnh. TOAN AAS chỉ lưu Telegram file ID trong phiên, chưa gọi provider và chưa trừ Xu."
                    if normalize_user_language(lang) == "vi"
                    else "📎 Send the self-shot video to transform. TOAN AAS only keeps its Telegram file ID in this session; no provider call and no Xu charged.",
                    reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại đối tượng" if normalize_user_language(lang) == "vi" else "⬅️ Back to subject", "selfscene|back_object")),
                )
            set_developing_video_pending(
                uid,
                "selfscene",
                "direction",
                input_type="video",
                selected_topic=self_scene_input_label("video", lang),
                source_file_id=recent.get("file_id"),
                source_file_name=recent.get("file_name") or "self_scene_video.mp4",
                source_mime_type=recent.get("mime_type") or "video/mp4",
                source_duration=recent.get("duration") or 0,
                source_file_size=recent.get("file_size") or 0,
            )
            sync_self_scene_source_video(uid, recent, lang)
            state = get_developing_video_pending(uid) or {}
            return await safe_edit_query_message(query, self_scene_start_text(lang, state), reply_markup=self_scene_input_keyboard(lang, state))
        if input_type != "custom":
            subject = self_scene_input_label(input_type, lang)
            next_step = "direction" if (get_developing_video_pending(uid) or {}).get("source_file_id") else "context"
            set_developing_video_pending(uid, "selfscene", next_step, input_type=input_type, selected_topic=subject)
            state = get_developing_video_pending(uid) or {}
            if next_step == "direction":
                return await safe_edit_query_message(query, self_scene_start_text(lang, state), reply_markup=self_scene_input_keyboard(lang, state))
            return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "describe", input_type=input_type)
        return await safe_edit_query_message(
            query,
            self_scene_describe_text(input_type, lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại đối tượng" if normalize_user_language(lang) == "vi" else "⬅️ Back to subject", "selfscene|back_object"),
            ),
        )
    pending = get_developing_video_pending(uid)
    if action == "back_direction":
        if not pending:
            recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
            return await safe_edit_query_message(
                query,
                self_scene_upload_text(lang, bool(recent.get("file_id"))),
                reply_markup=self_scene_upload_keyboard(lang, bool(recent.get("file_id"))),
            )
        restore_developing_video_pending(uid, "selfscene", pending, "direction")
        state = get_developing_video_pending(uid) or pending
        return await safe_edit_query_message(query, self_scene_start_text(lang, state), reply_markup=self_scene_input_keyboard(lang, state))
    if action == "back_object":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_object_text(pending, lang), reply_markup=self_scene_object_keyboard(lang))
    if action == "back_context":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_context_text(pending, lang), reply_markup=self_scene_context_keyboard(lang))
    if action == "back_style":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_style_text(pending, lang), reply_markup=self_scene_style_keyboard(lang))
    if action == "back_music":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        return await safe_edit_query_message(query, self_scene_music_text(pending, lang), reply_markup=self_scene_music_keyboard(lang))
    if action == "context_custom":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "context_custom")
        return await safe_edit_query_message(
            query,
            self_scene_context_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại ngữ cảnh" if normalize_user_language(lang) == "vi" else "⬅️ Back to contexts", "selfscene|back_context"),
            ),
        )
    if action == "context_refresh":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        offset = _safe_int(pending.get("suggest_offset"), 0) + 3
        set_developing_video_pending(uid, "selfscene", "context", suggest_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_context_text(state, lang), reply_markup=self_scene_context_keyboard(lang))
    if action == "context":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        options = self_scene_context_suggestions(pending.get("input_type"), pending.get("selected_topic"), lang, _safe_int(pending.get("suggest_offset"), 0))
        selected = options[idx - 1] if idx <= len(options) else options[0]
        set_developing_video_pending(uid, "selfscene", "style", selected_context=selected)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_style_text(state, lang), reply_markup=self_scene_style_keyboard(lang))
    if action == "style_custom":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "style_custom")
        return await safe_edit_query_message(
            query,
            self_scene_style_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại chuyển động" if normalize_user_language(lang) == "vi" else "⬅️ Back to motion", "selfscene|back_style"),
            ),
        )
    if action == "style_refresh":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        offset = _safe_int(pending.get("motion_offset"), 0) + 3
        set_developing_video_pending(uid, "selfscene", "style", motion_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_style_text(state, lang), reply_markup=self_scene_style_keyboard(lang))
    if action in {"style", "style_choice"}:
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        style = parts[2] if len(parts) > 2 else "pushin"
        if action == "style_choice":
            try:
                idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
            except Exception:
                idx = 1
            options = guided_video_motion_suggestions(pending, lang)
            selected = options[idx - 1] if idx <= len(options) else (options[0] if options else {})
            style = selected.get("code") or selected.get("label") or "pushin"
        set_developing_video_pending(uid, "selfscene", "addons", selected_motion=style, selected_style=style, selected_music="none")
        state = get_developing_video_pending(uid) or {}
        plan = save_developing_video_plan(uid, "selfscene", state)
        package = developing_video_public_package(plan, "selfscene", lang)
        return await open_video_finalization(query, uid, "selfscene", plan, lang, "selfscene|back_style", package)
    if action == "music_custom":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        set_developing_video_pending(uid, "selfscene", "music_custom")
        return await safe_edit_query_message(
            query,
            self_scene_music_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại âm thanh" if normalize_user_language(lang) == "vi" else "⬅️ Back to audio", "selfscene|back_music"),
            ),
        )
    if action == "music_refresh":
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        offset = _safe_int(pending.get("music_offset"), 0) + 3
        set_developing_video_pending(uid, "selfscene", "music", music_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, self_scene_music_text(state, lang), reply_markup=self_scene_music_keyboard(lang))
    if action in {"music", "music_choice"}:
        if not pending:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        music = parts[2] if len(parts) > 2 else "cinematic"
        if action == "music_choice":
            try:
                idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
            except Exception:
                idx = 1
            options = guided_video_music_suggestions(pending, lang)
            selected = options[idx - 1] if idx <= len(options) else (options[0] if options else {})
            music = selected.get("code") or selected.get("label") or "cinematic"
        state = dict(pending)
        state["selected_music"] = "none" if str(music).lower() in {"none", "skip", ""} else music
        state["step"] = "addons"
        plan = save_developing_video_plan(uid, "selfscene", state)
        package = developing_video_public_package(plan, "selfscene", lang)
        return await open_video_finalization(query, uid, "selfscene", plan, lang, "selfscene|back_style", package)
    if action == "plan":
        plan = get_latest_developing_video_plan(uid, "selfscene")
        if not plan:
            recent = get_recent_media_state(LAST_USER_VIDEO, uid) or {}
            return await safe_edit_query_message(
                query,
                self_scene_upload_text(lang, bool(recent.get("file_id"))),
                reply_markup=self_scene_upload_keyboard(lang, bool(recent.get("file_id"))),
            )
        return await safe_edit_query_message(query, self_scene_plan_text(plan, lang), reply_markup=self_scene_result_keyboard(lang))
    if action == "video_guard":
        plan = get_latest_developing_video_plan(uid, "selfscene")
        if not plan:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        if not plan.get("source_file_id"):
            return await safe_edit_query_message(
                query,
                developing_video_render_guard_text("selfscene", lang, source_ready=False),
                parse_mode="HTML",
                reply_markup=self_scene_result_keyboard(lang),
            )
        package = developing_video_public_package(plan, "selfscene", lang)
        return await open_video_finalization(query, uid, "selfscene", plan, lang, "selfscene|plan", package)
    if action == "finalization":
        plan = get_latest_developing_video_plan(uid, "selfscene")
        if not plan:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        package = developing_video_public_package(plan, "selfscene", lang)
        return await open_video_finalization(query, uid, "selfscene", plan, lang, "selfscene|plan", package)
    if action in {"image_guard", "frame_hint", "music_guard", "save"}:
        plan = get_latest_developing_video_plan(uid, "selfscene")
        if not plan:
            return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))
        if action == "frame_hint":
            photos = developing_video_frame_photos(plan)
            if len(photos) >= 2:
                return await open_existing_images_in_frame_video(query, uid, photos, "selfscene_plan", lang=lang)
        return await safe_edit_query_message(query, self_scene_guard_text(action, lang, plan), reply_markup=self_scene_result_keyboard(lang))
    return await safe_edit_query_message(query, self_scene_start_text(lang), reply_markup=self_scene_input_keyboard(lang))

async def handle_long_video_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    if not is_admin_user(uid):
        clear_developing_video_pending(uid)
        return await safe_edit_query_message(
            query,
            MULTISCENE_LONG_VIDEO_GUARD_TEXT,
            parse_mode=None,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("⬅️ Menu video" if normalize_user_language(lang) == "vi" else "⬅️ Video menu", callback_data="menu|main_video")],
                [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
            ]),
        )
    if action == "start":
        clear_developing_video_pending(uid)
        return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
    if action == "topic_custom":
        set_developing_video_pending(uid, "longvideo", "topic_custom")
        return await safe_edit_query_message(query, long_video_topic_custom_text(lang), reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🔙 Quay lại" if normalize_user_language(lang) == "vi" else "🔙 Back", callback_data="longvideo|start")],
            [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
        ]))
    if action == "topic":
        topic_key = parts[2] if len(parts) > 2 else "sales"
        set_developing_video_pending(uid, "longvideo", "topic_suggestions", topic_key=topic_key, suggest_offset=0)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, long_video_topic_suggestions_text(state, lang), reply_markup=long_video_topic_suggestions_keyboard(lang))
    pending = get_developing_video_pending(uid)
    saved_plan = get_latest_developing_video_plan(uid, "longvideo")
    if action == "topic_refresh":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        offset = _safe_int(pending.get("suggest_offset"), 0) + 3
        set_developing_video_pending(uid, "longvideo", "topic_suggestions", suggest_offset=offset)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, long_video_topic_suggestions_text(state, lang), reply_markup=long_video_topic_suggestions_keyboard(lang))
    if action == "topic_choice":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        options = long_video_topic_suggestions(pending.get("topic_key"), _safe_int(pending.get("suggest_offset"), 0), lang)
        topic = options[idx - 1] if idx <= len(options) else (options[0] if options else long_video_topic_label(pending.get("topic_key"), lang))
        set_developing_video_pending(uid, "longvideo", "duration", selected_topic=topic)
        return await safe_edit_query_message(query, long_video_duration_text(topic, lang), reply_markup=long_video_duration_keyboard(lang))
    if action == "back_topic_suggestions":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        restore_developing_video_pending(uid, "longvideo", pending, "topic_suggestions")
        return await safe_edit_query_message(query, long_video_topic_suggestions_text(pending, lang), reply_markup=long_video_topic_suggestions_keyboard(lang))
    if action == "back_duration":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        return await safe_edit_query_message(query, long_video_duration_text(pending.get("selected_topic") or long_video_topic_label(pending.get("topic_key"), lang), lang), reply_markup=long_video_duration_keyboard(lang))
    if action == "back_style":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        return await safe_edit_query_message(query, long_video_style_text(pending, lang), reply_markup=long_video_style_keyboard(lang))
    if action == "back_structure":
        state = pending or saved_plan
        if not state:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        restore_developing_video_pending(uid, "longvideo", state, "structure")
        return await safe_edit_query_message(
            query,
            long_video_structure_text(state, lang),
            reply_markup=long_video_structure_keyboard(state.get("duration"), lang),
        )
    if action == "duration_custom":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        set_developing_video_pending(uid, "longvideo", "duration_custom")
        return await safe_edit_query_message(
            query,
            long_video_duration_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("🔙 Quay lại thời lượng" if normalize_user_language(lang) == "vi" else "🔙 Back to duration", "longvideo|back_duration"),
            ),
        )
    if action == "duration":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        duration = parts[2] if len(parts) > 2 else "10 phút"
        set_developing_video_pending(uid, "longvideo", "style", duration=duration)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, long_video_style_text(state, lang), reply_markup=long_video_style_keyboard(lang))
    if action == "style_custom":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        set_developing_video_pending(uid, "longvideo", "style_custom")
        return await safe_edit_query_message(
            query,
            long_video_style_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("🔙 Quay lại phong cách" if normalize_user_language(lang) == "vi" else "🔙 Back to style", "longvideo|back_style"),
            ),
        )
    if action == "style":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        style = parts[2] if len(parts) > 2 else "professional"
        set_developing_video_pending(uid, "longvideo", "structure", selected_style=style)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_query_message(query, long_video_structure_text(state, lang), reply_markup=long_video_structure_keyboard(state.get("duration"), lang))
    if action == "structure_custom":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        set_developing_video_pending(uid, "longvideo", "structure_custom")
        return await safe_edit_query_message(
            query,
            long_video_structure_custom_text(lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("🔙 Quay lại cấu trúc" if normalize_user_language(lang) == "vi" else "🔙 Back to structure", "longvideo|back_structure"),
            ),
        )
    if action == "structure":
        if not pending:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        options = long_video_structure_suggestions(pending.get("duration"), lang)
        state = dict(pending)
        state["structure"] = options[idx - 1] if idx <= len(options) else options[0]
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "longvideo", state)
        project_id = create_long_video_project_from_plan(uid, plan, "ai_story_film")
        if project_id:
            plan["project_id"] = project_id
        return await safe_edit_or_send_long_html(query, long_video_plan_text(plan, lang), reply_markup=long_video_result_keyboard(lang))
    if action == "finalization":
        plan = saved_plan
        if not plan:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        package = developing_video_public_package(plan, "longvideo", lang)
        package["concept_text"] = f"Segment 1/{plan.get('structure') or 'long-form plan'}: {package.get('concept_text') or ''}"
        return await open_video_finalization(query, uid, "longvideo", plan, lang, "longvideo|back_structure", package)
    if action == "frame_video":
        plan = saved_plan
        if not plan:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        photos = developing_video_frame_photos(plan)
        if len(photos) >= 2:
            return await open_existing_images_in_frame_video(query, uid, photos, "longvideo_plan", lang=lang)
        text = (
            "⚠️ Lộ trình video dài chưa có bộ ảnh phân đoạn. Hãy tạo/lưu ít nhất 2 ảnh rồi dùng Ghép ảnh thành video. Bot chưa render và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "⚠️ This long-form roadmap has no segment image set yet. Create/save at least two images before using image slideshow video. No render and no Xu charged."
        )
        return await safe_edit_or_send(query, text, reply_markup=long_video_result_keyboard(lang))
    if action == "render_segments":
        plan = saved_plan
        if not plan:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        active = shopaikey_active_job_for_user(uid, "video")
        if active:
            return await safe_edit_or_send(query, public_video_active_job_text(lang), reply_markup=public_video_active_job_keyboard(active, lang))
        package = developing_video_public_package(plan, "longvideo", lang)
        package["concept_text"] = f"Segment 1/{plan.get('structure') or 'long-form plan'}: {package.get('concept_text') or ''}"
        return await open_video_finalization(query, uid, "longvideo", plan, lang, "longvideo|back_structure", package)
    if action in {"storyboard", "image_prompts", "video_prompts", "music", "save"}:
        plan = saved_plan
        if not plan:
            return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))
        if action == "save" and not plan.get("project_id"):
            project_id = create_long_video_project_from_plan(uid, plan, "ai_story_film")
            if project_id:
                plan["project_id"] = project_id
        return await safe_edit_or_send_long_html(query, long_video_followup_text(action, plan, lang), reply_markup=long_video_result_keyboard(lang))
    return await safe_edit_query_message(query, long_video_start_text(lang), reply_markup=long_video_topic_keyboard(lang))

async def handle_storyboard_pack_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    pending = get_developing_video_pending(uid)
    plan = get_latest_developing_video_plan(uid, "storypack")

    def _state_for_storypack() -> dict:
        return dict(pending or plan or {})

    if action == "start":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
    if action == "template":
        template = parts[2] if len(parts) > 2 else "product_ad"
        set_developing_video_pending(uid, "storypack", "topic", reference_template=template)
        state = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, storyboard_pack_topic_text(state, lang), reply_markup=storyboard_pack_topic_keyboard(lang), parse_mode="HTML")
    if action == "back_topic":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        restore_developing_video_pending(uid, "storypack", state, "topic")
        return await safe_edit_or_send(query, storyboard_pack_topic_text(state, lang), reply_markup=storyboard_pack_topic_keyboard(lang), parse_mode="HTML")
    if action == "brief_custom":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        restore_developing_video_pending(uid, "storypack", state, "brief_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập thêm yêu cầu ngắn, ví dụ: sang trọng hơn, ít chữ hơn, thêm CTA cuối.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Thiết lập nhanh", "storypack|back_brief")),
            parse_mode="HTML",
        )
    if action == "back_brief":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        restore_developing_video_pending(uid, "storypack", state, "brief")
        return await safe_edit_or_send(query, storyboard_pack_brief_text(state, lang), reply_markup=storyboard_pack_brief_keyboard(lang), parse_mode="HTML")
    if action in {"set_platform", "set_ratio", "set_duration", "set_style", "set_goal"}:
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        value = parts[2] if len(parts) > 2 else ""
        if action == "set_platform":
            state["platform"] = value
        elif action == "set_ratio":
            state["preferred_aspect_ratio"] = value
        elif action == "set_duration":
            state["duration"] = value
        elif action == "set_style":
            state["selected_style"] = value
        elif action == "set_goal":
            state["goal"] = value
        restore_developing_video_pending(uid, "storypack", state, "brief")
        return await safe_edit_or_send(query, storyboard_pack_brief_text(state, lang), reply_markup=storyboard_pack_brief_keyboard(lang), parse_mode="HTML")
    if action in {"generate_concepts", "regenerate_concepts", "refresh"}:
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        defaults = storyboard_pack_brief_defaults(state)
        state.setdefault("platform", defaults["platform"])
        state.setdefault("preferred_aspect_ratio", defaults["ratio"])
        state.setdefault("duration", defaults["duration"])
        state.setdefault("selected_style", defaults["style"])
        state.setdefault("goal", defaults["goal"])
        if action in {"regenerate_concepts", "refresh"}:
            state["suggest_offset"] = safe_int(state.get("suggest_offset"), 0) + 3
        else:
            state.setdefault("suggest_offset", 0)
        restore_developing_video_pending(uid, "storypack", state, "concepts")
        plan = save_developing_video_plan(uid, "storypack", state)
        return await safe_edit_or_send(query, storyboard_pack_concepts_text(plan, lang), reply_markup=storyboard_pack_concepts_keyboard(lang), parse_mode="HTML")
    if action == "back_concepts":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        restore_developing_video_pending(uid, "storypack", state, "concepts")
        return await safe_edit_or_send(query, storyboard_pack_concepts_text(state, lang), reply_markup=storyboard_pack_concepts_keyboard(lang), parse_mode="HTML")
    if action == "concept":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        state["selected_suggestion_index"] = max(1, min(3, safe_int(parts[2] if len(parts) > 2 else 1, 1)))
        plan = save_developing_video_plan(uid, "storypack", state)
        clear_developing_video_pending(uid)
        return await safe_edit_or_send_long_html(query, storyboard_pack_result_text(plan, lang), reply_markup=storyboard_pack_result_keyboard(lang))
    if action in {"back_detail", "detail"}:
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        return await safe_edit_or_send_long_html(query, storyboard_pack_result_text(state, lang), reply_markup=storyboard_pack_result_keyboard(lang))
    if action == "edit_requirement":
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        restore_developing_video_pending(uid, "storypack", state, "edit_requirement")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy gửi yêu cầu chỉnh storyboard, ví dụ: ít chữ hơn, thêm cảnh CTA, sang trọng hơn.\n\nBot chưa gọi API và chưa trừ Xu.",
            reply_markup=video_v6_keyboard([], lang, back=("⬅️ Quay lại chọn concept", "storypack|back_concepts")),
            parse_mode="HTML",
        )
    if action in {"image_prompts", "copy_image_prompts"}:
        state = _state_for_storypack()
        prefix = "📋 Copy các prompt trong khối <code>Prompt</code> bên dưới.\n\n" if action == "copy_image_prompts" else ""
        return await safe_edit_or_send_long_html(query, prefix + storyboard_pack_scene_prompts_text(state, "image", lang), reply_markup=storyboard_pack_scene_prompts_keyboard("image", lang))
    if action in {"video_prompts", "copy_video_prompts"}:
        state = _state_for_storypack()
        prefix = "📋 Copy các prompt trong khối <code>Prompt</code> bên dưới.\n\n" if action == "copy_video_prompts" else ""
        return await safe_edit_or_send_long_html(query, prefix + storyboard_pack_scene_prompts_text(state, "video", lang), reply_markup=storyboard_pack_scene_prompts_keyboard("video", lang))
    if action in {"regenerate_image_prompts", "regenerate_video_prompts"}:
        state = _state_for_storypack()
        state["prompt_variant_offset"] = safe_int(state.get("prompt_variant_offset"), 0) + 1
        plan = save_developing_video_plan(uid, "storypack", state)
        prompt_type = "video" if action == "regenerate_video_prompts" else "image"
        return await safe_edit_or_send_long_html(query, storyboard_pack_scene_prompts_text(plan, prompt_type, lang), reply_markup=storyboard_pack_scene_prompts_keyboard(prompt_type, lang))
    if action in {"meta_ai_prompt", "copy_meta_ai_prompt"}:
        state = _state_for_storypack()
        return await safe_edit_or_send(query, storyboard_pack_meta_ai_text(state, lang), reply_markup=storyboard_pack_meta_ai_keyboard(lang), parse_mode="HTML")
    if action == "regenerate_meta_ai_prompts":
        state = _state_for_storypack()
        state["meta_prompt_offset"] = safe_int(state.get("meta_prompt_offset"), 0) + 3
        plan = save_developing_video_plan(uid, "storypack", state)
        return await safe_edit_or_send(query, storyboard_pack_meta_ai_text(plan, lang), reply_markup=storyboard_pack_meta_ai_keyboard(lang), parse_mode="HTML")
    if action.startswith("copy_meta_"):
        state = _state_for_storypack()
        index = max(1, min(3, safe_int(action.rsplit("_", 1)[-1], 1)))
        variants = storyboard_pack_meta_ai_variants(state, lang)
        prompt = variants[index - 1] if len(variants) >= index else (variants[0] if variants else "")
        return await safe_edit_or_send(
            query,
            f"📋 <b>Prompt Meta AI {index}</b>\n\n<code>{html.escape(prompt)}</code>\n\nBot chưa gọi Meta API và chưa trừ Xu.",
            reply_markup=storyboard_pack_meta_ai_keyboard(lang),
            parse_mode="HTML",
        )
    if action == "copy_plan":
        state = _state_for_storypack()
        return await safe_edit_or_send_long_html(
            query,
            "📋 <b>Kế hoạch để copy</b>\n\n" + storyboard_pack_result_text(state, lang),
            reply_markup=storyboard_pack_result_keyboard(lang),
        )
    if action in {"lock", "save"}:
        state = _state_for_storypack()
        if not state:
            return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")
        pack_id = save_storyboard_prompt_pack(uid, state, "locked" if action == "lock" else "draft")
        prefix = "✅ Đã chốt shot pack." if action == "lock" else "💾 Đã lưu kế hoạch."
        if normalize_user_language(lang) != "vi":
            prefix = "✅ Shot pack locked." if action == "lock" else "💾 Plan saved."
        suffix = f"\nPack ID: <code>{pack_id}</code>\n\n" if pack_id else "\n\n"
        return await safe_edit_or_send_long_html(query, prefix + suffix + storyboard_pack_result_text(state, lang), reply_markup=storyboard_pack_result_keyboard(lang))
    if action in {"image_keyframes", "preview", "create_or_upload_images", "upload_images_guard"}:
        text = storyboard_pack_guard_text(action, lang)
        if action in {"create_or_upload_images", "upload_images_guard"}:
            return await safe_edit_or_send(query, text, reply_markup=storyboard_pack_image_guard_keyboard(lang), parse_mode="HTML")
        return await safe_edit_or_send(query, text, reply_markup=storyboard_pack_result_keyboard(lang), parse_mode="HTML")
    if action in {"ai_video", "create_video_ai"}:
        text = storyboard_pack_guard_text("create_video_ai", lang)
        return await safe_edit_or_send(query, text, reply_markup=storyboard_pack_video_guard_keyboard(lang), parse_mode="HTML")
    return await safe_edit_or_send(query, storyboard_pack_start_text(lang), reply_markup=storyboard_pack_start_keyboard(lang), parse_mode="HTML")

async def handle_video_idea_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    value = parts[2] if len(parts) > 2 else ""
    if action == "start":
        clear_developing_video_pending(uid)
        return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
    if action == "kind":
        kind = value if value in {"ad", "cinema", "custom"} else "custom"
        if kind == "ad":
            set_developing_video_pending(uid, "videoidea", "product_type", idea_kind=kind)
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        if kind == "cinema":
            set_developing_video_pending(uid, "videoidea", "cinema_suggestions", idea_kind=kind, suggest_offset=0)
            current = get_developing_video_pending(uid) or {}
            return await safe_edit_or_send(query, video_idea_cinema_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_cinema_suggestions_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "topic", idea_kind=kind)
        return await safe_edit_or_send(
            query,
            video_idea_topic_text(kind, lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("🔙 Quay lại Ý tưởng video" if normalize_user_language(lang) == "vi" else "🔙 Back to video ideas", "videoidea|start"),
            ),
        )
    pending = get_developing_video_pending(uid)
    plan = get_latest_developing_video_plan(uid, "videoidea")
    state = pending or plan or {}
    if action == "cinema_refresh":
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        set_developing_video_pending(uid, "videoidea", "cinema_suggestions", idea_kind="cinema", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_cinema_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_cinema_suggestions_keyboard(lang))
    if action == "cinema_custom":
        set_developing_video_pending(uid, "videoidea", "cinema_custom", idea_kind="cinema")
        return await safe_edit_or_send(
            query,
            video_idea_topic_text("cinema", lang),
            reply_markup=video_v6_keyboard(
                [],
                lang,
                back=("⬅️ Quay lại 3 gợi ý" if normalize_user_language(lang) == "vi" else "⬅️ Back to ideas", "videoidea|kind|cinema"),
            ),
        )
    if action == "cinema_choice":
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        suggestions = video_idea_cinema_suggestions(_safe_int(state.get("suggest_offset"), 0), lang)
        topic = suggestions[idx - 1] if idx <= len(suggestions) else (suggestions[0] if suggestions else "")
        base = dict(state or {})
        base.update({"idea_kind": "cinema", "selected_topic": topic, "product": topic, "context": "điện ảnh/kể chuyện" if normalize_user_language(lang) == "vi" else "cinematic/story", "prompt_variant_offset": 0})
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", base)
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "product_type":
        if value == "custom":
            set_developing_video_pending(uid, "videoidea", "product_type_custom", idea_kind="ad")
            return await safe_edit_or_send(
                query,
                "✍️ Hãy nhập loại sản phẩm/dịch vụ." if normalize_user_language(lang) == "vi" else "✍️ Enter the product/service category.",
                reply_markup=video_idea_product_description_keyboard(lang),
            )
        set_developing_video_pending(uid, "videoidea", "product_suggestions", idea_kind="ad", product_type=value, suggest_offset=0)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_product_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
    if action == "product_refresh":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        restore_developing_video_pending(uid, "videoidea", state, "product_suggestions")
        set_developing_video_pending(uid, "videoidea", "product_suggestions", suggest_offset=offset)
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(query, video_idea_product_suggestions_text(current, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
    if action == "product_custom":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", state, "topic")
        return await safe_edit_or_send(query, video_idea_product_description_text(state.get("product_type"), lang), parse_mode="HTML", reply_markup=video_idea_product_description_keyboard(lang))
    if action == "product_choice":
        if not state.get("product_type"):
            return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        options = video_idea_product_suggestions(state.get("product_type"), _safe_int(state.get("suggest_offset"), 0), lang)
        product = options[idx - 1] if idx <= len(options) else (options[0] if options else "")
        set_developing_video_pending(uid, "videoidea", "goal", idea_kind="ad", product=product, selected_topic=product)
        return await safe_edit_or_send(query, video_idea_goal_text(lang), parse_mode="HTML", reply_markup=video_idea_goal_keyboard(lang))
    if action == "back_product_type":
        restore_developing_video_pending(uid, "videoidea", state, "product_type")
        return await safe_edit_or_send(query, video_idea_product_type_text(lang), parse_mode="HTML", reply_markup=video_idea_product_type_keyboard(lang))
    if action == "back_description":
        if state.get("product_type"):
            restore_developing_video_pending(uid, "videoidea", state, "product_suggestions")
            return await safe_edit_or_send(query, video_idea_product_suggestions_text(state, lang), parse_mode="HTML", reply_markup=video_idea_product_suggestions_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", state, "topic")
        return await safe_edit_or_send(query, video_idea_product_description_text(state.get("product_type"), lang), parse_mode="HTML", reply_markup=video_idea_product_description_keyboard(lang))
    if action == "back_goal":
        restore_developing_video_pending(uid, "videoidea", state, "goal")
        return await safe_edit_or_send(query, video_idea_goal_text(lang), parse_mode="HTML", reply_markup=video_idea_goal_keyboard(lang))
    if action == "back_context":
        restore_developing_video_pending(uid, "videoidea", state, "context")
        return await safe_edit_or_send(query, video_idea_context_text(state, lang), parse_mode="HTML", reply_markup=video_idea_context_keyboard(lang))
    if action == "back_choices":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "idea_refresh":
        base = dict(plan or state or {})
        if not base.get("selected_topic") and not base.get("product"):
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        base["prompt_variant_offset"] = str(_safe_int(base.get("prompt_variant_offset"), 0) + 3)
        refreshed = save_developing_video_plan(uid, "videoidea", base)
        return await safe_edit_or_send(query, video_idea_choices_text(refreshed, lang), parse_mode="HTML", reply_markup=video_idea_choice_keyboard(lang, refreshed.get("idea_kind")))
    if action == "goal_custom":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "goal_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Nhập mục tiêu quảng cáo của bạn." if normalize_user_language(lang) == "vi" else "✍️ Enter your advertising goal.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại" if normalize_user_language(lang) == "vi" else "🔙 Back", callback_data="videoidea|back_goal"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "goal":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        goal_labels = {
            "sales": "bán hàng trực tiếp",
            "brand": "nhận diện thương hiệu",
            "viral": "viral TikTok/Reels",
        }
        set_developing_video_pending(uid, "videoidea", "context", goal=goal_labels.get(value, value))
        current = get_developing_video_pending(uid) or {}
        return await safe_edit_or_send(
            query,
            video_idea_context_text(current, lang),
            parse_mode="HTML",
            reply_markup=video_idea_context_keyboard(lang),
        )
    if action == "context_custom":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        set_developing_video_pending(uid, "videoidea", "context_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Nhập ngữ cảnh/bối cảnh quảng cáo." if normalize_user_language(lang) == "vi" else "✍️ Enter the advertising context.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại" if normalize_user_language(lang) == "vi" else "🔙 Back", callback_data="videoidea|back_context"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "context":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        options = video_idea_context_options(pending.get("product_type"), lang)
        try:
            idx = max(1, min(3, int(value or "1")))
        except Exception:
            idx = 1
        state = dict(pending)
        state["context"] = options[idx - 1]
        clear_developing_video_pending(uid)
        plan = save_developing_video_plan(uid, "videoidea", state)
        return await safe_edit_or_send(query, video_idea_choices_text(plan, lang), reply_markup=video_idea_choice_keyboard(lang, plan.get("idea_kind")))
    if action == "genre":
        if not pending:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        genre_labels = {"scifi": "khoa học viễn tưởng/công nghệ", "fantasy": "fantasy/điện ảnh", "drama": "drama/cảm xúc"}
        set_developing_video_pending(uid, "videoidea", "context", goal=genre_labels.get(value, value))
        return await safe_edit_or_send(
            query,
            "🌍 Chọn bối cảnh kể chuyện." if normalize_user_language(lang) == "vi" else "🌍 Choose the story context.",
            reply_markup=video_idea_context_keyboard(lang),
        )
    if action == "choose":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        try:
            choice = max(1, min(3, int(value or "1")))
        except Exception:
            choice = 1
        plan["idea_choice"] = str(choice)
        plan = save_developing_video_plan(uid, "videoidea", plan)
        return await safe_edit_or_send_long_html(query, video_idea_result_text(plan, choice, lang), reply_markup=video_idea_result_keyboard(lang))
    if action == "choice_custom":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        restore_developing_video_pending(uid, "videoidea", plan, "choice_custom")
        return await safe_edit_or_send(
            query,
            "✍️ Hãy nhập ý tưởng quảng cáo riêng của bạn." if normalize_user_language(lang) == "vi" else "✍️ Enter your custom advertising idea.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔙 Quay lại 3 ý tưởng" if normalize_user_language(lang) == "vi" else "🔙 Back to ideas", callback_data="videoidea|back_choices"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")]]),
        )
    if action == "finalization":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        package = developing_video_public_package(plan, "videoidea", lang)
        return await open_video_finalization(query, uid, "videoidea", plan, lang, "videoidea|back_choices", package)
    if action == "frame_video":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        photos = developing_video_frame_photos(plan)
        if len(photos) >= 2:
            return await open_existing_images_in_frame_video(query, uid, photos, "videoidea_plan", lang=lang)
        text = (
            "⚠️ Ý tưởng này chưa có bộ ảnh từng cảnh. Hãy tạo/lưu ít nhất 2 ảnh trước khi ghép video. Bot chưa render và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "⚠️ This idea has no scene image set yet. Create/save at least two images before assembling video. No render and no Xu charged."
        )
        return await safe_edit_or_send(query, text, reply_markup=video_idea_result_keyboard(lang))
    if action == "render_ai":
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        active = shopaikey_active_job_for_user(uid, "video")
        if active:
            return await safe_edit_or_send(query, public_video_active_job_text(lang), reply_markup=public_video_active_job_keyboard(active, lang))
        return await open_video_finalization(
            query,
            uid,
            "videoidea",
            plan,
            lang,
            "videoidea|back_choices",
            developing_video_public_package(plan, "videoidea", lang),
        )
    if action in {"storyboard", "image_prompts", "video_prompts", "music"}:
        if not plan:
            return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))
        return await safe_edit_or_send_long_html(query, video_idea_followup_text(action, plan, lang), reply_markup=video_idea_result_keyboard(lang))
    if action == "save":
        return await safe_edit_or_send(
            query,
            "💾 TOAN AAS đã lưu ý tưởng trong phiên hiện tại. Bot chưa gọi API và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "💾 Idea saved in this session. No API call and no Xu deducted.",
            reply_markup=video_idea_result_keyboard(lang),
        )
    return await safe_edit_or_send(query, video_idea_menu_text(lang), reply_markup=video_idea_menu_keyboard(lang))

