def localized_menu_content(action: str, is_admin: bool, lang: str, user_id=None) -> tuple[str, InlineKeyboardMarkup]:
    lang = normalize_user_language(lang) or "vi"
    if action in {"main", "back"}:
        return localized_start_menu_text(user_id or "__customer__", lang), localized_main_menu_keyboard(is_admin, lang)
    if action == "main_video":
        if user_id is not None:
            go_video_screen(user_id, "video_main", "main_video")
        return menu_text_main_video_i18n(lang), main_video_keyboard(lang)
    if action == "main_ai":
        return menu_text_main_ai_i18n(lang), main_ai_keyboard(lang)
    if action == "main_memory":
        return menu_text_main_memory_i18n(lang), main_memory_keyboard(lang, user_id)
    if action == "memory_storage_status":
        return memory_status_text(user_id or "__customer__"), memory_storage_nav_keyboard(lang)
    if action == "memory_storage_addon":
        return memory_storage_addon_text(), memory_storage_addon_keyboard(lang)
    if action == "memory_storage_cleanup":
        return memory_storage_cleanup_text(), memory_storage_nav_keyboard(lang)
    if action == "main_docs":
        return menu_text_main_docs_i18n(lang), main_docs_keyboard(lang)
    if action == "main_image":
        return menu_text_main_image_i18n(lang), main_image_keyboard(lang)
    if action == "main_music":
        if user_id is not None:
            set_music_nav_origin(user_id, "menu|main")
            enter_product_context(user_id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|main", product_area="voice_music")
        return menu_text_main_music_i18n(lang), music_tools_keyboard(lang)
    if action == "main_music_video":
        if user_id is not None:
            set_music_nav_origin(user_id, "menu|main_video")
            go_video_screen(user_id, "video_music_hub", "main_video")
            enter_product_context(user_id, PRODUCT_CONTEXT_VIDEO_ADDON, origin_screen="menu|main_video", product_area="voice_music")
        return menu_text_main_music_i18n(lang), music_tools_keyboard(lang, back_callback="menu|main_video")
    if action == "main_audio":
        return menu_text_main_audio_i18n(lang), main_audio_keyboard(lang)
    if action == "translate":
        if user_id is not None:
            enter_product_context(user_id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|main", product_area="translation")
        return translation_menu_text(lang), translation_menu_keyboard(lang)
    if action == "translation_video_factory":
        if user_id is not None:
            set_video_dubbing_pending(user_id, "menu", origin="translation", translation_context="media_center")
        return video_dubbing_menu_text(lang, "translation"), video_dubbing_menu_keyboard(lang, "translation")
    if action == "translation_media_file":
        if user_id is not None:
            clear_video_dubbing_pending(user_id)
            set_translation_menu_pending(user_id, "media_file", translation_context="translate_file")
        text = (
            "📄 <b>Dịch file</b>\n\n"
            "Anh/chị gửi file cần dịch. Luồng này chỉ dùng cho file, không dùng cho video hoặc audio.\n\n"
            "TOAN AAS chưa xử lý và chưa trừ Xu ở bước này."
            if normalize_user_language(lang) == "vi" else
            "📄 <b>Translate file</b>\n\nSend the file to translate. This flow is for files only, not video or audio.\n\nTOAN AAS has not processed or charged Xu yet."
        )
        return text, translation_input_keyboard(lang, parent="media")
    if action == "translation_media_audio":
        if user_id is not None:
            clear_video_dubbing_pending(user_id)
            set_translation_menu_pending(user_id, "media_audio", translation_context="translate_audio")
        return translation_voice_menu_text(lang), translation_voice_menu_keyboard(lang, parent="media")
    if action == "translation_subtitle_file":
        state = {
            "mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "process_type": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "video_processing_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "requested_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "active_flow": VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE,
            "flow_type": VIDEO_DUBBING_FLOW_HAS_SUBTITLE,
            "origin": "translation",
            "product_context": PRODUCT_CONTEXT_SHOWROOM,
        }
        if user_id is not None:
            state = set_video_dubbing_pending(user_id, "source", **state)
        return video_dubbing_source_text(state, lang), video_dubbing_source_keyboard(lang, state)
    if action == "translation_language_hub":
        return translation_language_hub_text(lang), translation_language_hub_keyboard(lang, user_id)
    if action == "translation_auto_target":
        return menu_text_translate_i18n(False, lang), translate_language_keyboard(False, lang)
    if action == "translate_more":
        return menu_text_translate_i18n(True, lang), translate_language_keyboard(True, lang)
    if action == "main_quick":
        return menu_text_main_quick_i18n(lang), main_quick_keyboard(lang)
    if action == "main_topup":
        return menu_text_main_topup_i18n(lang), main_topup_keyboard(lang, user_id)
    if action == "main_profile":
        return menu_text_main_profile_i18n(user_id or "__customer__", lang), main_profile_keyboard(lang)
    if action == "profile_packages":
        return user_package_summary_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "profile_ref_link":
        return referral_account_link_text(user_id or "__customer__", BOT_USERNAME, lang), profile_child_keyboard(lang)
    if action == "profile_ref_policy":
        return referral_account_policy_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "profile_ref_stats":
        return referral_account_stats_text(user_id or "__customer__"), profile_child_keyboard(lang)
    if action == "main_guide":
        return menu_text_main_guide_i18n(lang), main_guide_keyboard(lang)
    if action == "guide":
        return guide_index_text_i18n(lang), guide_keyboard("", lang)
    if action.startswith("guide_"):
        section = action.replace("guide_", "", 1)
        return guide_section_text_i18n(section, lang), guide_keyboard(section, lang)
    if action in ADMIN_MENU_PAGE_HANDLERS:
        return ADMIN_MENU_PAGE_HANDLERS[action]()
    if action == "doc_tools":
        return doc_tools_menu_text_i18n(lang), doc_tools_keyboard(lang)
    if action.startswith("hint_"):
        section, hint = menu_hint_text_i18n(action, lang)
        return hint, menu_nav_keyboard_i18n(section, is_admin, lang)
    return menu_content(action, is_admin)

def menu_content(action: str, is_admin: bool) -> tuple[str, InlineKeyboardMarkup]:
    if action in {"main", "back"}:
        return menu_text_main(is_admin), main_menu_keyboard(is_admin)
    if action == "main_video":
        return menu_text_main_video(), main_video_keyboard()
    if action == "main_ai":
        return menu_text_main_ai(), main_ai_keyboard()
    if action == "main_memory":
        return menu_text_main_memory(), main_memory_keyboard()
    if action == "memory_storage_status":
        return memory_status_text("__customer__"), memory_storage_nav_keyboard()
    if action == "memory_storage_addon":
        return memory_storage_addon_text(), memory_storage_addon_keyboard()
    if action == "memory_storage_cleanup":
        return memory_storage_cleanup_text(), memory_storage_nav_keyboard()
    if action == "main_docs":
        return menu_text_main_docs(), main_docs_keyboard()
    if action == "main_image":
        return menu_text_main_image(), main_image_keyboard()
    if action == "main_music":
        return menu_text_main_music(), music_tools_keyboard()
    if action == "main_music_video":
        return menu_text_main_music(), music_tools_keyboard(back_callback="menu|main_video")
    if action == "main_audio":
        return menu_text_main_audio(), main_audio_keyboard()
    if action == "translate":
        return translation_menu_text("vi"), translation_menu_keyboard("vi")
    if action == "translation_video_factory":
        return video_dubbing_menu_text("vi", "translation"), video_dubbing_menu_keyboard("vi", "translation")
    if action == "translation_media_file":
        return (
            "📄 <b>Dịch file</b>\n\n"
            "Anh/chị gửi file cần dịch. Luồng này chỉ dùng cho file, không dùng cho video hoặc audio.\n\n"
            "TOAN AAS chưa xử lý và chưa trừ Xu ở bước này.",
            translation_input_keyboard("vi", parent="media"),
        )
    if action == "translation_media_audio":
        return translation_voice_menu_text("vi"), translation_voice_menu_keyboard("vi", parent="media")
    if action == "translation_subtitle_file":
        state = {
            "mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "process_type": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "video_processing_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "requested_mode": VIDEO_SUBTITLE_MODE_TRANSLATE,
            "active_flow": VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE,
            "flow_type": VIDEO_DUBBING_FLOW_HAS_SUBTITLE,
            "origin": "translation",
            "product_context": PRODUCT_CONTEXT_SHOWROOM,
        }
        return video_dubbing_source_text(state, "vi"), video_dubbing_source_keyboard("vi", state)
    if action == "translation_language_hub":
        return translation_language_hub_text("vi"), translation_language_hub_keyboard("vi")
    if action == "translation_auto_target":
        return menu_text_translate(False), translate_language_keyboard(False)
    if action == "translate_more":
        return menu_text_translate(True), translate_language_keyboard(True)
    if action == "main_quick":
        return menu_text_main_quick(), main_quick_keyboard()
    if action == "main_topup":
        return menu_text_main_topup(), main_topup_keyboard()
    if action == "main_profile":
        return menu_text_main_profile("__customer__"), main_profile_keyboard()
    if action == "main_guide":
        return menu_text_main_guide(), main_guide_keyboard()
    if action == "ai_basic":
        return menu_text_ai_basic(), menu_nav_keyboard("ai_basic", is_admin)
    if action == "video_factory":
        return menu_text_video_factory(is_admin), menu_nav_keyboard("video_factory", is_admin)
    if action == "video_workflow":
        return menu_text_video_workflow(is_admin), menu_nav_keyboard("video_workflow", is_admin)
    if action == "video_factory_flow":
        return video_factory_flow_text(), menu_nav_keyboard("video_factory", is_admin)
    if action == "doc_tools":
        return doc_tools_menu_text(), doc_tools_keyboard()
    if action == "memory":
        return memory_menu_text(), menu_nav_keyboard("memory", is_admin)
    if action == "affiliate":
        return menu_text_affiliate(is_admin), menu_nav_keyboard("affiliate", is_admin)
    if action == "operator":
        return menu_text_operator(is_admin), menu_nav_keyboard("operator", is_admin)
    if action == "admin":
        return menu_text_admin(), menu_nav_keyboard("admin", is_admin)
    if action == "finance":
        return finance_menu_text(), finance_admin_keyboard()
    if action in ADMIN_MENU_PAGE_HANDLERS:
        return ADMIN_MENU_PAGE_HANDLERS[action]()
    if action == "system":
        return menu_text_system(), menu_nav_keyboard("system", is_admin)
    if action == "billing":
        return menu_text_billing(is_admin), menu_nav_keyboard("billing", is_admin)
    if action == "support":
        return menu_text_support(), menu_nav_keyboard("support", is_admin)
    if action == "legal":
        return legal_menu_text(), legal_menu_keyboard()
    if action == "guide":
        return guide_index_text(), guide_keyboard()
    if action.startswith("guide_"):
        section = action.replace("guide_", "", 1)
        return guide_section_text(section), guide_keyboard(section)
    if action.startswith("hint_"):
        section, hint = menu_hint_text(action)
        return hint, menu_nav_keyboard(section, is_admin)
    return menu_text_main(is_admin), main_menu_keyboard(is_admin)

def customer_start_surface_audit_data():
    public_text = build_start_message_text("__customer__")
    admin_text = build_start_message_text(ADMIN_ID or "__admin__")
    forbidden_public_markers = [
        "/tools", "/mmo", "/operator_menu", "/operator_contract", "/brain", "/mission_add",
        "/telegram_takeover", "/runtime", "A_TOOLSX", "A-TOOLS", "A_TOOLS", "join our channel",
        "must join our channel", "VIEW CHANNEL",
    ]
    public_lower = public_text.lower()
    leaked_markers = [marker for marker in forbidden_public_markers if marker.lower() in public_lower]
    return {
        "ok": not leaked_markers,
        "public_message_length": len(public_text),
        "admin_message_length": len(admin_text),
        "leaked_markers": leaked_markers,
        "public_has_payment": "Xu dịch vụ" in public_text or "Billing" in public_text,
        "admin_has_operator": "operator" in admin_text.lower() or "Quản trị" in admin_text,
        "rule": "Khách chỉ thấy menu dịch vụ/nạp tiền/hỗ trợ. Tools, MMO, operator và chẩn đoán webhook chỉ hiện trong menu Admin.",
    }

async def cmd_start(update: Update, context: ContextTypes.DEFAULT_TYPE):
    log_command_received("start", update)
    uid = update.effective_user.id
    user_existed_before = user_exists(uid)
    get_user(uid, update.effective_user.first_name)
    record_usage_event(
        uid,
        username=update.effective_user.username or update.effective_user.first_name or "",
        event_type="start",
        tool_name="core",
        command="/start",
        status="ok",
    )
    if context.args and context.args[0].startswith("ref_"):
        referrer = context.args[0].replace("ref_", "", 1)
        ref_result = register_referral(uid, referrer, user_existed_before=user_existed_before)
        if ref_result.get("registered"):
            await update.message.reply_text(
                "🎁 Đã ghi nhận mã giới thiệu.\n"
                "Người giới thiệu chỉ nhận Xu thưởng khi bạn nạp Xu lần đầu thành công."
            )
        elif ref_result.get("reason") == "self_ref":
            await update.message.reply_text("⚠️ Bạn không thể tự giới thiệu chính mình.")
    pending_notice = clear_pending_start_notice(uid)
    user_is_admin = is_admin_user(uid)
    if not has_user_language(uid):
        if pending_notice:
            await update.message.reply_text(pending_notice.strip())
        await update.message.reply_text(
            language_choice_text(),
            parse_mode="HTML",
            reply_markup=language_choice_keyboard(),
        )
        return
    lang = get_user_language(uid) or "vi"
    await update.message.reply_text(
        pending_notice + localized_start_menu_text(uid, lang) + mode_start_notice(uid),
        parse_mode="HTML",
        reply_markup=localized_main_menu_keyboard(user_is_admin, lang),
    )
    await maybe_auto_grant_birthday_gift(update, context)

async def cmd_menu(update: Update, context: ContextTypes.DEFAULT_TYPE):
    return await cmd_start(update, context)

