async def on_telegram_error(update: object, context: ContextTypes.DEFAULT_TYPE):
    error = context.error
    error_name = type(error).__name__ if error else "UnknownError"
    error_text = sanitize_log_text(str(error or ""))[:1200]
    message_text = ""
    if isinstance(update, Update) and update.effective_message:
        message_text = str(getattr(update.effective_message, "text", "") or "").strip()
    callback_data = ""
    if isinstance(update, Update) and update.callback_query:
        callback_data = str(update.callback_query.data or "").strip()
    completed_video_job = completed_video_job_for_callback_error(update)
    image_to_pdf_safe_error = (
        message_text.startswith("/image_to_pdf")
        or ('unsupported start tag "yêu"' in error_text.lower())
    )
    audio_timeout_safe_error = (
        is_audio_timeout_error(error)
        and (
            message_text.startswith(("/translate_voice", "/translate_audio", "/transcribe"))
            or callback_data.startswith("tr_")
        )
    )
    shopaikey_image_error_already_notified = False
    try:
        notified_at = float((context.chat_data or {}).get("shopaikey_public_image_error_notified_at") or 0)
        shopaikey_image_error_already_notified = callback_data.startswith("shopai|") and notified_at and (time.time() - notified_at) < 30
    except Exception:
        shopaikey_image_error_already_notified = False
    if error:
        logger.error(
            "Telegram handler error\n%s",
            sanitize_log_text("".join(traceback.format_exception(type(error), error, error.__traceback__)))[:4000],
        )
    else:
        logger.error("Telegram handler error | type=%s", error_name)

    if completed_video_job:
        record_video_post_output_error(error, completed_video_job, callback_data)
        logger.warning(
            "suppressed public error after completed video output | job_id=%s | task_id=%s",
            completed_video_job.get("id"),
            sanitize_log_text(str(completed_video_job.get("task_id") or ""))[:180],
        )
        return

    if shopaikey_image_error_already_notified:
        return

    try:
        if isinstance(update, Update) and update.effective_chat:
            text = (
                TRANSLATE_AUDIO_TIMEOUT_TEXT if audio_timeout_safe_error else
                "❌ Không tạo được PDF từ ảnh này. Bot chưa trừ Xu. Vui lòng thử lại sau."
                if image_to_pdf_safe_error else
                "❌ Có lỗi khi xử lý lệnh. Bot chưa trừ Xu. Vui lòng thử lại sau."
            )
            if (
                not image_to_pdf_safe_error
                and not audio_timeout_safe_error
                and update.effective_user
                and is_admin_or_owner(update.effective_user.id)
                and ADMIN_DEBUG_PUBLIC_ERRORS
            ):
                text += f"\n\n<code>{html.escape(error_name)}: {html.escape(error_text[:800])}</code>"
            await context.bot.send_message(
                chat_id=update.effective_chat.id,
                text=text,
                parse_mode=None if (image_to_pdf_safe_error or audio_timeout_safe_error) else "HTML",
            )
    except Exception:
        logger.exception("Failed to notify user about Telegram handler error")

    try:
        if ADMIN_ID and ADMIN_DEBUG_PUBLIC_ERRORS and not image_to_pdf_safe_error and not audio_timeout_safe_error:
            await context.bot.send_message(
                chat_id=int(ADMIN_ID),
                text=(
                    "🚨 <b>BOT COMMAND DEBUG ERROR</b>\n\n"
                    f"<code>{html.escape(error_name)}: {html.escape(error_text)}</code>"
                ),
                parse_mode="HTML",
            )
    except Exception:
        pass

async def safe_edit_query_message(query, text: str, reply_markup=None, parse_mode: str | None = "HTML"):
    try:
        return await query.edit_message_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    except Exception as e:
        if "message is not modified" in str(e).lower():
            return None
        if any(fragment in str(e).lower() for fragment in (
            "there is no text in the message to edit",
            "query is too old",
            "message to edit not found",
            "message can't be edited",
            "message is not editable",
        )):
            logger.warning("safe_edit_query_message fallback | %s", sanitize_log_text(str(e))[:240])
            message = getattr(query, "message", None)
            if message:
                try:
                    return await message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
                except Exception as send_error:
                    logger.warning("safe_edit_query_message fallback failed | %s", sanitize_log_text(str(send_error))[:240])
                    return None
        raise

def html_message_to_plain_text(text: str) -> str:
    plain = re.sub(r"<a\s+href=\"([^\"]+)\"[^>]*>(.*?)</a>", r"\2: \1", str(text or ""), flags=re.I | re.S)
    plain = re.sub(r"<br\s*/?>", "\n", plain, flags=re.I)
    plain = re.sub(r"</p\s*>", "\n", plain, flags=re.I)
    plain = re.sub(r"<[^>]+>", "", plain)
    return html.unescape(plain)

async def safe_reply_text(message, text: str, reply_markup=None, parse_mode: str | None = "HTML", disable_web_page_preview=None):
    if not message:
        return None
    kwargs = {"reply_markup": reply_markup}
    if parse_mode is not None:
        kwargs["parse_mode"] = parse_mode
    if disable_web_page_preview is not None:
        kwargs["disable_web_page_preview"] = disable_web_page_preview
    try:
        return await message.reply_text(str(text or ""), **kwargs)
    except Exception as e:
        logger.warning("safe_reply_text primary failed | %s", sanitize_log_text(str(e))[:240])
        if parse_mode:
            try:
                fallback_kwargs = {"reply_markup": reply_markup}
                if disable_web_page_preview is not None:
                    fallback_kwargs["disable_web_page_preview"] = disable_web_page_preview
                return await message.reply_text(html_message_to_plain_text(text), **fallback_kwargs)
            except Exception as fallback_error:
                logger.warning("safe_reply_text fallback failed | %s", sanitize_log_text(str(fallback_error))[:240])
        return None

def split_telegram_html_text(text: str, limit: int = 3600) -> list[str]:
    raw_text = str(text or "")
    if len(raw_text) <= limit:
        return [raw_text]
    chunks: list[str] = []
    current = ""
    for paragraph in raw_text.split("\n\n"):
        piece = paragraph if not current else "\n\n" + paragraph
        if len(current) + len(piece) <= limit:
            current += piece
            continue
        if current:
            chunks.append(current)
            current = ""
        if len(paragraph) <= limit:
            current = paragraph
            continue
        for start in range(0, len(paragraph), limit):
            chunks.append(paragraph[start:start + limit])
    if current:
        chunks.append(current)
    return chunks or [raw_text[:limit]]

async def safe_reply_long_html(message, text: str, reply_markup=None):
    chunks = split_telegram_html_text(text)
    sent = None
    for index, chunk in enumerate(chunks):
        sent = await safe_reply_text(
            message,
            chunk,
            parse_mode="HTML",
            reply_markup=reply_markup if index == len(chunks) - 1 else None,
        )
    return sent

async def safe_edit_or_send_long_html(query, text: str, reply_markup=None):
    chunks = split_telegram_html_text(text)
    if len(chunks) == 1:
        return await safe_edit_query_message(query, chunks[0], parse_mode="HTML", reply_markup=reply_markup)
    await safe_edit_query_message(query, chunks[0], parse_mode="HTML", reply_markup=None)
    message = getattr(query, "message", None)
    sent = None
    for index, chunk in enumerate(chunks[1:], start=1):
        sent = await safe_reply_text(
            message,
            chunk,
            parse_mode="HTML",
            reply_markup=reply_markup if index == len(chunks) - 1 else None,
        )
    return sent

def is_soft_telegram_edit_error(error: Exception) -> bool:
    text = str(error or "").lower()
    return any(fragment in text for fragment in (
        "there is no text in the message to edit",
        "message is not modified",
        "query is too old",
        "message to edit not found",
        "message can't be edited",
        "message is not editable",
    ))

async def safe_edit_or_send(query, text: str, reply_markup=None, parse_mode: str | None = "HTML"):
    """Edit callback message when possible; otherwise send a fresh message."""
    if not query:
        return None
    message = getattr(query, "message", None)
    if not hasattr(query, "edit_message_text") and hasattr(query, "reply_text"):
        return await query.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    try:
        return await query.edit_message_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
    except Exception as e:
        if "message is not modified" in str(e).lower():
            return None
        if not is_soft_telegram_edit_error(e):
            raise
        logger.warning("safe_edit_or_send fallback | %s", sanitize_log_text(str(e))[:240])
        try:
            if message:
                return await message.reply_text(text, parse_mode=parse_mode, reply_markup=reply_markup)
        except Exception as send_error:
            logger.warning("safe_edit_or_send reply fallback failed | %s", sanitize_log_text(str(send_error))[:240])
        try:
            bot = getattr(query, "bot", None)
            chat_id = getattr(message, "chat_id", None) if message else None
            if bot and chat_id:
                return await bot.send_message(chat_id=chat_id, text=text, parse_mode=parse_mode, reply_markup=reply_markup)
        except Exception as send_error:
            logger.warning("safe_edit_or_send bot fallback failed | %s", sanitize_log_text(str(send_error))[:240])
        return None

def _parse_support_ai_classification(raw_text: str) -> dict:
    value = str(raw_text or "").strip()
    if value.startswith("```"):
        value = re.sub(r"^```(?:json)?\s*|\s*```$", "", value, flags=re.IGNORECASE | re.DOTALL).strip()
    try:
        parsed = json.loads(value)
    except Exception:
        return {}
    if not isinstance(parsed, dict):
        return {}
    allowed_categories = {
        "onboarding", "pricing", "payment", "technical_error", "refund_complaint",
        "feature_question", "admin_escalation", "out_of_scope", "closing",
    }
    category = str(parsed.get("category") or "")
    priority = str(parsed.get("priority") or "normal")
    if category not in allowed_categories or priority not in {"low", "normal", "high", "urgent"}:
        return {}
    return {
        "matched": bool(parsed.get("matched")),
        "category": category,
        "needs_admin": bool(parsed.get("needs_admin")),
        "priority": priority,
        "reason": sanitize_log_text(str(parsed.get("reason") or "optional_ai_classifier"))[:160],
    }

async def classify_support_message(user_message: str, user_id=None) -> dict:
    rule_result = classify_support_escalation(user_message)
    if rule_result.get("matched") or not SUPPORT_AI_CLASSIFIER_ENABLED:
        return rule_result
    if not (gemini_client or openai_client or shopaikey_public_chat_fallback_enabled()):
        return rule_result
    instruction = (
        f"{AAS_SUPPORT_SYSTEM_PERSONA}\n\n"
        "Chỉ phân loại ý định CSKH. Trả JSON với các khóa: matched, category, "
        "needs_admin, priority, reason. category chỉ thuộc onboarding, pricing, "
        "payment, technical_error, refund_complaint, feature_question, "
        "admin_escalation, out_of_scope, closing. Không trả lời nội dung khách."
    )
    try:
        result = await call_ai_chat_with_fallback(instruction, str(user_message or "")[:1200], user_id, max_tokens=180)
        if not result.get("ok"):
            return rule_result
        parsed = _parse_support_ai_classification(result.get("text") or "")
        return classify_support_escalation(user_message, ai_classification=parsed)
    except Exception:
        return rule_result

async def notify_admin_new_support_ticket(
    context: ContextTypes.DEFAULT_TYPE,
    ticket: dict,
    classification: dict | None = None,
    suggested_reply: str = "",
    *,
    is_new: bool = True,
    customer_message: str = "",
) -> None:
    classification = classification or classify_support_escalation(ticket.get("message") or "")
    reason = str(classification.get("reason") or "ticket_created")
    priority = str(classification.get("priority") or ticket.get("priority") or "normal")
    category = str(classification.get("category") or ticket.get("category") or "other")
    reply_preview = format_support_reply(
        suggested_reply or support_reply_for_classification(classification),
        classification,
    )
    text = (
        f"{'🆕' if is_new else '🔔'} <b>{'Ticket mới' if is_new else 'Ticket có cập nhật'} TOAN AAS</b>\n\n"
        f"Mã: <code>{html.escape(ticket.get('ticket_code') or '')}</code>\n"
        f"User: <code>{html.escape(ticket.get('user_id') or '')}</code>\n"
        f"Username: {html.escape(ticket.get('username') or '-')}\n"
        f"Nhóm: {html.escape(category)} / {html.escape(support_category_label(ticket.get('category')))}\n"
        f"Ưu tiên: <b>{html.escape(support_priority_label(priority))}</b>\n"
        f"Lý do: {html.escape(reason)}\n\n"
        f"Tin nhắn: {html.escape((customer_message or ticket.get('message') or '')[:900])}\n\n"
        f"Gợi ý phản hồi:\n{html.escape(reply_preview[:900])}"
    )
    keyboard = InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🎫 Xem ticket", callback_data=f"ticket|av|{ticket['id']}|new"),
            InlineKeyboardButton("💬 Soạn trả lời", callback_data=f"ticket|reply|{ticket['id']}"),
        ],
        [InlineKeyboardButton("✅ Đã nhận xử lý", callback_data=f"ticket|assign|{ticket['id']}")],
    ])
    for admin_id in owner_and_admin_ids():
        try:
            await context.bot.send_message(chat_id=admin_id, text=text, parse_mode="HTML", reply_markup=keyboard)
        except Exception as exc:
            logger.warning("support ticket admin notify failed | ticket_id=%s error=%s", ticket.get("id"), type(exc).__name__)

async def handle_support_persona_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not SUPPORT_PERSONA_AUTO_REPLY_ENABLED or not update.effective_user or not update.message or not update.message.text:
        return False
    text = update.message.text.strip()
    classification = await classify_support_message(text, update.effective_user.id)
    if not classification.get("matched"):
        return False
    safe_reply = support_reply_for_classification(classification)
    ticket = None
    is_new = False
    if classification.get("should_create_ticket"):
        ticket, is_new = create_or_append_support_ticket(
            update.effective_user,
            classification.get("ticket_category") or "other",
            text,
            classification,
        )
        safe_reply += (
            f"\n\n🎫 Mã ticket: <code>{html.escape(ticket.get('ticket_code') or '')}</code>\n"
            "Admin sẽ kiểm tra trực tiếp; bot chưa tự động cộng, trừ hoặc hoàn Xu."
        )
    if classification.get("allowed_auto_send"):
        await update.message.reply_text(
            safe_reply,
            parse_mode="HTML",
            reply_markup=(
                support_ticket_created_keyboard(ticket["id"])
                if ticket else InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")]])
            ),
        )
    if ticket and classification.get("should_alert_admin"):
        await notify_admin_new_support_ticket(
            context,
            ticket,
            classification,
            support_reply_for_classification(classification),
            is_new=is_new,
            customer_message=text,
        )
    return True

async def handle_support_ticket_attachment(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    state = get_support_ticket_pending(update.effective_user.id)
    if not state or state.get("step") != "awaiting_attachment":
        return False
    ticket_id = int(state.get("ticket_id") or 0)
    ticket = get_support_ticket(ticket_id, update.effective_user.id)
    if not ticket:
        clear_support_ticket_pending(update.effective_user.id)
        await update.message.reply_text("⚠️ Không tìm thấy ticket của bạn. Vui lòng mở lại mục Hỗ trợ.")
        return True
    file_id = ""
    attachment_type = ""
    attachment_name = ""
    if getattr(update.message, "photo", None):
        file_id = update.message.photo[-1].file_id
        attachment_type = "photo"
        attachment_name = "support_screenshot.jpg"
    elif getattr(update.message, "document", None):
        document = update.message.document
        file_id = document.file_id
        attachment_type = "document"
        attachment_name = str(document.file_name or "support_attachment")[:240]
    if not file_id:
        return False
    update_support_ticket(
        ticket_id,
        attachment_file_id=file_id,
        attachment_type=attachment_type,
        attachment_name=attachment_name,
    )
    clear_support_ticket_pending(update.effective_user.id)
    await update.message.reply_text(
        f"✅ Đã lưu file vào ticket <code>{html.escape(ticket['ticket_code'])}</code>.\n\nAdmin sẽ dùng file này để kiểm tra yêu cầu.",
        parse_mode="HTML",
        reply_markup=support_ticket_created_keyboard(ticket_id),
    )
    return True

def support_admin_search_payload(search: str) -> tuple[str, InlineKeyboardMarkup]:
    exact = get_support_ticket_by_code(search)
    tickets = [exact] if exact else list_support_tickets(search=search, limit=10)
    lines = ["🔍 <b>Kết quả tìm ticket</b>", ""]
    if not tickets:
        lines.append("Không tìm thấy ticket phù hợp.")
    else:
        for ticket in tickets:
            lines.append(f"• <code>{ticket['ticket_code']}</code> — {html.escape(support_category_label(ticket['category']))} — user <code>{html.escape(ticket['user_id'])}</code>")
    rows = []
    for index in range(0, len(tickets), 2):
        rows.append([InlineKeyboardButton(f"🎫 {ticket['ticket_code'][-6:]}", callback_data=f"ticket|av|{ticket['id']}|new") for ticket in tickets[index:index + 2]])
    rows.append([InlineKeyboardButton("⬅️ CSKH/Ticket", callback_data="ticket|admin"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")])
    return "\n".join(lines), InlineKeyboardMarkup(rows)

async def handle_support_pending_input(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message or not update.message.text:
        return False
    uid = update.effective_user.id
    state = get_support_ticket_pending(uid)
    if not state:
        return False
    step = state.get("step")
    text = update.message.text.strip()
    if step == "lead_input":
        category = state.get("category") if state.get("category") in {"premium_lead", "custom_bot_lead", "service_consulting"} else "premium_lead"
        selected_option = str(state.get("selected_option") or "").strip()
        lead_type = str(state.get("lead_type") or state.get("service_type") or "").strip()
        full_message = f"{selected_option}\n{text}".strip()
        priority = "high" if category in {"premium_lead", "custom_bot_lead"} else "normal"
        classification = {
            "matched": True,
            "needs_admin": category in {"premium_lead", "custom_bot_lead"},
            "priority": priority,
            "reason": category,
            "category": "admin_escalation",
            "ticket_category": category,
            "suggested_reply_id": "b2b_contract",
            "should_create_ticket": True,
            "should_alert_admin": category in {"premium_lead", "custom_bot_lead"},
            "allowed_auto_send": True,
            "classifier_source": "support_lead_flow",
        }
        ticket, is_new = create_or_append_support_ticket(
            update.effective_user,
            category,
            full_message,
            classification,
        )
        complete_support_pending(uid, ticket["id"])
        lead_name = {
            "premium_lead": "đăng ký Premium",
            "custom_bot_lead": "kết nối bot riêng",
            "service_consulting": "tư vấn gói dịch vụ",
        }.get(category, "tư vấn")
        if category == "custom_bot_lead" and lead_type == "shop_bot":
            auto_reply = (
                "Dạ TOAN AAS đã nhận nhu cầu làm bot bán hàng/shop online của bạn nhé. "
                "Admin sẽ xem quy mô shop, nền tảng đang bán và quy trình bạn muốn tự động hóa."
            )
        elif category == "service_consulting" and (lead_type == "video" or "video" in selected_option.lower()):
            auto_reply = (
                "Dạ mình nhận được nhu cầu tư vấn gói video rồi nhé. TOAN AAS sẽ xem theo "
                "số lượng video, tần suất dùng và ngân sách phù hợp."
            )
        else:
            auto_reply = f"Dạ TOAN AAS đã nhận nhu cầu {lead_name} của bạn nhé."
        await update.message.reply_text(
            f"✅ <b>{html.escape(auto_reply)}</b>\n\n"
            "Mình đã ghi nhận nội dung trong ticket để hỗ trợ tiếp.\n\n"
            f"Mã ticket: <code>{html.escape(ticket.get('ticket_code') or '')}</code>\n"
            f"Trạng thái: {html.escape(support_status_label(ticket.get('status')))}",
            parse_mode="HTML",
            reply_markup=support_ticket_created_keyboard(ticket["id"]),
        )
        if classification.get("should_alert_admin") and (
            is_new or str(classification.get("priority") or "") == "urgent"
        ):
            await notify_admin_new_support_ticket(
                context,
                ticket,
                classification,
                support_reply_for_classification(classification),
                is_new=is_new,
                customer_message=full_message,
            )
        return True
    if step == "awaiting_message":
        if len(text) < 5:
            await update.message.reply_text("Vui lòng mô tả rõ hơn để admin có đủ thông tin kiểm tra.", reply_markup=support_ticket_input_keyboard())
            return True
        classification = await classify_support_message(text, uid)
        selected_category = state.get("category") or "other"
        if selected_category == "general_support" and classification.get("needs_admin"):
            selected_category = classification.get("ticket_category") or "general_support"
        ticket, is_new = create_or_append_support_ticket(
            update.effective_user,
            selected_category,
            text,
            classification,
        )
        complete_support_pending(uid, ticket["id"])
        if selected_category == "custom_bot_lead":
            intro = (
                "Dạ TOAN AAS đã nhận nhu cầu làm bot riêng của bạn nhé. Bạn có thể gửi thêm "
                "quy mô sử dụng, nền tảng hiện tại và quy trình muốn tự động hóa để admin tư vấn đúng hơn."
            )
        elif selected_category == "premium_lead":
            intro = "Dạ TOAN AAS đã nhận nhu cầu đăng ký Premium. Admin sẽ xem tần suất sử dụng và nhóm công cụ phù hợp để tư vấn."
        elif selected_category == "service_consulting":
            intro = (
                "Dạ mình nhận được nhu cầu tư vấn gói dịch vụ rồi nhé. TOAN AAS sẽ xem theo "
                "tần suất sử dụng, loại đầu ra và ngân sách phù hợp."
            )
        else:
            intro = support_auto_reply_for_ticket_category(
                classification,
                selected_category if selected_category != "other" else "general_support",
            )
        ticket_text = (
            support_ticket_created_text(ticket)
            if is_new
            else (
                f"✅ <b>Đã bổ sung thông tin vào ticket {html.escape(ticket.get('ticket_code') or '')}.</b>\n\n"
                "TOAN AAS giữ cùng ticket để admin theo dõi liền mạch."
            )
        )
        await update.message.reply_text(
            f"{html.escape(intro)}\n\n{ticket_text}",
            parse_mode="HTML",
            reply_markup=support_ticket_created_keyboard(ticket["id"]),
        )
        if is_new or str(classification.get("priority") or "") == "urgent":
            await notify_admin_new_support_ticket(
                context,
                ticket,
                classification,
                intro,
                is_new=is_new,
                customer_message=text,
            )
        return True
    if step == "awaiting_ticket_reply":
        ticket_id = int(state.get("ticket_id") or 0)
        ticket = get_support_ticket(ticket_id, uid)
        if not ticket:
            clear_support_ticket_pending(uid)
            await update.message.reply_text("⚠️ Không tìm thấy ticket của bạn. Vui lòng mở lại mục Ticket của tôi.")
            return True
        if len(text) < 2:
            await update.message.reply_text("Vui lòng nhập nội dung cần bổ sung.")
            return True
        add_support_ticket_message(ticket_id, "user", uid, text[:4000], "recorded")
        classification = await classify_support_message(text, uid)
        desired_priority = str(classification.get("priority") or ticket.get("priority") or "normal")
        priority_rank = {"low": 0, "normal": 1, "high": 2, "urgent": 3}
        update_fields = {"status": "reviewing"}
        if priority_rank.get(desired_priority, 1) > priority_rank.get(str(ticket.get("priority")), 1):
            update_fields["priority"] = desired_priority
        ticket = update_support_ticket(ticket_id, **update_fields) or ticket
        complete_support_pending(uid, ticket_id)
        await update.message.reply_text(
            f"✅ Đã bổ sung nội dung vào ticket <code>{html.escape(ticket.get('ticket_code') or '')}</code>.\n\n"
            "TOAN AAS đã ghi nhận cập nhật và sẽ báo admin nếu cần xử lý ưu tiên.",
            parse_mode="HTML",
            reply_markup=support_ticket_created_keyboard(ticket_id),
        )
        if classification.get("needs_admin") or str(ticket.get("priority")) in {"high", "urgent"}:
            await notify_admin_new_support_ticket(
                context,
                ticket,
                classification,
                support_reply_for_classification(classification),
                is_new=False,
                customer_message=text,
            )
        return True
    if step == "awaiting_attachment":
        await update.message.reply_text("📎 Vui lòng gửi một ảnh hoặc file tài liệu. Nếu không cần đính kèm, bạn có thể mở ticket khác hoặc về Menu chính.")
        return True
    if step == "admin_reply_input" and is_admin_user(uid):
        ticket_id = int(state.get("ticket_id") or 0)
        ticket = get_support_ticket(ticket_id)
        if not ticket:
            clear_support_ticket_pending(uid)
            await update.message.reply_text("Không tìm thấy ticket.")
            return True
        set_support_ticket_pending(uid, "admin_reply_preview", ticket_id=ticket_id, reply_text=text, source=state.get("source") or "new")
        await update.message.reply_text(
            "📨 <b>Xác nhận gửi phản hồi</b>\n\n"
            f"Gửi tới ticket <code>{html.escape(ticket['ticket_code'])}</code>\n\n"
            f"Nội dung:\n{html.escape(text)}\n\nBạn có muốn gửi cho khách không?",
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📨 Gửi cho khách", callback_data=f"ticket|send|{ticket_id}"), InlineKeyboardButton("✍️ Sửa lại", callback_data=f"ticket|reply|{ticket_id}")],
                [InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|av|{ticket_id}|new"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
        return True
    if step == "admin_note_input" and is_admin_user(uid):
        ticket_id = int(state.get("ticket_id") or 0)
        ticket = get_support_ticket(ticket_id)
        if not ticket:
            clear_support_ticket_pending(uid)
            await update.message.reply_text("Không tìm thấy ticket.")
            return True
        existing = str(ticket.get("admin_note") or "").strip()
        note = f"{existing}\n[{now_text()} admin {uid}] {text}".strip()[:4000]
        ticket = update_support_ticket(ticket_id, admin_note=note)
        clear_support_ticket_pending(uid)
        await update.message.reply_text(support_ticket_admin_text(ticket), parse_mode="HTML", reply_markup=support_ticket_admin_keyboard(ticket))
        return True
    if step == "admin_search" and is_admin_user(uid):
        clear_support_ticket_pending(uid)
        payload, keyboard = support_admin_search_payload(text)
        await update.message.reply_text(payload, parse_mode="HTML", reply_markup=keyboard)
        return True
    return False

async def handle_support_ticket_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    """Backward-compatible entry point for existing handlers and tests."""
    return await handle_support_pending_input(update, context)

async def handle_human_support_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    uid = query.from_user.id
    if action == "start":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, human_support_text(), reply_markup=human_support_keyboard())
    if action == "admin_contact":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, support_admin_contact_text(), reply_markup=support_admin_contact_keyboard())
    if action == "ticket":
        set_support_ticket_pending(
            uid,
            "awaiting_message",
            category="general_support",
            source="human_support",
            support_flow="create_support_ticket",
            support_origin="support_main",
            awaiting_support_message="1",
            back_to="support|start",
        )
        return await safe_edit_or_send(
            query,
            support_general_ticket_prompt(),
            reply_markup=support_flow_back_keyboard("support|start", "⬅️ Hỗ trợ", include_tickets=True),
        )
    if action == "premium":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, support_premium_text(), reply_markup=support_premium_keyboard())
    if action == "premium_type" and len(parts) >= 3:
        options = {
            "personal": "Cá nhân/Creator",
            "shop": "Shop/Affiliate",
            "business": "Doanh nghiệp",
            "private": "Tư vấn riêng",
        }
        selected = options.get(parts[2], "Tư vấn Premium")
        set_support_ticket_pending(
            uid,
            "lead_input",
            category="premium_lead",
            selected_option=selected,
            lead_type=f"premium_{parts[2]}",
            support_flow="premium_lead",
            support_origin="premium",
            awaiting_support_message="1",
            back_to="support|premium",
        )
        return await safe_edit_or_send(
            query,
            support_lead_input_text("premium_lead", selected),
            reply_markup=support_flow_back_keyboard("support|premium", "⬅️ Đăng ký Premium", include_tickets=True),
        )
    if action == "bot":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, support_custom_bot_text(), reply_markup=support_custom_bot_keyboard())
    if action == "bot_type" and len(parts) >= 3:
        bot_type = parts[2] if parts[2] in SUPPORT_CUSTOM_BOT_DETAILS else "custom"
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(
            query,
            support_custom_bot_detail_text(bot_type),
            reply_markup=support_custom_bot_detail_keyboard(bot_type),
        )
    if action == "bot_input" and len(parts) >= 3:
        bot_type = parts[2] if parts[2] in SUPPORT_CUSTOM_BOT_DETAILS else "custom"
        detail = SUPPORT_CUSTOM_BOT_DETAILS[bot_type]
        set_support_ticket_pending(
            uid,
            "lead_input",
            category="custom_bot_lead",
            selected_option=detail["title"],
            lead_type=detail["lead_type"],
            support_flow="custom_bot_lead",
            support_origin="custom_bot",
            awaiting_support_message="1",
            back_to=f"support|bot_type|{bot_type}",
        )
        return await safe_edit_or_send(
            query,
            support_custom_bot_detail_text(bot_type) + "\n\n✍️ Bạn nhập câu trả lời trong một tin nhắn nhé.",
            reply_markup=support_flow_back_keyboard(f"support|bot_type|{bot_type}", "⬅️ Loại bot này", include_tickets=True),
        )
    if action == "consult":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(
            query,
            "📦 <b>Tư vấn gói dịch vụ</b>\n\nBạn muốn tư vấn nhóm nào?",
            reply_markup=support_consult_keyboard(),
        )
    if action == "consult_type" and len(parts) >= 3:
        service_type = parts[2] if parts[2] in SUPPORT_CONSULT_DETAILS else "video"
        return await safe_edit_or_send(
            query,
            support_consult_detail_text(service_type),
            reply_markup=support_consult_detail_keyboard(service_type),
        )
    if action in {"consult_need", "consult_input"} and len(parts) >= 3:
        service_type = parts[2] if parts[2] in SUPPORT_CONSULT_DETAILS else "video"
        title, choices, question = SUPPORT_CONSULT_DETAILS[service_type]
        selected = title
        if action == "consult_need" and len(parts) >= 4:
            choice_index = max(0, min(int(parts[3] or 0), len(choices) - 1))
            selected = f"{title} — {choices[choice_index]}"
        set_support_ticket_pending(
            uid,
            "lead_input",
            category="service_consulting",
            selected_option=selected,
            service_type=service_type,
            lead_type=service_type,
            support_flow="service_consulting",
            support_origin="service_consulting",
            service_group=service_type,
            awaiting_support_message="1",
            back_to=f"support|consult_type|{service_type}",
        )
        return await safe_edit_or_send(
            query,
            f"📦 <b>{html.escape(selected)}</b>\n\n{html.escape(question)}\n\n✍️ Bạn nhập nhu cầu trong một tin nhắn nhé.",
            reply_markup=support_flow_back_keyboard(
                f"support|consult_type|{service_type}",
                f"⬅️ {title}",
                include_tickets=True,
            ),
        )
    return await query.answer("Thao tác hỗ trợ chưa được hỗ trợ.", show_alert=True)

async def handle_ticket_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = str(query.data or "")
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else "start"
    uid = query.from_user.id
    admin_actions = {"admin", "al", "av", "asearch", "stats", "templates", "st", "reply", "suggest", "send", "ask", "note", "assign", "lead", "file"}
    if action in admin_actions and not is_admin_user(uid):
        return await query.answer("Khu vực này chỉ dành cho Admin.", show_alert=True)
    if action == "start":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, support_ticket_menu_text(), reply_markup=support_ticket_menu_keyboard())
    if action == "cat" and len(parts) >= 3:
        category = parts[2]
        if category not in SUPPORT_CATEGORIES:
            category = "other"
        set_support_ticket_pending(uid, "awaiting_message", category=category)
        return await safe_edit_or_send(query, support_ticket_message_prompt(category), reply_markup=support_ticket_input_keyboard())
    if action == "mine":
        clear_support_ticket_pending(uid)
        text, keyboard = public_support_ticket_list_keyboard(uid)
        return await safe_edit_or_send(query, text, reply_markup=keyboard)
    if action == "pv" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]), uid)
        if not ticket:
            return await query.answer("Ticket không tồn tại hoặc không thuộc tài khoản của bạn.", show_alert=True)
        return await safe_edit_or_send(
            query,
            public_support_ticket_text(ticket),
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("💬 Gửi thêm nội dung", callback_data=f"ticket|reply_user|{ticket['id']}"), InlineKeyboardButton("📎 Gửi thêm ảnh/file", callback_data=f"ticket|attach|{ticket['id']}")],
                [InlineKeyboardButton("✅ Đánh dấu đã xong", callback_data=f"ticket|done|{ticket['id']}"), InlineKeyboardButton("📂 Ticket của tôi", callback_data="ticket|mine")],
                [InlineKeyboardButton("⬅️ Hỗ trợ", callback_data="support|start"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
    if action == "reply_user" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]), uid)
        if not ticket:
            return await query.answer("Ticket không tồn tại hoặc không thuộc tài khoản của bạn.", show_alert=True)
        set_support_ticket_pending(
            uid,
            "awaiting_ticket_reply",
            ticket_id=ticket["id"],
            support_flow="ticket_reply",
            awaiting_support_message="1",
            back_to=f"ticket|pv|{ticket['id']}",
        )
        return await safe_edit_or_send(
            query,
            f"💬 <b>Bổ sung ticket {html.escape(ticket['ticket_code'])}</b>\n\nBạn nhập nội dung cần bổ sung. TOAN AAS sẽ lưu vào đúng ticket này.",
            reply_markup=support_flow_back_keyboard(f"ticket|pv|{ticket['id']}", "⬅️ Ticket"),
        )
    if action == "done" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]), uid)
        if not ticket:
            return await query.answer("Ticket không tồn tại hoặc không thuộc tài khoản của bạn.", show_alert=True)
        ticket = update_support_ticket(ticket["id"], status="resolved") or ticket
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(
            query,
            f"✅ Ticket <code>{html.escape(ticket['ticket_code'])}</code> đã được đánh dấu đã xong.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📂 Ticket của tôi", callback_data="ticket|mine"), InlineKeyboardButton("⬅️ Hỗ trợ", callback_data="support|start")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
    if action == "attach" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]), uid)
        if not ticket:
            return await query.answer("Ticket không tồn tại hoặc không thuộc tài khoản của bạn.", show_alert=True)
        set_support_ticket_pending(uid, "awaiting_attachment", ticket_id=ticket["id"])
        return await safe_edit_or_send(
            query,
            f"📎 Gửi một ảnh chụp màn hình hoặc file cho ticket <code>{html.escape(ticket['ticket_code'])}</code>.\n\nNên gửi từng file một để tránh lỗi.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|pv|{ticket['id']}"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")]]),
        )
    if action == "admin":
        clear_support_ticket_pending(uid)
        return await safe_edit_or_send(query, support_admin_menu_text(), reply_markup=support_admin_menu_keyboard())
    if action == "al" and len(parts) >= 4:
        kind = parts[2]
        offset = max(0, int(parts[3] or 0))
        text, keyboard = support_admin_list_payload(kind, offset)
        return await safe_edit_or_send(query, text, reply_markup=keyboard)
    if action == "av" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]))
        if not ticket:
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        source = parts[3] if len(parts) >= 4 else "new"
        return await safe_edit_or_send(query, support_ticket_admin_text(ticket), reply_markup=support_ticket_admin_keyboard(ticket, source))
    if action == "asearch" and len(parts) >= 3:
        set_support_ticket_pending(uid, "admin_search", source=parts[2])
        prompt = "Nhập user ID để tìm ticket." if parts[2] == "user" else "Nhập mã ticket, user ID, username hoặc từ khóa."
        return await safe_edit_or_send(query, f"🔍 <b>Tìm ticket</b>\n\n{prompt}", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ CSKH/Ticket", callback_data="ticket|admin"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")]]))
    if action == "stats":
        return await safe_edit_or_send(query, support_ticket_stats_text(), reply_markup=support_admin_menu_keyboard())
    if action == "templates":
        return await safe_edit_or_send(query, support_reply_templates_text(), reply_markup=support_admin_menu_keyboard())
    if action == "st" and len(parts) >= 4:
        ticket_id = int(parts[2])
        new_status = parts[3]
        ticket = update_support_ticket(ticket_id, status=new_status)
        if not ticket:
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        if new_status == "refund_pending":
            await query.message.reply_text("💰 Ticket đã được đánh dấu cần kiểm tra hoàn Xu/refund. Thao tác này chưa cộng hoặc trừ Xu.")
        return await safe_edit_or_send(query, support_ticket_admin_text(ticket), reply_markup=support_ticket_admin_keyboard(ticket))
    if action == "reply" and len(parts) >= 3:
        ticket_id = int(parts[2])
        if not get_support_ticket(ticket_id):
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        set_support_ticket_pending(uid, "admin_reply_input", ticket_id=ticket_id, source="new")
        return await safe_edit_or_send(query, "💬 Nhập nội dung phản hồi cho khách. Bot chỉ gửi sau khi admin xem preview và bấm xác nhận.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|av|{ticket_id}|new"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")]]))
    if action == "ask" and len(parts) >= 3:
        ticket_id = int(parts[2])
        set_support_ticket_pending(uid, "admin_reply_input", ticket_id=ticket_id, source="new")
        return await safe_edit_or_send(query, "👤 Nhập câu hỏi hoặc thông tin bạn cần khách bổ sung. Bot sẽ cho xem preview trước khi gửi.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|av|{ticket_id}|new")]]))
    if action == "suggest" and len(parts) >= 4:
        ticket_id = int(parts[2])
        variant = int(parts[3] or 0)
        ticket = get_support_ticket(ticket_id)
        if not ticket:
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        reply_text = support_suggested_reply(ticket.get("category"), variant, ticket.get("message") or "")
        update_support_ticket(ticket_id, suggested_reply=reply_text)
        set_support_ticket_pending(uid, "admin_reply_preview", ticket_id=ticket_id, reply_text=reply_text, variant=variant, source="new")
        return await safe_edit_or_send(
            query,
            "🤖 <b>Gợi ý trả lời</b>\n\n"
            f"{html.escape(reply_text)}\n\nBot chưa gửi nội dung này cho khách.",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📨 Gửi cho khách", callback_data=f"ticket|send|{ticket_id}"), InlineKeyboardButton("✍️ Sửa lại", callback_data=f"ticket|reply|{ticket_id}")],
                [InlineKeyboardButton("🔄 Gợi ý khác", callback_data=f"ticket|suggest|{ticket_id}|{variant + 1}"), InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|av|{ticket_id}|new")],
            ]),
        )
    if action == "send" and len(parts) >= 3:
        ticket_id = int(parts[2])
        state = get_support_ticket_pending(uid) or {}
        if state.get("step") != "admin_reply_preview" or int(state.get("ticket_id") or 0) != ticket_id:
            return await query.answer("Bản xem trước đã hết hạn. Vui lòng soạn hoặc tạo gợi ý lại.", show_alert=True)
        ticket = get_support_ticket(ticket_id)
        reply_text = str(state.get("reply_text") or "").strip()
        if not ticket or not reply_text:
            return await query.answer("Không có nội dung hợp lệ để gửi.", show_alert=True)
        try:
            await context.bot.send_message(
                chat_id=ticket["user_id"],
                text=(f"💬 <b>Phản hồi từ TOAN AAS</b>\nTicket: <code>{html.escape(ticket['ticket_code'])}</code>\n\n{html.escape(reply_text)}"),
                parse_mode="HTML",
            )
        except Exception as exc:
            logger.warning("support ticket reply send failed | ticket_id=%s error=%s", ticket_id, type(exc).__name__)
            return await query.answer("Không gửi được phản hồi. Ticket chưa được đánh dấu đã gửi.", show_alert=True)
        add_support_ticket_message(ticket_id, "admin", uid, reply_text, "sent")
        ticket = update_support_ticket(ticket_id, status="waiting_user", assigned_admin_id=uid)
        clear_support_ticket_pending(uid)
        await query.message.reply_text("✅ Đã gửi phản hồi cho đúng user của ticket.")
        return await safe_edit_or_send(query, support_ticket_admin_text(ticket), reply_markup=support_ticket_admin_keyboard(ticket))
    if action == "note" and len(parts) >= 3:
        ticket_id = int(parts[2])
        set_support_ticket_pending(uid, "admin_note_input", ticket_id=ticket_id)
        return await safe_edit_or_send(query, "📌 Nhập ghi chú nội bộ. Nội dung này không hiển thị cho khách.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("⬅️ Ticket", callback_data=f"ticket|av|{ticket_id}|new")]]))
    if action == "assign" and len(parts) >= 3:
        ticket = update_support_ticket(int(parts[2]), status="reviewing", assigned_admin_id=uid)
        if not ticket:
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        return await safe_edit_or_send(query, support_ticket_admin_text(ticket), reply_markup=support_ticket_admin_keyboard(ticket))
    if action == "lead" and len(parts) >= 4:
        ticket = get_support_ticket(int(parts[2]))
        if not ticket:
            return await query.answer("Không tìm thấy ticket.", show_alert=True)
        marker = "Cần liên hệ" if parts[3] == "contact" else "Lead tiềm năng"
        note = f"{ticket.get('admin_note') or ''}\n[{now_text()} admin {uid}] {marker}".strip()
        ticket = update_support_ticket(ticket["id"], status="reviewing", assigned_admin_id=uid, admin_note=note)
        return await safe_edit_or_send(query, support_ticket_admin_text(ticket), reply_markup=support_ticket_admin_keyboard(ticket))
    if action == "file" and len(parts) >= 3:
        ticket = get_support_ticket(int(parts[2]))
        if not ticket or not ticket.get("attachment_file_id"):
            return await query.answer("Ticket chưa có file đính kèm.", show_alert=True)
        caption = f"📎 File của ticket <code>{html.escape(ticket['ticket_code'])}</code>"
        try:
            if ticket.get("attachment_type") == "photo":
                await context.bot.send_photo(chat_id=query.message.chat_id, photo=ticket["attachment_file_id"], caption=caption, parse_mode="HTML")
            else:
                await context.bot.send_document(chat_id=query.message.chat_id, document=ticket["attachment_file_id"], caption=caption, parse_mode="HTML")
        except Exception as exc:
            logger.warning("support attachment send failed | ticket_id=%s error=%s", ticket.get("id"), type(exc).__name__)
            return await query.answer("Không gửi lại được file đính kèm.", show_alert=True)
        return
    return await query.answer("Thao tác ticket chưa được hỗ trợ.", show_alert=True)

async def handle_admin_help_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    if not is_admin_user(query.from_user.id):
        return await query.answer("⛔ Khu vực này chỉ dành cho Admin.", show_alert=True)
    kind = (query.data.split("|", 1)[1] if "|" in query.data else "payment").strip()
    return await safe_edit_query_message(
        query,
        admin_handbook_section_text(kind),
        reply_markup=admin_handbook_section_keyboard(kind),
    )

async def handle_menu_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    action = (query.data.split("|", 1)[1] if "|" in query.data else "main").strip()
    user_is_admin = is_admin_user(query.from_user.id)
    lang = get_user_language(query.from_user.id) or "vi"
    if action not in {"translation_text", "translation_transcript"} and not action.startswith("translation_text_target_"):
        clear_translation_menu_pending(query.from_user.id)
    keep_translation_session = (
        action == "translate"
        or action.startswith("translation_")
        or action.startswith("translate_set_")
        or action in {"translate_more", "translate_off"}
    )
    if keep_translation_session:
        enter_product_context(query.from_user.id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|translate", product_area="translation")
    if not keep_translation_session:
        clear_translation_session(query.from_user.id)
    clear_media_creator_pending_states(query.from_user.id)
    clear_support_ticket_pending(query.from_user.id)
    if action != "finance_compliance_update":
        clear_finance_compliance_pending(query.from_user.id)
    if action != "internal_archive":
        clear_internal_archive_pending(query.from_user.id)
    if action not in DOC_TOOL_MENU_ACTIONS:
        clear_doc_tool_pending(query.from_user.id)
    if action != "memory_storage_addon":
        clear_storage_addon_pending(query.from_user.id)
    if action not in {"hint_note", "hint_search_note"}:
        clear_memory_guided_pending(query.from_user.id)
    clear_music_guided_pending(query.from_user.id)
    admin_only = {"affiliate", "operator", "admin", "system", "finance", "billing", "admin_packages", "admin_provider", "internal_archive"}
    admin_only_prefixes = (
        "finance_",
        "tax_",
        "freeze_",
        "admin_",
        "system_",
        "smoke_",
        "provider_custom",
        "clear_stale",
        "unfreeze_",
    )
