def video_gate_tool_status(tool_name: str) -> str:
    return str((preferred_tool_test_result(tool_name) or {}).get("status") or "NOT_TESTED").upper()

def video_gate_detail_has_output(detail: str = "") -> bool:
    text = str(detail or "").lower()
    return any(marker in text for marker in (
        "output_sent=yes",
        "output sent yes",
        "output_sent=true",
        "result_url",
        "video_url",
        "output_url",
        "sent_video=yes",
        "send_video=ok",
    ))

def video_ai_provider_smoke_gate() -> dict:
    snap = shopaikey_video_status_snapshot()
    status = str(snap.get("status") or "NOT_TESTED").upper()
    detail = str(snap.get("detail") or "")
    has_output = bool(video_gate_detail_has_output(detail))
    if has_output and status in {"PASS_SUBMITTED", "SUBMITTED", "IN_PROGRESS", "PROCESSING", "RUNNING", "QUEUED", "PENDING", "NOT_TESTED", ""}:
        status = "SUCCESS"
        snap["status"] = "SUCCESS"
    success_status = status in {"PASS", "SUCCESS", "COMPLETED", "DONE", "SUCCEEDED", "LIVE_PASS"}
    submitted_only = status in {"PASS_SUBMITTED", "SUBMITTED", "IN_PROGRESS", "PROCESSING", "RUNNING", "QUEUED", "PENDING"}
    blockers = []
    if not success_status:
        if submitted_only:
            blockers.append(f"Last video smoke still not completed: {status}")
        elif status == "TIMEOUT_STALE":
            blockers.append("Last video smoke: TIMEOUT_STALE")
        else:
            blockers.append(f"Last video smoke: {status}")
    if success_status and not has_output:
        blockers.append("Provider output/result_url and Telegram output_sent not confirmed")
    if provider_freeze_runtime_on("shopaikey_video"):
        blockers.append("Provider/video freeze is active")
    if not SHOPAIKEY_ENABLED:
        blockers.append("SHOPAIKEY_ENABLED=false")
    if not SHOPAIKEY_API_KEY:
        blockers.append("SHOPAIKEY_API_KEY missing")
    if not SHOPAIKEY_VIDEO_URL:
        blockers.append("SHOPAIKEY_VIDEO_URL missing")
    if not SHOPAIKEY_VIDEO_MODEL:
        blockers.append("SHOPAIKEY_VIDEO_MODEL missing")
    return {
        "ready": not blockers,
        "status": status,
        "detail": detail,
        "model": snap.get("model") or SHOPAIKEY_VIDEO_MODEL,
        "tested_at": snap.get("tested_at") or "",
        "has_output": has_output,
        "blockers": blockers,
    }

def frame_video_public_gate() -> dict:
    frame = frame_video_status_payload()
    status = video_gate_tool_status("frame_video")
    blockers = []
    if not FRAME_VIDEO_ENABLED:
        blockers.append("FRAME_VIDEO_ENABLED=false")
    if not frame.get("local_worker_connected"):
        blockers.append("Local Worker not connected")
    if not frame.get("ffmpeg_configured"):
        blockers.append("ffmpeg missing")
    if FRAME_VIDEO_DIRECT_RENDER_ENABLED:
        blockers.append("FRAME_VIDEO_DIRECT_RENDER_ENABLED=true; Railway direct render is not safe")
    if not FRAME_VIDEO_REQUIRE_LOCAL_WORKER:
        blockers.append("FRAME_VIDEO_REQUIRE_LOCAL_WORKER=false")
    if int(FRAME_VIDEO_MAX_CONCURRENT_JOBS or 1) > 1:
        blockers.append("FRAME_VIDEO_MAX_CONCURRENT_JOBS must be 1")
    if status != "PASS":
        blockers.append(f"/tool_test_frame_video status is {status}")
    if str(frame.get("last_error") or "").strip():
        blockers.append(f"last frame video error: {str(frame.get('last_error'))[:120]}")
    return {
        "ready": not blockers,
        "status": status,
        "frame": frame,
        "blockers": blockers,
    }

def video_billing_public_gate() -> dict:
    blockers = []
    if not VIDEO_PRICING_ENABLED:
        blockers.append("VIDEO_PRICING_ENABLED=false")
    if not SHOPAIKEY_REQUIRE_CONFIRM_BEFORE_DEDUCT or not VIDEO_PUBLIC_REQUIRE_CONFIRM:
        blockers.append("SHOPAIKEY_REQUIRE_CONFIRM_BEFORE_DEDUCT=false")
    if not SHOPAIKEY_REFUND_ON_PROVIDER_FAIL:
        blockers.append("SHOPAIKEY_REFUND_ON_PROVIDER_FAIL=false")
    if not SHOPAIKEY_PUBLIC_JOB_LOCK_ENABLED or not VIDEO_PUBLIC_REQUIRE_JOB_LOCK:
        blockers.append("SHOPAIKEY_PUBLIC_JOB_LOCK_ENABLED=false")
    if not SHOPAIKEY_VIDEO_JOB_LOCK_ENABLED:
        blockers.append("SHOPAIKEY_VIDEO_JOB_LOCK_ENABLED=false")
    if int(VIDEO_PUBLIC_MAX_CONCURRENT_JOBS or 1) > 1:
        blockers.append("VIDEO_PUBLIC_MAX_CONCURRENT_JOBS must be 1 for beta")
    if int(VIDEO_PUBLIC_MAX_DURATION_SECONDS or 0) > 8:
        blockers.append("VIDEO_PUBLIC_MAX_DURATION_SECONDS must stay <= 8 for beta")
    cost_rows = video_public_beta_cost_rows()
    base_enabled = {
        "low": bool(VIDEO_TIER_LOW_ENABLED),
        "basic": bool(VIDEO_TIER_BASIC_ENABLED),
        "common": bool(VIDEO_TIER_COMMON_ENABLED),
        "advanced": video_tier_public_flag("advanced"),
        "standard": video_tier_public_flag("standard"),
        "high": video_tier_public_flag("high"),
        "future_1000": video_tier_public_flag("future_1000"),
        "future_1200": video_tier_public_flag("future_1200"),
        "future_1500": video_tier_public_flag("future_1500"),
    }
    enabled_allowed = [
        tier for tier in video_public_allowed_tiers()
        if base_enabled.get(tier) and tier in video_public_launch_tiers()
    ]
    if not enabled_allowed:
        blockers.append("No 200/300/400/500/600/800/1000/1200/1500 public video tier enabled in allowlist")
    if VIDEO_PREMIUM_PUBLIC_ENABLED or (VIDEO_TIER_PREMIUM_ENABLED and not VIDEO_PREMIUM_ADMIN_ONLY):
        blockers.append("Premium video public must stay OFF")
    return {
        "ready": not blockers,
        "allowed_tiers": enabled_allowed,
        "cost_rows": cost_rows,
        "tier_blockers": [],
        "blockers": blockers,
    }

def video_public_status_payload() -> dict:
    ops = current_system_mode()
    frame_gate = frame_video_public_gate()
    ai_gate = video_ai_provider_smoke_gate()
    billing_gate = video_billing_public_gate()
    freeze = provider_freeze_display("shopaikey_video")
    worker = local_worker_status_payload()
    planning_public = bool(VIDEO_PLANNING_PUBLIC_ENABLED and VIDEO_TREND_CONTENT_PUBLIC_ENABLED and VIDEO_STORYBOARD_PUBLIC_ENABLED)
    frame_public = bool(FRAME_VIDEO_PUBLIC_ENABLED and frame_gate["ready"])
    ai_public = bool(
        video_public_beta_enabled_runtime()
        and video_ai_public_enabled_runtime()
        and video_ai_master_enabled_runtime()
        and shopaikey_public_video_enabled_runtime()
        and ai_gate["ready"]
        and billing_gate["ready"]
    )
    def _tier_public_conclusion(tier_name: str) -> str:
        tier_name = normalize_video_tier(tier_name)
        ui_status = get_public_video_tier_ui_status(tier_name)
        if tier_name in video_high_tiers():
            if tier_name in billing_gate.get("allowed_tiers", []) and ui_status.get("enabled"):
                return str(ui_status.get("public_status") or "PUBLIC") if ai_public else "PUBLIC_WITH_PROVIDER_GUARD"
            return "PUBLIC_WITH_PROVIDER_GUARD" if video_tier_public_flag(tier_name) else "MAINTENANCE_PROVIDER"
        if not ai_public or tier_name not in billing_gate.get("allowed_tiers", []):
            return "OFF"
        return str(ui_status.get("public_status") or "PUBLIC")

    return {
        "ops": ops,
        "frame_gate": frame_gate,
        "ai_gate": ai_gate,
        "billing_gate": billing_gate,
        "worker": worker,
        "freeze": freeze,
        "public_flags": {
            "VIDEO_PLANNING_PUBLIC_ENABLED": bool(VIDEO_PLANNING_PUBLIC_ENABLED),
            "VIDEO_TREND_CONTENT_PUBLIC_ENABLED": bool(VIDEO_TREND_CONTENT_PUBLIC_ENABLED),
            "VIDEO_STORYBOARD_PUBLIC_ENABLED": bool(VIDEO_STORYBOARD_PUBLIC_ENABLED),
            "SHOPAIKEY_PUBLIC_VIDEO_ENABLED": bool(shopaikey_public_video_enabled_runtime()),
            "VIDEO_AI_PUBLIC_ENABLED": bool(video_ai_public_enabled_runtime()),
            "VIDEO_AI_MASTER_ENABLED": bool(video_ai_master_enabled_runtime()),
            "VIDEO_TEXT_TO_VIDEO_PUBLIC_ENABLED": bool(video_text_to_video_public_enabled_runtime()),
            "VIDEO_PUBLIC_BETA_ENABLED": bool(video_public_beta_enabled_runtime()),
            "VIDEO_BETA_200_MARKETING_LOSS_ENABLED": bool(video_beta_200_marketing_loss_enabled_runtime()),
            "VIDEO_BETA_200_MAX_USER_DAY": int(VIDEO_BETA_200_MAX_USER_DAY or 1),
            "VIDEO_BETA_200_MAX_USER_WEEK": int(VIDEO_BETA_200_MAX_USER_WEEK or 1),
            "VIDEO_BETA_200_MAX_USER_MONTH": int(VIDEO_BETA_200_MAX_USER_MONTH or 1),
            "VIDEO_BETA_200_MAX_TOTAL_DAY": int(VIDEO_BETA_200_MAX_TOTAL_DAY or 10),
            "VIDEO_PUBLIC_MAX_DURATION_SECONDS": int(VIDEO_PUBLIC_MAX_DURATION_SECONDS or 0),
            "VIDEO_PUBLIC_MAX_JOBS_PER_USER_PER_DAY": int(VIDEO_PUBLIC_MAX_JOBS_PER_USER_PER_DAY or 0),
            "VIDEO_PUBLIC_MAX_CONCURRENT_JOBS": int(VIDEO_PUBLIC_MAX_CONCURRENT_JOBS or 0),
            "VIDEO_IMAGE_TO_VIDEO_ENABLED": bool(VIDEO_IMAGE_TO_VIDEO_ENABLED),
            "VIDEO_VIDEO_TO_VIDEO_ENABLED": bool(VIDEO_VIDEO_TO_VIDEO_ENABLED),
            "VIDEO_LONG_RENDER_ENABLED": bool(VIDEO_LONG_RENDER_ENABLED),
            "VIDEO_TREND_RENDER_ENABLED": bool(VIDEO_TREND_RENDER_ENABLED),
            "FRAME_VIDEO_PUBLIC_ENABLED": bool(FRAME_VIDEO_PUBLIC_ENABLED),
            "LOCAL_WORKER_ENABLED": bool(LOCAL_WORKER_ENABLED),
        },
        "conclusion": {
            "planning_video": "PUBLIC" if planning_public else "OFF",
            "trend_content": "PUBLIC" if VIDEO_TREND_CONTENT_PUBLIC_ENABLED else "OFF",
            "storyboard": "PUBLIC" if VIDEO_STORYBOARD_PUBLIC_ENABLED else "OFF",
            "frame_video_local": "PUBLIC" if frame_public else ("GUARDED" if FRAME_VIDEO_PUBLIC_ENABLED else "OFF"),
            "video_ai_from_prompt": "PUBLIC" if ai_public else ("ADMIN_ONLY" if ai_gate.get("status") in {"PASS_SUBMITTED", "SUCCESS", "PASS", "COMPLETED"} else "OFF"),
            "video_ai_realistic": "PUBLIC" if ai_public else "ADMIN_ONLY",
            "video_beta_200": (
                "PUBLIC_MARKETING_LOSS"
                if ai_public and "low" in billing_gate.get("allowed_tiers", []) and video_beta_200_marketing_loss_enabled_runtime()
                else "OFF"
            ),
            "video_beta_300": "PUBLIC" if ai_public and "basic" in billing_gate.get("allowed_tiers", []) else "OFF",
            "video_beta_400": "PUBLIC" if ai_public and "common" in billing_gate.get("allowed_tiers", []) else "OFF",
            "video_500": _tier_public_conclusion("advanced"),
            "video_600": _tier_public_conclusion("standard"),
            "video_800": _tier_public_conclusion("high"),
            "video_1000": _tier_public_conclusion("future_1000"),
            "video_1200": _tier_public_conclusion("future_1200"),
            "video_1500": _tier_public_conclusion("future_1500"),
            "video_600_plus": "PUBLIC" if ai_public and any(tier in billing_gate.get("allowed_tiers", []) for tier in {"advanced", "standard", "high", "future_1000", "future_1200", "future_1500"}) else "OFF",
            "premium_video": "OFF",
            "image_to_video": "OFF",
            "video_to_video": "OFF",
            "long_render": "OFF",
        },
    }

