async def cmd_tool_test_minimax_tts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    if not has_admin_paid_confirmation(context):
        save_tool_test_result("minimax_tts", "NO_CONFIRM", f"missing {ADMIN_PAID_CONFIRM_FLAG}; no provider call", uid)
        return await update.message.reply_text(admin_paid_confirm_required_text("/tool_test_minimax_tts"), parse_mode="HTML")
    readiness = get_minimax_voice_readiness()
    if not readiness.get("ready"):
        detail = f"missing={','.join(readiness.get('missing_env') or [])}; reason={readiness.get('admin_debug_reason')}"
        save_tool_test_result("minimax_tts", "NEED_DOCS", detail, uid)
        save_provider_attempt(
            "voice_tts",
            {
                "called": False,
                "provider": "none",
                "route": "minimax_tts",
                "status": "NEED_DOCS",
                "error": detail,
            },
            uid,
        )
        return await update.message.reply_text(
            "🎙 <b>MiniMax TTS Smoke</b>\n\n"
            "• Status: <code>NEED_DOCS/NOT_CONFIGURED</code>\n"
            f"• Missing: <code>{html.escape(', '.join(readiness.get('missing_env') or []) or '-')}</code>\n"
            "• Không gọi provider, không tạo audio giả, không trừ Xu.",
            parse_mode="HTML",
        )
    text = " ".join(args_without_admin_paid_confirmation(context.args or [])).strip() or "Xin chào, đây là bài kiểm tra giọng đọc của TOAN AAS."
    tests = [
        ("default_female", default_tts_voice_id("female")),
        ("default_male", default_tts_voice_id("male")),
    ]
    saved_voice_id = str(readiness.get("saved_voice_id") or "").strip()
    if saved_voice_id:
        tests.append(("saved_voice_id", saved_voice_id))
    results = []
    for label, voice_id in tests:
        route_calls = [("shopaikey", lambda: shopaikey_minimax_tts_bytes(text, voice_id=voice_id))]
        if key4u_minimax_tts_configured(require_public=False):
            route_calls.append(("key4u", lambda: key4u_minimax_tts_bytes(text, voice_id=voice_id, allow_admin=True)))
        for route, make_call in route_calls:
            async def _run_voice_tts_route(make_call=make_call):
                status, audio_bytes, detail, http_status = await make_call()
                return {
                    "ok": bool(status == "PASS" and audio_bytes),
                    "status": status,
                    "audio_bytes": audio_bytes,
                    "detail": detail,
                    "http_status": http_status,
                }
            engine_result = await execute_engine(
                "voice_tts",
                {"runner": _run_voice_tts_route, "voice_id": voice_id, "text": text},
                {
                    "user_id": uid,
                    "entry_source": ENGINE_ENTRY_SOURCE_SLASH_SMOKE,
                    "confirm_paid": True,
                    "is_paid_job": True,
                    "allow_admin": True,
                },
            )
            route_result = dict(engine_result.get("runner_result") or {})
            status = str(route_result.get("status") or engine_result.get("status") or "FAIL")
            audio_bytes = bytes(route_result.get("audio_bytes") or engine_result.get("output_bytes") or b"")
            detail = str(route_result.get("detail") or engine_result.get("detail") or "")
            http_status = int(route_result.get("http_status") or 0)
            output_sent = False
            if status == "PASS" and audio_bytes:
                audio = io.BytesIO(audio_bytes)
                audio.name = f"toan_aas_minimax_{route}_{label}.{MINIMAX_AUDIO_FORMAT or 'mp3'}"
                await context.bot.send_audio(
                    chat_id=update.effective_chat.id,
                    audio=audio,
                    caption=f"🎙 MiniMax TTS smoke: {route}/{label}\nAdmin test: không trừ Xu. Provider có thể tốn credit thật.",
                )
                output_sent = True
            provider_name = "key4u_minimax" if route == "key4u" else "shopaikey_minimax"
            attempt = record_voice_tts_attempt(
                status=status,
                provider=provider_name,
                route=f"{route}/{label}",
                voice_id=voice_id,
                bytes_count=len(audio_bytes or b""),
                output_sent=output_sent,
                error=detail,
                updated_by=uid,
            )
            route_tool = "minimax_tts_key4u" if route == "key4u" else "minimax_tts_shopaikey"
            if status == "PASS" and output_sent:
                save_tool_test_result(
                    route_tool,
                    "PASS",
                    json.dumps({
                        "provider": provider_name,
                        "route": f"{route}/{label}",
                        "voice_id": voice_id,
                        "bytes": int(attempt.get("bytes") or 0),
                        "output_sent": True,
                    }, ensure_ascii=False)[:900],
                    uid,
                )
            else:
                save_tool_test_result(route_tool, status, sanitize_log_text(detail)[:900], uid)
            results.append({
                "label": f"{route}/{label}",
                "voice_id": voice_id,
                "status": status,
                "http": int(http_status or 0),
                "output_sent": output_sent,
                "detail": sanitize_log_text(detail)[:180],
            })
    overall = "PASS" if any(item["status"] == "PASS" and item["output_sent"] for item in results) else str(results[-1]["status"] if results else "FAIL")
    save_tool_test_result("minimax_tts", overall, json.dumps(results, ensure_ascii=False)[:900], uid)
    result_lines = [
        f"• {html.escape(item['label'])}: <code>{html.escape(item['status'])}</code> | voice <code>{html.escape(str(item['voice_id'] or '-'))}</code> | sent <code>{'yes' if item['output_sent'] else 'no'}</code> | HTTP <code>{item['http']}</code>"
        for item in results
    ]
    await update.message.reply_text(
        "🎙 <b>MiniMax TTS Smoke</b>\n\n"
        f"• Status: <code>{html.escape(overall)}</code>\n"
        f"• Model: <code>{html.escape(MINIMAX_TTS_MODEL or '-')}</code>\n"
        + "\n".join(result_lines) + "\n"
        "• No Xu deducted: <code>yes</code>\n"
        "• Nếu không có audio, xem detail đã lưu trong tool test result.",
        parse_mode="HTML",
    )

