async def cmd_refund_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    if not context.args or not str(context.args[0]).isdigit():
        return await update.message.reply_text("Cú pháp: /refund_job <job_id>")
    job_id = int(context.args[0])
    job = shopaikey_job_by_id(job_id)
    if not job:
        return await update.message.reply_text("⚠️ Không tìm thấy job.")
    if str(job.get("refund_status") or "").lower() == "refunded":
        return await update.message.reply_text("ℹ️ Job này đã được hoàn Xu trước đó. Không hoàn trùng.")
    deducted = int(job.get("xu_deducted") or 0)
    if deducted <= 0:
        update_shopaikey_job(job_id=job_id, refund_status="not_charged", refund_reason="manual_refund_no_deduction", billing_status=job.get("billing_status") or "not_charged")
        return await update.message.reply_text("ℹ️ Job này chưa trừ Xu nên không cần hoàn.")
    refunded = refund_shopaikey_job_if_needed(job.get("user_id") or "", job_id, job.get("task_id") or "", "manual_admin_refund")
    fresh = shopaikey_job_by_id(job_id) or job
    response_text = (
        ("✅ Đã hoàn Xu cho job.\n" if refunded else "⚠️ Chưa hoàn được hoặc đã được xử lý trước đó.\n")
        + f"• Job ID: <code>{job_id}</code>\n"
        + f"• User ID: <code>{html.escape(str(job.get('user_id') or '-'))}</code>\n"
        + f"• Deducted: <code>{deducted} Xu</code>\n"
        + f"• Refund status: <code>{html.escape(str(fresh.get('refund_status') or '-'))}</code>\n\n"
        + "Không đụng PayOS/top-up/payment history."
    )
    await update.message.reply_text(
        response_text,
        parse_mode="HTML",
    )

async def cmd_clear_job_lock(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    if not context.args:
        return await update.message.reply_text("Cú pháp: /clear_job_lock <user_id>")
    uid = str(context.args[0] or "").strip()
    if not re.match(r"^[0-9A-Za-z_:-]{2,80}$", uid):
        return await update.message.reply_text("⚠️ User ID không hợp lệ.")
    statuses = tuple(sorted(SHOPAIKEY_ACTIVE_JOB_STATUSES))
    placeholders = ",".join("?" for _ in statuses)
    conn = db_connect()
    conn.row_factory = sqlite3.Row
    try:
        rows = conn.execute(
            f"""SELECT * FROM shopaikey_jobs
            WHERE user_id=? AND job_type='video' AND UPPER(status) IN ({placeholders})
            ORDER BY id DESC LIMIT 20""",
            (uid, *statuses),
        ).fetchall()
    finally:
        conn.close()
    cleared = 0
    refunded = 0
    for row in rows:
        job = dict(row)
        job_id = int(job.get("id") or 0)
        amount = int(job.get("xu_deducted") or 0)
        did_refund = refund_shopaikey_job_if_needed(uid, job_id, job.get("task_id") or "", "manual_clear_job_lock") if amount > 0 else False
        if did_refund:
            refunded += amount
        update_shopaikey_job(
            job_id=job_id,
            status="FAILED_MANUAL_CLEAR",
            error_class="MANUAL_CLEAR",
            fail_reason="admin_clear_job_lock",
            refund_status="refunded" if did_refund else ("not_charged" if amount <= 0 else str(job.get("refund_status") or "")),
            refund_reason="manual_clear_job_lock",
            billing_status="refunded" if did_refund else ("manual_clear_no_charge" if amount <= 0 else str(job.get("billing_status") or "")),
            finished_at=now_text(),
        )
        cleared += 1
    await update.message.reply_text(
        "🧹 <b>Clear Video Job Lock</b>\n\n"
        f"• User ID: <code>{html.escape(uid)}</code>\n"
        f"• Jobs cleared: <code>{cleared}</code>\n"
        f"• Xu refunded: <code>{refunded}</code>\n\n"
        "Chỉ clear active ShopAIKey video jobs. Không đụng PayOS/top-up.",
        parse_mode="HTML",
    )

async def cmd_shopaikey_usage(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    result = await get_shopaikey_usage()
    usage = result.get("usage") or {}
    detail = (
        f"http={result.get('http_status')}; latency_ms={result.get('latency_ms')}; "
        f"total={format_quota_number(usage.get('total'))}; used={format_quota_number(usage.get('used'))}; "
        f"remaining={format_quota_number(usage.get('remaining'))}; "
        f"remaining_percent={format_quota_number(usage.get('remaining_percent'))}; "
        f"group={str(usage.get('group_name') or '-')[:120]}; error_class={result.get('error_class') or '-'}"
    )
    save_tool_test_result("shopaikey_usage", result.get("status") or "FAIL", detail, uid)
    record_api_debug("shopaikey", "usage", result.get("status") or "FAIL", int(result.get("http_status") or 0), detail)
    if result.get("status") == "PASS":
        save_shopaikey_usage_snapshot(usage, uid)
        alert_sent = await maybe_alert_shopaikey_low_quota(context.bot, usage, uid)
        remaining_percent = float(usage.get("remaining_percent") or 0)
        status_label = "LOW" if remaining_percent <= float(SHOPAIKEY_USAGE_ALERT_PERCENT or 10) else "OK"
        return await update.message.reply_text(
            "📊 <b>ShopAIKey Usage</b>\n\n"
            f"• Status: <code>{status_label}</code>\n"
            f"• Total: <code>{format_quota_number(usage.get('total'))}</code>\n"
            f"• Used: <code>{format_quota_number(usage.get('used'))}</code>\n"
            f"• Balance: <code>{format_quota_number(usage.get('balance'))}</code>\n"
            f"• Remaining: <code>{format_quota_number(usage.get('remaining'))}</code>\n"
            f"• Remaining percent: <code>{remaining_percent:.2f}%</code>\n"
            f"• Group: <code>{html.escape(usage.get('group_name') or '-')}</code>\n"
            f"• Token: <code>{html.escape(mask_key_fingerprint(usage.get('token_name') or ''))}</code>\n"
            f"• Alert threshold: <code>{SHOPAIKEY_USAGE_ALERT_PERCENT}%</code>\n"
            f"• Alert sent now: <code>{'yes' if alert_sent else 'no'}</code>\n\n"
            "Không hiển thị API key hoặc usage URL đầy đủ.",
            parse_mode="HTML",
        )
    record_provider_error(
        "shopaikey",
        "usage",
        classify_provider_error(result.get("http_status") or 0, result.get("error_class") or result.get("status") or "", result.get("detail") or detail),
        result.get("detail") or detail,
    )
    await update.message.reply_text(
        "📊 <b>ShopAIKey Usage</b>\n\n"
        f"• Status: <code>{html.escape(str(result.get('status') or 'FAIL'))}</code>\n"
        f"• HTTP: <code>{html.escape(str(result.get('http_status') or 0))}</code>\n"
        f"• Error class: <code>{html.escape(str(result.get('error_class') or '-'))}</code>\n"
        f"• Detail: <code>{html.escape(str(result.get('detail') or '-')[:220])}</code>\n\n"
        "Không hiển thị API key hoặc usage URL đầy đủ.",
        parse_mode="HTML",
    )

async def cmd_tool_test_shopaikey(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    lang = user_ui_lang(uid)
    if not SHOPAIKEY_ENABLED:
        save_tool_test_result("shopaikey", "DISABLED", "SHOPAIKEY_ENABLED=false; no call", uid)
        return await update.message.reply_text(
            "🧪 <b>ShopAIKey Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Set <code>SHOPAIKEY_ENABLED=true</code> only for admin testing.\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    if not SHOPAIKEY_ADMIN_ONLY:
        save_tool_test_result("shopaikey", "DISABLED", "SHOPAIKEY_ADMIN_ONLY=false unsafe; no call", uid)
        return await update.message.reply_text(
            "🧪 <b>ShopAIKey Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Reason: <code>SHOPAIKEY_ADMIN_ONLY must remain true</code>\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    if not SHOPAIKEY_API_KEY:
        save_tool_test_result("shopaikey", "MISSING", "SHOPAIKEY_API_KEY missing", uid)
        return await update.message.reply_text("🧪 <b>ShopAIKey Smoke Test</b>\n\n• Status: <code>MISSING</code>", parse_mode="HTML")
    tool_type = "shopaikey_chat"
    normalized_prompt = normalize_generation_prompt("shopaikey chat smoke test")
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        return await update.message.reply_text("⏳ Yêu cầu trước của bạn vẫn đang xử lý. Vui lòng chờ kết quả, không cần gửi lại.")
