def is_timeout_exception(exc: Exception) -> bool:
    text = f"{type(exc).__name__} {str(exc)}".lower()
    return "timeout" in text or "timedout" in text or "timed out" in text

async def send_shopaikey_tts_audio_with_retry(context: ContextTypes.DEFAULT_TYPE, chat_id: int, audio_bytes: bytes) -> tuple[bool, str, int]:
    attempts = [
        max(30, int(SHOPAIKEY_TTS_TELEGRAM_SEND_TIMEOUT_SECONDS or 60)),
        max(45, int(SHOPAIKEY_TTS_TELEGRAM_RETRY_TIMEOUT_SECONDS or 90)),
    ]
    last_error = ""
    for index, timeout_seconds in enumerate(attempts, start=1):
        audio = io.BytesIO(audio_bytes or b"")
        audio.name = "toan_aas_shopaikey_tts_test.mp3"
        try:
            await context.bot.send_audio(
                chat_id=chat_id,
                audio=audio,
                caption="🔊 ShopAIKey TTS audio test\nKhông trừ Xu.",
                read_timeout=timeout_seconds,
                write_timeout=timeout_seconds,
                connect_timeout=min(20, timeout_seconds),
                pool_timeout=min(20, timeout_seconds),
            )
            return True, "", index
        except Exception as e:
            last_error = sanitize_provider_error(e)
            if index == 1 and is_timeout_exception(e):
                logger.warning("Telegram send_audio timeout, retrying once.")
                await asyncio.sleep(1)
                continue
            return False, last_error, index
    return False, last_error, len(attempts)

async def cmd_tool_test_shopaikey_tts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    if not SHOPAIKEY_ENABLED:
        save_tool_test_result("shopaikey_tts", "DISABLED", "SHOPAIKEY_ENABLED=false; no call", uid)
        return await update.message.reply_text(
            "🔊 <b>ShopAIKey TTS Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Set <code>SHOPAIKEY_ENABLED=true</code> only for admin testing.\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    if not SHOPAIKEY_ADMIN_ONLY:
        save_tool_test_result("shopaikey_tts", "DISABLED", "SHOPAIKEY_ADMIN_ONLY=false unsafe; no call", uid)
        return await update.message.reply_text(
            "🔊 <b>ShopAIKey TTS Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Reason: <code>SHOPAIKEY_ADMIN_ONLY must remain true</code>\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    tool_type = "shopaikey_tts"
    normalized_prompt = normalize_generation_prompt("shopaikey tts smoke test")
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        return await update.message.reply_text("⏳ Yêu cầu trước của bạn vẫn đang xử lý. Vui lòng chờ kết quả, không cần gửi lại.")
    start_generation_pending_job(uid, tool_type, normalized_prompt, provider="shopaikey", xu_cost=0, command="/tool_test_shopaikey_tts")
    waiting_message = None
    provider_status = "FAIL_PROVIDER_ERROR"
    final_status = "FAIL_PROVIDER_ERROR"
    audio_bytes = b""
    detail = ""
    http_status = 0
    provider_ok = False
    audio_exists = False
    output_sent = False
    send_error = ""
    send_attempts = 0
    audio_bytes_len = 0
    error_class = "-"
    final_report_sent = False
    friendly_message = ""

    async def send_tts_smoke_final_report() -> None:
        nonlocal final_report_sent
        if final_report_sent:
            return
        final_report_sent = True
        if final_status == "PASS":
            await update.message.reply_text(
                "🔊 <b>ShopAIKey TTS Smoke Test — PASS</b>\n\n"
                f"HTTP: <code>{html.escape(str(http_status or 0))}</code>\n"
                f"Model: <code>{html.escape(SHOPAIKEY_TTS_MODEL or '-')}</code>\n"
                f"Voice: <code>{html.escape(SHOPAIKEY_TTS_VOICE or '-')}</code>\n"
                f"Bytes: <code>{audio_bytes_len}</code>\n"
                "Output sent: <code>yes</code>\n"
                f"Send attempts: <code>{send_attempts}</code>\n"
                "Không trừ Xu.",
                parse_mode="HTML",
            )
            return
        await update.message.reply_text(
            "🔊 <b>ShopAIKey TTS Smoke Test</b>\n\n"
            f"• Status: <code>{html.escape(final_status)}</code>\n"
            f"• HTTP: <code>{html.escape(str(http_status or 0))}</code>\n"
            f"• Model: <code>{html.escape(SHOPAIKEY_TTS_MODEL or '-')}</code>\n"
            f"• Voice: <code>{html.escape(SHOPAIKEY_TTS_VOICE or '-')}</code>\n"
            "• Output sent: <code>no</code>\n"
            f"• Bytes: <code>{audio_bytes_len}</code>\n"
            f"• Error class: <code>{html.escape(str(error_class or '-'))}</code>\n"
            f"• Friendly message: <b>{html.escape(friendly_message)}</b>\n\n"
            "Không log prompt/response/key. Không trừ Xu.",
            parse_mode="HTML",
        )

    try:
        waiting_message = await send_waiting_message(update, context, "tts")
        try:
            provider_status, audio_bytes, detail, http_status = await shopaikey_tts_smoke_test()
            provider_ok = provider_status == "PASS"
        except Exception as e:
            detail = sanitize_provider_error(e)
            provider_status = "FAIL_TIMEOUT" if "timeout" in type(e).__name__.lower() else "FAIL_PROVIDER_ERROR"
            http_status = 0
            provider_ok = False
        audio_exists = bool(audio_bytes)
        audio_bytes_len = len(audio_bytes or b"")
        if audio_exists:
            output_sent, send_error, send_attempts = await send_shopaikey_tts_audio_with_retry(context, update.effective_chat.id, audio_bytes)
        if output_sent:
            final_status = "PASS"
        elif audio_exists or provider_ok:
            final_status = "FAIL_SEND_AUDIO"
        else:
            final_status = provider_status or "FAIL_PROVIDER_ERROR"
        error_class = "-" if final_status == "PASS" else ("TELEGRAM_SEND_FAILED" if final_status == "FAIL_SEND_AUDIO" else classify_provider_error(http_status or 0, final_status, send_error or detail))
        final_detail = (
            f"provider_status={provider_status}; output_sent={'yes' if output_sent else 'no'}; "
            f"bytes={audio_bytes_len}; error_class={error_class}; send_attempts={send_attempts}; "
            f"detail={sanitize_log_text(str(send_error or detail or '-'))[:220]}"
        )
        tts_snapshot = {
            "status": final_status,
            "model": f"{SHOPAIKEY_TTS_MODEL or 'speech-2.6-turbo'}/{SHOPAIKEY_TTS_VOICE or 'male-qn-qingse'}",
            "http_status": int(http_status or 0),
            "latency_ms": 0,
        }
        save_tool_test_result("shopaikey_tts", final_status, final_detail, uid)
        save_shopaikey_component_snapshot("tts", tts_snapshot, final_detail, uid)
        record_api_debug("shopaikey", "tool_test_shopaikey_tts", final_status, int(http_status or 0), final_detail)
        if final_status != "PASS":
            record_provider_error(
                "shopaikey",
                "tts",
                error_class,
                final_detail,
            )
        try:
            await update_waiting_message(
                waiting_message,
                "✅ ShopAIKey TTS smoke test đã xử lý xong. Không trừ Xu." if final_status == "PASS" else "⚠️ ShopAIKey TTS smoke test chưa gửi được audio. Không trừ Xu.",
            )
        except Exception as e:
            logger.warning("shopaikey tts waiting message update skipped | output_sent=%s | %s", output_sent, sanitize_log_text(str(e))[:220])
        if final_status != "PASS":
            friendly_message = (
                "⚠️ TTS đã tạo audio nhưng Telegram gửi file thất bại. Bot chưa trừ Xu."
                if final_status == "FAIL_SEND_AUDIO"
                else USER_TTS_PROVIDER_BUSY_MESSAGE
            )
            await send_tts_smoke_final_report()
            finish_generation_pending_job(uid, tool_type, normalized_prompt, final_status)
            return
        await send_tts_smoke_final_report()
        finish_generation_pending_job(uid, tool_type, normalized_prompt, final_status)
        return
    except Exception as e:
        safe_error = sanitize_provider_error(e)
        logger.warning("shopaikey tts smoke handler safe failure | output_sent=%s | %s", output_sent, safe_error)
        if output_sent:
            final_status = "PASS"
            error_class = "-"
            finish_generation_pending_job(uid, tool_type, normalized_prompt, "PASS")
            try:
                await update_waiting_message(waiting_message, "✅ TTS đã tạo xong. Không trừ Xu.")
            except Exception:
                pass
            try:
                await send_tts_smoke_final_report()
            except Exception as report_error:
                logger.warning("shopaikey tts final PASS report skipped after audio send | %s", sanitize_log_text(str(report_error))[:220])
            return
        friendly_message = USER_TTS_PROVIDER_BUSY_MESSAGE
        error_class = classify_provider_error(http_status or 0, "FAIL_PROVIDER_ERROR", safe_error)
        finish_generation_pending_job(uid, tool_type, normalized_prompt, "FAIL_PROVIDER_ERROR")
        save_tool_test_result("shopaikey_tts", "FAIL_PROVIDER_ERROR", safe_error, uid)
        save_shopaikey_component_snapshot("tts", {"status": "FAIL_PROVIDER_ERROR", "model": f"{SHOPAIKEY_TTS_MODEL or 'speech-2.6-turbo'}/{SHOPAIKEY_TTS_VOICE or 'male-qn-qingse'}", "http_status": int(http_status or 0), "latency_ms": 0}, safe_error, uid)
        record_api_debug("shopaikey", "tool_test_shopaikey_tts", "FAIL_PROVIDER_ERROR", int(http_status or 0), safe_error)
        await send_tts_smoke_final_report()
        return

async def cmd_shopaikey_music_test(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    if not has_admin_paid_confirmation(context):
        save_tool_test_result("shopaikey_music", "NO_CONFIRM", f"missing {ADMIN_PAID_CONFIRM_FLAG}; no provider call", uid)
        return await update.message.reply_text(admin_paid_confirm_required_text("/shopaikey_music_test"), parse_mode="HTML")
    missing = []
    for name, ok in [
        ("MUSIC_AI_ENABLED", MUSIC_AI_ENABLED),
        ("SHOPAIKEY_ENABLED", SHOPAIKEY_ENABLED),
        ("SHOPAIKEY_MUSIC_ENABLED", SHOPAIKEY_MUSIC_ENABLED),
        ("SHOPAIKEY_API_KEY", bool(SHOPAIKEY_API_KEY)),
        ("SHOPAIKEY_MUSIC_ENDPOINT", bool(SHOPAIKEY_MUSIC_ENDPOINT)),
    ]:
        if not ok:
            missing.append(name)
    model = SHOPAIKEY_MUSIC_MODEL or "chirp-fenix"
    if missing:
        detail = "missing=" + ",".join(missing)
        save_tool_test_result("shopaikey_music", "DISABLED", detail, uid)
        return await update.message.reply_text(
            "🎼 <b>ShopAIKey Suno Music Smoke</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            f"• Model: <code>{html.escape(model)}</code>\n"
            f"• Missing: <code>{html.escape(', '.join(missing))}</code>\n\n"
            "Không gọi provider và không trừ Xu.",
            parse_mode="HTML",
        )
    prompt_text = " ".join(str(arg) for arg in args_without_admin_paid_confirmation(context.args or [])).strip()
    if not prompt_text:
        prompt_text = "Nhạc nền công nghệ xanh ngọc cho video TOAN AAS, hiện đại, sạch, tích cực, không lời"
    prompt_text = prompt_text[:500]
    body = shopaikey_suno_submit_payload(
        prompt_text,
        title="TOAN AAS Smoke Test",
        tags="cinematic, tech, uplifting",
        instrumental=True,
        model=model,
    )
    url = shopaikey_suno_final_url(SHOPAIKEY_MUSIC_ENDPOINT)
    http_status = 0
    status = "FAIL_PROVIDER_ERROR"
    task_id = ""
    provider_message = ""
    try:
        async with httpx.AsyncClient(timeout=60.0, follow_redirects=True) as client:
            res = await client.post(
                url,
                headers={
                    "Authorization": f"Bearer {SHOPAIKEY_API_KEY}",
                    "Content-Type": "application/json",
                },
                json=body,
            )
        http_status = int(res.status_code or 0)
        try:
            payload = res.json() if res.content else {}
        except Exception:
            payload = {}
        task_id = extract_shopaikey_suno_task_id(payload)
        provider_message = sanitize_provider_error(
            (payload.get("message") if isinstance(payload, dict) else "")
            or (payload.get("error", {}).get("message") if isinstance(payload, dict) and isinstance(payload.get("error"), dict) else "")
            or (res.text[:220] if not task_id else "")
        )
        code = str(payload.get("code") or "").lower() if isinstance(payload, dict) else ""
        status = "PASS_SUBMITTED" if 200 <= http_status < 300 and task_id and code in {"", "success", "ok"} else classify_provider_error(http_status, "FAIL_PROVIDER_ERROR", provider_message)
    except httpx.TimeoutException:
        status = "FAIL_TIMEOUT"
        provider_message = "request timeout"
    except Exception as exc:
        status = "FAIL_PROVIDER_ERROR"
        provider_message = sanitize_provider_error(exc)
    detail = f"http={http_status}; model={model}; task_id={'yes' if task_id else 'no'}; message={provider_message[:240]}"
    save_tool_test_result("shopaikey_music", status, detail, uid)
    record_api_debug("shopaikey", "tool_test_shopaikey_music", status, http_status, detail)
    lines = [
        "🎼 <b>ShopAIKey Suno Music Smoke</b>",
        "",
        f"• Status: <code>{html.escape(status)}</code>",
        f"• HTTP: <code>{http_status or '-'}</code>",
        f"• Model: <code>{html.escape(model)}</code>",
        f"• Submit endpoint: <code>{html.escape(SHOPAIKEY_MUSIC_ENDPOINT)}</code>",
        f"• Task ID: <code>{html.escape(task_id or '-')}</code>",
        f"• Provider message: <code>{html.escape(provider_message or '-')}</code>",
        "",
        "Không trừ Xu. Lưu ý: admin smoke có thể tốn provider credit thật.",
    ]
    if task_id:
        lines.append(f"Poll: <code>/shopaikey_music_job {html.escape(task_id)}</code>")
    else:
        lines.append("Không có task_id vì provider chưa nhận job; không chạy /shopaikey_music_job cho lần test này.")
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_shopaikey_music_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    task_id = str((context.args or [""])[0] or "").strip()[:120]
    if not task_id:
        return await update.message.reply_text("Cú pháp: /shopaikey_music_job <task_id>")
    try:
        from providers.key4u_provider import is_placeholder_task_id
        placeholder = is_placeholder_task_id(task_id)
    except Exception:
        lowered = task_id.lower()
        placeholder = bool(
            task_id.startswith("<")
            or lowered in {"task_id", "your_task_id", "abc", "abc123", "none", "null", "*"}
            or len(task_id) < 8
        )
    if placeholder:
        return await update.message.reply_text(
            "Vui lòng dùng task_id thật do /shopaikey_music_test trả về. "
            "Nếu lệnh tạo nhạc chưa submit thành công thì hiện chưa có task_id để query."
        )
    if not (SHOPAIKEY_ENABLED and SHOPAIKEY_MUSIC_ENABLED and SHOPAIKEY_API_KEY and SHOPAIKEY_MUSIC_STATUS_ENDPOINT):
        save_tool_test_result("shopaikey_music_job", "DISABLED", "missing status endpoint or credentials; no call", uid)
        return await update.message.reply_text(
            "🎼 <b>ShopAIKey Music Job</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Reason: <code>missing status endpoint or credentials</code>\n\n"
            "Không gọi provider và không trừ Xu.",
            parse_mode="HTML",
        )
    endpoint = shopaikey_suno_fetch_endpoint(task_id)
    url = shopaikey_suno_final_url(endpoint)
    http_status = 0
    status = "FAIL_PROVIDER_ERROR"
    progress = "-"
    audio_present = False
    video_present = False
    image_present = False
    fail_reason = ""
    try:
        async with httpx.AsyncClient(timeout=45.0, follow_redirects=True) as client:
            res = await client.get(url, headers={"Authorization": f"Bearer {SHOPAIKEY_API_KEY}"})
        http_status = int(res.status_code or 0)
        try:
            payload = res.json() if res.content else {}
        except Exception:
            payload = {}
        status = normalize_shopaikey_suno_fetch_status(payload, http_status)
        data = payload.get("data") if isinstance(payload, dict) else {}
        progress = str((data.get("progress") if isinstance(data, dict) else "") or (payload.get("progress") if isinstance(payload, dict) else "") or "-")
        fail_reason = sanitize_provider_error((data.get("fail_reason") if isinstance(data, dict) else "") or (payload.get("message") if isinstance(payload, dict) else "") or (payload.get("error") if isinstance(payload, dict) else "") or "")
        media = extract_shopaikey_suno_media_presence(payload)
        audio_present = bool(media.get("audio"))
        video_present = bool(media.get("video"))
        image_present = bool(media.get("image"))
    except httpx.TimeoutException:
        status = "FAIL_TIMEOUT"
        fail_reason = "request timeout"
    except Exception as exc:
        status = "FAIL_PROVIDER_ERROR"
        fail_reason = sanitize_provider_error(exc)
    smoke_status = "PASS_FULL_RESULT" if status == "SUCCESS" and audio_present else status
    detail = f"http={http_status}; status={smoke_status}; task_id={task_id[:24]}; audio={audio_present}; video={video_present}; message={fail_reason[:220]}"
    save_tool_test_result("shopaikey_music_job", smoke_status, detail, uid)
    record_api_debug("shopaikey", "shopaikey_music_job", smoke_status, http_status, detail)
    await update.message.reply_text(
        "🎼 <b>ShopAIKey Suno Music Job</b>\n\n"
        f"• Task ID: <code>{html.escape(task_id)}</code>\n"
        f"• HTTP: <code>{http_status or '-'}</code>\n"
        f"• Status: <code>{html.escape(smoke_status)}</code>\n"
        f"• Progress: <code>{html.escape(progress)}</code>\n"
        f"• Audio URL: <code>{'yes' if audio_present else 'no'}</code>\n"
        f"• Video URL: <code>{'yes' if video_present else 'no'}</code>\n"
        f"• Image URL: <code>{'yes' if image_present else 'no'}</code>\n"
        f"• Fail reason: <code>{html.escape(fail_reason or '-')}</code>\n\n"
        "Không trừ Xu. Không hiển thị API key/raw response.",
        parse_mode="HTML",
    )

