async def cmd_tool_test_shopaikey_video(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    lang = user_ui_lang(uid)
    if not has_admin_paid_confirmation(context):
        save_tool_test_result("shopaikey_video", "NO_CONFIRM", f"missing {ADMIN_PAID_CONFIRM_FLAG}; no provider call", uid)
        return await update.message.reply_text(admin_paid_confirm_required_text("/tool_test_shopaikey_video"), parse_mode="HTML")
    if not SHOPAIKEY_ENABLED:
        save_tool_test_result("shopaikey_video", "DISABLED", "SHOPAIKEY_ENABLED=false; no call", uid)
        return await update.message.reply_text(
            "🎞 <b>ShopAIKey Video Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Set <code>SHOPAIKEY_ENABLED=true</code> only for admin testing.\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    if not SHOPAIKEY_ADMIN_ONLY or not SHOPAIKEY_VIDEO_ADMIN_ONLY:
        save_tool_test_result("shopaikey_video", "DISABLED", "admin-only flag unsafe; no call", uid)
        return await update.message.reply_text(
            "🎞 <b>ShopAIKey Video Smoke Test</b>\n\n"
            "• Status: <code>DISABLED</code>\n"
            "• Reason: <code>SHOPAIKEY_ADMIN_ONLY and SHOPAIKEY_VIDEO_ADMIN_ONLY must remain true</code>\n\n"
            "Không gọi API và không trừ Xu.",
            parse_mode="HTML",
        )
    args = args_without_admin_paid_confirmation(context.args or [])
    model_override = str(args[0] or "").strip() if args else ""
    if model_override and not re.match(r"^[A-Za-z0-9_.:-]{2,120}$", model_override):
        return await update.message.reply_text("⚠️ Model không hợp lệ. Ví dụ: /tool_test_shopaikey_video veo3.1")
    test_models = shopaikey_video_model_sequence(model_override)
    active_job = shopaikey_active_job_for_user(uid, "video")
    if active_job:
        return await update.message.reply_text(
            shopaikey_active_video_admin_block_text(active_job, uid),
            parse_mode="HTML",
        )
    tool_type = "shopaikey_video"
    normalized_prompt = normalize_generation_prompt("shopaikey video smoke test " + ",".join(test_models))
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        return await update.message.reply_text("⏳ Yêu cầu trước của bạn vẫn đang xử lý. Vui lòng chờ kết quả, không cần gửi lại.")
    start_generation_pending_job(uid, tool_type, normalized_prompt, provider="shopaikey", xu_cost=0, command="/tool_test_shopaikey_video")
    smoke_prompt = shopaikey_video_smoke_prompt()
    job_id = create_shopaikey_job(
        uid,
        update.effective_chat.id,
        "video",
        model=test_models[0] if test_models else SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast",
        prompt=smoke_prompt,
        status="QUEUED",
        admin_only=True,
        xu_cost_planned=0,
    )
    waiting_message = await send_waiting_message(update, context, "video_submit") if SHOPAIKEY_VIDEO_WAITING_MESSAGE_ENABLED else None
    submit_result = await shopaikey_video_create_smoke_test(model_override)
    result = dict(submit_result or {})
    attempts = submit_result.get("attempts") or []
    task_id = str(submit_result.get("task_id") or "")
    if task_id:
        poll_result = await poll_shopaikey_video_smoke_job(task_id)
        lifecycle_status = str(poll_result.get("lifecycle_status") or "processing")
        if lifecycle_status == "succeeded":
            result.update(poll_result)
            result["status"] = "SUCCEEDED"
        elif lifecycle_status == "failed":
            result.update(poll_result)
            result["status"] = "FAILED"
        else:
            result.update({
                "status": "PROCESSING",
                "provider_status": poll_result.get("provider_status") or submit_result.get("provider_status") or "processing",
                "progress": poll_result.get("progress") or "",
                "lifecycle_status": "processing",
            })
            result["task_id"] = task_id
            result["model"] = submit_result.get("model") or result.get("model")
            result["selected_model"] = submit_result.get("selected_model") or result.get("model")
            result["attempts"] = attempts
    status = str(result.get("status") or "FAIL")
    attempt_text = shopaikey_video_attempts_summary(attempts)
    detail = (
        f"model={result.get('model') or SHOPAIKEY_VIDEO_MODEL}; http={result.get('http_status')}; "
        f"latency_ms={result.get('latency_ms')}; task_id={result.get('task_id') or '-'}; "
        f"provider_status={result.get('provider_status') or '-'}; "
        f"error_class={result.get('error_class') or '-'}; attempts={attempt_text}; "
        f"message={result.get('message') or result.get('detail') or '-'}"
    )
    save_tool_test_result("shopaikey_video", status, detail, uid)
    save_shopaikey_component_snapshot("video", result, detail, uid)
    record_api_debug("shopaikey", "tool_test_shopaikey_video", status, int(result.get("http_status") or 0), detail)
    if status not in {"PASS_SUBMITTED", "SUBMITTED", "PROCESSING", "SUCCEEDED"}:
        record_provider_error(
            "shopaikey",
            "video",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, result.get("message") or result.get("detail") or detail),
            result.get("message") or result.get("detail") or detail,
        )
    selected_model = str(result.get("selected_model") or "") if task_id else ""
    db_status = "SUCCESS" if status == "SUCCEEDED" else ("IN_PROGRESS" if status in {"PASS_SUBMITTED", "SUBMITTED", "PROCESSING"} and task_id else "FAILED")
    update_shopaikey_job(
        job_id=job_id,
        task_id=task_id,
        status=db_status,
        model=selected_model or result.get("model") or (test_models[0] if test_models else SHOPAIKEY_VIDEO_MODEL),
        error_class=result.get("error_class") or "",
        provider_error_code=result.get("provider_error_code") or "",
        provider_message=result.get("message") or result.get("detail") or "",
        attempts=len(attempts),
        result_url=result.get("result_url") or "",
        finished_at="" if db_status == "IN_PROGRESS" else now_text(),
    )
    update_generation_pending_job(uid, tool_type, normalized_prompt, task_id=task_id, status=status)
    await update_waiting_message(waiting_message, "✅ ShopAIKey video submit đã xử lý xong. Không trừ Xu.")
    output_sent = False
    if db_status == "SUCCESS" and result.get("result_url"):
        send_result = await send_shopaikey_video_result_once(
            context.bot,
            update.effective_chat.id,
            task_id,
            str(result.get("result_url") or ""),
            job_id=job_id,
            source="admin_video_smoke",
        )
        output_sent = bool(send_result.get("sent") or send_result.get("already_sent"))
        if output_sent:
            mark_shopaikey_video_output_confirmed(task_id, result.get("model") or selected_model or SHOPAIKEY_VIDEO_MODEL, uid, "tool_test_shopaikey_video")
    if task_id and db_status == "IN_PROGRESS" and SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED:
        asyncio.create_task(auto_poll_shopaikey_video_job(context.bot, job_id, update.effective_chat.id, uid, task_id))
    await safe_reply_text(
        update.message,
        "🎞 <b>ShopAIKey Video Smoke Test</b>\n\n"
        f"• Provider freeze: <code>{html.escape(shopaikey_admin_freeze_warning_text())}</code>\n"
        f"• Status: <code>{html.escape(status)}</code>\n"
        f"• HTTP: <code>{html.escape(str(result.get('http_status') or 0))}</code>\n"
        f"• Selected model: <code>{html.escape(selected_model or '-')}</code>\n"
        f"• Task ID: <code>{html.escape(task_id or '-')}</code>\n"
        f"• Provider status: <code>{html.escape(str(result.get('provider_status') or '-'))}</code>\n"
        f"• Lifecycle: <code>{html.escape(str(result.get('lifecycle_status') or ('succeeded' if status == 'SUCCEEDED' else 'submitted')))}</code>\n"
        f"• Output sent: <code>{'yes' if output_sent else 'no'}</code>\n"
        f"• Attempts: <code>{html.escape(attempt_text)}</code>\n"
        f"• Message: <code>{html.escape(str(result.get('message') or result.get('detail') or '-')[:220])}</code>\n"
        f"• Friendly message: <code>{html.escape(shopaikey_generation_unavailable_message(status, result.get('message') or result.get('detail') or '') if status != 'PASS_SUBMITTED' else '-')}</code>\n"
        f"• No Xu deducted: <code>yes</code>\n\n"
        + (f"Auto poll: <code>{'ON' if (db_status == 'IN_PROGRESS' and SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED) else 'OFF'}</code>\n" if task_id else "")
        + (f"Kiểm tra tiếp: <code>/shopaikey_video_job {html.escape(task_id)}</code>\n\n" if task_id else "")
        + "Endpoint admin-only. Smoke test có thể tốn credit thật của provider. Không log prompt/response/key. Public video do ENV/billing guard kiểm soát.",
        parse_mode="HTML",
        reply_markup=shopaikey_video_job_check_keyboard(task_id, lang) if task_id else None,
    )
    finish_generation_pending_job(uid, tool_type, normalized_prompt, status)
    return

async def cmd_shopaikey_video_job(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    uid = update.effective_user.id
    lang = user_ui_lang(uid)
    if not SHOPAIKEY_ADMIN_ONLY or not SHOPAIKEY_VIDEO_ADMIN_ONLY:
        return await update.message.reply_text("⛔ ShopAIKey video job status chỉ cho admin smoke test. Public video do ENV/billing guard kiểm soát.")
    if not context.args:
        return await update.message.reply_text("Cú pháp: /shopaikey_video_job <task_id>")
    task_id = str(context.args[0] or "").strip()
    tool_type = "shopaikey_video_job"
    normalized_prompt = normalize_generation_prompt(task_id)
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        return await update.message.reply_text("⏳ Yêu cầu trước của bạn vẫn đang xử lý. Vui lòng chờ kết quả, không cần gửi lại.")
    start_generation_pending_job(uid, tool_type, normalized_prompt, provider="shopaikey", xu_cost=0, command="/shopaikey_video_job")
    update_generation_pending_job(uid, tool_type, normalized_prompt, task_id=task_id)
    waiting_message = await send_waiting_message(update, context, "video")
    db_job = shopaikey_job_by_task_id(task_id)
    job_id = int((db_job or {}).get("id") or 0)
    if not job_id:
        job_id = create_shopaikey_job(
            uid,
            update.effective_chat.id,
            "video",
            model=SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast",
            prompt=f"manual poll {task_id}",
            status="IN_PROGRESS",
            admin_only=True,
            xu_cost_planned=0,
        )
        update_shopaikey_job(job_id=job_id, task_id=task_id)
        db_job = shopaikey_job_by_task_id(task_id)
    result = await shopaikey_video_job_status(task_id)
    status = str(result.get("status") or "FAIL")
    result_url = str(result.get("result_url") or "")
    output_sent = False
    already_sent = bool(int((db_job or {}).get("result_sent") or 0))
    if result_url:
        if already_sent:
            output_sent = True
        elif bool(int((db_job or {}).get("admin_only") or 0)):
            send_result = await send_shopaikey_video_result_once(
                context.bot,
                update.effective_chat.id,
                task_id,
                result_url,
                job_id=job_id,
                source="admin_video_job_status",
            )
            output_sent = bool(send_result.get("sent") or send_result.get("already_sent"))
    if result_url and (output_sent or already_sent):
        mark_shopaikey_video_output_confirmed(task_id, (db_job or {}).get("model") or SHOPAIKEY_VIDEO_MODEL, uid, "shopaikey_video_job")
    normalized_db_status = shopaikey_db_video_status(status)
    detail = (
        f"http={result.get('http_status')}; task_id={task_id}; provider_status={result.get('provider_status') or '-'}; "
        f"progress={result.get('progress') or '-'}; result_url={'yes' if result_url else 'no'}; "
        f"output_sent={'yes' if output_sent else 'no'}; already_sent={'yes' if already_sent else 'no'}; fail_reason={result.get('fail_reason') or '-'}; "
        f"error_class={result.get('error_class') or '-'}"
    )
    snapshot_payload = {
        "status": status,
        "model": SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast",
        "http_status": int(result.get("http_status") or 0),
        "latency_ms": int(result.get("latency_ms") or 0),
    }
    save_tool_test_result("shopaikey_video", status, detail, uid)
    save_shopaikey_component_snapshot("video", snapshot_payload, detail, uid)
    record_api_debug("shopaikey", "shopaikey_video_job", status, int(result.get("http_status") or 0), detail)
    if shopaikey_db_video_status(status) in {"FAILED", "TIMEOUT"}:
        record_provider_error(
            "shopaikey",
            "video",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, result.get("fail_reason") or result.get("detail") or detail),
            result.get("fail_reason") or result.get("detail") or detail,
        )
    update_shopaikey_job(
        job_id=job_id,
        task_id=task_id,
        status=normalized_db_status,
        result_url=result_url,
        result_sent=1 if output_sent else 0,
        error_class=result.get("error_class") or "",
        provider_error_code=result.get("provider_error_code") or "",
        provider_message=result.get("detail") or "",
        fail_reason=result.get("fail_reason") or "",
        poll_count=int((db_job or {}).get("poll_count") or 0) + 1,
        finished_at=now_text() if normalized_db_status in {"SUCCESS", "FAILED", "TIMEOUT"} else "",
    )
    update_generation_pending_job(uid, tool_type, normalized_prompt, task_id=task_id, status=status)
    await update_waiting_message(waiting_message, "✅ ShopAIKey video job đã cập nhật xong. Không trừ Xu.")
    completed = bool(result_url)
    result_line = f"• Result URL: <a href=\"{html.escape(result_url, quote=True)}\">open</a>\n" if completed else ""
    sent_note = "already sent" if already_sent else ("yes" if output_sent else "no")
    response_text = (
        "🎞 <b>ShopAIKey Video Job</b>\n\n"
        f"• Task ID: <code>{html.escape(str(result.get('task_id') or task_id or '-'))}</code>\n"
        f"• Status: <code>{html.escape(status)}</code>\n"
        f"• HTTP: <code>{html.escape(str(result.get('http_status') or 0))}</code>\n"
        f"• Provider status: <code>{html.escape(str(result.get('provider_status') or '-'))}</code>\n"
        f"• Progress: <code>{html.escape(str(result.get('progress') or '-'))}</code>\n"
        + result_line
        + f"• Output sent: <code>{html.escape(sent_note)}</code>\n"
        f"• Fail reason: <code>{html.escape(str(result.get('fail_reason') or '-')[:220])}</code>\n"
        f"• No Xu deducted: <code>yes</code>\n\n"
        "Admin-only. Public video do ENV/billing guard kiểm soát. Không hiển thị API key."
    )
    await safe_reply_text(
        update.message,
        response_text,
        parse_mode="HTML",
        disable_web_page_preview=False,
        reply_markup=shopaikey_video_job_check_keyboard(task_id, lang, resend=bool(result_url and not (output_sent or already_sent))),
    )
    finish_generation_pending_job(uid, tool_type, normalized_prompt, status)
    return

def shopaikey_video_job_check_keyboard(task_id: str, lang: str = "vi", resend: bool = False, public_user: bool = False) -> InlineKeyboardMarkup | None:
    safe_task_id = str(task_id or "").strip()
    callback_data = f"shopai_video_job|{safe_task_id}"
    if not safe_task_id or len(callback_data.encode("utf-8")) > 64:
        return None
    status_callback = f"shopai_video_job|status|{safe_task_id}"
    rows = [[InlineKeyboardButton(ui_text(lang, "video.resend") if resend else ui_text(lang, "video.check_job"), callback_data=callback_data)]]
    if not public_user and len(status_callback.encode("utf-8")) <= 64:
        rows.append([InlineKeyboardButton("🧾 Xem trạng thái ShopAIKey" if normalize_user_language(lang) == "vi" else "🧾 ShopAIKey status", callback_data=status_callback)])
    rows.append([InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="shopai_video_job|main")])
    return InlineKeyboardMarkup(rows)

async def handle_shopaikey_video_job_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    await query.answer()
    uid = query.from_user.id if query.from_user else 0
    lang = user_ui_lang(uid)
    raw_parts = (query.data or "").split("|")
    if len(raw_parts) >= 2 and raw_parts[1] == "main":
        return await safe_edit_or_send(
            query,
            localized_start_menu_text(uid, lang),
            parse_mode="HTML",
            reply_markup=localized_main_menu_keyboard(is_admin_user(uid), lang),
        )
    if len(raw_parts) >= 3 and raw_parts[1] == "retry":
        return await handle_public_video_retry_callback(query, uid, raw_parts[2], lang)
    completed_addon_kind = {
        "av": "voice",
        "am": "music",
        "as": "subtitle",
        "fb": "feedback",
        "addon_voice": "voice",
        "addon_music": "music",
        "addon_subtitle": "subtitle",
        "feedback": "feedback",
    }.get(raw_parts[1] if len(raw_parts) >= 2 else "")
    if len(raw_parts) >= 3 and completed_addon_kind:
        task_id = str(raw_parts[2] or "").strip()
        db_job = shopaikey_job_by_task_id(task_id)
        if (
            not db_job
            or str(db_job.get("user_id") or "") != str(uid)
            or bool(int(db_job.get("admin_only") or 0))
        ):
            return await safe_edit_or_send(
                query,
                "⚠️ Không tìm thấy kết quả video của bạn. TOAN AAS chưa gọi API mới và chưa trừ thêm Xu.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="shopai_video_job|main")]]),
            )
        job_id = int(db_job.get("id") or 0)
        video_session_id = str((get_video_finalization_state(uid) or {}).get("session_id") or "")[:80]
        if completed_addon_kind == "feedback":
            context_note = f"task_id={task_id}; job_id={job_id}; video_session_id={video_session_id or '-'}"
            set_feedback_pending(uid, "video_error", context_note=context_note)
            _safe_set_video_system_setting("video_completed_addon_last_job", f"feedback:{context_note}", "completed video feedback")
            _safe_set_video_system_setting("video_completed_addon_last_error", "", "completed video feedback")
            return await safe_edit_or_send(
                query,
                "💬 Bạn hãy gửi góp ý hoặc chấm điểm kết quả video này. TOAN AAS chỉ lưu phản hồi để admin kiểm tra, chưa gọi provider và chưa trừ Xu.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Menu chính", callback_data="shopai_video_job|main")]]),
            )
        guard_text = VIDEO_COMPLETED_ADDON_GUARD_TEXTS.get(completed_addon_kind) or VIDEO_COMPLETED_ADDON_GUARD_TEXTS["subtitle"]
        _safe_set_video_system_setting(
            "video_completed_addon_last_job",
            f"{completed_addon_kind}:task_id={task_id};job_id={job_id};video_session_id={video_session_id or '-'}",
            "completed video addon guard",
        )
        _safe_set_video_system_setting("video_completed_addon_last_error", "maintenance_guard", "completed video addon guard")
        return await safe_edit_or_send(
            query,
            guard_text,
            reply_markup=public_video_success_keyboard(public_video_job_tier(db_job), lang, task_id=task_id),
        )
    if len(raw_parts) >= 3 and raw_parts[1] == "resend":
        task_id = str(raw_parts[2] or "").strip()
        db_job = shopaikey_job_by_task_id(task_id)
        if (
            not db_job
            or str(db_job.get("user_id") or "") != str(uid)
            or bool(int(db_job.get("admin_only") or 0))
        ):
            return await safe_edit_or_send(
                query,
                "⚠️ Không tìm thấy kết quả video của bạn. TOAN AAS chưa gọi API mới và chưa trừ thêm Xu.",
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="shopai_video_job|main")]]),
            )
        result_url = str(db_job.get("output_sent_result_url") or db_job.get("result_url") or "").strip()
        if not result_url or shopaikey_db_video_status(db_job.get("status") or "") != "SUCCESS":
            return await safe_edit_or_send(
                query,
                "⏳ Kết quả video chưa sẵn sàng để gửi lại. Bạn có thể kiểm tra trạng thái sau.",
                reply_markup=shopaikey_video_job_check_keyboard(task_id, lang, public_user=True),
            )
        resend = await send_shopaikey_video_result_once(
            context.bot,
            query.message.chat_id,
            task_id,
            result_url,
            job_id=int(db_job.get("id") or 0),
            source="explicit_public_resend",
            explicit_resend=True,
        )
        if not resend.get("sent"):
            return await safe_edit_or_send(
                query,
                "🛠 Kết quả đang được gửi lại nhưng Telegram chưa nhận được file. Xin vui lòng thử lại sau. TOAN AAS chưa trừ thêm Xu.",
                reply_markup=public_video_success_keyboard(public_video_job_tier(db_job), lang, task_id=task_id),
            )
        return await safe_edit_or_send(
            query,
            public_video_status_message("SUCCESS", output_sent=True, job=db_job, lang=lang),
            parse_mode="HTML",
            reply_markup=public_video_success_keyboard(public_video_job_tier(db_job), lang, task_id=task_id),
        )
    if len(raw_parts) >= 2 and raw_parts[1] == "status":
        if not is_admin_user(uid):
            status_detail_text = (
                "⚠️ Technical details are not shown in the public video flow. Please use the video status button for your own request."
                if normalize_user_language(lang) != "vi" else
                "⚠️ Chi tiết kỹ thuật không hiển thị ở giao diện công khai. Bạn hãy dùng nút kiểm tra trạng thái video của yêu cầu của mình."
            )
            if normalize_user_language(lang) == "zh":
                status_detail_text = "⚠️ 技术细节不会显示在公开视频流程中。请使用视频状态按钮查看自己的请求。"
            return await safe_edit_or_send(
                query,
                status_detail_text,
                reply_markup=shopaikey_video_job_check_keyboard(raw_parts[2] if len(raw_parts) >= 3 else "", lang, public_user=True),
            )
        return await safe_edit_or_send(
            query,
            "🧪 <b>ShopAIKey Status</b>\n\n"
            f"• Chat: <code>{html.escape(shopaikey_chat_status_text())}</code>\n"
            f"• TTS: <code>{html.escape(shopaikey_tts_status_text())}</code>\n"
            f"• Image: <code>{html.escape(shopaikey_image_status_text())}</code>\n"
            f"• Video: <code>{html.escape(shopaikey_video_status_text())}</code>\n"
            f"• Public video: <code>{'ON' if SHOPAIKEY_PUBLIC_VIDEO_ENABLED else 'OFF'}</code>\n"
            "• No Xu deducted: <code>yes</code>",
            parse_mode="HTML",
            reply_markup=shopaikey_video_job_check_keyboard(raw_parts[2] if len(raw_parts) >= 3 else "", lang),
        )
    task_id = str(raw_parts[1] if len(raw_parts) >= 2 else "").strip()
    db_job = shopaikey_job_by_task_id(task_id)
    job_id = int((db_job or {}).get("id") or 0)
    if not is_admin_user(uid):
        if not db_job or str((db_job or {}).get("user_id") or "") != str(uid) or bool(int((db_job or {}).get("admin_only") or 0)):
            not_found_text = (
                "⚠️ Video request was not found for your account or has expired. TOAN AAS has not started a new request and has not charged extra Xu."
                if normalize_user_language(lang) != "vi" else
                "⚠️ Không tìm thấy yêu cầu video của bạn hoặc yêu cầu đã hết hạn. TOAN AAS chưa tạo yêu cầu mới và chưa trừ thêm Xu."
            )
            if normalize_user_language(lang) == "zh":
                not_found_text = "⚠️ 未找到属于你的视频请求，或请求已过期。TOAN AAS 未创建新的请求，也未额外扣除 Xu。"
            return await safe_edit_or_send(
                query,
                not_found_text,
                reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="shopai_video_job|main")]]),
            )
    result = await shopaikey_video_job_status(task_id)
    status = str(result.get("status") or "FAIL")
    db_status = shopaikey_db_video_status(status)
    result_url = str(result.get("result_url") or "")
    output_sent = False
    already_sent = bool(int((db_job or {}).get("result_sent") or 0))
    callback_may_deliver_result = not is_admin_user(uid) or bool(int((db_job or {}).get("admin_only") or 0))
    if result_url and query.message and callback_may_deliver_result:
        send_result = await send_shopaikey_video_result_once(
            context.bot,
            query.message.chat_id,
            task_id,
            result_url,
            job_id=job_id,
            source="public_status_check",
        )
        output_sent = bool(send_result.get("sent"))
        already_sent = bool(already_sent or send_result.get("already_sent") or send_result.get("duplicate_prevented"))
    previous_db_status = shopaikey_db_video_status((db_job or {}).get("status") or "")
    if db_status in {"FAILED", "TIMEOUT"} and previous_db_status not in {"FAILED", "TIMEOUT"}:
        record_provider_error(
            "shopaikey",
            "video",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, result.get("fail_reason") or result.get("detail") or status),
            result.get("fail_reason") or result.get("detail") or status,
        )
    if job_id:
        update_shopaikey_job(
            job_id=job_id,
            task_id=task_id,
            status=db_status,
            result_url=result_url,
            result_sent=1 if (output_sent or already_sent) else 0,
            error_class=result.get("error_class") or "",
            provider_error_code=result.get("provider_error_code") or "",
            provider_message=result.get("detail") or "",
            fail_reason=result.get("fail_reason") or "",
            poll_count=int((db_job or {}).get("poll_count") or 0) + 1,
            finished_at=now_text() if db_status in {"SUCCESS", "FAILED", "TIMEOUT"} else "",
        )
    if not is_admin_user(uid):
        latest_job = shopaikey_job_by_id(job_id) if job_id else db_job
        fail_summary = {}
        if db_status in {"FAILED", "TIMEOUT"}:
            fail_summary = finalize_public_video_terminal_failure(latest_job or db_job or {}, result, db_status)
            latest_job = shopaikey_job_by_id(job_id) if job_id else latest_job
        public_text = public_video_status_message(
            status,
            progress=str(result.get("progress") or "-"),
            output_sent=bool(already_sent or output_sent),
            job=latest_job or db_job or {},
            fail_summary=fail_summary,
            lang=lang,
        )
        return await safe_edit_or_send(
            query,
            public_text,
            parse_mode="HTML",
            reply_markup=public_video_status_keyboard(task_id, latest_job or db_job or {}, db_status, lang, output_sent=bool(already_sent or output_sent)),
        )
    result_line = f"• Result: <a href=\"{html.escape(result_url, quote=True)}\">open</a>\n" if result_url else ""
    sent_note = "already sent" if already_sent else ("yes" if output_sent else "no")
    resend_needed = bool(result_url and not (output_sent or already_sent))
    response_text = (
        "🎞 <b>ShopAIKey Video Job</b>\n\n"
        f"• Task ID: <code>{html.escape(task_id or '-')}</code>\n"
        f"• Status: <code>{html.escape(status)}</code>\n"
        f"• HTTP: <code>{html.escape(str(result.get('http_status') or 0))}</code>\n"
        f"• Provider status: <code>{html.escape(str(result.get('provider_status') or '-'))}</code>\n"
        f"• Progress: <code>{html.escape(str(result.get('progress') or '-'))}</code>\n"
        + result_line
        + f"• Output sent: <code>{html.escape(sent_note)}</code>\n"
        f"• No Xu deducted: <code>yes</code>\n\n"
        "Admin-only. Public video do ENV/billing guard kiểm soát."
    )
    try:
        return await safe_edit_or_send(
            query,
            response_text,
            reply_markup=shopaikey_video_job_check_keyboard(task_id, lang, resend=resend_needed),
        )
    except Exception as e:
        logger.warning("shopaikey video job callback status reply failed | %s", sanitize_log_text(str(e))[:240])
        return await safe_reply_text(
            getattr(query, "message", None),
            response_text,
            parse_mode="HTML",
            reply_markup=shopaikey_video_job_check_keyboard(task_id, lang, resend=resend_needed),
        )

def shopaikey_public_prompt_from_args(context: ContextTypes.DEFAULT_TYPE) -> str:
    return " ".join(context.args or []).strip()

async def cmd_shopaikey_image_public(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    prompt = shopaikey_public_prompt_from_args(context)
    if not prompt:
        return await update.message.reply_text("⚠️ Cú pháp: /shopaikey_image <mô tả ảnh>")
    enabled, message = shopaikey_public_generation_guard("image")
    if not enabled:
        return await update.message.reply_text(f"{message}\nBot chưa trừ Xu.")
    if shopaikey_active_job_for_user(uid, "image"):
        return await update.message.reply_text(USER_JOB_LOCK_MESSAGE)
    credits, _, _ = get_user(uid, update.effective_user.first_name or update.effective_user.username or "Unknown")
    tier = normalize_image_tier(SHOPAIKEY_IMAGE_DEFAULT_TIER)
    tier_payload = image_tier_payload(tier)
    base_cost = int(tier_payload.get("cost") or image_base_cost_xu())
    final_preview_cost = shopaikey_preview_final_cost(uid, base_cost, "shopaikey_image")
    if int(credits or 0) < final_preview_cost and not is_admin_user(uid):
        record_shopaikey_billing_event(uid, 0, "insufficient_balance", 0, int(credits or 0), int(credits or 0), f"shopaikey_image; tier={tier}; required={final_preview_cost}")
        return await reply_insufficient_credits(update, int(credits or 0), final_preview_cost)
    lang = user_ui_lang(uid)
    set_media_aspect_pending(
        uid,
        "image",
        tier,
        prompt,
        logo_watermark_back_callback="create_media|quick_image",
        confirmation_source="shopaikey_image_command",
    )
    await update.message.reply_text(
        media_logo_watermark_choice_text("image", prompt, lang),
        parse_mode="HTML",
        reply_markup=media_logo_watermark_choice_keyboard("image", lang, "create_media|quick_image"),
    )

async def start_public_image_prompt_from_tier_message(message, user_id, tier: str) -> None:
    payload = image_tier_payload(tier)
    lang = user_ui_lang(user_id)
    if not payload.get("enabled"):
        return await message.reply_text(ui_text(lang, "image.tier_disabled_message"))
    if not SHOPAIKEY_PUBLIC_IMAGE_ENABLED:
        return await message.reply_text(ui_text(lang, "media.public_off"))
    if shopaikey_active_job_for_user(user_id, "image"):
        return await message.reply_text(ui_text(lang, "media.job_lock"))
    set_public_image_prompt_pending(user_id, payload["tier"])
    await message.reply_text(public_image_prompt_request_text(payload["tier"], lang), parse_mode="HTML")

async def handle_public_image_prompt_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_public_image_prompt_pending(uid)
    if not pending:
        return False
    prompt = re.sub(r"\s+", " ", update.message.text.strip())
    if not prompt:
        return False
    clear_public_image_prompt_pending(uid)
    lang = get_user_language(uid) or "vi"
    tier = normalize_image_tier(pending.get("tier") or SHOPAIKEY_IMAGE_DEFAULT_TIER)
    payload = image_tier_payload(tier)
    if not payload.get("enabled"):
        await update.message.reply_text(ui_text(lang, "image.tier_disabled_message"))
        return True
    enabled, message = shopaikey_public_generation_guard("image")
    if not enabled:
        await update.message.reply_text(ui_text(lang, "media.public_off"))
        return True
    if shopaikey_active_job_for_user(uid, "image"):
        await update.message.reply_text(ui_text(lang, "media.job_lock"))
        return True
    prompt_back_callback = f"create_media|image_tier_{tier}"
    set_media_aspect_pending(
        uid,
        "image",
        tier,
        prompt,
        logo_watermark_back_callback=prompt_back_callback,
        confirmation_source="public_image_prompt",
    )
    await update.message.reply_text(
        media_logo_watermark_choice_text("image", prompt, lang),
        parse_mode="HTML",
        reply_markup=media_logo_watermark_choice_keyboard("image", lang, prompt_back_callback),
    )
    return True

async def handle_media_logo_watermark_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_media_aspect_pending(uid) or {}
    if str(pending.get("logo_watermark_step") or "") != "input":
        return False
    text = logo_watermark_clean_text(update.message.text)
    if not text:
        return True
    lang = get_user_language(uid) or "vi"
    kind = "image" if pending.get("job_type") == "image" else "video"
    update_media_aspect_pending(
        uid,
        logo_watermark_enabled=True,
        logo_watermark_text=text,
        logo_watermark_position="bottom_right",
        logo_watermark_source="text",
        logo_watermark_step="position",
    )
    await update.message.reply_text(
        media_logo_watermark_position_text(text, lang),
        parse_mode="HTML",
        reply_markup=media_logo_watermark_position_keyboard(kind, lang, f"{'image' if kind == 'image' else 'video'}_logo_pos", f"create_media|{'image' if kind == 'image' else 'video'}_logo_add"),
    )
    return True

def image_prompt_confirm_keyboard(
    token: str,
    tier: str,
    lang: str = "vi",
    source: str = "image_prompt_tool",
) -> InlineKeyboardMarkup:
    vi = normalize_user_language(lang) == "vi"
    is_image_edit = str(source or "") == "image_edit_create_new"
    change_ratio_callback = (
        f"create_media|ia_{token}" if is_image_edit else f"imgtool|prompt_confirm_change|{token}"
    )
    back_callback = "imgtool|edit_create_new" if is_image_edit else "imgtool|prompt_back_result"
    back_label = (
        "⬅️ Về tạo ảnh mới" if vi and is_image_edit
        else "⬅️ Quay lại prompt" if vi
        else "⬅️ Back to create image" if is_image_edit
        else "⬅️ Back to prompt"
    )
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(ui_text(lang, "common.confirm"), callback_data=f"shopai|confirm|{token}")],
        [InlineKeyboardButton("📐 Đổi tỉ lệ" if vi else "📐 Change ratio", callback_data=change_ratio_callback)],
        [InlineKeyboardButton(back_label, callback_data=back_callback)],
        [InlineKeyboardButton(ui_text(lang, "common.cancel"), callback_data=f"shopai|cancel|{token}")],
        [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ])

async def show_image_prompt_confirmation(query, uid, tier: str, prompt: str, aspect_ratio: str, lang: str = "vi", source: str = "image_prompt_tool"):
    tier = normalize_image_tier(tier or SHOPAIKEY_IMAGE_DEFAULT_TIER)
    aspect = normalize_media_aspect_ratio(aspect_ratio, "1:1", "image")
    payload = image_tier_payload(tier)
    if not payload.get("enabled"):
        return await safe_edit_query_message(query, ui_text(lang, "image.tier_disabled_message"))
    enabled, _message = shopaikey_public_generation_guard("image")
    if not enabled:
        return await safe_edit_query_message(query, ui_text(lang, "media.public_off"))
    if shopaikey_active_job_for_user(uid, "image"):
        return await safe_edit_query_message(query, image_action_locked_text(lang))
    credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Image prompt user")
    base_cost = int(payload.get("cost") or 0)
    final_preview_cost = shopaikey_preview_final_cost(uid, base_cost, "shopaikey_image")
    package_item_type = package_item_type_for_image_tier(tier)
    package_item = active_package_item_for_user(uid, package_item_type)
    if int(credits or 0) < final_preview_cost and not is_admin_user(uid) and not package_item:
        return await edit_insufficient_credits(query, int(credits or 0), final_preview_cost, uid)
    logo_pending = get_media_aspect_pending(uid, "image") or {}
    logo_text = logo_watermark_clean_text(
        logo_pending.get("logo_watermark_text") if logo_pending.get("logo_watermark_enabled") else ""
    )
    logo_position = logo_watermark_normalize_position(
        logo_pending.get("logo_watermark_position") or "",
        "bottom_right",
    )
    generation_prompt = image_tier_prompt_for_generation(prompt, tier, aspect)
    generation_prompt = apply_logo_watermark_to_prompt(
        generation_prompt,
        logo_text,
        "image",
        logo_position,
    )
    token = set_shopaikey_pending_confirmation(uid, {
        "job_type": "image",
        "prompt": generation_prompt,
        "original_prompt": prompt,
        "base_cost": base_cost,
        "from_image": False,
        "image_tier": tier,
        "tier_label": payload.get("label") or tier,
        "model": payload.get("model") or SHOPAIKEY_IMAGE_MODEL or "nano-banana",
        "retry_warranty_count": int(payload.get("retry_warranty_count") or 0),
        "aspect_ratio": aspect,
        "package_item_type": package_item_type,
        "source": source,
        **logo_watermark_session_fields(bool(logo_text), logo_text, logo_position),
    })
    confirm_text = public_image_confirm_text(
        tier,
        prompt,
        int(credits or 0),
        lang,
        aspect,
        logo_text,
        logo_position,
    )
    confirm_markup = image_prompt_confirm_keyboard(token, tier, lang, source)
    if package_item:
        confirm_text = package_offer_text(package_item, confirm_text, lang)
        confirm_markup = package_use_choice_keyboard(
            "image",
            token,
            tier,
            lang,
            "imgtool|edit_create_new" if source == "image_edit_create_new" else "imgtool|prompt_back_result",
        )
    return await safe_edit_query_message(
        query,
        confirm_text,
        parse_mode="HTML",
        reply_markup=confirm_markup,
    )

async def handle_image_tools_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id
    lang = get_user_language(uid) or "vi"
    parts = str(query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else ""
    pending = get_image_menu_pending(uid) or {}

    if action == "editor_start":
        mode = parts[2] if len(parts) > 2 else "auto"
        source = recent_image_file_state(uid)
        if not source.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode=mode)
            return await safe_edit_query_message(query, image_editor_start_text(mode, lang), reply_markup=image_editor_start_keyboard(lang))
        state = {**source, "editor_mode": mode}
        set_image_menu_pending(uid, "image_editor_menu", **state)
        if mode == "auto":
            return await send_local_edited_image(update, context, state, preset="photo_clear_detail")
        if mode == "upscale":
            return await send_local_edited_image(update, context, state, preset="photo_clear_detail", upscale=True)
        if mode == "overlay":
            return await safe_edit_query_message(query, "🔠 Chọn thêm chữ hoặc Logo/Watermark. Bot chưa trừ Xu.", parse_mode=None, reply_markup=image_editor_overlay_keyboard(lang))
        return await safe_edit_query_message(query, "🎨 Chọn công thức màu local để xem preview.", parse_mode=None, reply_markup=image_editor_preset_keyboard(lang))
    if action == "editor_presets":
        return await safe_edit_query_message(query, "🎨 Chọn công thức màu local để xem preview.", parse_mode=None, reply_markup=image_editor_preset_keyboard(lang))
    if action == "editor_overlays":
        return await safe_edit_query_message(query, "🔠 Chọn thêm chữ hoặc Logo/Watermark. Bot chưa trừ Xu.", parse_mode=None, reply_markup=image_editor_overlay_keyboard(lang))
    if action == "editor_resize":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="resize")
            return await safe_edit_query_message(query, image_editor_start_text("resize", lang), reply_markup=image_editor_start_keyboard(lang))
        set_image_menu_pending(uid, "image_resize_choice", **state)
        return await safe_edit_query_message(query, image_resize_ratio_text(lang), reply_markup=image_resize_ratio_keyboard(False, lang))
    if action == "editor_upscale":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="upscale")
            return await safe_edit_query_message(query, image_editor_start_text("upscale", lang), reply_markup=image_editor_start_keyboard(lang))
        return await send_local_edited_image(update, context, state, preset="photo_clear_detail", upscale=True)
    if action == "editor_preset":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="preset")
            return await safe_edit_query_message(query, image_editor_start_text("preset", lang), reply_markup=image_editor_start_keyboard(lang))
        preset = parts[2] if len(parts) > 2 else "photo_clear_detail"
        return await send_local_edited_image(update, context, state, preset=preset)
    if action == "editor_custom":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="preset")
            return await safe_edit_query_message(query, image_editor_start_text("preset", lang), reply_markup=image_editor_start_keyboard(lang))
        set_image_menu_pending(uid, "image_editor_custom_settings", **state)
        return await safe_edit_query_message(
            query,
            "🎚 Nhập thông số theo mẫu:\nbrightness=1.05 contrast=1.10 saturation=1.08 sharpness=1.20\n\nMỗi giá trị từ 0.5 đến 2.0. Bot chưa trừ Xu.",
            parse_mode=None,
            reply_markup=image_editor_start_keyboard(lang),
        )
    if action in {"editor_text", "editor_text_menu", "editor_text_overlay"}:
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="text", editor_source=action)
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        back_callback = image_editor_origin_back_callback(action, "text")
        set_image_menu_pending(uid, "image_editor_text_input", **{**state, "back_to": back_callback, "editor_source": action, "editor_overlay_text": ""})
        return await safe_edit_query_message(
            query,
            image_editor_overlay_input_prompt("text", lang),
            parse_mode="HTML",
            reply_markup=image_editor_text_input_keyboard(lang, back_callback),
        )
    if action in {"editor_logo", "editor_logo_menu", "editor_logo_overlay"}:
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="logo", editor_source=action)
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        back_callback = image_editor_origin_back_callback(action, "logo")
        set_image_menu_pending(uid, "image_editor_logo_input", **{**state, "back_to": back_callback, "editor_source": action, "editor_logo_text": ""})
        return await safe_edit_query_message(
            query,
            image_editor_overlay_input_prompt("logo", lang),
            parse_mode="HTML",
            reply_markup=image_editor_text_input_keyboard(lang, back_callback),
        )
    if action in {"editor_text_input_back", "editor_logo_input_back"}:
        kind = "logo" if action == "editor_logo_input_back" else "text"
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode=kind)
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        origin_action = str(state.get("editor_source") or ("editor_logo" if kind == "logo" else "editor_text"))
        back_callback = str(state.get("back_to") or image_editor_origin_back_callback(origin_action, kind))
        current_text = state.get("editor_logo_text") if kind == "logo" else state.get("editor_overlay_text")
        set_image_menu_pending(uid, f"image_editor_{kind}_input", **{**state, "back_to": back_callback, "editor_source": origin_action})
        return await safe_edit_query_message(
            query,
            image_editor_overlay_input_prompt(kind, lang, str(current_text or "")),
            parse_mode="HTML",
            reply_markup=image_editor_text_input_keyboard(lang, back_callback),
        )
    if action in {"editor_text_position_back", "editor_logo_position_back"}:
        kind = "logo" if action == "editor_logo_position_back" else "text"
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode=kind)
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        text_value = _short_pending_text(state.get("editor_logo_text") if kind == "logo" else state.get("editor_overlay_text"), 260)
        if not text_value:
            origin_action = str(state.get("editor_source") or ("editor_logo" if kind == "logo" else "editor_text"))
            back_callback = str(state.get("back_to") or image_editor_origin_back_callback(origin_action, kind))
            set_image_menu_pending(uid, f"image_editor_{kind}_input", **{**state, "back_to": back_callback, "editor_source": origin_action})
            return await safe_edit_query_message(
                query,
                image_editor_overlay_input_prompt(kind, lang),
                parse_mode="HTML",
                reply_markup=image_editor_text_input_keyboard(lang, back_callback),
            )
        set_image_menu_pending(uid, f"image_editor_{kind}_position", **state)
        return await safe_edit_query_message(
            query,
            image_editor_position_prompt(kind, lang),
            parse_mode=None,
            reply_markup=image_editor_position_keyboard(kind, lang, f"editor_{kind}_pos", f"imgtool|editor_{kind}_input_back"),
        )
    if action == "editor_text_pos":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        position = normalize_image_editor_overlay_position(parts[2] if len(parts) > 2 else "", "bottom_center")
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="overlay")
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        origin_action = str((pending or {}).get("editor_source") or "editor_text")
        text_value = _short_pending_text(state.get("editor_overlay_text"), 260)
        if not text_value:
            back_callback = str((pending or {}).get("back_to") or image_editor_origin_back_callback(origin_action, "text"))
            set_image_menu_pending(uid, "image_editor_text_input", **{**state, "back_to": back_callback, "editor_source": origin_action})
            return await safe_edit_query_message(
                query,
                image_editor_overlay_input_prompt("text", lang),
                parse_mode="HTML",
                reply_markup=image_editor_text_input_keyboard(lang, back_callback),
            )
        set_image_menu_pending(uid, "image_editor_text_confirm", **{**state, "editor_overlay_position": position, "editor_source": origin_action})
        return await safe_edit_query_message(
            query,
            image_editor_overlay_confirm_text("text", text_value, position, lang),
            parse_mode="HTML",
            reply_markup=image_editor_overlay_confirm_keyboard("text", lang),
        )
    if action == "editor_logo_pos":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        position = normalize_image_editor_overlay_position(parts[2] if len(parts) > 2 else "", "bottom_right")
        if not state.get("file_id"):
            set_image_menu_pending(uid, "image_editor_wait_image", editor_mode="overlay")
            return await safe_edit_query_message(query, image_editor_start_text("overlay", lang), reply_markup=image_editor_start_keyboard(lang))
        origin_action = str((pending or {}).get("editor_source") or "editor_logo")
        text_value = _short_pending_text(state.get("editor_logo_text"), 260)
        if not text_value:
            back_callback = str((pending or {}).get("back_to") or image_editor_origin_back_callback(origin_action, "logo"))
            set_image_menu_pending(uid, "image_editor_logo_input", **{**state, "back_to": back_callback, "editor_source": origin_action})
            return await safe_edit_query_message(
                query,
                image_editor_overlay_input_prompt("logo", lang),
                parse_mode="HTML",
                reply_markup=image_editor_text_input_keyboard(lang, back_callback),
            )
        set_image_menu_pending(uid, "image_editor_logo_confirm", **{**state, "editor_overlay_position": position, "editor_source": origin_action})
        return await safe_edit_query_message(
            query,
            image_editor_overlay_confirm_text("logo", text_value, position, lang),
            parse_mode="HTML",
            reply_markup=image_editor_overlay_confirm_keyboard("logo", lang),
        )
    if action == "editor_text_confirm":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        text_value = _short_pending_text(state.get("editor_overlay_text"), 260)
        if not state.get("file_id") or not text_value:
            set_image_menu_pending(uid, "image_editor_text_input", **state)
            return await safe_edit_query_message(query, image_editor_overlay_input_prompt("text", lang), parse_mode="HTML", reply_markup=image_editor_text_input_keyboard(lang, "imgtool|editor_text_input_back"))
        return await send_local_edited_image(
            update,
            context,
            state,
            preset="photo_clear_detail",
            overlay_text=text_value,
            overlay_position=str(state.get("editor_overlay_position") or "bottom_center"),
        )
    if action == "editor_logo_confirm":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        text_value = _short_pending_text(state.get("editor_logo_text"), 260)
        if not state.get("file_id") or not text_value:
            set_image_menu_pending(uid, "image_editor_logo_input", **state)
            return await safe_edit_query_message(query, image_editor_overlay_input_prompt("logo", lang), parse_mode="HTML", reply_markup=image_editor_text_input_keyboard(lang, "imgtool|editor_logo_input_back"))
        return await send_local_edited_image(
            update,
            context,
            state,
            preset="photo_clear_detail",
            overlay_text=text_value,
            overlay_position=str(state.get("editor_overlay_position") or "bottom_right"),
            overlay_kind="logo",
        )
    if action == "editor_continue":
        result = get_image_tool_result(uid, "editor") or {}
        if not result.get("file_id"):
            return await safe_edit_query_message(query, image_editor_start_text("auto", lang), reply_markup=image_editor_start_keyboard(lang))
        set_image_menu_pending(uid, "image_editor_menu", **result)
        return await safe_edit_query_message(query, "🪄 Chọn thao tác tiếp theo cho ảnh preview hiện tại.", parse_mode=None, reply_markup=image_editor_action_keyboard(lang))
    if action == "editor_save":
        return await safe_edit_query_message(query, "💾 Ảnh đã được gửi trong chat. Bạn có thể tải/lưu trực tiếp từ tin nhắn ảnh. Bot chưa trừ Xu.", parse_mode=None, reply_markup=image_editor_result_keyboard(lang))
    if action == "editor_phase2":
        state = dict(pending or get_image_tool_result(uid, "editor") or recent_image_file_state(uid) or {})
        if state.get("file_id"):
            set_image_menu_pending(uid, "image_edit_choice", **state)
            return await safe_edit_query_message(query, image_edit_ai_choice_text(lang), reply_markup=image_edit_ai_choice_keyboard(lang))
        set_image_menu_pending(uid, "image_edit_wait_image")
        return await safe_edit_query_message(query, image_edit_menu_start_text(lang), reply_markup=image_edit_start_keyboard(lang))

    if action == "prompt_need_image":
        set_image_menu_pending(uid, "image_prompt_wait_image")
        return await safe_edit_query_message(query, image_prompt_send_image_hint_text(lang), parse_mode=None, reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_manual":
        set_image_menu_pending(uid, "image_prompt_subject", goal_code="custom", goal="mô tả thủ công" if normalize_user_language(lang) == "vi" else "manual description")
        return await safe_edit_query_message(query, image_prompt_subject_text("mô tả thủ công" if normalize_user_language(lang) == "vi" else "manual description", lang), reply_markup=image_menu_child_keyboard(lang))
    if action == "prompt_from_last":
        image_state = recent_image_file_state(uid)
        if image_state.get("file_id"):
            set_image_menu_pending(uid, "image_prompt_wait_purpose", **image_state, subject="ảnh đã nhận", prompt_source="image")
            return await safe_edit_query_message(query, image_prompt_received_text(lang), reply_markup=image_prompt_goal_keyboard(lang))
        set_image_menu_pending(uid, "image_prompt_wait_image")
        return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_back_wait_image":
        set_image_menu_pending(uid, "image_prompt_wait_image", **{k: v for k, v in pending.items() if k in {"file_id", "file_unique_id", "source_name"}})
        return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_back_goal":
        if pending.get("file_id"):
            set_image_menu_pending(uid, "image_prompt_wait_purpose", **pending)
            return await safe_edit_query_message(query, image_prompt_received_text(lang), reply_markup=image_prompt_goal_keyboard(lang))
        return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_back_style":
        if pending:
            set_image_menu_pending(uid, "image_prompt_style_custom", **pending)
            state = get_image_menu_pending(uid) or pending
            return await safe_edit_query_message(query, image_prompt_style_text(state, lang), reply_markup=image_prompt_style_keyboard(lang))
        return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_back_ratio":
        result = get_image_tool_result(uid, "prompt")
        if result:
            set_image_menu_pending(uid, "image_prompt_ratio_change", **{**result, "ratio_change": "1"})
            return await safe_edit_query_message(query, image_prompt_ratio_text(lang), reply_markup=image_prompt_ratio_keyboard(lang))
        return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_start_keyboard(lang))
    if action == "prompt_goal":
        goal_code = parts[2] if len(parts) > 2 else "product"
        goal = image_prompt_goal_label(goal_code, "", lang)
        if pending.get("file_id") or str(pending.get("pending_action") or "") == "image_prompt_wait_purpose":
            state = {**pending, "goal_code": goal_code, "goal": goal, "subject": pending.get("subject") or "ảnh đã nhận", "prompt_source": "image"}
            set_image_menu_pending(uid, "image_prompt_style_custom", **state)
            state = get_image_menu_pending(uid) or state
            return await safe_edit_query_message(query, image_prompt_style_text(state, lang), reply_markup=image_prompt_style_keyboard(lang))
        set_image_menu_pending(uid, "image_prompt_subject", goal_code=goal_code, goal=goal)
        return await safe_edit_query_message(query, image_prompt_subject_text(goal, lang), reply_markup=image_menu_child_keyboard(lang))
    if action == "prompt_goal_custom":
        set_image_menu_pending(uid, "image_prompt_goal_custom", **pending)
        return await safe_edit_query_message(query, "✍️ Bạn hãy nhập mục đích ảnh muốn tạo prompt. Bot chưa trừ Xu.", parse_mode=None, reply_markup=image_menu_child_keyboard(lang))
    if action == "prompt_style":
        if not pending:
            return await safe_edit_query_message(query, image_prompt_menu_start_text(lang), reply_markup=image_prompt_goal_keyboard(lang))
        try:
            idx = max(1, min(3, int(parts[2] if len(parts) > 2 else "1")))
        except Exception:
            idx = 1
        style = image_prompt_style_suggestions(pending.get("goal_code"), lang)[idx - 1]
        set_image_menu_pending(uid, "image_prompt_ratio_custom", **{**pending, "style": style})
