async def tts_elevenlabs_bytes(text: str) -> tuple[str, bytes, str, int]:
    if not ELEVENLABS_API_KEY:
        return "MISSING", b"", "ELEVENLABS_API_KEY missing", 0
    try:
        async with httpx.AsyncClient(timeout=45.0) as client:
            res = await client.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{ELEVENLABS_VOICE_ID}",
                headers={
                    "xi-api-key": ELEVENLABS_API_KEY,
                    "Content-Type": "application/json",
                    "Accept": "audio/mpeg",
                },
                json={
                    "text": text,
                    "model_id": "eleven_multilingual_v2",
                    "voice_settings": {"stability": 0.45, "similarity_boost": 0.75},
                },
            )
        if res.status_code < 400 and res.content:
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}", int(res.status_code)
        detail = sanitize_log_text(res.text[:300] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        return "FAIL", b"", detail, int(res.status_code)
    except Exception as e:
        return "FAIL", b"", provider_error_summary(e), 0

async def tts_fish_audio_bytes(text: str) -> tuple[str, bytes, str, int]:
    if not FISH_AUDIO_KEY:
        return "MISSING", b"", "FISH_AUDIO_KEY missing", 0
    try:
        async with httpx.AsyncClient(timeout=45.0) as client:
            res = await client.post(
                "https://api.fish.audio/v1/tts",
                headers={"Authorization": f"Bearer {FISH_AUDIO_KEY}", "Content-Type": "application/json"},
                json={"text": text, "reference_id": "7f0955e88846433e9ecb241357608bf8", "format": "mp3"},
            )
        if res.status_code < 400 and res.content:
            return "PASS", bytes(res.content), f"http={res.status_code}; bytes={len(res.content)}", int(res.status_code)
        detail = sanitize_log_text(res.text[:300] if getattr(res, "text", "") else f"HTTP {res.status_code}")
        return "FAIL", b"", detail, int(res.status_code)
    except Exception as e:
        return "FAIL", b"", provider_error_summary(e), 0

async def tts_edge_bytes(text: str, voice_id: str = "", voice_speed: str = VOICE_TTS_DEFAULT_SPEED) -> tuple[str, bytes, str, int]:
    if not edge_tts:
        return "MISSING", b"", f"edge-tts package missing: {EDGE_TTS_IMPORT_ERROR or 'import failed'}", 0
    tmp_path = ""
    try:
        with tempfile.NamedTemporaryFile(delete=False, suffix=".mp3") as tmp:
            tmp_path = tmp.name
        edge_voice = str(voice_id or "vi-VN-NamMinhNeural").strip()
        try:
            communicate = edge_tts.Communicate(text, edge_voice, rate=voice_tts_edge_rate(voice_speed))
        except TypeError:
            communicate = edge_tts.Communicate(text, edge_voice)
        await communicate.save(tmp_path)
        if os.path.exists(tmp_path) and os.path.getsize(tmp_path) > 0:
            with open(tmp_path, "rb") as f:
                audio_bytes = f.read()
            return "PASS", audio_bytes, f"bytes={len(audio_bytes)}", 0
        return "FAIL", b"", "empty_audio", 0
    except Exception as e:
        return "FAIL", b"", provider_error_summary(e), 0
    finally:
        if tmp_path and os.path.exists(tmp_path):
            try:
                os.remove(tmp_path)
            except Exception:
                pass

async def call_edge_tts_with_speed(text: str, voice_id: str = "", voice_speed: str = VOICE_TTS_DEFAULT_SPEED, edge_func=None) -> tuple[str, bytes, str, int]:
    func = edge_func if callable(edge_func) else tts_edge_bytes
    try:
        return await func(text, voice_id=voice_id, voice_speed=voice_speed)
    except TypeError:
        return await func(text, voice_id=voice_id)

async def cmd_tool_test_tts(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    text = " ".join(context.args or []).strip() or "Xin chào TOAN AAS"
    text = text[:240]
    uid = update.effective_user.id
    providers = [
        ("ElevenLabs", "tts:elevenlabs", tts_elevenlabs_bytes),
        ("Fish Audio", "tts:fish", tts_fish_audio_bytes),
        ("Edge TTS", "tts:edge", tts_edge_bytes),
    ]
    results = []
    output_provider = ""
    output_bytes = b""
    for idx, (label, tool_name, func) in enumerate(providers):
        status, data, detail, http_status = await func(text)
        save_tool_test_result(tool_name, status, detail, uid)
        record_api_debug(label.lower().replace(" ", "_"), "tool_test_tts", status, http_status, detail)
        results.append((label, status, detail))
        if status == "PASS" and data:
            output_provider = label
            output_bytes = data
            for skipped_label, skipped_tool, _ in providers[idx + 1:]:
                save_tool_test_result(skipped_tool, "NOT_USED", f"Skipped because {label} passed", uid)
                results.append((skipped_label, "NOT_USED", f"Skipped because {label} passed"))
            break
    overall = "PASS" if output_bytes else ("MISSING" if all(status == "MISSING" for _, status, _ in results) else "FAIL")
    detail = "; ".join(f"{label}={status}" for label, status, _ in results)
    save_tool_test_result("tts", overall, detail, uid)
    output_sent = False
    if output_bytes:
        audio = io.BytesIO(output_bytes)
        audio.name = f"toan_aas_tts_{output_provider.lower().replace(' ', '_')}.mp3"
        await context.bot.send_audio(
            chat_id=update.effective_chat.id,
            audio=audio,
            caption=f"🔊 TTS Smoke Test — {output_provider} PASS",
        )
        output_sent = True
    lines = [
        "🔊 <b>TTS Smoke Test</b>",
        "",
        f"• ElevenLabs: <code>{html.escape(provider_line_status(results[0][1], results[0][2]))}</code>",
        f"• Fish Audio fallback: <code>{html.escape(provider_line_status(results[1][1], results[1][2]))}</code>",
        f"• Edge TTS fallback: <code>{html.escape(provider_line_status(results[2][1], results[2][2]))}</code>",
        f"• Provider used: <code>{html.escape(output_provider or '-')}</code>",
        f"• Overall: <code>{html.escape(overall)}</code>",
        f"• Output sent: <code>{'yes' if output_sent else 'no'}</code>",
        "",
        "Không hiển thị API key và không trừ Xu nếu provider lỗi.",
    ]
    await update.message.reply_text("\n".join(lines), parse_mode="HTML")

async def cmd_tool_test_stt(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    command_name = extract_command_name(update) or "tool_test_stt"
    display_name = "/tool_test_asr" if command_name == "tool_test_asr" else "/tool_test_stt"
    if not has_admin_paid_confirmation(context):
        save_tool_test_result("stt", "NO_CONFIRM", f"missing {ADMIN_PAID_CONFIRM_FLAG}; no provider call", update.effective_user.id)
        save_tool_test_result("asr", "NO_CONFIRM", f"missing {ADMIN_PAID_CONFIRM_FLAG}; no provider call", update.effective_user.id)
        return await update.message.reply_text(admin_paid_confirm_required_text(display_name), parse_mode="HTML")
    readiness = get_asr_adapter_readiness(public=False)
    if not readiness.get("configured"):
        save_tool_test_result("stt", "MISSING", "asr adapter not configured", update.effective_user.id)
        save_tool_test_result("asr", "MISSING", "asr adapter not configured", update.effective_user.id)
        return await update.message.reply_text(
            "🎤 <b>ASR Smoke Test</b>\n\n• ASR configured: <code>NO</code>\n• Không gọi provider và không trừ Xu.",
            parse_mode="HTML",
        )
    media_info = await resolve_stt_test_media(update, context)
    if not media_info:
        set_pending_admin_tool_test(update.effective_user.id, "asr", display_name)
        return await update.message.reply_text(
            "Gửi hoặc reply voice/audio/video ngắn để test ASR.",
            parse_mode="HTML",
        )
    clear_pending_admin_tool_test(update.effective_user.id)
    file_size = int(media_info.get("file_size", 0) or 0)
    if file_size > PIPELINE_MAX_INPUT_MB_ADMIN * 1024 * 1024:
        save_tool_test_result("stt", "FAIL", f"file_too_large={file_size}", update.effective_user.id)
        return await update.message.reply_text(
            f"⚠️ File quá lớn để smoke test. Hãy dùng audio/video dưới {PIPELINE_MAX_INPUT_MB_ADMIN}MB."
        )
    try:
        content_type = media_info.get("content_type") or "application/octet-stream"
        file_type = str(media_info.get("file_type") or "").lower()
        media_kind = "video" if content_type.startswith("video/") or file_type == "video" else "audio"
        result = await transcribe_media_to_segments(
            {
                **media_info,
                "media_kind": media_kind,
                "duration_seconds": int(media_info.get("duration") or 0),
            },
            context=context,
            allow_admin=True,
            updated_by=update.effective_user.id,
        )
        transcript = str(result.get("transcript_text") or "").strip()
        passed = bool(result.get("output_valid") and transcript)
        status = "PASS" if passed else "FAIL"
        provider = str(result.get("provider") or readiness.get("adapter") or "asr")
        result_status = str(result.get("status") or ("pass" if passed else "failed"))
        safe_detail = sanitize_log_text(str(result.get("detail") or result_status))[:240]
        save_tool_test_result("stt", status, f"source={media_info.get('source')}; type={media_info.get('file_type')}; provider={provider}; chars={len(transcript)}; status={result_status}; {safe_detail}", update.effective_user.id)
        save_tool_test_result("asr", status, f"provider={provider}; source={media_info.get('source')}; chars={len(transcript)}; status={result_status}", update.effective_user.id)
        if passed:
            await update.message.reply_text(
                "🎙 <b>ASR PASS</b>\n\n"
                f"• Provider: <code>{html.escape(provider[:80])}</code>\n"
                f"• Source: <code>{html.escape(str(media_info.get('source') or '-'))}</code>\n"
                f"• Transcript:\n<code>{html.escape(transcript[:900])}</code>",
                parse_mode="HTML",
            )
        else:
            text = (
                "❌ <b>ASR không nhận được transcript hợp lệ.</b>\n\n"
                f"• Status: <code>{html.escape(result_status[:80])}</code>\n"
                "• Hãy thử voice/audio/video ngắn có giọng nói rõ.\n"
                "• Không trừ Xu và không bật public readiness."
            )
            await update.message.reply_text(text, parse_mode="HTML")
    except Exception as e:
        save_tool_test_result("stt", "FAIL", f"error_class={type(e).__name__}", update.effective_user.id)
        save_tool_test_result("asr", "FAIL", f"error_class={type(e).__name__}", update.effective_user.id)
        await update.message.reply_text(
            "🎤 <b>ASR Smoke Test</b>\n\n"
            "• Status: <code>FAIL</code>\n"
            f"• Error class: <code>{html.escape(type(e).__name__)}</code>\n"
            "• Không trừ Xu và không bật public readiness.",
            parse_mode="HTML",
        )

