async def cmd_tool_test_stt_debug(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    media_info = await resolve_stt_test_media(update, context)
    if not media_info:
        return await update.message.reply_text(
            "⚠️ Gửi voice/audio/video ngắn rồi reply <code>/tool_test_stt_debug</code>, "
            "hoặc gửi file xong gõ <code>/tool_test_stt_debug</code> trong vòng 2 phút.",
            parse_mode="HTML",
        )
    if not DEEPGRAM_API_KEY:
        return await update.message.reply_text("🎤 <b>STT Debug</b>\n\n• Deepgram: <code>MISSING</code>", parse_mode="HTML")
    file_size = int(media_info.get("file_size", 0) or 0)
    if file_size > PIPELINE_MAX_INPUT_MB_ADMIN * 1024 * 1024:
        save_tool_test_result("stt_debug", "FAIL", f"file_too_large={file_size}", update.effective_user.id)
        return await update.message.reply_text(
            f"⚠️ File quá lớn để debug. Hãy dùng audio/video dưới {PIPELINE_MAX_INPUT_MB_ADMIN}MB."
        )
    diagnostic = await AgentDeepgram.diagnostic(media_info["bytes"], media_info.get("content_type") or "application/octet-stream")
    stats = diagnostic.get("stats") or {}
    status = str(diagnostic.get("status") or "FAIL")
    record_api_debug(
        "deepgram",
        "stt_debug",
        status,
        int(diagnostic.get("http_status") or 0),
        (
            f"source={media_info.get('source')}; type={media_info.get('file_type')}; "
            f"mime={media_info.get('content_type')}; duration={stats.get('duration')}; "
            f"lang={stats.get('detected_language')}; transcript_length={stats.get('transcript_length')}; "
            f"words={stats.get('words_count')}; error={diagnostic.get('error') or diagnostic.get('body_preview')}"
        ),
    )
    save_tool_test_result("stt_debug", status, f"http={diagnostic.get('http_status')}; {stats}; error={diagnostic.get('error') or diagnostic.get('body_preview')}", update.effective_user.id)
    lines = [
        "🎤 <b>STT Debug</b>",
        "",
        f"• Source: <code>{html.escape(str(media_info.get('source') or '-'))}</code>",
        f"• File type: <code>{html.escape(str(media_info.get('file_type') or '-'))}</code>",
        f"• MIME: <code>{html.escape(str(media_info.get('content_type') or '-'))}</code>",
        f"• Filename: <code>{html.escape(str(media_info.get('file_name') or '-'))}</code>",
        f"• Telegram file size: <code>{int(media_info.get('file_size') or len(media_info.get('bytes') or b''))}</code>",
        "",
        f"• Deepgram HTTP: <code>{html.escape(str(diagnostic.get('http_status') or 0))}</code>",
        f"• Status: <code>{html.escape(status)}</code>",
        f"• Duration: <code>{html.escape(str(stats.get('duration') or '-'))}</code>",
        f"• Detected language: <code>{html.escape(str(stats.get('detected_language') or '-'))}</code>",
        f"• Confidence: <code>{html.escape(str(stats.get('confidence') or '-'))}</code>",
        f"• Transcript length: <code>{html.escape(str(stats.get('transcript_length') or 0))}</code>",
        f"• Alternatives count: <code>{html.escape(str(stats.get('alternatives_count') or 0))}</code>",
        f"• First words count: <code>{html.escape(str(stats.get('words_count') or 0))}</code>",
    ]
    error_short = diagnostic.get("error") or diagnostic.get("body_preview") or ""
    if error_short:
        lines.append(f"• Error short: <code>{html.escape(str(error_short)[:300])}</code>")
    transcript = diagnostic.get("transcript") or ""
    if transcript:
        lines.append(f"\nTranscript preview:\n<code>{html.escape(transcript[:700])}</code>")
    lines.append("\nKhông hiển thị API key.")
    await update.message.reply_text("\n".join(lines)[:3900], parse_mode="HTML")

async def cmd_tool_test_downloader(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    url = " ".join(context.args or []).strip()
    if not url:
        return await update.message.reply_text("⚠️ Cú pháp: <code>/tool_test_downloader https://...</code>", parse_mode="HTML")
    cobalt_raw = (COBALT_API_URL_RAW or "").rstrip("/")
    if not cobalt_raw:
        save_tool_test_result("downloader", "MISSING", "Cobalt self-host missing: COBALT_API_URL missing", update.effective_user.id)
        return await update.message.reply_text(
            "📥 <b>Downloader Smoke Test</b>\n\n"
            f"• URL: <code>{html.escape(url[:180])}</code>\n"
            "• Provider: <code>Cobalt</code>\n"
            "• API base: <code>-</code>\n"
            "• Result: <code>MISSING</code>\n\n"
            "Cobalt self-host missing. Hãy self-host Cobalt trên Railway/VPS rồi set <code>COBALT_API_URL</code>. "
            "Public Cobalt không dùng cho customer production.",
            parse_mode="HTML",
        )
    api_base = cobalt_raw
    public_cobalt = AgentDownloader._uses_public_cobalt(api_base)
    if public_cobalt:
        save_tool_test_result("downloader", "DISABLED_BY_POLICY", "public api.cobalt.tools disabled", update.effective_user.id)
        return await update.message.reply_text(
            "📥 <b>Downloader Smoke Test</b>\n\n"
            f"• URL: <code>{html.escape(url[:180])}</code>\n"
            "• Provider: <code>Cobalt</code>\n"
            f"• API base: <code>{html.escape(api_base)}</code>\n"
            "• Public Cobalt: <code>yes</code>\n"
            "• Result: <code>DISABLED_BY_POLICY</code>\n\n"
            "Public Cobalt đang bị khóa theo policy để tránh quảng cáo/kênh lạ. "
            "Muốn test thật, self-host Cobalt và set <code>COBALT_API_URL</code>.",
            parse_mode="HTML",
        )
    headers = {"Accept": "application/json", "Content-Type": "application/json"}
    if COBALT_API_KEY:
        headers["Authorization"] = f"Api-Key {COBALT_API_KEY}"
    payload = {
        "url": url,
        "downloadMode": "auto",
        "videoQuality": "720",
        "filenameStyle": "basic",
        "localProcessing": "disabled",
    }
    status = "FAIL"
    detail = ""
    has_media = False
    try:
        async with httpx.AsyncClient(timeout=35.0) as client:
            res = await client.post(api_base + "/", headers=headers, json=payload)
        try:
            data = res.json()
        except Exception:
            data = {"status": "error", "body": res.text[:300]}
        media_url = data.get("url", "") if isinstance(data, dict) else ""
        if isinstance(data, dict) and data.get("status") == "picker":
            picker = data.get("picker") or []
            media_url = next((item.get("url") for item in picker if item.get("url")), "")
        has_media = bool(media_url)
        status = "PASS" if res.status_code == 200 and has_media else "FAIL"
        detail = f"HTTP {res.status_code}; cobalt_status={data.get('status') if isinstance(data, dict) else '-'}; has_media={has_media}"
    except Exception as e:
        detail = str(e)[:300]
    save_tool_test_result("downloader", status, detail, update.effective_user.id)
    await update.message.reply_text(
        "📥 <b>Downloader Smoke Test</b>\n\n"
        f"• URL: <code>{html.escape(url[:180])}</code>\n"
        "• Provider: <code>Cobalt</code>\n"
        f"• API base: <code>{html.escape(api_base)}</code>\n"
        "• Public Cobalt: <code>no</code>\n"
        f"• Result: <code>{html.escape(status)}</code>\n"
        f"• Detail: <code>{html.escape(detail[:500])}</code>\n\n"
        "Smoke test chỉ kiểm tra provider trả media URL, không gửi video và không trừ Xu.",
        parse_mode="HTML",
    )

async def cmd_tool_test_trend_live(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    query = " ".join(context.args or []).strip()
    if not query:
        return await update.message.reply_text("⚠️ Cú pháp: <code>/tool_test_trend_live từ khóa</code>", parse_mode="HTML")
    if not SERPAPI_API_KEY:
        save_tool_test_result("trend_live", "MISSING", "SERPAPI_API_KEY missing", update.effective_user.id)
        return await update.message.reply_text(
            "📡 <b>Trend Live Smoke Test</b>\n\n• SerpAPI: <code>MISSING</code>\n• Không gọi provider.",
            parse_mode="HTML",
        )
    status = "FAIL"
    detail = ""
    preview = ""
    http_status = 0
    try:
        async with httpx.AsyncClient(timeout=30.0) as client:
            res = await client.get(
                "https://serpapi.com/search.json",
                params={"engine": "google", "q": query, "api_key": SERPAPI_API_KEY, "num": 3, "hl": "vi"},
            )
        http_status = int(res.status_code)
        data = res.json()
        organic = data.get("organic_results") or []
        titles = [str(item.get("title") or "").strip() for item in organic[:3] if item.get("title")]
        if res.status_code < 400 and titles:
            status = "PASS"
            preview = " | ".join(titles)
            detail = f"http={res.status_code}; results={len(titles)}"
        else:
            detail = sanitize_log_text(str(data.get("error") or data)[:350])
    except Exception as e:
        detail = provider_error_summary(e)
    save_tool_test_result("trend_live", status, f"query={query[:80]}; {detail}", update.effective_user.id)
    record_api_debug("serpapi", "tool_test_trend_live", status, http_status, detail)
    await update.message.reply_text(
        "📡 <b>Trend Live Smoke Test</b>\n\n"
        f"• Query: <code>{html.escape(query[:120])}</code>\n"
        f"• SerpAPI: <code>{html.escape(status)}</code>\n"
        f"• Detail: <code>{html.escape(detail[:350])}</code>"
        + (f"\n• Preview: <code>{html.escape(preview[:500])}</code>" if preview else "")
        + "\n\nKhông hiển thị API key.",
        parse_mode="HTML",
    )

