PRODUCT_CONTEXT_TTL_SECONDS = 60 * 60

def product_context_key(user_id) -> str:
    return f"product_context:{user_id}"

def normalize_product_context(value: str = "", default: str = PRODUCT_CONTEXT_SHOWROOM) -> str:
    raw = str(value or "").strip().lower().replace("-", "_")
    aliases = {
        "shop": PRODUCT_CONTEXT_SHOWROOM,
        "studio": PRODUCT_CONTEXT_SHOWROOM,
        "public": PRODUCT_CONTEXT_SHOWROOM,
        "standalone": PRODUCT_CONTEXT_SHOWROOM,
        "video": PRODUCT_CONTEXT_VIDEO_ADDON,
        "addon": PRODUCT_CONTEXT_VIDEO_ADDON,
        "videoaddon": PRODUCT_CONTEXT_VIDEO_ADDON,
        "video_addon": PRODUCT_CONTEXT_VIDEO_ADDON,
    }
    if raw in PRODUCT_CONTEXTS:
        return raw
    return aliases.get(raw, default if default in PRODUCT_CONTEXTS else PRODUCT_CONTEXT_SHOWROOM)

def product_context_callback(namespace: str, context: str, action: str) -> str:
    ns = str(namespace or "music_quick").strip() or "music_quick"
    ctx = normalize_product_context(context)
    act = str(action or "").strip()
    return f"{ns}|{ctx}|{act}"

def infer_product_context_from_callback(data: str = "", default: str = PRODUCT_CONTEXT_SHOWROOM) -> str:
    value = str(data or "").strip()
    if value.startswith(("vfinal|", "videoaddon|")):
        return PRODUCT_CONTEXT_VIDEO_ADDON
    if value.startswith("videodub|"):
        parts = value.split("|")
        if len(parts) > 1 and parts[1] in {"studio", "showroom"}:
            return PRODUCT_CONTEXT_SHOWROOM
        if len(parts) > 2 and parts[1] == "start" and parts[2] == "translation":
            return PRODUCT_CONTEXT_SHOWROOM
        return PRODUCT_CONTEXT_VIDEO_ADDON
    if value.startswith(("music_quick|", "sfx_quick|", "media_quick|", "tr_")):
        parts = value.split("|", 2)
        raw_context = parts[1].strip().lower() if len(parts) > 1 else ""
        context_aliases = {"shop", "studio", "public", "standalone", "video", "addon", "videoaddon", "video_addon"}
        if raw_context in PRODUCT_CONTEXTS or raw_context in context_aliases:
            return normalize_product_context(raw_context)
    return normalize_product_context(default)

def parse_product_context_callback(data: str = "", default_context: str = PRODUCT_CONTEXT_SHOWROOM) -> tuple[str, str, str]:
    parts = str(data or "").split("|", 2)
    namespace = parts[0] if parts else ""
    if len(parts) >= 3 and parts[1] in PRODUCT_CONTEXTS:
        return namespace, normalize_product_context(parts[1]), parts[2]
    action = parts[1] if len(parts) > 1 else ""
    return namespace, infer_product_context_from_callback(data, default_context), action

def enter_product_context(user_id, context: str, origin_screen: str = "", product_area: str = "", **fields) -> dict:
    ctx = normalize_product_context(context)
    payload = {
        "product_context": ctx,
        "origin_screen": str(origin_screen or ("menu|main" if ctx == PRODUCT_CONTEXT_SHOWROOM else "videoaddon|menu"))[:120],
        "product_area": str(product_area or "")[:80],
        "created_at_ts": time.time(),
        "updated_at_ts": time.time(),
    }
    for key, value in fields.items():
        payload[str(key)[:80]] = _short_pending_text(value, 500)
    if user_id:
        USER_PENDING[product_context_key(user_id)] = payload
    return dict(payload)

def get_product_context_state(user_id) -> dict:
    payload = USER_PENDING.get(product_context_key(user_id)) or {}
    if not payload:
        return {}
    if time.time() - float(payload.get("created_at_ts") or 0) > PRODUCT_CONTEXT_TTL_SECONDS:
        USER_PENDING.pop(product_context_key(user_id), None)
        return {}
    return dict(payload)

def clear_product_context(user_id) -> bool:
    return USER_PENDING.pop(product_context_key(user_id), None) is not None

def return_to_origin(context: str, origin_screen: str = "") -> str:
    ctx = normalize_product_context(context)
    if ctx == PRODUCT_CONTEXT_VIDEO_ADDON:
        return str(origin_screen or "videoaddon|menu")[:120]
    return str(origin_screen or "menu|main")[:120]

def current_product_context(user_id, fallback: str = PRODUCT_CONTEXT_SHOWROOM) -> str:
    state = get_product_context_state(user_id)
    return normalize_product_context(state.get("product_context"), fallback)

def music_guided_pending_key(user_id) -> str:
    return f"music_guided:{user_id}"

def music_guided_result_key(user_id) -> str:
    return f"music_guided_result:{user_id}"

def music_nav_origin_key(user_id) -> str:
    return f"music_nav_origin:{user_id}"

def set_music_nav_origin(user_id, back_callback: str = "menu|main") -> str:
    callback = str(back_callback or "menu|main").strip() or "menu|main"
    USER_PENDING[music_nav_origin_key(user_id)] = {
        "back_callback": callback[:80],
        "created_at_ts": time.time(),
    }
    return callback

def get_music_nav_back_callback(user_id, default: str = "menu|main") -> str:
    payload = USER_PENDING.get(music_nav_origin_key(user_id)) or {}
    if payload and time.time() - float(payload.get("created_at_ts") or 0) <= TREND_WORKFLOW_TTL_SECONDS:
        return str(payload.get("back_callback") or default or "menu|main")
    return str(default or "menu|main")

def get_music_nav_root_back(user_id) -> tuple[str, str]:
    callback = get_music_nav_back_callback(user_id, "menu|main")
    is_video = callback == "menu|main_video" or str(callback).startswith(("selfscene|", "videoaddon|", "vfinal|", "trendg|", "videoidea|", "storypack|"))
    label = "⬅️ Quay lại video" if is_video else "⬅️ Quay lại"
    return label, callback

def set_music_guided_pending(user_id, action: str, **fields) -> dict:
    payload = {
        "pending_action": str(action or "").strip(),
        "created_at_ts": time.time(),
    }
    for key, value in fields.items():
        payload[str(key)] = _short_pending_text(value, 900)
    USER_PENDING[music_guided_pending_key(user_id)] = payload
    return payload

VOICE_FLOW_ROOT_SCREEN = "voice_hub"

def encode_voice_back_stack(stack: list[str] | tuple[str, ...] | None = None) -> str:
    values = [str(item or "").strip() for item in (stack or []) if str(item or "").strip()]
    return json.dumps(values[-12:], ensure_ascii=False, separators=(",", ":"))

def decode_voice_back_stack(value: str | list | tuple | None = None) -> list[str]:
    if isinstance(value, (list, tuple)):
        return [str(item or "").strip() for item in value if str(item or "").strip()]
    try:
        parsed = json.loads(str(value or "[]"))
        if isinstance(parsed, list):
            return [str(item or "").strip() for item in parsed if str(item or "").strip()]
    except Exception:
        pass
    return []

def voice_flow_back_action_from_stack(back_stack: list[str] | tuple[str, ...] | None = None, fallback: str = VOICE_FLOW_ROOT_SCREEN) -> str:
    stack = decode_voice_back_stack(back_stack)
    return stack[-1] if stack else str(fallback or VOICE_FLOW_ROOT_SCREEN)

def voice_flow_pending_fields(
    *,
    product_context: str = PRODUCT_CONTEXT_SHOWROOM,
    origin: str = "",
    current_screen: str = "",
    previous_screen: str = "",
    return_to: str = "",
    back_stack: list[str] | tuple[str, ...] | None = None,
    voice_flow_step: str = "",
    profile_id: int = 0,
    voice_sample_file_id: str = "",
    voice_sample_path: str = "",
    voice_name: str = "",
    selected_voice_id: str = "",
    selected_voice_profile_id: int = 0,
    **extra,
) -> dict:
    current = str(current_screen or voice_flow_step or "").strip()
    pid = _safe_int(profile_id, 0)
    selected_pid = _safe_int(selected_voice_profile_id, 0)
    back_target = str(return_to or voice_flow_back_action_from_stack(back_stack, VOICE_FLOW_ROOT_SCREEN))[:120]
    data = {
        "product_context": normalize_product_context(product_context),
        "origin": str(origin or VOICE_FLOW_ROOT_SCREEN)[:120],
        "current_screen": current[:120],
        "previous_screen": str(previous_screen or back_target)[:120],
        "return_to": back_target,
        "back_stack": encode_voice_back_stack(list(back_stack or [])),
        "voice_flow_step": str(voice_flow_step or current)[:120],
        "profile_id": str(pid) if pid else "",
        "voice_sample_file_id": str(voice_sample_file_id or "")[:220],
        "voice_sample_path": str(voice_sample_path or "")[:260],
        "voice_name": str(voice_name or "")[:120],
        "selected_voice_id": str(selected_voice_id or "")[:160],
        "selected_voice_profile_id": str(selected_pid) if selected_pid else "",
    }
    for key, value in dict(extra or {}).items():
        clean_key = str(key or "").strip()[:80]
        if not clean_key or clean_key in data:
            continue
        if isinstance(value, (int, float, bool)) or value is None:
            data[clean_key] = value
        else:
            data[clean_key] = str(value or "")[:500]
    return data

def set_voice_flow_pending(user_id, action: str, **fields) -> dict:
    return set_music_guided_pending(user_id, action, **voice_flow_pending_fields(**fields))

def get_music_guided_pending(user_id) -> dict | None:
    payload = USER_PENDING.get(music_guided_pending_key(user_id)) or {}
    if not payload.get("pending_action"):
        return None
    if time.time() - float(payload.get("created_at_ts") or 0) > QUICK_MEDIA_PENDING_TTL_SECONDS:
        USER_PENDING.pop(music_guided_pending_key(user_id), None)
        return None
    return payload

def clear_music_guided_pending(user_id) -> bool:
    return USER_PENDING.pop(music_guided_pending_key(user_id), None) is not None

def save_music_guided_result(user_id, payload: dict) -> dict:
    data = dict(payload or {})
    data["created_at_ts"] = time.time()
    USER_PENDING[music_guided_result_key(user_id)] = data
    return data

def get_music_guided_result(user_id) -> dict | None:
    data = USER_PENDING.get(music_guided_result_key(user_id)) or {}
    if not data:
        return None
    if time.time() - float(data.get("created_at_ts") or 0) > TREND_WORKFLOW_TTL_SECONDS:
        USER_PENDING.pop(music_guided_result_key(user_id), None)
        return None
    return data

