async def show_voice_tts_settings_screen(message, user_id, source: str = "", *, product_context: str = PRODUCT_CONTEXT_SHOWROOM, gender: str = "", profile_id: int = 0, voice_label: str = "", voice_id: str = "", voice_style: str = "", lang: str = "vi"):
    ctx = normalize_product_context(product_context)
    result = voice_tts_settings_state(user_id, source, product_context=ctx, gender=gender, profile_id=profile_id, voice_label=voice_label, voice_id=voice_id, voice_style=voice_style)
    return await message.reply_text(
        voice_tts_settings_text(result.get("tts_speed"), result.get("voice_tts_volume_percent"), lang),
        parse_mode="HTML",
        reply_markup=voice_tts_settings_keyboard(lang, ctx),
    )


def voice_tts_invoice_voice_name(user_id, result: dict, lang: str = "vi") -> str:
    source = str((result or {}).get("voice_tts_settings_source") or "").strip().lower()
    if source == "default":
        gender = default_voice_gender_from_kind(str((result or {}).get("voice_tts_settings_gender") or (result or {}).get("selected_voice_kind") or "neutral"))
        return default_voice_label(gender, lang)
    if source == "saved":
        profile_id = _safe_int((result or {}).get("voice_tts_settings_profile_id") or (result or {}).get("selected_voice_profile_id"), 0)
        profile = get_user_voice_profile(user_id, profile_id)
        return str((profile or {}).get("display_name") or (result or {}).get("selected_voice_style") or "Giọng đã lưu")
    return str((result or {}).get("voice_tts_settings_voice_label") or (result or {}).get("selected_voice_style") or (result or {}).get("selected_voice_id") or "Giọng đã chọn")


async def show_voice_tts_price_summary(message, user_id, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM):
    ctx = normalize_product_context(product_context)
    result = get_music_guided_result(user_id) or {}
    source = str(result.get("voice_tts_settings_source") or "").strip().lower()
    text_value = str(result.get("voice_text") or "").strip()
    speed = voice_tts_speed_value(result.get("tts_speed") or VOICE_TTS_DEFAULT_SPEED)
    volume = voice_tts_volume_percent(result.get("voice_tts_volume_percent") or VOICE_TTS_DEFAULT_VOLUME_PERCENT)
    if not text_value:
        set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    if voice_tts_product_text_too_short(text_value):
        if source == "saved":
            set_music_guided_pending(user_id, "voice_tts_product_text", profile_id=_safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0), product_context=ctx)
        else:
            set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_tts_min_words_text(lang), reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    return await message.reply_text(
        voice_tts_price_summary_text(
            voice_name=voice_tts_invoice_voice_name(user_id, result, lang),
            text=text_value,
            speed=speed,
            volume_percent=volume,
            lang=lang,
            quote=voice_tts_product_quote_for_source(text_value, source),
        ),
        parse_mode="HTML",
        reply_markup=voice_tts_price_summary_keyboard(lang, ctx),
    )


async def voice_tts_return_previous_screen(message, user_id, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM):
    ctx = normalize_product_context(product_context)
    result = get_music_guided_result(user_id) or {}
    source = str(result.get("voice_tts_settings_source") or "").strip().lower()
    text_value = str(result.get("voice_text") or "").strip()
    if source == "default":
        gender = default_voice_gender_from_kind(str(result.get("voice_tts_settings_gender") or result.get("selected_voice_kind") or "neutral"))
        return await message.reply_text(default_voice_confirm_text(text_value, gender, lang), parse_mode="HTML", reply_markup=default_voice_confirm_keyboard(gender, lang, ctx))
    if source == "saved":
        profile_id = _safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0)
        profile = get_user_voice_profile(user_id, profile_id)
        if profile and text_value:
            return await message.reply_text(saved_voice_tts_confirm_text(profile, text_value, str(result.get("tts_speed") or VOICE_TTS_DEFAULT_SPEED), lang), parse_mode="HTML", reply_markup=saved_voice_tts_confirm_keyboard(profile_id, lang, custom_voice_usage_price_xu(text_value)))
        return await message.reply_text("⚠️ Nội dung giọng đọc đã hết hạn. Anh/chị nhập lại nội dung nhé.", reply_markup=voice_vault_keyboard(user_id, lang, ctx))
    return await message.reply_text(
        voice_tts_ready_text(text_value, lang, str(result.get("tts_speed") or VOICE_TTS_DEFAULT_SPEED)),
        parse_mode="HTML",
        reply_markup=voice_tts_choice_keyboard(lang, ctx),
    )

async def voice_tts_create_from_settings(message, user_id, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM, *, zero_confirmed: bool = False):
    ctx = normalize_product_context(product_context)
    result = get_music_guided_result(user_id) or {}
    source = str(result.get("voice_tts_settings_source") or "").strip().lower()
    text_value = str(result.get("voice_text") or "").strip()
    volume = voice_tts_volume_percent(result.get("voice_tts_volume_percent") or VOICE_TTS_DEFAULT_VOLUME_PERCENT)
    if not text_value:
        set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    if voice_tts_product_text_too_short(text_value):
        if source == "saved":
            set_music_guided_pending(user_id, "voice_tts_product_text", profile_id=_safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0), product_context=ctx)
        else:
            set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_tts_min_words_text(lang), reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    if volume == 0 and not zero_confirmed and not bool(result.get("voice_tts_zero_volume_confirmed")):
        return await message.reply_text(voice_tts_zero_volume_confirm_text(lang), reply_markup=voice_tts_zero_volume_confirm_keyboard(lang, ctx))
    if source == "saved":
        profile_id = _safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0)
        profile = get_user_voice_profile(user_id, profile_id)
        if not voice_profile_can_generate_tts(profile):
            return await message.reply_text(voice_profile_not_ready_text(profile, lang), parse_mode="HTML", reply_markup=voice_profile_actions_keyboard(profile_id, lang, ctx, profile))
    return await show_voice_tts_price_summary(message, user_id, lang, ctx)


async def voice_tts_generate_after_confirm(message, user_id, lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM):
    ctx = normalize_product_context(product_context)
    result = get_music_guided_result(user_id) or {}
    source = str(result.get("voice_tts_settings_source") or "").strip().lower()
    text_value = str(result.get("voice_text") or "").strip()
    speed = voice_tts_speed_value(result.get("tts_speed") or VOICE_TTS_DEFAULT_SPEED)
    volume = voice_tts_volume_percent(result.get("voice_tts_volume_percent") or VOICE_TTS_DEFAULT_VOLUME_PERCENT)
    if not text_value:
        set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    if voice_tts_product_text_too_short(text_value):
        if source == "saved":
            set_music_guided_pending(user_id, "voice_tts_product_text", profile_id=_safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0), product_context=ctx)
        else:
            set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        return await message.reply_text(voice_tts_min_words_text(lang), reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    result["voice_tts_invoice_confirmed"] = True
    save_music_guided_result(user_id, result)
    if source == "default":
        gender = default_voice_gender_from_kind(str(result.get("voice_tts_settings_gender") or result.get("selected_voice_kind") or "neutral"))
        return await send_default_free_tts_result(message, user_id, text_value, gender, speed=speed, volume_percent=volume, lang=lang, product_context=ctx)
    if source == "saved":
        profile_id = _safe_int(result.get("voice_tts_settings_profile_id") or result.get("selected_voice_profile_id"), 0)
        profile = get_user_voice_profile(user_id, profile_id)
        if not voice_profile_can_generate_tts(profile):
            return await message.reply_text("⚠️ Không tìm thấy giọng này trong Kho voice của bạn.", reply_markup=voice_vault_keyboard(user_id, lang, ctx))
        return await send_paid_saved_voice_tts_result(message, user_id, profile, text_value, speed=speed, volume_percent=volume, lang=lang)
    voice_label = str(result.get("voice_tts_settings_voice_label") or result.get("selected_voice_style") or result.get("selected_voice_id") or "").strip()
    return await send_standalone_tts_result(
        message,
        user_id,
        text_value,
        voice_label or "giọng đã chọn",
        voice_id=str(result.get("voice_tts_settings_voice_id") or result.get("selected_voice_id") or ""),
        voice_style=str(result.get("voice_tts_settings_voice_style") or result.get("selected_voice_style") or voice_label),
        speed=speed,
        volume_percent=volume,
        lang=lang,
        product_context=ctx,
    )

def standalone_tts_guard_text(lang: str = "vi") -> str:
    if music_ui_lang(lang=lang) != "vi":
        return "TOAN AAS could not create the voice audio right now. No Xu was charged. You can try again or change voice."
    return "TOAN AAS chưa tạo được giọng đọc lúc này. Hệ thống chưa trừ Xu. Anh/chị có thể thử lại hoặc đổi giọng khác."

def default_free_tts_guard_text(lang: str = "vi") -> str:
    if music_ui_lang(lang=lang) != "vi":
        return "TOAN AAS could not create the voice audio right now. No Xu was charged. You can try again or change voice."
    return "TOAN AAS chưa tạo được giọng đọc lúc này. Hệ thống chưa trừ Xu. Anh/chị có thể thử lại hoặc đổi giọng khác."

def tts_provider_guard_text(lang: str = "vi") -> str:
    if music_ui_lang(lang=lang) != "vi":
        return "AI voice is being prepared. TOAN AAS has not started processing and has not charged Xu. You can try again later or use another tool first."
    return "Giọng đọc AI đang được chuẩn bị. TOAN AAS chưa xử lý và chưa trừ Xu. Anh/chị có thể thử lại sau hoặc dùng công cụ khác trước."

def tts_failure_text(lang: str = "vi") -> str:
    return standalone_tts_guard_text(lang)

def tts_failure_keyboard(lang: str = "vi", product_context: str = PRODUCT_CONTEXT_SHOWROOM) -> InlineKeyboardMarkup:
    is_vi = music_ui_lang(lang=lang) == "vi"
    ctx = normalize_product_context(product_context)
    cb = lambda action: product_context_callback("music_quick", ctx, action)
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🔁 Thử lại" if is_vi else "🔁 Retry", callback_data=cb("voice_tts_guard")),
            InlineKeyboardButton("🎙 Đổi giọng" if is_vi else "🎙 Change voice", callback_data=cb("voice_hub")),
        ],
        [
            InlineKeyboardButton("✏️ Sửa nội dung" if is_vi else "✏️ Edit content", callback_data=cb("voice_tts_text")),
            InlineKeyboardButton("⬅️ Quay lại" if is_vi else "⬅️ Back", callback_data=cb("voice_hub")),
        ],
        [InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")],
    ])

async def synthesize_standalone_tts_audio(text: str, voice_id: str = "", voice_style: str = "", speed: str = "normal", provider_hint: str = "", allow_admin: bool = False) -> tuple[bool, bytes, str]:
    clean = re.sub(r"\s+", " ", str(text or "")).strip()[:3500]
    if not clean:
        return False, b"", "empty_text"
    requested_voice = str(voice_id or "").strip()
    requested_kind = requested_voice.lower()
    selected_voice = get_tts_voice_id(requested_voice)
    is_default_female = requested_kind in {"default_female", "female"} or selected_voice == default_tts_voice_id("female")
    is_default_male = requested_kind in {"default_male", "male"} or selected_voice == default_tts_voice_id("male")
    free_default_only = str(provider_hint or "").strip().lower() in {"default_free", "edge_free", "free_default", "edge"}
    voice_speed = voice_tts_speed_value(speed)
    shopaikey_call = lambda: call_shopaikey_minimax_tts_bytes_with_speed(clean, voice_id=selected_voice or default_tts_voice_id("male"), voice_style=voice_style, voice_speed=voice_speed)
    key4u_call = lambda: call_key4u_minimax_tts_bytes_with_speed(clean, voice_id=selected_voice or default_tts_voice_id("male"), voice_style=voice_style, voice_speed=voice_speed, allow_admin=allow_admin)
    simple_shopaikey_call = lambda: shopaikey_tts_bytes(clean)
    minimax_candidates = [key4u_call, shopaikey_call] if str(provider_hint or "").startswith("key4u") else [shopaikey_call, key4u_call]
    if free_default_only:
        edge_kind = "female" if is_default_female else "male"
        edge_call = globals().get("tts_" + "edge_bytes")
        candidates = [lambda: call_edge_tts_with_speed(clean, default_edge_tts_voice_id(edge_kind), voice_speed=voice_speed, edge_func=edge_call) if callable(edge_call) else ("MISSING", b"", "edge_tts_missing", 0)]
    elif selected_voice:
        candidates = list(minimax_candidates)
        if is_default_female or is_default_male:
            if shopaikey_tts_public_smoke_ready():
                candidates.append(simple_shopaikey_call)
            edge_kind = "female" if is_default_female else "male"
            edge_voice_runner = tts_edge_bytes
            candidates.append(lambda: call_edge_tts_with_speed(clean, default_edge_tts_voice_id(edge_kind), voice_speed=voice_speed, edge_func=edge_voice_runner))
    else:
        candidates = list(minimax_candidates)
        if shopaikey_tts_public_smoke_ready():
            candidates.append(simple_shopaikey_call)
        candidates.append(lambda: video_dubbing_tts_bytes(clean, voice_style=voice_style, voice_speed=voice_speed))
    last_detail = ""
    for make_call in candidates:
        try:
            result = await make_call()
            status = str(result[0] if result else "")
            audio_bytes = bytes(result[1] if len(result) > 1 and result[1] else b"")
            detail = str(result[2] if len(result) > 2 else "")
            if audio_bytes and (status == "PASS" or not status.upper().startswith(("FAIL", "MISSING", "NEED_"))):
                return True, audio_bytes, detail
            last_detail = detail or status
        except Exception as exc:
            last_detail = sanitize_log_text(str(exc))[:160]
    return False, b"", last_detail or "not_ready"

async def send_standalone_tts_result(
    message,
    user_id,
    text: str,
    voice_label: str,
    voice_id: str = "",
    voice_style: str = "",
    speed: str = "normal",
    volume_percent: int = VOICE_TTS_DEFAULT_VOLUME_PERCENT,
    lang: str = "vi",
    product_context: str = PRODUCT_CONTEXT_SHOWROOM,
) -> bool:
    ctx = normalize_product_context(product_context)
    speed = voice_tts_speed_value(speed)
    volume_percent = voice_tts_volume_percent(volume_percent)
    if is_default_tts_selection(voice_id, voice_label, voice_id):
        return await send_default_free_tts_result(
            message,
            user_id,
            text,
            default_voice_gender_from_kind(voice_id or voice_label),
            speed=speed,
            volume_percent=volume_percent,
            lang=lang,
            product_context=ctx,
        )
    quota_decision = preview_quota_guard(user_id, "voice_ai")
    if not quota_decision.get("allowed"):
        create_voice_asset_record(
            user_id,
            "voice_tts_preview",
            ctx,
            normalize_voice_asset_kind(voice_id, voice_label),
            text=text,
            duration_seconds=0,
            output_bytes=0,
            status="blocked",
            linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
            metadata={"reason": str(quota_decision.get("reason") or "preview_gate")},
        )
        await message.reply_text(
            preview_quota_block_text(quota_decision, "voice_ai", lang),
            parse_mode="HTML",
            reply_markup=voice_hub_keyboard(lang, ctx),
        )
        return False
    await message.reply_text(voice_preview_notice_text(lang), parse_mode="HTML")
    engine_result = await execute_engine(
        "voice_tts",
        {
            "text": text,
            "voice_id": voice_id,
            "voice_style": voice_style,
            "speed": speed,
        },
        {
            "user_id": user_id,
            "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
            "confirm_paid": True,
            "admin_interactive_confirm": True,
            "is_paid_job": bool(is_admin_user(user_id)),
            "allow_admin": bool(is_admin_user(user_id)),
        },
    )
    ok = bool(engine_result.get("ok"))
    audio_bytes = bytes(engine_result.get("output_bytes") or b"")
    detail = str(engine_result.get("detail") or engine_result.get("status") or "")
    if not ok or not audio_bytes:
        create_voice_asset_record(
            user_id,
            "voice_tts_preview",
            ctx,
            normalize_voice_asset_kind(voice_id, voice_label),
            text=text,
            duration_seconds=0,
            output_bytes=0,
            status="failed",
            linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
            metadata={"reason": sanitize_log_text(detail)[:160]},
        )
        logger.info("standalone tts not ready | user=%s | detail=%s", user_id, sanitize_log_text(detail)[:160])
        await message.reply_text(tts_failure_text(lang), reply_markup=tts_failure_keyboard(lang, ctx))
        return False
    preview_bytes, cap_detail = await cap_voice_preview_audio_bytes(audio_bytes, voice_preview_seconds())
    voice_kind = normalize_voice_asset_kind(voice_id, voice_label)
    asset_id = voice_asset_make_id(user_id, "voice_tts_preview", voice_kind, voice_asset_text_hash(text))
    local_path = write_voice_asset_audio_bytes(asset_id, audio_bytes)
    if not preview_bytes:
        create_voice_asset_record(
            user_id,
            "voice_tts_preview",
            ctx,
            voice_kind,
            text=text,
            duration_seconds=estimate_voice_duration_seconds(text, speed),
            output_bytes=len(audio_bytes or b""),
            file_ref=local_path,
            local_path=local_path,
            status="failed",
            linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
            metadata={"reason": f"preview_cap_failed:{sanitize_log_text(cap_detail)[:120]}"},
            voice_asset_id=asset_id,
        )
        await message.reply_text(tts_failure_text(lang), reply_markup=tts_failure_keyboard(lang, ctx))
        return False
    preview_bytes, preview_local_path, preview_boost_metadata = boost_voice_output_for_asset(f"{asset_id}_preview", preview_bytes, volume_percent=volume_percent)
    audio_file = video_dubbing_output_file(preview_bytes, "toan_aas_voice_preview.mp3")
    price = tts_full_price_xu(text, speed)
    duration = estimate_voice_duration_seconds(text, speed)
    chars = voice_tts_billable_chars(text)
    caption = (
        f"✅ Đã tạo bản nghe thử {voice_preview_seconds()} giây bằng {voice_label}.\n"
        f"Voice asset: {asset_id}\n"
        f"Ước tính bản đầy đủ {duration} giây, {chars} ký tự tính phí. Dự kiến bản đầy đủ {price} Xu.\n"
        "Bản đầy đủ đã được lưu làm asset và chỉ giao/ghép khi quý khách xác nhận. TOAN AAS chưa trừ Xu final."
        if music_ui_lang(lang=lang) == "vi" else
        f"✅ {voice_preview_seconds()}s voice preview created with {voice_label}.\nVoice asset: {asset_id}\nEstimated full output {duration}s, {chars} billable chars. Full output estimate {price} Xu.\nTOAN AAS has not charged final Xu."
    )
    if hasattr(message, "reply_audio"):
        sent = await message.reply_audio(audio=audio_file, filename="toan_aas_voice_preview.mp3", caption=caption)
    else:
        sent = await message.reply_document(document=audio_file, filename="toan_aas_voice_preview.mp3", caption=caption)
    sent_file_id = str(getattr(getattr(sent, "audio", None), "file_id", "") or getattr(getattr(sent, "document", None), "file_id", "") or "")
    create_voice_asset_record(
        user_id,
        "voice_tts_preview",
        ctx,
        voice_kind,
        text=text,
        duration_seconds=duration,
        output_bytes=len(audio_bytes or b""),
        file_ref=local_path or sent_file_id,
        file_id=sent_file_id,
        local_path=local_path,
        status="preview_sent",
        linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
        metadata={
            "voice_label": str(voice_label or "")[:120],
            "voice_id": str(voice_id or "")[:120],
            "preview_seconds": voice_preview_seconds(),
            "preview_output_bytes": len(preview_bytes or b""),
            "full_price_xu": price,
            **preview_boost_metadata,
        },
        voice_asset_id=asset_id,
    )
    consume_preview_quota(user_id, "voice_ai", updated_by=user_id)
    return True

async def send_default_free_tts_result(
    message,
    user_id,
    text: str,
    gender: str = "neutral",
    speed: str = "normal",
    volume_percent: int = VOICE_TTS_DEFAULT_VOLUME_PERCENT,
    lang: str = "vi",
    product_context: str = PRODUCT_CONTEXT_SHOWROOM,
) -> bool:
    ctx = normalize_product_context(product_context)
    speed = voice_tts_speed_value(speed)
    volume_percent = voice_tts_volume_percent(volume_percent)
    gender = default_voice_gender_from_kind(gender)
    voice_label = default_voice_label(gender, lang)
    voice_kind = f"default_{gender}"
    voice_id = get_tts_voice_id(voice_kind)
    engine_result = await execute_engine(
        "voice_tts",
        {
            "text": text,
            "voice_id": voice_kind,
            "voice_style": voice_label,
            "speed": speed,
            "provider_hint": "default_free",
        },
        {
            "user_id": user_id,
            "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
            "confirm_paid": True,
            "admin_interactive_confirm": True,
            "is_paid_job": False,
            "allow_admin": bool(is_admin_user(user_id)),
        },
    )
    ok = bool(engine_result.get("ok"))
    audio_bytes = bytes(engine_result.get("output_bytes") or b"")
    detail = str(engine_result.get("detail") or engine_result.get("status") or "")
    duration = estimate_voice_duration_seconds(text, speed)
    asset_id = voice_asset_make_id(user_id, "voice_default_free_tts", voice_kind, voice_asset_text_hash(text))
    if not ok or not audio_bytes:
        create_voice_asset_record(
            user_id,
            "voice_default_free_tts",
            ctx,
            voice_kind,
            text=text,
            duration_seconds=0,
            output_bytes=0,
            status="failed",
            linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
            metadata={
                "reason": sanitize_log_text(detail)[:160],
                "price_xu": 0,
                "charge_status": "free_default_voice",
                "voice_id": voice_id[:120],
            },
            voice_asset_id=asset_id,
        )
        logger.info("default free tts not ready | user=%s | detail=%s", user_id, sanitize_log_text(detail)[:160])
        await message.reply_text(default_free_tts_guard_text(lang), reply_markup=tts_failure_keyboard(lang, ctx))
        return False
    audio_bytes, local_path, boost_metadata = boost_voice_output_for_asset(asset_id, audio_bytes, volume_percent=volume_percent)
    audio_file = video_dubbing_output_file(audio_bytes, "toan_aas_default_voice.mp3")
    quote = voice_tts_product_quote_for_source(text, "default")
    word_count = int(quote.get("word_count") or 0)
    caption = (
        "✅ Đã tạo audio.\n\n"
        f"• Số từ: {word_count}\n"
        "• Tổng giá: 0 Xu\n"
        "• Đã trừ: 0 Xu\n\n"
        "Miễn phí, không trừ Xu."
        if music_ui_lang(lang=lang) == "vi" else
        f"✅ Audio created with {voice_label}.\n\n• Words: {word_count}\n• Total price: 0 Xu\n• Charged: 0 Xu\n\nFree, no Xu charged."
    )
    if hasattr(message, "reply_audio"):
        sent = await message.reply_audio(audio=audio_file, filename="toan_aas_default_voice.mp3", caption=caption)
    else:
        sent = await message.reply_document(document=audio_file, filename="toan_aas_default_voice.mp3", caption=caption)
    sent_file_id = str(getattr(getattr(sent, "audio", None), "file_id", "") or getattr(getattr(sent, "document", None), "file_id", "") or "")
    create_voice_asset_record(
        user_id,
        "voice_default_free_tts",
        ctx,
        voice_kind,
        text=text,
        duration_seconds=duration,
        output_bytes=len(audio_bytes or b""),
        file_ref=local_path or sent_file_id,
        file_id=sent_file_id,
        local_path=local_path,
        status="used",
        linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
        metadata={
            "voice_label": str(voice_label or "")[:120],
            "voice_id": voice_id[:120],
            "price_xu": 0,
            "charge_status": "free_default_voice",
            "route": "edge_free",
            **boost_metadata,
        },
        voice_asset_id=asset_id,
    )
    return True

async def send_paid_saved_voice_tts_result(message, user_id, profile: dict, text: str, speed: str = "normal", volume_percent: int = VOICE_TTS_DEFAULT_VOLUME_PERCENT, lang: str = "vi") -> bool:
    speed = voice_tts_speed_value(speed)
    volume_percent = voice_tts_volume_percent(volume_percent)
    profile_id = int((profile or {}).get("id") or 0)
    if not voice_profile_can_generate_tts(profile):
        await message.reply_text(
            voice_profile_not_ready_text(profile, lang),
            parse_mode="HTML",
            reply_markup=voice_profile_actions_keyboard(profile_id, lang, PRODUCT_CONTEXT_SHOWROOM, profile),
        )
        return False
    if custom_voice_usage_text_too_short(text):
        await message.reply_text(
            "Nội dung quá ngắn. Vui lòng nhập trên 10 ký tự để tạo voice riêng.",
            reply_markup=saved_voice_tts_confirm_keyboard(profile_id, lang, custom_voice_usage_price_xu(text)),
        )
        return False
    billable_chars = custom_voice_usage_billable_chars(text)
    quote = voice_tts_product_quote(text)
    price = int(quote.get("total_xu") or 0)
    billable_words = int(quote.get("word_count") or 0)
    charged = 0
    tts_kwargs = {
        "voice_id": str(profile.get("provider_voice_id") or ""),
        "voice_style": str(profile.get("display_name") or ""),
        "speed": speed,
        "provider_hint": str(profile.get("provider") or ""),
    }
    async def _voice_saved_tts_executor(clean_text: str, provider_voice_id: str = "", **_kwargs):
        return await execute_engine(
            "voice_saved_tts",
            {"text": clean_text, **tts_kwargs, "voice_id": provider_voice_id},
            {
                "user_id": user_id,
                "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
                "confirm_paid": True,
                "admin_interactive_confirm": True,
                "is_paid_job": True,
                "allow_admin": bool(is_admin_user(user_id)),
            },
        )
    tts_output_path = str(voice_asset_storage_dir() / f"saved_voice_tts_{user_id}_{profile_id}_{voice_asset_text_hash(text)}.mp3")
    tts_result = await voice_clone_pipeline.process_voice_tts(
        user_id=user_id,
        text=text,
        selected_voice_option=profile,
        product_context=PRODUCT_CONTEXT_SHOWROOM,
        admin_mode=bool(is_admin_user(user_id)),
        fake=False,
        output_path=tts_output_path,
        get_profile_func=get_user_voice_profile,
        get_default_voice_id_func=default_tts_voice_id,
        execute_tts_func=_voice_saved_tts_executor,
        volume_percent=volume_percent,
    )
    audio_bytes = Path(tts_result.audio_path).read_bytes() if tts_result.ok and tts_result.audio_path and Path(tts_result.audio_path).exists() else b""
    if not tts_result.ok or not audio_bytes:
        logger.info("saved voice tts not ready | user=%s | profile=%s | detail=%s", user_id, profile_id, sanitize_log_text(tts_result.admin_debug_summary)[:160])
        await message.reply_text(
            tts_result.safe_public_message or tts_failure_text(lang),
            reply_markup=tts_failure_keyboard(lang, PRODUCT_CONTEXT_SHOWROOM),
        )
        return False
    if custom_voice_usage_output_too_short(text, speed, audio_bytes):
        await message.reply_text(
            "Đoạn đọc quá ngắn. Vui lòng nhập nội dung dài hơn để tạo audio hợp lệ trên 3 giây.",
            reply_markup=saved_voice_tts_confirm_keyboard(profile_id, lang, price),
        )
        return False
    if price > 0:
        if is_admin_user(user_id):
            charge = {"ok": True, "final_cost": 0}
        else:
            charge = spend_fixed_credit_info(
                user_id,
                price,
                "saved_voice_tts",
                f"voice_profile={profile_id}; words={billable_words}",
                apply_member_discount_flag=False,
            )
            if not charge.get("ok"):
                await message.reply_text(
                    f"⚠️ Số dư chưa đủ để tạo giọng đọc này. Cần {price} Xu. TOAN AAS đã tạo file hợp lệ nhưng chưa giao file và chưa trừ Xu.",
                    reply_markup=saved_voice_tts_confirm_keyboard(profile_id, lang, price),
                )
                return False
        charged = int(charge.get("final_cost") or 0) if is_admin_user(user_id) else int(charge.get("final_cost") or price)
    asset_id = voice_asset_make_id(user_id, "voice_saved_tts", "custom_clone", voice_asset_text_hash(text))
    local_path = str(tts_result.audio_path or "")
    boost_metadata = dict(tts_result.metadata or {})
    audio_file = video_dubbing_output_file(audio_bytes, "toan_aas_saved_voice.mp3")
    caption = (
        "✅ Đã tạo audio.\n\n"
        f"• Số từ: {billable_words}\n"
        f"• Tổng giá: {price} Xu\n"
        f"• Đã trừ: {charged} Xu"
    )
    if hasattr(message, "reply_audio"):
        sent = await message.reply_audio(audio=audio_file, filename="toan_aas_saved_voice.mp3", caption=caption)
    else:
        sent = await message.reply_document(document=audio_file, filename="toan_aas_saved_voice.mp3", caption=caption)
    sent_file_id = str(getattr(getattr(sent, "audio", None), "file_id", "") or getattr(getattr(sent, "document", None), "file_id", "") or "")
    create_voice_asset_record(
        user_id,
        "voice_saved_tts",
        PRODUCT_CONTEXT_SHOWROOM,
        "custom_clone_usage",
        text=text,
        duration_seconds=custom_voice_usage_duration_seconds(text, speed),
        output_bytes=len(audio_bytes or b""),
        file_ref=local_path or sent_file_id,
        file_id=sent_file_id,
        local_path=local_path,
        status="used",
        metadata={
            "profile_id": profile_id,
            "provider": str(profile.get("provider") or "")[:80],
            "charged_xu": charged,
            "price_xu": charged,
            "quoted_price_xu": price,
            "billable_words": billable_words,
            "price_per_word_xu": float(VOICE_TTS_PRODUCT_PRICE_PER_WORD_XU or 0.05),
            "billable_chars": billable_chars,
            "price_per_char_xu": float(CUSTOM_VOICE_USAGE_PRICE_PER_CHAR_XU or 0.1),
            "min_chars_rule": f">{int(CUSTOM_VOICE_USAGE_MIN_CHARS or 10)}",
            "min_duration_seconds_rule": f">{int(CUSTOM_VOICE_USAGE_MIN_DURATION_SECONDS or 3)}",
            "charge_status": "paid_custom_voice_usage" if charged > 0 else "admin_custom_voice_usage_no_charge",
            "linked_voice_profile_id": profile_id,
            **boost_metadata,
        },
        voice_asset_id=asset_id,
    )
    update_user_voice_profile(user_id, profile_id, last_used_at=now_text())
    return True

async def transcribe_standalone_audio_message(update: Update, context: ContextTypes.DEFAULT_TYPE) -> tuple[bool, str, str]:
    media, file_type = message_media_candidate(update.message)
    if not media:
        return False, "", "missing_media"
    file_id = str(getattr(media, "file_id", "") or "").strip()
    if not file_id:
        return False, "", "missing_file_id"
    try:
        tg_file = await context.bot.get_file(file_id)
        audio_bytes = bytes(await tg_file.download_as_bytearray())
    except Exception as exc:
        logger.warning("standalone stt download failed | %s", sanitize_log_text(str(exc))[:180])
        return False, "", "download_failed"
    content_type = media_content_type(media, file_type)
    status, transcript, detail, _http = await shopaikey_audio_transcribe_bytes(audio_bytes, content_type)
    if status == "PASS" and transcript:
        return True, transcript.strip(), detail
    if video_asr_provider_available():
        try:
            status, transcript, detail = await video_dubbing_transcribe_bytes(audio_bytes, context, content_type)
            if transcript:
                return True, transcript.strip(), detail
        except Exception as exc:
            detail = sanitize_log_text(str(exc))[:160]
    return False, "", detail or status or "not_ready"

