def music_product_quote_price_xu(product_kind: str = "background") -> int:
    kind = str(product_kind or "background").strip().lower()
    if kind in {"song", "song_full", "lyrics", "vocal_ai"}:
        return int(MUSIC_VOCAL_FULL_PRICE_XU or 800)
    if kind in {"background", "music_background", "instrumental_ai"}:
        return int(MUSIC_BACKGROUND_FULL_PRICE_XU or 250)
    if kind == "song_half" and music_short_mode_verified():
        return int(HALF_SONG_PRICE_XU or 0)
    return int(MUSIC_BACKGROUND_FULL_PRICE_XU or 250)

def music_ai_output_price_xu(duration_seconds, product_kind: str = "background") -> int:
    kind = str(product_kind or "background").strip().lower()
    if kind == "song_half":
        return int(HALF_SONG_PRICE_XU or 0) if music_short_mode_verified() else int(MUSIC_VOCAL_FULL_PRICE_XU or 800)
    if kind == "song_full":
        return int(MUSIC_VOCAL_FULL_PRICE_XU or 800)
    duration = normalize_music_duration_seconds(duration_seconds, 30)
    if kind == "song_seconds":
        if duration <= MUSIC_AI_SHORT_DURATION_SECONDS:
            return int(LYRIC_SONG_15S_PRICE_XU or 0)
        if duration <= 30:
            return int(LYRIC_SONG_30S_PRICE_XU or 0)
        if duration <= 60:
            return int(LYRIC_SONG_60S_PRICE_XU or 0)
        extra_blocks = int(math.ceil((duration - 60) / 30.0))
        return round_video_xu(
            float(LYRIC_SONG_60S_PRICE_XU or 0) + extra_blocks * float(LYRIC_SONG_EXTRA_30S_PRICE_XU or 0),
            MUSIC_AI_PRICE_ROUND_TO_XU,
        )
    if kind in {"background", "music_background", "instrumental_ai"}:
        return int(MUSIC_BACKGROUND_FULL_PRICE_XU or 250)
    if duration <= MUSIC_AI_SHORT_DURATION_SECONDS:
        return int(MUSIC_BACKGROUND_FULL_PRICE_XU or MUSIC_AI_15S_PRICE_XU or 0)
    if duration <= 30:
        return int(MUSIC_AI_30S_PRICE_XU or 0)
    extra_blocks = int(math.ceil((duration - 30) / 30.0))
    return round_video_xu(
        max(
            float(MUSIC_AI_MIN_XU or 0),
            float(MUSIC_AI_30S_PRICE_XU or 0) + extra_blocks * float(MUSIC_AI_EXTRA_30S_PRICE_XU or 0),
        ),
        MUSIC_AI_PRICE_ROUND_TO_XU,
    )

def music_song_length_mode(result: dict | None = None) -> str:
    result = dict(result or {})
    mode = str(result.get("song_length_mode") or result.get("song_product") or "").strip().lower()
    if mode == "half" and not music_short_mode_verified():
        return "full"
    return mode if mode in {"half", "full"} else ""

def music_result_duration_seconds(result: dict | None = None) -> int:
    result = dict(result or {})
    for key in ("music_result_duration_seconds", "music_output_duration_seconds", "actual_duration_seconds", "audio_duration_seconds"):
        value = result.get(key)
        if value not in (None, "", 0, "0"):
            try:
                parsed = int(round(float(value)))
                if parsed > 0:
                    return parsed
            except Exception:
                pass
    package_mode = music_song_length_mode(result)
    if package_mode == "half":
        return 60
    if package_mode == "full":
        return 120
    return normalize_music_duration_seconds(
        result.get("guided_duration_seconds") or result.get("guided_duration") or MUSIC_AI_SHORT_DURATION_SECONDS,
        MUSIC_AI_SHORT_DURATION_SECONDS,
    )

def music_result_product_kind(result: dict | None = None) -> str:
    result = dict(result or {})
    if music_product_result_is_3tier(result):
        return "song_full" if music_product_mode_from_result(result) == "song" else "background"
    package_mode = music_song_length_mode(result)
    if package_mode == "half" and music_short_mode_verified():
        return "song_half"
    if package_mode == "full":
        return "song_full"
    if result.get("song_product") == "seconds":
        return "song_seconds"
    return "background"

def music_result_price_xu(result: dict | None = None) -> int:
    result = dict(result or {})
    if music_product_result_is_3tier(result):
        return music_product_tier_price_xu(result.get("music_product_tier"), music_product_mode_from_result(result))
    return music_ai_output_price_xu(music_result_duration_seconds(result), music_result_product_kind(result))

