def voice_clone_preview_fail_category(error: Exception | str = "", readiness: dict | None = None, output_bytes: int = 0, route_errors: list[dict | str] | None = None) -> str:
    readiness = dict(readiness or {})
    detail = str(error or "").lower()
    if not readiness.get("ready"):
        return "ADAPTER_MISSING"
    clone_status = voice_clone_not_ready_status(route_errors, error)
    if clone_status in {"CLONE_PERMISSION_FORBIDDEN", "CLONE_ADAPTER_MISSING"}:
        return clone_status
    if "voice_routes_not_ready" in detail:
        return "NO_ROUTE_READY"
    if "voice_routes_failed" in detail or route_errors:
        return "PROVIDER_ROUTE_FAILED"
    if "voice_preview_cap" in detail or "preview_cap_failed" in detail:
        return "PREVIEW_CAP_FAILED"
    if "missing_file_id" in detail:
        return "TELEGRAM_SEND_FAILED"
    if int(output_bytes or 0) <= 0:
        return "NO_OUTPUT_BYTES"
    return "PREVIEW_FAILED"

def voice_clone_admin_preview_failure_text(
    readiness: dict | None = None,
    *,
    provider_name: str = "",
    output_bytes: int = 0,
    route_errors: list[dict | str] | None = None,
    error: Exception | str = "",
) -> str:
    readiness = dict(readiness or {})
    routes = _engine_missing_values(readiness.get("routes"))
    selected_adapter = provider_name or ",".join(routes) or "none"
    fail_category = voice_clone_preview_fail_category(error, readiness, output_bytes, route_errors)
    route_detail = " | ".join(voice_clone_route_error_summary(item, 420) for item in (route_errors or [])[:5]) or "-"
    return (
        "⚙️ <b>Bản nghe thử giọng chưa tạo được.</b>\n"
        f"{html.escape(VOICE_CLONE_PROVIDER_NOT_READY_ADMIN_VI)}\n"
        "Admin diagnostic:\n\n"
        f"• selected_adapter: <code>{_engine_safe(selected_adapter, 160)}</code>\n"
        f"• configured: <code>{_engine_yes_no(readiness.get('ready'))}</code>\n"
        f"• tts_smoke: <code>{_engine_safe(readiness.get('tts_smoke') or 'NOT_TESTED', 80)}</code>\n"
        f"• clone_smoke: <code>{_engine_safe(readiness.get('clone_smoke') or 'NOT_TESTED', 80)}</code>\n"
        f"• output_bytes: <code>{int(output_bytes or 0)}</code>\n"
        f"• fail_category: <code>{_engine_safe(fail_category, 80)}</code>\n"
        f"• route_errors: <code>{route_detail}</code>"
    )

def voice_clone_access_allowed(user_id, readiness: dict | None = None, route_attempts: list | None = None, *, admin_access: bool = False) -> bool:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())
    if admin_access or is_admin_user(user_id):
        return bool(readiness.get("ready") and (route_attempts is None or bool(route_attempts)))
    decision = can_user_access_product_engine(
        user_id,
        "voice_clone",
        "clone",
        is_provider_call=True,
        is_paid_job=False,
    )
    return bool(decision.get("allowed"))

def voice_clone_ready_for_processing(readiness: dict | None = None, route_attempts: list | None = None, *, admin_access: bool = False) -> bool:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())
    if not readiness.get("ready"):
        return False
    if readiness.get("provider_permission_blocked") and not admin_access:
        return False
    if route_attempts is not None and not route_attempts:
        return False
    if MINIMAX_REQUIRE_SMOKE_PASS and not admin_access:
        tts_smoke = str(readiness.get("tts_smoke") or "NOT_TESTED")
        clone_smoke = str(readiness.get("clone_smoke") or "NOT_TESTED")
        if not provider_status_is_pass(tts_smoke) or not provider_status_is_pass(clone_smoke):
            return False
    return True

def voice_clone_provider_route_names(readiness: dict | None = None, *, include_optional: bool = True, admin_access: bool = False) -> list[str]:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())
    names = []
    if readiness.get("shopaikey_configured"):
        names.append("shopaikey_minimax")
    if readiness.get("key4u_configured"):
        names.append("key4u_minimax")
    if include_optional and readiness.get("fish_audio_configured"):
        names.append("fish_audio")
    if include_optional and readiness.get("elevenlabs_configured"):
        names.append("elevenlabs")
    if not admin_access and readiness.get("provider_permission_blocked") and not voice_clone_last_forbidden_provider() and len(names) <= 1:
        return []
    preferred = str(readiness.get("active_custom_voice_route") or "").strip()
    if "shopaikey_minimax" in names:
        names = ["shopaikey_minimax", *[name for name in names if name != "shopaikey_minimax"]]
    elif preferred in names:
        names = [preferred, *[name for name in names if name != preferred]]
    blocked = "" if admin_access else voice_clone_last_forbidden_provider()
    if blocked in names:
        unblocked = [name for name in names if name != blocked]
        if unblocked:
            names = unblocked
        else:
            names = []
    return names

def voice_clone_provider_route_attempts(readiness: dict | None = None, *, admin_access: bool = False) -> list[tuple[str, object, object, object]]:
    readiness = dict(readiness or get_minimax_voice_clone_readiness())

    async def key4u_clone_tts(text: str, voice_id: str = "", voice_style: str = ""):
        return await key4u_minimax_tts_bytes(text, voice_id=voice_id, voice_style=voice_style, allow_admin=admin_access)

    route_map = {
        "shopaikey_minimax": (shopaikey_minimax_upload_voice_sample, shopaikey_minimax_voice_clone, shopaikey_minimax_tts_bytes),
        "key4u_minimax": (key4u_minimax_upload_voice_sample, key4u_minimax_voice_clone, key4u_clone_tts),
        "fish_audio": (fish_audio_upload_voice_sample_adapter, fish_audio_voice_clone_adapter, lambda text, voice_id="", voice_style="": tts_fish_audio_bytes(text)),
        "elevenlabs": (elevenlabs_upload_voice_sample_adapter, elevenlabs_voice_clone_adapter, lambda text, voice_id="", voice_style="": tts_elevenlabs_bytes(text)),
    }
    attempts = []
    for name in voice_clone_provider_route_names(readiness, admin_access=admin_access):
        upload_call, clone_call, tts_call = route_map[name]
        attempts.append((name, upload_call, clone_call, tts_call))
    return attempts

def mark_voice_profile_activation_failed(user_id, profile_id: int, profile: dict | None, status: str, admin_error: str) -> dict:
    metadata = voice_profile_metadata(profile or {})
    metadata["activation_status"] = str(status or "failed")
    metadata["activation_admin_error"] = sanitize_log_text(str(admin_error or ""))[:700]
    metadata["activation_failed_at"] = now_text()
    metadata["preview_key_pending"] = ""
    update_user_voice_profile(
        user_id,
        profile_id,
        status=str(status or "failed"),
        is_default=0,
        provider_voice_id="",
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    )
    fresh = get_user_voice_profile(user_id, profile_id) or dict(profile or {})
    fresh.update({
        "status": str(status or "failed"),
        "is_default": 0,
        "provider_voice_id": "",
        "metadata_json": json.dumps(metadata, ensure_ascii=False),
    })
    return fresh


