def finalize_custom_voice_creation(
    user_id,
    profile_id: int,
    *,
    provider: str,
    provider_voice_id: str,
    provider_file_id: str = "",
    preview_audio_ref: str = "",
    product_context: str = PRODUCT_CONTEXT_SHOWROOM,
    metadata_updates: dict | None = None,
) -> dict:
    profile_id = int(profile_id or 0)
    profile = get_user_voice_profile(user_id, profile_id)
    clean_provider_voice_id = minimax_voice_adapter.normalize_voice_id(provider_voice_id)
    if not profile or not minimax_voice_adapter.validate_provider_voice_id(clean_provider_voice_id):
        return {
            "ok": False,
            "reason": "missing_provider_voice_id",
            "public_message": "TOAN AAS chưa tạo được voice hợp lệ từ mẫu này. Anh/chị thử mẫu rõ hơn hoặc dùng giọng nam/nữ mặc định.",
            "profile": profile or {},
        }
    ctx = normalize_product_context(product_context)
    metadata = voice_profile_metadata(profile)
    metadata.update(dict(metadata_updates or {}))
    metadata["source_type"] = "custom_clone"
    metadata["provider"] = str(provider or "minimax")[:80]
    metadata["provider_voice_id"] = clean_provider_voice_id
    if provider_file_id:
        metadata["provider_file_id"] = str(provider_file_id or "")[:240]
    metadata["preview_charged_xu"] = 0
    metadata["activation_status"] = "provider_voice_id_saved"
    metadata["provider_voice_id_saved_at"] = now_text()
    cost = voice_profile_storage_price_xu(user_id, ctx, profile_id)
    metadata["final_cost_xu"] = int(cost or 0)
    pending_status = "pending_charge" if int(cost or 0) > 0 and not is_admin_user(user_id) else "ready"
    if not update_user_voice_profile(
        user_id,
        profile_id,
        provider=str(provider or "minimax")[:80],
        provider_voice_id=clean_provider_voice_id,
        preview_audio_ref=str(preview_audio_ref or "")[:220],
        status=pending_status,
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    ):
        return {
            "ok": False,
            "reason": "vault_save_failed",
            "public_message": "TOAN AAS chưa lưu được voice riêng vào Kho voice. Anh/chị thử lại sau.",
            "profile": profile,
        }
    charged = 0
    if int(cost or 0) > 0 and not is_admin_user(user_id):
        charge = spend_fixed_credit_info(
            user_id,
            int(cost or 0),
            "voice_clone_create",
            f"Voice profile #{profile_id}",
            apply_member_discount_flag=False,
        )
        if not charge.get("ok"):
            metadata["charge_status"] = "charge_failed_after_provider_success"
            metadata["charge_failed_at"] = now_text()
            update_user_voice_profile(
                user_id,
                profile_id,
                status="pending_charge",
                metadata_json=json.dumps(metadata, ensure_ascii=False),
            )
            return {
                "ok": False,
                "reason": "insufficient_xu",
                "public_message": f"⚠️ Số dư chưa đủ để lưu voice riêng ({int(cost or 0)} Xu). TOAN AAS chưa trừ Xu.",
                "profile": get_user_voice_profile(user_id, profile_id),
                "cost_xu": int(cost or 0),
            }
        charged = int(charge.get("final_cost") or cost or 0)
    metadata["charged_xu"] = charged
    metadata["charged_at"] = now_text() if charged > 0 else ""
    metadata["price_xu"] = int(cost or 0)
    metadata["charge_status"] = (
        "admin_custom_voice_created_no_charge"
        if is_admin_user(user_id)
        else ("paid_custom_voice_created" if charged > 0 else "free_custom_voice_created")
    )
    metadata["activation_status"] = "ready"
    metadata["activation_ready_at"] = now_text()
    update_user_voice_profile(
        user_id,
        profile_id,
        status="ready",
        metadata_json=json.dumps(metadata, ensure_ascii=False),
    )
    return {
        "ok": True,
        "reason": "custom_voice_ready",
        "profile": get_user_voice_profile(user_id, profile_id),
        "charged_xu": charged,
        "cost_xu": int(cost or 0),
    }


async def create_minimax_voice_profile_preview(query, context, user_id, profile: dict, lang: str = "vi", retry: bool = False, product_context: str = PRODUCT_CONTEXT_SHOWROOM, full_generation: bool = False):
    ctx = normalize_product_context(product_context)
    profile_id = int((profile or {}).get("id") or 0)
    if not profile_id or str((profile or {}).get("consent_status") or "") != "confirmed":
        return await query.message.reply_text(
            "⚠️ Yêu cầu tạo giọng không còn hợp lệ hoặc chưa xác nhận quyền sử dụng.",
            reply_markup=voice_hub_keyboard(lang, ctx),
        )
    metadata = voice_profile_metadata(profile)
    missing_draft = []
    if not str(profile.get("source_file_id") or profile.get("source_file_ref") or "").strip():
        missing_draft.append("source_file_id/source_file_ref")
    if not str(profile.get("display_name") or "").strip():
        missing_draft.append("display_name")
    if str(metadata.get("confirmation_sample_text") or "") != VOICE_CLONE_CONFIRMATION_SAMPLE_TEXT:
        missing_draft.append("confirmation_sample_text")
    if missing_draft:
        failed_profile = mark_voice_profile_activation_failed(
            user_id,
            profile_id,
            profile,
            "failed_invalid_voice_draft",
            "missing " + ",".join(missing_draft),
        )
        return await query.message.reply_text(
            "⚠️ Yêu cầu tạo giọng còn thiếu mẫu giọng, tên hoặc câu xác nhận. TOAN AAS chưa trừ Xu. Bạn có thể tạo lại voice riêng.",
            reply_markup=voice_profile_actions_keyboard(profile_id, lang, ctx, failed_profile),
        )
    readiness = get_minimax_voice_clone_readiness()
    admin_access = is_admin_user(user_id)
    preflight = await voice_clone_pipeline.preflight_custom_voice_create(
        user_id=user_id,
        profile_id=profile_id,
        admin_mode=admin_access,
        readiness=readiness,
        route_attempts_func=voice_clone_provider_route_attempts,
        access_allowed_func=voice_clone_access_allowed,
        ready_for_processing_func=voice_clone_ready_for_processing,
    )
    if not preflight.ok:
        fail_status = str(preflight.error_code or "provider_not_ready")
        failed_profile = mark_voice_profile_activation_failed(
            user_id,
            profile_id,
            profile,
            "failed_clone_permission_forbidden" if voice_clone_permission_error(fail_status) else "failed_provider_not_ready",
            preflight.admin_debug_summary or fail_status,
        )
        if not load_provider_attempt("voice_clone"):
            save_provider_attempt(
                "voice_clone",
                {
                    "called": False,
                    "provider": ",".join(readiness.get("routes") or []) or "none",
                    "status": "BLOCKED",
                    "error": voice_clone_admin_blocker(readiness),
                },
                user_id,
            )
        if voice_clone_permission_error(fail_status):
            return await query.message.reply_text(
                voice_clone_product_failure_text(lang, fail_status),
                reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
            )
        return await query.message.reply_text(
            voice_clone_product_failure_text(lang, fail_status),
            reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
        )
    if not full_generation:
        quota_decision = preview_quota_guard(user_id, "voice_ai")
        if not quota_decision.get("allowed"):
            return await query.message.reply_text(
                preview_quota_block_text(quota_decision, "voice_ai", lang),
                parse_mode="HTML",
                reply_markup=voice_clone_preview_entry_keyboard(profile_id, lang, ctx),
            )
    guard = voice_preview_guard(
        user_id,
        profile_id,
        VOICE_CLONE_CONFIRMATION_SAMPLE_TEXT,
        "clone_preview",
        bypass_limits=bool(full_generation or admin_access),
    )
    if guard.get("cached"):
        cached_profile = guard.get("profile") or profile
        await context.bot.send_audio(
            chat_id=query.message.chat_id,
            audio=str(guard.get("preview_audio_ref") or ""),
            caption=f"🔊 Bản nghe thử giọng “{str(cached_profile.get('display_name') or 'Giọng mới')}” đã được dùng lại.",
        )
        return await query.message.reply_text(
            "✅ TOAN AAS đã dùng lại bản nghe thử trước đó, không tạo thêm lượt xử lý và chưa trừ Xu final.",
            reply_markup=voice_profile_actions_keyboard(profile_id, lang, ctx, cached_profile),
        )
    if not guard.get("ok"):
        if str(guard.get("reason") or "") == "quota":
            return await query.message.reply_text(
                voice_preview_guard_message("quota"),
                reply_markup=voice_preview_quota_exhausted_keyboard(profile_id, lang, ctx),
            )
        return await query.message.reply_text(
            voice_preview_guard_message(str(guard.get("reason") or "invalid"), int(guard.get("retry_after") or 0)),
            reply_markup=voice_clone_preview_entry_keyboard(profile_id, lang, ctx),
        )
    acquired, locked_profile = acquire_voice_preview_generation(user_id, profile_id, guard)
    if not acquired:
        return await query.message.reply_text(
            voice_preview_guard_message("inflight"),
            reply_markup=voice_clone_preview_entry_keyboard(profile_id, lang, ctx),
        )
    profile = locked_profile or profile
    metadata = voice_profile_metadata(profile)
    cost = voice_profile_storage_price_xu(user_id, ctx, profile_id)
    metadata["final_cost_xu"] = cost
    metadata["preview_charged_xu"] = 0
    await query.message.reply_text(
        "🎙 TOAN AAS đang tạo voice riêng. Vui lòng chờ và không bấm lại nhiều lần."
        if full_generation
        else "🎙 TOAN AAS đang tạo bản nghe thử. Vui lòng chờ và không bấm lại nhiều lần."
    )
    provider_name = ""
    provider_voice_id = ""
    route_errors = []
    try:
        telegram_file = await context.bot.get_file(str(profile.get("source_file_id") or profile.get("source_file_ref") or ""))
        audio_bytes = bytes(await telegram_file.download_as_bytearray())
        sample_path = write_voice_clone_sample_file(user_id, profile_id, audio_bytes)
        preview_text = str(guard.get("preview_text") or capped_voice_preview_text(VOICE_CLONE_CONFIRMATION_SAMPLE_TEXT))
        async def _finalize_custom_voice(**kwargs):
            return finalize_custom_voice_creation(
                user_id,
                profile_id,
                product_context=ctx,
                **kwargs,
            )
        result = await voice_clone_pipeline.process_custom_voice_create(
            user_id=user_id,
            sample_path=sample_path,
            display_name=str(profile.get("display_name") or ""),
            product_context=ctx,
            profile_id=profile_id,
            admin_mode=admin_access,
            no_charge=admin_access,
            fake=False,
            preview_text=preview_text,
            readiness=readiness,
            output_dir=str(voice_asset_storage_dir()),
            metadata_updates={
                "final_cost_xu": cost,
                "preview_charged_xu": 0,
                "preview_attempts": int(metadata.get("preview_attempts") or 0) + 1,
                "preview_key": str(guard.get("preview_key") or ""),
                "preview_key_pending": "",
                "preview_generated_at": now_text(),
                "preview_seconds_max": int(VOICE_PREVIEW_MAX_SECONDS),
                "preview_text_hash": hashlib.sha256(preview_text.encode("utf-8", errors="ignore")).hexdigest()[:24],
            },
            route_attempts_func=voice_clone_provider_route_attempts,
            access_allowed_func=voice_clone_access_allowed,
            ready_for_processing_func=voice_clone_ready_for_processing,
            make_provider_voice_id_func=make_minimax_voice_id,
            execute_engine_func=execute_engine,
            audio_reference_to_bytes_func=minimax_audio_reference_to_bytes,
            cap_preview_audio_func=cap_voice_preview_audio_bytes,
            record_attempt_func=record_voice_clone_attempt,
            finalize_profile_func=_finalize_custom_voice,
            max_preview_seconds=VOICE_PREVIEW_MAX_SECONDS,
        )
        provider_name = str(result.provider or "")
        provider_voice_id = str(result.provider_voice_id or "")
        provider_file_id = str(result.provider_file_id or "")
        route_errors = list((result.metadata or {}).get("route_errors") or [])
        if not result.ok:
            fail_status = str(result.error_code or result.status or "CLONE_NOT_READY")
            mark_voice_profile_activation_failed(user_id, profile_id, profile, "failed_" + fail_status.lower(), str(result.admin_debug_summary or fail_status))
            sample_error_codes = {"sample_missing_or_empty", "sample_too_large", "sample_duration_too_short", "unsupported_audio_extension"}
            public_failure_text = (
                str(result.safe_public_message or "").strip()
                if fail_status in sample_error_codes
                else voice_clone_product_failure_text(lang, fail_status)
            )
            if voice_clone_permission_error(fail_status):
                return await query.message.reply_text(
                    public_failure_text,
                    reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
                )
            return await query.message.reply_text(
                public_failure_text,
                reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
            )
        preview_ref = ""
        if result.preview_audio_path and Path(result.preview_audio_path).exists():
            preview_payload = Path(result.preview_audio_path).read_bytes()
            if preview_payload:
                audio_file = io.BytesIO(preview_payload)
                audio_file.name = f"toan_aas_voice_{profile_id}.mp3"
                sent = await context.bot.send_audio(
                    chat_id=query.message.chat_id,
                    audio=audio_file,
                    title=str(profile.get("display_name") or "TOAN AAS Voice Preview"),
                    caption=f"🔊 Bản nghe thử giọng “{str(profile.get('display_name') or 'Giọng mới')}”.",
                )
                preview_ref = str(getattr(getattr(sent, "audio", None), "file_id", "") or "")
                if not preview_ref:
                    metadata["preview_unavailable_reason"] = "voice_preview_missing_file_id"
                else:
                    update_user_voice_profile(user_id, profile_id, preview_audio_ref=preview_ref)
                    create_voice_asset_record(
                        user_id,
                        "voice_clone_preview",
                        ctx,
                        "custom_clone",
                        text=preview_text,
                        duration_seconds=voice_preview_seconds(),
                        output_bytes=int(result.preview_audio_bytes or len(preview_payload or b"")),
                        file_ref=preview_ref,
                        file_id=preview_ref,
                        local_path=str(result.preview_audio_path or ""),
                        status="preview_sent",
                        linked_video_session_id=voice_asset_video_session_id(user_id, ctx),
                        metadata={
                            "profile_id": profile_id,
                            "provider": provider_name,
                            "provider_voice_id": provider_voice_id,
                            "preview_output_bytes": int(result.preview_audio_bytes or len(preview_payload or b"")),
                            "price_xu": cost,
                            "charge_status": "free_custom_voice_created" if int(cost or 0) <= 0 else "paid_custom_voice_created_pending_finalize",
                        },
                    )
        if preview_ref and not full_generation:
            consume_preview_quota(user_id, "voice_ai", updated_by=user_id)
        fresh_profile = get_user_voice_profile(user_id, profile_id) or {}
        charged_line = f"\nĐã trừ: {int(result.charged_xu or 0)} Xu." if int(result.charged_xu or 0) > 0 else ""
        demo_line = "Bạn có thể nghe demo, tạo audio bằng nội dung riêng, đặt mặc định hoặc dùng cho video." if preview_ref else "Voice đã được lưu. Bản nghe thử chưa tạo được, anh/chị vẫn có thể tạo audio bằng nội dung riêng."
        return await query.message.reply_text(
            f"✅ Đã tạo voice riêng “{str(profile.get('display_name') or 'Giọng mới')}” và lưu vào Kho voice.\n\n"
            f"{demo_line}{charged_line}",
            reply_markup=custom_voice_created_keyboard(profile_id, lang, ctx),
        )
    except Exception as exc:
        logger.warning("voice profile preview failed | profile=%s | %s", profile_id, sanitize_log_text(str(exc))[:220])
        fail_status = voice_clone_not_ready_status(route_errors, exc)
        record_voice_clone_attempt(
            status=fail_status,
            provider=provider_name or "fallback_exhausted",
            route="voice_clone/product",
            error=str(exc),
            updated_by=user_id,
        )
        failed_profile = mark_voice_profile_activation_failed(user_id, profile_id, profile, "failed_" + fail_status.lower(), str(exc))
        if voice_clone_permission_error(exc):
            return await query.message.reply_text(
                voice_clone_product_failure_text(lang, fail_status),
                reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
            )
        return await query.message.reply_text(
            voice_clone_product_failure_text(lang, fail_status),
            reply_markup=custom_voice_failed_keyboard(lang, ctx, profile_id),
        )

async def handle_music_product_confirm(query, context, *, user_id, lang: str, product_context: str, result: dict) -> object:
    ctx = normalize_product_context(product_context)
    current = dict(result or {})
    if not music_product_result_is_3tier(current):
        return None
    price = music_result_price_xu(current)
    feature = music_engine_feature_for_result(current)
    decision = can_user_access_product_engine(
        user_id,
        feature,
        "confirm",
        is_provider_call=True,
        is_paid_job=True,
        confirm_paid=True,
        admin_interactive_confirm=True,
        state=current,
    )
    if not decision.get("allowed"):
        if is_admin_user(user_id):
            return await query.message.reply_text(
                decision.get("message") or "⚙️ Chưa chạy được tạo nhạc thật. TOAN AAS chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=music_product_invoice_keyboard(current, lang, ctx),
            )
        return await query.message.reply_text(
            music_ai_public_guard_text(lang),
            parse_mode="HTML",
            reply_markup=music_product_invoice_keyboard(current, lang, ctx),
        )
    credits, _, _ = get_user(user_id)
    if not is_admin_user(user_id) and int(credits or 0) < price:
        return await query.message.reply_text(
            f"⚠️ Số dư chưa đủ để tạo audio.\n• Cần: {price} Xu\n• Hiện có: {int(credits or 0)} Xu\n\nTOAN AAS chưa xử lý và chưa trừ Xu.",
            reply_markup=music_product_invoice_keyboard(current, lang, ctx),
        )
    if current.get("music_result_delivered_at") or current.get("music_full_sent_at"):
        return await query.message.reply_text(
            "✅ Đã gửi file nhạc phía trên.",
            reply_markup=music_product_success_keyboard(lang, ctx),
        )
    engine_result = await execute_engine(
        feature,
        {"result": current, "preview": False, "state": current},
        {
            "user_id": user_id,
            "entry_source": ENGINE_ENTRY_SOURCE_PRODUCT,
            "confirm_paid": True,
            "admin_interactive_confirm": True,
            "is_paid_job": True,
            "admin_smoke": bool(is_admin_user(user_id)),
            "updated_by": user_id,
        },
    )
    submitted = dict(engine_result.get("provider_result") or {})
    if not engine_result.get("ok"):
        logger.warning("music product submit failed | user=%s | %s", user_id, sanitize_log_text(str(engine_result.get("detail") or engine_result.get("status")))[:220])
        if is_admin_user(user_id):
            return await query.message.reply_text(
                engine_result.get("message") or "⚙️ Chưa tạo được nhạc thật. TOAN AAS chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=music_product_invoice_keyboard(current, lang, ctx),
            )
        return await query.message.reply_text(
            "⚙️ Chưa tạo được nhạc lúc này. TOAN AAS chưa trừ Xu, anh/chị thử lại sau nhé.",
            reply_markup=music_product_invoice_keyboard(current, lang, ctx),
        )
    music_task_id = music_provider_result_task_id(submitted) or str(engine_result.get("provider_task_id") or "")
    music_audio = engine_output_bytes(submitted) or engine_output_bytes(engine_result)
    current.update({
        "music_provider": str(submitted.get("provider") or ""),
        "music_task_id": music_task_id,
        "music_pending_charge_xu": price,
        "music_charged_xu": 0,
        "music_refunded": False,
    })
    if music_audio:
        delivered = await send_music_product_audio_result(
            query.message,
            context,
            user_id=user_id,
            lang=lang,
            product_context=ctx,
            result=current,
            audio_bytes=bytes(music_audio),
            job={},
            updated_by=user_id,
        )
        if delivered.get("ok"):
            return await query.message.reply_text(
                music_product_success_text(delivered.get("result") or current, int(delivered.get("charged_xu") or 0), lang),
                parse_mode="HTML",
                reply_markup=music_product_success_keyboard(lang, ctx),
            )
        return await query.message.reply_text(
            "⚠️ File nhạc đã tạo xong nhưng chưa gửi hoặc chưa xác nhận được thanh toán. TOAN AAS chưa trừ thêm Xu.",
            reply_markup=music_ai_status_keyboard(lang, ctx),
        )
    if not music_task_id:
        current.update({"music_status": "provider_no_job", "music_pending_charge_xu": 0, "music_charged_xu": 0})
        save_music_guided_result(user_id, current)
        return await query.message.reply_text(
            "⚙️ Chưa tạo được nhạc lúc này. TOAN AAS chưa trừ Xu, anh/chị thử lại sau nhé.",
            reply_markup=music_product_invoice_keyboard(current, lang, ctx),
        )
    music_job = create_music_suno_async_job(
        user_id=user_id,
        chat_id=query.message.chat_id,
        provider=str(submitted.get("provider") or ""),
        task_id=music_task_id,
        result=current,
        status="submitted",
        charged_xu=0,
        admin_test=bool(is_admin_user(user_id)),
    )
    current.update({
        "music_internal_job_id": str(music_job.get("internal_job_id") or ""),
        "music_job_id": str(music_job.get("internal_job_id") or ""),
        "music_status": "submitted",
        "music_submitted_at": now_text(),
        "music_result_delivery_lock": "pending",
    })
    save_music_guided_result(user_id, current)
    auto = await music_product_auto_deliver_job(
        query,
        context,
        user_id=user_id,
        lang=lang,
        product_context=ctx,
        result=current,
        internal_job_id=str(music_job.get("internal_job_id") or ""),
    )
    if auto.get("ok"):
        delivered_result = dict(auto.get("result") or get_music_guided_result(user_id) or current)
        return await query.message.reply_text(
            music_product_success_text(delivered_result, int(auto.get("charged_xu") or 0), lang),
            parse_mode="HTML",
            reply_markup=music_product_success_keyboard(lang, ctx),
        )
    return await query.message.reply_text(
        "⏳ TOAN AAS đang tạo nhạc. Khi có file, bot sẽ gửi kết quả cho anh/chị. TOAN AAS chưa trừ Xu cho đến khi file nhạc được gửi thành công.",
        reply_markup=music_ai_status_keyboard(lang, ctx),
    )

async def handle_music_quick_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    if not query:
        return
    raw_callback = str(query.data or "")
    canonical_callback = LEGACY_CANONICAL_CALLBACK_REDIRECTS.get(raw_callback, raw_callback)
    namespace, product_context, action = parse_product_context_callback(canonical_callback, PRODUCT_CONTEXT_SHOWROOM)
    user_id = update.effective_user.id if update.effective_user else 0
    lang = music_ui_lang(user_id)
    ctx = normalize_product_context(product_context)
    if ctx == PRODUCT_CONTEXT_VIDEO_ADDON:
        origin_screen = "vfinal|voice" if action.startswith("voice") else "vfinal|music"
    else:
        origin_screen = "menu|main"
    if namespace in {"music_quick", "sfx_quick", "media_quick"}:
        if action.startswith("voice"):
            product_area = "voice"
        elif namespace == "media_quick" or action == "media":
            product_area = "media"
        elif action == "translation_hub":
            product_area = "translation"
        else:
            product_area = "music"
        enter_product_context(user_id, ctx, origin_screen=origin_screen, product_area=product_area)
    if action == "root":
        await query.answer()
        clear_music_guided_pending(user_id)
        enter_product_context(user_id, ctx, origin_screen=origin_screen, product_area="voice_music")
        back_callback = "menu|main_video" if ctx == PRODUCT_CONTEXT_VIDEO_ADDON else "menu|main"
        return await query.message.reply_text(menu_text_main_music_i18n(lang), parse_mode="HTML", reply_markup=music_tools_keyboard(lang, back_callback))
    if action == "voice_hub":
        await query.answer()
        clear_music_guided_pending(user_id)
        enter_product_context(user_id, ctx, origin_screen="vfinal|voice" if ctx == PRODUCT_CONTEXT_VIDEO_ADDON else "menu|main", product_area="voice")
        return await query.message.reply_text(voice_hub_text(lang, ctx), parse_mode="HTML", reply_markup=voice_hub_keyboard(lang, ctx))
    if action == "music_hub":
        await query.answer()
        clear_music_guided_pending(user_id)
        enter_product_context(user_id, ctx, origin_screen="vfinal|music" if ctx == PRODUCT_CONTEXT_VIDEO_ADDON else "menu|main", product_area="music")
        return await query.message.reply_text(music_hub_text(lang, ctx), parse_mode="HTML", reply_markup=music_hub_keyboard(lang, ctx))
    if action == "translation_hub":
        await query.answer()
        clear_music_guided_pending(user_id)
        enter_product_context(user_id, PRODUCT_CONTEXT_SHOWROOM, origin_screen="menu|main", product_area="translation")
        return await query.message.reply_text(translation_menu_text(lang), parse_mode="HTML", reply_markup=translation_menu_keyboard(lang))
    if action == "music_none":
        await query.answer()
        if ctx == PRODUCT_CONTEXT_VIDEO_ADDON:
            update_video_finalization(user_id, music_enabled=False, music_mode="none", music_choice="none", music_prompt="", music_file_id="")
            return await video_finalization_return_after_addon(query, user_id, get_video_finalization_state(user_id), lang)
        result = get_music_guided_result(user_id) or {}
        result.update({"selected_music": "none", "music_is_free": True})
        save_music_guided_result(user_id, result)
        return await query.message.reply_text("🎵 Studio âm thanh là khu độc lập, không cần chọn “không thêm nhạc”. Quý khách có thể nghe thử, tạo prompt hoặc quay lại menu.", reply_markup=music_hub_keyboard(lang, PRODUCT_CONTEXT_SHOWROOM))
    if action == "prompt":
        await query.answer()
        clear_music_guided_pending(user_id)
        enter_product_context(user_id, ctx, origin_screen=origin_screen, product_area="music")
        return await query.message.reply_text(music_prompt_entry_text(lang), parse_mode="HTML", reply_markup=music_prompt_entry_keyboard(lang, ctx))
    if action == "prompt_custom":
        await query.answer()
        set_music_guided_pending(user_id, "music_prompt_input", product_context=ctx)
        enter_product_context(user_id, ctx, origin_screen=origin_screen, product_area="music")
        return await query.message.reply_text(music_prompt_input_text(lang), parse_mode="HTML", reply_markup=music_guided_back_keyboard(lang, ctx, "music_hub"))
    if action in {"prompt_seed", "prompt_seed_more"}:
        await query.answer()
        result = get_music_guided_result(user_id) or {}
        desc = result.get("description") or "video quảng cáo sản phẩm/dịch vụ, đăng TikTok/Reels, cần nhạc an toàn bản quyền"
        offset = (_safe_int(result.get("offset"), 0) + (3 if action == "prompt_seed_more" else 0)) % 6
        mode = str(result.get("music_ai_kind") or "")
        suggestions = music_prompt_suggestions(desc, offset, lang, mode)
        save_music_guided_result(user_id, {"description": desc, "offset": offset, "suggestions": suggestions, "selected_prompt": "", "music_ai_kind": mode})
        return await query.message.reply_text(music_prompt_suggestions_text(desc, offset, lang, mode), parse_mode="HTML", reply_markup=music_prompt_result_keyboard(lang, ctx, result))
    if action in {"voice", "voice_pick"}:
        await query.answer()
        current_pending = get_music_guided_pending(user_id) or {}
        if ctx == PRODUCT_CONTEXT_SHOWROOM and str(current_pending.get("pending_action") or "") in {"voice_text", "audio_voice_waiting_text"}:
            return await query.message.reply_text(
                "Bạn gửi nội dung cần đọc ở tin nhắn tiếp theo nhé." if lang == "vi" else "Please send the text to read in your next message.",
                reply_markup=music_guided_back_keyboard(lang, ctx, "root"),
            )
        set_music_guided_pending(user_id, "audio_voice_waiting_text", product_context=ctx)
        enter_product_context(user_id, ctx, origin_screen="vfinal|voice" if ctx == PRODUCT_CONTEXT_VIDEO_ADDON else "menu|main", product_area="voice")
        return await query.message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "root"))
    if action == "voice_tts_text":
        await query.answer()
        result = get_music_guided_result(user_id) or {}
        result.setdefault("tts_speed", "normal")
        save_music_guided_result(user_id, result)
        set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        enter_product_context(user_id, ctx, origin_screen="menu|main", product_area="voice")
        return await query.message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
    if action in {"voice_speed_slow", "voice_speed_normal", "voice_speed_fast"}:
        await query.answer()
        speed = action.rsplit("_", 1)[-1]
        result = get_music_guided_result(user_id) or {}
        result["tts_speed"] = speed
        save_music_guided_result(user_id, result)
        pending = get_music_guided_pending(user_id) or {}
        if not pending:
            set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
        label = {"slow": "đọc chậm", "normal": "bình thường", "fast": "đọc nhanh"}.get(speed, "bình thường")
        return await query.message.reply_text(
            f"✅ Đã chọn tốc độ {label}.\n\nBạn gửi văn bản cần đọc ở tin nhắn tiếp theo nhé.",
            reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"),
        )
    if action.startswith("voice_tts_settings_default:"):
        await query.answer()
        gender = default_voice_gender_from_kind(action.split(":", 1)[1])
        result = get_music_guided_result(user_id) or {}
        voice_text = str(result.get("voice_text") or "").strip()
        if not voice_text:
            set_music_guided_pending(user_id, "voice_tts_text_input", product_context=ctx)
            return await query.message.reply_text(voice_text_input_text(lang), parse_mode="HTML", reply_markup=voice_speed_keyboard(lang, ctx, "voice_hub"))
        return await show_voice_tts_settings_screen(query.message, user_id, "default", product_context=ctx, gender=gender, lang=lang)
    if action.startswith("voice_tts_settings_saved:"):
        await query.answer()
        profile_id = _safe_int(action.split(":", 1)[1], 0)
        profile = get_user_voice_profile(user_id, profile_id)
        result = get_music_guided_result(user_id) or {}
        voice_text = str(result.get("voice_text") or "").strip()
