MEDIA_PREVIEW_TTL_SECONDS = 600
MEDIA_PREVIEW_MAX_BYTES = 10 * 1024 * 1024
LAST_SFX_RESULTS: dict[int, dict] = {}
LAST_MUSIC_RESULTS: dict[int, dict] = {}
LAST_MEDIA_RESULTS: dict[int, dict] = {}
LAST_AUDIO_LINK: dict[int, dict] = {}
SELECTED_MUSIC: dict[int, dict] = {}
SELECTED_SFX: dict[int, dict] = {}
SELECTED_MEDIA: dict[int, dict] = {}
LAST_VIDEO_MUSIC_CONTEXT: dict[int, dict] = {}
LAST_VIDEO_PACKAGES: dict[int, dict] = {}
VIDEO_MUSIC_CONTEXT_TTL_SECONDS = 600
VIDEO_PACKAGE_TTL_SECONDS = 3600

def media_runtime_user_key(user_id):
    try:
        return int(user_id)
    except Exception:
        return str(user_id)

def set_video_music_context(user_id, source: str):
    if not user_id:
        return
    LAST_VIDEO_MUSIC_CONTEXT[media_runtime_user_key(user_id)] = {
        "source": str(source or "")[:40],
        "created_at": time.time(),
    }

def get_video_music_context(user_id) -> dict:
    if not user_id:
        return {}
    key = media_runtime_user_key(user_id)
    item = LAST_VIDEO_MUSIC_CONTEXT.get(key) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_at") or 0) > VIDEO_MUSIC_CONTEXT_TTL_SECONDS:
        LAST_VIDEO_MUSIC_CONTEXT.pop(key, None)
        return {}
    return item

def clear_video_music_context(user_id):
    if user_id:
        LAST_VIDEO_MUSIC_CONTEXT.pop(media_runtime_user_key(user_id), None)

def save_latest_video_package(user_id, package: dict) -> dict:
    if not user_id:
        return {}
    now_value = time.time()
    clean = dict(package or {})
    clean["user_id"] = str(user_id)
    clean["created_at"] = clean.get("created_at") or now_text()
    clean["created_ts"] = now_value
    clean["public_video_enabled"] = bool(SHOPAIKEY_PUBLIC_VIDEO_ENABLED)
    clean["package_id"] = clean.get("package_id") or f"vpack_{int(now_value)}_{str(user_id)[-6:]}"
    for key in ("concept_text", "image_prompt", "video_prompt"):
        if key in clean:
            clean[key] = str(clean.get(key) or "")[:2200]
    LAST_VIDEO_PACKAGES[media_runtime_user_key(user_id)] = clean
    return clean

def get_latest_video_package(user_id) -> dict:
    if not user_id:
        return {}
    key = media_runtime_user_key(user_id)
    item = LAST_VIDEO_PACKAGES.get(key) or {}
    if not item:
        return {}
    if time.time() - float(item.get("created_ts") or 0) > VIDEO_PACKAGE_TTL_SECONDS:
        LAST_VIDEO_PACKAGES.pop(key, None)
        return {}
    return item

def public_video_context_key(user_id) -> str:
    return f"public_video_context:{user_id}"

def set_public_video_package_context(user_id, package: dict) -> dict:
    clean = save_latest_video_package(user_id, package or {})
    if not clean:
        return {}
    USER_PENDING[public_video_context_key(user_id)] = {
        "pending_action": "public_video_context",
        "package": clean,
        "created_at_ts": time.time(),
    }
    return clean

def get_public_video_package_context(user_id) -> dict:
    key = public_video_context_key(user_id)
    pending = USER_PENDING.get(key) or {}
    if pending.get("pending_action") != "public_video_context":
        return {}
    if time.time() - float(pending.get("created_at_ts") or 0) > VIDEO_PACKAGE_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return {}
    return dict(pending.get("package") or {})

def clear_public_video_package_context(user_id) -> bool:
    return USER_PENDING.pop(public_video_context_key(user_id), None) is not None

def video_package_prompt(package: dict) -> str:
    for key in ("video_prompt", "prompt", "motion_prompt", "concept_text"):
        value = re.sub(r"\s+", " ", str((package or {}).get(key) or "").strip())
        if value:
            return value[:1200]
    return ""

def video_package_music_label(package: dict, lang: str = "vi") -> str:
    music = (package or {}).get("music_choice") or {}
    if (package or {}).get("no_music") or str(music.get("type") or "").lower() == "none":
        return "không" if normalize_user_language(lang) == "vi" else ("no" if normalize_user_language(lang) != "zh" else "无")
    label = str(music.get("label") or music.get("title") or music.get("provider") or "").strip()
    return label[:160] if label else ("có" if normalize_user_language(lang) == "vi" else ("yes" if normalize_user_language(lang) != "zh" else "有"))

