async def select_media_preview(update: Update, context: ContextTypes.DEFAULT_TYPE, kind: str, index_text: str):
    user_id = update.effective_user.id if update.effective_user else 0
    lang = music_ui_lang(user_id)
    item, error = get_media_preview_item(kind, user_id, index_text)
    chat_id = update.effective_chat.id if update.effective_chat else None
    if not chat_id:
        return
    if error == "expired":
        text = "⚠️ Preview results expired. Please search again with /sfx_library or /music_library." if lang == "en" else ("⚠️ 试听结果已过期。请使用 /sfx_library 或 /music_library 重新查找。" if lang == "zh" else "⚠️ Kết quả nghe thử đã hết hạn. Vui lòng tìm lại bằng /sfx_library hoặc /music_library.")
        return await context.bot.send_message(chat_id=chat_id, text=text)
    if error or not item:
        text = "⚠️ Result number not found. Please choose a number from your latest search list." if lang == "en" else ("⚠️ 未找到这个编号。请从刚才的搜索结果中选择编号。" if lang == "zh" else "⚠️ Không tìm thấy kết quả số này. Vui lòng chọn số từ danh sách vừa tìm.")
        return await context.bot.send_message(chat_id=chat_id, text=text)
    selected = dict(item)
    selected["created_at"] = time.time()
    if current_product_context(user_id) == PRODUCT_CONTEXT_VIDEO_ADDON and kind in {"music", "sfx"}:
        selected_for_video = {
            "provider": selected.get("provider") or "",
            "title": selected.get("title") or "",
            "author": selected.get("author") or "",
            "duration": selected.get("duration") or "",
            "license": selected.get("license") or "",
            "source_url": selected.get("source_url") or "",
            "created_at": selected.get("created_at") or time.time(),
        }
        music_mode = "sfx_library" if kind == "sfx" else "library"
        if kind == "sfx":
            SELECTED_SFX[int(user_id)] = selected
        else:
            SELECTED_MUSIC[int(user_id)] = selected
        video_state = get_video_finalization_state(user_id)
        if video_state:
            update_video_finalization(
                user_id,
                music_enabled=True,
                music_mode=music_mode,
                music_choice="stock_sfx" if kind == "sfx" else "stock_music",
                music_prompt=str(selected.get("title") or "")[:300],
                music_item_count=1,
                music_selected_item=selected_for_video,
            )
            if update.callback_query:
                return await video_finalization_return_after_addon(update.callback_query, user_id, get_video_finalization_state(user_id), lang)
            return await context.bot.send_message(
                chat_id=chat_id,
                text=f"✅ Đã chọn {'SFX' if kind == 'sfx' else 'nhạc'} miễn phí cho video hiện tại. Gói, thời lượng và file nguồn vẫn được giữ nguyên.",
            )
        addon_state = get_video_addon_state(user_id)
        if addon_state:
            addon_state["current_video_music_option"] = music_mode
            addon_state["current_video_music_choice"] = "stock_sfx" if kind == "sfx" else "stock_music"
            addon_state["current_video_music_item_count"] = 1
            addon_state["current_video_music_selected_item"] = selected_for_video
            set_video_addon_state(user_id, addon_state)
            if update.callback_query:
                return await finalize_video_addon_confirmation(update.callback_query, user_id, get_video_addon_state(user_id), lang)
            return await context.bot.send_message(
                chat_id=chat_id,
                text=f"✅ Đã chọn {'SFX' if kind == 'sfx' else 'nhạc'} miễn phí cho video hiện tại. Hóa đơn video vẫn giữ gói, thời lượng và file nguồn.",
            )
    if kind == "sfx":
        SELECTED_SFX[int(user_id)] = selected
        noun = "SFX" if lang != "zh" else "音效"
        cmd_label = "/select_sfx"
    else:
        SELECTED_MUSIC[int(user_id)] = selected
        noun = "music" if lang == "en" else ("音乐" if lang == "zh" else "nhạc")
        cmd_label = "/select_music"
        flow_context = get_video_music_context(user_id)
        if flow_context:
            selected_for_video = {
                "provider": selected.get("provider") or "",
                "title": selected.get("title") or "",
                "author": selected.get("author") or "",
                "duration": selected.get("duration") or "",
                "license": selected.get("license") or "",
                "source_url": selected.get("source_url") or "",
                "created_at": selected.get("created_at") or time.time(),
            }
            if str(flow_context.get("source") or "") == "trend_guided":
                set_trend_video_flow_pending(user_id, "music_selected", music_choice="library", music_selected_item=selected_for_video)
            else:
                concept = get_latest_cinematic_ad_concept(user_id)
