async def send_media_library_results(message, user_id, query: str):
    lang = music_ui_lang(user_id)
    if not PIXABAY_API_KEY:
        text = "⚠️ Media library is not ready yet.\nThe bot has not charged Xu." if lang == "en" else ("⚠️ 媒体库暂时不可用。\n本次未扣除 Xu。" if lang == "zh" else "⚠️ Kho media đang tạm chưa sẵn sàng. Bot chưa trừ Xu.")
        return await message.reply_text(text)
    try:
        images, videos = await fetch_pixabay_media(query, limit=5)
    except Exception as e:
        record_api_debug("pixabay", "media_library", "FAIL", 0, provider_error_summary(e))
        return await message.reply_text(music_provider_error_text(lang))
    record_api_debug("pixabay", "media_library", "PASS" if (images or videos) else "EMPTY", 200, f"images={len(images)} videos={len(videos)}")
    save_tool_test_result("media_library", "PASS" if (images or videos) else "EMPTY", f"query={query[:80]}; images={len(images)} videos={len(videos)}", user_id)
    if not images and not videos:
        text = "⚠️ No suitable media found. Try another keyword.\nThe bot has not charged Xu." if lang == "en" else ("⚠️ 未找到合适的媒体素材。请尝试其他关键词。\n本次未扣除 Xu。" if lang == "zh" else "⚠️ Chưa tìm thấy media phù hợp. Bot chưa trừ Xu.")
        return await message.reply_text(text)
    title = "🖼 <b>Media library / Pixabay</b>" if lang == "en" else ("🖼 <b>媒体库 / Pixabay</b>" if lang == "zh" else "🖼 <b>Kho media Pixabay</b>")
    lines = [
        f"{title} — <code>{html.escape(query[:80])}</code>",
        "",
    ]
    media_items: list[dict] = []
    display_images = images[:5]
    remaining_video_slots = max(0, 5 - len(display_images))
    for idx, item in enumerate(display_images, start=1):
        lines.append(format_pixabay_image(item, idx, lang))
        media_items.append(pixabay_image_preview_item(item))
    offset = len(display_images)
    for idx, item in enumerate(videos[:remaining_video_slots], start=offset + 1):
        lines.append(format_pixabay_video(item, idx, lang))
        media_items.append(pixabay_video_preview_item(item))
    lines.extend([
        "",
        f"📜 {music_license_notice_text(lang)}",
        music_no_xu_text(lang),
    ])
    await message.reply_text("\n".join(lines), parse_mode="HTML", disable_web_page_preview=True)
    save_pixabay_media_results(user_id, query, media_items)
    kb = pixabay_media_keyboard(media_items, lang)
    if kb:
        prompt = "🖼 Preview/select media quickly:" if lang == "en" else ("🖼 快速查看/选择素材:" if lang == "zh" else "🖼 Xem/chọn media nhanh:")
        await message.reply_text(prompt, reply_markup=kb)

async def cmd_media_library(update: Update, context: ContextTypes.DEFAULT_TYPE):
    lang = music_ui_lang(update.effective_user.id if update.effective_user else 0)
    query = " ".join(context.args or []).strip()
    if not query:
        return await update.message.reply_text(media_library_guide_text(lang), parse_mode="HTML", reply_markup=media_library_quick_keyboard(lang))
    return await send_media_library_results(update.message, update.effective_user.id, query)

def normalize_music_inline_command_text(text: str) -> str:
    raw = (text or "").strip()
    if not raw:
        return ""
    bot_name = str(BOT_USERNAME or "toanaasbot").lstrip("@").lower()
    lowered = raw.lower()
    mention_prefix = f"@{bot_name} "
    if lowered.startswith(mention_prefix):
        raw = raw.split(None, 1)[1].strip() if len(raw.split(None, 1)) > 1 else ""
    if not raw.startswith("/"):
        return ""
    first, *rest = raw.split(maxsplit=1)
    if "@" in first:
        command_name, mention = first.split("@", 1)
        if mention.lower() != bot_name:
            return ""
        first = command_name
    return first + (f" {rest[0]}" if rest else "")

async def dispatch_music_inline_command(update: Update, context: ContextTypes.DEFAULT_TYPE, command_text: str) -> bool:
    raw = (command_text or "").strip()
    if not raw.startswith("/"):
        return False
    first, *rest = raw.split(maxsplit=1)
    command = first.lstrip("/").split("@", 1)[0].lower()
    handler_map = {
        "music_prompt": cmd_music_prompt,
        "music_library": cmd_music_library,
        "sfx_library": cmd_sfx_library,
        "media_library": cmd_media_library,
    }
    handler = handler_map.get(command)
    if not handler:
        return False
    old_args = getattr(context, "args", None)
    try:
        context.args = (rest[0].split() if rest else [])
        await handler(update, context)
    finally:
        context.args = old_args
    return True

async def handle_music_guided_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    state = get_music_guided_pending(uid)
    if not state:
        return False
    lang = music_ui_lang(uid)
    action = str(state.get("pending_action") or "")
    ctx = normalize_product_context(state.get("product_context"), PRODUCT_CONTEXT_SHOWROOM)
    text_limit = 3500 if action in {"music_product_background_details", "music_product_song_details"} else 900
    if action in {"music_product_background_details", "music_product_song_details"}:
        text = str(update.message.text or "").strip()[:text_limit]
    else:
        text = _short_pending_text(update.message.text, text_limit)
    if not text or text.startswith("/"):
        return False
    clear_music_guided_pending(uid)
    if action in {"music_product_background_idea", "music_product_song_idea"}:
        result = get_music_guided_result(uid) or {}
        mode = "song" if action == "music_product_song_idea" else "background"
        tier = normalize_music_product_tier(result.get("music_product_tier") or state.get("music_product_tier"))
        vocal_mode = normalize_song_vocal_mode(result.get("song_vocal") or result.get("vocal_mode") or state.get("vocal_mode") or "auto")
        blocked = music_copyright_block_reason(text)
        if blocked:
            set_music_guided_pending(uid, action, product_context=ctx, previous_screen=str(state.get("previous_screen") or ""), return_to=str(state.get("return_to") or "music_product_back_idea"))
            await update.message.reply_text(
                "⛔ Nội dung này có rủi ro bản quyền. Hãy dùng ý tưởng nguyên bản. TOAN AAS chưa xử lý và chưa trừ Xu.",
                reply_markup=music_product_idea_keyboard(mode, lang, ctx),
            )
            return True
        result.update({
            "music_product_flow": "p0_20b1_suggestions",
            "music_product_mode": mode,
            "music_product_tier": tier,
            "music_product_price_xu": music_product_tier_price_xu(tier, mode),
            "vocal_mode": vocal_mode,
            "song_vocal": vocal_mode if mode == "song" else "",
        })
        product_result = music_product_prepare_suggestions_result(result, idea=text, offset=0, lang=lang)
        save_music_guided_result(uid, product_result)
        await update.message.reply_text(
            music_product_suggestions_text(product_result, lang),
            parse_mode="HTML",
            reply_markup=music_product_suggestions_keyboard(mode, lang, ctx),
        )
        return True
    if action in {"music_product_background_details", "music_product_song_details"}:
        result = get_music_guided_result(uid) or {}
        mode = "song" if action == "music_product_song_details" else "background"
        tier = normalize_music_product_tier(result.get("music_product_tier") or state.get("music_product_tier"))
        vocal_mode = normalize_song_vocal_mode(result.get("song_vocal") or result.get("vocal_mode") or state.get("vocal_mode") or "auto")
