def parse_mark_payos_test_args(args: list[str]) -> tuple[str, str, str]:
    raw = " ".join(args or []).strip()
    action = (args[0].lower() if args else "").strip()
    order = ""
    note = ""
    order_match = re.search(r"\border=([^\s]+)", raw)
    if order_match:
        order = order_match.group(1).strip().strip("\"'")
    note_match = re.search(r"\bnote=(.+)$", raw)
    if note_match:
        note = note_match.group(1).strip().strip("\"'")
    return action, order, note

async def cmd_mark_payos_test(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    action, order, note = parse_mark_payos_test_args(context.args)
    if action not in {"pass", "fail", "reset"}:
        return await update.message.reply_text(
            "⚠️ Cú pháp:\n"
            "<code>/mark_payos_test pass order=123456 note=\"Test 10k OK\"</code>\n"
            "<code>/mark_payos_test fail note=\"Webhook chưa về\"</code>\n"
            "<code>/mark_payos_test reset</code>",
            parse_mode="HTML",
        )
    status = "NOT_TESTED" if action == "reset" else action.upper()
    marked_at = now_text()
    set_system_setting("payos_real_payment_test_status", status, note, update.effective_user.id)
    set_system_setting("payos_real_payment_test_at", marked_at, note, update.effective_user.id)
    set_system_setting("payos_real_payment_test_order", order, note, update.effective_user.id)
    set_system_setting("payos_real_payment_test_note", note, note, update.effective_user.id)
    record_audit_event(
        update.effective_user.id,
        "admin",
        "payos.real_test_marked",
        "system_setting",
        "payos_real_payment_test_status",
        before=None,
        after={"status": status, "order": order, "marked_at": marked_at},
        note=note,
    )
    await update.message.reply_text(
        "✅ <b>Đã ghi nhận PayOS real payment test</b>\n\n"
        f"• Status: <code>{html.escape(status)}</code>\n"
        f"• At: <code>{html.escape(marked_at)}</code>\n"
        f"• Order: <code>{html.escape(order or '-')}</code>\n"
        f"• Note: <code>{html.escape(note or '-')}</code>\n\n"
        "Kiểm tra lại: <code>/sales_ready</code>",
        parse_mode="HTML",
    )

def _report_dt_text(dt: datetime) -> str:
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def report_period_bounds(period: str) -> tuple[str, str, str]:
    now = datetime.now()
    period = str(period or "today").lower().strip()
    if period == "week":
        start = datetime(now.year, now.month, now.day) - timedelta(days=6)
        label = "7 ngày gần nhất"
    elif period == "month":
        start = datetime(now.year, now.month, 1)
        label = f"Tháng {now.month:02d}/{now.year}"
    elif period == "year":
        start = datetime(now.year, 1, 1)
        label = f"Năm {now.year}"
    else:
        start = datetime(now.year, now.month, now.day)
        label = "Hôm nay"
    return _report_dt_text(start), _report_dt_text(now), label

def report_range_bounds(args) -> tuple[str, str, str] | None:
    if len(args) < 2:
        return None
    try:
        start = datetime.strptime(args[0], "%Y-%m-%d")
        end = datetime.strptime(args[1], "%Y-%m-%d") + timedelta(days=1) - timedelta(seconds=1)
        if end < start:
            return None
        return _report_dt_text(start), _report_dt_text(end), f"{args[0]} → {args[1]}"
    except Exception:
        return None

def sql_scalar(conn, query: str, params=(), default=0):
    try:
        row = conn.execute(query, params).fetchone()
        if not row or row[0] is None:
            return default
        return row[0]
    except Exception:
        return default

def sql_rows(conn, query: str, params=()):
    try:
        return conn.execute(query, params).fetchall()
    except Exception:
        return []

def vnd_text(value) -> str:
    return f"{int(value or 0):,}đ".replace(",", ".")

def xu_text(value) -> str:
    return f"{int(value or 0):,} Xu".replace(",", ".")

FINANCE_EXPENSE_CATEGORIES = {
    "provider_ai",
    "railway_hosting",
    "domain_hosting",
    "software_subscription",
    "marketing_ads",
    "content_affiliate",
    "staff_freelancer",
    "office_equipment",
    "internet_phone",
    "bank_payment_fee",
    "refund_customer",
    "legal_tax_accounting",
    "other",
} | set(OPERATIONS_EXPENSE_CATEGORIES)

FINANCE_INVOICE_STATUSES = {"invoice_ok", "receipt_only", "screenshot_only", "no_document", "internal_only"}

def finance_tracking_start_text() -> str:
    raw = str(FINANCE_TRACKING_START_DATE or "").strip()
    try:
        return datetime.strptime(raw[:10], "%Y-%m-%d").strftime("%Y-%m-%d")
    except Exception:
        return datetime.now(VN_TZ).strftime("%Y-%m-%d")

def finance_period_bounds(raw: str = "", default_period: str = "month") -> tuple[str, str, str, str]:
    value = str(raw or "").strip()
    now = datetime.now()
    if value.lower() in {"today", "day"}:
        dt = datetime(now.year, now.month, now.day)
        return _report_dt_text(dt), _report_dt_text(dt + timedelta(days=1) - timedelta(seconds=1)), "Hôm nay", "day"
    if re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
        dt = datetime.strptime(value, "%Y-%m-%d")
        return _report_dt_text(dt), _report_dt_text(dt + timedelta(days=1) - timedelta(seconds=1)), f"Ngày {value}", "day"
    if re.fullmatch(r"\d{4}-\d{2}", value):
        start_at, end_at, label = month_report_bounds(value)
        return start_at, end_at, label, "month"
    if re.fullmatch(r"\d{4}", value):
        start_at, end_at, label = year_report_bounds(value)
        return start_at, end_at, label, "year"
    if value:
        raise ValueError("invalid_finance_period")
    if default_period == "year":
        start_at, end_at, label = year_report_bounds("")
        return start_at, end_at, label, "year"
    if default_period == "day":
        dt = datetime(now.year, now.month, now.day)
        return _report_dt_text(dt), _report_dt_text(now), "Hôm nay", "day"
    start_at, end_at, label = month_report_bounds("")
    return start_at, end_at, label, "month"

def finance_credit_service_type(event_type: str, note: str = "") -> str:
    value = f"{event_type or ''} {note or ''}".lower()
    if "frame_video" in value:
        return "frame_video"
    if "storyboard" in value:
        return "storyboard_image"
    if "video" in value:
        return "video_ai"
    if "image" in value or "shopaikey_image" in value or "ai_image" in value:
        return "image"
    if "chat" in value or "ai_chat" in value:
        return "chat"
    if "voice" in value or "tts" in value:
        return "tts"
    if "music" in value or "sfx" in value:
        return "music"
    if "package" in value or "combo" in value:
        return "combo_usage"
    if "admin" in value or "deduct" in value:
        return "admin_adjust"
    return "other"

def record_finance_revenue_event_conn(
    conn,
    user_id,
    source_type: str,
    source_id: str,
    amount_vnd: int,
    xu_credited: int = 0,
    payment_method: str = "",
    status: str = "success",
    note: str = "",
    created_by_admin_id: str = "",
    created_at: str = "",
) -> None:
    try:
        source_type = str(source_type or "manual_revenue").strip()[:80]
        source_id = str(source_id or "").strip()[:160]
        if not source_id:
            source_id = f"{source_type}:{user_id}:{amount_vnd}:{now_text()}"
        conn.execute(
            """INSERT OR IGNORE INTO finance_revenue_events
            (created_at, user_id, source_type, source_id, amount_vnd, xu_credited, payment_method, status, note, created_by_admin_id)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                created_at or now_text(),
                str(user_id or ""),
                source_type,
                source_id,
                int(amount_vnd or 0),
                int(xu_credited or 0),
                str(payment_method or "")[:80],
                str(status or "success")[:40],
                sanitize_log_text(str(note or ""))[:1000],
                str(created_by_admin_id or "")[:80],
            ),
        )
    except Exception as e:
        logger.warning(f"Finance revenue write failed: {e}")

def record_finance_usage_event_conn(
    conn,
    user_id,
    service_type: str,
    xu_spent: int,
    job_id: str = "",
    package_id: str = "",
    provider: str = "",
    provider_cost_estimate_vnd: int = 0,
    status: str = "success",
    note: str = "",
    created_at: str = "",
) -> None:
    try:
        conn.execute(
            """INSERT INTO finance_usage_events
            (created_at, user_id, service_type, job_id, xu_spent, package_id, provider, provider_cost_estimate_vnd, status, note)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                created_at or now_text(),
                str(user_id or ""),
                str(service_type or "other")[:80],
                str(job_id or "")[:120],
                int(xu_spent or 0),
                str(package_id or "")[:120],
                str(provider or "")[:80],
                int(provider_cost_estimate_vnd or 0),
                str(status or "success")[:40],
                sanitize_log_text(str(note or ""))[:1000],
            ),
        )
    except Exception as e:
        logger.warning(f"Finance usage write failed: {e}")

def record_finance_usage_from_credit_event_conn(conn, user_id, delta, event_type, ref_id="", note="") -> None:
    try:
        delta = int(delta or 0)
        event = str(event_type or "")
        if delta < 0:
            record_finance_usage_event_conn(
                conn,
                user_id,
                finance_credit_service_type(event, note),
                abs(delta),
                job_id=str(ref_id or ""),
                status="success",
                note=f"credit_event={event}; {note or ''}",
            )
        elif delta > 0 and "refund" in event.lower():
            record_finance_usage_event_conn(
                conn,
                user_id,
                finance_credit_service_type(event, note),
                -abs(delta),
                job_id=str(ref_id or ""),
                status="refunded",
                note=f"credit_event={event}; {note or ''}",
            )
    except Exception as e:
        logger.warning(f"Finance usage from credit event failed: {e}")

def add_finance_expense(
    amount_vnd: int,
    category: str,
    vendor: str,
    note: str,
    admin_id,
    pre_establishment: bool = False,
    expense_date: str = "",
    payment_method: str = "manual",
    invoice_status: str = "internal_only",
    is_recurring: bool = False,
    evidence_note: str = "",
) -> int:
    category = str(category or "other").strip().lower()
    if category not in FINANCE_EXPENSE_CATEGORIES:
        category = "other"
    invoice_status = str(invoice_status or "internal_only").strip().lower()
    if invoice_status not in FINANCE_INVOICE_STATUSES:
        invoice_status = "internal_only"
    if not expense_date:
        expense_date = datetime.now(VN_TZ).strftime("%Y-%m-%d")
    conn = db_connect()
    try:
        cur = conn.cursor()
        cur.execute(
            """INSERT INTO finance_expense_events
            (expense_date, created_at, amount_vnd, category, vendor, payment_method, invoice_status,
             is_pre_establishment, is_recurring, note, evidence_folder_or_file_note, created_by_admin_id)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?)""",
            (
                str(expense_date)[:10],
                now_text(),
                int(amount_vnd or 0),
                category,
                str(vendor or "")[:160],
                str(payment_method or "manual")[:80],
                invoice_status,
                1 if pre_establishment else 0,
                1 if is_recurring else 0,
                sanitize_log_text(str(note or ""))[:1000],
                sanitize_log_text(str(evidence_note or ""))[:500],
                str(admin_id or ""),
            ),
        )
        conn.commit()
        return int(cur.lastrowid)
    finally:
        conn.close()

def finance_summary_payload(start_at: str, end_at: str, label: str) -> dict:
    conn = db_connect()
    try:
        revenue_success = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(amount_vnd),0) FROM finance_revenue_events WHERE status='success' AND created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0)
        revenue_count = int(sql_scalar(
            conn,
            "SELECT COUNT(*) FROM finance_revenue_events WHERE status='success' AND created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0)
        xu_credited = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(xu_credited),0) FROM finance_revenue_events WHERE status='success' AND created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0)
        revenue_by_source = sql_rows(
            conn,
            """SELECT source_type, COUNT(*), COALESCE(SUM(amount_vnd),0), COALESCE(SUM(xu_credited),0)
            FROM finance_revenue_events
            WHERE status='success' AND created_at BETWEEN ? AND ?
            GROUP BY source_type ORDER BY SUM(amount_vnd) DESC""",
            (start_at, end_at),
        )
        expenses_after = int(sql_scalar(
            conn,
            """SELECT COALESCE(SUM(amount_vnd),0) FROM finance_expense_events
            WHERE COALESCE(deleted_at,'')='' AND COALESCE(is_pre_establishment,0)=0 AND expense_date BETWEEN ? AND ?""",
            (start_at[:10], end_at[:10]),
            0,
        ) or 0)
        expenses_pre_period = int(sql_scalar(
            conn,
            """SELECT COALESCE(SUM(amount_vnd),0) FROM finance_expense_events
            WHERE COALESCE(deleted_at,'')='' AND COALESCE(is_pre_establishment,0)=1 AND expense_date BETWEEN ? AND ?""",
            (start_at[:10], end_at[:10]),
            0,
        ) or 0)
        expenses_pre_total = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(amount_vnd),0) FROM finance_expense_events WHERE COALESCE(deleted_at,'')='' AND COALESCE(is_pre_establishment,0)=1",
            default=0,
        ) or 0)
        expense_count = int(sql_scalar(
            conn,
            "SELECT COUNT(*) FROM finance_expense_events WHERE COALESCE(deleted_at,'')='' AND expense_date BETWEEN ? AND ?",
            (start_at[:10], end_at[:10]),
            0,
        ) or 0)
        expenses_by_category = sql_rows(
            conn,
            """SELECT category, COUNT(*), COALESCE(SUM(amount_vnd),0)
            FROM finance_expense_events
            WHERE COALESCE(deleted_at,'')='' AND expense_date BETWEEN ? AND ?
            GROUP BY category ORDER BY SUM(amount_vnd) DESC""",
            (start_at[:10], end_at[:10]),
        )
        xu_spent = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(xu_spent),0) FROM finance_usage_events WHERE status='success' AND created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0)
        xu_refunded = abs(int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(xu_spent),0) FROM finance_usage_events WHERE status='refunded' AND created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0))
        provider_cost_estimate = int(sql_scalar(
            conn,
            "SELECT COALESCE(SUM(provider_cost_estimate_vnd),0) FROM finance_usage_events WHERE created_at BETWEEN ? AND ?",
            (start_at, end_at),
            0,
        ) or 0)
        usage_by_service = sql_rows(
            conn,
            """SELECT service_type, COUNT(*), COALESCE(SUM(xu_spent),0)
            FROM finance_usage_events
            WHERE status='success' AND created_at BETWEEN ? AND ?
            GROUP BY service_type ORDER BY SUM(xu_spent) DESC, COUNT(*) DESC""",
            (start_at, end_at),
        )
        tax_reserve = int(round(revenue_success * float(TAX_RESERVE_RATE or 0)))
        profit_management = revenue_success - expenses_after - expenses_pre_period - provider_cost_estimate - tax_reserve
        profit_operating = revenue_success - expenses_after - provider_cost_estimate - tax_reserve
        return {
            "label": label,
            "start_at": start_at,
            "end_at": end_at,
            "tracking_start_date": finance_tracking_start_text(),
            "tax_reserve_rate": float(TAX_RESERVE_RATE or 0),
            "revenue_success": revenue_success,
            "revenue_count": revenue_count,
            "xu_credited": xu_credited,
            "revenue_by_source": revenue_by_source,
            "expenses_after": expenses_after,
            "expenses_pre_period": expenses_pre_period,
            "expenses_pre_total": expenses_pre_total,
            "expense_count": expense_count,
            "expenses_by_category": expenses_by_category,
            "xu_spent": xu_spent,
            "xu_refunded": xu_refunded,
            "provider_cost_estimate": provider_cost_estimate,
            "usage_by_service": usage_by_service,
            "tax_reserve": tax_reserve,
            "profit_management": profit_management,
            "profit_operating": profit_operating,
        }
    finally:
        conn.close()

def finance_report_text(payload: dict, report_type: str = "dashboard") -> str:
    usage_lines = [
        f"• {html.escape(str(service or 'other'))}: <b>{int(count or 0)}</b> job/lượt / <b>{xu_text(xu)}</b>"
        for service, count, xu in payload.get("usage_by_service", [])[:8]
    ]
    source_lines = [
        f"• {html.escape(str(source or 'unknown'))}: <b>{vnd_text(amount)}</b> ({int(count or 0)} đơn, {xu_text(xu)})"
        for source, count, amount, xu in payload.get("revenue_by_source", [])[:8]
    ]
    expense_lines = [
        f"• {html.escape(str(category or 'other'))}: <b>{vnd_text(amount)}</b> ({int(count or 0)} khoản)"
        for category, count, amount in payload.get("expenses_by_category", [])[:8]
    ]
    lines = [
        "💰 <b>TOAN AAS — Tài chính nội bộ</b>",
        f"• Kỳ: <code>{html.escape(payload.get('label') or '')}</code>",
        f"• Từ <code>{html.escape(payload.get('start_at') or '')}</code> đến <code>{html.escape(payload.get('end_at') or '')}</code>",
        f"• Ngày bắt đầu ghi nhận: <code>{html.escape(payload.get('tracking_start_date') or '')}</code>",
        "",
        "<b>Doanh thu tiền thật</b>",
        f"• Tiền nạp/thanh toán thành công: <b>{vnd_text(payload.get('revenue_success'))}</b>",
        f"• Số giao dịch: <b>{int(payload.get('revenue_count') or 0)}</b>",
        f"• Xu đã phát hành theo doanh thu: <b>{xu_text(payload.get('xu_credited'))}</b>",
    ]
    if source_lines:
        lines.extend(source_lines)
    lines.extend([
        "",
        "<b>Xu tiêu dùng / dịch vụ</b>",
        f"• Xu khách đã dùng: <b>{xu_text(payload.get('xu_spent'))}</b>",
        f"• Xu đã hoàn trong kỳ: <b>{xu_text(payload.get('xu_refunded'))}</b>",
    ])
    if usage_lines:
        lines.extend(usage_lines)
    lines.extend([
        "",
        "<b>Chi phí</b>",
        f"• Chi phí sau vận hành: <b>{vnd_text(payload.get('expenses_after'))}</b>",
        f"• Chi phí trước thành lập trong kỳ: <b>{vnd_text(payload.get('expenses_pre_period'))}</b>",
        f"• Tổng chi phí trước thành lập đã ghi nhận: <b>{vnd_text(payload.get('expenses_pre_total'))}</b>",
        f"• Provider cost ước tính: <b>{vnd_text(payload.get('provider_cost_estimate'))}</b>",
        f"• Số khoản chi: <b>{int(payload.get('expense_count') or 0)}</b>",
    ])
    if expense_lines:
        lines.extend(expense_lines)
    lines.extend([
        "",
        "<b>Lãi/lỗ ước tính</b>",
        f"• Thuế dự phòng ({float(payload.get('tax_reserve_rate') or 0):.2%}): <b>{vnd_text(payload.get('tax_reserve'))}</b>",
        f"• Lãi/lỗ vận hành: <b>{vnd_text(payload.get('profit_operating'))}</b>",
        f"• Lãi/lỗ quản trị gồm chi phí trước thành lập trong kỳ: <b>{vnd_text(payload.get('profit_management'))}</b>",
        "",
        "Lưu ý: Báo cáo này phục vụ quản trị nội bộ. Số liệu thuế chính thức cần đối chiếu hóa đơn/chứng từ và quy định thuế.",
    ])
    if report_type == "export_hint":
        lines.append("Export CSV: <code>/finance_export YYYY-MM</code> hoặc <code>/finance_export YYYY</code>")
    return "\n".join(lines)

def finance_csv(kind: str, start_at: str, end_at: str) -> str:
    buffer = io.StringIO()
    writer = csv.writer(buffer)
    writer.writerow(["TOAN AAS finance export", kind, start_at, end_at])
    conn = db_connect()
    try:
        if kind == "revenue":
            writer.writerow(["id", "created_at", "user_id", "source_type", "source_id", "amount_vnd", "xu_credited", "payment_method", "status", "note", "created_by_admin_id"])
            rows = sql_rows(
                conn,
                """SELECT id,created_at,user_id,source_type,source_id,amount_vnd,xu_credited,payment_method,status,note,created_by_admin_id
                FROM finance_revenue_events WHERE created_at BETWEEN ? AND ? ORDER BY created_at,id""",
                (start_at, end_at),
            )
        elif kind == "expenses":
            writer.writerow(["id", "expense_date", "created_at", "amount_vnd", "category", "vendor", "payment_method", "invoice_status", "is_pre_establishment", "is_recurring", "note", "evidence", "created_by_admin_id", "deleted_at", "delete_reason"])
            rows = sql_rows(
                conn,
                """SELECT id,expense_date,created_at,amount_vnd,category,vendor,payment_method,invoice_status,is_pre_establishment,is_recurring,note,evidence_folder_or_file_note,created_by_admin_id,deleted_at,delete_reason
                FROM finance_expense_events WHERE expense_date BETWEEN ? AND ? ORDER BY expense_date,id""",
                (start_at[:10], end_at[:10]),
            )
        else:
            writer.writerow(["id", "created_at", "user_id", "service_type", "job_id", "xu_spent", "package_id", "provider", "provider_cost_estimate_vnd", "status", "note"])
            rows = sql_rows(
                conn,
                """SELECT id,created_at,user_id,service_type,job_id,xu_spent,package_id,provider,provider_cost_estimate_vnd,status,note
                FROM finance_usage_events WHERE created_at BETWEEN ? AND ? ORDER BY created_at,id""",
                (start_at, end_at),
            )
        for row in rows:
            writer.writerow(list(row))
        return buffer.getvalue()
    finally:
        conn.close()

def tax_quarter_bounds(now: datetime | None = None) -> tuple[str, str, str, str]:
    current = now or datetime.now()
    quarter = ((current.month - 1) // 3) + 1
    first_month = (quarter - 1) * 3 + 1
    start = datetime(current.year, first_month, 1)
    if quarter == 4:
        next_quarter = datetime(current.year + 1, 1, 1)
    else:
        next_quarter = datetime(current.year, first_month + 3, 1)
    end = next_quarter - timedelta(seconds=1)
    return _report_dt_text(start), _report_dt_text(end), f"Quý {quarter}/{current.year}", f"{current.year}_Q{quarter}"

def get_tax_profile(admin_id) -> dict:
    admin_id = str(admin_id or ADMIN_ID or "default")
    conn = db_connect()
    try:
        conn.execute(
            """INSERT OR IGNORE INTO tax_profiles
            (owner_admin_id, business_type, tax_method, vat_rate_percent, pit_rate_percent,
             revenue_threshold_vnd, license_fee_enabled, license_fee_amount_vnd,
             effective_from, effective_to, note, created_at, updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
            (admin_id, "", "manual_config", 0, 0, 0, 0, 0, "", "", "", now_text(), now_text()),
        )
        conn.commit()
        row = conn.execute(
            """SELECT owner_admin_id,business_type,tax_method,vat_rate_percent,pit_rate_percent,
                      revenue_threshold_vnd,license_fee_enabled,license_fee_amount_vnd,
                      effective_from,effective_to,note,created_at,updated_at
               FROM tax_profiles WHERE owner_admin_id=?""",
            (admin_id,),
        ).fetchone()
        keys = [
            "owner_admin_id", "business_type", "tax_method", "vat_rate_percent", "pit_rate_percent",
            "revenue_threshold_vnd", "license_fee_enabled", "license_fee_amount_vnd",
            "effective_from", "effective_to", "note", "created_at", "updated_at",
        ]
        payload = dict(zip(keys, row or []))
        payload["license_fee_enabled"] = bool(int(payload.get("license_fee_enabled") or 0))
        return payload
    finally:
        conn.close()

def update_tax_profile(admin_id, updates: dict) -> dict:
    allowed = {
        "business_type", "tax_method", "vat_rate_percent", "pit_rate_percent",
        "revenue_threshold_vnd", "license_fee_enabled", "license_fee_amount_vnd",
        "effective_from", "effective_to", "note",
    }
    clean = {key: value for key, value in dict(updates or {}).items() if key in allowed}
    get_tax_profile(admin_id)
    if not clean:
        return get_tax_profile(admin_id)
    assignments = ", ".join(f"{key}=?" for key in clean)
    values = list(clean.values()) + [now_text(), str(admin_id or ADMIN_ID or "default")]
    conn = db_connect()
    try:
        conn.execute(f"UPDATE tax_profiles SET {assignments}, updated_at=? WHERE owner_admin_id=?", values)
        conn.commit()
    finally:
        conn.close()
    return get_tax_profile(admin_id)

FINANCE_COMPLIANCE_STATUS_LABELS = {
    "license_fee_exempt": "Lệ phí môn bài",
    "tax_exempt_period": "Thời kỳ miễn/ưu đãi thuế",
    "tax_not_required_now": "Hiện chưa phát sinh nghĩa vụ",
    "accountant_note": "Ghi chú kế toán",
    "policy_note": "Ghi chú chính sách",
    "manual_review": "Cần rà soát thủ công",
}

def save_finance_compliance_note(
    status_type: str,
    title: str,
    description: str,
    admin_id,
    effective_from: str = "",
    effective_to: str = "",
    source_note: str = "",
    attachment_file_id: str = "",
) -> int:
    status_type = str(status_type or "manual_review").strip().lower()
    if status_type not in FINANCE_COMPLIANCE_STATUS_LABELS:
        status_type = "manual_review"
    created_at = now_text()
    conn = db_connect()
    try:
        cur = conn.execute(
            """INSERT INTO finance_compliance_notes
            (status_type,title,description,effective_from,effective_to,source_note,
             attachment_file_id,confirmed_by_admin,created_at,updated_at)
            VALUES (?,?,?,?,?,?,?,?,?,?)""",
            (
                status_type,
                sanitize_log_text(str(title or ""))[:300],
                sanitize_log_text(str(description or ""))[:2000],
                sanitize_log_text(str(effective_from or ""))[:40],
                sanitize_log_text(str(effective_to or ""))[:40],
                sanitize_log_text(str(source_note or ""))[:1000],
                str(attachment_file_id or "")[:300],
                str(admin_id or ""),
                created_at,
                created_at,
            ),
        )
        conn.commit()
        return int(cur.lastrowid or 0)
    finally:
        conn.close()

def finance_compliance_notes(limit: int = 20) -> list[dict]:
    conn = db_connect()
    try:
        rows = conn.execute(
            """SELECT id,status_type,title,description,effective_from,effective_to,
                      source_note,attachment_file_id,confirmed_by_admin,created_at,updated_at
               FROM finance_compliance_notes
               ORDER BY updated_at DESC,id DESC LIMIT ?""",
            (max(1, min(int(limit or 20), 100)),),
        ).fetchall()
    finally:
        conn.close()
    keys = [
        "id", "status_type", "title", "description", "effective_from", "effective_to",
        "source_note", "attachment_file_id", "confirmed_by_admin", "created_at", "updated_at",
    ]
    return [dict(zip(keys, row)) for row in rows]

def finance_compliance_status_text() -> str:
    notes = finance_compliance_notes(20)
    latest_by_type = {}
    for note in notes:
        latest_by_type.setdefault(note.get("status_type") or "manual_review", note)
    lines = [
        "🟢 <b>Trạng thái miễn/ưu đãi thuế phí</b>",
        "",
        "Mục này giúp admin ghi chú tình trạng miễn/ưu đãi thuế, phí môn bài hoặc chính sách hỗ trợ đang áp dụng cho TOAN AAS.",
        "",
    ]
    for status_type in ("license_fee_exempt", "tax_exempt_period", "tax_not_required_now", "accountant_note", "policy_note", "manual_review"):
        note = latest_by_type.get(status_type)
        label = FINANCE_COMPLIANCE_STATUS_LABELS[status_type]
        if not note:
            lines.append(f"• {label}: <i>chưa cập nhật</i>")
            continue
        period = " → ".join(filter(None, [str(note.get("effective_from") or ""), str(note.get("effective_to") or "")])) or "-"
        lines.extend([
            f"• <b>{html.escape(label)}</b>: {html.escape(str(note.get('title') or '-'))}",
            f"  Trạng thái/ghi chú: {html.escape(str(note.get('description') or '-'))}",
            f"  Thời gian áp dụng: <code>{html.escape(period)}</code>",
            f"  Căn cứ: {html.escape(str(note.get('source_note') or '-'))}",
            f"  Người xác nhận: <code>{html.escape(str(note.get('confirmed_by_admin') or '-'))}</code>",
            f"  Ngày cập nhật: <code>{html.escape(str(note.get('updated_at') or '-'))}</code>",
        ])
    lines.extend(["", f"⚠️ <i>{html.escape(TAX_PREP_DISCLAIMER)}</i>"])
    return "\n".join(lines)

def tax_estimate_payload(start_at: str, end_at: str, label: str, admin_id) -> dict:
    finance = finance_summary_payload(start_at, end_at, label)
    config = get_tax_profile(admin_id)
    estimate = calculate_tax_estimate(finance.get("revenue_success") or 0, config)
    expenses_total = (
        int(finance.get("expenses_after") or 0)
        + int(finance.get("expenses_pre_period") or 0)
        + int(finance.get("provider_cost_estimate") or 0)
    )
    return {
        **finance,
        **estimate,
        "tax_config": config,
        "expenses_total": expenses_total,
        "management_profit_before_tax": int(finance.get("revenue_success") or 0) - expenses_total,
    }

def tax_estimate_text(payload: dict) -> str:
    has_data = int(payload.get("revenue_count") or 0) > 0 or int(payload.get("expense_count") or 0) > 0
    lines = [
        "📊 <b>Thu chi / Báo cáo nội bộ TOAN AAS</b>",
        "",
        f"• Kỳ: <code>{html.escape(str(payload.get('label') or ''))}</code>",
        f"• Doanh thu: <b>{vnd_text(payload.get('taxable_revenue'))}</b>",
        f"• Chi phí nội bộ: <b>{vnd_text(payload.get('expenses_total'))}</b>",
        f"• Lãi/lỗ quản trị: <b>{vnd_text(payload.get('management_profit_before_tax'))}</b>",
    ]
    if not has_data:
        lines.extend(["", "Chưa có dữ liệu cho kỳ này."])
    lines.extend(["", f"⚠️ <i>{html.escape(TAX_PREP_DISCLAIMER)}</i>"])
    return "\n".join(lines)

