def memory_public_stage() -> str:
    return "PUBLIC_READY" if ENABLE_MEMORY_PUBLIC else "ADMIN_ONLY"

def memory_can_use_full(user_id) -> bool:
    return bool(ENABLE_MEMORY_PUBLIC or is_admin_user(user_id))

def memory_access_message() -> str:
    return (
        "🧠 <b>TOAN AAS Memory đang test nội bộ.</b>\n\n"
        "Hiện khách có thể xem <code>/memory</code> và <code>/memory_plan</code>. "
        "Lệnh lưu note/nhắc việc sẽ mở public sau khi admin test ổn.\n\n"
        "Bạn có thể dùng <code>/film &lt;chủ đề&gt;</code> để tạo content pack trước."
    )

async def memory_require_access(update: Update) -> bool:
    uid = update.effective_user.id if update.effective_user else ""
    if memory_can_use_full(uid):
        return True
    await update.message.reply_text(memory_access_message(), parse_mode="HTML")
    return False

def memory_plan_config(plan: str) -> dict:
    return dict(MEMORY_PLANS.get(str(plan or "").lower(), MEMORY_PLANS["free"]))

def storage_mb_label(mb: int | float) -> str:
    value = float(mb or 0)
    if value.is_integer():
        return f"{int(value)}MB"
    return f"{value:.1f}MB"

def storage_bytes_to_mb_text(value: int | float) -> str:
    mb = float(value or 0) / (1024 * 1024)
    if mb >= 10:
        return f"{mb:.1f}MB"
    return f"{mb:.2f}MB"

def storage_addon_lines() -> list[str]:
    return [
        f"• +50MB/tháng: {STORAGE_ADDON_BLOCK_PRICE_VND:,}đ".replace(",", "."),
        f"• +100MB/tháng: {STORAGE_ADDON_BLOCK_PRICE_VND * 2:,}đ".replace(",", "."),
        f"• +250MB/tháng: {STORAGE_ADDON_BLOCK_PRICE_VND * 5:,}đ".replace(",", "."),
        f"• +500MB/tháng: {STORAGE_ADDON_BLOCK_PRICE_VND * 10:,}đ".replace(",", "."),
        "• Cần số khác: nhập bội số 50MB hoặc số tiền tương ứng.",
    ]

def storage_addon_tiers() -> list[dict]:
    return [
        {"code": "50mb", "addon_mb": 50, "amount_vnd": STORAGE_ADDON_BLOCK_PRICE_VND, "months": 1},
        {"code": "100mb", "addon_mb": 100, "amount_vnd": STORAGE_ADDON_BLOCK_PRICE_VND * 2, "months": 1},
        {"code": "250mb", "addon_mb": 250, "amount_vnd": STORAGE_ADDON_BLOCK_PRICE_VND * 5, "months": 1},
        {"code": "500mb", "addon_mb": 500, "amount_vnd": STORAGE_ADDON_BLOCK_PRICE_VND * 10, "months": 1},
    ]

def storage_addon_spec_by_code(code: str) -> dict:
    safe_code = str(code or "").strip().lower()
    for item in storage_addon_tiers():
        if item["code"] == safe_code:
            return dict(item)
    if safe_code.startswith("custom_") and safe_code.endswith("mb"):
        return storage_addon_spec_from_custom(safe_code.replace("custom_", ""))
    return {}

def storage_addon_spec_from_custom(value: str) -> dict:
    raw = str(value or "").strip().lower().replace(" ", "")
    if not raw:
        return {}
    digits = re.sub(r"[^0-9]", "", raw)
    if not digits:
        return {}
    number = int(digits or 0)
    if number <= 0:
        return {}
    if "k" in raw or "đ" in raw or "vnd" in raw:
        amount_vnd = number * 1000 if "k" in raw and number < 1000 else number
        if amount_vnd < STORAGE_ADDON_BLOCK_PRICE_VND or amount_vnd % STORAGE_ADDON_BLOCK_PRICE_VND != 0:
            return {}
        blocks = amount_vnd // STORAGE_ADDON_BLOCK_PRICE_VND
        addon_mb = blocks * STORAGE_ADDON_BLOCK_MB
    else:
        addon_mb = number
        if addon_mb < STORAGE_ADDON_BLOCK_MB or addon_mb % STORAGE_ADDON_BLOCK_MB != 0:
            return {}
        blocks = addon_mb // STORAGE_ADDON_BLOCK_MB
        amount_vnd = blocks * STORAGE_ADDON_BLOCK_PRICE_VND
    return {
        "code": f"custom_{int(addon_mb)}mb",
        "addon_mb": int(addon_mb),
        "amount_vnd": int(amount_vnd),
        "months": 1,
    }

def storage_addon_label(spec: dict) -> str:
    addon_mb = int((spec or {}).get("addon_mb") or 0)
    amount_vnd = int((spec or {}).get("amount_vnd") or 0)
    if amount_vnd % 1000 == 0:
        price = f"{amount_vnd // 1000}k"
    else:
        price = f"{amount_vnd:,}đ".replace(",", ".")
    return f"{price} — +{addon_mb}MB/tháng"

def ensure_memory_storage_addons_table(conn=None) -> None:
    own_conn = conn is None
    if own_conn:
        conn = db_connect()
    try:
        conn.execute("""CREATE TABLE IF NOT EXISTS memory_storage_addons (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id TEXT,
            order_code TEXT DEFAULT '',
            addon_mb INTEGER DEFAULT 0,
            amount_vnd INTEGER DEFAULT 0,
            months INTEGER DEFAULT 1,
            status TEXT DEFAULT 'active',
            source TEXT DEFAULT '',
            granted_by TEXT DEFAULT '',
            note TEXT DEFAULT '',
            starts_at TEXT,
            expires_at TEXT,
            created_at TEXT,
            updated_at TEXT
        )""")
        conn.execute("CREATE INDEX IF NOT EXISTS idx_memory_storage_addons_user_status ON memory_storage_addons(user_id,status,expires_at)")
        if own_conn:
            conn.commit()
    finally:
        if own_conn:
            conn.close()

def ensure_storage_billing_tables_conn(conn) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS storage_entitlements (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT,
        source TEXT DEFAULT '',
        payment_order_code TEXT DEFAULT '',
        package_id TEXT DEFAULT '',
        quota_mb INTEGER DEFAULT 0,
        starts_at TEXT,
        expires_at TEXT,
        status TEXT DEFAULT 'active',
        created_at TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS storage_usage (
        user_id TEXT PRIMARY KEY,
        used_bytes INTEGER DEFAULT 0,
        updated_at TEXT
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS storage_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id TEXT,
        event_type TEXT,
        delta_mb INTEGER DEFAULT 0,
        used_bytes_after INTEGER DEFAULT 0,
        ref_id TEXT DEFAULT '',
        note TEXT DEFAULT '',
        created_at TEXT
    )""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_storage_entitlements_user_status ON storage_entitlements(user_id,status,expires_at)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_storage_events_user_created ON storage_events(user_id,created_at)")

def memory_active_storage_addon_mb_conn(conn, user_id) -> int:
    ensure_memory_storage_addons_table(conn)
    row = conn.execute(
        """SELECT COALESCE(SUM(COALESCE(addon_mb,0)),0)
           FROM memory_storage_addons
           WHERE user_id=? AND status='active' AND (expires_at IS NULL OR expires_at='' OR expires_at>=?)""",
        (str(user_id), now_text()),
    ).fetchone()
    return int(row[0] or 0) if row else 0

def memory_active_storage_addon_mb(user_id) -> int:
    conn = db_connect()
    try:
        return memory_active_storage_addon_mb_conn(conn, user_id)
    finally:
        conn.close()

def grant_memory_storage_addon_conn(
    conn,
    user_id,
    addon_mb: int,
    amount_vnd: int = 0,
    months: int = 1,
    order_code: str = "",
    source: str = "admin",
    granted_by: str = "",
    note: str = "",
) -> dict:
    ensure_memory_storage_addons_table(conn)
    ensure_storage_billing_tables_conn(conn)
    uid = str(user_id)
    addon_mb = max(0, int(addon_mb or 0))
    months = max(1, int(months or 1))
    if addon_mb <= 0:
        return {"ok": False, "reason": "invalid_addon_mb"}
    cfg = memory_plan_config("free")
    conn.execute(
        """INSERT OR IGNORE INTO memory_plans
        (user_id, plan, note_limit, storage_limit_mb, ai_classify_monthly_limit, ai_classify_used, renew_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?)""",
        (uid, "free", cfg["note_limit"], cfg["storage_limit_mb"], cfg["ai_classify_monthly_limit"], 0, memory_current_period_key(), now_text()),
    )
    starts = datetime.now()
    expires = starts + timedelta(days=30 * months)
    conn.execute(
        """INSERT INTO memory_storage_addons
        (user_id, order_code, addon_mb, amount_vnd, months, status, source, granted_by, note, starts_at, expires_at, created_at, updated_at)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
        (
            uid,
            str(order_code or ""),
            int(addon_mb),
            int(amount_vnd or 0),
            int(months),
            "active",
            str(source or ""),
            str(granted_by or ""),
            str(note or "")[:500],
            datetime_text(starts),
            datetime_text(expires),
            now_text(),
            now_text(),
        ),
    )
    conn.execute(
        """INSERT INTO storage_entitlements
        (user_id, source, payment_order_code, package_id, quota_mb, starts_at, expires_at, status, created_at)
        VALUES (?,?,?,?,?,?,?,?,?)""",
        (
            uid,
            str(source or ""),
            str(order_code or ""),
            f"storage_{int(addon_mb)}mb",
            int(addon_mb),
            datetime_text(starts),
            datetime_text(expires),
            "active",
            now_text(),
        ),
    )
    used_row = conn.execute(
        """SELECT
               COALESCE(SUM(LENGTH(CAST(COALESCE(content,'') AS BLOB)) + LENGTH(CAST(COALESCE(summary,'') AS BLOB))),0),
               COALESCE(SUM(COALESCE(file_size,0)),0)
           FROM memory_notes WHERE user_id=? AND is_archived=0""",
        (uid,),
    ).fetchone()
    archive_bytes = int(sql_scalar(
        conn,
        "SELECT COALESCE(SUM(COALESCE(size_bytes,0)),0) FROM internal_documents WHERE owner_admin_id=? AND status='active'",
        (uid,),
        0,
    ) or 0)
    used_bytes_after = int((used_row[0] or 0) + (used_row[1] or 0) + archive_bytes) if used_row else archive_bytes
    conn.execute(
        """INSERT INTO storage_events
        (user_id, event_type, delta_mb, used_bytes_after, ref_id, note, created_at)
        VALUES (?,?,?,?,?,?,?)""",
        (
            uid,
            "storage_addon_granted",
            int(addon_mb),
            int(used_bytes_after),
            str(order_code or ""),
            str(note or source or "")[:500],
            now_text(),
        ),
    )
    conn.execute(
        """INSERT INTO storage_usage (user_id, used_bytes, updated_at)
        VALUES (?,?,?)
        ON CONFLICT(user_id) DO UPDATE SET used_bytes=excluded.used_bytes, updated_at=excluded.updated_at""",
        (uid, int(used_bytes_after), now_text()),
    )
    active_mb = memory_active_storage_addon_mb_conn(conn, uid)
    plan_row = conn.execute("SELECT storage_limit_mb FROM memory_plans WHERE user_id=?", (uid,)).fetchone()
    base_mb = max(TOTAL_FREE_STORAGE_MB, int(plan_row[0] or TOTAL_FREE_STORAGE_MB) if plan_row else TOTAL_FREE_STORAGE_MB)
    return {
        "ok": True,
        "user_id": uid,
        "addon_mb": int(addon_mb),
        "active_addon_mb": int(active_mb),
        "total_limit_mb": int(base_mb + active_mb),
        "expires_at": datetime_text(expires),
    }

def storage_policy_short_lines() -> list[str]:
    return [
        f"✅ {NOTES_TEXT_FREE_MB}MB cho ghi chú/text/nhắc hẹn",
        f"✅ {FILES_AUDIO_FREE_MB}MB cho tệp/ảnh/âm thanh lưu lâu dài",
        f"✅ Tổng {TOTAL_FREE_STORAGE_MB}MB miễn phí cho mỗi tài khoản",
    ]

def memory_current_period_key() -> str:
    return datetime.now(VN_TZ).strftime("%Y-%m")

def memory_next_period_key() -> str:
    now = datetime.now(VN_TZ)
    year = now.year + (1 if now.month == 12 else 0)
    month = 1 if now.month == 12 else now.month + 1
    return f"{year:04d}-{month:02d}"

def memory_dt_text(dt: datetime) -> str:
    if dt.tzinfo is not None:
        dt = dt.astimezone(VN_TZ).replace(tzinfo=None)
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def memory_now() -> datetime:
    return datetime.now(VN_TZ).replace(tzinfo=None)

def memory_parse_stored_dt(value: str) -> datetime | None:
    value = str(value or "").strip()
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d %H:%M"):
        try:
            return datetime.strptime(value, fmt)
        except Exception:
            pass
    return None

def ensure_memory_plan(user_id) -> dict:
    uid = str(user_id)
    now = now_text()
    current_period = memory_current_period_key()
    conn = db_connect()
    try:
        c = conn.cursor()
        c.execute(
            """CREATE TABLE IF NOT EXISTS memory_plans (
                user_id TEXT PRIMARY KEY,
                plan TEXT DEFAULT 'free',
                note_limit INTEGER DEFAULT 30,
                storage_limit_mb INTEGER DEFAULT 50,
                ai_classify_monthly_limit INTEGER DEFAULT 10,
                ai_classify_used INTEGER DEFAULT 0,
                renew_at TEXT,
                updated_at TEXT
            )"""
        )
        c.execute("SELECT plan, note_limit, storage_limit_mb, ai_classify_monthly_limit, ai_classify_used, renew_at FROM memory_plans WHERE user_id=?", (uid,))
        row = c.fetchone()
        if not row:
            cfg = memory_plan_config("free")
            c.execute(
                """INSERT INTO memory_plans
                (user_id, plan, note_limit, storage_limit_mb, ai_classify_monthly_limit, ai_classify_used, renew_at, updated_at)
                VALUES (?,?,?,?,?,?,?,?)""",
                (uid, "free", cfg["note_limit"], cfg["storage_limit_mb"], cfg["ai_classify_monthly_limit"], 0, current_period, now),
            )
            conn.commit()
            return {"plan": "free", "ai_classify_used": 0, **cfg}
        plan, note_limit, storage_limit_mb, ai_limit, ai_used, renew_at = row
        plan = str(plan or "free").lower()
        cfg = memory_plan_config(plan)
        if plan == "free" and int(storage_limit_mb or 0) < TOTAL_FREE_STORAGE_MB:
            storage_limit_mb = TOTAL_FREE_STORAGE_MB
            c.execute(
                "UPDATE memory_plans SET storage_limit_mb=?, updated_at=? WHERE user_id=?",
                (TOTAL_FREE_STORAGE_MB, now, uid),
            )
            conn.commit()
        if str(renew_at or "") != current_period:
            ai_used = 0
            c.execute(
                """UPDATE memory_plans
                SET ai_classify_used=0, renew_at=?, updated_at=?
                WHERE user_id=?""",
                (current_period, now, uid),
            )
            conn.commit()
        return {
            "plan": plan,
            "note_limit": int(note_limit or cfg["note_limit"]),
            "storage_limit_mb": int(storage_limit_mb or cfg["storage_limit_mb"]),
            "ai_classify_monthly_limit": int(ai_limit or cfg["ai_classify_monthly_limit"]),
            "ai_classify_used": int(ai_used or 0),
            "price": cfg["price"],
        }
    finally:
        conn.close()

