def public_product_maintenance_text(lang: str = "vi", product: str = "") -> str:
    base = PUBLIC_PRODUCT_MAINTENANCE_VI if normalize_user_language(lang) == "vi" else PUBLIC_PRODUCT_MAINTENANCE_EN
    if not product:
        return base
    label = html.escape(str(product)[:80])
    return f"{label}: {base}"

def video_voice_scene_sync_schema(state: dict | None = None) -> dict:
    """Small future-ready schema only; Task 3D.7 does not generate TTS or run ffmpeg."""
    state = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    source_payload = dict(state.get("source_payload") or state.get("pending_payload") or {})
    prompt_bundle = dict(source_payload.get("prompt_bundle") or state.get("prompt_bundle") or {})
    scenes = list(prompt_bundle.get("shot_table") or source_payload.get("shot_table") or source_payload.get("scenes") or [])
    voice_id = str(finalization.get("voice_profile_id") or finalization.get("voice_choice") or "")[:80]
    full_script = str(finalization.get("voice_script") or finalization.get("voice_text") or "").strip()
    scene_voice_map = []
    narration_segments = []
    for index, scene in enumerate(scenes[:30], start=1):
        item = dict(scene) if isinstance(scene, dict) else {"description": str(scene or "")}
        scene_number = int(item.get("scene_number") or item.get("shot_number") or item.get("index") or index)
        duration_seconds = max(1, int(item.get("duration_seconds") or item.get("duration") or VIDEO_AI_DEFAULT_SEGMENT_SECONDS or 8))
        narration = str(item.get("narration_text") or item.get("narration") or item.get("voiceover") or "").strip()
        scene_voice_map.append({
            "scene_number": scene_number,
            "narration_text": narration,
            "duration_seconds": duration_seconds,
            "voice_id": voice_id,
        })
        if narration:
            narration_segments.append({"scene_number": scene_number, "text": narration, "duration_seconds": duration_seconds})
    if not scene_voice_map and full_script:
        duration_seconds = max(1, int(source_payload.get("duration_seconds") or state.get("current_video_duration_seconds") or VIDEO_AI_DEFAULT_SEGMENT_SECONDS or 8))
        scene_voice_map.append({"scene_number": 1, "narration_text": full_script[:3000], "duration_seconds": duration_seconds, "voice_id": voice_id})
        narration_segments.append({"scene_number": 1, "text": full_script[:3000], "duration_seconds": duration_seconds})
    voice_requested = bool(finalization.get("voice_enabled") or full_script or voice_id)
    return {
        "scene_voice_map": scene_voice_map,
        "narration_segments": narration_segments,
        "tts_audio_refs": list(finalization.get("tts_audio_refs") or []),
        "mux_status": "ready" if voice_requested and is_voice_mux_ready() else ("maintenance" if voice_requested else "not_requested"),
    }

def video_voice_mux_export_guard(state: dict | None = None) -> dict:
    state = dict(state or {})
    pending = dict(state.get("pending_payload") or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or pending.get("video_finalization") or {}))
    choice = str(
        state.get("current_video_voice_choice")
        or pending.get("voice_choice")
        or finalization.get("voice_choice")
        or finalization.get("voice_mode")
        or "none"
    ).strip().lower()
    default_voice = choice in {"female", "male", "auto", "default_female", "default_male", "default", "free_default"}
    selected = bool(
        finalization.get("voice_enabled")
        or choice not in {"", "none", "off", "no"}
        or str(pending.get("dubbing_option") or "none").lower() not in {"", "none", "off", "no"}
    )
    paid_voice = choice in {"paid_clone", "voice_clone", "voice_clone_create", "voice_clone_reuse", "advanced_dubbing", "uploaded", "custom"}
    try:
        classified = classify_video_addons_for_package(state)
        paid_voice = paid_voice or any(
            str(item.get("key") or "") in {"voice_clone_create", "voice_advanced", "voice_clone_reuse", "paid_voice"}
            for item in (classified.get("paid_addons") or [])
        )
    except Exception:
        pass
    if selected and not is_voice_mux_ready() and paid_voice and not default_voice:
        return {"ok": False, "reason": "paid_voice_mux_maintenance", "selected": True, "default_voice": False}
    if selected and not is_voice_mux_ready():
        return {"ok": True, "reason": "default_voice_saved_not_muxed", "selected": True, "default_voice": default_voice}
    return {"ok": True, "reason": "ready" if selected else "none", "selected": selected, "default_voice": default_voice}

def video_finalization_payload(state: dict | None = None) -> dict:
    state = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    payload = dict(state.get("source_payload") or {})
    music_choice_value = str(finalization.get("music_choice") or "").strip().lower()
    music_mode_value = str(finalization.get("music_mode") or "").strip().lower()
    music_mode = music_choice_value if music_choice_value not in {"", "none"} else (music_mode_value or "none")
    voice_choice_value = str(finalization.get("voice_choice") or "").strip().lower()
    voice_mode_value = str(finalization.get("voice_mode") or "").strip().lower()
    voice_choice = voice_choice_value if voice_choice_value not in {"", "none"} else (voice_mode_value or "none")
    subtitle_dub_choice = str(finalization.get("subtitle_dub_choice") or "none").strip().lower()
    audio_settings = video_audio_settings_from_state({"video_finalization": finalization, "source_payload": payload})
    finalization.update(audio_settings)
    payload.update({
        "video_finalization": finalization,
        "video_finalization_confirmed": bool(finalization.get("finalization_confirmed")),
        "music_option": music_mode if finalization.get("music_enabled") else "none",
        "music_choice_key": music_mode if finalization.get("music_enabled") else "none",
        "music_choice": {
            "type": music_mode if finalization.get("music_enabled") else "none",
            "label": (
                "Nhạc tải lên" if music_mode == "uploaded"
                else "SFX có sẵn" if music_mode == "sfx_library"
                else "Nhạc AI" if music_mode == "ai_music"
                else "Nhạc nền gợi ý" if finalization.get("music_enabled")
                else "Không dùng nhạc"
            ),
        },
        "music_file_id": str(finalization.get("music_file_id") or "")[:220],
        "music_prompt": str(finalization.get("music_prompt") or "")[:1000],
        "music_item_count": int(finalization.get("music_item_count") or 0),
        "subtitle_option": (
            "subtitle_translated" if finalization.get("translation_enabled") and finalization.get("subtitle_enabled")
            else "subtitle_original" if finalization.get("subtitle_enabled")
            else "none"
        ),
        "dubbing_option": (
            "dub_translated" if finalization.get("translation_enabled") and (finalization.get("dub_enabled") or finalization.get("voice_enabled"))
            else "dub_original" if finalization.get("dub_enabled") or finalization.get("voice_enabled")
            else "none"
        ),
        "translation_enabled": bool(finalization.get("translation_enabled")),
        "target_language": str(finalization.get("subtitle_language") or finalization.get("voice_language") or finalization.get("dub_language") or "")[:80],
        "voice_choice": voice_choice,
        "voice_profile_id": str(finalization.get("voice_profile_id") or "")[:80],
        "voice_style": str(finalization.get("voice_style") or "natural")[:80],
        "video_voice_speed": audio_settings["video_voice_speed"],
        "video_voice_volume_percent": audio_settings["video_voice_volume_percent"],
        "voice_speed": audio_settings["voice_speed"],
        "voice_speed_percent": audio_settings["voice_speed_percent"],
        "voice_volume_percent": audio_settings["voice_volume_percent"],
        "voice_text": str(finalization.get("voice_text") or "")[:3000],
        "voice_script": str(finalization.get("voice_script") or finalization.get("voice_text") or "")[:3000],
        "voice_file_id": str(finalization.get("voice_file_id") or "")[:220],
        "subtitle_dub_choice": subtitle_dub_choice,
        "subtitle_text": str(finalization.get("subtitle_text") or "")[:3000],
        "video_music_speed": audio_settings["video_music_speed"],
        "video_music_volume_percent": audio_settings["video_music_volume_percent"],
        "music_speed": audio_settings["music_speed"],
        "music_speed_percent": audio_settings["music_speed_percent"],
        "music_volume_percent": audio_settings["music_volume_percent"],
        **logo_watermark_session_fields(
            bool(finalization.get("logo_watermark_enabled")),
            str(finalization.get("logo_watermark_text") or ""),
            str(finalization.get("logo_watermark_position") or ""),
        ),
    })
    payload["video_project"] = build_video_project(
        state.get("user_id") or state.get("owner_user_id") or "",
        state.get("source") or payload.get("source_flow") or payload.get("source") or "video_plan",
        payload,
        finalization,
    )
    payload.update(video_voice_scene_sync_schema({**state, "video_finalization": finalization, "source_payload": payload}))
    return payload

def set_video_finalization_state(user_id, state: dict) -> dict:
    now_ts = time.time()
    clean = dict(state or {})
    finalization = video_finalization_defaults()
    finalization.update(dict(clean.get("video_finalization") or {}))
    audio_settings = video_audio_settings_from_state({**clean, "video_finalization": finalization})
    finalization.update(audio_settings)
    clean["video_finalization"] = finalization
    for key, value in audio_settings.items():
        clean[key] = value
        if key.startswith("video_"):
            clean[f"current_{key}"] = value
    clean["pending_action"] = "video_finalization"
    clean.setdefault("step", "menu")
    clean.setdefault("session_id", hashlib.sha256(f"{user_id}:{now_ts}".encode("utf-8")).hexdigest()[:12])
    clean.setdefault("created_at_ts", now_ts)
    clean["updated_at_ts"] = now_ts
    clean["expires_at_ts"] = now_ts + VIDEO_FINALIZATION_STATE_TTL_SECONDS
    clean.setdefault("source", "video_plan")
    clean.setdefault("source_label", "")
    clean.setdefault("back_callback", "menu|main_video")
    clean.setdefault("photos", [])
    clean.setdefault("source_payload", {})
    USER_PENDING[video_finalization_pending_key(user_id)] = clean
    try:
        session = go_video_screen(
            user_id,
            f"finalization:{clean.get('step') or 'menu'}",
            str(clean.get("source") or "video_finalization"),
        )
        session["order"] = dict(clean.get("video_order") or session.get("order") or {})
        session["draft"].update({
            "finalization_source": str(clean.get("source") or "")[:80],
            "finalization_step": str(clean.get("step") or "menu")[:80],
            "selected_video_tier": str(clean.get("selected_video_tier") or "")[:40],
            "selected_video_aspect_ratio": str(clean.get("selected_video_aspect_ratio") or "")[:20],
            "video_voice_speed": audio_settings["video_voice_speed"],
            "video_voice_volume_percent": audio_settings["video_voice_volume_percent"],
            "video_music_speed": audio_settings["video_music_speed"],
            "video_music_volume_percent": audio_settings["video_music_volume_percent"],
        })
        save_video_session(user_id, session)
    except Exception:
        logger.debug("video session sync skipped for finalization", exc_info=True)
    return clean

def get_video_finalization_state(user_id) -> dict:
    key = video_finalization_pending_key(user_id)
    state = USER_PENDING.get(key) or {}
    if state.get("pending_action") != "video_finalization":
        if state:
            USER_PENDING.pop(key, None)
        return {}
    if float(state.get("expires_at_ts") or 0) < time.time():
        USER_PENDING.pop(key, None)
        return {}
    return state

def clear_video_finalization_state(user_id) -> bool:
    return USER_PENDING.pop(video_finalization_pending_key(user_id), None) is not None

def update_video_finalization(user_id, **fields) -> dict:
    state = get_video_finalization_state(user_id)
    if not state:
        return {}
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    finalization.update(fields)
    state["video_finalization"] = finalization
    return set_video_finalization_state(user_id, state)

