async def video_finalization_render_aspect(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    current["step"] = "aspect"
    current["aspect_screen_shown"] = True
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_aspect_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_aspect_keyboard(lang),
    )

async def video_finalization_render_menu(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = video_finalization_prepare_aspect_state(state or get_video_finalization_state(user_id) or {})
    if video_finalization_needs_aspect_choice(current):
        return await video_finalization_render_aspect(query, user_id, current, lang)
    current["step"] = "menu"
    current["return_to_invoice"] = False
    current["addon_return_target"] = "package"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_menu_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_menu_keyboard(lang),
    )

def video_finalization_package_from_state(state: dict | None = None) -> dict:
    state = dict(state or {})
    package = video_finalization_payload(state)
    package.setdefault("source", str(state.get("source") or "promptvideo")[:80])
    package.setdefault("source_flow", str(state.get("source") or "promptvideo")[:80])
    package.setdefault("video_prompt", video_finalization_prompt_text(state))
    package.setdefault("prompt", video_finalization_prompt_text(state))
    package.setdefault("concept_text", str((state.get("session_context") or {}).get("script") or "")[:1200])
    package.setdefault("video_project", dict(state.get("video_project") or {}))
    for key in (
        "source_file_id",
        "source_video_file_id",
        "input_video_file_id",
        "telegram_file_id",
        "source_file_name",
        "source_mime_type",
        "source_duration",
        "source_file_size",
        "object_prompt",
        "direction_prompt",
        "selected_topic",
        "selected_context",
        "selected_motion",
        "selected_music",
        "invoice_id",
        "add_on_origin",
        "addon_origin",
    ):
        if not package.get(key) and state.get(key):
            package[key] = state.get(key)
    return package

def video_scene_selection_info(state: dict | None = None) -> dict:
    state = dict(state or {})
    sources = [
        state,
        dict(state.get("source_payload") or {}),
        dict(state.get("pending_payload") or {}),
        dict(state.get("video_project") or {}),
        dict((state.get("pending_payload") or {}).get("video_project") or {}),
        dict((state.get("source_payload") or {}).get("video_project") or {}),
    ]
    selected = 0
    for source in sources:
        selected = safe_int(source.get("selected_scene_count") or 0, 0)
        if selected > 0:
            break
    if selected <= 0:
        return {}
    scene_seconds = 0
    duration = 0
    duration_mode = ""
    note = ""
    for source in sources:
        scene_seconds = scene_seconds or safe_int(source.get("estimated_scene_seconds") or source.get("scene_duration_seconds") or 0, 0)
        duration = duration or safe_int(source.get("estimated_duration_seconds") or 0, 0)
        duration_mode = duration_mode or str(source.get("duration_mode") or "").strip()
        note = note or str(source.get("duration_note") or "").strip()
    scene_seconds = max(1, scene_seconds or TASK3D_SCENE_SECONDS)
    duration = duration or selected * scene_seconds
    return {
        "selected_scene_count": selected,
        "estimated_scene_seconds": scene_seconds,
        "estimated_duration_seconds": duration,
        "duration_mode": duration_mode or "scene_based",
        "duration_note": note or f"{selected} cảnh, khoảng {duration} giây",
    }

def video_scene_selection_summary_lines(state: dict | None = None, lang: str = "vi", invoice: bool = False) -> list[str]:
    info = video_scene_selection_info(state)
    if not info:
        return []
    count = int(info["selected_scene_count"])
    duration = int(info["estimated_duration_seconds"])
    scene_seconds = int(info["estimated_scene_seconds"])
    if normalize_user_language(lang) != "vi":
        calc = f"each scene/clip is about {scene_seconds} seconds" if invoice else f"1 scene ≈ {scene_seconds} seconds"
        lines = [
            f"Scene count: <b>{count} scene{'s' if count != 1 else ''}</b>",
            f"Estimated duration: <b>about {duration} seconds</b>",
            f"Calculation: <b>{html.escape(calc)}</b>",
        ]
        if count >= 10 and not invoice:
            lines.append("Longer multi-scene videos may take more time. TOAN AAS will confirm before processing or charging Xu.")
        return lines
    calc = f"mỗi cảnh/clip khoảng {scene_seconds} giây" if invoice else f"1 cảnh ≈ {scene_seconds} giây"
    lines = [
        f"Số cảnh: <b>{count} cảnh</b>",
        f"Thời lượng ước tính: <b>khoảng {duration} giây</b>",
        f"Cách tính: <b>{html.escape(calc)}</b>",
    ]
    if count >= 10 and not invoice:
        lines.append("Video nhiều cảnh có thể mất lâu hơn và có thể cần ghép nhiều clip. TOAN AAS sẽ báo lại trước khi xử lý/trừ Xu.")
    return lines

def video_finalization_invoice_active(user_id, state: dict | None = None) -> bool:
    state = dict(state or {})
    if str(state.get("addon_return_target") or "").strip().lower() == "invoice":
        return True
    addon_state = get_video_addon_state(user_id)
    if addon_state:
        return True
    return str(state.get("step") or "").strip().lower() == "confirm"

def video_finalization_set_origin(state: dict | None, origin_screen: str) -> dict:
    current = dict(state or {})
    origin = str(origin_screen or "video_options").strip().lower()
    stack = [str(item) for item in (current.get("screen_stack") or []) if str(item or "").strip()]
    if not stack or stack[-1] != origin:
        stack.append(origin)
    current["origin_screen"] = origin
    current["return_to_invoice"] = origin == "invoice"
    current["screen_stack"] = stack[-8:]
    current["addon_return_target"] = "invoice" if origin == "invoice" else "hub"
    return current

async def video_finalization_render_invoice(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    addon_state = get_video_addon_state(user_id)
    if addon_state:
        current["step"] = "confirm"
        current["origin_screen"] = "invoice"
        current["return_to_invoice"] = True
        current["addon_return_target"] = "invoice"
        set_video_finalization_state(user_id, current)
        return await render_video_addon_screen(query, user_id, addon_state, "invoice", lang)
    return await video_finalization_continue_to_invoice_or_tier(query, user_id, current, lang)

def video_finalization_addon_return_target(user_id, state: dict | None = None) -> str:
    return "invoice" if video_finalization_invoice_active(user_id, state) else "hub"

def video_finalization_merge_pending_payload(existing: dict | None, new_payload: dict | None) -> dict:
    existing = dict(existing or {})
    merged = {**existing, **dict(new_payload or {})}
    for key in (
        "source_file_id",
        "source_video_file_id",
        "input_video_file_id",
        "telegram_file_id",
        "source_file_name",
        "source_mime_type",
        "source_duration",
        "source_file_size",
        "object_prompt",
        "direction_prompt",
        "selected_topic",
        "selected_context",
        "selected_motion",
        "selected_music",
        "invoice_id",
        "add_on_origin",
        "addon_origin",
    ):
        if not merged.get(key) and existing.get(key):
            merged[key] = existing.get(key)
    return merged

async def video_finalization_return_after_addon(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    if not current:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    clear_video_addon_state(user_id)
    current = video_finalization_prepare_aspect_state(current)
    current["step"] = "menu"
    current["return_to_invoice"] = False
    current["addon_return_target"] = "hub"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_menu_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_menu_keyboard(lang),
    )

async def video_finalization_continue_to_invoice_or_tier(query, user_id, state: dict | None = None, lang: str = "vi"):
    current = dict(state or get_video_finalization_state(user_id) or {})
    if not current:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    tier = normalize_video_tier(current.get("selected_video_tier") or "")
    has_selected_tier = bool(current.get("selected_video_tier"))
    if has_selected_tier and video_finalization_has_prompt(current):
        current["selected_video_tier"] = tier
        current["selected_video_aspect_ratio"] = video_finalization_selected_aspect(current)
        if not video_scene_selection_info(current):
            if current.get("addon_return_target") == "invoice" or current.get("return_to_invoice"):
                current = video_finalization_apply_scene_count_fields(current, 1, user_id)
            else:
                return await video_finalization_render_scene_count(query, user_id, current, lang)
        current["step"] = "confirm"
        set_video_finalization_state(user_id, current)
        status = get_public_video_tier_ui_status(tier, is_admin_user(user_id))
        if not status.get("enabled"):
            return await safe_edit_or_send(
                query,
                video_finalization_tier_guard_text(tier, lang),
                parse_mode="HTML",
                reply_markup=video_finalization_tier_guard_keyboard(lang),
            )
        package = video_finalization_package_from_state(current)
        aspect = video_finalization_selected_aspect(current)
        pending_payload = public_video_pending_payload_from_package(tier, package, aspect)
        pending_payload.update({
            "video_finalization": dict(package.get("video_finalization") or {}),
            "video_finalization_confirmed": True,
            "video_addon_ready_for_invoice": True,
            "source": str(current.get("source") or package.get("source") or "promptvideo")[:80],
            "source_flow": str(current.get("source") or package.get("source_flow") or "promptvideo")[:80],
        })
        set_public_video_package_context(user_id, pending_payload)
        return await start_video_addon_step(query, user_id, pending_payload, tier, lang, source="ai")
    current["step"] = "tier"
    set_video_finalization_state(user_id, current)
    return await safe_edit_or_send(
        query,
        video_finalization_tier_text(current, lang),
        parse_mode="HTML",
        reply_markup=video_finalization_tier_keyboard(lang),
    )

def ensure_video_finalization_from_addon_state(user_id, addon_state: dict | None = None) -> dict:
    addon_state = dict(addon_state or {})
    pending = dict(addon_state.get("pending_payload") or {})
    current = dict(get_video_finalization_state(user_id) or {})
    source_payload = video_finalization_merge_pending_payload(
        current.get("source_payload") or {},
        pending,
    )
    current.update({
        "step": "menu",
        "addon_return_target": "hub",
        "source_payload": source_payload,
        "selected_video_tier": normalize_video_tier(
            current.get("selected_video_tier")
            or addon_state.get("video_tier")
            or pending.get("video_tier")
            or "low"
        ),
        "source": str(current.get("source") or addon_state.get("source") or pending.get("source") or "video_addon")[:80],
        "source_label": current.get("source_label") or addon_state.get("source_label") or "",
        "video_order": dict(addon_state.get("video_order") or current.get("video_order") or {}),
    })
    if pending.get("aspect_ratio") and not current.get("selected_video_aspect_ratio"):
        current["selected_video_aspect_ratio"] = normalize_media_aspect_ratio(
            str(pending.get("aspect_ratio")),
            "9:16",
            "video",
        )
    finalization = video_finalization_defaults()
    finalization.update(dict(current.get("video_finalization") or {}))
    finalization.update(dict(pending.get("video_finalization") or {}))
    finalization.update(video_audio_settings_from_state({**addon_state, **current, "video_finalization": finalization, "pending_payload": pending}))
    current["video_finalization"] = finalization
    current = video_audio_apply_settings_to_state(current, finalization)
    return set_video_finalization_state(user_id, current)

