async def open_video_finalization(query, user_id, source: str, source_state: dict | None = None, lang: str = "vi", back_callback: str = "menu|main_video", source_payload: dict | None = None, initial_step: str = "addons"):
    source_state = dict(source_state or {})
    photos = developing_video_frame_photos(source_state)
    initial_payload = dict(source_payload or {})
    initial_project = build_video_project(user_id, source, {**source_state, **initial_payload})
    explicit_initial_aspect = ""
    for aspect_source in (initial_payload, source_state):
        for aspect_key in (
            "selected_video_aspect_ratio",
            "aspect_ratio",
            "preferred_aspect_ratio",
            "source_aspect_ratio",
            "media_aspect_ratio",
            "original_aspect_ratio",
            "ratio",
        ):
            explicit_initial_aspect = _video_finalization_valid_aspect(aspect_source.get(aspect_key))
            if explicit_initial_aspect:
                break
        if explicit_initial_aspect:
            break
    selected_scene_count = safe_int(
        initial_payload.get("selected_scene_count")
        or source_state.get("selected_scene_count")
        or initial_project.get("selected_scene_count")
        or 0,
        0,
    )
    estimated_scene_seconds = safe_int(
        initial_payload.get("estimated_scene_seconds")
        or source_state.get("estimated_scene_seconds")
        or initial_project.get("estimated_scene_seconds")
        or TASK3D_SCENE_SECONDS,
        TASK3D_SCENE_SECONDS,
    )
    estimated_duration_seconds = safe_int(
        initial_payload.get("estimated_duration_seconds")
        or source_state.get("estimated_duration_seconds")
        or initial_project.get("estimated_duration_seconds")
        or (selected_scene_count * estimated_scene_seconds if selected_scene_count else 0),
        0,
    )
    requested_step = str(initial_step or "").strip().lower()
    step = "aspect" if requested_step in {"aspect", "ratio", "aspect_ratio"} else "menu"
    initial_state = {
        "step": step,
        "user_id": str(user_id),
        "source": source,
        "source_label": video_finalization_source_label(source, lang),
        "back_callback": back_callback,
        "photos": photos,
        "source_payload": initial_payload,
        "video_project": initial_project,
        "has_script": bool(source_state.get("selected_script") or source_state.get("script") or source_state.get("caption") or source_state.get("voice_text")),
        "has_video_prompt": bool(source_state.get("video_prompt") or source_state.get("selected_prompt") or source_state.get("custom_video_prompt")),
        "has_reference_video": bool(source_state.get("source_file_id") or source_state.get("video_file_id")),
        "session_context": {
            "script": str(source_state.get("selected_script") or source_state.get("script") or source_state.get("caption") or "")[:3000],
            "video_prompt": str(source_state.get("video_prompt") or source_state.get("selected_prompt") or source_state.get("custom_video_prompt") or "")[:3000],
        },
    }
    if explicit_initial_aspect:
        normalized_aspect = normalize_media_aspect_ratio(explicit_initial_aspect, "9:16", "video")
        initial_state.update({
            "selected_video_aspect_ratio": normalized_aspect,
            "aspect_ratio": normalized_aspect,
            "aspect_source": "provided",
        })
        initial_payload.setdefault("aspect_ratio", normalized_aspect)
        initial_state["source_payload"] = initial_payload
    if selected_scene_count > 0:
        initial_state.update({
            "selected_scene_count": selected_scene_count,
            "estimated_scene_seconds": estimated_scene_seconds,
            "estimated_duration_seconds": estimated_duration_seconds,
            "duration_mode": str(initial_payload.get("duration_mode") or source_state.get("duration_mode") or "scene_based")[:80],
            "duration_note": str(initial_payload.get("duration_note") or source_state.get("duration_note") or f"{selected_scene_count} cảnh, khoảng {estimated_duration_seconds} giây")[:160],
        })
    initial_state = video_finalization_prepare_aspect_state(initial_state)
    state = set_video_finalization_state(user_id, initial_state)
    if video_finalization_needs_aspect_choice(state):
        return await video_finalization_render_aspect(query, user_id, state, lang)
    return await video_finalization_render_menu(query, user_id, state, lang)

async def handle_legacy_frame_video_export(query, user_id, source: str, lang: str = "vi", state: dict | None = None):
    state = dict(state or get_video_finalization_state(user_id) or {})
    photos = developing_video_frame_photos(state)
    if len(photos) < 2:
        return await safe_edit_or_send(
            query,
            video_finalization_local_needs_images_text(state, lang),
            parse_mode="HTML",
            reply_markup=video_finalization_local_needs_images_keyboard(state, lang),
        )
    finalization = video_finalization_defaults()
    finalization.update(dict(state.get("video_finalization") or {}))
    missing = []
    if finalization.get("music_enabled") and finalization.get("music_mode") == "uploaded" and not is_music_mux_ready():
        missing.append("ghép nhạc" if normalize_user_language(lang) == "vi" else "music mux")
    if finalization.get("voice_enabled") and not is_voice_mux_ready():
        missing.append("ghép voice" if normalize_user_language(lang) == "vi" else "voice mux")
    if finalization.get("subtitle_enabled") and finalization.get("subtitle_burn_in") and not is_subtitle_burn_ready():
        missing.append("burn phụ đề" if normalize_user_language(lang) == "vi" else "subtitle burn-in")
    if missing:
        detail = ", ".join(missing)
        text = (
            f"⚙️ Các bước sau chưa sẵn sàng trên worker: {detail}.\n"
            "TOAN AAS đã lưu lựa chọn, chưa xử lý video và chưa trừ Xu. "
            "Bạn có thể bỏ add-on chưa sẵn hoặc lưu kế hoạch."
            if normalize_user_language(lang) == "vi"
            else f"⚙️ These worker steps are not ready: {detail}.\nChoices were saved; no video was processed and no Xu charged."
        )
        return await safe_edit_or_send(
            query,
            text,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("⏭ Xuất không add-on" if normalize_user_language(lang) == "vi" else "⏭ Export without add-ons", callback_data="vfinal|strip_addons")],
                [InlineKeyboardButton("💾 Lưu kế hoạch" if normalize_user_language(lang) == "vi" else "💾 Save plan", callback_data="vfinal|save")],
                [InlineKeyboardButton("⬅️ Thêm tính năng khác" if normalize_user_language(lang) == "vi" else "⬅️ Extra features", callback_data="vfinal|menu")],
            ]),
        )
    return await open_existing_images_in_frame_video(
        query,
        user_id,
        photos,
        source or state.get("source") or "video_finalization",
        lang=lang,
        video_finalization=finalization,
        finalization_session_id=str(state.get("session_id") or "")[:20],
    )

async def video_finalization_back_to_source(query, user_id, state: dict, lang: str = "vi"):
    back_callback = str((state or {}).get("back_callback") or "").strip()
    if back_callback.startswith("vproduct|"):
        session = get_video_session(user_id)
        action = back_callback.split("|", 1)[1] if "|" in back_callback else ""
        if action == "result":
            session["current_step"] = "result"
            save_video_session(user_id, session)
            return await task3d_render_step(query, user_id, session, lang)
        if action == "prompt_video_detail":
            session["current_step"] = "prompt_video_detail"
            save_video_session(user_id, session)
            return await safe_edit_or_send(
                query,
                task3d_prompt_detail_text(session, "video"),
                parse_mode="HTML",
                reply_markup=task3d_prompt_video_detail_keyboard(lang),
            )
    source = str((state or {}).get("source") or "").strip().lower()
    if source == "trend":
        trend_state = get_trend_video_flow_pending(user_id) or {}
        if trend_state:
            idx = safe_int(trend_state.get("video_prompt_choice") or 1, 1)
            return await safe_edit_or_send(
                query,
                trend_guided_selected_video_prompt_text(trend_state, idx, lang),
                parse_mode="HTML",
                reply_markup=trend_guided_selected_video_prompt_keyboard(lang, is_admin_user(user_id)),
            )
    if source == "longvideo":
        plan = get_developing_video_pending(user_id) or get_latest_developing_video_plan(user_id, "longvideo") or {}
        if plan:
            return await safe_edit_or_send_long_html(query, long_video_plan_text(plan, lang), reply_markup=long_video_result_keyboard(lang))
    if source == "storypack":
        plan = get_developing_video_pending(user_id) or get_latest_developing_video_plan(user_id, "storypack") or {}
        if plan:
            return await safe_edit_or_send_long_html(query, storyboard_pack_result_text(plan, lang), reply_markup=storyboard_pack_result_keyboard(lang))
    if source in {"promptvideo", "imagevideo", "videoref", "videoidea"}:
        flow = "videoref" if source == "videoref" else source
        plan = get_developing_video_pending(user_id) or get_latest_developing_video_plan(user_id, flow) or {}
        if plan:
            return await safe_edit_or_send_long_html(
                query,
                guided_video_plan_text(plan, lang, from_image=(source == "imagevideo")),
                reply_markup=guided_video_result_keyboard(flow, lang),
            )
    if source == "selfscene":
        plan = get_developing_video_pending(user_id) or get_latest_developing_video_plan(user_id, "selfscene") or {}
        if plan:
            return await safe_edit_or_send(
                query,
                self_scene_plan_text(plan, lang),
                parse_mode="HTML",
                reply_markup=self_scene_result_keyboard(lang),
            )
    if source == "storyboard":
        project_id = safe_int((state or {}).get("project_id") or (state or {}).get("source_payload", {}).get("project_id") or 0, 0)
        if project_id:
            return await safe_edit_or_send(
                query,
                storyboard_video_mode_text(project_id),
                parse_mode=None,
                reply_markup=storyboard_after_images_keyboard(project_id),
            )
    return await safe_edit_or_send(
        query,
        menu_text_main_video_i18n(lang),
        parse_mode="HTML",
        reply_markup=main_video_keyboard(lang),
    )

async def render_video_finalization_stack_target(query, user_id, state: dict, target_screen: str, lang: str = "vi"):
    if not str(target_screen or "").startswith("finalization:"):
        return False, None
    step = str(target_screen).split(":", 1)[1].strip() or "menu"
    state = dict(state or {})
    state["step"] = step
    set_video_finalization_state(user_id, state)
    if step == "menu":
        return True, await video_finalization_render_menu(query, user_id, state, lang)
    if step == "aspect":
        return True, await video_finalization_render_aspect(query, user_id, state, lang)
    if step == "tier":
        return True, await safe_edit_or_send(query, video_finalization_tier_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_tier_keyboard(lang))
    if step == "scene_count":
        return True, await safe_edit_or_send(query, video_finalization_scene_count_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_scene_count_keyboard(state, lang))
    if step == "scene_count_custom":
        return True, await safe_edit_or_send(query, video_finalization_scene_count_custom_text(lang), reply_markup=video_finalization_scene_count_custom_keyboard(lang))
    if step in {"confirm", "review", "saved"}:
        return True, await safe_edit_or_send(query, video_finalization_summary_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_summary_keyboard(state, lang))
    if step == "music":
        return True, await safe_edit_or_send(query, video_order_screen_text("music", state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
    if step == "music_suggest":
        state["step"] = "music"
        set_video_finalization_state(user_id, state)
        return True, await safe_edit_or_send(query, video_finalization_music_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
    if step in {"voice", "voice_language"}:
        if step == "voice_language":
            return True, await safe_edit_or_send(query, "🎙 <b>Chọn ngôn ngữ/giọng đọc</b>", parse_mode="HTML", reply_markup=video_finalization_voice_language_keyboard(lang))
        return True, await safe_edit_or_send(query, video_order_screen_text("voice", state, lang), parse_mode="HTML", reply_markup=video_finalization_voice_keyboard(lang))
    if step == "subtitle":
        return True, await safe_edit_or_send(query, video_order_screen_text("subtitle_dub", state, lang), parse_mode="HTML", reply_markup=video_finalization_subtitle_keyboard(lang))
    if step == "addon":
        return True, await safe_edit_or_send(query, video_finalization_addon_text(lang), parse_mode="HTML", reply_markup=video_finalization_addon_keyboard(lang))
    if step == "await_logo_watermark":
        return True, await safe_edit_or_send(query, video_finalization_logo_input_text(lang), parse_mode="HTML", reply_markup=video_finalization_logo_input_keyboard(lang))
    if step == "logo_watermark_position":
        return True, await safe_edit_or_send(query, video_finalization_logo_position_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_logo_position_keyboard(lang))
    if step == "logo_watermark_confirm":
        return True, await safe_edit_or_send(query, video_finalization_logo_confirm_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_logo_confirm_keyboard(lang))
    if step == "copy_prompt":
        return True, await safe_edit_or_send(query, video_finalization_copy_prompt_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_summary_keyboard(state, lang))
    if step == "ai_guard":
        return True, await safe_edit_or_send(query, video_finalization_ai_guard_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_guard_keyboard(state, lang))
    if step == "local_guard":
        return True, await safe_edit_or_send(query, video_finalization_local_guard_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_guard_keyboard(state, lang))
    if step == "await_music_upload":
        text = "📎 Hãy gửi file nhạc/audio. Bot chỉ lưu file ID trong phiên, chưa ghép video và chưa trừ Xu." if normalize_user_language(lang) == "vi" else "📎 Send a music/audio file. It will only be saved in this session; no processing or Xu charge."
        return True, await safe_edit_or_send(query, text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    if step == "await_voice_upload":
        text = "📎 Hãy gửi file voice/audio. Bot chỉ lưu file ID, chưa ghép video và chưa trừ Xu." if normalize_user_language(lang) == "vi" else "📎 Send a voice/audio file. It will only be saved; no processing or Xu charge."
        return True, await safe_edit_or_send(query, text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    if step == "await_voice_text":
        text = "✍️ Hãy nhập nội dung cần đọc. Bot chưa gọi TTS và chưa trừ Xu." if normalize_user_language(lang) == "vi" else "✍️ Enter the narration text. No TTS call or Xu charge yet."
        return True, await safe_edit_or_send(query, text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    if step == "await_subtitle_text":
        text = "✍️ Hãy nhập nội dung phụ đề. Flow này chỉ lưu phụ đề, chưa xử lý video." if normalize_user_language(lang) == "vi" else "✍️ Enter subtitle text. This only saves subtitles; no video processing starts."
        return True, await safe_edit_or_send(query, text, reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    if step in {"combo_language", "combo_source"}:
        if step == "combo_source":
            return True, await safe_edit_or_send(query, "🎬 <b>Dịch + lồng tiếng tự động</b>\n\nChọn nguồn nội dung để xử lý.", parse_mode="HTML", reply_markup=video_finalization_combo_source_keyboard(lang))
        return True, await safe_edit_or_send(query, "🎬 <b>Dịch + lồng tiếng tự động</b>\n\nChọn ngôn ngữ đích.", parse_mode="HTML", reply_markup=video_finalization_combo_language_keyboard(lang))
    if step == "await_combo_language":
        return True, await safe_edit_or_send(query, "✍️ Hãy nhập ngôn ngữ bạn muốn dùng.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    if step == "await_combo_text":
        return True, await safe_edit_or_send(query, "✍️ Hãy nhập nội dung dùng chung cho phụ đề và lồng tiếng. TOAN AAS chưa xử lý video và chưa trừ Xu.", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")]]))
    return False, None

async def handle_video_finalization_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    uid = query.from_user.id if query.from_user else 0
    lang = get_user_language(uid) or "vi"
    raw_callback = str(query.data or "")
    canonical_callback = LEGACY_CANONICAL_CALLBACK_REDIRECTS.get(raw_callback, raw_callback)
    parts = canonical_callback.split("|")
    action = parts[1] if len(parts) > 1 else "menu"
    value = parts[2] if len(parts) > 2 else ""
    state = get_video_finalization_state(uid)

    if action == "main":
        clear_video_finalization_state(uid)
        clear_product_context(uid)
        return await safe_edit_or_send(query, localized_start_menu_text(uid, lang), parse_mode="HTML", reply_markup=localized_main_menu_keyboard(is_admin_user(uid), lang))
    if not state:
        addon_state = get_video_addon_state(uid)
        if addon_state and action not in {"main"}:
            state = ensure_video_finalization_from_addon_state(uid, addon_state)
            if action == "back":
                return await safe_edit_or_send(query, video_finalization_menu_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_menu_keyboard(lang))
        else:
            return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    if not state:
        return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
    if action in {"menu", "tier", "music", "voice", "addon"} and video_finalization_invoice_active(uid, state):
        state = video_finalization_set_origin(state, "invoice")
        set_video_finalization_state(uid, state)
    product_area = "subtitle" if action in {"addon", "addon_none", "subtitle", "translate_sub", "combo", "translate_combo", "dub"} else ("voice" if action.startswith("voice") else ("music" if action.startswith("music") or action == "my_media" else "video"))
    enter_product_context(uid, PRODUCT_CONTEXT_VIDEO_ADDON, origin_screen=f"vfinal|{action}", product_area=product_area)
    state.setdefault("addon_origin", "vfinal|menu")
    if product_area in {"music", "voice", "subtitle"}:
        state[f"{product_area}_origin"] = f"vfinal|{action}"
    if action in {"music", "music_library", "music_sfx", "music_ai", "my_media", "voice", "voice_vault", "voice_create", "addon", "subtitle", "translate_sub", "translate_lang", "dub", "combo"}:
        state["addon_return_target"] = video_finalization_addon_return_target(uid, state)
    if action == "back":
        current_step = str(state.get("step") or "")
        if current_step == "confirm":
            clear_video_addon_state(uid)
            return await video_finalization_render_scene_count(query, uid, state, lang)
        if current_step == "scene_count_custom":
            return await video_finalization_render_scene_count(query, uid, state, lang)
        if current_step == "scene_count":
            state["step"] = "tier"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_tier_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_tier_keyboard(lang))
        if current_step == "tier":
            return await video_finalization_render_menu(query, uid, state, lang)
        if current_step == "menu":
            if bool(state.get("aspect_screen_shown")):
                return await video_finalization_render_aspect(query, uid, state, lang)
            return await video_finalization_back_to_source(query, uid, state, lang)
        if current_step == "aspect":
            return await video_finalization_back_to_source(query, uid, state, lang)
        target_screen = pop_video_screen(uid, "")
        handled, rendered = await render_video_finalization_stack_target(query, uid, state, target_screen, lang)
        if handled:
            return rendered
        if current_step in {"review", "saved"}:
            state["step"] = "tier" if state.get("selected_video_tier") else "menu"
            set_video_finalization_state(uid, state)
            if state["step"] == "tier":
                return await safe_edit_or_send(query, video_finalization_tier_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_tier_keyboard(lang))
            return await safe_edit_or_send(query, video_finalization_menu_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_menu_keyboard(lang))
        if current_step in {"music", "voice", "subtitle", "translation_language", "combo_language", "combo_source", "voice_language"}:
            addon_state = get_video_addon_state(uid)
            if addon_state:
                current = ensure_video_finalization_from_addon_state(uid, addon_state)
                if video_scene_selection_info(current):
                    return await render_video_addon_screen(query, uid, addon_state, "video_addon_menu", lang)
            state["step"] = "menu"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_menu_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_menu_keyboard(lang))
        if current_step in {"await_music_upload", "await_voice_upload"}:
            state["step"] = "music"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_music_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
        if current_step in {"await_video_music_speed", "await_video_music_volume"}:
            state["step"] = "music"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_music_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
        if current_step in {"await_video_voice_speed", "await_video_voice_volume"}:
            state["step"] = "voice"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_voice_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_voice_keyboard(lang))
        if current_step in {"await_voice_text", "await_voice_script"}:
            state["step"] = "voice"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_voice_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_voice_keyboard(lang))
        if current_step == "await_subtitle_text":
            state["step"] = "subtitle"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, "💬 <b>Thêm phụ đề</b>\n\nBạn muốn tạo phụ đề theo cách nào?" if normalize_user_language(lang) == "vi" else "💬 <b>Add subtitles</b>\n\nHow would you like to create subtitles?", parse_mode="HTML", reply_markup=video_finalization_subtitle_keyboard(lang))
        if current_step in {"await_combo_language", "await_combo_text"}:
            state["step"] = "combo_language"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, "🎬 <b>Dịch + lồng tiếng tự động</b>\n\nBạn muốn dùng ngôn ngữ nào?", parse_mode="HTML", reply_markup=video_finalization_combo_language_keyboard(lang))
        return await video_finalization_back_to_source(query, uid, state, lang)
    if action == "menu":
        addon_state = get_video_addon_state(uid)
        if addon_state:
            state = ensure_video_finalization_from_addon_state(uid, addon_state)
            clear_video_addon_state(uid)
        return await video_finalization_render_menu(query, uid, state, lang)
    if action == "aspect":
        aspect = media_aspect_ratio_from_token(value, "video")
        if aspect not in VIDEO_FINALIZATION_ASPECT_CHOICES:
            return await video_finalization_render_aspect(query, uid, state, lang)
        state = video_finalization_apply_aspect(state, aspect, "user_selected")
        set_video_finalization_state(uid, state)
        return await video_finalization_render_menu(query, uid, state, lang)
    if action == "my_media":
        state["step"] = "music"
        set_video_finalization_state(uid, state)
        enter_product_context(uid, PRODUCT_CONTEXT_VIDEO_ADDON, origin_screen="vfinal|music", product_area="media")
        return await safe_edit_or_send(
            query,
            "📁 <b>Media của tôi cho video</b>\n\nTOAN AAS giữ nguyên gói, thời lượng và file nguồn hiện tại. Chọn media/audio miễn phí ở đây chỉ lưu vào kế hoạch video, chưa xử lý và chưa trừ Xu."
            if normalize_user_language(lang) == "vi"
            else "📁 <b>My media for this video</b>\n\nThe current package, duration and source file are preserved. Selecting media here only saves the video plan.",
            parse_mode="HTML",
            reply_markup=media_library_quick_keyboard(lang, PRODUCT_CONTEXT_VIDEO_ADDON),
        )
    if action in {"voice_speed", "voice_volume", "music_speed", "music_volume"}:
        audio_kind, control = action.split("_", 1)
        state["step"] = f"await_video_{audio_kind}_{control}"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(
            query,
            video_audio_input_text(audio_kind, control, lang),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(ui_text(lang, "common.back"), callback_data=f"vfinal|{audio_kind}"),
                InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main"),
            ]]),
        )
    if action in {"voice_volume_zero_confirm", "music_volume_zero_confirm"}:
        audio_kind = action.split("_", 1)[0]
        state = video_audio_set_control(state, audio_kind, "volume", 0)
        state["step"] = audio_kind
        set_video_finalization_state(uid, state)
        sync_video_audio_controls_to_addon_state(uid, state)
        if audio_kind == "music":
            return await safe_edit_or_send(query, video_finalization_music_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
        return await safe_edit_or_send(query, video_finalization_voice_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_voice_keyboard(lang))
    if action in {"voice_volume_retry", "music_volume_retry"}:
        audio_kind = action.split("_", 1)[0]
        state["step"] = f"await_video_{audio_kind}_volume"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(
            query,
            video_audio_input_text(audio_kind, "volume", lang),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton(ui_text(lang, "common.back"), callback_data=f"vfinal|{audio_kind}"),
                InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main"),
            ]]),
        )
    if action == "logo":
        state["step"] = "await_logo_watermark"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(
            query,
            video_finalization_logo_input_text(lang),
            parse_mode="HTML",
            reply_markup=video_finalization_logo_input_keyboard(lang),
        )
    if action == "logo_pos":
        finalization = video_finalization_defaults()
        finalization.update(dict(state.get("video_finalization") or {}))
        logo_text = logo_watermark_clean_text(finalization.get("logo_watermark_text") or "")
        if not logo_text:
            state["step"] = "await_logo_watermark"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_logo_input_text(lang), parse_mode="HTML", reply_markup=video_finalization_logo_input_keyboard(lang))
        position = logo_watermark_normalize_position(value, "bottom_right")
        finalization.update(logo_watermark_session_fields(True, logo_text, position))
        state["video_finalization"] = finalization
        state["step"] = "logo_watermark_confirm"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(query, video_finalization_logo_confirm_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_logo_confirm_keyboard(lang))
    if action == "logo_confirm":
        finalization = video_finalization_defaults()
        finalization.update(dict(state.get("video_finalization") or {}))
        logo_text = logo_watermark_clean_text(finalization.get("logo_watermark_text") or "")
        logo_position = logo_watermark_normalize_position(finalization.get("logo_watermark_position") or "", "bottom_right")
        if not logo_text:
            state["step"] = "await_logo_watermark"
            set_video_finalization_state(uid, state)
            return await safe_edit_or_send(query, video_finalization_logo_input_text(lang), parse_mode="HTML", reply_markup=video_finalization_logo_input_keyboard(lang))
        finalization.update(logo_watermark_session_fields(True, logo_text, logo_position))
        state["video_finalization"] = finalization
        state["step"] = "menu"
        set_video_finalization_state(uid, state)
        return await video_finalization_render_menu(query, uid, state, lang)
    if action == "voice_defaults":
        state["step"] = "voice"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(query, video_finalization_voice_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_voice_keyboard(lang))
    if action == "tier":
        if value:
            tier = normalize_video_tier(value)
            task3d_product_id = str(
                (state.get("source_payload") or {}).get("product_id")
                or (state.get("source_payload") or {}).get("source")
                or state.get("source")
                or ""
            ).strip()
            task3d_package_id = {"low": "package_200", "basic": "package_300", "common": "package_400"}.get(tier, "")
            if task3d_product_id in VIDEO_PRODUCT_REGISTRY and task3d_package_id:
                task3d_fit = validate_package_selection(task3d_product_id, task3d_package_id, ["none"])
                if not task3d_fit.get("ok"):
                    guard = VIDEO_PRODUCT_REGISTRY[task3d_product_id].get("public_guard_message") or "Gói này không phù hợp với sản phẩm đã chọn."
                    return await safe_edit_or_send(
                        query,
                        f"🛡 <b>Gói chưa phù hợp</b>\n\n{html.escape(str(guard))}\n\nTOAN AAS chưa xử lý và chưa trừ Xu.",
                        parse_mode="HTML",
                        reply_markup=InlineKeyboardMarkup([
                            [InlineKeyboardButton("300 Xu", callback_data="vfinal|tier|basic"), InlineKeyboardButton("400 Xu", callback_data="vfinal|tier|common")],
                            [InlineKeyboardButton(ui_text(lang, "common.back"), callback_data="vfinal|back"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="vfinal|main")],
                        ]),
                    )
            state = video_finalization_prepare_aspect_state(state)
            if video_finalization_needs_aspect_choice(state):
                return await video_finalization_render_aspect(query, uid, state, lang)
            state["selected_video_tier"] = tier
            state["video_tier"] = tier
            state["selected_video_aspect_ratio"] = video_finalization_selected_aspect(state)
            state.pop("video_order", None)
            if tier == "low":
                state = video_finalization_apply_scene_count_fields(state, 1, uid)
            status = get_public_video_tier_ui_status(tier, is_admin_user(uid))
            if not status.get("enabled"):
                return await safe_edit_or_send(query, video_finalization_tier_guard_text(tier, lang), parse_mode="HTML", reply_markup=video_finalization_tier_guard_keyboard(lang))
            quote = calculate_video_quote(state)
            if tier == "low" and not quote.get("is_package_200_valid"):
                return await safe_edit_or_send(
                    query,
                    video_experience_tier_lock_text(lang, video_package_200_lock_reasons(quote)),
                    parse_mode=None,
                    reply_markup=video_experience_tier_lock_keyboard(lang, upgrade_callback="vfinal|upgrade_300", back_callback="vfinal|tier"),
                )
            if not video_finalization_has_prompt(state):
                return await safe_edit_or_send(query, video_finalization_confirm_not_ready_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_confirm_not_ready_keyboard(state, lang))
            state["step"] = "scene_count"
            set_video_finalization_state(uid, state)
            return await video_finalization_render_scene_count(query, uid, state, lang)
        state = video_finalization_prepare_aspect_state(state)
        if video_finalization_needs_aspect_choice(state):
            return await video_finalization_render_aspect(query, uid, state, lang)
        state["step"] = "tier"
        state["return_to_invoice"] = False
        state["addon_return_target"] = "package"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(query, video_finalization_tier_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_tier_keyboard(lang))
    if action == "scene_count_screen":
        return await video_finalization_render_scene_count(query, uid, state, lang)
    if action == "upgrade_300":
        state["selected_video_tier"] = "basic"
        state["video_tier"] = "basic"
        state["selected_video_aspect_ratio"] = video_finalization_selected_aspect(state)
        state.pop("video_order", None)
        state["step"] = "scene_count"
        set_video_finalization_state(uid, state)
        return await video_finalization_render_scene_count(query, uid, state, lang)
    if action == "scene_custom":
        tier = normalize_video_tier(state.get("selected_video_tier") or state.get("video_tier") or "low")
        if tier == "low":
            return await video_finalization_render_scene_count(query, uid, state, lang)
        state["step"] = "scene_count_custom"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(
            query,
            video_finalization_scene_count_custom_text(lang),
            reply_markup=video_finalization_scene_count_custom_keyboard(lang),
        )
    if action == "scene_count":
        tier = normalize_video_tier(state.get("selected_video_tier") or state.get("video_tier") or "low")
        count = safe_int(value, 0)
        if tier == "low":
            count = 1
        if count < 1:
            return await safe_edit_or_send(
                query,
                video_finalization_scene_count_custom_text(lang),
                reply_markup=video_finalization_scene_count_custom_keyboard(lang),
            )
        if count > 20:
            return await safe_edit_or_send(
                query,
                "Hiện video ngắn chỉ hỗ trợ tối đa 20 cảnh/khoảng 2 phút. Phim dài sẽ xử lý ở giai đoạn sau.",
                reply_markup=video_finalization_scene_count_keyboard(state, lang),
            )
        state = video_finalization_apply_scene_count_fields(state, count, uid)
        state["selected_video_tier"] = tier
        set_video_finalization_state(uid, state)
        return await video_finalization_continue_after_scene_count(query, uid, state, lang)
    if action == "music":
        state["step"] = "music"
        set_video_finalization_state(uid, state)
        return await safe_edit_or_send(query, video_finalization_music_text(state, lang), parse_mode="HTML", reply_markup=video_finalization_music_keyboard(lang))
    if action == "music_library":
        state["step"] = "music"
