def calculate_preview_seconds(duration_seconds) -> int:
    try:
        duration = int(math.ceil(float(duration_seconds or 0)))
    except Exception:
        duration = 0
    if duration <= 0:
        return 2
    if duration <= 6:
        return int(min(3, max(2, duration)))
    return int(min(6, max(2, math.ceil(duration / 3))))

def paid_preview_seconds(duration_seconds) -> int:
    return calculate_preview_seconds(duration_seconds)

def video_paid_preview_required(payload: dict | None = None) -> bool:
    payload = dict(payload or {})
    return bool(
        str(payload.get("job_type") or "").lower() == "video"
        and payload.get("preview_required")
        and int(payload.get("base_cost") or 0) > 0
        and video_preview_scene_count_known(payload)
        and video_preview_scene_count(payload) > 3
    )

PAID_PREVIEW_REQUIRED_TASKS = {
    "video",
    "ai_music",
    "custom_voice",
    "voice_clone",
    "dubbing",
    "subtitle_translation",
    "subtitle_plus_dubbing",
    "music_merge",
    "voice_merge",
    "audio_video_merge",
}

def paid_task_requires_preview(task_kind: str, payload: dict | None = None) -> bool:
    kind = str(task_kind or "").strip().lower()
    payload = dict(payload or {})
    if kind == "video":
        return video_paid_preview_required(payload)
    if kind in PAID_PREVIEW_REQUIRED_TASKS:
        return int(payload.get("price_xu") or payload.get("cost_xu") or payload.get("base_cost") or 1) > 0
    return False

