def public_video_confirm_text(tier: str, prompt: str, current_credits: int = 0, lang: str = "vi", music_label: str = "", aspect_ratio: str = "") -> str:
    payload = video_tier_payload(tier)
    cost = int(payload.get("cost") or 0)
