async def cmd_tool_test_frame_video(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    if not is_admin_user(uid):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    if not FRAME_VIDEO_ENABLED:
        save_tool_test_result("frame_video", "DISABLED", "FRAME_VIDEO_ENABLED=false; no render", uid)
        return await update.message.reply_text("🎞 Frame video đang tắt bằng ENV. Bot chưa trừ Xu.")
    if not FRAME_VIDEO_DIRECT_RENDER_ENABLED:
        save_tool_test_result("frame_video", "GUARDED", "FRAME_VIDEO_DIRECT_RENDER_ENABLED=false; Railway direct render blocked", uid)
        return await update.message.reply_text(
            "🎞 Frame video direct render đang bị khóa để tránh Railway OOM.\n"
            "Bot chưa gọi ffmpeg và chưa trừ Xu.\n"
            "Muốn test render trực tiếp, admin phải bật FRAME_VIDEO_DIRECT_RENDER_ENABLED=true rõ ràng."
        )
    ffmpeg = frame_video_ffmpeg_path()
    if not ffmpeg:
        save_tool_test_result("frame_video", "MISSING", "ffmpeg missing; no render", uid)
        return await update.message.reply_text("⚠️ ffmpeg chưa được cấu hình. Bot chưa trừ Xu.")
    await update.message.reply_text("🎞 Đang render video test từ 2 ảnh mẫu. Bot chưa trừ Xu.")
    with tempfile.TemporaryDirectory() as tmpdir:
        img1 = os.path.join(tmpdir, "frame_test_1.png")
        img2 = os.path.join(tmpdir, "frame_test_2.png")
        out_path = os.path.join(tmpdir, "toan_aas_frame_video_test.mp4")
        sample_specs = [
            ("0x14b8a6", img1),
            ("0xffffff", img2),
        ]
        for color, path in sample_specs:
            cmd = [
                ffmpeg, "-y",
                "-f", "lavfi",
                "-i", f"color=c={color}:s=720x1280:r=1",
                "-frames:v", "1",
                path,
            ]
            ok, detail = await run_ffmpeg_command(cmd, timeout=30)
            if not ok or not os.path.exists(path):
                save_tool_test_result("frame_video", "FAIL", f"sample_image:{detail}", uid)
                return await update.message.reply_text("❌ Frame video test FAIL khi tạo ảnh mẫu. Bot chưa trừ Xu.")
        ok, detail = await render_frame_video_paths([img1, img2], out_path, 720, 1280, 1.0, "fade", ffmpeg)
        if not ok or not os.path.exists(out_path):
            save_tool_test_result("frame_video", "FAIL", f"render:{detail}", uid)
            return await update.message.reply_text(
                "❌ Frame video test FAIL.\n"
                f"Admin detail: <code>{html.escape(str(detail or '-')[:300])}</code>\n\n"
                "Bot chưa trừ Xu.",
                parse_mode="HTML",
            )
        try:
            with open(out_path, "rb") as f:
                await context.bot.send_video(
                    chat_id=update.effective_chat.id,
                    video=f,
                    caption="✅ Frame video test PASS.\nffmpeg render OK.\nNo Xu deducted: yes",
                )
            save_tool_test_result("frame_video", "PASS", "ffmpeg slideshow render sent; no Xu", uid)
        except Exception as e:
            detail = sanitize_log_text(str(e))[:300]
            save_tool_test_result("frame_video", "FAIL_SEND", detail, uid)
            await update.message.reply_text("⚠️ Render PASS nhưng Telegram gửi video lỗi. Bot chưa trừ Xu.")

async def handle_frame_video_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = query.data or ""
    parts = data.split("|")
    action = parts[1] if len(parts) > 1 else "start"
    uid = query.from_user.id if query.from_user else 0
    lang = get_user_language(uid) or "vi"
    state = get_frame_video_state(uid)

    if action == "status" and len(parts) > 2:
        job = frame_video_job_for_user(parts[2], uid)
        return await safe_edit_or_send(
            query,
            frame_video_job_status_text(job),
            parse_mode="HTML",
            reply_markup=frame_video_job_status_keyboard(parts[2]) if job else InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")]]),
        )

    if action in {"hub", "menu", "ai_first", "layout"}:
        text = ivf.frame_video_ai_first_guard_text(lang) if action == "ai_first" else ivf.frame_video_layout_helper_text(lang) if action == "layout" else ivf.frame_video_unified_menu_text(lang)
        markup = ivf.frame_video_layout_helper_keyboard(lang) if action == "layout" else ivf.frame_video_unified_menu_keyboard(lang)
        return await safe_edit_or_send(query, text, parse_mode=None if action == "ai_first" else "HTML", reply_markup=markup)

    if action == "main":
        clear_frame_video_state(uid)
        return await safe_edit_or_send(
            query,
            localized_start_menu_text(uid, lang),
            parse_mode="HTML",
            reply_markup=localized_main_menu_keyboard(is_admin_user(uid), lang),
        )
    if action == "cancel":
        clear_frame_video_state(uid)
        return await safe_edit_or_send(
            query,
            "❌ Đã hủy ghép ảnh thành video. Bot chưa gọi ffmpeg và chưa trừ Xu.",
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")]]),
            parse_mode=None,
        )
    if action == "start":
        existing = get_frame_video_state(uid)
        if existing.get("step") == "rendering":
            return await safe_edit_or_send(query, "Bạn đang có tác vụ đang xử lý. Vui lòng chờ kết quả, không cần gửi lại lệnh.", parse_mode=None)
        if not FRAME_VIDEO_ENABLED:
            set_frame_video_last_error("frame_video_disabled")
            return await safe_edit_or_send(query, frame_video_maintenance_text(), parse_mode=None)
        if not FRAME_VIDEO_PUBLIC_ENABLED and not is_admin_user(uid):
            return await safe_edit_or_send(query, "Công cụ ghép video đang bảo trì, vui lòng thử lại sau. Bot chưa trừ Xu.", parse_mode=None)
        clear_media_creator_pending_states(uid)
        set_frame_video_state(uid, {"step": "collect", "photos": [], "source": "existing_images"})
        return await safe_edit_or_send(
            query,
            "📷 <b>Tôi có ảnh sẵn</b>\n\n" + frame_video_collect_text(0),
            reply_markup=frame_video_collect_keyboard(),
            parse_mode="HTML",
        )
    if not state:
        return await safe_edit_or_send(query, "⏰ Yêu cầu đã hết hạn hoặc đã xử lý. Bot chưa trừ Xu.", parse_mode=None)
    if state.get("step") == "rendering" and action != "confirm":
        return await safe_edit_or_send(query, "Bạn đang có tác vụ đang xử lý. Vui lòng chờ kết quả, không cần gửi lại lệnh.", parse_mode=None)

    if action == "preview_check":
        local_job_id = _safe_int(parts[2] if len(parts) > 2 else state.get("paid_preview_local_job_id"), 0)
        job = get_local_worker_job(local_job_id) if local_job_id else {}
        if not job:
            return await safe_edit_or_send(
                query,
                "⚠️ Không tìm thấy job preview. TOAN AAS chưa trừ Xu.",
                parse_mode=None,
                reply_markup=frame_video_preview_entry_keyboard(),
            )
        status = str(job.get("status") or "").lower()
        if status == "succeeded" and str(job.get("output_file_id") or ""):
            state["paid_preview_seen"] = True
            state["paid_preview_seconds"] = frame_video_paid_preview_seconds(state)
            state["paid_preview_video_file_id"] = str(job.get("output_file_id") or "")
            state["step"] = "confirm"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(
                query,
                frame_video_preview_text(state, ready=True),
                parse_mode="HTML",
                reply_markup=frame_video_preview_ready_keyboard(),
            )
        if status in {"failed", "cancelled"}:
            state = invalidate_frame_video_paid_preview(state)
            state["step"] = "confirm"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(
                query,
                "⚠️ Preview chưa tạo thành công. TOAN AAS chưa trừ Xu. Bạn có thể thử lại hoặc đổi cấu hình.",
                parse_mode=None,
                reply_markup=frame_video_preview_entry_keyboard(),
            )
        return await safe_edit_or_send(
            query,
            "▶️ Preview đang được xử lý. TOAN AAS chưa tạo bản đầy đủ và chưa trừ Xu final.",
            parse_mode=None,
            reply_markup=frame_video_preview_status_keyboard(local_job_id),
        )

    if action == "preview":
        if len(state.get("photos") or []) < 2:
            return await safe_edit_or_send(query, "⚠️ Cần ít nhất 2 ảnh để tạo preview. TOAN AAS chưa trừ Xu.", reply_markup=frame_video_collect_keyboard(), parse_mode=None)
        existing_local_job_id = _safe_int(state.get("paid_preview_local_job_id"), 0)
        if existing_local_job_id:
            job = get_local_worker_job(existing_local_job_id)
            if str((job or {}).get("status") or "").lower() in {"queued", "running"}:
                return await safe_edit_or_send(
                    query,
                    "▶️ Preview đang được xử lý. TOAN AAS chưa tạo bản đầy đủ và chưa trừ Xu final.",
                    parse_mode=None,
                    reply_markup=frame_video_preview_status_keyboard(existing_local_job_id),
                )
        guard = frame_video_runtime_guard(state, uid)
        if guard.get("action") == "worker_queue":
            frame_job_id = create_frame_video_job(uid, query.message.chat_id, state, 0, "waiting_worker")
            payload = frame_video_preview_worker_payload(frame_job_id, uid, query.message.chat_id, state)
            try:
                local_job_id = create_local_worker_job(
                    user_id=str(uid),
                    command="frame_video_paid_preview",
                    job_type="frame_video_render",
                    provider="local_ffmpeg",
                    input_file_id=payload,
                    xu_cost=0,
                    admin_only=is_admin_user(uid),
                )
            except Exception as exc:
                detail = sanitize_log_text(str(exc))[:220]
                update_frame_video_job(frame_job_id, status="failed", detail=f"preview_queue:{detail}")
                return await safe_edit_or_send(
                    query,
                    "⚠️ Chưa tạo được preview an toàn. TOAN AAS chưa trừ Xu.",
                    parse_mode=None,
                    reply_markup=frame_video_preview_entry_keyboard(),
                )
            update_frame_video_job(frame_job_id, status="waiting_worker", detail=f"paid_preview_local_job:{local_job_id}")
            state["paid_preview_seen"] = False
            state["paid_preview_seconds"] = frame_video_paid_preview_seconds(state)
            state["paid_preview_frame_job_id"] = frame_job_id
            state["paid_preview_local_job_id"] = local_job_id
            state["step"] = "preview_waiting"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(
                query,
                frame_video_preview_text(state, ready=False) + "\n\nPreview đang được gửi sang máy xử lý.",
                parse_mode="HTML",
                reply_markup=frame_video_preview_status_keyboard(local_job_id),
            )
        if not guard.get("ok"):
            return await safe_edit_or_send(
                query,
                video_paid_preview_unavailable_text({"current_video_duration_seconds": frame_video_estimated_output_seconds(state)}, lang),
                parse_mode="HTML",
                reply_markup=frame_video_preview_entry_keyboard(),
            )
        with tempfile.TemporaryDirectory() as tmpdir:
            output_path = os.path.join(tmpdir, "toan_aas_frame_preview.mp4")
            ok, detail = await render_frame_video_preview_from_state(context, state, output_path, tmpdir)
            if not ok or not os.path.exists(output_path):
                logger.warning("frame paid preview failed | %s", sanitize_log_text(str(detail))[:220])
                return await safe_edit_or_send(
                    query,
                    "⚠️ Preview chưa tạo thành công. TOAN AAS chưa trừ Xu.",
                    parse_mode=None,
                    reply_markup=frame_video_preview_entry_keyboard(),
                )
            with open(output_path, "rb") as file_obj:
                sent = await context.bot.send_video(
                    chat_id=query.message.chat_id,
                    video=file_obj,
                    caption=f"▶️ Bản xem thử ngắn {frame_video_paid_preview_seconds(state)} giây. TOAN AAS chưa trừ Xu final.",
                )
        state["paid_preview_seen"] = True
        state["paid_preview_seconds"] = frame_video_paid_preview_seconds(state)
        state["paid_preview_video_file_id"] = str(getattr(getattr(sent, "video", None), "file_id", "") or "")
        state["step"] = "confirm"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(
            query,
            frame_video_preview_text(state, ready=True),
            parse_mode="HTML",
            reply_markup=frame_video_preview_ready_keyboard(),
        )

    if action == "mode_frame":
        photos = list(state.get("photos") or [])
        if len(photos) < 2:
            return await safe_edit_or_send(
                query,
                "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.",
                reply_markup=frame_video_collect_keyboard(),
                parse_mode=None,
            )
        state["step"] = "planning"
        state["motion_mode"] = "frame"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_planning_text(state, lang), parse_mode="HTML", reply_markup=frame_video_planning_keyboard(lang))

    if action == "mode_ai":
        enabled, message = shopaikey_public_generation_guard("video")
        return await safe_edit_or_send(
            query,
            storyboard_ai_video_busy_text() if not enabled else "✨ Video AI từ ảnh có sẵn sẽ dùng flow chọn ảnh đã tạo trong TOAN AAS. Với ảnh upload trực tiếp, V1 ưu tiên 🎞 Ghép ảnh thành video. Bot chưa trừ Xu.",
            parse_mode=None,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🎞 Ghép ảnh thành video", callback_data="framevideo|mode_frame")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
            ]),
        )

    if action == "mode_audio":
        return await safe_edit_or_send(
            query,
            frame_video_audio_not_ready_text(),
            parse_mode=None,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🎞 Ghép ảnh thành video", callback_data="framevideo|mode_frame")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
            ]),
        )

    if action == "save":
        return await safe_edit_or_send(query, "💾 Bộ ảnh đã được giữ trong phiên hiện tại. Bot chưa gọi API, chưa render và chưa trừ Xu.", parse_mode=None)

    if action == "done":
        photos = list(state.get("photos") or [])
        if len(photos) < 2:
            return await safe_edit_or_send(
                query,
                "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.",
                reply_markup=frame_video_collect_keyboard(),
                parse_mode=None,
            )
        if str(state.get("source") or "") == "storyboard_user_images":
            state["step"] = "mode_select"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_mode_select_text(), parse_mode=None, reply_markup=frame_video_mode_select_keyboard())
        state["ratio"] = state.get("ratio") or "9x16"
        state["duration"] = state.get("duration") or "standard"
        state["step"] = "effect"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_effect_text(state), parse_mode="HTML", reply_markup=frame_video_effect_keyboard())

    if action == "back":
        target = parts[2] if len(parts) > 2 else "collect"
        if target == "collect":
            state["step"] = "collect"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_collect_text(len(state.get("photos") or [])), reply_markup=frame_video_collect_keyboard(), parse_mode=None)
        if target == "planning":
            state["step"] = "planning"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_planning_text(state, lang), parse_mode="HTML", reply_markup=frame_video_planning_keyboard(lang))
        if target == "ratio":
            state["step"] = "ratio"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_ratio_text(state), parse_mode="HTML", reply_markup=frame_video_ratio_keyboard())
        if target == "duration":
            state["step"] = "duration"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_duration_text(state), parse_mode="HTML", reply_markup=frame_video_duration_keyboard())
        if target == "effect":
            state["step"] = "effect"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_effect_text(state), parse_mode="HTML", reply_markup=frame_video_effect_keyboard())
        if target == "music":
            state["step"] = "music"
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(query, frame_video_music_text(state), parse_mode="HTML", reply_markup=frame_video_music_keyboard())

    if action == "planning_refresh":
        if len(state.get("photos") or []) < 2:
            return await safe_edit_or_send(query, "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.", reply_markup=frame_video_collect_keyboard(), parse_mode=None)
        state["step"] = "planning"
        state["planning_offset"] = _safe_int(state.get("planning_offset"), 0) + 3
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_planning_text(state, lang), parse_mode="HTML", reply_markup=frame_video_planning_keyboard(lang))

    if action == "planning_continue":
        if len(state.get("photos") or []) < 2:
            return await safe_edit_or_send(query, "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.", reply_markup=frame_video_collect_keyboard(), parse_mode=None)
        state["step"] = "ratio"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_ratio_text(state), parse_mode="HTML", reply_markup=frame_video_ratio_keyboard())

    if action == "ratio" and len(parts) > 2:
        state = invalidate_frame_video_paid_preview(state)
        state["ratio"] = parts[2]
        state["step"] = "duration"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_duration_text(state), parse_mode="HTML", reply_markup=frame_video_duration_keyboard())

    if action == "duration" and len(parts) > 2:
        state = invalidate_frame_video_paid_preview(state)
        state["duration"] = parts[2]
        state["step"] = "effect"
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_effect_text(state), parse_mode="HTML", reply_markup=frame_video_effect_keyboard())

    if action == "effect" and len(parts) > 2:
        state = ivf.frame_video_apply_effect_defaults(invalidate_frame_video_paid_preview(state), parts[2])
        set_frame_video_state(uid, state)
        return await safe_edit_or_send(query, frame_video_confirm_text(state, uid), parse_mode="HTML", reply_markup=frame_video_confirm_keyboard(state))

    if action == "music" and len(parts) > 2:
        state = invalidate_frame_video_paid_preview(state)
        choice = str(parts[2] or "skip").strip().lower()
        if choice == "suggest":
            state["music_choice"] = "Vui tươi / năng động, sang trọng / nhẹ nhàng, hoặc công nghệ / hiện đại"
            state["music_merge_enabled"] = False
        elif choice == "library":
            state["music_choice"] = "library_not_ready"
            state["music_merge_enabled"] = False
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(
                query,
                frame_video_audio_not_ready_text(),
                parse_mode=None,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("⏭ Bỏ qua nhạc", callback_data="framevideo|music|skip")],
                    [InlineKeyboardButton("🔙 Quay lại", callback_data="framevideo|back|effect")],
                    [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
                ]),
            )
        elif choice == "voice":
            state["voice_choice"] = "voice_not_ready"
            state["voice_merge_enabled"] = False
            set_frame_video_state(uid, state)
            return await safe_edit_or_send(
                query,
                frame_video_audio_not_ready_text(),
                parse_mode=None,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("⏭ Bỏ qua âm thanh", callback_data="framevideo|music|skip")],
                    [InlineKeyboardButton("🔙 Quay lại", callback_data="framevideo|back|effect")],
                    [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
                ]),
            )
        else:
            state["music_choice"] = "skip"
            state["music_merge_enabled"] = False
            state["voice_choice"] = "skip"
            state["voice_merge_enabled"] = False
        state["step"] = "video_addon"
        set_frame_video_state(uid, state)
        return await start_video_addon_step(query, uid, state, "low", lang, source="frame")

    if action == "confirm":
        if len(state.get("photos") or []) < 2:
            return await safe_edit_or_send(query, "⚠️ Cần ít nhất 2 ảnh để ghép thành video. Bot chưa trừ Xu.", reply_markup=frame_video_collect_keyboard(), parse_mode=None)
        if not state.get("paid_preview_seen") or not str(state.get("paid_preview_video_file_id") or ""):
            return await safe_edit_or_send(
                query,
                frame_video_preview_text(state, ready=False),
                parse_mode="HTML",
                reply_markup=frame_video_preview_entry_keyboard(),
            )
        addon_guard = video_addon_runtime_guard(state)
        if not addon_guard.get("ok"):
            return await safe_edit_or_send(
                query,
                video_addon_guard_text(lang),
                parse_mode=None,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🚫 Chọn không thêm", callback_data="videoaddon|none")],
                    [InlineKeyboardButton("👁 Đổi phụ đề", callback_data="vfinal|addon"), InlineKeyboardButton("🗣 Đổi lồng tiếng", callback_data="vfinal|addon")],
                    [InlineKeyboardButton("🏠 Menu chính", callback_data="videoaddon|main")],
                ]),
            )
        guard = frame_video_runtime_guard(state, uid)
        if guard.get("action") == "worker_queue":
            credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Frame video user")
            render_type = frame_video_render_type(state)
            base_cost = frame_video_price_for_state(state)
            preview_cost = shopaikey_preview_final_cost(uid, int(base_cost or 0), f"frame_video_{render_type}")
            if int(credits or 0) < preview_cost and not is_admin_user(uid):
                return await edit_insufficient_credits(query, int(credits or 0), preview_cost, uid)
            charge = spend_fixed_credit_info(uid, int(base_cost or 0), f"spend_frame_video_{render_type}", "Ghép ảnh thành video")
            if not charge.get("ok"):
                credits_now, _, _ = get_user(uid)
                return await edit_insufficient_credits(query, int(credits_now or 0), int(charge.get("final_cost") or preview_cost), uid)
            charged_amount = int(charge.get("final_cost") or 0)
            job_id = create_frame_video_job(uid, query.message.chat_id, state, charged_amount, "waiting_worker")
            payload = frame_video_worker_payload(job_id, uid, query.message.chat_id, state, charged_amount)
            try:
                local_job_id = create_local_worker_job(
                    user_id=str(uid),
                    command="frame_video",
                    job_type="frame_video_render",
                    provider="local_ffmpeg",
                    input_file_id=payload,
                    xu_cost=charged_amount,
                    admin_only=is_admin_user(uid),
                )
            except Exception as e:
                detail = sanitize_log_text(str(e))[:240]
                refund_charged_credit(uid, charged_amount, "frame_video_refund", "", "Hoàn Xu ghép ảnh thành video do worker queue lỗi", charged_amount > 0)
                update_frame_video_job(job_id, status="failed", detail=f"worker_queue:{detail}")
                set_frame_video_last_error(f"worker_queue:{detail}")
                clear_frame_video_state(uid)
                return await safe_edit_or_send(
                    query,
                    "⚠️ Ghép video lỗi do tài nguyên xử lý không đủ. TOAN AAS đã hoàn Xu nếu có trừ. Vui lòng thử lại với ít ảnh hơn hoặc chờ worker.\n\n"
                    f"Job: {job_id}\nStatus: failed",
                    parse_mode=None,
                    reply_markup=frame_video_job_status_keyboard(job_id),
                )
            update_frame_video_job(job_id, status="waiting_worker", detail=f"local_worker_job:{local_job_id}")
            state["step"] = "waiting_worker"
            state["charged_amount"] = charged_amount
            state["frame_video_job_id"] = job_id
            state["local_worker_job_id"] = local_job_id
            set_frame_video_state(uid, state)
            clear_frame_video_state(uid)
            price = frame_video_price_breakdown(state)
            return await safe_edit_or_send(
                query,
                "🎞 TOAN AAS đang ghép ảnh thành video cho bạn.\n"
                "Quá trình này có thể mất vài phút.\n"
                "Không cần gửi lại lệnh.\n\n"
                f"Job: {job_id}\n"
                f"Worker job: {local_job_id}\n"
                "Auto poll: ON\n"
                f"Số ảnh: {int(price.get('image_count') or 0)}\n"
                "Status: waiting_worker",
                parse_mode=None,
                reply_markup=frame_video_job_status_keyboard(job_id),
            )
        if not guard.get("ok"):
            reason = str(guard.get("reason") or "blocked")
            set_frame_video_last_error(reason)
            blocked_status = "failed_worker_unavailable" if reason in {"worker_unavailable", "direct_render_disabled"} else "failed"
            job_id = create_frame_video_job(uid, query.message.chat_id, state, 0, blocked_status)
            update_frame_video_job(job_id, status=blocked_status, detail=reason)
            clear_frame_video_state(uid)
            return await safe_edit_or_send(
                query,
                f"{guard.get('message') or frame_video_maintenance_text()}\n\nJob: {job_id}\nStatus: {blocked_status}",
                parse_mode=None,
                reply_markup=frame_video_job_status_keyboard(job_id),
            )
        ffmpeg = frame_video_ffmpeg_path()
        if not ffmpeg:
            set_frame_video_last_error("ffmpeg_missing")
            job_id = create_frame_video_job(uid, query.message.chat_id, state, 0, "failed")
            update_frame_video_job(job_id, status="failed", detail="ffmpeg_missing")
            clear_frame_video_state(uid)
            return await safe_edit_or_send(
                query,
                f"{frame_video_maintenance_text()}\n\nJob: {job_id}\nStatus: failed",
                parse_mode=None,
                reply_markup=frame_video_job_status_keyboard(job_id),
            )
        credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Frame video user")
        render_type = frame_video_render_type(state)
        base_cost = frame_video_price_for_state(state)
        preview_cost = shopaikey_preview_final_cost(uid, int(base_cost or 0), f"frame_video_{render_type}")
        if int(credits or 0) < preview_cost and not is_admin_user(uid):
            return await edit_insufficient_credits(query, int(credits or 0), preview_cost, uid)
        charge = spend_fixed_credit_info(uid, int(base_cost or 0), f"spend_frame_video_{render_type}", "Ghép ảnh thành video")
        if not charge.get("ok"):
            credits_now, _, _ = get_user(uid)
            return await edit_insufficient_credits(query, int(credits_now or 0), int(charge.get("final_cost") or preview_cost), uid)
        charged_amount = int(charge.get("final_cost") or 0)
        job_id = create_frame_video_job(uid, query.message.chat_id, state, charged_amount, "queued")
        state["step"] = "rendering"
        state["charged_amount"] = charged_amount
        state["frame_video_job_id"] = job_id
        set_frame_video_state(uid, state)
        update_frame_video_job(job_id, status="rendering", detail="ffmpeg render started")
        price = frame_video_price_breakdown(state)
        waiting = await safe_edit_or_send(
            query,
            "🎞 TOAN AAS đang ghép ảnh thành video cho bạn.\n"
            "Quá trình này có thể mất vài phút.\n"
            "Không cần gửi lại lệnh.\n\n"
            f"Job: {job_id}\n"
            "Auto poll: OFF\n"
            f"Số ảnh: {int(price.get('image_count') or 0)}\n"
            "Status: rendering",
            parse_mode=None,
            reply_markup=frame_video_job_status_keyboard(job_id),
        )
        with tempfile.TemporaryDirectory() as tmpdir:
            out_path = os.path.join(tmpdir, "toan_aas_frame_video.mp4")
            ok, detail = await render_frame_video_from_state(context, state, out_path, tmpdir)
            if not ok or not os.path.exists(out_path):
                refunded = refund_charged_credit(uid, charged_amount, "frame_video_refund", "", "Hoàn Xu ghép ảnh thành video do render lỗi", charged_amount > 0)
                set_frame_video_last_error(f"render_fail:{sanitize_log_text(str(detail))[:220]}")
                update_frame_video_job(job_id, status="failed", detail=sanitize_log_text(str(detail))[:240])
                clear_frame_video_state(uid)
                save_tool_test_result("frame_video", "FAIL", f"render:{sanitize_log_text(str(detail))[:300]}", uid)
                record_usage_event(
                    uid,
                    username=query.from_user.username or "",
                    event_type="tool_fail",
                    tool_name="frame_video",
                    command="framevideo",
                    status="render_fail",
                    provider="ffmpeg",
                    detail=sanitize_log_text(str(detail))[:300],
                )
                fail_text = (
                    "⚠️ Ghép video lỗi do tài nguyên xử lý không đủ. TOAN AAS đã hoàn Xu nếu có trừ. Vui lòng thử lại với ít ảnh hơn hoặc chờ worker.\n\n"
                    f"Job: {job_id}\n"
                    "Status: failed"
                )
                if not refunded and charged_amount > 0:
                    fail_text += "\nNếu số dư chưa cập nhật đúng, vui lòng liên hệ admin."
                if waiting:
                    try:
                        return await waiting.edit_text(fail_text, reply_markup=InlineKeyboardMarkup([
                            [InlineKeyboardButton("🎞 Thử lại ghép video", callback_data="framevideo|start")],
                            [InlineKeyboardButton("🏠 Menu chính", callback_data="framevideo|main")],
                        ]))
                    except Exception:
                        pass
                return await safe_edit_or_send(query, fail_text, parse_mode=None)
            caption = (
                "✅ Đã ghép ảnh thành video.\n"
                f"Job: {job_id}\n"
                f"Đã trừ: {charged_amount} Xu.\n"
                "Bạn có thể thêm nhạc hoặc giọng đọc ở bước sau nếu cần."
            )
            try:
                with open(out_path, "rb") as f:
                    await context.bot.send_video(
                        chat_id=query.message.chat_id,
                        video=f,
                        caption=caption,
                        reply_markup=frame_video_success_keyboard(),
                    )
                clear_frame_video_state(uid)
                update_frame_video_job(job_id, status="success", detail="mp4 sent")
                save_tool_test_result("frame_video", "PASS", f"rendered {len(state.get('photos') or [])} images; cost={charged_amount}", uid)
                record_usage_event(
                    uid,
                    username=query.from_user.username or "",
                    event_type="tool_success",
                    tool_name="frame_video",
                    command="framevideo",
                    status="success",
                    provider="ffmpeg",
                    xu_delta=-charged_amount,
                    detail=f"images={len(state.get('photos') or [])}; ratio={state.get('ratio')}; duration={state.get('duration')}; effect={state.get('effect')}",
                )
                if waiting:
                    try:
                        await waiting.edit_text(
                            f"✅ Video đã tạo xong và được gửi bên dưới.\n\nJob: {job_id}\nStatus: success",
                            reply_markup=frame_video_job_status_keyboard(job_id),
                        )
                    except Exception:
                        pass
                return
            except Exception as e:
                detail = sanitize_log_text(str(e))[:300]
                set_frame_video_last_error(f"telegram_send:{detail}")
                refund_charged_credit(uid, charged_amount, "frame_video_refund", "", "Hoàn Xu ghép ảnh thành video do Telegram gửi lỗi", charged_amount > 0)
                update_frame_video_job(job_id, status="failed", detail=f"telegram_send:{detail}")
                clear_frame_video_state(uid)
                save_tool_test_result("frame_video", "FAIL_SEND", detail, uid)
                return await safe_edit_or_send(query, "⚠️ Ghép video lỗi do tài nguyên xử lý không đủ. TOAN AAS đã hoàn Xu nếu có trừ. Vui lòng thử lại với ít ảnh hơn hoặc chờ worker.", parse_mode=None)

    return await safe_edit_or_send(query, frame_video_collect_text(len(state.get("photos") or [])), reply_markup=frame_video_collect_keyboard(), parse_mode=None)

async def cmd_storyboard_video(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id if update.effective_user else 0
    clear_media_creator_pending_states(uid)
    set_storyboard_state(uid, {"step": "start"})
    await update.message.reply_text(storyboard_start_text(), parse_mode="HTML", reply_markup=storyboard_start_keyboard())

async def storyboard_start_user_images(query, uid) -> None:
    clear_storyboard_state(uid)
    if not FRAME_VIDEO_PUBLIC_ENABLED and not is_admin_user(uid):
        await safe_edit_or_send(query, "Công cụ ghép video đang bảo trì, vui lòng thử lại sau. Bot chưa trừ Xu.", parse_mode=None)
        return
    set_frame_video_state(uid, {"step": "collect", "photos": [], "source": "storyboard_user_images"})
    await safe_edit_or_send(
        query,
        "🖼 <b>Tôi có ảnh sẵn</b>\n\n"
        "Gửi ảnh theo đúng thứ tự bạn muốn xuất hiện trong video. Tối thiểu 2 ảnh. Khi gửi xong bấm ✅ Xong.\n\n"
        + frame_video_collect_text(0),
        parse_mode="HTML",
        reply_markup=frame_video_collect_keyboard(),
    )

def storyboard_store_project_in_state(uid, state: dict, scene_count: int) -> dict:
    selected_script = str(state.get("selected_script") or state.get("idea") or "").strip()
    source_type = str(state.get("source_type") or "user_script")
    scenes = storyboard_build_scenes(selected_script, scene_count)
    title = storyboard_safe_text(selected_script, 120) or "Storyboard TOAN AAS"
    project_id = create_storyboard_project(uid, source_type, title, selected_script, scenes)
    state.update({
        "step": "storyboard_ready",
        "project_id": project_id,
        "scene_count": len(scenes),
        "scenes": scenes,
    })
    set_storyboard_state(uid, state)
    return state

async def storyboard_reply_ready(message_or_query, state: dict, via_query: bool = False):
    text = storyboard_text(list(state.get("scenes") or []), int(state.get("project_id") or 0))
    if via_query:
        return await safe_edit_or_send(message_or_query, text, parse_mode="HTML", reply_markup=storyboard_ready_keyboard())
    return await message_or_query.reply_text(text, parse_mode="HTML", reply_markup=storyboard_ready_keyboard())

async def storyboard_generate_images_for_query(query, context: ContextTypes.DEFAULT_TYPE, uid, state: dict) -> None:
    scenes = list(state.get("scenes") or [])
    project_id = int(state.get("project_id") or 0)
    tier = normalize_image_tier(state.get("image_tier") or "standard")
    if not scenes or not project_id:
        await safe_edit_or_send(query, "⚠️ Storyboard chưa sẵn sàng. Bot chưa gọi API và chưa trừ Xu.", parse_mode=None)
        return
    if not SHOPAIKEY_PUBLIC_IMAGE_ENABLED and not is_admin_user(uid):
        await safe_edit_or_send(query, ui_text(user_ui_lang(uid), "media.public_off"), parse_mode=None)
        return
    if not SHOPAIKEY_API_KEY:
        await safe_edit_or_send(query, "🛠 Tạo ảnh storyboard đang thiếu provider. Bot chưa trừ Xu.", parse_mode=None)
        return
    await safe_edit_or_send(
        query,
        f"🖼 Đang tạo {len(scenes)} ảnh storyboard theo thứ tự cảnh. Vui lòng chờ, không cần gửi lại lệnh.",
        parse_mode=None,
    )
    generated_count = 0
    for scene in scenes:
        scene_index = int(scene.get("scene_index") or 0)
        raw_prompt = str(scene.get("image_prompt") or "")
        prompt = image_tier_prompt_for_generation(raw_prompt, tier, "9:16")
        price_each = storyboard_image_unit_cost(tier, len(scenes))
        balance_before, _, _ = get_user(uid)
        deducted = 0
        if not is_admin_user(uid):
            preview_cost = shopaikey_preview_final_cost(uid, price_each, "storyboard_image")
            if int(balance_before or 0) < preview_cost:
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=f"⚠️ Không đủ Xu để tạo cảnh {scene_index}. Bot dừng tại đây, các ảnh đã tạo vẫn được lưu.",
                )
                return
            charge = spend_fixed_credit_info(uid, price_each, "storyboard_image", f"Storyboard image scene {scene_index}", True)
            if not charge.get("ok"):
                credits_now, _, _ = get_user(uid)
                await context.bot.send_message(
                    chat_id=query.message.chat_id,
                    text=f"⚠️ Không đủ Xu để tạo cảnh {scene_index}. Số dư hiện tại: {int(credits_now or 0)} Xu.",
                )
                return
            deducted = int(charge.get("final_cost") or 0)
        job_id = create_shopaikey_job(
            uid,
            query.message.chat_id,
            "image",
            model=SHOPAIKEY_IMAGE_MODEL or "nano-banana",
            prompt=prompt,
            status="IN_PROGRESS",
            admin_only=is_admin_user(uid),
            xu_cost_planned=price_each,
            retry_warranty_count=image_tier_retry_warranty_count(tier),
        )
        update_shopaikey_job(job_id=job_id, xu_deducted=deducted, billing_status="deducted" if deducted else "admin_free", confirmed_at=now_text(), confirm_required=0)
        result = await shopaikey_image_generate(prompt, SHOPAIKEY_IMAGE_MODEL or "nano-banana", aspect_ratio="9:16", tier=tier)
        status = str(result.get("status") or "FAIL")
        image_url = str(result.get("image_url") or "")
        if status != "PASS" or not image_url:
            provider_error = result.get("detail") or result.get("error_class") or status
            refunded = refund_shopaikey_job_if_needed(uid, job_id, "", provider_error) if deducted > 0 else False
            update_shopaikey_job(
                job_id=job_id,
                status="FAILED",
                error_class=result.get("error_class") or status,
                provider_message=provider_error,
                refund_status="refunded" if refunded else ("not_charged" if deducted <= 0 else "refund_failed"),
                refund_amount=deducted if refunded else 0,
                refund_reason=provider_error,
                finished_at=now_text(),
            )
            update_storyboard_scene_asset(project_id, scene_index, image_job_id=job_id, tier=tier, price_xu=deducted, status="image_failed")
            await context.bot.send_message(
                chat_id=query.message.chat_id,
                text=f"⚙️ Cảnh {scene_index}/{len(scenes)} lỗi provider. TOAN AAS đã hoàn Xu nếu cảnh này đã bị trừ. Storyboard vẫn được lưu để thử lại sau.",
            )
            return
        output_sent, output_file_id = await send_generated_image_result(
            context,
            query.message.chat_id,
            image_url,
            f"✅ Cảnh {scene_index}/{len(scenes)} đã xong.\nJob #{job_id}\nĐã trừ: {deducted} Xu.",
            None,
            "vi",
        )
        update_shopaikey_job(job_id=job_id, status="SUCCESS", result_url=image_url, result_sent=1, output_file_id=output_file_id, attempts=1, finished_at=now_text())
        update_storyboard_scene_asset(project_id, scene_index, image_job_id=job_id, image_file_id=output_file_id, image_url=image_url, tier=tier, price_xu=deducted, status="image_ready")
        generated_count += 1
    state["step"] = "images_ready"
    state["generated_count"] = generated_count
    set_storyboard_state(uid, state)
    await context.bot.send_message(
        chat_id=query.message.chat_id,
        text="✅ Đã tạo xong bộ ảnh storyboard.\n\n" + storyboard_video_mode_text(project_id),
        reply_markup=storyboard_after_images_keyboard(project_id),
    )

async def handle_storyboard_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = (query.data or "").split("|")
    action = parts[1] if len(parts) > 1 else "start"
    uid = query.from_user.id if query.from_user else 0
    if action == "start":
        clear_media_creator_pending_states(uid)
        set_storyboard_state(uid, {"step": "start"})
        return await safe_edit_or_send(query, storyboard_start_text(), parse_mode="HTML", reply_markup=storyboard_start_keyboard())
    if action == "suggest":
        clear_storyboard_state(uid)
        idea, scripts = storyboard_default_scripts(0)
        set_storyboard_state(uid, {"step": "script_options", "source_type": "ai_suggested", "idea": idea, "scripts": scripts, "suggest_offset": 0})
        return await safe_edit_or_send(query, storyboard_scripts_text(idea, scripts), parse_mode="HTML", reply_markup=storyboard_scripts_keyboard())
    if action == "idea_custom":
        clear_storyboard_state(uid)
        set_storyboard_state(uid, {"step": "await_idea", "source_type": "ai_suggested"})
        return await safe_edit_or_send(query, storyboard_idea_request_text(), parse_mode="HTML", reply_markup=video_v6_keyboard([], "vi", back=("🔙 Quay lại", "storyboard|start")))
    if action == "script":
        clear_storyboard_state(uid)
        set_storyboard_state(uid, {"step": "await_script", "source_type": "user_script"})
        return await safe_edit_or_send(query, storyboard_script_request_text(), parse_mode="HTML", reply_markup=video_v6_keyboard([], "vi", back=("🔙 Quay lại", "storyboard|start")))
    if action == "images":
        return await storyboard_start_user_images(query, uid)
    state = get_storyboard_state(uid)
    persisted_project_actions = {"mode_back", "mode_select", "mode_frame", "render", "mode_ai", "ai_scene", "ai_motion", "mode_audio", "finalization"}
    if not state and action in persisted_project_actions and len(parts) > 2:
        project_id = safe_int(parts[2], 0)
        project = storyboard_project_for_user(project_id, uid)
        if project:
            state = set_storyboard_state(uid, {
                "step": "images_ready",
                "project_id": project_id,
                "scene_count": int(project.get("scene_count") or 0),
                "source_type": str(project.get("source_type") or "restored_project"),
            })
    if not state:
        return await safe_edit_or_send(query, "⚠️ Thiếu dữ liệu storyboard ở bước này. Vui lòng quay lại bước trước để chọn hoặc tạo lại. Bot chưa gọi API và chưa trừ Xu.", parse_mode=None)
    if action == "script_refresh":
        offset = _safe_int(state.get("suggest_offset"), 0) + 3
        idea, scripts = storyboard_default_scripts(offset)
        state.update({"step": "script_options", "idea": idea, "scripts": scripts, "source_type": "ai_suggested", "suggest_offset": offset})
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, storyboard_scripts_text(idea, scripts), parse_mode="HTML", reply_markup=storyboard_scripts_keyboard())
    if action == "back_scripts":
        scripts = list(state.get("scripts") or [])
        idea = state.get("idea") or "ý tưởng video"
        if scripts:
            state["step"] = "script_options"
            set_storyboard_state(uid, state)
            return await safe_edit_or_send(query, storyboard_scripts_text(idea, scripts), parse_mode="HTML", reply_markup=storyboard_scripts_keyboard())
        return await safe_edit_or_send(query, storyboard_start_text(), parse_mode="HTML", reply_markup=storyboard_start_keyboard())
    if action == "back_count":
        state["step"] = "choose_count"
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, storyboard_scene_count_text(), parse_mode="HTML", reply_markup=storyboard_scene_count_keyboard())
    if action == "select" and len(parts) > 2:
        scripts = list(state.get("scripts") or [])
        idx = max(1, min(3, int(parts[2] or 1))) - 1
        selected = scripts[idx] if idx < len(scripts) else {}
        selected_script = "\n".join([
            str(selected.get("title") or ""),
            str(selected.get("hook") or ""),
            str(selected.get("main") or ""),
            str(selected.get("scenes") or ""),
            str(selected.get("cta") or ""),
            str(selected.get("style") or ""),
        ]).strip()
        state.update({"step": "choose_count", "selected_script": selected_script, "source_type": "ai_suggested"})
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, storyboard_scene_count_text(), parse_mode="HTML", reply_markup=storyboard_scene_count_keyboard())
    if action == "count" and len(parts) > 2:
        state = storyboard_store_project_in_state(uid, state, int(parts[2] or 5))
        return await storyboard_reply_ready(query, state, via_query=True)
    if action == "count_custom":
        state["step"] = "await_count_custom"
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, "🔢 Hãy nhập số cảnh bạn muốn. V1 khuyến nghị 2-10, tối đa kỹ thuật 20 cảnh.", parse_mode=None)
    if action == "use":
        state["step"] = "choose_image_tier"
        set_storyboard_state(uid, state)
        scene_count = len(state.get("scenes") or []) or int(state.get("scene_count") or 1)
        return await safe_edit_or_send(
            query,
            "🖼 Chọn gói tạo ảnh storyboard\n\n" + storyboard_image_tier_selection_text(scene_count),
            parse_mode=None,
            reply_markup=storyboard_image_tier_keyboard(scene_count),
        )
    if action == "regen":
        scene_count = int(state.get("scene_count") or 5)
        state = storyboard_store_project_in_state(uid, state, scene_count)
        return await storyboard_reply_ready(query, state, via_query=True)
    if action == "edit_scene":
        return await safe_edit_or_send(query, "✏️ Sửa từng cảnh sẽ mở chi tiết ở bản tiếp theo. V1: bạn có thể bấm 🔄 Gợi ý lại hoặc gửi kịch bản khác.", parse_mode=None, reply_markup=storyboard_ready_keyboard())
    if action == "tier" and len(parts) > 2:
        tier = normalize_image_tier(parts[2])
        if tier not in {"low", "standard", "high"}:
            tier = "standard"
        state["image_tier"] = tier
        state["step"] = "confirm_images"
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, storyboard_image_confirm_text(state, uid), parse_mode="HTML", reply_markup=storyboard_image_confirm_keyboard(tier))
    if action == "warranty":
        tier = normalize_image_tier(state.get("image_tier") or "standard")
        if tier == "standard":
            state["image_tier"] = "standard_warranty"
        elif tier == "high":
            state["image_tier"] = "high_warranty"
        else:
            return await safe_edit_or_send(query, "🟢 Ảnh tiết kiệm không có bảo hành. Hãy chọn gói tiêu chuẩn hoặc chất lượng cao nếu cần bảo hành.", parse_mode=None)
        set_storyboard_state(uid, state)
        return await safe_edit_or_send(query, storyboard_image_confirm_text(state, uid), parse_mode="HTML", reply_markup=storyboard_image_confirm_keyboard(state["image_tier"]))
    if action == "confirm_images":
        return await storyboard_generate_images_for_query(query, context, uid, state)
    if action in {"mode_back", "mode_select"} and len(parts) > 2:
        project_id = int(parts[2] or 0)
        return await safe_edit_or_send(query, storyboard_video_mode_text(project_id), parse_mode=None, reply_markup=storyboard_after_images_keyboard(project_id))
    if action == "finalization" and len(parts) > 2:
        project_id = int(parts[2] or 0)
        project = storyboard_project_for_user(project_id, uid)
        rows = storyboard_scenes_for_project(project_id)
        photos = [
            {"file_id": str(row.get("image_file_id") or ""), "image_url": str(row.get("image_url") or "")}
            for row in rows
            if str(row.get("image_file_id") or "") or str(row.get("image_url") or "")
        ]
        source_state = {
            "photos": photos,
            "selected_script": str(project.get("selected_script") or ""),
            "video_prompt": str((rows[0] if rows else {}).get("image_prompt") or ""),
            "project_id": project_id,
        }
        package = {}
        first_ready = next((row for row in rows if str(row.get("image_job_id") or "")), None)
        if first_ready:
            package = storyboard_video_package_from_scene(uid, project_id, int(first_ready.get("scene_index") or 1), 1, get_user_language(uid) or "vi")
        return await open_video_finalization(query, uid, "storyboard", source_state, get_user_language(uid) or "vi", f"storyboard|mode_back|{project_id}", package)
    if action in {"mode_frame", "render"} and len(parts) > 2:
        project_id = int(parts[2] or 0)
        rows = storyboard_scenes_for_project(project_id)
        photos = [
            {"file_id": str(row.get("image_file_id") or ""), "image_url": str(row.get("image_url") or "")}
            for row in rows
            if str(row.get("image_file_id") or "") or str(row.get("image_url") or "")
        ]
        if len(photos) < 2:
            return await safe_edit_or_send(query, "⚠️ Chưa đủ ảnh để ghép video. Hãy tạo đủ ảnh hoặc dùng nhánh gửi ảnh có sẵn.", parse_mode=None, reply_markup=storyboard_after_images_keyboard(project_id))
        create_storyboard_video_record(project_id, "handoff_to_frame_video", frame_video_price_for_state({"effect": "fade", "photos": photos[:FRAME_VIDEO_MAX_IMAGES]}))
        return await open_existing_images_in_frame_video(
            query,
            uid,
            photos,
            "storyboard_project",
            lang=get_user_language(uid) or "vi",
            project_id=project_id,
        )
    if action == "mode_ai" and len(parts) > 2:
        project_id = int(parts[2] or 0)
        return await safe_edit_or_send(
            query,
            "✨ Chọn ảnh/cảnh muốn animate bằng video AI.\n\nBot chưa trừ Xu. Sau bước này bạn sẽ chọn tier video theo bảng giá hiện tại.",
            parse_mode=None,
            reply_markup=storyboard_ai_scene_keyboard(project_id),
        )
    if action == "ai_scene" and len(parts) > 3:
        project_id = int(parts[2] or 0)
        scene_index = int(parts[3] or 1)
        return await safe_edit_or_send(
            query,
            f"✨ Chọn chuyển động AI cho ảnh {scene_index}:\n\n"
            "1️⃣ Camera zoom nhẹ vào sản phẩm.\n"
            "2️⃣ Sản phẩm nổi bật/chuyển động nhẹ.\n"
            "3️⃣ Lifestyle motion tự nhiên.",
            parse_mode=None,
            reply_markup=storyboard_ai_motion_keyboard(project_id, scene_index),
        )
    if action == "ai_motion" and len(parts) > 4:
        project_id = int(parts[2] or 0)
        scene_index = int(parts[3] or 1)
        motion_index = int(parts[4] or 1)
        package = storyboard_video_package_from_scene(uid, project_id, scene_index, motion_index, get_user_language(uid) or "vi")
        if not package.get("source_job_id"):
            return await safe_edit_or_send(
                query,
                "⚠️ Cảnh này chưa có ảnh đã tạo bằng TOAN AAS để dùng cho video AI. Bạn vẫn có thể dùng 🎞 Ghép ảnh thành video. Bot chưa trừ Xu.",
                parse_mode=None,
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🎞 Ghép ảnh thành video", callback_data=f"storyboard|mode_frame|{project_id}")],
                    [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
                ]),
            )
        rows = storyboard_scenes_for_project(project_id)
        photos = [
            {"file_id": str(row.get("image_file_id") or ""), "image_url": str(row.get("image_url") or "")}
            for row in rows
            if str(row.get("image_file_id") or "") or str(row.get("image_url") or "")
        ]
        source_state = {
            "photos": photos,
            "video_prompt": package.get("video_prompt") or "",
            "project_id": project_id,
        }
        return await open_video_finalization(
            query,
            uid,
            "storyboard",
            source_state,
            get_user_language(uid) or "vi",
            f"storyboard|mode_ai|{project_id}",
            package,
        )
    if action == "mode_audio" and len(parts) > 2:
        project_id = int(parts[2] or 0)
        return await safe_edit_or_send(
            query,
            frame_video_audio_not_ready_text(),
            parse_mode=None,
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("🎞 Ghép ảnh thành video", callback_data=f"storyboard|mode_frame|{project_id}")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
    if action == "save":
        return await safe_edit_or_send(query, "💾 Storyboard/bộ ảnh đã được lưu trong project hiện tại. Bạn có thể quay lại ghép video từ bộ ảnh này.", parse_mode=None)
    return await safe_edit_or_send(query, storyboard_start_text(), parse_mode="HTML", reply_markup=storyboard_start_keyboard())

async def handle_storyboard_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    state = get_storyboard_state(uid)
    if not state:
        return False
    text = storyboard_safe_text(update.message.text, 1400)
    step = str(state.get("step") or "")
    if step == "await_idea":
        scripts = storyboard_suggest_scripts(text)
        state.update({"step": "script_options", "idea": text, "scripts": scripts, "source_type": "ai_suggested"})
        set_storyboard_state(uid, state)
        await update.message.reply_text(storyboard_scripts_text(text, scripts), parse_mode="HTML", reply_markup=storyboard_scripts_keyboard())
        return True
    if step == "await_script":
        state.update({"step": "choose_count", "selected_script": text, "source_type": "user_script"})
        set_storyboard_state(uid, state)
        await update.message.reply_text(storyboard_scene_count_text(), parse_mode="HTML", reply_markup=storyboard_scene_count_keyboard())
        return True
    if step == "await_count_custom":
        match = re.search(r"\d+", text)
        if not match:
            await update.message.reply_text("⚠️ Vui lòng nhập số cảnh, ví dụ: 4 hoặc 8. Bot chưa trừ Xu.")
            return True
        scene_count = max(2, min(20, int(match.group(0))))
        state = storyboard_store_project_in_state(uid, state, scene_count)
        await storyboard_reply_ready(update.message, state, via_query=False)
        return True
    return False

async def run_quick_image_admin_smoke(update: Update, context: ContextTypes.DEFAULT_TYPE, prompt: str) -> None:
    uid = update.effective_user.id if update.effective_user else 0
    lang = user_ui_lang(uid)
    if not is_admin_user(uid):
        await update.message.reply_text(create_media_public_off_message(lang))
        return
    if not SHOPAIKEY_ENABLED or not SHOPAIKEY_ADMIN_ONLY or not SHOPAIKEY_API_KEY:
        save_tool_test_result("quick_image", "DISABLED", "ShopAIKey admin image smoke not configured; no call", uid)
        await update.message.reply_text("🧪 Quick image đang thiếu cấu hình admin smoke. Bot chưa gọi API và chưa trừ Xu.")
        return
    if shopaikey_active_job_for_user(uid, "image"):
        await update.message.reply_text(USER_JOB_LOCK_MESSAGE)
        return
    tool_type = "quick_image"
    normalized_prompt = normalize_generation_prompt(prompt)
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        await update.message.reply_text(USER_JOB_LOCK_MESSAGE)
        return
    start_generation_pending_job(uid, tool_type, normalized_prompt, provider="shopaikey", xu_cost=0, command="/quick_image_test")
    job_id = create_shopaikey_job(
        uid,
        update.effective_chat.id,
        "image",
        model=SHOPAIKEY_IMAGE_MODEL or "nano-banana",
        prompt="admin quick image smoke prompt",
        status="IN_PROGRESS",
        admin_only=True,
        xu_cost_planned=0,
    )
    waiting = await update.message.reply_text(public_image_waiting_text(SHOPAIKEY_IMAGE_DEFAULT_TIER, lang))
    result = await shopaikey_image_generate(prompt)
    status = str(result.get("status") or "FAIL")
    image_url = str(result.get("image_url") or "")
    output_sent = False
    if status == "PASS" and image_url:
        try:
            await context.bot.send_photo(
                chat_id=update.effective_chat.id,
                photo=image_url,
                caption=(
                    "✅ Quick image smoke PASS\n"
                    f"Model: {result.get('model') or SHOPAIKEY_IMAGE_MODEL}\n"
                    f"Size: {result.get('size') or '-'}\n"
                    "No Xu deducted: yes\n"
                    f"Public image: {'ON' if SHOPAIKEY_PUBLIC_IMAGE_ENABLED else 'OFF'}"
                ),
            )
            output_sent = True
        except Exception:
            try:
                await update.message.reply_text(
                    "✅ Quick image smoke PASS nhưng Telegram không gửi trực tiếp được ảnh từ URL.\n"
                    "Admin kiểm tra lại trong provider dashboard. Bot chưa trừ Xu."
                )
            except Exception:
                pass
    detail = (
        f"model={result.get('model') or SHOPAIKEY_IMAGE_MODEL}; http={result.get('http_status') or 0}; "
        f"latency_ms={result.get('latency_ms') or 0}; size={result.get('size') or '-'}; "
        f"output_sent={'yes' if output_sent else 'no'}; error_class={result.get('error_class') or '-'}"
    )
    save_tool_test_result("quick_image", status, detail, uid)
    record_api_debug("shopaikey", "quick_image_test", status, int(result.get("http_status") or 0), detail)
    update_shopaikey_job(
        job_id=job_id,
        status="SUCCESS" if status == "PASS" else "FAILED",
        result_url=image_url if status == "PASS" else "",
        result_sent=1 if output_sent else 0,
        model=result.get("model") or SHOPAIKEY_IMAGE_MODEL or "nano-banana",
        error_class=result.get("error_class") or "",
        provider_error_code=result.get("provider_error_code") or "",
        provider_message=result.get("detail") or "",
        attempts=1,
        finished_at=now_text(),
    )
    await update_waiting_message(waiting, "✅ Quick image smoke đã xử lý xong. Không trừ Xu.")
    if status != "PASS":
        record_provider_error(
            "shopaikey",
            "image",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, result.get("detail") or status),
            result.get("detail") or status,
        )
        await update.message.reply_text(f"{shopaikey_generation_unavailable_message(status, result.get('detail') or '')}\nBot chưa trừ Xu.")
    finish_generation_pending_job(uid, tool_type, normalized_prompt, status)

async def run_quick_video_admin_smoke(update: Update, context: ContextTypes.DEFAULT_TYPE, prompt: str) -> None:
    uid = update.effective_user.id if update.effective_user else 0
    lang = user_ui_lang(uid)
    if not is_admin_user(uid):
        await update.message.reply_text(create_media_public_off_message(lang))
        return
    if not SHOPAIKEY_ENABLED or not SHOPAIKEY_ADMIN_ONLY or not SHOPAIKEY_VIDEO_ADMIN_ONLY or not SHOPAIKEY_API_KEY:
        save_tool_test_result("quick_video", "DISABLED", "ShopAIKey admin video smoke not configured; no call", uid)
        await update.message.reply_text("🧪 Quick video đang thiếu cấu hình admin smoke. Bot chưa gọi API và chưa trừ Xu.")
        return
    if shopaikey_active_job_for_user(uid, "video"):
        await update.message.reply_text(USER_JOB_LOCK_MESSAGE)
        return
    tool_type = "quick_video"
    normalized_prompt = normalize_generation_prompt(prompt)
    if is_duplicate_pending_job(uid, tool_type, normalized_prompt):
        await update.message.reply_text(USER_JOB_LOCK_MESSAGE)
        return
    start_generation_pending_job(uid, tool_type, normalized_prompt, provider="shopaikey", xu_cost=0, command="/quick_video_test")
    model = SHOPAIKEY_VIDEO_MODEL or "veo3.1-fast"
    job_id = create_shopaikey_job(
        uid,
        update.effective_chat.id,
        "video",
        model=model,
        prompt="admin quick video smoke prompt",
        status="QUEUED",
        admin_only=True,
        xu_cost_planned=0,
    )
    waiting = await update.message.reply_text("🎞 Đang tạo video. Quá trình này có thể mất 1–5 phút. Bot sẽ tự gửi kết quả khi hoàn tất.")
    result = await shopaikey_video_create_smoke_test(model, prompt)
    status = str(result.get("status") or "FAIL")
    task_id = str(result.get("task_id") or "")
    attempts = result.get("attempts") or []
    attempt_text = shopaikey_video_attempts_summary(attempts)
    detail = (
        f"model={result.get('model') or model}; http={result.get('http_status') or 0}; "
        f"latency_ms={result.get('latency_ms') or 0}; task_id={task_id or '-'}; "
        f"provider_status={result.get('provider_status') or '-'}; error_class={result.get('error_class') or '-'}; attempts={attempt_text}"
    )
    save_tool_test_result("quick_video", status, detail, uid)
    record_api_debug("shopaikey", "quick_video_test", status, int(result.get("http_status") or 0), detail)
    update_shopaikey_job(
        job_id=job_id,
        task_id=task_id,
        status="IN_PROGRESS" if status == "PASS_SUBMITTED" and task_id else "FAILED",
        model=result.get("selected_model") or result.get("model") or model,
        error_class=result.get("error_class") or "",
        provider_error_code=result.get("provider_error_code") or "",
        provider_message=result.get("message") or result.get("detail") or "",
        attempts=len(attempts),
        finished_at="" if status == "PASS_SUBMITTED" and task_id else now_text(),
    )
    await update_waiting_message(waiting, "✅ Quick video submit đã xử lý xong. Không trừ Xu.")
    if task_id and SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED:
        asyncio.create_task(auto_poll_shopaikey_video_job(context.bot, job_id, update.effective_chat.id, uid, task_id))
    if status == "PASS_SUBMITTED" and task_id:
        await safe_reply_text(
            update.message,
            "🎞 Quick video smoke đã gửi vào queue.\n"
            f"Task: {task_id}\n"
            f"Auto poll: {'ON' if SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED else 'OFF'}\n"
            + ("Bot sẽ tự gửi video khi hoàn tất.\n" if SHOPAIKEY_VIDEO_AUTO_POLL_ENABLED else "Bấm nút kiểm tra job để xem tiến độ.\n")
            + "No Xu deducted: yes\nPublic video: OFF\n\n"
            "Lưu ý admin: smoke test có thể tốn credit thật của provider.\n\n"
            "Bạn có thể bấm nút kiểm tra job hoặc dùng "
            f"/shopaikey_video_job {task_id}",
            parse_mode=None,
            reply_markup=shopaikey_video_job_check_keyboard(task_id, lang),
        )
    else:
        record_provider_error(
            "shopaikey",
            "video",
            classify_provider_error(result.get("http_status") or 0, result.get("error_class") or status, result.get("message") or result.get("detail") or status),
            result.get("message") or result.get("detail") or status,
        )
        await safe_reply_text(
            update.message,
            f"{shopaikey_generation_unavailable_message(status, result.get('message') or result.get('detail') or '')}\nBot chưa trừ Xu.",
            parse_mode=None,
        )
    finish_generation_pending_job(uid, tool_type, normalized_prompt, status)
    return

async def handle_quick_image_flow_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_quick_image_flow(uid)
    if not pending:
        return False
    if pending.get("step") == "logo_input":
        text = logo_watermark_clean_text(update.message.text)
        if not text:
            return True
        lang = get_user_language(uid) or "vi"
        state = set_quick_image_flow(
            uid,
            "logo_position",
            logo_watermark_text=text,
            logo_watermark_enabled=True,
            logo_watermark_source="text",
            logo_watermark_position="bottom_right",
        )
        await update.message.reply_text(
            quick_image_logo_position_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_logo_position_keyboard(lang),
        )
        return True
    if pending.get("step") != "custom_prompt":
        return False
    prompt = re.sub(r"\s+", " ", update.message.text.strip())[:1400]
    if not prompt:
        return False
    lang = get_user_language(uid) or "vi"
    package = build_image_prompt(prompt, tier="standard")
    state = set_quick_image_flow(
        uid,
        "prepared_prompt",
        selected_topic=prompt,
        original_request=prompt,
        prompt=package.get("prompt") or prompt,
        negative_prompt=package.get("negative_prompt") or "",
        prompt_source="custom",
        image_purpose=package.get("purpose") or "custom",
        purpose_label=package.get("purpose_label") or "",
        suggested_ratio=package.get("suggested_ratio") or "1:1",
        text_logo_caution=package.get("text_logo_caution") or "",
    )
    await update.message.reply_text(
        quick_image_prepared_prompt_text(state, lang),
        parse_mode="HTML",
        reply_markup=quick_image_prepared_prompt_keyboard(lang),
    )
    return True

async def handle_quick_media_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_quick_media_pending(uid)
    if not pending:
        return False
    prompt = re.sub(r"\s+", " ", update.message.text.strip())
    if not prompt:
        return False
    clear_quick_media_pending(uid)
    if pending.get("pending_action") == "quick_video_prompt":
        await run_quick_video_admin_smoke(update, context, prompt)
        return True
    await run_quick_image_admin_smoke(update, context, prompt)
    return True

async def handle_create_media_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    callback_parts = str(query.data or "").split("|")
    action = callback_parts[1] if len(callback_parts) > 1 else ""
    value = callback_parts[2] if len(callback_parts) > 2 else ""
    uid = query.from_user.id if query.from_user else 0
    lang = get_user_language(uid) or "vi"
    if action == "cancel":
        clear_media_creator_pending_states(uid)
        return await safe_edit_or_send(
            query,
            ui_text(lang, "media.cancelled"),
            reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton(ui_text(lang, "common.main_menu_back"), callback_data="menu|main")]]),
        )
    if action == "main":
        notice = clear_pending_start_notice(uid)
        text = (notice or (ui_text(lang, "media.open_main") + "\n\n")) + localized_start_menu_text(uid, lang)
        return await safe_edit_or_send(
            query,
            text,
            parse_mode="HTML",
            reply_markup=localized_main_menu_keyboard(is_admin_user(uid), lang),
        )
    if action == "support":
        clear_media_creator_pending_states(uid)
        return await safe_edit_or_send(
            query,
            support_contact_text(),
            parse_mode="HTML",
            reply_markup=support_contact_keyboard(back_to_media=True, lang=lang),
        )
    if action == "pricing":
        clear_media_creator_pending_states(uid)
        return await safe_edit_or_send(
            query,
            "\n".join(pricing_hub_lines(lang)),
            parse_mode="HTML",
            reply_markup=pricing_main_keyboard(lang),
        )
    if action == "trend":
        return await trend_guided_start_from_query(query, uid, lang)
    if action == "quick_image":
        clear_trend_video_flow_pending(uid)
        clear_quick_media_pending(uid)
        clear_quick_image_flow(uid)
        clear_public_image_prompt_pending(uid)
        clear_public_video_prompt_pending(uid)
        clear_media_aspect_pending(uid)
        clear_public_video_package_context(uid)
        clear_image_menu_pending(uid)
        if shopaikey_active_job_for_user(uid, "image"):
            return await safe_edit_or_send(query, ui_text(lang, "media.job_lock"))
        set_quick_image_flow(uid, "entry", suggest_offset=0)
        return await safe_edit_or_send(
            query,
            quick_image_entry_text(lang),
            parse_mode="HTML",
            reply_markup=quick_image_entry_keyboard(lang),
        )
    if action == "qi_entry":
        state = get_quick_image_flow(uid) or {}
        token = str(state.get("confirm_token") or "")
        if token:
            pop_shopaikey_pending_confirmation(token, uid)
        set_quick_image_flow(uid, "entry", confirm_token="")
        return await safe_edit_or_send(
            query,
            quick_image_entry_text(lang),
            parse_mode="HTML",
            reply_markup=quick_image_entry_keyboard(lang),
        )
    if action in {"qi_suggest", "qi_refresh"}:
        state = get_quick_image_flow(uid) or set_quick_image_flow(uid, "entry", suggest_offset=0)
        offset = _safe_int(state.get("suggest_offset"), 0)
        if action == "qi_refresh":
            offset += 3
        state = set_quick_image_flow(uid, "suggestions", suggest_offset=offset, prompt_source="suggestion")
        return await safe_edit_or_send(
            query,
            quick_image_suggestions_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_suggestions_keyboard(lang),
        )
    if action == "qi_custom":
        state = set_quick_image_flow(uid, "custom_prompt", prompt_source="custom")
        return await safe_edit_or_send(
            query,
            quick_image_custom_prompt_text(lang, state.get("prompt") or ""),
            parse_mode="HTML",
            reply_markup=quick_image_custom_prompt_keyboard(lang),
        )
    if action.startswith("qi_pick_"):
        state = get_quick_image_flow(uid)
        if not state:
            set_quick_image_flow(uid, "entry", suggest_offset=0)
            return await safe_edit_or_send(query, quick_image_entry_text(lang), parse_mode="HTML", reply_markup=quick_image_entry_keyboard(lang))
        try:
            index = max(1, min(3, int(action.rsplit("_", 1)[1])))
        except Exception:
            index = 1
        suggestions = quick_image_suggestions(_safe_int(state.get("suggest_offset"), 0), lang)
        topic = suggestions[index - 1] if index <= len(suggestions) else (suggestions[0] if suggestions else "")
        package = build_image_prompt(topic, tier="standard")
        prompt, negative_prompt = quick_image_prompt_from_topic(topic, lang, 0)
        state = set_quick_image_flow(
            uid,
            "prepared_prompt",
            selected_topic=topic,
            original_request=topic,
            prompt=prompt,
            negative_prompt=negative_prompt,
            prompt_source="suggestion",
            prompt_variant=0,
            image_purpose=package.get("purpose") or "custom",
            purpose_label=package.get("purpose_label") or "",
            suggested_ratio=package.get("suggested_ratio") or "1:1",
            text_logo_caution=package.get("text_logo_caution") or "",
        )
        return await safe_edit_or_send(
            query,
            quick_image_prepared_prompt_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_prepared_prompt_keyboard(lang),
        )
    if action == "qi_rewrite":
        state = get_quick_image_flow(uid) or {}
        topic = str(state.get("selected_topic") or "").strip()
        if not topic:
            state = set_quick_image_flow(uid, "suggestions")
            return await safe_edit_or_send(query, quick_image_suggestions_text(state, lang), parse_mode="HTML", reply_markup=quick_image_suggestions_keyboard(lang))
        variant = _safe_int(state.get("prompt_variant"), 0) + 1
        prompt, negative_prompt = quick_image_prompt_from_topic(topic, lang, variant)
        state = set_quick_image_flow(uid, "prepared_prompt", prompt=prompt, negative_prompt=negative_prompt, prompt_variant=variant)
        return await safe_edit_or_send(
            query,
            quick_image_prepared_prompt_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_prepared_prompt_keyboard(lang),
        )
    if action in {"qi_topics", "qi_back_suggestions"}:
        state = set_quick_image_flow(uid, "suggestions")
        return await safe_edit_or_send(
            query,
            quick_image_suggestions_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_suggestions_keyboard(lang),
        )
    if action == "qi_choose_ratio":
        state = get_quick_image_flow(uid) or {}
        if not state.get("prompt"):
            state = set_quick_image_flow(uid, "suggestions")
            return await safe_edit_or_send(query, quick_image_suggestions_text(state, lang), parse_mode="HTML", reply_markup=quick_image_suggestions_keyboard(lang))
        state = set_quick_image_flow(uid, "ratio", ratio_back_target="prepared_prompt")
        return await safe_edit_or_send(
            query,
            quick_image_ratio_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_ratio_keyboard(lang),
        )
    if action == "qi_logo_choice":
        state = get_quick_image_flow(uid) or {}
        if not state.get("prompt"):
            state = set_quick_image_flow(uid, "suggestions")
            return await safe_edit_or_send(query, quick_image_suggestions_text(state, lang), parse_mode="HTML", reply_markup=quick_image_suggestions_keyboard(lang))
        state = set_quick_image_flow(uid, "logo_choice")
        return await safe_edit_or_send(
            query,
            quick_image_logo_choice_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_logo_choice_keyboard(lang),
        )
    if action == "qi_logo_add":
        state = set_quick_image_flow(uid, "logo_input")
        return await safe_edit_or_send(
            query,
            quick_image_logo_input_text(lang),
            parse_mode="HTML",
            reply_markup=quick_image_logo_input_keyboard(lang),
        )
    if action == "qi_logo_skip":
        state = set_quick_image_flow(
            uid,
            "ratio",
            logo_watermark_enabled=False,
            logo_watermark_text="",
            logo_watermark_position="",
            logo_watermark_source="",
            logo_watermark_decided=True,
            ratio_back_target="logo_choice",
        )
        return await safe_edit_or_send(
            query,
            quick_image_ratio_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_ratio_keyboard(lang),
        )
    if action == "qi_logo_pos":
        state = get_quick_image_flow(uid) or {}
        text = logo_watermark_clean_text(state.get("logo_watermark_text") or "")
        if not text:
            state = set_quick_image_flow(uid, "logo_input")
            return await safe_edit_or_send(query, quick_image_logo_input_text(lang), parse_mode="HTML", reply_markup=quick_image_logo_input_keyboard(lang))
        position = logo_watermark_normalize_position(value, "bottom_right")
        state = set_quick_image_flow(uid, "logo_confirm", logo_watermark_position=position)
        return await safe_edit_or_send(
            query,
            quick_image_logo_confirm_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_logo_confirm_keyboard(lang),
        )
    if action == "qi_logo_confirm":
        state = get_quick_image_flow(uid) or {}
        text = logo_watermark_clean_text(state.get("logo_watermark_text") or "")
        position = logo_watermark_normalize_position(state.get("logo_watermark_position") or "", "bottom_right")
        if not text:
            state = set_quick_image_flow(uid, "logo_input")
            return await safe_edit_or_send(query, quick_image_logo_input_text(lang), parse_mode="HTML", reply_markup=quick_image_logo_input_keyboard(lang))
        state = set_quick_image_flow(
            uid,
            "ratio",
            logo_watermark_enabled=True,
            logo_watermark_text=text,
            logo_watermark_position=position,
            logo_watermark_source="text",
            logo_watermark_decided=True,
            ratio_back_target="logo_choice",
        )
        return await safe_edit_or_send(
            query,
            quick_image_ratio_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_ratio_keyboard(lang),
        )
    if action == "qi_back_prompt":
        state = get_quick_image_flow(uid) or {}
        if state.get("step") == "ratio" and state.get("prompt") and state.get("ratio_back_target") == "logo_choice":
            state = set_quick_image_flow(uid, "logo_choice")
            return await safe_edit_or_send(
                query,
                quick_image_logo_choice_text(state, lang),
                parse_mode="HTML",
                reply_markup=quick_image_logo_choice_keyboard(lang),
            )
        if state.get("prompt_source") == "suggestion":
            state = set_quick_image_flow(uid, "prepared_prompt")
            return await safe_edit_or_send(
                query,
                quick_image_prepared_prompt_text(state, lang),
                parse_mode="HTML",
                reply_markup=quick_image_prepared_prompt_keyboard(lang),
            )
        state = set_quick_image_flow(uid, "custom_prompt", prompt_source="custom")
        return await safe_edit_or_send(
            query,
            quick_image_custom_prompt_text(lang, state.get("prompt") or ""),
            parse_mode="HTML",
            reply_markup=quick_image_custom_prompt_keyboard(lang),
        )
    if action.startswith("qi_ratio_"):
        state = get_quick_image_flow(uid) or {}
        prompt = str(state.get("prompt") or "").strip()
        if not prompt:
            set_quick_image_flow(uid, "entry", suggest_offset=0)
            return await safe_edit_or_send(query, quick_image_entry_text(lang), parse_mode="HTML", reply_markup=quick_image_entry_keyboard(lang))
        aspect = media_aspect_ratio_from_token(action.replace("qi_ratio_", "", 1), "image")
        state = set_quick_image_flow(uid, "tier", aspect_ratio=aspect)
        return await safe_edit_or_send(
            query,
            quick_image_tier_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_tier_keyboard(lang),
        )
    if action == "qi_back_ratio":
        state = get_quick_image_flow(uid) or {}
        if not state.get("prompt"):
            set_quick_image_flow(uid, "entry", suggest_offset=0)
            return await safe_edit_or_send(query, quick_image_entry_text(lang), parse_mode="HTML", reply_markup=quick_image_entry_keyboard(lang))
        state = set_quick_image_flow(uid, "ratio")
        return await safe_edit_or_send(
            query,
            quick_image_ratio_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_ratio_keyboard(lang),
        )
    if action == "qi_back_tier":
        state = get_quick_image_flow(uid) or {}
        token = str(state.get("confirm_token") or "")
        if token:
            pop_shopaikey_pending_confirmation(token, uid)
        if not state.get("prompt") or not state.get("aspect_ratio"):
            set_quick_image_flow(uid, "entry", suggest_offset=0)
            return await safe_edit_or_send(query, quick_image_entry_text(lang), parse_mode="HTML", reply_markup=quick_image_entry_keyboard(lang))
        state = set_quick_image_flow(uid, "tier", confirm_token="")
        return await safe_edit_or_send(
            query,
            quick_image_tier_text(state, lang),
            parse_mode="HTML",
            reply_markup=quick_image_tier_keyboard(lang),
        )
    if action.startswith("qi_tier_"):
        state = get_quick_image_flow(uid) or {}
        prompt = str(state.get("prompt") or "").strip()
        original_request = str(state.get("original_request") or state.get("selected_topic") or prompt).strip()
        aspect = normalize_media_aspect_ratio(state.get("aspect_ratio"), "1:1", "image")
        if not prompt:
            set_quick_image_flow(uid, "entry", suggest_offset=0)
            return await safe_edit_or_send(query, quick_image_entry_text(lang), parse_mode="HTML", reply_markup=quick_image_entry_keyboard(lang))
        tier = normalize_image_tier(action.replace("qi_tier_", "", 1))
        payload = image_tier_payload(tier)
        if not payload.get("enabled"):
            return await safe_edit_or_send(query, ui_text(lang, "image.tier_disabled_message"))
        enabled, _message = shopaikey_public_generation_guard("image")
        if not enabled:
            return await safe_edit_or_send(query, ui_text(lang, "media.public_off"))
        if shopaikey_active_job_for_user(uid, "image"):
            return await safe_edit_or_send(query, ui_text(lang, "media.job_lock"))
        credits, _, _ = get_user(uid, query.from_user.first_name or query.from_user.username or "Image user")
        base_cost = int(payload.get("cost") or 0)
        final_preview_cost = shopaikey_preview_final_cost(uid, base_cost, "shopaikey_image")
        package_item_type = package_item_type_for_image_tier(tier)
        package_item = active_package_item_for_user(uid, package_item_type)
        if int(credits or 0) < final_preview_cost and not is_admin_user(uid) and not package_item:
            return await edit_insufficient_credits(query, int(credits or 0), final_preview_cost, uid)
        logo_text = logo_watermark_clean_text(state.get("logo_watermark_text") if state.get("logo_watermark_enabled") else "")
        logo_position = logo_watermark_normalize_position(state.get("logo_watermark_position") or "", "bottom_right")
        generation_prompt = image_tier_prompt_for_generation(original_request, tier, aspect)
        generation_prompt = apply_logo_watermark_to_prompt(generation_prompt, logo_text, "image", logo_position)
        token = set_shopaikey_pending_confirmation(uid, {
            "job_type": "image",
            "prompt": generation_prompt,
            "original_prompt": original_request,
            "base_cost": base_cost,
            "from_image": False,
            "image_tier": tier,
            "tier_label": payload.get("label") or tier,
            "model": payload.get("model") or SHOPAIKEY_IMAGE_MODEL or "nano-banana",
            "retry_warranty_count": int(payload.get("retry_warranty_count") or 0),
            "aspect_ratio": aspect,
            "package_item_type": package_item_type,
            "source": "quick_image_v6",
            **logo_watermark_session_fields(bool(logo_text), logo_text, logo_position),
        })
        set_quick_image_flow(uid, "confirm", tier=tier, confirm_token=token)
        confirm_text = public_image_confirm_text(tier, prompt, int(credits or 0), lang, aspect, logo_text, logo_position)
        confirm_markup = quick_image_confirm_keyboard(token, lang)
        if package_item:
            confirm_text = package_offer_text(package_item, confirm_text, lang)
            confirm_markup = package_use_choice_keyboard("image", token, tier, lang)
        return await safe_edit_or_send(
            query,
            confirm_text,
            parse_mode="HTML",
            reply_markup=confirm_markup,
        )
    if action.startswith("ia_") or action.startswith("va_"):
        token = action.split("_", 1)[1]
        pending_confirm = pop_shopaikey_pending_confirmation(token, uid) or {}
        if not pending_confirm:
            return await safe_edit_or_send(query, ui_text(lang, "common.expired_not_charged"))
        job_type = "image" if str(pending_confirm.get("job_type") or "").lower() == "image" else "video"
        tier = normalize_image_tier(pending_confirm.get("image_tier") or "") if job_type == "image" else normalize_video_tier(pending_confirm.get("video_tier") or "")
        prompt = str(pending_confirm.get("original_prompt") or "").strip() or str(pending_confirm.get("prompt") or "").strip()
        package = {}
        if job_type == "video":
            package = {
                "source": str(pending_confirm.get("source") or "")[:80],
                "source_job_id": str(pending_confirm.get("source_job_id") or "")[:80],
                "image_url": str(pending_confirm.get("image_url") or "")[:1000],
                "telegram_file_id": str(pending_confirm.get("telegram_file_id") or "")[:220],
                "video_prompt": prompt,
                "music_choice": {"label": str(pending_confirm.get("music_label") or "").strip()},
                "package_id": str(pending_confirm.get("package_id") or "")[:80],
            }
        set_media_aspect_pending(uid, job_type, tier, prompt, package)
        update_media_aspect_pending(
            uid,
            **logo_watermark_session_fields(
                bool(pending_confirm.get("logo_watermark_enabled")),
                str(pending_confirm.get("logo_watermark_text") or ""),
                str(pending_confirm.get("logo_watermark_position") or ""),
            ),
            logo_watermark_decided=True,
        )
        return await safe_edit_or_send(
            query,
            public_media_aspect_ratio_text(job_type, tier, prompt, lang),
            parse_mode="HTML",
            reply_markup=public_media_aspect_ratio_keyboard(job_type, lang),
        )
    if action in {"image_logo_choice", "image_logo_add", "image_logo_skip", "image_logo_pos", "image_logo_confirm"}:
        pending_aspect = get_media_aspect_pending(uid, "image") or {}
