def pricing_detail_keyboard(section: str = "main", lang: str = "vi") -> InlineKeyboardMarkup:
    rows = []
    if section in {"image", "video"}:
        rows.append([
            InlineKeyboardButton("💳 Nạp Xu", callback_data="menu|main_topup"),
            InlineKeyboardButton("🎁 Gói / Combo", callback_data="pricing|packages"),
        ])
    elif section == "storage":
        rows.append([
            InlineKeyboardButton("📦 Mua thêm dung lượng", callback_data="menu|memory_storage_addon"),
            InlineKeyboardButton("💾 Dung lượng của tôi", callback_data="menu|memory_storage_status"),
        ])
    rows.append([InlineKeyboardButton(ui_text(lang, "pricing.back"), callback_data="pricing|catalog"), InlineKeyboardButton(ui_text(lang, "common.main_menu"), callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)

def pricing_combo_keyboard(lang: str = "vi") -> InlineKeyboardMarkup:
    rows: list[list[InlineKeyboardButton]] = []
    pending: list[InlineKeyboardButton] = []
    for item in public_video_combo_pricing_payload():
        code = str(item.get("code") or "").strip()
        label = str(item.get("button_label") or item.get("label") or code)
        callback = "menu|support" if item.get("manual") or not int(item.get("price_vnd") or 0) else f"pkgbuy|combo|{code}"
        pending.append(InlineKeyboardButton(label, callback_data=callback))
        if len(pending) == 2:
            rows.append(pending)
            pending = []
    if pending:
        rows.append(pending)
    rows.append([InlineKeyboardButton("📩 Cần gói lớn hơn", callback_data="pricing|need_larger"), InlineKeyboardButton("📦 Gói của tôi", callback_data="pricing|my_packages")])
    rows.append([InlineKeyboardButton("⬅️ Nạp Xu / Bảng giá", callback_data="pricing|main"), InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")])
    return InlineKeyboardMarkup(rows)

