async def handle_package_purchase_callback(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    parts = (query.data or "").split("|")
    if len(parts) < 3:
        return await safe_edit_or_send(query, "⚠️ Gói không hợp lệ. Bot chưa tạo đơn.")
    if parts[1] == "confirm":
        if len(parts) < 4:
            return await safe_edit_or_send(query, "⚠️ Xác nhận không hợp lệ. Bot chưa tạo đơn.")
        package_type, code = parts[2], parts[3]
        return await start_package_purchase(update, context, package_type, code, message=query.message)
    package_type, code = parts[1], parts[2]
    entry = package_catalog_entry(code, package_type)
    if not entry:
        return await safe_edit_or_send(query, "⚠️ Gói không hợp lệ. Bot chưa tạo đơn.")
    if entry.get("manual"):
        return await edit_or_send_pricing_lines(
            query,
            package_purchase_detail_lines(package_type, code),
            package_purchase_manual_keyboard(package_type, code),
        )
    return await edit_or_send_pricing_lines(
        query,
        package_purchase_detail_lines(package_type, code),
        package_purchase_confirm_keyboard(package_type, code),
    )

async def cmd_admin_grant_plan(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Bạn không có quyền dùng lệnh này.")
    try:
        target_id = str(context.args[0])
        plan_id = normalize_plan_id(context.args[1])
        days = int(context.args[2]) if len(context.args) >= 3 else int(PLAN_CATALOG[plan_id]["duration_days"])
        if not plan_id or days <= 0:
            raise ValueError("invalid")
    except Exception:
        return await update.message.reply_text(
            "⚠️ Cú pháp: <code>/admin_grant_plan &lt;user_id&gt; &lt;starter|creator|pro|business&gt; &lt;days&gt;</code>",
            parse_mode="HTML",
        )
    get_user(target_id)
    conn = db_connect()
    try:
        conn.execute("BEGIN IMMEDIATE")
        info = activate_user_plan_conn(conn, target_id, plan_id, days=days, order_code="", source=f"admin:{update.effective_user.id}")
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=(
                f"🎁 <b>Bạn đã được admin cấp gói {html.escape(info['plan_name'])}</b>\n\n"
                f"Thời hạn: <b>{int(info['duration_days'])} ngày</b>\n"
                f"Hạn mức xử lý: <b>{int(info['plan_xu']):,} Xu</b>\n"
                f"Hết hạn: <code>{html.escape(info['expires_at'])}</code>"
            ),
            parse_mode="HTML",
        )
    except Exception as e:
        logger.warning(f"Admin grant plan notify failed: {e}")
    await update.message.reply_text(
        f"✅ Đã cấp gói <b>{html.escape(info['plan_name'])}</b> cho user <code>{html.escape(target_id)}</code> trong <b>{int(info['duration_days'])} ngày</b>.\n"
        "Không tính vào tổng nạp nâng hạng.",
        parse_mode="HTML",
    )

