    if intent == "affiliate_report":
        return f"/affiliate_report days={max(1, min(int(plan.get('days') or 30), 180))} limit={max(3, min(int(plan.get('limit') or 15), 30))}"
    if intent == "affiliate_decisions":
        return (
            f"/affiliate_decisions days={max(1, min(int(plan.get('days') or 30), 180))} "
            f"platform={plan.get('platform') or 'tiktok'} limit={max(3, min(int(plan.get('limit') or 12), 30))}"
        )
    if intent == "affiliate_import":
        return f"/affiliate_import {plan.get('topic') or plan.get('raw') or '<PASTE_LINKS>'}"
    if intent == "operator":
        return (
            f"/operator topic={plan.get('topic') or plan.get('niche') or 'video affiliate'} "
            f"channel={int(plan.get('channel') or 0)} aff={int(plan.get('affiliate') or 0)} "
            f"campaign={int(plan.get('campaign') or 0)}"
        )
    if intent == "operator_build":
        return f"/operator_build job={int(plan.get('job') or 0)} n={max(2, min(int(plan.get('limit') or 5), 8))} duration={int(plan.get('duration') or 45)}"
    if intent == "worker_next":
        return (
            f"/worker_next job={int(plan.get('job') or 0)} "
            f"tool={plan.get('tool') or ''} limit={max(1, min(int(plan.get('limit') or 5), 10))}"
        )
    if intent == "next_task":
        parts = ["/next_task"]
        if int(plan.get("job") or 0):
            parts.append(f"job={int(plan.get('job') or 0)}")
        if plan.get("tool"):
            parts.append(f"tool={plan.get('tool')}")
        return " ".join(parts)
    if intent == "task_handoff":
        return f"/task_handoff id={int(plan.get('task') or plan.get('id') or 0)}"
    if intent == "compose_video":
        return (
            f"/compose_video job={int(plan.get('job') or 0)} "
            f"voice={int(plan.get('include_voice') if plan.get('include_voice') is not None else 1)} "
            f"force={int(plan.get('force') or 0)}"
        )
    if intent == "review_video":
        return f"/review_video job={int(plan.get('job') or 0)} send={safe_int(plan.get('send') if plan.get('send') is not None else 1, 1)}"
    if intent == "post_publish":
        return f"/post_publish job={int(plan.get('job') or 0)} days={max(1, min(int(plan.get('days') or 30), 180))}"
    if intent == "job_ready":
        return f"/job_ready job={int(plan.get('job') or 0)}"
    if intent == "operator_daily":
        return f"/operator_daily days={max(1, min(int(plan.get('days') or 1), 30))}"
    if intent == "trend_search":
        return (
            f"/trend_search niche={plan.get('niche') or 'công nghệ AI'} "
            f"platform={plan.get('platform') or 'tiktok'} channel={int(plan.get('channel') or 0)} "
            f"aff={int(plan.get('affiliate') or 0)} campaign={int(plan.get('campaign') or 0)}"
        )
    if intent == "publish_queue":
        return "/publish_queue"
    if intent == "performance":
        return "/performance"
    return "/operator_menu"

