async def cmd_setvip(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    valid_tiers = {"silver", "gold", "platinum", "diamond", "vip"}
    invalid_message = "⚠️ Hạng không hợp lệ. Chỉ hỗ trợ: silver, gold, platinum, diamond, vip."
    syntax = (
        "⚠️ Cú pháp: /setvip <ID> <silver|gold|platinum|diamond|vip>\n"
        "Ví dụ: /setvip 7817576663 gold"
    )
    if len(context.args or []) < 2:
        return await update.message.reply_text(syntax)
    target_id = str(context.args[0]).strip()
    raw_tier = " ".join(context.args[1:]).strip().lower()
    if raw_tier == "1":
        tier = "vip"
    elif raw_tier == "0":
        return await update.message.reply_text(invalid_message)
    else:
        tier = normalize_member_tier(raw_tier)
    if tier not in valid_tiers:
        return await update.message.reply_text(invalid_message)
    if not user_exists(target_id):
        return await update.message.reply_text(f"⚠️ Không tìm thấy user <code>{html.escape(str(target_id))}</code>. User cần bấm /start trước.", parse_mode="HTML")
    conn = db_connect()
    try:
        before = get_member_profile(target_id, conn=conn)
        conn.execute(
            """INSERT OR REPLACE INTO member_tier_overrides (user_id, tier, reason, updated_at)
            VALUES (?,?,?,?)""",
            (str(target_id), tier, f"Admin /setvip override by {update.effective_user.id}", now_text()),
        )
        conn.execute("UPDATE users SET vip_tier_override=?, is_vip=? WHERE user_id=?", (tier, 1 if tier == "vip" else 0, str(target_id)))
        record_audit(
            conn,
            update.effective_user.id,
            "admin",
            "member.tier_override_set",
            "user",
            str(target_id),
            before={"tier": before.get("tier")},
            after={"tier": tier},
            note="Admin updated member tier via /setvip",
        )
        conn.commit()
    finally:
        conn.close()
    label = member_tier_label(tier)
    notify_warning = ""
    try:
        await context.bot.send_message(
            chat_id=target_id,
            text=f"✅ Đã cập nhật hạng thành viên: <b>{html.escape(label)}</b>.",
            parse_mode="HTML",
        )
    except Exception as e:
        notify_warning = (
            "\n⚠️ Đã cập nhật hạng nhưng chưa gửi được thông báo cho user."
            f"\n• Error: <code>{html.escape(provider_error_summary(e))}</code>"
        )
        logger.warning("Setvip target notify failed | %s", sanitize_log_text(str(e))[:240])
    await update.message.reply_text(
        f"✅ Đã cập nhật hạng thành viên: <b>{html.escape(label)}</b>.\n"
        f"• User: <code>{html.escape(str(target_id))}</code>\n"
        f"• Admin: <code>{html.escape(str(update.effective_user.id))}</code>"
        f"{notify_warning}",
        parse_mode="HTML",
    )

async def cmd_backup_db(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not is_admin_user(update.effective_user.id):
        return
    if flag_on("emergency_lock") and not is_owner_user(update.effective_user.id):
        return await update.message.reply_text("⛔ Emergency mode: chỉ owner được chạy /backup_db.")
    admin_id = str(update.effective_user.id)
    result = create_db_backup_now(admin_id, "/backup_db")
    action = "backup.created" if result.get("ok") else "backup.failed"
    record_audit_event(
        update.effective_user.id,
        "admin",
        action,
        "database",
        os.path.basename(str(DB_FILE or "toandaas_system.db")),
        after={
            "ok": bool(result.get("ok")),
            "reason": result.get("reason") or "",
            "filename": result.get("filename") or "",
            "size": result.get("size_bytes") or 0,
        },
        note="/backup_db_now" if (update.message and str(update.message.text or "").startswith("/backup_db_now")) else "/backup_db",
    )
    record_security_event(
        "db_backup_created" if result.get("ok") else "db_backup_failed",
        "medium" if result.get("ok") else "high",
        {"ok": bool(result.get("ok")), "reason": result.get("reason") or "", "filename": result.get("filename") or ""},
        user_id=admin_id,
        username=str(update.effective_user.username or ""),
        action="backup_db",
    )
    text = backup_db_result_text(result)
    if result.get("ok") and result.get("path") and os.path.exists(result["path"]) and int(result.get("size_bytes") or 0) <= BACKUP_MAX_BYTES:
        try:
            with open(result["path"], "rb") as f:
                await context.bot.send_document(
                    chat_id=update.effective_chat.id if update.effective_chat else ADMIN_ID,
                    document=f,
                    filename=result.get("filename") or db_backup_filename(),
                    caption=text,
                    parse_mode="HTML",
                )
            return
        except Exception as e:
            logger.warning("DB backup document send failed: %s", sanitize_log_text(str(e))[:160])
            text += f"\n\n⚠️ Không gửi được file qua Telegram: <code>{safe_html(provider_error_summary(e))}</code>"
    await update.message.reply_text(text, parse_mode="HTML", reply_markup=admin_db_status_keyboard())

# ─── OPERATIONS V1A: INTERNAL BUSINESS ARCHIVE ───────────────────────────────
INTERNAL_ARCHIVE_TTL_SECONDS = 15 * 60

def internal_archive_pending_key(user_id) -> str:
    return f"internal_archive:{user_id}"

def set_internal_archive_pending(user_id, step: str, **fields) -> dict:
    key = internal_archive_pending_key(user_id)
    current = USER_PENDING.get(key) or {}
    state = dict(current) if current.get("pending_action") == "internal_archive" else {}
    state.update({
        "pending_action": "internal_archive",
        "step": str(step or "")[:60],
        "created_at_ts": time.time(),
    })
    state.update({key: value for key, value in fields.items() if key not in {"pending_action", "step", "created_at_ts"}})
    USER_PENDING[key] = state
    return state

def get_internal_archive_pending(user_id) -> dict | None:
    key = internal_archive_pending_key(user_id)
    state = USER_PENDING.get(key) or {}
    if state.get("pending_action") != "internal_archive":
        return None
    if time.time() - float(state.get("created_at_ts") or 0) > INTERNAL_ARCHIVE_TTL_SECONDS:
        USER_PENDING.pop(key, None)
        return None
    return state

def clear_internal_archive_pending(user_id) -> bool:
    return USER_PENDING.pop(internal_archive_pending_key(user_id), None) is not None

