async def handle_photo(update: Update, context: ContextTypes.DEFAULT_TYPE):
    uid = update.effective_user.id
    username = update.effective_user.first_name
    bill_state = get_active_manual_bill_state(uid)
    is_bill = bool(bill_state)

    if is_bill:
        USER_BILL_STATE.pop(uid, None)
        photo = update.message.photo[-1]
        deposit = create_manual_pending_deposit(
            update.effective_user,
            bill_state,
            file_id=photo.file_id,
            file_unique_id=str(getattr(photo, "file_unique_id", "") or ""),
        )
        if not deposit.get("ok"):
            return await update.message.reply_text("⚠️ Không thể lưu bill này. Vui lòng mở lại Nạp thủ công và thử lại.")
        await notify_manual_pending_deposit(context, deposit)
        await update.message.reply_text(
            manual_pending_user_text(deposit),
            parse_mode="HTML",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📂 Lịch sử nạp thủ công", callback_data=f"manual|history|{uid}"), InlineKeyboardButton("💬 Hỗ trợ", callback_data="support|start")],
                [InlineKeyboardButton("🏠 Menu chính", callback_data="menu|main")],
            ]),
        )
        return

    if await handle_free_hub_pending_upload(update, context):
        return

    if await handle_internal_archive_pending_upload(update, context):
        return

    if await handle_support_ticket_attachment(update, context):
        return

    if await handle_doc_tool_pending_upload(update, context):
        return

    if await handle_video_product_pending_media(update, context):
        return

    if await handle_developing_video_pending_image(update, context):
        return

    if await handle_image_menu_pending_photo(update, context):
        return

    if await handle_frame_video_photo(update, context):
        return

    remember_last_user_file(update)
    cache_recent_media_state(update)
    await update.message.reply_text(
        image_upload_outside_flow_text(get_user_language(update.effective_user.id) if update.effective_user else "vi"),
        parse_mode="HTML",
        reply_markup=image_upload_outside_flow_keyboard(
            get_user_language(update.effective_user.id) if update.effective_user else "vi",
            admin=is_admin_user(update.effective_user.id) if update.effective_user else False,
        ),
    )

async def handle_translation_media_pending_upload(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    uid = update.effective_user.id
    pending = get_translation_menu_pending(uid)
    ctx = str((pending or {}).get("translation_context") or "")
    if ctx not in {"translate_file", "translate_audio"}:
        return False
    lang = get_user_language(uid) or "vi"
    message = update.message
    document = getattr(message, "document", None)
    audio = getattr(message, "audio", None)
    voice = getattr(message, "voice", None)
    video = getattr(message, "video", None)
    doc_mime = str(getattr(document, "mime_type", "") or "").lower()
    doc_name = str(getattr(document, "file_name", "") or "").lower()
    doc_is_audio = bool(doc_mime.startswith("audio/") or doc_name.endswith((".mp3", ".wav", ".m4a", ".ogg", ".oga", ".aac", ".flac")))
    doc_is_video = bool(doc_mime.startswith("video/") or doc_name.endswith((".mp4", ".mov", ".mkv", ".webm", ".avi")))

    if ctx == "translate_file":
        if document and not doc_is_audio and not doc_is_video:
            info, _source = doc_input_file_info(update)
            if info:
                save_translation_request(uid, "file", source_ref=info)
                clear_translation_menu_pending(uid)
                await show_translation_picker(update, "file")
                return True
        await message.reply_text(
            "Luồng này chỉ dùng để dịch file. Anh/chị hãy chọn Dịch audio hoặc Phụ đề / Lồng tiếng nếu cần xử lý video hoặc audio.",
            reply_markup=translation_input_keyboard(lang, parent="media"),
        )
        return True

    if ctx == "translate_audio":
        if video or doc_is_video:
            await message.reply_text(
                "Luồng này chỉ dùng để dịch audio. Nếu muốn xử lý video, anh/chị hãy chọn các nút video trong Phụ đề / Lồng tiếng.",
                reply_markup=translation_voice_menu_keyboard(lang, parent="media"),
            )
            return True
        if audio or voice or doc_is_audio:
            cache_recent_media_state(update)
            remember_last_media(update)
            save_translation_request(uid, "voice")
            clear_translation_menu_pending(uid)
            await show_translation_picker(update, "voice")
            return True
        await message.reply_text(
            "Luồng này chỉ dùng để dịch audio. Anh/chị gửi voice hoặc file âm thanh cần dịch.",
            reply_markup=translation_voice_menu_keyboard(lang, parent="media"),
        )
        return True
    return False

async def handle_document_cache_only(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if await handle_video_dubbing_pending_upload(update, context):
        return
    if await handle_video_product_pending_media(update, context):
        return
    if await handle_translation_media_pending_upload(update, context):
        return
    if await handle_translation_studio_lost_state_media(update, context):
        return
    if await handle_free_hub_pending_upload(update, context):
        return

    if await handle_internal_archive_pending_upload(update, context):
        return

    if await handle_support_ticket_attachment(update, context):
        return

    if await handle_doc_tool_pending_upload(update, context):
        return

    if await handle_developing_video_pending_image(update, context):
        return

    if await handle_image_menu_pending_document(update, context):
        return
    if update.effective_user and getattr(update.message, "document", None):
        document = update.message.document
        mime_type = str(getattr(document, "mime_type", "") or "").lower()
        file_name = str(getattr(document, "file_name", "") or "").lower()
        if mime_type.startswith("image/") or file_name.endswith((".jpg", ".jpeg", ".png", ".webp")):
            remember_last_user_file(update)
            lang = get_user_language(update.effective_user.id) or "vi"
            return await update.message.reply_text(
                image_upload_outside_flow_text(lang),
                parse_mode="HTML",
                reply_markup=image_upload_outside_flow_keyboard(lang, admin=is_admin_user(update.effective_user.id)),
            )
    remember_last_user_file(update)
    if update.effective_user:
        info, _source = doc_input_file_info(update)
        if info:
            save_translation_request(update.effective_user.id, "file", source_ref=info)
    await update.message.reply_text(
        "✅ Đã nhận file.\n\n"
        "Bạn có thể dùng:\n"
        "• /translate_file — chọn ngôn ngữ để dịch file\n"
        "• /translate_file en — dịch file sang English\n"
        "• /doc_tools — xem công cụ tài liệu khác\n\n"
        "File đã được lưu tạm 10 phút.",
        reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🌐 Dịch file", callback_data="tr_pick|file")]]),
    )

async def handle_caption_admin_tool_test_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    command, args = parse_admin_caption_tool_test(update.message)
    if not command:
        return False
    media, _file_type = message_media_candidate(update.message)
    if not media:
        return False
    cache_recent_media_state(update)
    remember_last_media(update)
    caption_context = admin_tool_test_context_from_args(context, args)
    if command == "tool_test_asr":
        await cmd_tool_test_asr(update, caption_context)
        return True
    if command == "tool_test_auto_subtitle":
        await cmd_tool_test_subtitle_generate(update, caption_context)
        return True
    if command == "tool_test_dub_audio":
        await cmd_tool_test_video_dub(update, caption_context)
        return True
    if command == "tool_test_full_dub_video":
        await cmd_tool_test_full_dub_video(update, caption_context)
        return True
    return False

async def handle_pending_admin_tool_test_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    uid = update.effective_user.id
    if not is_admin_user(uid):
        return False
    pending = get_pending_admin_tool_test(uid)
    if not pending or not pending.get("confirm_paid"):
        return False
    media, _file_type = message_media_candidate(update.message)
    if not media:
        return False
    cache_recent_media_state(update)
    remember_last_media(update)
    clear_pending_admin_tool_test(uid)
    confirmed_context = admin_tool_test_context_with_confirm(context)
    tool = str(pending.get("tool") or "")
    if tool == "asr":
        await cmd_tool_test_asr(update, confirmed_context)
        return True
    if tool == "auto_subtitle":
        await cmd_tool_test_subtitle_generate(update, confirmed_context)
        return True
    if tool == "dub_audio":
        await cmd_tool_test_video_dub(update, confirmed_context)
        return True
    if tool == "full_dub_video":
        await cmd_tool_test_full_dub_video(update, confirmed_context)
        return True
    return False

