def video_dubbing_pending_key(user_id) -> str:
    return f"video_dubbing:{user_id}"

def video_dubbing_artifact_key(user_id, kind: str) -> str:
    return f"video_dubbing_artifact:{user_id}:{str(kind or '')[:40]}"

def set_video_dubbing_artifact(user_id, kind: str, value: str) -> str:
    ref = video_dubbing_artifact_key(user_id, kind)
    USER_PENDING[ref] = {"value": str(value or ""), "created_at_ts": time.time()}
    return ref

def get_video_dubbing_artifact(user_id, ref_or_kind: str) -> str:
    ref = str(ref_or_kind or "")
    if not ref.startswith("video_dubbing_artifact:"):
        ref = video_dubbing_artifact_key(user_id, ref)
    payload = USER_PENDING.get(ref) or {}
    if time.time() - float(payload.get("created_at_ts") or 0) > VIDEO_DUBBING_TTL_SECONDS:
        USER_PENDING.pop(ref, None)
        return ""
    return str(payload.get("value") or "")

def normalize_video_translate_mode(value: str) -> str:
    aliases = {
        "subtitle": VIDEO_SUBTITLE_MODE_CREATE,
        "translate_subtitle": VIDEO_SUBTITLE_MODE_TRANSLATE,
        "voice": VIDEO_SUBTITLE_MODE_DUB,
        "translate_voice": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "translate_dub": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        "full_video": VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB,
        VIDEO_DUBBING_FLOW_SUBTITLE_FILE_TRANSLATE: VIDEO_SUBTITLE_MODE_TRANSLATE,
        VIDEO_DUBBING_FLOW_TRANSCRIPT: VIDEO_SUBTITLE_MODE_CREATE,
        "transcript": VIDEO_SUBTITLE_MODE_CREATE,
    }
    mode = aliases.get(str(value or "").strip(), str(value or "").strip())
    return mode if mode in VIDEO_TRANSLATE_MODES else ""

def video_dubbing_is_video_only_mode(mode: str) -> bool:
    return normalize_video_translate_mode(mode) in VIDEO_ONLY_TRANSLATE_MODES

def video_dubbing_is_video_upload_info(info: dict | None = None) -> bool:
    info = dict(info or {})
    media_kind = str(info.get("media_kind") or info.get("file_type") or "").strip().lower()
    mime_type = str(info.get("mime_type") or info.get("source_mime_type") or "").strip().lower()
    file_name = str(info.get("file_name") or info.get("source_file_name") or "").strip().lower()
    return bool(
        media_kind == "video"
        or mime_type.startswith("video/")
        or file_name.endswith((".mp4", ".mov", ".mkv", ".webm"))
    )

