def video_dubbing_uses_custom_voice(state: dict | None = None) -> bool:
    state = dict(state or {})
    voice_kind = str(state.get("voice_kind") or "").strip().lower()
    voice_id = str(state.get("voice_id") or "").strip()
    voice_profile_id = _safe_int(state.get("voice_profile_id"), 0)
    if voice_kind in {"saved_voice", "custom_clone", "custom_prompt"}:
        return True
    return bool(voice_profile_id or (voice_id and voice_kind not in {"default_female", "default_male"}))

def video_dubbing_voice_rate_xu(state: dict | None = None) -> float:
    return VIDEO_ONLY_DUB_CUSTOM_RATE_XU if video_dubbing_uses_custom_voice(state) else VIDEO_ONLY_DUB_DEFAULT_RATE_XU

def video_dubbing_saved_voice_keyboard(user_id, lang: str = "vi", page: int = 0) -> InlineKeyboardMarkup:
    is_vi = normalize_user_language(lang) == "vi"
    page = max(0, int(page or 0))
    page_size = voice_vault_page_size(5)
    total = user_voice_profile_count(user_id)
    profiles = user_voice_profile_rows(user_id, page_size, page * page_size)
    buttons = []
    for index_on_page, _profile in enumerate(profiles):
        code = voice_profile_display_code(page, index_on_page, page_size)
        buttons.append((str(code), f"videodub|voice_profile|{code}"))
    if page > 0:
        buttons.append(("⬅️ Trang trước" if is_vi else "⬅️ Previous", f"videodub|voice_profile_page|{page - 1}"))
    if (page + 1) * page_size < total:
        buttons.append(("➡️ Trang sau" if is_vi else "➡️ Next", f"videodub|voice_profile_page|{page + 1}"))
    return video_v6_keyboard(
        buttons,
        lang,
        back=("⬅️ Quay lại giọng" if is_vi else "⬅️ Back to voices", "videodub|back_voice"),
    )

def video_dubbing_voice_payload(choice: str, profile: dict | None = None, lang: str = "vi") -> dict:
    value = str(choice or "").strip()
    normalized = value.lower()
    if profile:
        return {
            "voice_style": str(profile.get("display_name") or "Voice đã lưu")[:120],
            "voice_id": str(profile.get("provider_voice_id") or "")[:180],
            "voice_kind": "saved_voice",
            "voice_profile_id": int(profile.get("id") or 0),
        }
    if normalized in {"default_female", "female", "nữ tự nhiên", "nu tu nhien"}:
        label = value[:120] if normalized in {"nữ tự nhiên", "nu tu nhien"} else ("giọng nữ mặc định" if normalize_user_language(lang) == "vi" else "default female voice")
        return {
            "voice_style": label,
            "voice_id": get_tts_voice_id("default_female"),
            "voice_kind": "default_female",
            "voice_profile_id": 0,
        }
    if normalized in {"default_male", "male", "nam tự nhiên", "nam tu nhien"}:
        label = value[:120] if normalized in {"nam tự nhiên", "nam tu nhien"} else ("giọng nam mặc định" if normalize_user_language(lang) == "vi" else "default male voice")
        return {
            "voice_style": label,
            "voice_id": get_tts_voice_id("default_male"),
            "voice_kind": "default_male",
            "voice_profile_id": 0,
        }
    return {
        "voice_style": value[:120] or ("giọng lồng tiếng tự nhiên" if normalize_user_language(lang) == "vi" else "natural dubbing voice"),
        "voice_id": "",
        "voice_kind": "custom_prompt",
        "voice_profile_id": 0,
    }

def video_dubbing_invoice_breakdown(state: dict | None = None) -> dict:
    state = dict(state or {})
    mode = normalize_video_translate_mode(state.get("mode") or state.get("video_processing_mode"))
    chars = video_dubbing_billing_char_count(state)
    subtitle_price = calculate_video_only_char_price(chars, VIDEO_ONLY_SUBTITLE_TRANSLATE_RATE_XU)
    voice_rate = video_dubbing_voice_rate_xu(state)
    dub_price = calculate_video_only_char_price(chars, voice_rate)
    translation_needed = mode in {VIDEO_SUBTITLE_MODE_TRANSLATE, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
    dubbing_needed = mode in {VIDEO_SUBTITLE_MODE_DUB, VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB}
    translation_xu = int(subtitle_price.get("total_xu") or 0) if translation_needed else 0
    voice_xu = int(dub_price.get("total_xu") or 0) if dubbing_needed else 0
    return {
        "chars": chars,
        "subtitle_chars": chars,
        "dub_chars": chars,
        "subtitle_rate_xu": VIDEO_ONLY_SUBTITLE_TRANSLATE_RATE_XU,
        "dub_rate_xu": voice_rate,
        "subtitle_discount_percent": int(subtitle_price.get("discount_percent") or 0),
        "dub_discount_percent": int(dub_price.get("discount_percent") or 0),
        "subtitle_xu": 0,
        "translation_xu": translation_xu,
        "voice_xu": voice_xu,
        "mix_xu": 0,
        "link_xu": int(state.get("link_import_charged_xu") or 0),
        "total_xu": translation_xu + voice_xu,
    }

def video_dubbing_estimated_price_xu(state: dict | None = None) -> int:
    try:
        return max(0, int(video_dubbing_invoice_breakdown(state).get("total_xu") or 0))
    except Exception:
        return 0

def video_dubbing_final_video_label(mode: str, lang: str = "vi") -> tuple[str, str, str]:
    mode = normalize_video_translate_mode(mode)
    is_vi = normalize_user_language(lang) == "vi"
    if mode == VIDEO_SUBTITLE_MODE_TRANSLATE:
        return (
            "toan_aas_translated_subtitle_video.mp4",
            "✅ Đã tạo video phụ đề dịch." if is_vi else "✅ Translated subtitle video is ready.",
            "📹 Tải video phụ đề dịch" if is_vi else "📹 Download translated subtitle video",
        )
    if mode == VIDEO_SUBTITLE_MODE_DUB:
        return (
            "toan_aas_dub_video.mp4",
            "✅ Đã tạo video lồng tiếng." if is_vi else "✅ Dubbed video is ready.",
            "📹 Tải video lồng tiếng" if is_vi else "📹 Download dubbed video",
        )
    if mode == VIDEO_SUBTITLE_MODE_SUBTITLE_PLUS_DUB:
        return (
            "toan_aas_subtitle_dub.mp4",
            "✅ Đã tạo video phụ đề + lồng tiếng." if is_vi else "✅ Subtitle + dubbed video is ready.",
            "📹 Tải video hoàn chỉnh" if is_vi else "📹 Download final video",
        )
    return (
        "toan_aas_subtitle_video.mp4",
        "✅ Đã tạo video phụ đề." if is_vi else "✅ Subtitle video is ready.",
        "📹 Tải video phụ đề" if is_vi else "📹 Download subtitle video",
    )

