async def handle_feedback_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_feedback_pending(uid)
    if not pending:
        return False
    text = update.message.text.strip()
    if not text:
        return True
    category = str(pending.get("category") or "other")
    if category not in SUPPORT_CATEGORIES:
        category = "other"
    classification = await classify_support_message(text, uid)
    priority = support_ticket_priority(category, text)
    reply_ids = {
        "payment_topup": "payment_missing_xu",
        "refund": "refund_review",
        "image_error": "technical_image_error",
        "video_error": "technical_video_error",
        "document_pdf": "technical_deep_question",
        "package_combo": "feature_video_affiliate",
        "feature_request": "feature_video_affiliate",
        "other": classification.get("suggested_reply_id") or "feature_video_affiliate",
    }
    classification.update({
        "matched": True,
        "needs_admin": True,
        "priority": priority,
        "reason": classification.get("reason") or f"structured_feedback_{category}",
        "ticket_category": category,
        "suggested_reply_id": reply_ids.get(category, "feature_video_affiliate"),
        "should_create_ticket": True,
        "should_alert_admin": True,
        "allowed_auto_send": True,
        "classifier_source": "structured_feedback",
    })
    context_note = str(pending.get("context_note") or "").strip()
    ticket_text = text if not context_note else f"{text}\n\n[Video result context] {context_note}"
    ticket, is_new = create_or_append_support_ticket(update.effective_user, category, ticket_text, classification)
    clear_feedback_pending(uid)
    lang = user_ui_lang(uid)
    if normalize_user_language(lang) != "vi":
        message = (
            "✅ <b>Thank you.</b> TOAN AAS has created a support ticket.\n\n"
            f"Ticket: <code>{html.escape(ticket.get('ticket_code') or '')}</code>\n"
            "The bot has not called AI/API and has not charged Xu."
        )
    else:
        message = (
            "✅ <b>Cảm ơn bạn.</b> TOAN AAS đã tạo ticket góp ý/báo lỗi.\n\n"
            f"Mã ticket: <code>{html.escape(ticket.get('ticket_code') or '')}</code>\n"
            "Admin sẽ kiểm tra nội dung. Bot chưa gọi AI/API, chưa trừ và chưa tự hoàn Xu."
        )
    await update.message.reply_text(
        message,
        parse_mode="HTML",
        reply_markup=support_ticket_created_keyboard(ticket["id"]),
    )
    await notify_admin_new_support_ticket(
        context,
        ticket,
        classification,
        support_reply_for_classification(classification),
        is_new=is_new,
        customer_message=text,
    )
    return True

async def handle_free_hub_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    state = get_free_hub_pending(uid)
    if not state or state.get("step") != "input":
        return False
    text = re.sub(r"\s+", " ", update.message.text.strip())[:2000]
    if not text:
        return True
    lang = get_user_language(uid) or "vi"
    task_type = str(state.get("task_type") or "")
    reason = sensitive_free_task_reason(text, task_type)
    if reason:
        clear_free_hub_pending(uid)
        await update.message.reply_text(
            free_hub_sensitive_text(lang),
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("👨‍💼 Hỗ trợ", callback_data="menu|support")],
                [InlineKeyboardButton("⬅️ Công cụ miễn phí", callback_data="freehub|main")],
            ]),
        )
        return True
    quota = free_hub_quota_payload(uid)
    if not quota["allowed"]:
        clear_free_hub_pending(uid)
        await update.message.reply_text(free_hub_quota_exhausted_text(lang), reply_markup=free_hub_main_keyboard(lang))
        return True
    if task_type == "meta_ai_prompt":
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type == "content_idea":
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type == "caption_hashtag":
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type == "image_video_prompt":
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type in {"image_prompt", "video_prompt"}:
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type == "hook_script":
        payload, task_type, provider = free_hub_generate_task_payload(task_type, text)
    elif task_type == "free_chat":
        result = await free_provider_router_call(task_type, text, uid)
        if result.get("blocked"):
            clear_free_hub_pending(uid)
            await update.message.reply_text(free_hub_sensitive_text(lang), reply_markup=free_hub_main_keyboard(lang))
            return True
        if not result.get("ok"):
            clear_free_hub_pending(uid)
            await update.message.reply_text(
                "⚠️ Provider AI miễn phí đang bận hoặc chưa cấu hình. TOAN AAS chưa trừ Xu. "
                "Bạn vẫn có thể dùng thư viện prompt và các công cụ content local.",
                reply_markup=free_hub_main_keyboard(lang),
            )
            return True
        payload = {
            "title": "Hỏi AI miễn phí",
            "prompt": str(result.get("text") or ""),
            "copy_instruction": "Kết quả AI miễn phí; hãy kiểm tra lại thông tin quan trọng trước khi sử dụng.",
        }
        provider = str(result.get("provider") or "free_router")
    else:
        clear_free_hub_pending(uid)
        return False
    set_free_hub_pending(
        uid,
        "result",
        task_type=task_type,
        user_input=text,
        result=payload,
        provider=provider,
        context=dict(payload.get("context") or {}),
    )
    count = free_hub_record_success(update.effective_user, task_type, provider)
    await update.message.reply_text(
        free_hub_prompt_result_text(payload, task_type, provider),
        parse_mode="HTML",
        reply_markup=free_hub_result_keyboard(lang, task_type, meta=task_type == "meta_ai_prompt"),
    )
    await maybe_send_free_hub_promo(update.message, uid, lang, count)
    return True

async def handle_free_hub_pending_upload(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.effective_user or not update.message:
        return False
    uid = update.effective_user.id
    state = get_free_hub_pending(uid)
    if not state or state.get("step") != "upload":
        return False
    lang = get_user_language(uid) or "vi"
    photo = bool(getattr(update.message, "photo", None))
    video = bool(getattr(update.message, "video", None))
    document = getattr(update.message, "document", None)
    if document:
        mime_type = str(getattr(document, "mime_type", "") or "").lower()
        file_name = str(getattr(document, "file_name", "") or "").lower()
        photo = photo or mime_type.startswith("image/") or file_name.endswith((".jpg", ".jpeg", ".png", ".webp"))
        video = video or mime_type.startswith("video/") or file_name.endswith((".mp4", ".mov", ".mkv", ".webm"))
    if not (photo or video or document):
        await update.message.reply_text("⚠️ Hãy gửi một ảnh, video hoặc tài liệu nhỏ. Bot chưa trừ Xu.")
        return True
    remember_last_user_file(update)
    if photo:
        clear_free_hub_pending(uid)
        await update.message.reply_text(
            "✅ Đã nhận ảnh và lưu tạm.\n\nBạn có thể tạo prompt/caption miễn phí hoặc mở công cụ ảnh hiện có. "
            "Tác vụ render/chỉnh sửa tốn Xu phải báo giá trước.",
            reply_markup=image_upload_outside_flow_keyboard(lang, admin=is_admin_user(uid)),
        )
        return True
    if video:
        cache_recent_media_state(update)
        remember_last_media(update)
        clear_free_hub_pending(uid)
        await update.message.reply_text(
            "✅ Đã nhận video và lưu tạm.\n\nBạn có thể lấy ý tưởng/caption miễn phí hoặc mở công cụ hậu kỳ video hiện có. "
            "Phụ đề/lồng tiếng/render tốn Xu phải báo giá và xác nhận trước.",
            reply_markup=video_upload_received_keyboard(uid, lang),
        )
        return True
    clear_free_hub_pending(uid)
    await update.message.reply_text(
        "✅ Đã nhận tài liệu và lưu tạm.\n\nHãy chọn công cụ PDF/Word hiện có để xử lý. Bot chưa trừ Xu.",
        reply_markup=free_hub_docs_keyboard(lang),
    )
    return True

async def handle_translation_menu_pending_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    pending = get_translation_menu_pending(uid)
    if not pending:
        return False
    text = update.message.text.strip()
    if not text:
        return True
    lang = get_user_language(uid) or "vi"
    source_type = str(pending.get("source_type") or "text")
    if source_type == "text_target_custom":
        target = normalize_translate_target(text)
        if not target:
            await update.message.reply_text(
                "⚠️ Ngôn ngữ này chưa được nhận diện. Hãy nhập tên hoặc mã ngôn ngữ khác.",
                reply_markup=translation_input_keyboard(lang),
            )
            return True
        set_translation_menu_pending(uid, "text", target_language=target)
        await update.message.reply_text(
            f"📝 Gửi văn bản cần dịch sang <b>{html.escape(translate_target_label(target))}</b>.",
            parse_mode="HTML",
            reply_markup=translation_input_keyboard(lang),
        )
        return True
    if source_type == "pair_custom":
        normalized = re.sub(r"\s+", "", text.lower().replace("↔", "-").replace("/", "-").replace(",", "-"))
        parts = [part for part in re.split(r"[-|:]+", normalized) if part]
        if len(parts) < 2:
            await update.message.reply_text(
                "⚠️ Vui lòng nhập cặp ngôn ngữ dạng <code>vi-en</code> hoặc <code>zh-vi</code>. Bot chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=translation_input_keyboard(lang),
            )
            return True
        lang_a = normalize_translate_target(parts[0])
        lang_b = normalize_translate_target(parts[1])
        if not lang_a or not lang_b:
            await update.message.reply_text(
                "⚠️ Có ngôn ngữ chưa hỗ trợ. Ví dụ hợp lệ: <code>vi-en</code>, <code>zh-vi</code>, <code>ja-vi</code>. Bot chưa trừ Xu.",
                parse_mode="HTML",
                reply_markup=translation_input_keyboard(lang),
            )
            return True
        clear_translation_menu_pending(uid)
        session = set_translation_session(uid, "two_way", lang_a, lang_b, input_mode="text_voice", output_mode="text")
        await update.message.reply_text(
            translation_session_started_text(session, lang),
            parse_mode="HTML",
            reply_markup=translation_session_keyboard(lang, "two_way"),
        )
        return True
    if len(text) > 3000:
        await update.message.reply_text(
            "⚠️ Nội dung dài hơn 3.000 ký tự. Vui lòng chia thành từng đoạn ngắn để dịch ổn định. Bot chưa trừ Xu."
            if normalize_user_language(lang) == "vi" else
            "⚠️ Text is longer than 3,000 characters. Split it into shorter sections. No Xu charged.",
            reply_markup=translation_input_keyboard(lang),
        )
        return True
    target = normalize_translate_target(pending.get("target_language"))
    if source_type == "text" and target:
        token = hashlib.sha256(f"translate:{uid}:{target}:{time.time_ns()}".encode("utf-8")).hexdigest()[:16]
        set_translation_menu_pending(
            uid,
            "text_confirm",
            target_language=target,
            source_text=text[:1800],
            source_language="auto",
            output_type="txt",
            confirm_token=token,
        )
        await update.message.reply_text(
            translation_text_confirm_text(text, target, lang),
            parse_mode="HTML",
            reply_markup=translation_text_confirm_keyboard(lang),
        )
        return True
    clear_translation_menu_pending(uid)
    save_translation_request(uid, source_type, source_text=text)
    await show_translation_picker(update, source_type)
    return True

async def handle_translation_session_text(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.message.text or not update.effective_user:
        return False
    uid = update.effective_user.id
    session = get_translation_session(uid)
    if not session:
        return False
    text = update.message.text.strip()
    if not text or text.startswith("/"):
        return False
    lang = get_user_language(uid) or "vi"
    if len(text) > 1800:
        await update.message.reply_text(
            "⚠️ Tin nhắn quá dài cho phiên dịch liên tục. Vui lòng chia nhỏ từng đoạn. Bot chưa trừ Xu.",
            reply_markup=translation_session_keyboard(lang, session.get("mode")),
        )
        return True
    source, target = translation_detect_direction(text, session)
    try:
        try:
            result = await translate_subtitle_text(
                text,
                target,
                allow_admin=is_admin_user(uid),
                updated_by=uid,
            )
        except Exception:
            result = await translate_to_language(text, target)
        translated = (result.get("text") or "").strip()
        if not translated:
            raise RuntimeError("translation_empty")
        session = {
            **session,
            "last_used_at_ts": time.time(),
            "last_detected_language": source,
            "detected_lang_a": source if normalize_translate_target(session.get("lang_a")) == "auto" and source != target else session.get("detected_lang_a", ""),
            "current_step": "active",
            "previous_step": "translated_text",
        }
        TRANSLATION_SESSION_PENDING[str(uid)] = session
        await send_translation_session_result(update, context, session, text, translated, source, target)
        return True
    except Exception:
        await update.message.reply_text(
            "⚙️ Dịch vụ đang được kiểm tra tài nguyên xử lý. TOAN AAS chưa xử lý và chưa trừ Xu. Quý khách có thể thử lại sau hoặc chọn tác vụ khác.",
            parse_mode="HTML",
            reply_markup=translation_session_keyboard(lang, session.get("mode")),
        )
        return True

async def send_translation_session_result(update: Update, context: ContextTypes.DEFAULT_TYPE, session: dict, original: str, translated: str, source: str, target: str) -> None:
    uid = update.effective_user.id
    lang = get_user_language(uid) or "vi"
    conversation = str(session.get("mode") or "") == "live_conversation"
    title = "💬 <b>HỘI THOẠI 2 CHIỀU</b>" if conversation else "🌐 <b>TOAN AAS DỊCH 2 CHIỀU</b>"
    body = [
        title,
        "",
        f"• Chiều dịch: <b>{html.escape(translate_target_label(source))} → {html.escape(translate_target_label(target))}</b>",
    ]
    if conversation:
        body.extend(["", "<b>Nội dung gốc:</b>", html.escape(str(original or "")[:1500])])
    body.extend(["", "<b>Bản dịch:</b>", html.escape(str(translated or "")[:2600]), "", "Bot chưa trừ Xu."])
    await update.message.reply_text(
        "\n".join(body),
        parse_mode="HTML",
        reply_markup=translation_session_keyboard(lang, session.get("mode")),
    )
    if str(session.get("output_mode") or "text") != "voice" or not video_tts_provider_available():
        return
    try:
        _provider, audio_bytes, _detail = await video_dubbing_tts_bytes(
            translated,
            session.get("selected_voice") or "",
            "",
            session.get("speed") or "1.0",
        )
        if not audio_bytes:
            return
        audio = video_dubbing_output_file(audio_bytes, "toan_aas_translation_voice.mp3")
        if hasattr(update.message, "reply_audio"):
            await update.message.reply_audio(
                audio=audio,
                filename="toan_aas_translation_voice.mp3",
                caption=f"🔊 Bản dịch giọng nói: {translate_target_label(target)}",
            )
    except Exception:
        logger.info("translation session TTS unavailable | user=%s", uid)

def translation_voice_guard_text(admin: bool = False) -> str:
    text = "Dịch voice đang chờ tài nguyên xử lý. TOAN AAS chưa xử lý và chưa trừ Xu."
    if admin:
        blockers = []
        if not key4u_asr_public_ready():
            blockers.append("Key4U ASR smoke/config")
        if not shopaikey_stt_public_ready():
            blockers.append("ShopAIKey STT smoke/config")
        text += "\n\n<b>Admin blocker:</b>\n<code>" + html.escape(", ".join(blockers) or "ASR request failed") + "</code>"
    return text

async def handle_translation_session_media(update: Update, context: ContextTypes.DEFAULT_TYPE) -> bool:
    if not update.message or not update.effective_user:
        return False
    uid = update.effective_user.id
    session = get_translation_session(uid)
    if not session:
        return False
    lang = get_user_language(uid) or "vi"
    media_info = await resolve_stt_test_media(update, context)
    if not media_info or media_info.get("error") or not media_info.get("bytes"):
        await update.message.reply_text(
            translation_voice_guard_text(is_translation_admin(uid)),
            parse_mode="HTML",
            reply_markup=translation_session_keyboard(lang, session.get("mode")),
        )
        return True
    try:
        _asr_provider, transcript, _detail = await video_dubbing_transcribe_bytes(
            media_info["bytes"],
            context,
            media_info.get("content_type") or "application/octet-stream",
            allow_admin=is_admin_user(uid),
            updated_by=uid,
        )
        transcript = str(transcript or "").strip()
        if not transcript:
            raise RuntimeError("empty_transcript")
        source, target = translation_detect_direction(transcript, session)
        try:
            result = await translate_subtitle_text(
                transcript[:3500],
                target,
                allow_admin=is_admin_user(uid),
                updated_by=uid,
            )
        except Exception:
            result = await translate_to_language(transcript[:3500], target)
        translated = str(result.get("text") or "").strip()
        if not translated:
            raise RuntimeError("translation_empty")
        media = media_info.get("media") or {}
        source_ref = str(media_info.get("file_id") or getattr(media, "file_id", "") or "telegram_voice")
        session = {
            **session,
            "source_ref": source_ref[:300],
            "last_used_at_ts": time.time(),
            "last_detected_language": source,
            "detected_lang_a": source if normalize_translate_target(session.get("lang_a")) == "auto" and source != target else session.get("detected_lang_a", ""),
            "current_step": "active",
            "previous_step": "translated_voice",
        }
        TRANSLATION_SESSION_PENDING[str(uid)] = session
        await send_translation_session_result(update, context, session, transcript, translated, source, target)
        return True
    except Exception:
        await update.message.reply_text(
            translation_voice_guard_text(is_translation_admin(uid)),
            parse_mode="HTML",
            reply_markup=translation_session_keyboard(lang, session.get("mode")),
        )
        return True

async def handle_state_reset_slash_command(update: Update, context: ContextTypes.DEFAULT_TYPE, text: str) -> bool:
    command = str(text or "").strip().split(maxsplit=1)[0].split("@", 1)[0].lower()
    if command not in {"/start", "/menu", "/help", "/commands", "/huongdan", "/guide", "/hdsd", "/status", "/runtime"}:
        return False
    args = str(text or "").strip().split()[1:]
    try:
        context.args = args
    except Exception:
        pass
    if command == "/start":
        await cmd_start(update, context)
    elif command == "/menu":
        await cmd_menu(update, context)
    elif command in {"/help", "/commands"}:
        await cmd_help(update, context)
    elif command in {"/huongdan", "/guide", "/hdsd"}:
        await cmd_huongdan(update, context)
    elif command == "/status":
        await cmd_status(update, context)
    elif command == "/runtime":
        await cmd_runtime(update, context)
    return True

async def handle_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.message or not update.message.text:
        return
    text = update.message.text.strip()
    uid  = update.effective_user.id

    if await handle_state_reset_slash_command(update, context, text):
        return

    if await handle_manual_approval_pending_text(update, context):
        return

    if await handle_manual_topup_pending_text(update, context):
        return

    if await handle_free_hub_pending_text(update, context):
        return

    if await handle_translation_menu_pending_text(update, context):
        return

    if await handle_translation_session_text(update, context):
        return

    if await handle_finance_compliance_pending_text(update, context):
        return

    if await handle_feedback_pending_text(update, context):
        return

    if await handle_internal_archive_pending_text(update, context):
        return

    if await handle_doc_tool_pending_text(update, context):
        return

    if await handle_video_product_pending_text(update, context):
        return

    if await handle_storage_addon_pending_text(update, context):
        return

    if await handle_memory_pending_text(update, context):
        return

    if await handle_music_guided_pending_text(update, context):
        return

    if await handle_storyboard_pending_text(update, context):
        return

    if await handle_trend_video_flow_pending_text(update, context):
        return

    if await handle_image_warranty_retry_pending_text(update, context):
        return

    if await handle_quick_image_flow_pending_text(update, context):
        return

    if await handle_media_logo_watermark_pending_text(update, context):
        return

    if await handle_public_image_prompt_pending_text(update, context):
        return

    if await handle_public_video_prompt_pending_text(update, context):
        return

    if await handle_video_editor_pending_text(update, context):
        return

    if await handle_image_menu_pending_text(update, context):
        return

    if await handle_creative_motion_pending_text(update, context):
        return

    if await handle_cinematic_ad_pending_text(update, context):
        return

    if await handle_marketing_pending_text(update, context):
        return

    if await handle_video_downloader_pending_text(update, context):
        return

    if await handle_video_dubbing_pending_text(update, context):
        return

    if await handle_video_finalization_pending_text(update, context):
        return

    if await handle_developing_video_pending_text(update, context):
        return

    if await handle_quick_media_pending_text(update, context):
        return

    if await handle_support_pending_input(update, context):
        return

    if await handle_support_persona_message(update, context):
        return

    normalized_music_command = normalize_music_inline_command_text(text)
    if normalized_music_command:
        handled = await dispatch_music_inline_command(update, context, normalized_music_command)
        if handled:
            return

    if text.startswith("/"):
        return await handle_unknown_or_unmatched_command(update, context)

    audio_url = extract_first_http_url(text)
    if audio_url and is_audio_link_url(audio_url):
        return await reply_audio_link_received(update, audio_url)

    if is_media_preview_url_text(text):
        return await reply_media_preview_url_hint(update)

    if is_probable_media_tags_text(text):
        return await reply_media_tags_hint(update)

    if text in {"🏠 TOAN AAS MENU", "🛸 MENU DỊCH VỤ TOAN AAS"}:
        return await cmd_start(update, context)

    modes = ensure_user_modes(uid)
    translate_target = modes.get("translate_mode_target") or ""
    if translate_target:
        return await handle_auto_translate_message(update, context, text, translate_target)

    detected_video_url = extract_supported_video_url(text)
    if detected_video_url:
        route = {"action": "download", "data": detected_video_url}
    else:
        if not gemini_client and not openai_client and not shopaikey_public_chat_fallback_enabled():
            return await update.message.reply_text("⚠️ AI chat đang bận hoặc hết quota tạm thời.\nBot chưa trừ Xu. Vui lòng thử lại sau.")
        if not gemini_client and not openai_client and shopaikey_public_chat_fallback_enabled():
            route = {"action": "general", "data": text}
        else:
            try:
                route_raw = AgentGemini.chat(
                    "Phân loại: 'voice' (đọc văn bản), 'download' (URL video), 'general' (còn lại). Trả về JSON.",
                    text, uid, is_json=True
                )
                route = json.loads(route_raw)
            except Exception:
                route = {"action": "general", "data": text}

    act  = route.get("action", "general")
    data = route.get("data", text)
    size_calc = len(data) if act != "download" else 0
    action_key = act if act in ("voice", "download") else "chat"

    # ── LOGIC CHAT / TOOL CREDIT CHECK ───────────────────────────────────────
    is_admin = is_admin_user(uid)
    credits, total_spent, is_vip = get_user(uid)

    if action_key == "chat":
        mode_name = modes.get("chat_mode") or CHAT_TIER_NORMAL
        mode_name = normalize_chat_tier(mode_name or CHAT_TIER_NORMAL)
        base_cost = chat_mode_cost(mode_name)
        charge = effective_chat_charge(uid, mode_name, base_cost, is_admin=is_admin, is_legacy_vip=bool(is_vip))
        cost = int(charge["cost"])
        discount = 0.0
        warn = ""
        if cost > 0 and credits < cost:
            return await update.message.reply_text(chat_insufficient_credits_text(mode_name, cost, credits))
    else:
        # voice / download — voice được chọn provider trước; download trừ Xu trực tiếp.
        if action_key == "voice":
            free_voice_charge = apply_member_service_discount(uid, VOICE_FREE_COST, "spend_voice_free")
            min_voice_cost = 0 if is_admin else int(free_voice_charge.get("final_cost") or 0)
            if min_voice_cost and credits < min_voice_cost:
                return await reply_insufficient_credits(update, credits, min_voice_cost)
            cost, discount = 0, 0.0
        else:
            can_afford, cost, discount = deduct_dynamic_credit(uid, action_key, size_calc)
            if not can_afford:
                credits_now, _, _ = get_user(uid)
                return await reply_insufficient_credits(update, credits_now, cost)
        warn = ""

    if act == "voice":
        raw_cost_v = calculate_dynamic_cost("voice", size_calc)
        refund_charged_credit(uid, cost, "refund", "", "Hoàn phí phân loại voice trước khi khách chọn gói", True)
        fish_charge = apply_member_service_discount(uid, raw_cost_v, "spend_voice_paid")
        fish_cost = 0 if is_admin else int(fish_charge.get("final_cost") or 0)
        free_voice_charge = apply_member_service_discount(uid, VOICE_FREE_COST, "spend_voice_free")
        voice_free_cost = 0 if is_admin else int(free_voice_charge.get("final_cost") or 0)
        USER_PENDING[uid] = {
            "type": "voice",
            "data": data,
            "cost": fish_cost,
            "chat_id": update.effective_chat.id,
            "file_bytes": None,
            "premium_charged": False,
        }
        kb = provider_keyboard("voice", uid, fish_cost)
        if is_trial_account(uid):
            voice_desc = (
                f"🎙️ <b>Chọn gói đọc giọng nói:</b>\n\n"
                f"🔊 <b>Gói Tiết Kiệm</b> — Giọng chuẩn, trừ <b>{voice_free_cost} Xu</b>\n\n"
                f"<i>💡 Nạp tiền để mở khoá Gói Cao Cấp — giọng nhân bản siêu thực!</i>"
            )
        else:
            voice_desc = (
                f"🎙️ <b>Chọn gói đọc giọng nói:</b>\n\n"
                f"🎙️ <b>Gói Cao Cấp</b> — Giọng chất lượng cao, trừ <b>{fish_cost} Xu</b>\n"
                f"🔊 <b>Gói Tiết Kiệm</b> — Giọng chuẩn, trừ <b>{voice_free_cost} Xu</b>\n\n"
                f"<i>Nếu gói cao cấp lỗi/quota, hệ thống tự chuyển gói dự phòng và hoàn phần chênh lệch.</i>"
            )
        await update.message.reply_text(voice_desc, parse_mode="HTML", reply_markup=kb)
    elif act == "download":
        await AgentDownloader.download(data, context, update.effective_chat.id, cost, uid)
    else:
        await context.bot.send_chat_action(chat_id=update.effective_chat.id, action="typing")
        mode_name = normalize_chat_tier((modes.get("chat_mode") or CHAT_TIER_NORMAL))
        mode_instruction = chat_mode_instruction(mode_name)
        username = update.effective_user.username or update.effective_user.first_name or ""
        record_usage_event(
            uid,
            username=username,
            event_type="tool_use",
            tool_name="ai_chat",
            command="text_chat",
            status=mode_name,
        )
        result = await call_ai_chat_with_fallback(mode_instruction, text, uid, max_tokens=1800 if mode_name == CHAT_TIER_DEEP else 1200)
        if not result.get("ok"):
            detail = ai_failure_detail(result.get("statuses") or {}, result.get("errors") or {})
            record_usage_event(
                uid,
                username=username,
                event_type="tool_fail",
                tool_name="ai_chat",
                command="text_chat",
                status="provider_fail",
                provider="ai_router",
                detail=detail,
            )
            save_tool_test_result("ai_chat", "FAIL", detail, uid)
            return await update.message.reply_text(result.get("message") or ai_failure_user_text(result.get("statuses") or {}, result.get("errors") or {}))

        if cost > 0 and not spend_fixed_credit_info(uid, cost, f"spend_ai_chat_{mode_name}", f"AI chat {mode_name}", apply_member_discount_flag=False).get("ok"):
            credits_now, _, _ = get_user(uid)
            return await update.message.reply_text(chat_insufficient_credits_text(mode_name, cost, credits_now))

        provider = result.get("provider") or "ai_router"
        reply = result.get("text") or ""
        credits_after, _, _ = get_user(uid)
        if cost > 0:
            cost_line = f"\n\n<i>{chat_charge_line(cost, mode_name)}</i>"
            warn = (
                f"\n\n💼 <i>Số dư còn lại: <b>{credits_after} Xu</b> | /naptien để nạp thêm</i>"
                if credits_after < 200 else
                f"\n\n💼 <i>Còn: {credits_after} Xu</i>"
            )
        else:
            cost_line = f"\n\n<i>{chat_charge_line(cost, mode_name, cost == 0, charge.get('reason') or '')}</i>"
        record_usage_event(
            uid,
            username=username,
            event_type="tool_success",
            tool_name="ai_chat",
            command="text_chat",
            status=mode_name,
            provider=provider,
            xu_delta=-int(cost or 0),
            detail=f"tier={charge['tier']}; base={charge['base_cost']}; cost={charge['cost']}; benefit={charge.get('reason') or '-'}",
        )
        save_tool_test_result("ai_chat", "PASS", f"provider={provider}; mode={mode_name}; base={charge['base_cost']}; cost={cost}; tier={charge['tier']}", uid)
        await update.message.reply_text(
            f"🤖 {html.escape(reply)}{cost_line}{warn}{active_mode_hint(uid)}",
            parse_mode="HTML"
        )

