async def maybe_send_remote_worker_final_video(result: dict) -> dict:
    if not result.get("ok") or result.get("duplicate") or not tg_app:
        return {"sent": False, "reason": "not_ready_or_duplicate"}
    job = result.get("job") or {}
    project = result.get("project") or {}
    user_id = str(project.get("user_id") or "").strip()
    final_path = str(project.get("final_video_path") or "")
    if not user_id or not final_path or not os.path.exists(final_path) or os.path.getsize(final_path) <= 0:
        return {"sent": False, "reason": "missing_user_or_file"}
    is_canary = remote_worker_api.is_remote_worker_canary_job(job, project)
    is_admin_canary = remote_worker_api.is_remote_worker_admin_canary_job(job, project)
    is_admin_video = remote_worker_api.is_remote_worker_admin_video_job(job, project)
    render_mode = video_b14_render_mode_from_job(job, project)
    job_result = video_b14_job_result_payload(job)
    blocked_reason = video_b14_product_result_block_reason(job, project)
    visual_classification = video_b14_result_visual_classification(job)
    if blocked_reason:
        try:
            conn = db_connect()
            try:
                video_project_queue.fail_video_job(conn, job_id=safe_int(job.get("id") or job.get("job_id"), 0), error=blocked_reason, retry=False)
            finally:
                conn.close()
        except Exception:
            logger.warning("blocked product video result fail marking skipped")
        try:
            await tg_app.bot.send_message(chat_id=int(user_id), text=VIDEO_B14_PRODUCT_CLEAN_FAIL_MESSAGE)
            return {"sent": False, "reason": blocked_reason, "message_sent": True}
        except Exception as exc:
            logger.warning(f"blocked product video notice failed: {type(exc).__name__}")
            return {"sent": False, "reason": blocked_reason}
    test_pattern = bool(job_result.get("test_pattern")) or render_mode == "admin_test_pattern"
    if is_admin_canary:
        caption = "🧪 VPS Worker Production Canary hoàn tất. File test admin từ VPS/Railway."
    elif is_canary:
        caption = "🧪 Remote Worker Canary hoàn tất. File kết quả test từ VPS/Railway."
    elif is_admin_video and test_pattern:
        caption = "🧪 ADMIN TEST PATTERN — đây là video test kỹ thuật để kiểm tra đường gửi file, không phải video dựng thật. Không trừ Xu."
    elif visual_classification == "partial_simple_video":
        caption = "⚠️ " + VIDEO_B14_PARTIAL_SIMPLE_MESSAGE
    elif render_mode == "real":
        caption = "✅ Hệ thống đã dựng video thật. TOAN AAS gửi file kết quả cuối."
    else:
        return {"sent": False, "reason": "render_mode_not_real"}
    try:
        with open(final_path, "rb") as handle:
            await tg_app.bot.send_video(
                chat_id=int(user_id),
                video=handle,
                caption=caption,
            )
        return {"sent": True}
    except Exception as exc:
        logger.warning(f"remote worker final video send failed: {type(exc).__name__}")
        return {"sent": False, "reason": type(exc).__name__}


@fastapi_app.post("/api/v1/worker/complete")
async def api_worker_complete(request: Request):
    verify_remote_worker_api_access(request)
    content_type = request.headers.get("content-type", "").lower()
    uploaded_path = ""
    uploaded_file = False
    if "multipart/form-data" in content_type:
        form = await request.form()
        raw_metadata = form.get("metadata") or "{}"
        try:
            payload = json.loads(str(raw_metadata))
        except Exception:
            raise HTTPException(status_code=400, detail="metadata must be JSON")
        upload = form.get("file")
        if not upload or not hasattr(upload, "read"):
            raise HTTPException(status_code=400, detail="file required")
        job_id_for_path = safe_int(payload.get("job_id"), 0)
        content = await upload.read()
        try:
            uploaded_path = remote_worker_api.save_uploaded_result(
                worker_result_upload_root(),
                job_id=job_id_for_path,
                filename=getattr(upload, "filename", "result.mp4"),
                content=content,
            )
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=str(exc))
        uploaded_file = True
    else:
        payload = await read_json_body(request)
    worker_id = remote_worker_api.sanitize_worker_id(payload.get("worker_id") or request.headers.get("x-worker-id") or "remote-worker")
    job_id = safe_int(payload.get("job_id"), 0)
    if not job_id:
        raise HTTPException(status_code=400, detail="job_id required")
    result_payload = payload.get("result") if isinstance(payload.get("result"), dict) else {}
    conn = db_connect()
    try:
        result = remote_worker_api.complete_remote_worker_job(
            conn,
            worker_id=worker_id,
            job_id=job_id,
            result=result_payload,
            final_video_path=uploaded_path or str(result_payload.get("final_video_path") or ""),
            final_video_file_id=str(result_payload.get("final_video_file_id") or ""),
            uploaded_file=uploaded_file,
        )
        if not result.get("ok"):
            raise HTTPException(status_code=409, detail=result.get("reason") or "complete_rejected")
    finally:
        conn.close()
    delivery = await maybe_send_remote_worker_final_video(result)
    job = result.get("job") or {}
    project = result.get("project") or {}
    is_safe_worker_canary = remote_worker_api.is_remote_worker_canary_job(job, project)
    is_admin_prod_canary = remote_worker_api.is_remote_worker_admin_canary_job(job, project)
    if is_safe_worker_canary or is_admin_prod_canary:
        conn = db_connect()
        try:
            remote_worker_api.note_remote_worker_canary_delivery(
                conn,
                job_id=job_id,
                sent=bool(delivery.get("sent")),
                reason=str(delivery.get("reason") or ""),
            )
        finally:
            conn.close()
        try:
            if is_admin_prod_canary:
                set_system_setting("remote_worker:last_admin_prod_canary_job_id", str(job_id), "last remote worker admin prod canary job", worker_id)
                set_system_setting("remote_worker:last_admin_prod_canary_status", str(job.get("status") or "completed"), "last remote worker admin prod canary status", worker_id)
            else:
                set_system_setting("remote_worker:last_canary_job_id", str(job_id), "last remote worker canary job", worker_id)
                set_system_setting("remote_worker:last_canary_status", str(job.get("status") or "completed"), "last remote worker canary status", worker_id)
        except Exception:
            logger.warning("remote worker canary complete setting skipped")
    return {"ok": True, "result": result, "delivery": delivery}


@fastapi_app.post("/api/v1/worker/fail")
async def api_worker_fail(request: Request):
    verify_remote_worker_api_access(request)
    payload = await read_json_body(request)
    worker_id = remote_worker_api.sanitize_worker_id(payload.get("worker_id") or request.headers.get("x-worker-id") or "remote-worker")
    job_id = safe_int(payload.get("job_id"), 0)
    if not job_id:
        raise HTTPException(status_code=400, detail="job_id required")
    partial_artifacts = payload.get("partial_artifacts") if isinstance(payload.get("partial_artifacts"), list) else []
    diagnostics = payload.get("diagnostics") if isinstance(payload.get("diagnostics"), dict) else {}
    conn = db_connect()
    try:
        result = remote_worker_api.fail_remote_worker_job(
            conn,
            worker_id=worker_id,
            job_id=job_id,
            safe_error=str(payload.get("safe_error") or "remote_worker_failed")[:500],
            retryable=bool(payload.get("retryable", True)),
            partial_artifacts=partial_artifacts,
            diagnostics=diagnostics,
        )
        if not result.get("ok"):
            raise HTTPException(status_code=409, detail=result.get("reason") or "fail_rejected")
        return result
    finally:
        conn.close()


@fastapi_app.get("/api/v1/worker/assets/{asset_id}")
async def api_worker_asset_download(asset_id: str, request: Request):
    verify_remote_worker_api_access(request)
    safe_asset_id = re.sub(r"[^A-Za-z0-9_.-]+", "-", str(asset_id or ""))[:120]
    if not safe_asset_id:
        raise HTTPException(status_code=400, detail="asset_id required")
    asset_root = os.path.join(os.path.dirname(__file__), "files", "worker_assets")
    candidate = os.path.abspath(os.path.join(asset_root, safe_asset_id))
    if not candidate.startswith(os.path.abspath(asset_root)) or not os.path.exists(candidate) or not os.path.isfile(candidate):
        raise HTTPException(status_code=404, detail="asset_not_found")
    return FileResponse(candidate, filename=os.path.basename(candidate))

